-- 国試の解説を差し替える。blueprint_code で行を特定するので、
-- 本文が壊れている行でも当たる。何度流しても結果は同じ。
BEGIN;

UPDATE quiz_question AS q
SET explanation = v.explanation
FROM (VALUES
    ('114-A-1', '正答は D「アナフィラキシー — アドレナリン静注」。

アナフィラキシーに対するアドレナリンは大腿前外側への筋注が標準で、静注ではない。筋注は血中濃度の立ち上がりが速く安全域も広い。静注は不整脈や心筋虚血を招くため、心停止例や筋注に反応しない難治性ショックに限り、希釈して監視下で行う例外的な投与法である。

【誤答選択肢の解説】
A「蕁麻疹 — H1受容体拮抗薬内服」: 蕁麻疹の第一選択は非鎮静性H1受容体拮抗薬の内服で、標準治療として正しい。
B「食物アレルギー — 原因食物除去」: 食物アレルギーの基本は原因食物の必要最小限の除去であり、正しい組合せである。
C「アトピー性皮膚炎 — 副腎皮質ステロイド外用」: アトピー性皮膚炎の炎症を抑える中心は副腎皮質ステロイド外用薬で、正しい。
E「気管支喘息発作(急性増悪) — β2刺激薬吸入」: 気管支喘息の急性増悪では短時間作用性β2刺激薬の吸入が第一選択で、正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-A-10', '正答は B「三叉神経痛」。

典型的な三叉神経痛は、上小脳動脈などの血管が橋から出る三叉神経の根部（root entry zone）を圧迫して生じる。片側顔面痙攣が顔面神経で起こるのと同じ機序で、微小血管減圧術が根治的治療になる。

【誤答選択肢の解説】
A「片頭痛」: 片頭痛の発症には三叉神経血管系の活性化が関わるが、血管が神経を圧迫して起こるわけではない。
C「本態性振戦」: 本態性振戦は小脳-視床-皮質回路の機能的な異常によるもので、血管圧迫は関与しない。
D「Parkinson病」: Parkinson病は黒質のドパミン神経の変性による。
E「側頭葉てんかん」: 側頭葉てんかんの多くは海馬硬化などの内側側頭葉病変による。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-A-11', '正答は D「メトトレキサート」。

メトトレキサートは葉酸代謝を阻害し、神経管閉鎖障害や頭蓋顔面の形成異常など催奇形性をもつため妊娠中は禁忌である。挙児希望があれば妊娠前に中止し、少なくとも1月経周期をおいてから妊娠を計画する。

【誤答選択肢の解説】
A「タクロリムス」: タクロリムスは胎盤移行が限られ、妊娠中も継続可能な免疫抑制薬として扱われる。
B「インドメタシン」: NSAIDは妊娠後期には胎児動脈管の早期閉鎖のため避けるが、妊娠前にあらかじめ中止する薬ではない。
C「エタネルセプト」: TNF阻害薬は妊娠中期までの胎盤移行が少なく、必要に応じて継続できる。
E「サラゾスルファピリジン」: サラゾスルファピリジンは妊娠中も比較的安全に使用でき、葉酸を併用する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-A-12', '正答は A「年齢6歳以上」。

小児急性中耳炎が難治化・反復する最大の危険因子は2歳未満の低年齢である。乳幼児では耳管が短く太く水平に近いため、鼻咽腔からの感染が及びやすく換気も悪い。6歳以上ではむしろ治りやすくなる。

【誤答選択肢の解説】
B「免疫能の低下」: 免疫能の低下は起炎菌の排除を妨げ、難治化の要因となる。
C「鼻副鼻腔炎の合併」: 鼻副鼻腔炎の合併は耳管を介した感染源となり、難治化に関連する。
D「集団保育所への通所」: 集団保育所への通所は耐性菌への曝露と反復感染の機会を増やす。
E「薬剤耐性菌の耳漏内検出」: 耳漏から薬剤耐性菌が検出されれば、通常の抗菌薬が効かず難治化する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A012（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-A-2', '正答は D「胃食道逆流症 — 後鼻漏」。

後鼻漏は副鼻腔炎など上気道由来の咳（上気道咳症候群）の特徴であって、胃食道逆流症の特徴ではない。逆流による慢性咳嗽は胸やけや呑酸を伴い、食後や臥位・前屈で増悪するのが特徴である。

【誤答選択肢の解説】
A「COPD — 喫煙歴」: COPDによる咳嗽の背景には喫煙歴があり、正しい組合せである。
B「咳喘息 — 季節性」: 咳喘息は季節性や日内変動（夜間から早朝の増悪）を示し、正しい。
C「アトピー咳嗽 — 咽喉頭瘙痒感」: アトピー咳嗽は咽喉頭の瘙痒感（イガイガ感）を伴い、抗ヒスタミン薬が有効である。
E「副鼻腔気管支症候群 — 膿性痰」: 副鼻腔気管支症候群は慢性副鼻腔炎に気道病変を合併し、膿性痰を伴う。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-A-21', '正答は E「第VIII因子活性の測定」。

高齢者に誘因なく広範な皮下出血が出現し、PTが正常でAPTTのみが延長し、血小板数も正常であることから、後天性血友病A（第VIII因子インヒビターの出現）を第一に考える。第VIII因子活性の測定とクロスミキシング試験、インヒビター定量で確定する。

【誤答選択肢の解説】
A「骨髄穿刺」: 貧血はあるが白血球分画も血小板数も正常で、造血器腫瘍を積極的に疑う所見に乏しい。APTT単独延長も説明できない。
B「皮膚生検」: 血管炎による紫斑は触知可能で下腿優位のことが多い。本例は凝固検査の異常が明らかで、皮膚生検では診断に至らない。
C「Coombs試験」: Coombs試験は自己免疫性溶血性貧血の検査だが、網赤血球増加や間接ビリルビン上昇の所見はなく、出血傾向も説明できない。
D「抗血小板抗体の測定」: 抗血小板抗体は免疫性血小板減少症を疑うときの検査で、血小板32万と正常な本例には当たらない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A021（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-A-22', '正答は E「プロゲステロン負荷試験」。

プロゲステロン負荷試験は無月経の患者でエストロゲン分泌と子宮内膜の反応性をみて第1度・第2度無月経を鑑別する検査である。本例は稀発月経ながら月経があり、不妊の原因検索には寄与しない。

【誤答選択肢の解説】
A「子宮鏡検査」: 子宮鏡は子宮内腔の癒着・ポリープ・粘膜下筋腫など着床を妨げる病変の評価に有用である。
B「超音波検査」: 経腟超音波は卵胞発育や多囊胞性卵巣の所見、子宮筋腫などの評価に必須である。
C「基礎体温測定」: 基礎体温の二相性から排卵の有無と黄体機能を推定でき、月経周期が不整な本例では特に有用である。
D「子宮卵管造影検査」: 子宮卵管造影は卵管の疎通性を評価する検査で、不妊症の基本検査に含まれる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-A-23', '正答は D「聴力の左右差」。

立ち上がった時に限って起こり意識消失を伴わない前失神発作で、起立性低血圧を強く示唆する。原因として心拍出量の制限（大動脈弁狭窄など）、貧血、自律神経障害、脱水を確認する。聴力の左右差は蝸牛症状を伴う末梢前庭疾患を疑うときの所見で、体位変換に限って生じる本例では優先度が最も低い。

【誤答選択肢の解説】
A「心雑音」: 大動脈弁狭窄など器質的心疾患による失神を除外するために心雑音の聴取は重要である。
B「低血圧」: 臥位と立位での血圧測定は起立性低血圧を直接証明する検査で、最優先である。
C「頸部血管雑音」: 頸部血管雑音は頸動脈狭窄を示唆し、脳灌流低下の要因となる。
E「眼瞼結膜の貧血」: 眼瞼結膜の蒼白は貧血を示唆し、貧血は起立耐性を低下させる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A023（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-A-24', '正答は E「黄色ブドウ球菌」。

熱傷創を有する患者に、発熱・低血圧・びまん性紅斑・消化器症状が急速に出現しており、黄色ブドウ球菌のTSST-1などの毒素によるトキシックショック症候群を考える。熱傷創は発赤や膿など明らかな感染徴候に乏しくても菌が定着していることがある。

【誤答選択肢の解説】
A「大腸菌」: 大腸菌は腸管由来の敗血症を起こしうるが、熱傷創とびまん性紅斑という組合せは説明しにくい。
B「緑膿菌」: 緑膿菌は熱傷創感染の代表的な起炎菌だが、緑色の滲出液やエクチマ壊疽が典型で、毒素性ショック様の紅斑は非典型である。
C「カンジダ」: カンジダは広域抗菌薬の長期投与や中心静脈カテーテル留置例に多く、受傷1週でこの急激な経過をとることは考えにくい。
D「肺炎球菌」: 肺炎球菌感染は呼吸器症状が主体で、呼吸音に異常のない本例の経過に合わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-A-25', '正答は E「仕事に関する本人の考えを聞く。」。

症状は平日と職場に限られ、休日は熟睡でき趣味も以前どおり楽しめている。気分反応性が保たれており、うつ病エピソードの基準を満たさず、異動というストレス因に対する適応反応症（適応障害）が考えられる。初診ではまず職場で何が起きていて本人がどう受け止めているかを聴くのが適切である。

【誤答選択肢の解説】
A「休職を勧める。」: 欠勤はなく職業機能は保たれている。評価の前に休職を勧めるのは早計である。
B「頑張るよう励ます。」: 励ましは本人を追い詰めるおそれがあり、支持的精神療法の原則に反する。
C「抗うつ薬を処方する。」: 適応反応症では抗うつ薬は第一選択とならず、まず環境調整と支持的介入を行う。
D「投影法の心理検査を実施する。」: 投影法の心理検査は初診時に必須ではなく、まず病歴の聴取が優先される。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-A-29', '正答は B「蛋白摂取量は45g/日とする。」。

顕性腎症からさらに進行した糖尿病性腎臓病で、蛋白制限が中心となる。0.6〜0.8 g/kg標準体重/日が目安で、標準体重約64 kgでは38〜51 g/日にあたり、45 g/日は妥当である。

【誤答選択肢の解説】
A「塩分摂取量は10g/日とする。」: 血圧182/102 mmHgで腎症も進行しており、食塩は6 g/日未満に制限する。
C「総エネルギー量は1,400kcal/日とする。」: 蛋白を制限する分エネルギーは十分に確保しないと異化が亢進する。標準体重約64 kgの軽労作では1,600〜1,900 kcal/日が目安で、1,400 kcalでは不足する。
D「糖質の割合は総エネルギー量の40%とする。」: 蛋白制限下でエネルギーを確保するには糖質を減らせない。糖質は総エネルギーの50〜60%とする。
E「コレステロール摂取量は1,000mg/日とする。」: 脂質異常症も合併しており、コレステロールは200〜300 mg/日未満に抑える。1,000 mg/日は過剰である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A029（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-A-32', '正答は D「乳汁漏出」。

乳汁漏出は高プロラクチン血症による症状で、ドパミン受容体を遮断する抗精神病薬やメトクロプラミドなどで起こる。NSAIDの副作用ではない。

【誤答選択肢の解説】
A「浮腫」: 腎でのプロスタグランジン産生が抑えられ、ナトリウムと水の貯留から浮腫を生じる。
B「鼻出血」: COX-1阻害により血小板のトロンボキサンA2産生が抑えられ、出血傾向から鼻出血を生じうる。
C「血圧上昇」: ナトリウム貯留と腎血管拡張の抑制により血圧が上昇する。
E「上腹部痛」: 上腹部痛はNSAID起因性の胃十二指腸潰瘍を示唆し、倍量を連日服用している本例で最も警戒すべき症状である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A032（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-A-4', '正答は B「汗腺の数が増加している。」。

原発性局所多汗症では汗腺の数も組織像も正常で、増加していない。交感神経を介した発汗刺激が過剰になっているだけであり、これが治療の標的になる。

【誤答選択肢の解説】
A「精神性発汗は亢進する。」: 掌蹠の発汗は精神的緊張で亢進する精神性発汗が主体で、正しい。
C「真菌や細菌の感染を起こしやすい。」: 常に湿潤するため角層が浸軟し、白癬や点状角質融解症などを起こしやすい。正しい。
D「治療にはイオントフォレーシスが用いられる。」: 水道水イオントフォレーシスは掌蹠多汗症の標準的な治療法の一つである。
E「Minor法はヨードデンプン反応を利用した検査法である。」: Minor法はヨードとデンプンの反応で発汗部位を可視化する検査で、正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-A-40', '正答は B「便のGram染色」。

東南アジアからの帰国後2日で発症した発熱を伴う下痢で、細菌性の旅行者下痢症を考える。便のGram染色は迅速で、Campylobacterのらせん状桿菌など起炎菌の推定に役立ち、培養と併せて診断を確定する。

【誤答選択肢の解説】
A「腹部造影CT」: 腹膜刺激徴候はなく、造影CTは起炎菌の同定には寄与しない。
C「腹部超音波検査」: 腹部超音波は腸管壁の肥厚を捉えることはあっても、原因微生物を確定できない。
D「便の抗酸菌染色」: 抗酸菌染色は腸結核を疑うときの検査だが、腸結核は亜急性から慢性の経過をとり、2日の急性経過に合わない。
E「便のClostridioides difficile毒素」: Clostridioides difficile感染症は先行する抗菌薬使用歴や入院歴を背景に起こるが、本例にはいずれもない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A040（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-A-44', '正答は E「機能性ディスペプシア」。

早期飽満感と食後の心窩部痛が6か月続き、上部消化管内視鏡でも腹部超音波でも器質的疾患が除外されている。食後愁訴症候群と心窩部痛症候群の要素をもつ機能性ディスペプシアと考える。

【誤答選択肢の解説】
A「慢性膵炎」: 慢性膵炎ではアミラーゼの変動や脂肪便、背部に放散する疼痛がみられるが、本例は膵酵素も正常である。
B「逆流性食道炎」: 逆流性食道炎は胸やけが主症状で、内視鏡で粘膜傷害を認めることが多いが、本例の内視鏡は正常である。
C「過敏性腸症候群」: 過敏性腸症候群は排便に関連する腹痛と便通異常が診断に必要だが、本例に便通異常はない。
D「食道アカラシア」: 食道アカラシアはつかえ感と食物の逆流が主症状で、内視鏡でも食道の拡張や食物残渣を認めることが多い。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A044（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-A-5', '正答は B「味覚異常 — 亜鉛」。

亜鉛は味蕾の細胞の代謝回転に必要で、欠乏すると味覚異常をきたす。ほかに皮膚炎、脱毛、創傷治癒の遅延、小児では成長障害を伴う。

【誤答選択肢の解説】
A「匙状爪 — 銅」: 匙状爪（スプーンネイル）は鉄欠乏の徴候である。銅欠乏では貧血・好中球減少・脊髄症をきたす。
C「出血傾向 — ビタミンA」: 出血傾向をきたすのはビタミンK欠乏。ビタミンA欠乏では夜盲や眼球乾燥症を生じる。
D「ペラグラ — ビタミンB2」: ペラグラはナイアシン（ビタミンB3）欠乏で、皮膚炎・下痢・認知症を三徴とする。
E「骨軟化症 — ビタミンC」: 骨軟化症はビタミンD欠乏による。ビタミンC欠乏で起こるのは壊血病である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-A-51', '正答は B「酸素投与」。

閉鎖された倉庫内でガソリンエンジンを使用し、同じ場所にいた同僚も頭痛や悪心を訴えていることから一酸化炭素中毒を考える。カルボキシヘモグロビンはパルスオキシメータで酸素化ヘモグロビンと区別できないためSpO2は見かけ上正常となる。直ちに高濃度酸素を投与してCOの半減期を短縮する。

【誤答選択肢の解説】
A「胃管挿入」: 経口摂取による中毒ではなく、胃管挿入の適応はない。
C「ブドウ糖静注」: 低血糖を疑う病歴はない。血糖測定は行うにしても、まず行うべき処置ではない。
D「アドレナリン筋注」: アナフィラキシーを示唆する皮疹・気道症状・曝露歴がない。
E「吸入β刺激薬投与」: 喘鳴など気道閉塞の所見はなく、β刺激薬の適応はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A051（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-A-58', '正答は D「Machado-Joseph病」。

父、父方祖父、叔父に同症状があり常染色体顕性遺伝の形式をとる。小脳性運動失調に錐体路徴候を伴い、眼瞼後退による「びっくり眼」を認めることから脊髄小脳失調症3型（Machado-Joseph病）を考える。CAGリピートの伸長による疾患である。

【誤答選択肢の解説】
A「Parkinson病」: Parkinson病は静止時振戦・筋強剛・寡動が主体で、小脳性運動失調は伴わない。
B「多系統萎縮症」: 多系統萎縮症は孤発性で、起立性低血圧や排尿障害など自律神経症状が目立つ。本例は明らかな家族歴があり自律神経障害もない。
C「Huntington病」: Huntington病も常染色体顕性だが、舞踏運動と精神症状・認知機能低下が主体である。本例は不随意運動がなく認知機能も正常である。
E「ミトコンドリア脳筋症」: ミトコンドリア脳筋症は母系遺伝を示す。父方に症状が連なる本例の家系図と合わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A058（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-A-6', '正答は C「カルシウム製剤」。

甲状腺全摘に伴って副甲状腺が摘出されたり血流障害を受けたりすると、術後に低カルシウム血症が生じる。テタニーは神経筋の興奮性亢進による症候で、直ちにグルコン酸カルシウムを静注して補正する。

【誤答選択肢の解説】
A「抗甲状腺薬」: 甲状腺を全摘した後であり、抗甲状腺薬の適応はない。
B「抗けいれん薬」: テタニーはてんかん発作ではなく低カルシウム血症による神経筋興奮性の亢進であり、抗けいれん薬では改善しない。
D「ビスホスホネート製剤」: ビスホスホネートは血清カルシウムをさらに低下させるため、低カルシウム血症では避ける。
E「活性型ビタミンD製剤」: 活性型ビタミンD製剤は術後低カルシウム血症の維持療法として併用するが、作用発現が遅く急性期のテタニーには間に合わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-A-61', '正答は E「非アルコール性脂肪性肝疾患」。

肥満（BMI約31）、耐糖能異常、高トリグリセリド血症、低HDLコレステロール血症とメタボリック症候群の要素が揃い、飲酒歴がなくウイルス性肝炎も自己抗体も陰性である。ALT優位の軽度トランスアミナーゼ上昇は非アルコール性脂肪性肝疾患に典型的である。

【誤答選択肢の解説】
A「Wilson病」: Wilson病は若年発症で、セルロプラスミン低値、Kayser-Fleischer輪、神経・精神症状を伴う。58歳発症で神経診察も正常な本例は非典型である。
B「Gilbert症候群」: Gilbert症候群は間接ビリルビン優位の軽度上昇のみでトランスアミナーゼは正常。本例は直接ビリルビン優位でAST・ALTも上昇している。
C「自己免疫性肝炎」: 自己免疫性肝炎は中年女性に多いが、抗核抗体が陰性でIgG上昇の所見もない。
D「原発性胆汁性胆管炎」: 原発性胆汁性胆管炎は抗ミトコンドリア抗体が陽性となり胆道系酵素優位の上昇を示すが、本例は抗体陰性でALPも基準内である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A061（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-A-64', '正答は B「クラミジア感染症は治癒した。」。

治療により症状が消失し、性器クラミジアDNA検査も陰性化しており、感染症としては治癒したと説明してよい。ただし治癒は再感染しないことを意味せず、パートナーの同時治療とコンドームの使用を併せて説明する必要がある。

【誤答選択肢の解説】
A「3か月の避妊が望ましい。」: クラミジア感染症の治癒後に避妊を要する医学的根拠はない。
C「異所性妊娠のリスクは低下した。」: 骨盤内炎症性疾患による卵管の器質的障害は治癒しても元に戻らず、異所性妊娠のリスクは残る。低下したとは言えない。
D「子宮性不妊となる可能性が高い。」: クラミジアによる不妊は卵管性であって子宮性ではなく、また必ず不妊になるわけでもない。
E「今後クラミジア感染症になることはない。」: クラミジアに対する感染防御免疫は成立せず、再感染しうる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A064（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-A-8', '正答は B「聴力は正常である。」。

選択（性）緘黙は、家庭など特定の場面では話せるのに学校など別の場面では話せなくなる不安症で、聴力・言語能力・知能はいずれも正常である。話せないのは能力の問題ではなく不安によるという理解が対応の前提になる。

【誤答選択肢の解説】
A「思春期に多い。」: 発症の多くは5歳前後で、就学を機に気づかれることが多い。思春期に多いわけではない。
C「言語理解の障害が原因である。」: 言語理解は保たれている。言語発達の障害が原因なら、話せる場面があることを説明できない。
D「脳波検査が診断に有用である。」: 器質的な脳疾患ではないため、脳波検査は診断に寄与しない。
E「発声練習による治療が有効である。」: 発声機能そのものに問題はないので発声練習は的外れで、行動療法や環境調整、不安への介入が中心となる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-A-9', '正答は E「収縮性心膜炎」。

収縮性心膜炎は心膜の線維化・石灰化により拡張が妨げられる疾患で、結核や心臓手術、放射線照射などが原因となる。閉塞性睡眠時無呼吸症候群との因果関係は知られていない。

【誤答選択肢の解説】
A「心不全」: 夜間の間欠的低酸素と胸腔内圧の変動が心負荷となり、心不全のリスクを高める。
B「突然死」: 重症例では夜間から早朝の突然死のリスクが上昇することが知られている。
C「高血圧症」: 交感神経活動の亢進により高血圧、とくに治療抵抗性高血圧と強く関連する。
D「心房細動」: 左房への負荷と自律神経の変動から心房細動のリスクが上昇する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 A009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-1', '正答は B「「2型糖尿病の発症予防には肥満にならないことが重要です」」。

2型糖尿病の最大の修正可能な危険因子は肥満で、体重管理が発症予防の中心になる。市民向けの健康教育として妥当な内容である。

【誤答選択肢の解説】
A「「受動喫煙は肺癌の発症リスクとは無関係です」」: 受動喫煙が肺癌のリスクを高めることは確立しており、誤った情報を伝えることになる。
C「「飽和脂肪酸は血中コレステロールを下げる作用があります」」: 飽和脂肪酸はLDLコレステロールを上昇させる。下げるのは不飽和脂肪酸である。
D「「高血圧症の方で推奨される塩分摂取量は1日当たり10gです」」: 高血圧症患者に推奨される食塩摂取量は6g/日未満で、10gでは過剰である。
E「「食物繊維を多く含む食品の摂取は食道癌の発症リスクを下げます」」: 食物繊維との関連が示されているのは主に大腸癌である。食道癌の確立した危険因子は飲酒・喫煙・熱い飲食物である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-10', '正答は E「基線細変動消失」。

基線細変動の消失は、胎児の自律神経系が低酸素やアシドーシスで抑制されていることを示し、胎児機能不全のなかで最も重篤な所見である。

【誤答選択肢の解説】
A「一過性頻脈」: 一過性頻脈は胎児が健常であることを示す所見で、懸念すべきものではない。
B「早発一過性徐脈」: 早発一過性徐脈は児頭圧迫による生理的な反応で、予後に影響しない。
C「変動一過性徐脈」: 変動一過性徐脈は臍帯圧迫によるもので、軽度・散発性なら経過観察でよい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-14', '正答は E「5」。

受療行動とは、患者がいつ・どこで・なぜ医療を受けようとしたかという行動そのものを指す。「評判が良く家から近いので来た」という発言は、この医療機関を選んだ理由であり受療行動の情報である。

【誤答選択肢の解説】
A「1」: 「左の膝が痛い」は主訴である。
B「2」: 「階段で膝が痛くなる」は症状の増悪因子で、現病歴にあたる。
C「3」: 「昨年末くらいから」は発症時期と経過で、現病歴にあたる。
D「4」: 「歩けなくなったら周りに迷惑をかけるのでは」は患者の解釈モデル・懸念であって、受療行動そのものではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B014（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-16', '正答は D「運動習慣」。

運動習慣は慢性腎臓病の危険因子ではなく、肥満や高血圧の是正を通じてむしろ発症を抑える方向に働く。

【誤答選択肢の解説】
A「加齢」: 加齢に伴い糸球体濾過量は生理的に低下し、CKDの主要な危険因子である。
B「喫煙」: 喫煙は腎の細動脈硬化と蛋白尿を促進する。
C「糖尿病」: 糖尿病は糖尿病性腎臓病を通じて透析導入原因の第1位である。
E「高血圧症」: 高血圧は腎硬化症の原因であり、透析導入原因の上位を占める。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B016（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-17', '正答は E「臍帯静脈の血液は胎児側に向かって流れる。」。

臍帯静脈は胎盤で酸素化された血液を胎児へ運ぶ。臍帯のなかで静脈は1本、動脈が2本である。

【誤答選択肢の解説】
A「羊水は弱酸性である。」: 羊水はpH7.0〜7.5の弱アルカリ性で、破水の診断にBTB試験紙の変色を利用するのはこのためである。
B「臍帯動脈は1本である。」: 臍帯動脈は通常2本ある。1本しかない単一臍帯動脈では他の奇形の合併に注意する。
C「臍帯表面は絨毛膜で覆われる。」: 臍帯の表面を覆うのは羊膜である。
D「羊膜はWharton膠質からなる。」: Wharton膠質は臍帯血管を保護する間質のゼリー状組織で、羊膜そのものではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-18', '正答は B「「症状の出現は突然であった」」。

脳血管障害の本質は血流の突然の途絶であり、症状が突然出現したという病歴が最も脳梗塞を示唆する。

【誤答選択肢の解説】
A「「以前に同じような症状があった」」: 同様の症状の反復は片頭痛やてんかん、あるいは一過性脳虚血発作でもみられ、脳梗塞に特異的ではない。
C「「症状の変動はなかった」」: 症状が変動しないことは脳梗塞と矛盾しないが、発症様式ほど診断的価値は高くない。
D「「頭痛は伴わなかった」」: 頭痛を伴わないことは脳出血やくも膜下出血を相対的に否定するにとどまる。
E「「発熱はなかった」」: 発熱がないことは感染症の除外にはなるが、脳梗塞を積極的に示唆しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B018（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-19', '正答は A「黄疸」。

溶血で放出されたヘモグロビンが処理されて間接ビリルビンが増加し、黄疸をきたす。ハプトグロビン低下、LD上昇、網赤血球増加を伴う。

【誤答選択肢の解説】
B「徐脈」: 貧血では組織への酸素供給を保つため代償性に頻脈となる。
C「匙状爪」: 匙状爪(スプーンネイル)は鉄欠乏性貧血の徴候である。
D「眼球突出」: 眼球突出はBasedow病の所見で、溶血とは関係しない。
E「拡張期心雑音」: 貧血で聴取されるのは血流量増加による収縮期駆出性雑音である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-2', '正答は D「急性喉頭蓋炎」。

急性喉頭蓋炎は声門上の腫脹で急速に気道が閉塞し、窒息死しうる。腫脹のため経口挿管が困難あるいは不可能なことがあり、輪状甲状靱帯切開を含む外科的気道確保を準備する。

【誤答選択肢の解説】
A「肺水腫」: 肺水腫では気道自体は開通しており、酸素投与・非侵襲的陽圧換気・利尿薬で対応する。
B「緊張性気胸」: 緊張性気胸は胸腔穿刺による脱気が第一で、気道の問題ではない。
C「過換気症候群」: 過換気症候群では気道閉塞はなく、まず安心させて呼吸を整える。
E「声帯ポリープ」: 声帯ポリープは嗄声が主症状で、急性の気道閉塞をきたすことは稀である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-21', '正答は B「「自分の考えていることが周りの人に伝わってしまいます」」。

自分の考えが他人に伝わってしまうという体験は考想伝播で、自我障害の一つである。Schneiderの一級症状に含まれ、統合失調症を強く示唆する。

【誤答選択肢の解説】
A「「いつも自殺したいと考えています」」: 希死念慮はうつ病をはじめ多くの精神疾患でみられ、統合失調症に特異的ではない。
C「「映画を見ているような感じで、周囲の景色に実感がありません」」: 現実感が失われる訴えは離人感・現実感消失症で、健常者でも疲労時に生じうる。
D「「汚くないとわかっていても何度も手を洗わないと気がすみません」」: 不合理と分かっていながらやめられない手洗いは強迫症の強迫行為である。
E「「検査で体に異常はないと言われたけれど、間違いなく癌だと思います」」: 検査で異常がないのに重篤な病気だと確信するのは心気症(病気不安症)の訴えである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B021（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-22', '正答は A「エックス線写真を撮影して確認する。」。

胃管が気管に誤挿入されていないことを確実に示せるのはエックス線写真による確認である。誤挿入に気づかず栄養剤を注入すると致命的になる。

【誤答選択肢の解説】
B「口腔内にチューブのたわみがないことを確認する。」: 口腔内でたわんでいないことは、先端が胃にあることの保証にならない。
C「チューブからシリンジで液体が引けることを確認する。」: 気管に入っていても気道分泌物が引けることがあり、確実ではない。
D「挿入されている長さをチューブの目盛りにより確認する。」: 挿入長は目安にすぎず、先端の位置を保証しない。
E「チューブに空気を送り込み、心窩部で気泡音が聴取できることを確認する。」: 気泡音の聴取は気管や食道への誤挿入でも聴こえることがあり、確認法として推奨されない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-23', '正答は A「動眼神経麻痺」。

瞳孔括約筋を支配する副交感神経線維は動眼神経の表層を走る。動眼神経麻痺では散瞳に加えて眼瞼下垂と外眼筋麻痺を伴う。

【誤答選択肢の解説】
B「有機リン中毒」: 有機リン中毒はコリンエステラーゼ阻害によりムスカリン作用が過剰となり、著明な縮瞳をきたす。
C「Horner症候群」: Horner症候群は交感神経の障害で、縮瞳・眼瞼下垂・患側顔面の発汗低下を示す。
D「オピオイド投与」: オピオイドは特徴的な縮瞳(pinpoint pupil)をきたす。
E「Wallenberg症候群」: Wallenberg症候群では同側のHorner症候群を伴い、縮瞳となる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B023（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-25', '正答は A「嗅覚障害」。

嗅覚は姿勢の制御に関与しないため、転倒の危険因子とはならない。転倒予防では下肢筋力・視覚・体性感覚・前庭機能というバランスを支える要素を評価する。

【誤答選択肢の解説】
B「筋力低下」: 下肢筋力の低下は立ち直り反応を弱め、転倒の主要な危険因子である。
C「視覚障害」: 視覚は姿勢制御の重要な入力で、白内障などによる視力低下は転倒を増やす。
D「深部知覚低下」: 深部知覚の低下は足底からの位置情報を失わせ、暗所での転倒を招く。
E「前庭機能障害」: 前庭機能障害はめまい・平衡障害を通じて直接転倒につながる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-26', '正答は A「仰臥位にする。」。

創部を見たことを契機に顔面蒼白と冷汗を伴う気分不快が生じており、血管迷走神経反射(神経調節性失神の前駆症状)である。直ちに仰臥位とし、必要なら下肢を挙上して脳血流を確保する。

【誤答選択肢の解説】
B「AEDを装着する。」: 意識があり脈も保たれており、AEDの適応はない。
C「アドレナリンを筋注する。」: 皮疹や気道症状、曝露歴がなくアナフィラキシーではない。
D「深呼吸するように指導する。」: 過換気の所見はなく、深呼吸の指導はかえって症状を悪化させうる。
E「創部を強くガーゼで圧迫する。」: すでに止血は確認されており、再圧迫は不要である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B026（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-3', '正答は C「265」。

血漿浸透圧の推定式は 2×Na + 血糖/18 + 尿素窒素/2.8。2×125 + 90/18 + 28/2.8 = 250 + 5 + 10 = 265 mOsm/kgH2O となる。低ナトリウム血症が浸透圧を規定していることが読み取れる。

【誤答選択肢の解説】
A「245」: 計算値より20低く、Naの寄与を過小に見積もっている。
B「255」: 計算値より10低い。
D「275」: Naが正常域(140程度)であれば得られる値で、本例の125に合わない。
E「285」: 正常血漿浸透圧の値であり、低ナトリウム血症を反映していない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-31', '正答は D「深部静脈血栓症」。

ネフローゼ症候群では、アンチトロンビンなどの凝固制御因子が尿中に失われる一方で肝臓での凝固因子産生が亢進し、血液濃縮も加わって血栓症を起こしやすい。本例もフィブリノゲンとDダイマーが上昇し、Hb18.1g/dLと血液濃縮を示している。

【誤答選択肢の解説】
A「左室肥大」: 左室肥大は慢性的な圧負荷の結果生じるもので、血圧92/56mmHgの本例で警戒すべき合併症ではない。
B「食道静脈瘤」: 食道静脈瘤は門脈圧亢進症による。低アルブミン血症は共通するが、本例に肝疾患を示す所見はない。
C「視神経乳頭浮腫」: 視神経乳頭浮腫は頭蓋内圧亢進の所見で、ネフローゼ症候群の合併症ではない。
E「甲状腺機能亢進症」: ネフローゼ症候群では甲状腺ホルモン結合蛋白が尿中に失われるため、機能はむしろ低下傾向を示す。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B031（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-33', '正答は B「ビリルビン尿」。

急性下肢動脈閉塞に対する再灌流では、虚血で壊死した筋から細胞内成分が全身へ流入する。高カリウム血症、乳酸アシドーシス、CK上昇、ミオグロビン尿による赤褐色尿、そしてコンパートメント症候群による浮腫が問題となる。ビリルビン尿は肝胆道疾患による所見で、この病態では生じない。

【誤答選択肢の解説】
A「右下肢浮腫」: 再灌流後の浮腫やコンパートメント症候群は典型的な合併症である。
C「高カリウム血症」: 壊死筋から細胞内カリウムが放出され、致死的不整脈の原因となる。
D「乳酸アシドーシス」: 虚血組織に貯留した乳酸が再灌流により全身循環へ流入する。
E「血清クレアチンキナーゼ高値」: 横紋筋融解によりクレアチンキナーゼが著明に上昇する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B033（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-34', '正答は E「脳動脈瘤破裂」。

突然の激しい頭痛に片側の動眼神経麻痺(眼瞼下垂・散瞳・対光反射消失)を伴っており、内頸動脈-後交通動脈分岐部の脳動脈瘤破裂によるくも膜下出血を第一に考える。動脈瘤が直上を走る動眼神経を圧迫することで生じる。

【誤答選択肢の解説】
A「髄膜炎」: 髄膜炎は発熱を伴い数時間から数日かけて進行することが多く、突発する激しい頭痛と片側動眼神経麻痺の組合せは説明できない。
B「脳梗塞」: 脳梗塞では突然の激しい頭痛は典型的でなく、片麻痺を伴わない点も合わない。
C「片頭痛」: 片頭痛は反復する拍動性頭痛で、瞳孔不同と対光反射消失を伴うことはない。
D「緊張型頭痛」: 緊張型頭痛は締めつけられるような持続性の頭痛で、突発せず神経学的異常も伴わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B034（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-35', '正答は E「死亡確認し、死亡診断書を作成する。」。

在宅で看取る方針が本人・家族で共有され、診療を継続してきた患者が、その傷病の経過として死亡している。死後に診察して死因が診療中の傷病であると判断できるため、死亡確認のうえ死亡診断書を作成する。身体所見に不審な点がなく、異状死としての警察への届出も要さない。

【誤答選択肢の解説】
A「救急車を呼ぶ。」: 蘇生を望まない在宅看取りであり、救急要請は本人と家族の意向に反する。
B「警察に通報する。」: 医師法第21条の届出は異状を認めた場合の規定である。診療中の傷病による死亡で不審な点もなく、該当しない。
C「心肺蘇生を行う。」: 心肺蘇生は本人・家族が選択しなかった医療であり、行ってはならない。
D「自家用車で病院に搬送する。」: 病院へ搬送しても得られるものはなく、看取りの場を本人の望んだ自宅から移すことになる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B035（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-37', '正答は D「脊髄後索」。

胃全摘後10年で内因子が失われ、ビタミンB12欠乏による亜急性連合性脊髄変性症をきたしている。閉眼で増強する体幹動揺(Romberg徴候陽性)は深部感覚の障害を示し、後索が主座である。側索も侵されるため膝蓋腱反射は亢進し、末梢神経障害を合併してアキレス腱反射は低下するという一見矛盾した所見をとる。

【誤答選択肢の解説】
A「後頭葉」: 後頭葉の障害では視野障害が主体で、深部感覚障害やしびれは説明できない。
B「大脳基底核」: 大脳基底核の障害では寡動・筋強剛・不随意運動が前面に出る。
C「小脳」: 小脳性の失調では開眼でも動揺があり閉眼で著明に増強することはなく、眼振を伴うことが多い。本例は眼球運動が正常で眼振もない。
E「神経筋接合部」: 神経筋接合部の障害は易疲労性の筋力低下が主体で、感覚障害や腱反射の変化は伴わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B037（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-39', '正答は B「直ちに救急搬送するように指示する。」。

意識変容(JCS II-10)、呼吸数30/分、収縮期血圧78mmHgとqSOFAの3項目すべてを満たし、敗血症性ショックの状態にある。誤嚥性肺炎が疑われ、輸液と抗菌薬、循環管理を要するため直ちに救急搬送する。

【誤答選択肢の解説】
A「NSAIDを服用するように指示する。」: 解熱しても循環不全は改善せず、NSAIDは腎血流をさらに減らすため有害である。
C「午前の外来診療終了後に再度連絡させる。」: 数時間の遅れが予後を左右する病態であり、外来終了を待つ余裕はない。
D「水分を十分に摂り、安静にするように伝える。」: 経口摂取で補える脱水の程度ではなく、静脈路の確保が必要である。
E「定期訪問診療を予定している明日まで様子をみるように伝える。」: 翌日まで待てば死亡しうる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B039（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-4', '正答は B「肺癌」。

Lambert-Eaton筋無力症候群は、小細胞肺癌に伴う傍腫瘍性神経症候群として最も多く発症する。P/Q型電位依存性カルシウムチャネルに対する自己抗体により神経筋接合部からのアセチルコリン放出が減少する。

【誤答選択肢の解説】
A「膵癌」: 膵癌に伴う傍腫瘍症候群としてはTrousseau症候群(遊走性血栓性静脈炎)が知られる。
C「胸腺腫」: 胸腺腫と合併するのは重症筋無力症であり、Lambert-Eaton症候群ではない。
D「直腸癌」: 直腸癌との合併は知られていない。
E「悪性リンパ腫」: 悪性リンパ腫でも傍腫瘍性神経症候群は起こりうるが、Lambert-Eaton症候群の合併頻度は高くない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-40', '正答は B「片肺挿管」。

成人男性の気管チューブの適正な深さは門歯で21〜23cm程度で、28cmは深すぎる。右主気管支に入って左肺が換気されず、左の呼吸音消失・左胸郭挙上不良・低酸素血症をきたしている。チューブを引き抜いて左右の呼吸音を再確認する。

【誤答選択肢の解説】
A「気胸」: 気胸であれば患側の打診で鼓音となるが、本例は打診で左右差がない。
C「食道挿管」: 食道挿管ではカプノグラフに持続する波形は出ない。本例は波形が出ており否定される。
D「気管支けいれん」: 気管支けいれんは両側性で、呼気の延長と喘鳴を伴う。片側の呼吸音消失は説明できない。
E「気管チューブ閉塞」: チューブ閉塞では換気自体が困難となり、片側だけ換気されるという所見にはならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B040（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-5', '正答は D「児童相談所に通告する。」。

児童虐待の防止等に関する法律により、虐待を受けたと思われる児童を発見した者には通告義務がある。確証は不要で、疑いの段階で児童相談所または市町村に通告する。守秘義務違反にはあたらない。

【誤答選択肢の解説】
A「学校に連絡する。」: 学校への連絡は通告に代わるものではない。まず通告する。
B「警察へ通報する。」: 通告先は児童相談所または市町村である。生命の危険が差し迫っていれば警察にも連絡するが、原則ではない。
C「虐待の事実を立証する。」: 虐待の事実の立証は医師の役割ではなく、児童相談所や司法の判断に委ねる。
E「親に事実関係を確認する。」: 親への確認は証拠の隠滅や児のさらなる危険を招くおそれがあり、通告前に行うべきでない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-6', '正答は B「「鼻腔RSウイルス迅速検査を行います」」。

生後8か月で発熱・咳嗽・鼻汁に続いて喘鳴と陥没呼吸をきたし、SpO2が低下している。乳児の急性細気管支炎で、原因としてRSウイルスが最も多い。鼻腔からの迅速検査で診断でき、入院時の隔離方針にも直結する。

【誤答選択肢の解説】
A「「咽頭溶連菌迅速検査を行います」」: A群溶連菌性咽頭炎は3歳未満には稀で、喘鳴を主体とする本例の病像と合わない。
C「「尿中肺炎球菌抗原迅速検査を行います」」: 尿中肺炎球菌抗原は小児では鼻咽腔の保菌で偽陽性となりやすく、有用性が低い。
D「「咽頭アデノウイルス迅速検査を行います」」: アデノウイルス感染では眼球結膜の充血や滲出性扁桃炎を伴うことが多いが、本例では認めない。
E「「咽頭マイコプラズマ迅速検査を行います」」: マイコプラズマ感染は学童期以降に多く、乳児の細気管支炎の原因としては考えにくい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-7', '正答は C「右小脳半球」。

小脳は同側性に四肢の協調運動を支配する。右上肢の運動失調は右小脳半球の病変で生じる。

【誤答選択肢の解説】
A「右放線冠」: 放線冠は皮質脊髄路の通り道で、障害されると対側(左)の運動麻痺をきたす。
B「右中脳被蓋」: 中脳被蓋では上小脳脚がすでに交叉しており、病変により対側の失調を生じる。
D「左延髄外側」: 左延髄外側の障害(Wallenberg症候群)では同側すなわち左の小脳性失調をきたす。
E「左脊髄後索」: 脊髄後索の障害は同側の深部感覚障害による感覚性失調で、左病変なら左に出る。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-8', '正答は A「医師法に定められている。」。

説明と同意について定めているのは医療法である(第1条の4第2項で、医療従事者は適切な説明を行い理解を得るよう努めなければならないとされる)。医師法ではない。

【誤答選択肢の解説】
B「患者の自己決定権の行使が目的である。」: 患者が自らの価値観に基づいて治療を選べるようにすることが目的で、正しい。
C「代替可能な治療法についても提示する。」: 提案する治療だけでなく代替となる選択肢や何もしない場合の見通しも示す必要がある。
D「同意はいつでも撤回することができる。」: 一度同意しても患者はいつでも撤回でき、それによって不利益を受けない。
E「医療従事者側からの十分な説明が前提である。」: 判断に足る情報が医療従事者側から十分に提供されていることが前提となる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-B-9', '正答は E「大胸筋前面での可動性低下」。

腫瘤が大胸筋の前面で動かなくなっているのは、癌が乳腺を越えて胸壁側へ浸潤・固定していることを意味し、乳癌を強く示唆する。

【誤答選択肢の解説】
A「随伴する疼痛」: 疼痛を伴う乳房腫瘤は乳腺症や乳腺炎など良性のことが多く、乳癌はむしろ無痛性が典型である。
B「乳頭部の熱感」: 乳頭部の熱感は急性乳腺炎で目立つ。炎症性乳癌もあるが頻度は低い。
C「平滑な腫瘤表面」: 境界明瞭で表面平滑な可動性腫瘤は線維腺腫など良性を示唆する。乳癌は表面不整で硬い。
D「白色の乳頭分泌物」: 乳汁様・白色の分泌物は生理的あるいは高プロラクチン血症による。乳癌を示唆するのは血性分泌である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 B009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-1', '正答は C「構想区域は都道府県単位である。」。

地域医療構想の構想区域は、原則として二次医療圏を単位とする。都道府県単位ではない。

【誤答選択肢の解説】
A「2025年の医療需要を推計する。」: 団塊の世代が75歳以上となる2025年の医療需要を推計するのが出発点である。
B「医療計画の一部として策定する。」: 医療計画の一部として都道府県が策定する。
D「病床の必要量を病床の機能別に推計する。」: 高度急性期・急性期・回復期・慢性期の機能別に必要病床数を推計する。
E「地域医療構想会議には医療保険者も参加する。」: 地域医療構想調整会議には医療関係者のほか医療保険者も参加する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-10', '正答は D「自己複製能」。

造血幹細胞の本質的な性質は、自分と同じ細胞を作り出す自己複製能と、すべての血球系統へ分化できる多分化能である。この2つがあるため生涯にわたり血球を供給し続けられる。

【誤答選択肢の解説】
A「止血作用」: 止血に働くのは血小板である。
B「貪食作用」: 貪食を担うのは好中球やマクロファージなど分化した細胞である。
C「酸素運搬能」: 酸素運搬は成熟赤血球のヘモグロビンが担う。
E「血栓溶解作用」: 血栓の溶解はプラスミンによる線溶系の働きである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-12', '正答は A「食中毒患者を診断したとき保健所長に届け出る。」。

食品衛生法により、食中毒患者を診断した医師は直ちに最寄りの保健所長に届け出なければならない。集団発生の探知と拡大防止の起点になる。

【誤答選択肢の解説】
B「サルモネラ菌による食中毒で発熱を起こすことはない。」: サルモネラ食中毒は発熱・腹痛・下痢を典型とし、発熱はむしろ特徴的である。
C「黄色ブドウ球菌食中毒の予防には食品の食前加熱が有効である。」: 黄色ブドウ球菌の産生するエンテロトキシンは耐熱性で、加熱しても失活しない。予防は菌を増やさないこと(手指衛生と低温保存)である。
D「カンピロバクターによる食中毒の潜伏期間は2〜3週間である。」: カンピロバクターの潜伏期は2〜5日で、細菌性食中毒のなかではやや長いがそれでも週単位ではない。
E「我が国での食中毒による患者数では腸炎ビブリオによるものが最も多い。」: 近年の食中毒患者数はノロウイルスとカンピロバクターが上位を占め、腸炎ビブリオは減少している。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C012（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-13', '正答は A「「一定時刻に起床し日光を浴びましょう」」。

睡眠衛生の基本は、起床時刻を一定にして朝の光を浴び、体内時計を毎日リセットすることである。入眠時刻は結果としてついてくる。

【誤答選択肢の解説】
B「「可能な限り早い時刻に就床しましょう」」: 眠くないうちから床に就くと、床のなかで眠れない時間が延びて入眠困難がかえって悪化する。
C「「就床前にアルコール飲料を飲むようにしましょう」」: アルコールは入眠を早めるが睡眠を浅くし中途覚醒を増やす。耐性がついて量が増える危険もある。
D「「一晩に8時間以上就床しているようにしましょう」」: 臥床時間を延ばすと睡眠効率が下がり、不眠が固定しやすい。
E「「就床後、入眠できない時はじっと眠気が来るのを待ちましょう」」: 眠れないまま床にとどまると「床＝眠れない場所」という条件づけができる。いったん床を離れ、眠気が来てから戻る(刺激制御法)。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C013（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-15', '正答は E「らせん状視野 — 心因性視力障害」。

らせん状視野は、視野計測を繰り返すうちに測定値がらせん状に狭くなっていくもので、解剖学的な視路の障害では説明できない。管状視野とともに心因性視力障害・視野異常に特徴的な所見である。

【誤答選択肢の解説】
A「管状視野 — 視神経炎」: 視神経炎で典型的なのは中心暗点である。管状視野は網膜色素変性症の末期や緑内障末期、心因性でみられる。
B「同名半盲 — 黄斑疾患」: 同名半盲は視交叉より後方の視路の障害による。黄斑疾患では中心暗点となる。
C「盲中心暗点 — 緑内障」: 盲中心暗点は視神経炎や中毒性視神経症でみられる。緑内障ではBjerrum暗点や鼻側階段が特徴的である。
D「Bjerrum暗点 — 視路障害」: Bjerrum暗点は緑内障の典型的な視野欠損である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C015（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-17', '正答は D「ロコモティブシンドローム」。

運動器の障害により移動機能が低下した状態をロコモティブシンドローム(運動器症候群)と呼ぶ。日本整形外科学会が提唱した概念で、要介護に至る前段階として予防的介入の対象になる。

【誤答選択肢の解説】
A「クラッシュシンドローム」: クラッシュシンドロームは長時間の圧挫後、解放により生じる横紋筋融解と高カリウム血症・急性腎障害である。
B「ダンピングシンドローム」: ダンピングシンドロームは胃切除後に食物が急速に小腸へ流入して起こる症候群である。
C「メタボリックシンドローム」: メタボリックシンドロームは内臓脂肪蓄積を基盤とする代謝異常の集積で、運動器の概念ではない。
E「コンパートメントシンドローム」: コンパートメントシンドロームは筋区画内圧の上昇による循環障害で、急性の外科的緊急症である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-18', '正答は D「腹部ダイナミックCT」。

腹部ダイナミックCTは単純相に加えて動脈相・門脈相・平衡相と複数回撮影するため、1回の検査当たりの被ばく線量が最も大きくなる。

【誤答選択肢の解説】
A「FDG-PET」: FDG-PETの被ばくは投与放射能に依存し、PET単独では数mSv程度でダイナミックCTには及ばない。
B「頭部単純CT」: 頭部単純CTは撮影範囲が限られ、2mSv前後である。
C「上部消化管造影検査」: 上部消化管造影は透視時間によるが、数mSv程度である。
E「胸部単純エックス線写真」: 胸部単純エックス線写真は0.1mSv未満で、選択肢のなかで最も少ない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C018（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-2', '正答は E「保険療養費は被災労働者の自己負担はない。」。

労働者災害補償保険の療養補償給付は現物給付(療養の給付)として全額が支給され、被災労働者の自己負担はない。健康保険と異なり一部負担金が生じない点が重要である。

【誤答選択肢の解説】
A「通勤災害は含まれない。」: 平成期の改正で通勤災害も給付対象に含まれている。
B「保険者は市町村である。」: 保険者は国(政府)であり、市町村ではない。
C「労働災害の認定は厚生労働大臣が行う。」: 業務上外の認定は労働基準監督署長が行う。
D「保険料は労働者と事業者の両者で負担する。」: 労災保険料は全額を事業主が負担し、労働者の負担はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-22', '正答は E「興味のあるものに指さしをしない。」。

興味のあるものを指さして相手と共有する行動(共同注意)は生後10〜12か月ごろに現れる。2歳0か月で指さしがないのは明らかな発達の遅れで、自閉スペクトラム症を含めた評価が必要になる。

【誤答選択肢の解説】
A「三輪車をこげない。」: 三輪車をこげるようになるのは3歳ごろで、2歳でできなくても遅れではない。
B「片足立ちができない。」: 片足立ちは3〜4歳の課題である。
C「自分の姓名が言えない。」: 自分の姓名を言えるようになるのは3歳ごろである。
D「はさみで紙を切れない。」: はさみで紙を切れるようになるのは3歳ごろである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-24', '正答は C「100」。

グルコース5.0%は100mLあたり5gなので、500mL中には25gが含まれる。糖質は1gあたり約4kcalなので、25g×4=100kcalとなる。維持輸液だけでは必要エネルギーをまったく賄えないことが分かる。

【誤答選択肢の解説】
A「25」: 約6gのグルコースに相当し、濃度と液量の掛け算が合わない。
B「50」: グルコース量を半分に見積もった値である。
D「200」: グルコース50g分にあたり、5%500mLの2倍である。
E「400」: 1gあたり9kcalの脂質として計算したような値で、糖質のエネルギー換算と合わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-3', '正答は C「死戦期呼吸を認めたら蘇生行為を開始する。」。

死戦期呼吸(あえぎ呼吸)は心停止直後にみられる異常呼吸で、正常な呼吸ではない。これを認めたら心停止と判断して直ちに胸骨圧迫を開始する。

【誤答選択肢の解説】
A「胸骨圧迫の深さは胸の厚さの約1/2である。」: 胸骨圧迫の深さは胸の厚さの約1/3で、乳児では約4cmが目安である。
B「胸骨圧迫は60〜80回/分の速さで行う。」: 胸骨圧迫の速さは年齢によらず100〜120回/分である。
D「2人の救助者で行う場合の胸骨圧迫と人工呼吸の比は30:2である。」: 医療者2人で行う小児・乳児の蘇生では胸骨圧迫と人工呼吸の比は15:2とする。30:2は1人法または成人の場合である。
E「脈拍の触知は大腿動脈で行う。」: 乳児では上腕動脈で脈を確認する。大腿動脈は小児で用いる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-35', '正答は B「徒手整復」。

手を引っ張られた直後から肘を動かさなくなり、橈骨頭周囲に圧痛があって腫脹・熱感・発赤がなく、エックス線写真でも骨折がない。輪状靱帯から橈骨頭が亜脱臼する肘内障で、徒手整復(回外法または回内屈曲法)で速やかに改善する。

【誤答選択肢の解説】
A「NSAID」: 整復すれば直ちに使えるようになる病態で、鎮痛薬で経過をみる意味はない。
C「シーネ固定」: 固定しても亜脱臼は戻らない。整復が先である。
D「肘関節包切開」: 感染や外傷性の関節内病変ではなく、観血的処置の適応はない。
E「肘関節可動域訓練」: 整復前の可動域訓練は疼痛を与えるだけで意味がない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C035（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-37', '正答は E「副腎皮質ステロイド全身投与」。

犬吠様(オットセイの鳴き声様)咳嗽、吸気性喘鳴、陥没呼吸はクループ症候群(急性喉頭気管気管支炎)の典型像である。アドレナリン吸入は効果が一過性なので、声門下の浮腫を抑えるデキサメタゾンなど副腎皮質ステロイドの全身投与を併せて行う。

【誤答選択肢の解説】
A「気管挿管」: SpO2 96%で意識も保たれており、直ちに挿管する段階ではない。挿管はさらに気道浮腫を招く危険もある。
B「吸入β2刺激薬投与」: β2刺激薬は下気道の平滑筋に働くもので、声門下の浮腫による上気道狭窄には無効である。
C「呼吸リハビリテーション」: 急性の気道狭窄に呼吸リハビリテーションの適応はない。
D「マクロライド系抗菌薬投与」: クループの大半はパラインフルエンザウイルスなどウイルス性で、抗菌薬は無効である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C037（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-38', '正答は C「炭水化物主体の食事にする。」。

炭水化物は呼吸商が1.0と高く、代謝により産生される二酸化炭素が多い。換気予備能の乏しいCOPD患者では炭水化物主体の食事はCO2産生を増やして換気の負担となるため、脂質の比率を高めた食事が勧められる。

【誤答選択肢の解説】
A「塩分の過剰摂取を避ける。」: 肺性心や浮腫を避けるため、塩分の過剰摂取は控える。適切である。
B「1回の食事摂取量を減らす。」: 腹部膨満が横隔膜を押し上げて呼吸を妨げるため、1回量を減らして分割食にする。適切である。
D「十分なエネルギー量を摂取する。」: 呼吸仕事量の増大でエネルギー消費が亢進しており、十分なエネルギー摂取が必要である。適切である。
E「分岐鎖アミノ酸の摂取を心掛ける。」: 骨格筋量の維持のため分岐鎖アミノ酸を含む蛋白質の確保が勧められる。適切である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C038（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-39', '正答は D「サルコペニア」。

長期透析と加齢を背景に、歩行速度の低下、体重減少、下肢筋力低下(MMT 4)が揃っており、サルコペニアと考える。透析患者では蛋白異化の亢進と活動量低下が重なり、高頻度にみられる。

【誤答選択肢の解説】
A「腎性貧血」: Hb11.0g/dLは透析患者の管理目標範囲に近く、この程度の貧血で横断歩道を渡りきれないほどの歩行障害は説明できない。
B「高尿酸血症」: 高尿酸血症は関節炎の原因になるが、本例に関節症状の記載はない。
C「高リン血症」: 高リン血症は血管石灰化や二次性副甲状腺機能亢進症に関わるが、直接歩行機能を落とすものではない。
E「閉塞性動脈硬化症」: 閉塞性動脈硬化症なら間欠性跛行と足背動脈の触知不良を伴うが、本例は左右差なく触知できる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C039（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-4', '正答は E「現在の気持ちについて話題にする。」。

「死にたい」という訴えの背後には、痛み、孤独、役割の喪失、家族への負担感など具体的な苦痛が隠れている。まず訴えを否定せずに受け止め、いま何を感じているかを尋ねることが出発点になる。

【誤答選択肢の解説】
A「頑張れと励ます。」: 励ましは「その苦しみは受け止めてもらえない」というメッセージになり、患者を孤立させる。
B「速やかに退院させる。」: 訴えの背景を確かめずに退院を進めるのは、問題からの回避である。
C「ホスピスへの入院を勧める。」: 療養場所の調整は必要になりうるが、気持ちを聴く前に持ち出す話ではない。
D「死について触れないようにする。」: 死の話題を避けることは、患者が最も話したいことを封じることになる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-41', '正答は B「術前3時間までの飲水」。

術後回復力強化(ERAS)の考え方では、術前の長時間絶飲食は脱水とインスリン抵抗性を招くため避け、清澄水は麻酔導入の2〜3時間前まで摂取を許可する。

【誤答選択肢の解説】
A「術前48時間の絶食」: 48時間もの絶食は脱水と異化亢進を招き、合併症を増やす。
C「術中大量輸液」: 術中の過剰輸液は腸管浮腫を生じて縫合不全や腸管麻痺のリスクを高める。目標指向型の適正輸液を行う。
D「術後3日間のベッド上安静」: 術後は早期離床が原則で、臥床の継続は肺炎・静脈血栓症・筋力低下を招く。
E「術後1週間の絶食」: 結腸切除後も早期に経口摂取を開始するのが標準で、1週間の絶食は回復を遅らせる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C041（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-43', '正答は B「オピオイド投与」。

寛解に至らない急性白血病の患者で、NSAIDでは抑えられない腰背部痛と腹痛が増悪し歩行も不能になっている。まず苦痛を取ることが優先で、WHO方式に沿って強オピオイドへ切り替える。血小板が低下しつつある状況でNSAIDを続けることも避けたい。

【誤答選択肢の解説】
A「アルブミン製剤投与」: アルブミン製剤は膠質浸透圧を保つためのもので、疼痛には無効である。
C「血小板輸血」: 皮下出血などの出血徴候はなく、この血小板数で予防的輸血の適応にはならない。
D「全身放射線照射」: 全身放射線照射は造血幹細胞移植の前処置であり、この場面の疼痛緩和にはならない。
E「薬物による抗癌治療」: すでに複数の薬物療法で寛解に至っておらず、また抗癌治療に即座の除痛効果は期待できない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C043（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-47', '正答は D「生活習慣に関する詳細な聴取」。

腹囲104cm、血糖・脂質・肝機能の異常、喫煙、毎日の飲酒と危険因子が重なっており、どれか一つに介入すればよい状態ではない。まず食事内容、飲酒量、身体活動、喫煙の実態と本人の考えを詳しく聴き取り、優先順位をつけて介入を組み立てる。

【誤答選択肢の解説】
A「降圧薬投与」: 血圧138/76mmHgは高値血圧の域で、この段階で降圧薬を開始する適応はない。
B「ニコチン補充療法」: 禁煙の意思や準備性を確認しないまま薬物療法を始めても続かない。
C「75g経口ブドウ糖負荷試験」: 空腹時血糖130mg/dL、HbA1c6.8%ですでに糖尿病型を疑う値であり、負荷試験を行う段階を越えている。
E「週3回以上のジョギングの推奨」: 現在の活動量や整形外科的な問題を把握せずに一律の運動強度を勧めるのは、続かないうえ危険でもある。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C047（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-49', '正答は D「肺血栓塞栓症」。

妊娠・産褥期は凝固能が亢進しており、帝王切開・肥満・術後臥床が加わって静脈血栓塞栓症の高リスクとなる。臥床していた患者が初回歩行を始めた直後に突然の呼吸困難・胸痛・低酸素血症をきたすのは肺血栓塞栓症の典型的な発症様式で、下肢深部静脈の血栓が遊離したことによる。

【誤答選択肢の解説】
A「羊水塞栓症」: 羊水塞栓症は分娩中から直後に発症し、播種性血管内凝固と大量出血を伴う。産後1日目の初回歩行時という経過に合わない。
B「急性心筋梗塞」: 29歳で急性心筋梗塞は極めて稀で、心電図異常の記載もない。
C「周産期心筋症」: 周産期心筋症は心不全として数日から数週かけて進行するもので、突然発症の胸痛と低酸素血症は説明できない。
E「急性大動脈解離」: 急性大動脈解離では引き裂かれるような激痛や血圧の左右差を伴う。呼吸音正常で酸素化のみが低下する本例とは病像が異なる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C049（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-5', '正答は C「国民健康・栄養調査」。

国民健康・栄養調査は、栄養摂取状況・身体状況・生活習慣を毎年把握する調査で、健康日本21をはじめとする一次予防(健康増進・発症予防)施策の基礎資料となる。

【誤答選択肢の解説】
A「患者調査」: 患者調査は医療機関を受診した患者の傷病状況を調べるもので、二次予防以降の資料である。
B「人口動態調査」: 人口動態調査は出生・死亡・婚姻などを扱い、健康増進施策の直接の基礎資料ではない。
D「医師・歯科医師・薬剤師調査」: 医師・歯科医師・薬剤師調査は医療従事者の分布を把握する調査である。
E「全国在宅障害児・者等実態調査」: 全国在宅障害児・者等実態調査は障害福祉施策のための調査である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-50', '正答は D「地域包括支援センター」。

地域包括支援センターは、高齢者の総合相談窓口として介護予防・権利擁護・ケアマネジメントを担う。介護保険の利用に至る前の生活上の困りごとを相談する先として適切である。

【誤答選択肢の解説】
A「診療所」: 診療所は医療の窓口であり、生活支援の調整を担う機関ではない。
B「保健所」: 保健所は感染症対策や難病支援など公衆衛生を担い、個別の生活支援の窓口ではない。
C「特別養護老人ホーム」: 特別養護老人ホームは原則要介護3以上を対象とする入所施設で、在宅生活の相談先ではない。
E「訪問看護ステーション」: 訪問看護ステーションは医療的ケアを提供する事業所で、サービス全体を調整する総合相談窓口ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C050（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-53', '正答は E「5」。

要介護度は市町村の介護認定審査会が一次判定と主治医意見書をもとに決定するもので、主治医が意見書に記載する事項ではない。主治医は医学的な状態像を書く。

【誤答選択肢の解説】
A「1」: 麻痺の有無と程度は身体状況として記載が求められる。
B「2」: 食事の摂取方法は日常生活動作の状況として記載する。
C「3」: 移動能力や屋外歩行の可否は記載事項である。
D「4」: 認知機能や意思決定能力は記載事項である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C053（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-56', '正答は E「感染予防にサージカルマスク着用が有用である。」。

麻疹は空気感染するため、サージカルマスクでは感染を防げない。医療従事者にはN95マスクの着用が必要で、患者は陰圧個室で管理する。

【誤答選択肢の解説】
A「保健所へ届け出る。」: 麻疹は5類感染症の全数把握対象で、診断した医師は直ちに保健所へ届け出る。正しい。
B「ウイルス遺伝子検査を行う。」: 血液・咽頭ぬぐい液・尿からのウイルス遺伝子検査で確定診断する。正しい。
C「陰圧個室管理体制で診療する。」: 空気感染対策として陰圧個室での管理は正しい。
D「患者の受診前の行動を確認する。」: 感染力が強く、受診前の行動から接触者を把握して感染拡大を防ぐ必要がある。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C056（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-7', '正答は E「医療ソーシャルワーカー」。

医療ソーシャルワーカーは保健医療機関で相談援助を担う職種の呼称であって、資格の名称ではない。相当する国家資格は社会福祉士である。

【誤答選択肢の解説】
A「介護福祉士」: 介護福祉士は社会福祉士及び介護福祉士法に基づく国家資格である。
B「言語聴覚士」: 言語聴覚士は言語聴覚士法に基づく国家資格である。
C「理学療法士」: 理学療法士は理学療法士及び作業療法士法に基づく国家資格である。
D「臨床工学技士」: 臨床工学技士は臨床工学技士法に基づく国家資格である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-8', '正答は D「浮腫性硬化症 — 糖尿病」。

浮腫性硬化症(scleredema)は項部から背部にかけて皮膚が板状に硬くなる疾患で、コントロール不良の2型糖尿病に合併する型が知られる。

【誤答選択肢の解説】
A「Sweet病 — 慢性膵炎」: Sweet病(急性熱性好中球性皮膚症)は骨髄異形成症候群や白血病などの血液疾患に伴うことがある。
B「環状肉芽腫 — 甲状腺機能亢進症」: 環状肉芽腫は糖尿病との関連が指摘される疾患で、甲状腺機能亢進症ではない。
C「壊疽性膿皮症 — Fabry病」: 壊疽性膿皮症は潰瘍性大腸炎などの炎症性腸疾患や関節リウマチに伴う。
E「脛骨前粘液水腫 — 潰瘍性大腸炎」: 脛骨前粘液水腫はBasedow病に特徴的で、潰瘍性大腸炎ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-C-9', '正答は C「市役所入口の自動ドア」。

ユニバーサルデザインは、障害の有無や年齢にかかわらず初めから誰もが使える設計を指す。自動ドアは車椅子利用者にも荷物を持った人にも子どもにも等しく有用で、特定の人向けの設備ではない点が該当する。

【誤答選択肢の解説】
A「市民会館の授乳室」: 授乳室は授乳する人のための専用設備で、対象を限定している。
B「国道交差点の歩道橋」: 歩道橋は階段があり、車椅子利用者や高齢者をむしろ排除する。
D「美術館のオストメイト対応トイレ」: オストメイト対応トイレは人工肛門・人工膀胱保有者のための設備である。
E「駅のプラットホームの点字ブロック」: 点字ブロックは視覚障害者のための設備で、バリアフリーの発想にあたる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 C009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-1', '正答は D「頸部の聴診」。

繰り返す片側性の一過性視力障害(一過性黒内障)は、同側の内頸動脈の粥腫から飛んだ微小塞栓が網膜中心動脈を一時的に閉塞して起こる。頸部を聴診して血管雑音を確認し、頸動脈エコーへつなげる。脳梗塞の前触れであり見逃せない。

【誤答選択肢の解説】
A「眼圧測定」: 眼圧上昇による急性緑内障発作は視力低下が持続し、眼痛・充血・頭痛を伴う。反復して自然軽快する経過に合わない。
B「視野検査」: 視野検査は発作間欠期には正常で、診断の決め手にならない。
C「対光反射」: 対光反射も発作間欠期には正常である。
E「眼球運動検査」: 眼球運動障害は視力障害の機序に関与しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-10', '正答は B「大動脈二尖弁」。

大動脈二尖弁は左心系の弁の形態異常で、右左短絡を生じないためチアノーゼをきたさない。狭窄や閉鎖不全、上行大動脈拡大が問題となる。

【誤答選択肢の解説】
A「Fallot四徴症」: Fallot四徴症は右室流出路狭窄と心室中隔欠損により右左短絡を生じ、チアノーゼをきたす。
C「完全大血管転位症」: 完全大血管転位症は体循環と肺循環が並列となり、生後早期から強いチアノーゼを示す。
D「総肺静脈還流異常症」: 総肺静脈還流異常症では肺静脈血が右房に還り、心房間交通を通じて右左短絡となる。
E「Eisenmenger症候群」: Eisenmenger症候群では肺高血圧により短絡が右左に逆転してチアノーゼが出現する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-11', '正答は E「後頸部リンパ節腫脹」。

伝染性単核球症(EBウイルス感染症)では後頸部のリンパ節が腫大するのが特徴で、前頸部が主体となるA群溶連菌性咽頭炎との鑑別点になる。肝脾腫、異型リンパ球、肝逸脱酵素上昇を伴う。

【誤答選択肢の解説】
A「頭痛」: 頭痛は両者に共通してみられ、鑑別に役立たない。
B「発熱」: 発熱も両者に共通する。
C「咽頭発赤」: 咽頭発赤・扁桃の白苔はどちらでもみられ、外観では区別できない。
D「乾性咳嗽」: 咳嗽の有無はウイルス性咽頭炎と溶連菌性咽頭炎の区別に用いるが、伝染性単核球症を特異的に示すものではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-16', '正答は D「右付属器」。

子宮内膜症性囊胞(チョコレート囊胞)を背景に発生した卵巣癌が疑われる。卵巣癌の標準術式は子宮全摘・両側付属器摘出・大網切除であり、肉眼的に正常にみえる対側(右)の付属器も摘出する。潜在的な転移や新たな発生の場となるためである。

【誤答選択肢の解説】
A「腟壁」: 腟壁への浸潤を示す所見はなく、切除の対象にならない。
B「膀胱」: 膀胱への浸潤や癒着は認められていない。
C「S状結腸」: 腫瘤と腸管との癒着はないと明記されており、S状結腸を合併切除する理由がない。
E「腸間膜リンパ節」: 腹膜播種がなく、腸間膜リンパ節は卵巣癌の所属リンパ節でもない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D016（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-17', '正答は C「子宮破裂」。

腹腔鏡下子宮筋腫核出術の既往があり、その瘢痕部から子宮が破裂したと考える。外出血が少量にとどまるのに頻脈・低血圧・意識混濁と腹痛をきたしているのは、出血が腹腔内に貯留しているためである。

【誤答選択肢の解説】
A「頸管裂傷」: 頸管裂傷では持続する鮮紅色の外出血が目立つ。本例は外出血が少量である。
B「弛緩出血」: 弛緩出血でも外出血が多量となり、子宮は柔らかく触れる。
D「癒着胎盤」: 胎盤は5分でスムーズに娩出されており、癒着胎盤は否定的である。
E「子宮内反症」: 子宮内反症では腟内に反転した子宮底を触知し、強い下腹部痛と外出血を伴う。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-18', '正答は B「卵巣」。

1年前から月経がなくFSHが38mIU/mLと上昇しており、卵巣機能の低下によるエストロゲン欠乏状態にある。発作性の発汗・熱感(hot flush)や肩こりは更年期症状で、原因臓器は卵巣である。

【誤答選択肢の解説】
A「肝臓」: AST・ALTとも正常で肝疾患を示す所見はない。
C「下垂体」: FSHが高値であることは下垂体が正常に反応している証拠で、下垂体の障害は否定的である。
D「冠動脈」: 心電図に異常がなく胸部症状もない。冠動脈疾患では説明できない。
E「甲状腺」: TSHもFT4も基準内で、甲状腺機能は正常である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D018（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-19', '正答は C「遂行機能障害」。

時刻や食事内容への常同的なこだわり、脱抑制的な易怒性、自分の主張を押し通す社会的行動の変化が前景で、記憶・見当識・日常生活動作は保たれている。行動障害型前頭側頭型認知症であり、前頭葉機能である遂行機能の障害が予想される。

【誤答選択肢の解説】
A「幻視」: 具体的で反復する幻視はLewy小体型認知症の中核症状である。
B「復唱障害」: 復唱の障害は伝導失語でみられる所見で、会話に不自由のない本例には合わない。
D「視空間認知能障害」: 視空間認知の障害はAlzheimer型やLewy小体型で目立つ。
E「エピソード記憶障害」: エピソード記憶の障害はAlzheimer型の中核症状だが、本例は物忘れがないと明記されている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-2', '正答は A「脂腺癌」。

マイボーム腺(脂腺)由来の脂腺癌は霰粒腫と外観が酷似し、高齢者で再発を繰り返す霰粒腫では必ず鑑別する。診断が遅れやすい悪性腫瘍で、疑えば生検を行う。

【誤答選択肢の解説】
B「乳頭腫」: 乳頭腫は有茎性で表面が乳頭状に隆起し、霰粒腫の皮下腫瘤とは外観が異なる。
C「麦粒腫」: 麦粒腫は急性の炎症で発赤・疼痛・熱感を伴い、無痛性の霰粒腫と経過が異なる。
D「基底細胞癌」: 基底細胞癌は眼瞼縁に潰瘍や結節を作り睫毛脱落を伴うことが多く、瞼板内の腫瘤とは像が違う。
E「ぶどう膜腫瘍」: ぶどう膜腫瘍は眼球内の腫瘍で、眼瞼腫瘤と紛れることはない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-29', '正答は B「頰粘膜」。

発熱がいったん下がって再び上昇する二峰性の経過と、その後の発疹は麻疹に典型的である。カタル期の終わりに頰粘膜(第二大臼歯付近)に現れるKoplik斑は麻疹に特異的で、発疹出現前後の短期間しか見られないため確認を急ぐ。

【誤答選択肢の解説】
A「口唇」: 口唇の変化(いちご舌や口唇の紅潮・亀裂)は川崎病や溶連菌感染症の所見である。
C「眼球結膜」: 眼球結膜の充血は麻疹でもみられるが、川崎病やアデノウイルス感染でも生じ特異性が低い。
D「頸部リンパ節」: 後頸部リンパ節腫脹は風疹を示唆する所見である。
E「BCGの接種部位」: BCG接種部位の発赤は川崎病に特徴的な所見である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D029（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-31', '正答は E「保存療法として足関節背屈制限装具を用いる。」。

アキレス腱断裂の保存療法では、足関節を底屈位に保って断裂した腱の断端を近づけ、背屈を制限する装具を用いる。治癒に伴って徐々に背屈を許していく。

【誤答選択肢の解説】
A「手術治療の適応はない。」: スポーツ復帰を目指す例や再断裂を避けたい例では手術も選択肢となり、適応がないとは言えない。
B「足関節の自動運動ができない。」: 長母趾屈筋や後脛骨筋など他の底屈筋が働くため自動運動は可能で、つま先立ちができないだけである。
C「足関節前後方向の不安定性が生じる。」: 前後方向の不安定性は靱帯損傷でみられるもので、腱の断裂では生じない。
D「下腿三頭筋の把握テストで足関節が底屈する。」: Thompson試験では下腿三頭筋を把握しても足関節が底屈しないことが断裂の所見である。底屈するのは腱が連続している証拠になる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D031（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-35', '正答は A「減圧症」。

潜水後に十分な時間をおかず航空機に搭乗すると、機内の気圧低下により体内に溶けていた窒素が気泡化して減圧症をきたす。関節痛(ベンズ)や四肢のしびれ、手指の震えといった神経症状が現れる。

【誤答選択肢の解説】
B「動揺病」: 動揺病は悪心・嘔吐・冷汗が主症状で、関節痛や指先の感覚異常は生じない。
C「頸肩腕障害」: 頸肩腕障害は反復作業の蓄積で緩徐に進行するもので、ダイビングと搭乗を契機とする急性発症に合わない。
D「有機溶剤中毒」: 塗料店での仕事は在庫管理であって有機溶剤への曝露は限定的であり、症状の発現時期がダイビングと搭乗に一致している。
E「VDT作業による障害」: VDT作業による障害は眼精疲労や頸肩腕症状が中心で、経過が合わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D035（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-36', '正答は B「寒冷凝集素高値」。

寒冷曝露で手指や耳介がチアノーゼとなり、貧血・黄疸・ヘモグロビン尿(尿潜血3+)を伴っている。IgM型の寒冷凝集素が低温で赤血球に結合し、補体を介して血管内溶血を起こす寒冷凝集素症である。

【誤答選択肢の解説】
A「網赤血球低値」: 溶血に対する骨髄の代償で網赤血球はむしろ増加する。
C「IgG型自己抗体陽性」: IgG型の自己抗体が関与するのは温式自己免疫性溶血性貧血で、寒冷凝集素はIgMである。
D「血清ハプトグロビン高値」: 血管内溶血で遊離したヘモグロビンと結合して消費されるため、ハプトグロビンは低下する。
E「GPIアンカー蛋白欠損赤血球陽性」: GPIアンカー蛋白の欠損は発作性夜間ヘモグロビン尿症の所見で、寒冷曝露との関連はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D036（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-40', '正答は D「頸動脈洞マッサージ」。

両側頸動脈に動脈硬化性狭窄があるため、頸動脈洞マッサージは粥腫を遊離させて脳塞栓を起こす危険があり行ってはならない。同様に高齢者や頸動脈雑音を聴取する例では禁忌である。

【誤答選択肢の解説】
A「Valsalva手技」: Valsalva手技は迷走神経刺激により発作性上室頻拍を停止させる方法で、最初に試みるべき安全な手技である。
B「ベラパミル投与」: ベラパミルは房室結節の伝導を抑えて発作性上室頻拍を停止させる。
C「ジソピラミド投与」: ジソピラミドはIa群抗不整脈薬で、上室頻拍に用いられることがある。
E「アデノシン三リン酸投与」: アデノシン三リン酸は房室結節を一過性に遮断し、発作性上室頻拍の停止に有効である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D040（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-42', '正答は A「関節液検査」。

発熱を伴う急性の単関節炎で、関節液を採取して細胞数・グラム染色・培養・偏光顕微鏡による結晶の検索を行うことが最優先である。化膿性関節炎と結晶誘発性関節炎は治療がまったく異なり、関節液を見ずに治療を始めてはならない。

【誤答選択肢の解説】
B「膝関節造影CT」: 造影CTは膿瘍や骨破壊の評価には役立つが、起炎菌や結晶の有無は分からない。
C「下肢ギプス包帯固定」: 固定は診断がついた後の補助的手段で、原因の特定にならない。
D「広域抗菌薬の点滴静注」: 培養検体を採る前に広域抗菌薬を投与すると起炎菌の同定が困難になる。
E「副腎皮質ステロイドの関節内投与」: 化膿性関節炎であればステロイドの関節内投与は感染を悪化させる。診断前には行えない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D042（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-47', '正答は D「Lewy小体型認知症」。

具体的で反復する幻視、REM睡眠行動異常症を示唆する数年来の寝言や夜間の行動、半年前からの動作緩慢というパーキンソニズムが揃っており、Lewy小体型認知症の中核症状を満たす。見当識が保たれ礼節も保たれている点も矛盾しない。

【誤答選択肢の解説】
A「妄想性障害」: 妄想性障害では体系化した妄想が主体で、パーキンソニズムやREM睡眠行動異常症は説明できない。
B「血管性認知症」: 血管性認知症では脳血管障害の画像所見と階段状の経過、局所神経徴候を伴う。
C「前頭側頭型認知症」: 前頭側頭型認知症では脱抑制や常同行動が前景となり、幻視は稀である。
E「Alzheimer型認知症」: Alzheimer型認知症は近時記憶の障害が中核で、初期から幻視とパーキンソニズムが揃うことはない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D047（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-48', '正答は D「Fanconi症候群」。

シスプラチンは近位尿細管に毒性を示す。血糖が正常なのに尿糖が陽性(腎性糖尿)で、尿中β2-マイクログロブリンが著明に増加しているのは近位尿細管での再吸収障害を意味し、Fanconi症候群である。

【誤答選択肢の解説】
A「腎性尿崩症」: 腎性尿崩症では集合管がADHに反応せず、多尿と低張尿(尿比重の低下)をきたす。尿量1,200mL・比重1.014の本例と合わない。
B「Liddle症候群」: Liddle症候群は上皮性ナトリウムチャネルの機能亢進による遺伝性疾患で、高血圧と低カリウム性アルカローシスを示す。
C「Bartter症候群」: Bartter症候群はHenleループ上行脚の障害で、低カリウム性アルカローシスをきたすが尿細管性の糖尿は示さない。
E「Gitelman症候群」: Gitelman症候群は遠位尿細管の障害で、低カリウム血症と低マグネシウム血症が特徴である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D048（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-5', '正答は E「直腸子宮窩」。

直腸子宮窩(Douglas窩)は仰臥位で腹腔内の最も低い位置にあたり、術後の滲出液や血液が重力で貯留する。S状結腸切除のように骨盤内を操作した術後に膿瘍を形成しやすい。

【誤答選択肢の解説】
A「右横隔膜下」: 右横隔膜下は上腹部の手術後に膿瘍を作りやすい部位である。
B「左横隔膜下」: 左横隔膜下は脾摘後などで問題となる。
C「右傍結腸溝」: 右傍結腸溝は液体の通り道になるが、最終的には骨盤底に落ちる。
D「左傍結腸溝」: 左傍結腸溝も同様に貯留の最終地点にはなりにくい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-55', '正答は B「発達遅滞をきたす。」。

胎児発育不全、眼裂狭小と小下顎の特徴的顔貌、手指の重合(overlapping fingers)、揺り椅子状足底、筋緊張亢進は18トリソミー(Edwards症候群)の所見である。生存例では重度の発達遅滞をきたす。

【誤答選択肢の解説】
A「生命予後は良い。」: 18トリソミーの生命予後は不良で、多くが生後1年以内に死亡する。
C「心疾患は合併しにくい。」: 心室中隔欠損をはじめとする先天性心疾患を90%以上に合併する。
D「急性白血病を合併しやすい。」: 急性白血病を合併しやすいのは21トリソミー(Down症候群)である。
E「甲高い泣き声が特徴的である。」: 甲高い猫の鳴き声のような泣き声は5p欠失症候群(猫鳴き症候群)の特徴である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D055（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-56', '正答は B「吸入副腎皮質ステロイド薬」。

吸入副腎皮質ステロイド薬は気道の慢性炎症そのものを抑える治療の土台で、症状が消えても継続する。中止すると炎症が再燃して増悪や死亡のリスクが上がる。本例は好酸球10%と気道炎症の残存も示唆され、減薬するとしても最後まで残すべき薬剤である。

【誤答選択肢の解説】
A「テオフィリン徐放薬」: テオフィリンは有効血中濃度の幅が狭く、悪心・不整脈・けいれんなどの副作用もあるため、減薬では優先して外す。
C「吸入長時間作用性β2刺激薬」: 長時間作用性β2刺激薬は単独では使えず、症状が安定すれば吸入ステロイド単剤に戻すことができる。
D「吸入長時間作用性抗コリン薬」: 長時間作用性抗コリン薬は step-up のための追加薬で、コントロールが得られれば減らせる。
E「ロイコトリエン受容体拮抗薬」: ロイコトリエン受容体拮抗薬も追加治療の位置づけで、減薬の対象となる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D056（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-58', '正答は D「心拍数」。

母体のTSH受容体刺激抗体は胎盤を通過して児の甲状腺を刺激する。母体が服用していた抗甲状腺薬は児から速やかに消失するため、生後数日で新生児バセドウ病が顕在化する。頻脈が最も早く現れる徴候で、放置すると心不全に至る。

【誤答選択肢の解説】
A「血圧」: 血圧は新生児甲状腺機能亢進症の早期指標として鋭敏ではない。
B「尿量」: 尿量は循環動態を反映するが、甲状腺機能亢進の直接の指標ではない。
C「呼吸数」: 呼吸数は心不全が進めば増えるが、頻脈より遅れて現れる。
E「動脈血酸素飽和度」: 酸素飽和度の低下は心不全の進行を示すもので、早期発見の指標にならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D058（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-6', '正答は D「緑膿菌感染症 — セファゾリン」。

セファゾリンは第1世代セフェムで、緑膿菌には抗菌活性がない。緑膿菌にはセフタジジムやピペラシリン・タゾバクタム、カルバペネム、アミノグリコシドなど抗緑膿菌活性をもつ薬剤を用いる。

【誤答選択肢の解説】
A「オウム病 — ミノサイクリン」: オウム病(Chlamydia psittaci)にはテトラサイクリン系が第一選択で、正しい。
B「放線菌症 — アンピシリン」: 放線菌症にはペニシリン系の大量長期投与を行う。正しい。
C「ノカルジア症 — ST合剤」: ノカルジア症にはST合剤が第一選択である。正しい。
E「レジオネラ症 — レボフロキサシン」: レジオネラ症にはキノロン系やマクロライド系が有効である。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-60', '正答は D「リスペリドン」。

被害関係妄想(テレビが自分のことを流す、サインを送ってくる)と幻聴を疑わせる訴えがあり、感情表出の乏しさなど陰性症状も伴う。器質的疾患は除外されており統合失調症と考え、第二世代抗精神病薬であるリスペリドンを用いる。

【誤答選択肢の解説】
A「イミプラミン」: イミプラミンは三環系抗うつ薬で、うつ病に用いる。
B「炭酸リチウム」: 炭酸リチウムは双極症の気分安定薬である。
C「フェニトイン」: フェニトインは抗てんかん薬で、脳波に異常のない本例に適応はない。
E「カルバマゼピン」: カルバマゼピンは抗てんかん薬・気分安定薬で、統合失調症の第一選択にはならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D060（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-7', '正答は C「離脱症状にベンゾジアゼピン系薬を投与する。」。

アルコール離脱では中枢神経の過剰興奮が生じ、けいれんや振戦せん妄に至りうる。ベンゾジアゼピン系薬はアルコールと交叉耐性があり、これを予防・軽減する目的で用いる。

【誤答選択肢の解説】
A「入院治療が第一選択である。」: 外来での断酒治療が基本で、入院は重症の離脱や重い身体合併症、家庭環境の問題がある場合に選択する。
B「断酒会は匿名参加が原則である。」: 匿名参加を原則とするのはAA(Alcoholics Anonymous)である。断酒会は実名で家族とともに参加するのが特徴である。
D「脳症の予防としてビタミンDは有効である。」: Wernicke脳症の予防に必要なのはビタミンB1(チアミン)であり、ビタミンDではない。
E「患者に知らせずに抗酒薬を食事に混ぜて投与する。」: 本人に知らせずに薬を投与することは同意原則に反し、飲酒時の強い反応で危険でもある。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-8', '正答は C「子宮頸管ポリープ」。

子宮頸管ポリープは不正性器出血の原因となるが、妊娠の継続を妨げる病態ではなく流産との関連は知られていない。

【誤答選択肢の解説】
A「年齢」: 年齢が上がるほど卵子の染色体異常が増え、流産率は上昇する。
B「甲状腺機能低下症」: 甲状腺機能低下症は流産・早産のリスクを高め、妊娠前からの補充が必要となる。
D「抗リン脂質抗体症候群」: 抗リン脂質抗体症候群は胎盤の微小血栓により反復流産をきたす代表的な病態である。
E「転座型染色体異常の保因者」: 均衡型転座の保因者では不均衡型の配偶子が生じ、流産を繰り返す。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-D-9', '正答は A「咽頭」。

ヘルパンギーナはコクサッキーA群ウイルスによる夏かぜで、軟口蓋から口蓋弓にかけての咽頭後方に小水疱とアフタが多発する。高熱を伴い、疼痛のため摂食不良となる。

【誤答選択肢の解説】
B「手掌」: 手掌の水疱は手足口病の所見である。
C「足底」: 足底の水疱も手足口病でみられる。
D「体幹」: 体幹の発疹は水痘や麻疹などで、ヘルパンギーナの好発部位ではない。
E「外陰部」: 外陰部は手足口病で時に侵されるが、ヘルパンギーナの好発部位ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 D009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-1', '正答は B「患者本人の意思が確認できる場合は患者の意向を尊重する。」。

人生の最終段階における医療・ケアの決定プロセスに関するガイドラインでは、本人による意思決定を基本とする。本人の意思が確認できるならその意向を尊重し、繰り返し話し合って共有する。

【誤答選択肢の解説】
A「患者本人の意思が確認できない場合は家族の意向に従う。」: 意思が確認できないときも、家族の意向にそのまま従うのではなく、家族らとともに本人の推定意思を探ることが求められる。
C「患者が認知症の場合は患者本人の意思が確認できないと判断する。」: 認知症があっても意思決定能力は一律に失われるわけではなく、その時々の状態に応じて個別に評価する。
D「患者本人の意思決定能力の判断には精神科医の診察が必要となる。」: 意思決定能力の評価は主治医を含む医療・ケアチームが行うもので、精神科医の診察が必須ではない。
E「患者の配偶者と実子の意見が対立する場合は配偶者の意見を優先する。」: 家族間で意見が分かれた場合に優先順位はなく、多職種のチームで話し合い合意形成を図る。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-10', '正答は C「過多月経」。

筋層内筋腫が大きくなると子宮内腔の面積が増え、月経時の子宮収縮も妨げられるため出血量が増える。過多月経とそれによる鉄欠乏性貧血が代表的な症状である。

【誤答選択肢の解説】
A「片頭痛」: 片頭痛は血管・三叉神経系の病態で、子宮筋腫とは関係しない。
B「無排卵」: 排卵の有無は視床下部-下垂体-卵巣系が規定するもので、筋腫は関与しない。
D「希発月経」: 希発月経は排卵障害によるもので、筋腫では生じない。
E「月経前症候群」: 月経前症候群は黄体期のホルモン変動に伴う症候群であり、筋腫の有無とは独立である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-11', '正答は E「反跳痛〈rebound tenderness〉は手掌全体で押さえて確認する。」。

反跳痛は、指先で局所をゆっくり圧迫してから急に手を離し、離した瞬間の痛みをみる。手掌全体で押さえると圧痛の局在が分からず、患者に与える苦痛も大きい。

【誤答選択肢の解説】
A「患者の表情に注意する。」: 言葉で訴えない患者もいるため、表情の変化を観察することは重要である。正しい。
B「自発痛がない部位から始める。」: 痛みのない部位から始めることで、患者の緊張を減らし比較の基準も得られる。正しい。
C「打診で痛みを訴える部位には慎重に行う。」: 打診で痛みがある時点で腹膜刺激が疑われ、触診はより慎重にすべきである。正しい。
D「腹膜刺激が顕著な部位の触診は必要最小限にする。」: 腹膜刺激が明らかな部位を繰り返し触診しても情報は増えず、苦痛を与えるだけである。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-12', '正答は C「細菌検査の検体を採取後に抗菌薬を投与する。」。

抗菌薬を投与すると細菌が検出されにくくなるため、血液培養などの検体は投与前に採取する。起炎菌と感受性が分かれば、狭域薬への変更(de-escalation)が可能になる。

【誤答選択肢の解説】
A「解熱後はすぐに抗菌薬を中止する。」: 感染症ごとに必要な投与期間があり、解熱だけを基準に中止すると再燃する。
B「発熱のある患者には抗菌薬を投与する。」: 発熱の原因はウイルス感染や非感染性のことも多く、発熱そのものは抗菌薬の適応にならない。
D「感受性検査の結果によらず広域抗菌薬を継続する。」: 感受性が判明したら狭域薬へ変更するのが原則で、広域薬の漫然とした継続は耐性菌を生む。
E「解熱薬を併用することで抗菌薬の効果判定が容易になる。」: 解熱薬は発熱を抑えてしまい、抗菌薬が効いているかどうかの判定をかえって難しくする。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E012（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-14', '正答は C「データを自分の仮説に合うように改ざんする。」。

データを仮説に合うように書き換えることは改ざんであり、捏造・盗用と並ぶ研究不正の中核である。研究そのものの信頼を失わせ、患者に害を及ぼしうる。

【誤答選択肢の解説】
A「発表内容に関する利益相反を公表する。」: 利益相反の公表は求められる行為で、倫理に反しない。
B「患者の個人情報を特定できないようにする。」: 個人が特定されないようにすることは守秘義務上必要な配慮である。
D「自分が経験した複数の症例をまとめた内容を発表する。」: 自験例をまとめて発表することは通常の学術活動である。
E「医療機器メーカーから研究助成を受けた研究結果を発表する。」: 企業から助成を受けた研究でも、利益相反を開示したうえで発表することは問題ない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E014（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-15', '正答は A「職種独自の略語を使用する。」。

職種の内輪でしか通じない略語は、他職種に意味が伝わらないだけでなく誤解を生み、患者の安全を損なう。チーム内では共通の言葉を使う。

【誤答選択肢の解説】
B「患者の家族の希望を傾聴する。」: 家族の希望を聴くことは、患者中心のケアを組み立てるうえで欠かせない。
C「他職種からの意見を尊重する。」: 他職種の意見を尊重する姿勢はチーム医療の前提である。
D「各職種の専門性が確立している。」: 各職種の専門性が確立していることは、役割分担を可能にする条件である。
E「他職種の役割や機能を理解する。」: 他職種の役割と機能を理解していれば、適切な依頼と連携ができる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E015（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-16', '正答は A「貧血の影響を受ける。」。

HbA1cは赤血球の寿命に依存するため、貧血の影響を受ける。溶血や出血で赤血球寿命が短縮すると低値になり、未治療の鉄欠乏性貧血では高値に傾く。数値の解釈には血算を併せて見る必要がある。

【誤答選択肢の解説】
B「グルコース以外の糖類も影響する。」: HbA1cはグルコースがヘモグロビンのβ鎖N末端に結合したもので、他の糖は反映しない。
C「過去1〜2週間の血糖状況を反映する。」: 反映するのは過去1〜2か月の平均血糖である。1〜2週間を反映するのはグリコアルブミンである。
D「赤血球内の酵素反応により形成される。」: 酵素を介さない非酵素的な糖化反応によって生じる。
E「我が国のメタボリックシンドロームの診断基準に含まれている。」: 我が国のメタボリックシンドロームの診断基準は腹囲に加えて血圧・血糖(空腹時)・脂質で、HbA1cは含まれない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E016（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-17', '正答は D「症例数の設定のためには治療効果の推定が必要である。」。

必要な症例数は、検出したい治療効果の大きさ、有意水準、検出力から算出する。したがって設計段階で治療効果を推定しておく必要がある。

【誤答選択肢の解説】
A「二重盲検は必須である。」: 外科手技やリハビリテーションなど盲検化が困難な介入もあり、二重盲検は必須ではない。
B「プラセボは現在では使用が禁止されている。」: 有効性が確立した標準治療がない領域ではプラセボ対照は倫理的に許容される。禁止されてはいない。
C「ランダム割付は症例数を少なくするために行われる。」: ランダム割付の目的は既知・未知の交絡因子を群間で均等にすることであり、症例数を減らすためではない。
E「Intentiontotreat〈ITT〉による解析は実際に行った治療に基づいて行われる。」: ITT解析は実際に受けた治療ではなく、割り付けられたとおりに解析する方法である。実際の治療に基づくのはper protocol解析やas treated解析である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-18', '正答は B「大村智 — マラリアに対する新たな治療法の発見」。

大村智の受賞理由は、線虫による寄生虫感染症(オンコセルカ症・リンパ系フィラリア症)に対する新規治療法の発見で、イベルメクチンの基となるエバーメクチンの発見による。マラリアに対する治療法(アルテミシニン)の発見で同時受賞したのは屠呦呦である。

【誤答選択肢の解説】
A「大隅良典 — オートファジーの仕組みの解明」: 大隅良典はオートファジーの仕組みの解明で2016年に受賞した。正しい。
C「利根川進 — 抗体の多様性に関する遺伝的原理の発見」: 利根川進は抗体の多様性が生まれる遺伝的原理の発見で1987年に受賞した。正しい。
D「本庶佑 — 免疫チェックポイント分子の発見」: 本庶佑は免疫チェックポイント分子PD-1の発見と癌治療への応用で2018年に受賞した。正しい。
E「山中伸弥 — 成熟した細胞のリプログラミングによる多能性の獲得」: 山中伸弥は成熟細胞の初期化による多能性獲得(iPS細胞)で2012年に受賞した。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E018（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-19', '正答は A「脂肪腫」。

脂肪腫は皮下に存在する腫瘍で、その上の表皮は正常である。したがって触診では表面が平滑で、柔らかく可動性のある腫瘤として触れる。

【誤答選択肢の解説】
B「Bowen病」: Bowen病は表皮内癌で、角化を伴う紅色局面として鱗屑を付け表面はざらつく。
C「尋常性疣贅」: 尋常性疣贅は表面が粗糙で乳頭状に隆起し、点状の黒色(血栓化した毛細血管)を伴う。
D「脂漏性角化症」: 脂漏性角化症は表面が疣状・顆粒状で、脂ぎった感触を示す。
E「ケラトアカントーマ」: ケラトアカントーマは中央に角栓を有する火山状の結節で、表面は平滑ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-2', '正答は D「麻酔薬の注射後、疼痛の有無を確認してから処置を行う。」。

局所麻酔薬を注射した後は、切開する前に疼痛の有無を確認して効果が得られていることを確かめる。効いていないまま処置を始めると強い苦痛を与える。

【誤答選択肢の解説】
A「麻酔薬の注射には18G針を使用する。」: 18Gは太く刺入時の痛みが強い。局所麻酔には25〜27Gの細い針を用いる。
B「滅菌シーツの穴より狭い範囲で消毒する。」: 消毒は滅菌ドレープの穴より広い範囲に行う。狭いと清潔野の縁が汚染される。
C「ポビドンヨードを塗布後、直ちに処置を行う。」: ポビドンヨードは乾燥する過程で殺菌力を発揮するため、2分程度待ってから処置する。
E「注射針を刺入し血液逆流があることを確認してから麻酔薬を注入する。」: 血液の逆流が「ない」ことを確認してから注入する。逆流があれば血管内であり、局所麻酔薬中毒の危険がある。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-20', '正答は E「25%アルブミン液」。

25%アルブミン液は血漿より浸透圧が高い高張液で、投与すると膠質浸透圧により組織間から血管内へ水を引き込む。循環血漿量を増やす目的で用いる。

【誤答選択肢の解説】
A「生理食塩液」: 生理食塩液は0.9%塩化ナトリウム液で、血漿とほぼ等張である。
B「5%ブドウ糖液」: 5%ブドウ糖液は投与時点では等張だが、糖が代謝されて自由水が残るため細胞内へも分布する。等張液に分類される。
C「酢酸リンゲル液」: 酢酸リンゲル液は電解質組成を血漿に近づけた等張の細胞外液補充液である。
D「乳酸リンゲル液」: 乳酸リンゲル液も同様に等張の細胞外液補充液である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E020（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-21', '正答は A「GH」。

成長ホルモンは血糖の上昇によって分泌が抑制されるため、食後に低下する。逆に空腹・睡眠・運動・低血糖で分泌が高まる。この性質を利用して、先端巨大症の診断には75g経口ブドウ糖負荷試験でGHが抑制されないことを確認する。

【誤答選択肢の解説】
B「インスリン」: インスリンは食後の血糖上昇に応じて分泌が増える。
C「グルコース」: 血糖は食後に上昇する。
D「トリグリセリド」: トリグリセリドは食事由来のカイロミクロンにより食後に上昇する。
E「遊離サイロキシン〈FT4〉」: 遊離サイロキシンは食事による短期的な変動を示さない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E021（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-22', '正答は B「腎不全」。

観察研究のアウトカムには、患者にとって意味のある事象を置く。糖尿病腎症の腎機能予後を問うなら、透析導入を要する腎不全という真のアウトカムが臨床的に最も重要である。

【誤答選択肢の解説】
A「HbA1c」: HbA1cは血糖管理の指標であって、腎機能の予後そのものではない。
C「蛋白尿」: 蛋白尿は腎不全への進行を予測する代替アウトカムで、真のアウトカムには及ばない。
D「下腿浮腫」: 下腿浮腫は腎機能以外の要因でも生じ、腎機能予後の指標としては不適切である。
E「病理所見」: 病理所見は病態の理解には有用だが、患者にとっての帰結を直接表すものではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-23', '正答は B「嚥下機能」。

言語聴覚士は言語・構音・音声・聴覚に加えて摂食嚥下を担当する。脳梗塞後は嚥下障害の頻度が高く、誤嚥性肺炎の予防のため嚥下機能の評価と訓練を行う。

【誤答選択肢の解説】
A「見当識」: 見当識を含む認知機能の評価は医師や公認心理師が担うことが多い。
C「巧緻運動」: 手指の巧緻運動や日常生活動作の訓練は作業療法士の領域である。
D「四肢筋力」: 四肢筋力の評価と基本動作の訓練は理学療法士の領域である。
E「心理状態」: 心理状態の評価と支援は公認心理師や精神科医が担う。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E023（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-24', '正答は C「心電図検査」。

失神ではまず心原性失神を除外する。不整脈、QT延長、Brugada症候群、心筋虚血など突然死につながる病態を心電図で拾えるため、血糖測定とともに直ちに施行する。

【誤答選択肢の解説】
A「脳波検査」: けいれんを伴わない失神でてんかんの頻度は低く、脳波は初期検査として優先度が低い。
B「頸椎MRI」: 頸椎の病変は失神の原因とならない。
D「頸動脈エコー検査」: 頸動脈狭窄は脳梗塞の危険因子だが、それ自体で失神をきたすことは稀である。
E「胸部エックス線撮影」: 胸部エックス線写真は補助的で、失神の致死的原因を直接拾えない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-25', '正答は C「水痘帯状疱疹ウイルス」。

麻疹は空気(飛沫核)感染するため、陰圧個室とN95マスクによる空気予防策を要する。同じ空気予防策が必要なのは水痘帯状疱疹ウイルスと結核菌である。

【誤答選択肢の解説】
A「A群レンサ球菌」: A群レンサ球菌は飛沫予防策の対象である。
B「ムンプスウイルス」: ムンプスウイルスも飛沫予防策の対象である。
D「多剤耐性緑膿菌〈MDRP〉」: 多剤耐性緑膿菌は接触予防策の対象である。
E「メチシリン耐性黄色ブドウ球菌〈MRSA〉」: メチシリン耐性黄色ブドウ球菌も接触予防策の対象である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-26', '正答は B「血液培養」。

アトピー性皮膚炎の搔破で皮膚のバリアが破綻したところから細菌が侵入し、菌血症をきたしている。悪寒戦慄を伴う発熱に加え、血圧86/58mmHg、頻脈、頻呼吸と敗血症の徴候が揃っており、抗菌薬を開始する前に血液培養を2セット採取する。

【誤答選択肢の解説】
A「尿培養」: 頻尿も排尿時痛もなく背部叩打痛もないため、尿路感染を第一に疑う根拠がない。
C「喀痰Gram染色」: 咳・痰がなく呼吸音も正常で、喀痰を採取できる状況でも肺炎を示唆する状況でもない。
D「麻疹抗体価測定」: 皮疹はアトピー性皮膚炎による紅斑・鱗屑・搔破痕であり、麻疹の発疹の経過とは異なる。
E「インフルエンザ迅速検査」: 上気道症状がなく周囲に同様の症状の人もおらず、インフルエンザを疑う状況ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E026（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-27', '正答は E「バッグバルブマスクによる人工呼吸」。

新生児蘇生では、初期処置(保温・気道確保・皮膚刺激)の後に自発呼吸がないか心拍が100/分未満であれば、直ちにバッグバルブマスクによる人工呼吸を開始する。本例は心拍110/分だが自発呼吸がないため、人工呼吸の適応である。

【誤答選択肢の解説】
A「気管挿管」: 気管挿管はマスク換気で有効な換気が得られない場合や胸骨圧迫を要する場合に考慮する。
B「胸骨圧迫」: 胸骨圧迫は有効な人工呼吸を30秒行っても心拍が60/分未満のときに開始する。心拍110/分では適応がない。
C「生理食塩液の静脈内投与」: 生理食塩液の急速投与は循環血液量減少が疑われるときの処置である。
D「アドレナリンの静脈内投与」: アドレナリンは十分な換気と胸骨圧迫を行っても心拍が60/分未満のときに用いる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E027（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-28', '正答は E「常位胎盤早期剝離」。

妊娠高血圧腎症と喫煙という危険因子があり、激しい腹痛、板状硬の子宮、胎盤の著明な肥厚(後血腫)、基線細変動の減少と遅発一過性徐脈という胎児機能不全が揃っている。常位胎盤早期剝離で、外出血が少量でも出血の大半は子宮内に貯留する。母児ともに危険で緊急帝王切開を要する。

【誤答選択肢の解説】
A「切迫早産」: 切迫早産では規則的な子宮収縮と頸管の熟化がみられるが、子宮が板状に硬くなることはない。
B「切迫流産」: 切迫流産は妊娠22週未満の概念で、妊娠34週の本例には当てはまらない。
C「前置胎盤」: 前置胎盤は無痛性の性器出血が特徴で、本例は胎盤が子宮底部にあり位置も合わない。
D「絨毛膜羊膜炎」: 絨毛膜羊膜炎では発熱と子宮の圧痛、破水を伴うが、本例は体温36.9°Cで感染徴候がない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E028（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-3', '正答は D「医療安全支援センターの業務は医療法に規定されている。」。

医療安全支援センターは医療法第6条の13に基づき都道府県・保健所設置市・特別区に設置され、患者からの苦情・相談への対応や情報提供を行う。

【誤答選択肢の解説】
A「予防接種の実施主体は教育委員会である。」: 定期予防接種の実施主体は市町村である。
B「地方衛生研究所は主に対人サービスを行う。」: 地方衛生研究所は検査・研究を担う対物サービスの機関で、対人サービスは行わない。
C「地域包括支援センターの設置主体は都道府県である。」: 地域包括支援センターの設置主体は市町村である。
E「地域保健センターには必ず医師を置かなければならない。」: 市町村保健センターに医師を必ず置くという規定はない。医師であることが求められるのは保健所長である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-31', '正答は C「9点」。

開眼は痛み刺激で開くのでE2、発語はうなり声のみで意味のある言葉がないためV2、運動は左上下肢が痛み刺激を払いのける(localizing)ためM5。合計9点となる。運動反応は左右で良いほうを採用する。

【誤答選択肢の解説】
A「3点」: 3点は開眼・発語・運動のすべてが最低(E1V1M1)で、深昏睡の状態である。
B「6点」: 6点は運動反応をM2〜M3と誤って評価した場合の値である。
D「12点」: 12点は呼びかけで開眼(E3)し発語も保たれる場合の値で、本例より軽い。
E「15点」: 15点は完全に清明な状態である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E031（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-32', '正答は E「喫煙量を戻すように指導する。」。

喫煙本数を減らしてイライラが強まっているのはニコチン離脱症状で、依存が形成されている証拠である。喫煙量を戻すよう指導するのは依存を維持させるだけで、支援として誤っている。禁煙治療につなぐべき場面である。

【誤答選択肢の解説】
A「喫煙状況を把握する。」: 現在の喫煙状況とニコチン依存度の把握は支援の出発点である。
B「禁煙外来を紹介する。」: ニコチン依存が明らかで、禁煙外来での薬物療法を含む治療につなぐのは適切である。
C「喫煙の危険性を説明する。」: 健康被害を具体的に伝えることは行動変容の動機づけになる。
D「禁煙の重要性を説明する。」: 禁煙が本人にとってなぜ重要かを伝えることは短時間支援の要素である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E032（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-33', '正答は E「腰椎穿刺」。

発熱・頭痛・頻回の嘔吐があり、jolt accentuation(頭を左右に振ると頭痛が増強する)が陽性である。項部硬直やKernig徴候がなくても髄膜炎は否定できず、髄液検査で確定させる必要がある。

【誤答選択肢の解説】
A「尿培養」: 排尿時痛も背部叩打痛もなく尿所見も正常で、尿路感染を疑う根拠がない。
B「便培養」: 下痢や腹痛の記載がなく、腸管感染を疑う状況ではない。
C「咽頭培養」: 咽頭痛がなく咽頭炎を示す所見もない。
D「喀痰培養」: 咳嗽がなく呼吸音も正常で、喀痰を採取する状況ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E033（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-34', '正答は D「地域包括支援センターに相談するよう説明する。」。

本人が問題を認めず受診も拒んでいる段階で、まず必要なのは家族への支援と地域資源へのつなぎである。地域包括支援センターは高齢者と家族の総合相談窓口として、こうした事例の相談先になる。

【誤答選択肢の解説】
A「直ちに警察に通報する。」: 差し迫った暴力や生命の危険がある状況の記載はなく、いきなり通報すると家族関係を壊しかねない。
B「精神科受診のための紹介状を作成する。」: 本人が受診を拒んでいるため、紹介状を用意しても受診にはつながらない。
C「夫に直接連絡し、禁酒するよう説得する。」: 診療関係のない相手に医師が直接連絡して説得することは、本人の反発を招き逆効果になりやすい。
E「地域の在宅医に連絡し、夫に対する訪問診療を依頼する。」: 訪問診療は本人の同意なしには導入できない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E034（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-37', '正答は A「仰臥位で診察する。」。

直腸肛門指診は左側臥位(Sims位)または砕石位で行う。仰臥位では肛門部の視診も指の挿入も行いにくく、患者の負担も大きい。

【誤答選択肢の解説】
B「手袋を着用する。」: 手袋の着用は感染対策として必須である。正しい。
C「肛門周囲を視診する。」: 痔核・裂肛・瘻孔などは視診で分かることが多く、指診の前に必ず観察する。正しい。
D「示指に潤滑剤を塗り肛門内に挿入する。」: 潤滑剤を用いてゆっくり挿入することで疼痛と粘膜損傷を避ける。正しい。
E「直腸内腔や肛門管内の触診をする。」: 直腸内腔と肛門管の触診により腫瘤や狭窄、前立腺の性状を評価する。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E037（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-39', '正答は B「抗コリン薬」。

残尿240mLと著明な排出障害があり、国際前立腺症状スコアも重症域である。この状態で抗コリン薬を用いると排尿筋の収縮がさらに弱まり尿閉を招く危険が高い。過活動膀胱症状の治療は、まず排出障害を改善してから検討する。

【誤答選択肢の解説】
A「α1遮断薬」: α1遮断薬は前立腺平滑筋の緊張を下げて尿道抵抗を減らす、前立腺肥大症の第一選択薬である。
C「抗男性ホルモン薬」: 抗男性ホルモン薬は前立腺を縮小させる目的で用いられる。
D「5α還元酵素阻害薬」: 5α還元酵素阻害薬は推定体積60mLと腫大した前立腺を縮小させ、長期的な進行を抑える。
E「PDE5〈phosphodiesterase5〉阻害薬」: タダラフィルは前立腺肥大症に伴う排尿障害に保険適応がある。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E039（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-4', '正答は D「「心配し過ぎるあなたの性格に問題があるように思います」」。

「心配し過ぎる性格に問題がある」という言葉は、患者の訴えを性格のせいにして責めるもので、信頼関係を損ない受診の継続も妨げる。不安の背景を探る機会も失われる。

【誤答選択肢の解説】
A「「あなたの気持ちを聞かせてください」」: 感情の表出を促す開かれた問いで、適切である。
B「「どのような病気を心配されていますか」」: 患者が何を恐れているのかという解釈モデルを尋ねるもので、適切である。
C「「異常を認めないと言われても不安があるのですね」」: 患者の感情を言葉にして返す共感的応答で、適切である。
E「「不安をお持ちでしょうが、それでもよく頑張っていますね」」: 努力を認めて支える支持的な言葉で、適切である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-40', '正答は A「輸液」。

アルコール性肝硬変を背景とした食道静脈瘤破裂による大量吐血で、血圧88/68mmHg、頻脈、冷汗と出血性ショックの状態にある。太い静脈路を確保して急速輸液を開始し、輸血の準備を進めることが最優先である。止血処置はその後である。

【誤答選択肢の解説】
B「胃管留置」: 胃管は出血の程度を知る助けになるが、循環を立て直すことが先で、静脈瘤破裂では挿入自体が出血を助長しうる。
C「腹腔穿刺」: 腹水の診断的穿刺は緊急性がなく、ショックの是正が優先される。
D「AED装着」: 意識があり脈も触れており、AEDの適応はない。
E「尿道カテーテル留置」: 尿量のモニタリングは必要だが、まず行うべき処置ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E040（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-5', '正答は E「瞳孔径の左右差」。

瞳孔径の左右差(瞳孔不同)は、鉤ヘルニアにより動眼神経が圧迫されていることを示す。脳ヘルニアが切迫している徴候で、直ちに画像評価と頭蓋内圧管理を要する。

【誤答選択肢の解説】
A「眼脂」: 眼脂は結膜炎などの所見で、緊急性はない。
B「翼状片」: 翼状片は結膜の増殖性変化で、慢性の所見である。
C「眼球結膜の出血」: 眼球結膜下出血は自然に吸収され、それ自体は緊急性がない。
D「眼瞼結膜の充血」: 眼瞼結膜の充血は結膜炎などを示すもので、意識障害の原因評価では優先度が低い。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-6', '正答は B「PM2.5はタバコの煙に含まれている。」。

タバコの煙には粒径2.5μm以下の微小粒子状物質(PM2.5)が大量に含まれ、屋内の受動喫煙環境ではしばしば大気汚染の基準値をはるかに超える濃度になる。

【誤答選択肢の解説】
A「喫煙の依存性はタールが原因である。」: 依存性の本体はニコチンである。タールは発癌物質を含む成分である。
C「屋内の分煙により受動喫煙を防止できる。」: 煙は空間を越えて拡散し、換気や分煙では受動喫煙を防ぎきれない。屋内の全面禁煙が必要である。
D「喫煙による発癌はニコチンが主因である。」: 発癌の主因はタールに含まれる多環芳香族炭化水素やニトロソアミンなどである。
E「禁煙すれば肺癌死亡率は非喫煙者と同じになる。」: 禁煙により肺癌のリスクは着実に低下するが、長期の禁煙後も非喫煙者と同じ水準までは下がらない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-8', '正答は C「輸血製剤の放射線照射が予防に有効である。」。

輸血後移植片対宿主病は、輸血製剤中の生きたドナーリンパ球が受血者の組織を攻撃して起こる。放射線照射でリンパ球を不活化することが確実な予防法で、我が国ではほぼすべての輸血用血液が照射されている。

【誤答選択肢の解説】
A「輸血後6時間以内に発症する。」: 発症は輸血の1〜2週後で、6時間以内ではない。6時間以内に起こるのは輸血関連急性肺障害などである。
B「新鮮血と比較して保存血で起こりやすい。」: リンパ球が生存している新鮮血のほうが起こりやすい。保存により生着能は低下する。
D「初回と比較して複数回の輸血後に起こりやすい。」: 初回輸血でも発症しうる。輸血回数との関連はない。
E「血縁者と比較して非血縁者からの供血で起こりやすい。」: HLAハプロタイプが一方向に適合する血縁者からの供血で起こりやすい。このため血縁者からの輸血は避ける。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-E-9', '正答は E「黄色泡沫状腟分泌」。

黄色泡沫状の腟分泌物はトリコモナス腟炎に特徴的な所見で、感染症によるものである。月経周期に伴うホルモン変動とは関係しない。

【誤答選択肢の解説】
A「体重」: 黄体期にはプロゲステロンの作用で水分が貯留し、体重がわずかに増える。
B「中間期出血」: 排卵期にエストロゲンが一過性に低下することで中間期出血が起こる。
C「乳房緊満感」: 乳房の緊満感は黄体期のプロゲステロンによるもので、月経開始とともに軽快する。
D「透明な頸管粘液」: 排卵期にはエストロゲンの作用で頸管粘液が増量し、透明で牽糸性が高くなる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 E009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-1', '正答は D「大腸菌が10 コロニー/mL 以下」。

水道水の水質基準では、大腸菌は「検出されないこと」と定められている。何コロニーまで許容という基準ではない。

【誤答選択肢の解説】
A「濁度は2度以下」: 濁度は2度以下と定められている。正しい。
B「味は異常でないこと」: 味は異常でないことと定められている。正しい。
C「pH 値は5.8 以上8.6 以下」: pH値は5.8以上8.6以下である。正しい。
E「一般細菌が100 コロニー/mL 以下」: 一般細菌は1mLの検水で形成される集落数が100以下と定められている。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-12', '正答は B「血清FSH」。

閉経に伴い卵巣からのエストロゲンとインヒビンの分泌が低下すると、負のフィードバックが外れて下垂体からのFSH分泌が増える。高齢女性でFSHが高値になるのはこのためである。

【誤答選択肢の解説】
A「肺活量」: 肺活量は加齢に伴い低下する。
C「血清アルブミン」: 血清アルブミンは加齢とともにやや低下する。
D「血清クレアチンキナーゼ」: 血清クレアチンキナーゼは筋量の減少に伴い低下する。
E「クレアチニンクリアランス」: クレアチニンクリアランスは糸球体濾過量の生理的低下により減少する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F012（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-13', '正答は D「被虐待児の一時保護を行う。」。

児童相談所は児童福祉法に基づき、虐待を受けた児童の一時保護を行う権限をもつ。保護者の同意がなくても所長の判断で実施できる。

【誤答選択肢の解説】
A「国の機関である。」: 設置主体は都道府県と指定都市などであり、国の機関ではない。
B「療育の指導を行う。」: 療育の指導は保健所の業務として法に定められている。
C「乳児健康診査を実施する。」: 乳幼児健康診査の実施主体は市町村である。
E「所長は医師でなければならない。」: 所長が医師でなければならないという規定はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F013（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-14', '正答は B「医師の指示を受けて業務を行う。」。

訪問看護は主治医が交付する訪問看護指示書に基づいて提供される。看護師の判断だけで開始できるものではない。

【誤答選択肢の解説】
A「事業者は医療法人に限られる。」: 訪問看護ステーションの開設主体は医療法人に限られず、営利法人や社会福祉法人なども可能である。
C「人工呼吸器の在宅管理は業務ではない。」: 在宅人工呼吸器の管理は訪問看護の重要な業務に含まれる。
D「介護保険による訪問回数は、原則週1回までである。」: 介護保険の訪問看護に原則週1回という回数制限はない。
E「介護保険が適用される場合、訪問看護の自己負担は3割である。」: 介護保険が適用される場合の自己負担は原則1割で、所得により2〜3割となる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F014（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-17', '正答は E「ピークフロー」。

ピークフロー(最大呼気流量)は気道の可逆的な狭窄を反映し、早朝に低下する日内変動(morning dip)を示す。変動が大きいことは喘息のコントロール不良を意味し、自己管理の指標として用いられる。

【誤答選択肢の解説】
A「残気量」: 残気量は発作時に増加するが、日内変動の指標としては用いない。
B「肺活量」: 肺活量は気道狭窄の影響を受けにくく、日内変動を示さない。
C「肺拡散能」: 肺拡散能は肺胞毛細血管でのガス交換能を反映し、喘息では通常正常で日内変動もない。
D「1回換気量」: 1回換気量は呼吸パターンで変わるが、気道狭窄の日内変動を表す指標ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-18', '正答は C「就寝時にベッド柵で囲む。」。

高齢者虐待防止法が定める養護者による虐待は、身体的虐待・介護等放棄・心理的虐待・性的虐待・経済的虐待の5類型である。転倒防止のためのベッド柵は安全確保の措置であり、この類型に該当しない。

【誤答選択肢の解説】
A「食事の提供を拒絶する。」: 必要な食事を与えないことは介護等放棄(ネグレクト)にあたる。
B「わいせつな行為をする。」: わいせつな行為は性的虐待にあたる。
D「排泄物の処理を拒絶する。」: 排泄物を放置することは介護等放棄にあたる。
E「本人の財産を許諾なく処分する。」: 本人の財産を無断で処分することは経済的虐待にあたる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F018（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-19', '正答は D「虚血性心疾患」。

高所得国では感染症や周産期の死亡が減り、非感染性疾患が死因の上位を占める。虚血性心疾患は高所得国の死因第1位である。

【誤答選択肢の解説】
A「交通事故」: 交通事故は低・中所得国で相対的に上位を占める。
B「下痢性疾患」: 下痢性疾患は衛生環境と関連し、低所得国で上位に入る。
C「下気道感染症」: 下気道感染症は低所得国の主要死因である。
E「新生児仮死および出生時損傷」: 新生児仮死および出生時損傷は周産期医療の整備が不十分な低所得国で上位となる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-2', '正答は B「司法解剖には遺族の承諾は必要ない。」。

司法解剖は犯罪との関連が疑われる場合に、刑事訴訟法に基づき裁判官の発する鑑定処分許可状によって行われる。遺族の承諾は必要としない。

【誤答選択肢の解説】
A「死体検案は警察が行う。」: 死体検案は医師が行うものである。警察は検視を行う。
C「行政解剖には遺族の承諾が必要である。」: 監察医制度のある地域では、行政解剖を遺族の承諾なく行うことができる。
D「最終診察から24 時間以内であれば死体検案は必要ない。」: 医師法第20条ただし書きは死亡診断書の交付に関する規定であって、検案の要否を定めたものではない。診療中の傷病と異なる原因が疑われれば検案が必要である。
E「死体検案で異状が認められる場合の届出義務は医療法で規定されている。」: 異状死体の届出義務を定めているのは医師法第21条であり、医療法ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-20', '正答は E「周産期死亡とはすべての死産に早期新生児死亡を加えたものである。」。

周産期死亡は「妊娠22週以後の死産」に早期新生児死亡を加えたものと定義される。すべての死産を含むわけではない。死産の法的定義(妊娠12週以後)とは区切りが異なる点が問われている。

【誤答選択肢の解説】
A「乳児死亡とは生後1年未満の死亡である。」: 乳児死亡は生後1年未満の死亡で、正しい。
B「新生児死亡とは生後4週未満の死亡である。」: 新生児死亡は生後4週(28日)未満の死亡で、正しい。
C「死産とは妊娠12 週以後の死児の出産である。」: 死産は死産の届出に関する規程により妊娠12週以後の死児の出産と定められている。正しい。
D「早期新生児死亡とは生後1週未満の死亡である。」: 早期新生児死亡は生後1週(7日)未満の死亡で、正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F020（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-21', '正答は D「転倒防止のための住宅改修に利用できる。」。

介護保険の居宅サービスには住宅改修費の支給が含まれ、手すりの設置や段差の解消など転倒防止のための改修に利用できる(支給限度基準額20万円)。

【誤答選択肢の解説】
A「保険者は都道府県である。」: 保険者は市町村および特別区である。
B「被保険者は65 歳以上に限定される。」: 40歳以上65歳未満の第2号被保険者も、特定疾病による要介護状態であれば給付を受けられる。
C「介護給付費は国民医療費に含まれる。」: 介護給付費は国民医療費には含まれない。
E「自己負担割合は所得にかかわらず1割である。」: 自己負担割合は原則1割だが、一定以上の所得がある場合は2割または3割となる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F021（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-22', '正答は E「流行性耳下腺炎」。

証明書にはHib、肺炎球菌、B型肝炎、DPT-IPV、BCG、麻疹風疹混合、水痘の記載がある。流行性耳下腺炎(ムンプス)ワクチンだけが記録になく、これは我が国では定期接種に含まれない任意接種であることが背景にある。

【誤答選択肢の解説】
A「水痘」: 水痘はVaricella 1st・2ndとして接種済みである。
B「麻疹」: 麻疹はMeasles, Rubella 1stとして接種済みである。
C「百日咳」: 百日咳はDPT-IPVに含まれ、4回接種済みである。
D「肺炎球菌」: 肺炎球菌はPneumococcalとして4回接種済みである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-24', '正答は C「国民医療費の総額は40 兆円を超えている。」。

平成28年度の国民医療費は約42.1兆円で、40兆円を超えている。国民所得に対する比率は約11%である。

【誤答選択肢の解説】
A「予防接種の費用を含む。」: 予防接種や健康診断、正常分娩、美容整形など保険診療の対象外の費用は国民医療費に含まれない。
B「生活保護による医療扶助費は含まれない。」: 生活保護の医療扶助費は国民医療費に含まれる。
D「65 歳以上の入院医療費が50 % 以上を占める。」: 65歳以上の医療費は全体の約6割を占めるが、そのうち入院分に限れば全体の50%には達しない。
E「受診1日あたりの単価が最も高いのは75 歳以上の入院医療費である。」: 1日あたりの単価は高度医療を要する若年層の入院のほうが高く、75歳以上の入院が最高というわけではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-37', '正答は A「抗凝固薬の投与」。

75歳・高血圧という脳梗塞の危険因子をもつ心房細動で、CHADS2スコアは2点となる。自覚症状がなくても心原性脳塞栓症の予防が最優先で、抗凝固薬(直接経口抗凝固薬またはワルファリン)を開始する。

【誤答選択肢の解説】
B「t-PA の点滴静注」: t-PAは急性期脳梗塞に対する血栓溶解療法で、脳梗塞を発症していない本例に適応はない。
C「ペースメーカー留置」: 徐脈や房室ブロックはなく、ペースメーカーの適応がない。
D「カルディオバージョン」: 無症状で心拍数も許容範囲であり、除細動を急ぐ理由がない。行うとしても抗凝固を先行させる必要がある。
E「カテーテルアブレーション」: アブレーションは症状が強く薬物治療で抑えられない例に検討するもので、まず行う対応ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F037（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-38', '正答は E「「夜間の決めた時間に起こして排尿させましょう」」。

夜間に決まった時刻に起こして排尿させる方法は、睡眠を妨げるうえ夜尿の改善につながらないことが分かっており、現在は勧められていない。

【誤答選択肢の解説】
A「「就寝前に完全に排尿させましょう」」: 就寝前に膀胱を空にしておくことは基本的な生活指導で、適切である。
B「「睡眠中の冷えから身体を守りましょう」」: 冷えは膀胱容量を小さくするため、保温は生活指導として適切である。
C「「水分は昼過ぎまでに多めに摂らせましょう」」: 夕方以降の水分を控え、日中に多めに摂らせるのは適切な指導である。
D「「おねしょをしても叱らないようにしましょう」」: 叱責は子どもの自尊心を傷つけ改善にもつながらないため、叱らないよう伝えるのは適切である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F038（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-39', '正答は D「臓器障害の全身管理が可能な医療施設に緊急に転院させる。」。

クレゾールはフェノール系の化合物で、皮膚から吸収されて肝障害・腎障害・溶血・メトヘモグロビン血症・中枢神経抑制をきたす。下半身の広範囲に曝露しており、局所の創処置だけでは足りない。全身管理のできる施設へ緊急に搬送する。

【誤答選択肢の解説】
A「これ以上の処置は不要である。」: 経皮吸収による全身毒性が起こりうるため、処置を終えて帰すことはできない。
B「翌日皮膚科を受診することを患者に勧める。」: 翌日まで待つ間に肝腎障害や溶血が進行する危険がある。
C「疼痛時に服用するようNSAID を処方し帰宅させる。」: 鎮痛だけを行って帰宅させると全身毒性を見逃す。
E「抗菌薬を処方して、悪化すれば再度受診するように伝える。」: 問題は感染ではなく化学物質の全身毒性である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F039（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-4', '正答は D「経食道心エコー検査」。

経食道心エコーは探触子を食道内に置くため心臓との距離が近く、経胸壁心エコーでは捉えられない小さな疣贅や弁周囲膿瘍、人工弁の病変も描出できる。感染性心内膜炎を疑って経胸壁で所見がない場合も、経食道で確認する。

【誤答選択肢の解説】
A「心臓MRI」: 心臓MRIは心筋の性状評価には優れるが、可動する小さな疣贅の描出には向かない。
B「胸部造影CT」: 造影CTは塞栓や膿瘍の検索には有用だが、疣贅の検出感度はエコーに劣る。
C「経胸壁心エコー検査」: 経胸壁心エコーは第一に行う検査だが、感度は経食道に及ばない。
E「MIBG 心筋シンチグラフィ」: MIBG心筋シンチグラフィは心臓交感神経機能の評価に用いる検査である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-40', '正答は C「染色体検査」。

低身長に翼状頸と外反肘を伴っており、Turner症候群(45,X など)を考える。確定には染色体検査(核型分析)を行う。

【誤答選択肢の解説】
A「GH 測定」: 成長ホルモン分泌の評価は低身長の精査に含まれるが、基礎疾患そのものの診断にはならない。
B「遺伝子検査」: Turner症候群は特定の遺伝子変異ではなくX染色体の数的・構造的異常によるため、核型分析が必要である。
D「手根骨エックス線撮影」: 手根骨エックス線は骨年齢の評価に用いるもので、原因診断にはならない。
E「血中エストラジオール測定」: エストラジオールは性腺機能低下を示すが、その原因を特定できない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F040（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-41', '正答は C「任意入院」。

患者自身が症状を苦痛と感じ、入院しての治療を希望している。本人の同意に基づく任意入院が適切である。精神科入院は本人の同意による任意入院が原則である。

【誤答選択肢の解説】
A「応急入院」: 応急入院は急速を要し家族等の同意も得られない場合に72時間を限度として行うもので、本人が同意している本例には当たらない。
B「自由入院」: 自由入院という入院形式は精神保健福祉法に定められていない。
D「医療保護入院」: 医療保護入院は本人の同意が得られない場合に家族等の同意で行うもので、本人が希望している状況では選ばない。
E「緊急措置入院」: 緊急措置入院は自傷他害のおそれが著しく急を要する場合の形式である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F041（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-42', '正答は E「本日の抗TNF-α 抗体の自己注射をしないよう指導する。」。

抗TNF-α抗体は感染症を増悪させ重症化させるため、発熱など感染徴候があるときは投与を見合わせる。関節症状は落ち着いており、まず本日の自己注射を中止するよう指導する。

【誤答選択肢の解説】
A「抗菌薬を投与する。」: 鼻汁と発熱のみで細菌感染を示す所見に乏しく、経過をみる段階で抗菌薬を投与する根拠がない。
B「ステロイドパルス療法を行う。」: ステロイドパルス療法の適応となる病態ではなく、免疫抑制をさらに強めることになる。
C「他の抗リウマチ薬を追加する。」: 関節の腫脹・圧痛はなく抗リウマチ薬を追加する理由がない。感染時に免疫抑制を強めるのは危険である。
D「メトトレキサートを増量する。」: 同様に、感染徴候があるときにメトトレキサートを増量すべきではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F042（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-44', '正答は A「起立試験」。

朝起きられない、起立時の気分不良と眼前暗黒感、午前中に症状が強いという訴えは起立性調節障害に典型的である。新起立試験(能動起立試験)で臥位から立位への血圧・心拍の反応をみて診断する。

【誤答選択肢の解説】
B「視野検査」: 視野の異常を示す所見はなく、視野検査の適応がない。
C「脳波検査」: 意識消失や痙攣はなく、てんかんを疑う状況ではない。
D「温度眼振検査」: 回転性めまいや眼振はなく、末梢前庭機能の検査は不要である。
E「重心動揺検査」: 平衡機能そのものの異常を示す所見はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F044（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-46', '正答は C「喉頭軟化症」。

出生直後から吸気性喘鳴があり、成長とともに安静時にも目立つようになっている。RSウイルスは陰性で胸部エックス線も正常であり、喉頭軟化症を考える。乳児の吸気性喘鳴の原因として最も多く、多くは1〜2歳までに自然軽快する。

【誤答選択肢の解説】
A「心不全」: 心音は正常で体重増加も良好であり、心不全を示す所見がない。
B「乳児喘息」: 喘息では呼気性の喘鳴となり、2か月児で診断することはない。
D「急性細気管支炎」: RSウイルス迅速検査が陰性で、出生直後からの喘鳴を急性疾患では説明できない。
E「クループ症候群」: クループは犬吠様咳嗽を伴って急性に発症するもので、経過が異なる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F046（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-48', '正答は A「睡眠薬の処方」。

産業医は労働者の健康管理と就業上の措置に関する意見を担う立場で、診療行為である処方は行わない。治療が必要であれば主治医や専門医療機関につなぐ。

【誤答選択肢の解説】
B「飲酒状況の評価」: 飲酒は睡眠障害の重要な要因で、評価は産業医の役割に含まれる。
C「リラクセーションの指導」: リラクセーションなどセルフケアの指導は保健指導として適切である。
D「快適な職場づくりへの助言」: 作業環境や職場のあり方への助言は産業医の中心的な役割である。
E「勤務状態に配慮した生活指導」: 勤務状態を踏まえた生活指導は就業上の配慮につながる産業医の役割である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F048（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-53', '正答は B「交換輸血」。

総ビリルビン29.5mg/dLと著明な高ビリルビン血症があり、傾眠、吸啜反射とMoro反射の減弱、筋緊張低下と急性ビリルビン脳症の徴候が出ている。光線療法では間に合わず、直ちに交換輸血を行ってビリルビンを除去する。

【誤答選択肢の解説】
A「血漿交換」: 血漿交換は新生児高ビリルビン血症の標準治療ではない。
C「アルブミン投与」: アルブミン投与は遊離ビリルビンを結合させる補助的手段で、これ単独では脳症の進行を止められない。
D「多面照射光線療法」: すでに神経症状が出ており、光線療法の強化では間に合わない。
E「ガンマグロブリン投与」: 免疫グロブリンは血液型不適合による溶血の抑制に用いる補助療法で、脳症が出現した時点の主治療にはならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F053（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-54', '正答は C「環軸椎亜脱臼」。

瞼裂斜上、内眼角贅皮、鼻根部平坦、巨舌、筋緊張低下はDown症候群の所見である。環軸椎の不安定性(亜脱臼)を10〜20%に合併し、頸髄症をきたしうるため、頸椎の評価と運動時の注意が長期管理上の要点になる。

【誤答選択肢の解説】
A「大動脈解離」: 大動脈解離のリスクが高いのはMarfan症候群である。
B「潰瘍性大腸炎」: 潰瘍性大腸炎の合併が特に多いという関連はない。
D「神経芽細胞腫」: 神経芽細胞腫との関連はない。Down症候群で増えるのは一過性骨髄異常増殖症と急性巨核芽球性白血病である。
E「副甲状腺機能亢進症」: Down症候群で問題となるのは甲状腺機能低下症であり、副甲状腺機能亢進症ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F054（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-6', '正答は A「強迫観念」。

自分でも「そんなことはない」と分かっているのに繰り返し頭に浮かんで離れないという訴えは、不合理性の認識(自我異和性)を伴う強迫観念である。

【誤答選択肢の解説】
B「作為体験」: 作為体験は自分の考えや行動が他人に操られているという自我障害で、統合失調症でみられる。
C「罪業妄想」: 罪業妄想はうつ病でみられる微小妄想で、訂正不能である点が強迫観念と異なる。
D「滅裂思考」: 滅裂思考は話のつながりが失われる思考形式の障害で、本例の訴えは筋が通っている。
E「妄想着想」: 妄想着想は根拠なく突然確信が生じるもので、不合理性の自覚を欠く。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-8', '正答は A「妊娠の1か月以上前」。

神経管は受精後およそ28日までに閉鎖するため、妊娠に気づいてから飲み始めたのでは間に合わない。妊娠の1か月以上前から葉酸400μg/日の摂取を始める。

【誤答選択肢の解説】
B「妊娠10 週」: 妊娠10週ではすでに神経管の閉鎖が完了しており、予防の時期を過ぎている。
C「妊娠20 週」: 妊娠20週では遅すぎる。
D「妊娠30 週」: 妊娠30週では遅すぎる。
E「妊娠36 週」: 妊娠36週では遅すぎる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('114-F-9', '正答は A「疼痛の緩和」。

転移性骨腫瘍に対する放射線治療の主目的は除痛(緩和)である。多くの症例で数週以内に疼痛が軽減し、鎮痛薬の減量につながる。

【誤答選択肢の解説】
B「病変の根治」: すでに全身に播種した病態であり、局所照射で根治は望めない。
C「遠隔転移の抑制」: 放射線は照射野内に作用する局所治療で、遠隔転移を抑える効果はない。
D「病的骨折の予防」: 照射後に骨の再石灰化が進むまでには数か月を要し、切迫骨折には手術による固定を優先する。
E「高カルシウム血症の是正」: 高カルシウム血症の是正にはビスホスホネートやデノスマブ、輸液を用いる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第114回医師国家試験 F009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp200421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-1', '正答は E「血栓性微小血管障害」。

強皮症腎クリーゼでは腎の細小動脈に内膜の増殖と狭窄が生じ、血栓性微小血管障害をきたす。急激な血圧上昇、腎機能の急速な悪化、微小血管障害性溶血性貧血と血小板減少を伴う。ACE阻害薬が治療の中心である。

【誤答選択肢の解説】
A「大動脈瘤」: 大動脈瘤は強皮症腎に特徴的な所見ではない。
B「仙腸関節炎」: 仙腸関節炎は脊椎関節炎(強直性脊椎炎など)の所見である。
C「サーモンピンク疹」: サーモンピンク疹は成人Still病に特徴的な皮疹である。
D「ネフローゼ症候群」: 強皮症腎の蛋白尿は軽度にとどまることが多く、ネフローゼ症候群を呈するのは典型的でない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-10', '正答は E「大動脈およびその分枝に病変をきたしやすい。」。

高安動脈炎は大動脈とその主要分枝を侵す大型血管炎で、上肢の脈拍減弱・血圧の左右差、血管雑音、めまいなどを呈する。我が国では若年女性に多い。

【誤答選択肢の解説】
A「中年男性に多い。」: 好発は10〜30歳代の女性で、中年男性ではない。
B「喫煙との関連性が高い。」: 喫煙との関連が強いのは閉塞性血栓血管炎(Buerger病)である。
C「水晶体偏位を合併しやすい。」: 水晶体偏位はMarfan症候群やホモシスチン尿症の所見である。
D「浅側頭動脈の炎症を合併しやすい。」: 浅側頭動脈の炎症は巨細胞性動脈炎の特徴で、高齢者に発症する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-16', '正答は E「抗D人免疫グロブリン投与」。

RhD陰性の母からRhD陽性児が生まれており、分娩時に児の赤血球が母体に入って感作される危険がある。分娩後72時間以内に抗D人免疫グロブリンを投与し、次回妊娠での血液型不適合を防ぐ。

【誤答選択肢の解説】
A「薬剤投与は行わない」: 投与しなければ感作が成立し、次回妊娠で胎児溶血性疾患を起こしうる。
B「アルブミン投与」: アルブミン投与は感作の予防に無関係である。
C「ハプトグロビン投与」: ハプトグロビンは血管内溶血時に用いるもので、この場面の適応ではない。
D「副腎皮質ステロイド投与」: 副腎皮質ステロイドは感作の予防にならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A016（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-17', '正答は E「コルポスコピィ検査」。

細胞診で異常を指摘された場合の次の段階は、コルポスコピィ(腟拡大鏡診)で子宮頸部を観察し、疑わしい部位から狙い組織診を行うことである。肉眼で異常がなくてもこの手順を踏む。

【誤答選択肢の解説】
A「子宮全摘出」: 22歳で組織診も行っていない段階での子宮全摘は、妊孕性を失わせる過剰な治療である。
B「抗ウイルス薬投与」: HPVそのものを排除する抗ウイルス薬は存在しない。
C「子宮頸部円錐切除」: 円錐切除は組織診で高度異形成以上が確認されてから検討する。
D「腫瘍マーカー測定」: 腫瘍マーカーは早期の子宮頸部病変の診断に役立たない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-2', '正答は A「Douglas窩」。

Douglas窩(直腸子宮窩・直腸膀胱窩)は仰臥位で腹腔内の最も低い位置にあたり、骨盤内の手術後に貯留する滲出液や出血を効率よく排出できる。

【誤答選択肢の解説】
B「Morrison窩」: Morrison窩は右肝下面で、上腹部の手術後に用いる。
C「Winslow孔」: Winslow孔は網囊への入口で、膵や胆道の手術で用いる。
D「左横隔膜下」: 左横隔膜下は脾摘後などのドレナージ部位である。
E「右横隔膜下」: 右横隔膜下は肝切除後などのドレナージ部位である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-23', '正答は A「睡眠中は消失する。」。

抗精神病薬の長期投与により生じた遅発性ジスキネジアである。口をもぐもぐ動かす、舌を突き出すといった口部・舌の不随意運動が特徴で、他の多くの不随意運動と同様に睡眠中は消失する。

【誤答選択肢の解説】
B「抗Parkinson病薬が著効する。」: 抗Parkinson病薬(抗コリン薬)はむしろ遅発性ジスキネジアを悪化させる。
C「抗精神病薬に特異的な副作用である。」: メトクロプラミドなど抗精神病薬以外のドパミン受容体遮断薬でも生じるため、特異的とは言えない。
D「口の動きに注意を向けさせると増悪する。」: 注意を向けると一時的に抑制できることが多く、増悪するわけではない。
E「片側上下肢を投げ出すような不随意運動を伴う。」: 片側の上下肢を投げ出すような大きな不随意運動はバリズムで、遅発性ジスキネジアの典型ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A023（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-24', '正答は D「睡眠薬による前向健忘」。

睡眠薬を服用して就床した後の行動を本人がまったく覚えていないが、周囲からは普通に振る舞っていたと見える。ベンゾジアゼピン系や非ベンゾジアゼピン系の睡眠薬による前向健忘で、夜間の摂食や外出といった複雑な行動を伴うことがある。

【誤答選択肢の解説】
A「夜間せん妄」: 夜間せん妄では意識が混濁し行動もまとまらない。本例は普通に歌い飲食したと友人が述べている。
B「一過性全健忘」: 一過性全健忘は数時間の記銘障害が一度だけ生じるもので、2か月にわたり反復する経過に合わない。
C「全生活史健忘」: 全生活史健忘は解離性の健忘で、自分が誰かを含む生活史全体を失う。
E「レム〈REM〉睡眠行動障害」: REM睡眠行動障害は夢の内容に伴う暴力的な動きが特徴で、外出やカラオケのような複雑で社会的な行動はとらない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-25', '正答は A「経過観察」。

RSウイルスによる細気管支炎だが、SpO2は98%で陥没呼吸もなく、哺乳量も保たれている。軽症であり、水分摂取と呼吸状態の観察を続ける経過観察でよい。悪化の徴候を保護者に伝えることが重要である。

【誤答選択肢の解説】
B「抗菌薬投与」: ウイルス感染であり、細菌感染を示す所見もないため抗菌薬の適応がない。
C「抗ウイルス薬投与」: RSウイルスに対する抗ウイルス薬は一般診療では用いない。
D「ガンマグロブリン投与」: 免疫グロブリンの適応となる病態ではない。
E「ヒト化モノクローナル抗体投与」: パリビズマブはハイリスク児の発症予防に用いる薬剤で、発症後の治療薬ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-3', '正答は C「平均赤血球ヘモグロビン濃度は正常範囲である。」。

腎性貧血はエリスロポエチンの産生低下による貧血で、赤血球の大きさもヘモグロビン濃度も正常な正球性正色素性貧血を示す。したがって平均赤血球ヘモグロビン濃度(MCHC)は正常範囲にある。

【誤答選択肢の解説】
A「網赤血球数は増加する。」: エリスロポエチンが不足しているため骨髄の反応は乏しく、網赤血球は増加しない。
B「血中間接ビリルビン値は上昇する。」: 溶血ではないので間接ビリルビンは上昇しない。
D「血中ヘモグロビン値は慢性腎臓病のG2期から低下する。」: 貧血が明らかになるのはおおむねG3b期(eGFR 45未満)以降で、G2期から低下するわけではない。
E「血中エリスロポエチン濃度は発症初期から測定感度以下になる。」: エリスロポエチンは貧血の程度に見合った上昇を示さないだけで、測定感度以下になるわけではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-31', '正答は B「加齢黄斑変性」。

高齢者で線がゆがんで見える変視症と中心視力の低下があり、両眼性で左右差を伴っている。加齢黄斑変性を第一に考える。滲出型では脈絡膜新生血管が黄斑部に生じ、抗VEGF薬の硝子体内注射が治療となる。

【誤答選択肢の解説】
A「視神経炎」: 視神経炎は若年に多く、眼球運動時痛と中心暗点、相対的瞳孔求心路障害を伴う。
C「特発性黄斑円孔」: 特発性黄斑円孔も変視症をきたすが、中高年女性の片眼性に生じることが多い。
D「網膜中心静脈閉塞症」: 網膜中心静脈閉塞症は突然の視力低下と広範な眼底出血をきたす。
E「網膜動脈分枝閉塞症」: 網膜動脈分枝閉塞症は突然の視野欠損として発症する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A031（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-34', '正答は B「急性動脈閉塞」。

心房細動があり、突然発症した片側上肢の疼痛・しびれに加え、蒼白と橈骨動脈拍動の微弱を認める。心内血栓が上肢動脈に飛んだ急性動脈閉塞で、疼痛・蒼白・脈拍消失・知覚異常・運動麻痺の5徴を確認する。時間との勝負で、血行再建を急ぐ。

【誤答選択肢の解説】
A「脳梗塞」: 意識障害や片麻痺、構音障害など中枢神経症状がなく、脳梗塞では上肢の蒼白と脈拍微弱を説明できない。
C「手根管症候群」: 手根管症候群は正中神経領域のしびれが緩徐に進むもので、突然発症せず皮膚色や脈拍にも影響しない。
D「胸郭出口症候群」: 胸郭出口症候群は上肢挙上など特定の姿勢で誘発される慢性の症候群である。
E「頸椎椎間板ヘルニア」: 頸椎椎間板ヘルニアは神経根症状をきたすが、皮膚の蒼白や動脈拍動の消失は生じない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A034（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-35', '正答は E「自宅での経過観察の指示」。

マムシ咬傷では腫脹が数日かけて中枢側へ進み、横紋筋融解による急性腎障害やDICを合併しうる。症状が軽くみえても入院して経過を観察する必要があり、自宅で様子をみるよう指示するのは誤りである。

【誤答選択肢の解説】
A「抗菌薬の投与」: 蛇の口腔内細菌による創部感染を予防するため抗菌薬を投与する。正しい。
B「局所の血液吸引」: 受傷直後であれば吸引器で局所から毒を吸い出すことが試みられる。正しい。
C「細胞外液の補液」: 横紋筋融解による腎障害を防ぐため十分な輸液を行う。正しい。
D「抗マムシ血清の投与」: 腫脹が進行する例では抗マムシウマ血清の投与を検討する。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A035（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-36', '正答は C「膀胱瘻を造設する。」。

会陰部打撲後に外尿道口からの出血と尿閉があり、尿道損傷を考える。この状況で尿道カテーテルを挿入すると損傷を完全断裂に広げてしまうため禁忌で、恥骨上から膀胱瘻を造設して尿路を確保する。

【誤答選択肢の解説】
A「血液透析を行う。」: クレアチニン0.7mg/dLと腎機能は正常で、透析の適応がない。
B「腎瘻を造設する。」: 閉塞は下部尿路にあり、腎瘻では尿道損傷の管理にならない。
D「尿管ステントを留置する。」: 尿管の損傷ではないため、尿管ステントの適応がない。
E「外腸骨動脈の塞栓術を行う。」: 血圧は保たれており、動脈塞栓術を要する大量出血ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A036（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-38', '正答は C「アドレナリン筋注」。

給食(エビ・小麦)の後の運動中に喘鳴と全身の膨疹が出現しており、食物依存性運動誘発アナフィラキシーである。皮膚と呼吸器の2臓器に症状が及んでおり、直ちにアドレナリン0.01mg/kgを大腿前外側に筋注する。

【誤答選択肢の解説】
A「気道確保」: 意識は清明で会話もできており、この時点で気道確保の手技を優先する状況ではない。アドレナリンが先である。
B「ステロイド吸入」: 吸入ステロイドは効果発現が遅く、アナフィラキシーの急性期治療にならない。
D「抗ヒスタミン薬内服」: 抗ヒスタミン薬は皮膚症状にしか効かず、気道や循環の症状を改善しない。
E「重炭酸ナトリウム静注」: 重炭酸ナトリウムの適応となる病態ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A038（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-39', '正答は E「Guillain-Barré症候群」。

上気道感染の1週後に外眼筋麻痺、運動失調、腱反射消失の三徴が亜急性に進行しており、Guillain-Barré症候群の亜型であるFisher症候群である。抗GQ1b抗体が高率に陽性となる。

【誤答選択肢の解説】
A「重症筋無力症」: 重症筋無力症は症状に日内変動と易疲労性があり、腱反射は保たれる。
B「多発性硬化症」: 多発性硬化症は中枢の脱髄で、腱反射は亢進し感覚障害を伴うことが多い。
C「進行性核上性麻痺」: 進行性核上性麻痺は高齢者に緩徐進行し、垂直方向の注視麻痺と易転倒性を示す。10日の経過に合わない。
D「筋萎縮性側索硬化症」: 筋萎縮性側索硬化症は筋萎縮と線維束性収縮が主体で、外眼筋は末期まで保たれる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A039（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-4', '正答は D「PD〈programmed cell death〉-1」。

切除不能の悪性黒色腫には免疫チェックポイント阻害薬が用いられ、ニボルマブやペムブロリズマブはT細胞上のPD-1を標的とする。PD-1とそのリガンドの結合を遮ることで、腫瘍が免疫から逃れる仕組みを解除する。

【誤答選択肢の解説】
A「IL-17」: IL-17を標的とする抗体薬は乾癬などに用いる。
B「EGF受容体」: EGFR抗体は大腸癌や頭頸部癌に用いる。
C「IL-6受容体」: IL-6受容体抗体(トシリズマブ)は関節リウマチなどに用いる。
E「VEGF〈vascular endothelial growth factor〉」: VEGF抗体(ベバシズマブ)は大腸癌や肺癌に用いる血管新生阻害薬である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-41', '正答は E「右心カテーテル検査」。

労作時息切れにII音肺動脈成分の亢進、右室肥大、肺動脈主幹部の拡張があり、肺血栓塞栓や肺実質病変は否定されている。肺動脈性肺高血圧症を疑うが、確定には右心カテーテル検査で平均肺動脈圧と肺血管抵抗、肺動脈楔入圧を実測する必要がある。心エコーの推定値だけでは診断できない。

【誤答選択肢の解説】
A「胸部MRI」: 胸部MRIは右室機能の評価には使えるが、肺動脈圧を実測できない。
B「FDG-PET」: FDG-PETは悪性腫瘍の検索に用いるもので、この病態の診断には寄与しない。
C「喀痰細胞診」: 喀痰細胞診は肺癌を疑うときの検査で、肺野に異常のない本例には当たらない。
D「冠動脈造影」: 冠動脈造影は虚血性心疾患の評価で、労作時息切れの原因としては否定的である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A041（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-42', '正答は D「浸透圧性下剤投与」。

兎糞状便で排便回数が少なく、強くいきむ必要があり残便感が続く慢性便秘症である。器質的疾患は内視鏡で除外されており、生活指導に加えて浸透圧性下剤(酸化マグネシウムなど)から始める。

【誤答選択肢の解説】
A「安静指示」: 身体活動は腸蠕動を促すため、安静はむしろ便秘を悪化させる。
B「抗菌薬投与」: 感染性の病態ではなく抗菌薬の適応がない。
C「定期的な浣腸」: 浣腸を習慣化すると直腸の排便反射が鈍り、自力での排便が難しくなる。
E「食物繊維摂取の制限」: 食物繊維は便量を増やして排便を促すため、制限するのは逆である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A042（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-43', '正答は A「血小板輸血」。

寛解導入療法中で血小板1.0万/μLまで低下し、下腿に紫斑という出血症状が出ている。予防的輸血の閾値を下回ったうえ出血徴候もあり、血小板輸血の適応である。

【誤答選択肢の解説】
B「新鮮凍結血漿輸血」: PT-INR 1.0、APTT 29.2秒とほぼ正常で、凝固因子の補充を要する状態ではない。
C「赤血球濃厚液輸血」: Hb8.8g/dLは化学療法中としては許容範囲で、緊急の赤血球輸血の適応にならない。
D「エリスロポエチン製剤の投与」: エリスロポエチン製剤は化学療法後の貧血に用いる薬剤ではなく、効果発現も遅い。
E「トロンボポエチン受容体作動薬の投与」: トロンボポエチン受容体作動薬は免疫性血小板減少症に用いるもので、化学療法による骨髄抑制の急性期には使わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A043（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-44', '正答は B「抗SS-A抗体」。

眼の乾燥と口腔乾燥に多関節痛と白血球減少を伴っており、Sjögren症候群を考える。診断の裏づけとして抗SS-A抗体(抗Ro抗体)を測定する。関節リウマチとの合併もあるため注意する。

【誤答選択肢の解説】
A「PR3-ANCA」: PR3-ANCAは多発血管炎性肉芽腫症で陽性となる。
C「抗MDA5抗体」: 抗MDA5抗体は皮膚筋炎、とくに急速進行性間質性肺炎を伴う型でみられる。
D「抗dsDNA抗体」: 抗dsDNA抗体は全身性エリテマトーデスに特異的で、腎炎の活動性を反映する。
E「抗アクアポリン4抗体」: 抗アクアポリン4抗体は視神経脊髄炎スペクトラム障害の抗体である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A044（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-46', '正答は C「気管支喘息の合併が多い。」。

気管支肺胞洗浄液の好酸球37%と肺胞隔壁への好酸球浸潤があり、自然軽快と再燃を繰り返す遊走性の陰影という経過から慢性好酸球性肺炎である。半数程度に気管支喘息を合併する。

【誤答選択肢の解説】
A「高齢者に多い。」: 中年女性に多い疾患で、高齢者に多いわけではない。
B「喫煙が発症に関係する。」: 非喫煙者に多い。喫煙が発症に関わるのは急性好酸球性肺炎のほうである。
D「ステロイド抵抗性である。」: 副腎皮質ステロイドが著効するのが特徴で、抵抗性ではない。ただし減量で再燃しやすい。
E「末梢血好酸球は正常である。」: 末梢血好酸球も増加することが多い。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A046（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-47', '正答は D「機能性ディスペプシア」。

食後のもたれ感と早期飽満感が半年続き、内視鏡・腹部超音波とも異常がなくH. pylori抗体も陰性である。体重減少もなく、機能性ディスペプシアの食後愁訴症候群と考える。

【誤答選択肢の解説】
A「逆流性食道炎」: 逆流性食道炎は胸やけが主症状で、内視鏡で粘膜傷害を認める。本例は胸やけがなく内視鏡も正常である。
B「過敏性腸症候群」: 過敏性腸症候群は排便に関連する腹痛と便通異常が診断に必要である。
C「食道裂孔ヘルニア」: 食道裂孔ヘルニアは内視鏡で確認できる形態異常で、本例では指摘されていない。
E「非びらん性胃食道逆流症〈NERD〉」: 非びらん性胃食道逆流症は内視鏡で異常がない逆流症だが、胸やけや呑酸が主症状である。本例に逆流症状はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A047（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-48', '正答は C「大動脈縮窄症」。

上肢のSpO2が96%、下肢が88%と下半身のみ酸素化が低い分離性チアノーゼで、皮膚色も下半身が暗い。動脈管を介して肺動脈血が下行大動脈へ流れていることを意味し、大動脈縮窄症など動脈管に依存する左心系閉塞性病変を考える。

【誤答選択肢の解説】
A「Fallot四徴症」: Fallot四徴症では右左短絡血が全身に回るため、上下肢に差のない全身性チアノーゼとなる。
B「三尖弁閉鎖症」: 三尖弁閉鎖症も全身性のチアノーゼを示す。
D「心室中隔欠損症」: 心室中隔欠損症は左右短絡でチアノーゼをきたさない。
E「完全大血管転位症」: 完全大血管転位症では動脈管を通る血流の向きが逆になり、上肢のほうが低く下肢が高い逆分離性チアノーゼを示すことがある。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A048（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-5', '正答は A「髄様癌」。

甲状腺髄様癌は傍濾胞細胞(C細胞)由来の腫瘍で、カルシトニンを産生する。CEAも上昇し、多発性内分泌腫瘍症2型の部分症として発症することがあるためRET遺伝子の検索も行う。

【誤答選択肢の解説】
B「乳頭癌」: 乳頭癌は濾胞上皮由来で、サイログロブリンが指標となる。
C「濾胞癌」: 濾胞癌も濾胞上皮由来である。
D「亜急性甲状腺炎」: 亜急性甲状腺炎は炎症性疾患で、破壊性の甲状腺中毒症を示す。
E「腺腫様甲状腺腫」: 腺腫様甲状腺腫は過形成性の病変でホルモン産生の異常を伴わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-51', '正答は D「4」。

高齢者の高血圧でもサイアザイド系利尿薬は第一選択薬の一つで、カルシウム拮抗薬・ARB・ACE阻害薬と並ぶ。「第一選択にできません」という4は誤りである。

【誤答選択肢の解説】
A「1」: 高齢者でも減塩は降圧に有効だが、極端な制限は食欲低下から低栄養を招くため配慮が要る。正しい。
B「2」: 加齢に伴う圧受容器反射の低下により、起立時の血圧維持が弱くなる。正しい。
C「3」: 食後に内臓血流が増えることで血圧が下がる食後低血圧は高齢者で問題になる。正しい。
E「5」: ACE阻害薬とARBの併用は腎機能悪化と高カリウム血症を増やし、予後の改善も示されていないため推奨されない。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A051（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-52', '正答は B「経過観察」。

紙巻たばこの誤飲では、ニコチンの吸収が遅く胃内で嘔吐を誘発することが多いため、乾いた葉を少量食べただけで3時間無症状なら中毒症状が出る可能性は低い。経過観察でよい。

【誤答選択肢の解説】
A「胃洗浄」: 胃洗浄は誤嚥のリスクがあり、無症状の少量誤飲には適応がない。
C「下剤投与」: 下剤で排泄を促す必要はない。
D「活性炭投与」: 活性炭はニコチンを吸着するが、無症状で時間が経過した本例には不要である。
E「生理食塩液の点滴」: 脱水も循環不全もなく、輸液の適応がない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A052（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-53', '正答は C「明け方の血糖値の測定」。

朝食前の血糖が3日とも最も高く、夜間に発汗を伴って目覚めることがある。夜間低血糖の反跳による朝の高血糖(Somogyi効果)か、単純な暁現象かで対応が正反対になるため、まず明け方(午前3時前後)の血糖を測って区別する。

【誤答選択肢の解説】
A「夕食後の散歩」: 夕食後の運動は夜間低血糖をさらに助長しうる。
B「夕食時の糖質減量」: 夕食の糖質を減らすことも夜間低血糖を悪化させる方向に働く。
D「スルホニル尿素薬の内服の追加」: インスリン療法中の2型糖尿病にスルホニル尿素薬を追加すれば低血糖の危険が増す。
E「夕食前の超速効型ヒトインスリンの増量」: 夕食前の超速効型インスリンを増やすと夜間低血糖がさらに強まる。原因を確かめる前に増量してはならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A053（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-54', '正答は B「チック」。

突発的で非律動的な瞬目や顔しかめ、首振りが数か月にわたり増減し、睡眠中には消失し、短時間なら自分で抑えられる。いずれもチックの特徴である。運動チックと音声チックが1年以上続けばTourette症候群を考える。

【誤答選択肢の解説】
A「振戦」: 振戦は律動的な振動で、抑制できず睡眠中に消失する点は共通だが動作の性質が異なる。
C「バリズム」: バリズムは片側の四肢を投げ出すような大振りの不随意運動である。
D「舞踏運動」: 舞踏運動は流れるように次々と部位が移る不随意運動で、意図的に抑制できない。
E「アテトーゼ」: アテトーゼはゆっくりとねじれるような持続的な運動である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A054（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-56', '正答は E「精巣」。

25歳男性でhCGとAFPがともに上昇しており、非セミノーマ型の胚細胞腫瘍を考える。この年代の胚細胞腫瘍の原発は精巣が最も多く、腰背部痛は後腹膜リンパ節転移、咳嗽は肺転移で説明できる。触診と陰囊超音波で精巣を確認する。

【誤答選択肢の解説】
A「甲状腺」: 甲状腺癌はサイログロブリンやカルシトニンが指標で、hCG・AFPは上昇しない。
B「肝臓」: 肝細胞癌でもAFPは上昇するが、25歳で背景肝疾患がなく、hCG上昇も説明できない。
C「膵臓」: 膵癌の腫瘍マーカーはCA19-9で、本例は基準内である。
D「大腸」: 大腸癌のマーカーはCEAで、本例は基準内である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A056（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-57', '正答は D「2,500mL」。

心拍数120/分・収縮期血圧80mmHgでショックインデックスは1.5となる。産科危機的出血ではショックインデックス1.0でおよそ1,000〜1,500mL、1.5でおよそ2,500mLの出血に相当するとされる。

【誤答選択肢の解説】
A「500mL」: 500mLはショックインデックス1.0未満に相当し、この循環動態には合わない。
B「1,000mL」: 1,000mLはショックインデックス1.0前後の目安である。
C「1,500mL」: 1,500mLでもショックインデックスは1.0強にとどまる。
E「4,000mL」: 4,000mLではさらに高度のショックとなり、意識レベルも保たれない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A057（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-61', '正答は D「網膜色素変性」。

顔面の三叉神経第1枝領域のポートワイン母斑と、同側大脳の軟膜血管腫、そして無熱性けいれんからSturge-Weber症候群である。網膜色素変性は含まれず、眼合併症としては緑内障や脈絡膜血管腫がみられる。

【誤答選択肢の解説】
A「片麻痺」: 血管腫のある大脳半球の障害により、対側の片麻痺を生じる。
B「精神遅滞」: 難治性てんかんの反復により精神運動発達の遅れをきたす。
C「てんかん」: 軟膜血管腫による皮質の慢性虚血でてんかんを発症し、しばしば難治性となる。
E「脳回に沿った石灰化」: 皮質に沿った軌道様(tram-track)の石灰化が特徴的な画像所見である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A061（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-62', '正答は E「5」。

双胎の分娩様式を決めるうえで最も重要なのは先進児の胎位である。先進児が頭位でなければ経腟分娩は選択できず、帝王切開となる。本例は先進児が骨盤位であり、この情報が判断を左右する。

【誤答選択肢の解説】
A「1」: 高年初産であることは分娩管理上の注意点だが、それ自体が経腟分娩の可否を決めない。
B「2」: 不妊治療歴も分娩様式の決定因子ではない。
C「3」: 卵巣囊胞摘出術の既往は子宮に及ぶ手術ではなく、子宮破裂のリスクにならない。
D「4」: 推定胎児体重の差は小さく、いずれも経腟分娩が可能な範囲である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A062（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-63', '正答は A「術後出血」。

骨盤底に留置したドレーンからの排液の性状と量を見ることで、術後出血を早期に発見できる。血性排液の増加は再開腹の判断につながる。

【誤答選択肢の解説】
B「腸管癒着」: 腸管癒着はドレーンの排液では分からない。むしろドレーン自体が癒着の原因になりうる。
C「神経因性膀胱」: 神経因性膀胱は広汎子宮全摘術に伴う骨盤神経損傷で起こるが、排尿機能の評価でしか分からない。
D「骨盤内の癌再発」: 癌の再発は画像や腫瘍マーカーで追うもので、術直後のドレーンでは検出できない。
E「深部静脈血栓症」: 深部静脈血栓症は下肢の腫脹やDダイマー、超音波で評価する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A063（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-7', '正答は C「内鼠径ヘルニア」。

Hesselbach三角(下腹壁動静脈の内側、腹直筋外側縁、鼠径靱帯に囲まれた領域)から後腹壁を押し出すように脱出するのが内鼠径ヘルニア(直接鼠径ヘルニア)である。高齢男性の腹壁脆弱化に伴って生じる。

【誤答選択肢の解説】
A「大腿ヘルニア」: 大腿ヘルニアは鼠径靱帯の下、大腿輪から脱出する。女性に多く嵌頓しやすい。
B「外鼠径ヘルニア」: 外鼠径ヘルニアは下腹壁動静脈の外側にある内鼠径輪から鼠径管に入る。
D「閉鎖孔ヘルニア」: 閉鎖孔ヘルニアは骨盤の閉鎖孔から脱出し、やせた高齢女性に多い。
E「Bochdalek孔ヘルニア」: Bochdalek孔ヘルニアは横隔膜後外側の欠損による先天性横隔膜ヘルニアである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-8', '正答は E「α-フェトプロテイン〈AFP〉値」。

α-フェトプロテインは肝細胞癌の腫瘍マーカーであり、肝臓がどれだけ働けるか(肝予備能)とは無関係である。切除可能な肝容積の判断には使えない。

【誤答選択肢の解説】
A「血清アルブミン値」: 血清アルブミンは肝の蛋白合成能を反映し、Child-Pugh分類の項目である。
B「ICG試験(15分値)」: ICG15分停滞率は色素の肝取り込み・排泄能を反映し、切除可能量の決定に用いる。
C「血清総ビリルビン値」: 総ビリルビンは肝の排泄能を反映し、Child-Pugh分類の項目である。
D「プロトロンビン時間」: プロトロンビン時間は凝固因子の合成能を反映し、Child-Pugh分類の項目である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-A-9', '正答は E「血栓性血小板減少性紫斑病」。

血栓性血小板減少性紫斑病では微小血管内に血小板血栓ができ、そこを通過する赤血球が機械的に破砕される。末梢血に破砕赤血球(schistocyte)が出現するのが特徴で、ADAMTS13活性の著減による。

【誤答選択肢の解説】
A「異常ヘモグロビン症」: 異常ヘモグロビン症では赤血球の変形や不安定化が起こるが、機械的な破砕によるものではない。
B「遺伝性球状赤血球症」: 遺伝性球状赤血球症は膜蛋白の異常による球状化と脾での捕捉が本態である。
C「自己免疫性溶血性貧血」: 自己免疫性溶血性貧血は自己抗体による血管外溶血が主体である。
D「発作性寒冷血色素尿症」: 発作性寒冷血色素尿症はDonath-Landsteiner抗体による補体介在性の血管内溶血で、破砕赤血球は伴わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 A009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-1', '正答は A「飲酒 — 食道癌」。

飲酒は食道扁平上皮癌の確立した危険因子で、喫煙との相乗効果がある。アセトアルデヒド脱水素酵素の活性が低い人ではとくにリスクが高い。

【誤答選択肢の解説】
B「低体重 — 睡眠時無呼吸症候群」: 睡眠時無呼吸症候群の危険因子は肥満であり、低体重ではない。
C「体重増加 — フレイル」: フレイルは体重減少・筋力低下を特徴とし、体重増加は危険因子でない。
D「食物繊維の摂取 — 糖尿病」: 食物繊維の摂取は糖尿病の発症を抑える方向に働く。
E「n-3系多価不飽和脂肪酸摂取 — 虚血性心疾患」: n-3系多価不飽和脂肪酸は虚血性心疾患のリスクを下げる方向に働く。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-10', '正答は B「食塩」。

ナトリウムは摂取したほぼ全量が尿中に排泄されるため、24時間蓄尿の尿中ナトリウム量から食塩摂取量を推定できる。減塩指導の効果判定に用いられる。

【誤答選択肢の解説】
A「脂質」: 脂質は尿中に排泄されないため蓄尿では評価できない。
C「食物繊維」: 食物繊維は消化されず糞便に排泄されるため、尿では分からない。
D「エネルギー」: エネルギー摂取量は尿から推定できない。
E「脂溶性ビタミン」: 脂溶性ビタミンは体内に蓄積され尿中排泄が乏しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-11', '正答は C「問題を具体化せず意見を求める。」。

コンサルテーションでは、何を相談したいのかを具体的な問いの形にして伝えることが要である。問題を具体化せずに漠然と意見を求めると、相手は何に答えればよいか分からず、時間も浪費する。

【誤答選択肢の解説】
A「簡潔なコンサルテーションを心掛ける。」: 要点を絞って簡潔に伝えることは適切である。
B「相手との良好な関係性を心掛ける。」: 継続的に相談できる関係を保つことは診療の質につながる。
D「患者についての情報を集める。」: 病歴・所見・検査結果を整理してから相談するのは適切である。
E「緊急性を考えて行う。」: 緊急度に応じて連絡の手段とタイミングを選ぶのは適切である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-13', '正答は A「嗅覚低下」。

嗅覚の低下は食欲や食事の楽しみに影響しうるが、嚥下の運動そのものには関与しないため嚥下障害の原因にはならない。

【誤答選択肢の解説】
B「歯牙欠損」: 歯牙の欠損は咀嚼を妨げ、食塊形成の不良から嚥下を難しくする。
C「舌運動低下」: 舌の運動低下は食塊を咽頭へ送り込む口腔期の障害となる。
D「唾液分泌低下」: 唾液分泌の低下は食塊がまとまらず、咽頭への送り込みを妨げる。
E「咽頭収縮力低下」: 咽頭収縮力の低下は咽頭残留と誤嚥の直接の原因になる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B013（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-14', '正答は D「はさみ歩行」。

両下肢の痙縮では股関節内転筋の緊張が強まり、歩行時に膝が内側で交差する。この歩容をはさみ歩行(scissors gait)と呼び、痙直型脳性麻痺や痙性対麻痺でみられる。

【誤答選択肢の解説】
A「開脚歩行」: 開脚歩行は小脳性運動失調で、体幹の動揺を補うため足を広げて歩く。
B「動揺歩行」: 動揺歩行は近位筋の筋力低下(筋ジストロフィーなど)で骨盤が左右に揺れる歩き方である。
C「小刻み歩行」: 小刻み歩行はParkinson病でみられ、歩幅が小さく前傾姿勢をとる。
E「分回し歩行」: 分回し歩行は片麻痺で麻痺側下肢を外側に回して振り出す歩き方である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B014（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-15', '正答は E「マイコプラズマ肺炎」。

3週未満の急性咳嗽の大半は感染性で、かぜ症候群や肺炎などが原因となる。マイコプラズマ肺炎はその代表である。

【誤答選択肢の解説】
A「COPD」: COPDによる咳嗽は8週を超える慢性咳嗽の原因である。
B「咳喘息」: 咳喘息は遷延性から慢性咳嗽の代表的な原因である。
C「胃食道逆流症」: 胃食道逆流症も慢性咳嗽の原因として重要である。
D「副鼻腔気管支症候群」: 副鼻腔気管支症候群は慢性咳嗽の原因である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B015（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-16', '正答は E「本人の意思が確認できない場合、家族等による推定意思が尊重される。」。

本人の意思が確認できない場合は、家族等が本人の価値観や以前の言動から推定する意思を尊重し、それも分からなければ本人にとって何が最善かを医療・ケアチームと家族等で慎重に話し合って決める。

【誤答選択肢の解説】
A「対象は癌患者である。」: 癌に限らず、非癌の慢性疾患や老衰なども対象である。
B「意思決定は変化することはない。」: 意思は状態や状況の変化で変わりうるため、繰り返し話し合うことが求められる。
C「積極的安楽死が選択肢の一つとなる。」: 積極的安楽死は我が国では認められておらず、選択肢にならない。
D「可能な限り生命を維持したいと希望する患者は対象とならない。」: 生命維持を希望する患者も当然に対象で、その意思が尊重される。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B016（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-17', '正答は A「小脳梗塞 — 同名半盲」。

同名半盲は視交叉より後方の視路(後頭葉や視放線)の障害で生じる。小脳は視覚路に関与しないため、小脳梗塞で同名半盲は起こらない。小脳梗塞では失調性歩行、眼振、めまい、嘔吐がみられる。

【誤答選択肢の解説】
B「聴神経腫瘍 — 語音明瞭度低下」: 聴神経腫瘍では後迷路性難聴として、聴力低下の程度に不釣り合いな語音明瞭度の低下を示す。
C「突発性難聴 — 耳鳴」: 突発性難聴では耳鳴やめまいを伴うことが多い。
D「パニック障害 — 動悸」: パニック障害では動悸・発汗・呼吸困難などの自律神経症状が発作性に生じる。
E「良性発作性頭位めまい症 — 寝返り時のめまい」: 良性発作性頭位めまい症は寝返りや起き上がりなど頭位変換で誘発される回転性めまいが特徴である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-18', '正答は C「行為によって不安は緩和される。」。

強迫行為は、強迫観念による不安を打ち消すために行われる。行為によって不安は一時的に和らぐが、繰り返すほど強迫観念が強化されるという悪循環に陥る。

【誤答選択肢の解説】
A「行為中の記憶がない。」: 意識は保たれており、行為中の記憶はある。
B「行為は夕方増悪する。」: 時間帯による一定の日内変動は特徴でない。
D「患者は行為を合理的であると考えている。」: 患者自身も行為が不合理だと分かっており(自我異和性)、そこが妄想と異なる点である。
E「「行為をしなさい」という命令が外から頭の中に吹き込まれる。」: 外から命令が吹き込まれるのは幻聴や作為体験で、統合失調症の症状である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B018（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-19', '正答は A「僧帽弁狭窄症」。

僧帽弁狭窄症では左房から左室への流入が妨げられるため、左室に入る血液量すなわち前負荷が低下する。左室はむしろ小さく保たれ、うっ血は左房から肺静脈側に生じる。

【誤答選択肢の解説】
B「大動脈弁狭窄症」: 大動脈弁狭窄症は左室の後負荷が増える病態で、前負荷は低下しない。
C「三尖弁閉鎖不全症」: 三尖弁閉鎖不全症は右心系の容量負荷で、左室前負荷には直接影響しない。
D「僧帽弁閉鎖不全症」: 僧帽弁閉鎖不全症では逆流した血液が左房を経て左室に戻るため前負荷が増える。
E「大動脈弁閉鎖不全症」: 大動脈弁閉鎖不全症では拡張期に大動脈から左室へ逆流し、前負荷が増える。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-2', '正答は E「疾患や診療に対する患者の考えを把握する。」。

解釈モデルとは、患者が自分の症状を何によるものと考え、何を心配し、どうしてほしいと思っているかという理解の枠組みである。これを聞くことで説明の焦点が定まり、患者の納得と治療への参加が得られる。

【誤答選択肢の解説】
A「患者の取り違えを防ぐ。」: 患者誤認の防止は氏名と生年月日など2つ以上の識別子で確認するもので、解釈モデルとは別である。
B「患者の訴えの信憑性を評価する。」: 訴えの信憑性を疑うための手段ではない。
C「精神疾患をスクリーニングする。」: 精神疾患のスクリーニングを目的とするものではない。
D「医療機関に対する不満を把握する。」: 医療機関への不満を聞き出すことが目的ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-21', '正答は D「児童相談所」。

児童虐待防止法により、虐待を受けたと思われる児童を発見した者は児童相談所または市町村に通告する義務を負う。生命の危険がない段階でも通告する。

【誤答選択肢の解説】
A「警察署」: 警察への通報は生命に差し迫った危険がある場合で、通常の通告先ではない。
B「小学校」: 学校は通告先として法に定められていない。
C「保健所」: 保健所は感染症や難病を扱う機関で、虐待通告の窓口ではない。
E「市町村保健センター」: 市町村保健センターは健康づくりの拠点で、通告先として第一に挙がるものではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B021（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-22', '正答は B「胆囊癌」。

胆囊は肝臓に付着しているため、呼吸に伴う横隔膜の動きで肝臓とともに上下する。腫大した胆囊や胆囊癌は、吸気時に触知しやすく呼吸性に移動する。

【誤答選択肢の解説】
A「膵囊胞」: 膵囊胞は後腹膜にあり、呼吸性の移動を示さない。
C「腹部大動脈瘤」: 腹部大動脈瘤は後腹膜で拍動性に触れるが、呼吸で移動しない。
D「腹膜偽粘液腫」: 腹膜偽粘液腫は腹腔内にゼリー状の粘液が充満する病態で、限局した可動性腫瘤としては触れない。
E「Krukenberg腫瘍」: Krukenberg腫瘍は骨盤内の卵巣転移で、呼吸性の移動はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-23', '正答は D「喀痰のGram染色を確認してから開始する。」。

喀痰のGram染色は数分で結果が得られ、起炎菌の推定と適切な狭域抗菌薬の選択に直結する。培養結果を待たずに治療を始められるという点で、抗菌薬適正使用の要になる。

【誤答選択肢の解説】
A「体温により抗菌薬を選択する。」: 体温の高さは起炎菌の種類を示さない。
B「白血球数により抗菌薬を選択する。」: 白血球数も起炎菌の推定には使えない。
C「喀痰培養の最終結果が出てから開始する。」: 培養の最終結果は数日かかり、待っていては治療が遅れる。
E「治療効果の判定はCRPの正常化を指標とする。」: CRPは炎症の指標にすぎず、正常化を治療終了の基準にすると不要に長期投与になる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B023（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-24', '正答は D「蛋白制限」。

蛋白制限はアンモニアの産生を抑えるため、肝性脳症の誘因ではなく治療の一部である。ただし過度の制限は筋肉量を落としてかえって不利になるため、現在は極端な制限は行わない。

【誤答選択肢の解説】
A「感染」: 感染は異化を亢進させアンモニア産生を増やす。誘因となる。
B「脱水」: 脱水は腎前性の腎障害と電解質異常を招き、脳症を誘発する。
C「便秘」: 便秘は腸内でのアンモニア産生と吸収を増やす。誘因となる。
E「消化管出血」: 消化管出血では血液が腸内で分解されて大量のアンモニアが生じる。誘因となる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-25', '正答は B「FSH」。

54歳女性で発汗発作(hot flush)、疲労感、動悸が反復しており更年期症状である。卵巣機能の低下によりエストロゲンとインヒビンが減り、負のフィードバックが外れてFSHが上昇する。

【誤答選択肢の解説】
A「GH」: GHは加齢とともに分泌が低下する。
C「オキシトシン」: オキシトシンは分娩や授乳に関わるホルモンで、この症候とは無関係である。
D「プロラクチン」: プロラクチンの上昇は乳汁漏出や無月経をきたすが、発汗発作の原因ではない。
E「プロゲステロン」: プロゲステロンは黄体から分泌されるため、閉経期にはむしろ低下する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-26', '正答は D「4」。

ノロウイルスはエンベロープを持たないためアルコールが効きにくい。診察後は石けんと流水による手洗いで物理的に洗い流す必要があり、聴診器をそのままポケットにしまうのは誤りである。使用のたびに次亜塩素酸ナトリウムなどで清拭する。

【誤答選択肢の解説】
A「1」: 診察前の手指衛生は必要で、この時点でのアルコール消毒は誤りではない。
B「2」: 接触予防策としてガウンの着用は正しい。
C「3」: 手袋の着用も接触予防策として正しい。
E「5」: ノロウイルスにはアルコールが効きにくいため、石けんと流水での手洗いは正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B026（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-27', '正答は E「Master二階段負荷試験」。

心房細動があり一過性の意識消失を繰り返している。徐脈性不整脈(徐脈頻脈症候群)による失神が疑われ、運動負荷は失神や重篤な不整脈を誘発する危険がある。日常の活動度も5分の杖歩行が限界で、負荷試験に耐えられない。

【誤答選択肢の解説】
A「血液検査」: 貧血や電解質異常、腎機能の評価は失神の鑑別に必要である。
B「心エコー検査」: 弁膜症や心機能、心内血栓の評価に有用である。
C「Holter心電図」: 発作性の徐脈や頻脈を捉えるためHolter心電図は適切である。
D「12誘導心電図」: 12誘導心電図は不整脈や伝導障害の評価に必須である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B027（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-28', '正答は B「胸骨圧迫」。

心電図モニターに心拍数20/分の波形が出ているが、意識も脈もない。心静止でも心室細動でもない無脈性電気活動(PEA)であり、除細動の適応はない。直ちに胸骨圧迫を再開し、可逆的な原因の検索と是正を進める。

【誤答選択肢の解説】
A「気管挿管」: 気道確保は重要だが、胸骨圧迫の中断を最小にすることが優先される。
C「電気的除細動」: PEAと心静止は電気ショックの適応外である。
D「アトロピン静注」: アトロピンは現在の心停止アルゴリズムでは推奨されていない。
E「リドカイン静注」: リドカインは難治性の心室細動・無脈性心室頻拍に用いるもので、PEAには適応がない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B028（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-3', '正答は B「守秘義務」。

医師の守秘義務を定めているのは刑法第134条(秘密漏示罪)であり、医師法ではない。医師法には応召義務、臨床研修、処方箋交付義務、診療録記載・保存義務などが規定されている。

【誤答選択肢の解説】
A「応召義務」: 応召義務は医師法第19条第1項に規定されている。
C「臨床研修」: 臨床研修は医師法第16条の2に規定されている。
D「処方箋の交付」: 処方箋の交付義務は医師法第22条に規定されている。
E「診療録の記載」: 診療録の記載と5年間の保存は医師法第24条に規定されている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-30', '正答は C「3」。

2歳児の呼吸数48/分は明らかな頻呼吸で、陥没呼吸を伴っており呼吸仕事量の増大を示す。SpO2が保たれていても代償の限界に近づいている可能性があり、緊急性を示す所見として最も重要である。

【誤答選択肢の解説】
A「1」: 体温37.8°Cは軽度の発熱で、緊急性を示すものではない。
B「2」: 2歳の脈拍120/分は正常範囲である。
D「4」: SpO2 98%は保たれており、この値自体は緊急性を示さない。
E「5」: 毛細血管再充満時間1秒は正常で、循環は保たれている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B030（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-31', '正答は C「抗菌薬の投与」。

白血球54,300で芽球95%、貧血と血小板減少を伴っており急性白血病である。発熱性好中球減少症に近い状態で肺炎を併発しており、生命に直結するのは感染症のコントロールである。血液培養と喀痰培養を採ったうえで、直ちに広域抗菌薬を開始する。

【誤答選択肢の解説】
A「高血圧症」: 高血圧症は既往としてあるが、この場面で優先される問題ではない。
B「血小板低値」: 血小板3.2万は出血徴候がなければ直ちに介入を要する値ではない。
D「肺炎球菌による肺炎」: 起炎菌は未確定で、肺炎球菌と決めつける根拠がない。
E「芽球を伴う白血球増多」: 芽球を伴う白血球増多は診断の手がかりだが、対応そのものではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B031（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-34', '正答は A「1」。

開放型質問は「はい・いいえ」や特定の語で答えられない、患者が自由に語れる問いである。「症状について詳しく教えてください」がこれにあたる。

【誤答選択肢の解説】
B「2」: 「熱や鼻汁はありますか」は有無を問う閉鎖型質問である。
C「3」: 「周囲に同じような症状の人はいますか」も有無を問う閉鎖型質問である。
D「4」: 「アレルギーはありますか」も閉鎖型質問である。
E「5」: 「ご両親にアレルギーはありますか」も閉鎖型質問である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B034（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-35', '正答は C「腹部超音波検査」。

直接ビリルビン優位の黄疸にトランスアミナーゼ上昇を伴っている。胆道の閉塞(総胆管結石や腫瘍)をまず除外する必要があり、非侵襲的で胆管拡張と胆石の描出に優れる腹部超音波検査を最初に行う。

【誤答選択肢の解説】
A「腹部造影CT」: 造影CTは超音波で胆管拡張を確認したうえで、原因検索として次に行う。
B「Coombs試験」: Coombs試験は溶血性貧血の検査だが、貧血がなく間接ビリルビン優位でもない。
D「腫瘍マーカー測定」: 腫瘍マーカーは閉塞の有無を確認した後の検討事項である。
E「薬剤リンパ球刺激試験」: 薬剤性肝障害も鑑別に挙がるが、まず閉塞性黄疸を除外するのが順序である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B035（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-37', '正答は A「患者を左側臥位として挿入する。」。

経鼻胃管は座位または半座位で挿入するのが基本で、左側臥位にする必要はない。臥位では誤嚥の危険が増し、嚥下の協力も得にくい。

【誤答選択肢の解説】
B「胃内容物を吸引しpHを確認する。」: 胃内容物を吸引してpHを確認することは、胃内留置の確認法の一つである。
C「初回の栄養投与は日中に実施する。」: 初回投与は異常が起きたときに対応しやすい日中に行う。
D「栄養投与前に聴診器で気泡音を確認する。」: 気泡音の聴診は補助的な確認法として行われる(単独では不十分)。
E「留置後にエックス線撮影で位置を確認する。」: エックス線撮影による位置確認が最も確実で、初回留置時には必須である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B037（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-4', '正答は E「後腹膜線維症」。

後腹膜線維症はIgG4関連疾患や薬剤性などで生じる病態で、関節リウマチの関節外症状には含まれない。

【誤答選択肢の解説】
A「皮下結節」: 皮下結節(リウマトイド結節)は肘頭など伸側に生じる代表的な関節外症状である。
B「皮膚潰瘍」: リウマトイド血管炎により皮膚潰瘍を生じることがある。
C「心外膜炎」: 心外膜炎は関節リウマチの心病変として知られる。
D「間質性肺炎」: 間質性肺炎は関節リウマチの肺病変として頻度が高く、予後を左右する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-5', '正答は A「患者の権利に基づく。」。

セカンドオピニオンは、患者が自分の治療について他の医師の意見も聞いたうえで選択するという自己決定権に基づくものである。主治医は求めに応じて診療情報を提供する。

【誤答選択肢の解説】
B「保険診療内で行われる。」: セカンドオピニオン外来は原則として保険給付の対象外で、自費診療となる。
C「悪性腫瘍だけが対象になる。」: 悪性腫瘍に限らず、あらゆる疾患・治療方針が対象になる。
D「主治医の変更が目的である。」: 目的は治療方針の理解と納得であって、主治医を替えることではない。
E「受持ち患者からの依頼を拒否できる。」: 患者の権利に基づく求めであり、担当医が拒否することはできない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-B-7', '正答は D「家族が同居していることが必要である。」。

在宅医療は独居でも受けられる。訪問診療・訪問看護・訪問介護を組み合わせ、必要に応じて介護保険サービスや看取りの体制を整える。家族の同居を要件とすると、独居高齢者が在宅療養を選べなくなる。

【誤答選択肢の解説】
A「介護保険が申請できる。」: 末期の悪性腫瘍は40〜64歳でも第2号被保険者として介護保険の特定疾病に該当し、申請できる。
B「患者本人の同意が必要である。」: 療養の場を決めるのは本人であり、同意が前提となる。
C「在宅で点滴を受けることができる。」: 在宅でも輸液や麻薬の持続投与を行うことができる。
E「在宅でリハビリテーションを受けることができる。」: 在宅でのリハビリテーションも訪問リハビリや通所リハビリとして提供される。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 B007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-1', '正答は C「各都道府県内の複数の市町村を含む。」。

二次医療圏は、一般的な入院医療を提供する単位として設定され、複数の市町村をまとめた地域に相当する。地域医療構想の構想区域も原則としてこれに一致する。

【誤答選択肢の解説】
A「中学校区に該当する。」: 中学校区は日常生活圏域の目安で、医療圏の区分ではない。
B「各市町村に該当する。」: 市町村単位は一次医療圏に相当する。
D「各都道府県に該当する。」: 都道府県単位は三次医療圏に相当する。
E「複数の都道府県を含む。」: 複数の都道府県にまたがる医療圏は設定されていない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-11', '正答は E「人工妊娠中絶」。

人工妊娠中絶は母体保護法第14条により、都道府県の医師会が指定する医師(指定医師)でなければ行えない。

【誤答選択肢の解説】
A「人工授精」: 人工授精に母体保護法上の資格要件はない。
B「体外受精」: 体外受精も母体保護法の対象ではなく、学会の登録施設要件による。
C「不妊手術」: 不妊手術は母体保護法第3条に定めがあるが、条文上は「医師」が行えるとされ、指定医師に限定されていない。
D「出生前診断」: 出生前診断に母体保護法指定医の資格は要求されない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-12', '正答は A「アラニンは糖新生に利用される。」。

筋で生じたアラニンは肝へ運ばれてピルビン酸に変換され、糖新生の材料になる(グルコース-アラニン回路)。飢餓時の血糖維持に働く。

【誤答選択肢の解説】
B「胆汁酸は中性脂肪から合成される。」: 胆汁酸はコレステロールから合成される。中性脂肪からではない。
C「非代償性肝硬変では芳香族アミノ酸が低下する。」: 非代償性肝硬変では分岐鎖アミノ酸が減り芳香族アミノ酸が増えるため、Fischer比は低下する。
D「アンモニアはTCAサイクルで尿素に変換される。」: アンモニアは尿素回路(オルニチン回路)で尿素に変換される。TCAサイクルではない。
E「非抱合型ビリルビンはグルクロン酸抱合を受け脂溶性になる。」: グルクロン酸抱合を受けることで水溶性となり、胆汁中に排泄される。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C012（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-15', '正答は E「新型インフルエンザは、診断後直ちに都道府県知事に届け出る。」。

新型インフルエンザ等感染症は、診断した医師が直ちに最寄りの保健所長を経由して都道府県知事へ届け出る。

【誤答選択肢の解説】
A「結核は検疫感染症である。」: 検疫感染症は1類感染症、新型インフルエンザ等感染症、マラリア・デング熱などが指定されており、結核は含まれない。
B「コレラの治療医療費は全額公費負担となる。」: コレラは3類感染症で、医療費の公費負担はない。
C「髄膜炎菌感染症は定期予防接種の対象である。」: 髄膜炎菌ワクチンは任意接種で、定期接種の対象ではない。
D「マラリアは感染症法に基づく入院勧告の対象となる。」: マラリアは4類感染症で、入院勧告の対象ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C015（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-16', '正答は C「生物学的製剤の使用 — HIV感染」。

生物学的製剤は遺伝子組換え技術で製造される抗体などで、ヒト血液を原料としないためHIV感染の原因にはならない。感染症の再活性化(結核・B型肝炎)には注意を要する。

【誤答選択肢の解説】
A「輸血 — ヘモクロマトーシス」: 頻回輸血では鉄が体内に蓄積し、続発性ヘモクロマトーシスをきたす。
B「副木固定 — 腓骨神経麻痺」: 腓骨頭部を副木で圧迫すると腓骨神経麻痺(下垂足)を生じる。
D「ヒト乾燥硬膜の使用 — Creutzfeldt-Jakob病」: ヒト乾燥硬膜の移植によるCreutzfeldt-Jakob病は実際に発生し、大きな問題となった。
E「プレドニゾロン長期内服 — 二次性副腎機能不全」: ステロイドの長期内服は視床下部-下垂体-副腎系を抑制し、二次性副腎機能不全をきたす。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C016（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-17', '正答は E「萎縮性胃炎」。

悪性貧血は自己免疫性の萎縮性胃炎により胃壁細胞と内因子が失われ、ビタミンB12の吸収が障害されて起こる。抗内因子抗体・抗胃壁細胞抗体が陽性となり、胃癌のリスクも高まる。

【誤答選択肢の解説】
A「胆石」: 色素胆石は慢性溶血に伴って生じる。
B「脾腫」: 脾腫は遺伝性球状赤血球症など血管外溶血で目立つ。
C「異食症」: 氷などを無性に食べたくなる異食症は鉄欠乏性貧血の特徴である。
D「嚥下障害」: 鉄欠乏に伴う嚥下障害はPlummer-Vinson症候群である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-18', '正答は C「尋常性狼瘡」。

尋常性狼瘡は皮膚結核の一型で、顔面などに緩徐に拡大する赤褐色の局面を作る。自覚症状に乏しく瘙痒を伴わない。

【誤答選択肢の解説】
A「疥癬」: 疥癬はヒゼンダニによるもので、夜間に増強する激しい瘙痒が特徴である。
B「扁平苔癬」: 扁平苔癬は紫紅色の多角形丘疹で強い瘙痒を伴う。
D「疱疹状皮膚炎」: 疱疹状皮膚炎は激しい瘙痒を伴う小水疱性の皮疹で、セリアック病と関連する。
E「水疱性類天疱瘡」: 水疱性類天疱瘡は緊満性水疱に先行して強い瘙痒が出ることが多い。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C018（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-19', '正答は C「涙もろくなるのが特徴である。」。

マタニティ・ブルーズは産後3〜10日ごろに現れる一過性の情緒不安定で、涙もろさ、不安、集中困難などを示す。多くは2週以内に自然軽快する。

【誤答選択肢の解説】
A「母乳育児は禁止する。」: 母乳育児を禁止する理由はない。
B「直ちに精神科医師に連絡する。」: 直ちに精神科へつなぐ必要はなく、支持的な関わりと経過観察が基本である。ただし2週を超えて続くなら産後うつ病を疑う。
D「自然に軽快することはまれである。」: 大半が自然に軽快する。
E「分娩1か月後に発症のピークがある。」: 発症のピークは産後数日で、1か月後ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-2', '正答は A「労働者に悪影響がみられないと判断する濃度」。

許容濃度は、労働者が1日8時間・週40時間程度その濃度の環境で働いても、ほとんどの人に健康上の悪影響がみられないと判断される濃度である。日本産業衛生学会が勧告している。

【誤答選択肢の解説】
B「維持することが望ましいと国が定めた濃度」: 国が望ましいとして定めるのは環境基準である。
C「食品添加物の1日当たりの最大摂取濃度」: 食品添加物について定められるのは一日摂取許容量(ADI)である。
D「作業場の管理区分決定のための濃度」: 作業場の管理区分を決めるのに用いるのは管理濃度である。
E「毒性が認められない最大生体内濃度」: 毒性が認められない最大量は無毒性量(NOAEL)であり、許容濃度とは概念が異なる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-21', '正答は D「低体重 — 巨大児出産」。

巨大児出産の危険因子は母体の肥満と糖尿病である。母体の低体重はむしろ低出生体重児のリスクとなる。

【誤答選択肢の解説】
A「喫煙 — 常位胎盤早期剝離」: 喫煙は胎盤の血管障害を通じて常位胎盤早期剝離のリスクを高める。正しい。
B「高齢 — 流産」: 高年妊娠では卵子の染色体異常が増え、流産率が上がる。正しい。
C「肥満 — 妊娠高血圧症候群」: 肥満は妊娠高血圧症候群の危険因子である。正しい。
E「子宮筋腫術後 — 子宮破裂」: 子宮筋腫核出術後の瘢痕は子宮破裂の危険因子である。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C021（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-22', '正答は B「尿道カテーテルは陰茎を頭側に向けて下腹部に固定する。」。

陰茎を頭側に向けて下腹部に固定すると、陰茎陰囊角での尿道の屈曲がなくなる。屈曲したまま留置するとその部位に圧迫壊死が起き、尿道皮膚瘻を生じうる。

【誤答選択肢の解説】
A「尿道カテーテルと連結する蓄尿バッグは開放式回路を用いる。」: 尿路感染を防ぐため閉鎖式回路を用いる。
C「尿道カテーテルを3日ごとに入れ換える。」: 定期的な交換は感染を減らさない。閉塞や汚染があるときに交換する。
D「入院中は連日膀胱洗浄を行う。」: 膀胱洗浄の連日施行は感染予防効果が示されておらず、推奨されない。
E「留置中は安静臥床を促す。」: 留置中も可能な範囲で離床を促す。安静臥床は合併症を増やす。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-24', '正答は C「急速な都市化や生活習慣のグローバル化が加速要因となっている。」。

非感染性疾患の増加には、都市化に伴う身体活動の低下、加工食品や砂糖入り飲料の普及、たばこ・アルコールの流通といった生活習慣のグローバル化が背景にある。低・中所得国でとくに急速に進んでいる。

【誤答選択肢の解説】
A「死亡原因としては感染性疾患より少ない。」: 世界の死亡の約7割を非感染性疾患が占め、感染性疾患より多い。
B「死亡の半分以上は高所得国で発生している。」: 非感染性疾患による死亡の8割近くは低・中所得国で生じている。
D「最大の寄与を有する単一リスクファクターは塩分過剰摂取である。」: 最大の寄与を持つ単一の危険因子は喫煙や高血圧であり、塩分過剰摂取単独ではない。
E「低・中所得国においては、富裕層の方が貧困層より死亡率が高い。」: 低・中所得国では貧困層のほうが死亡率が高い。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-3', '正答は A「発疹が消失するまで」。

学校保健安全法施行規則では、風疹の出席停止期間を「発疹が消失するまで」と定めている。

【誤答選択肢の解説】
B「解熱した後3日を経過するまで」: 「解熱した後3日を経過するまで」は麻疹の基準である。
C「発症した後5日を経過するまで」: 「発症した後5日を経過し、かつ解熱した後2日を経過するまで」はインフルエンザの基準である。
D「すべての発疹が痂皮化するまで」: 「すべての発疹が痂皮化するまで」は水痘の基準である。
E「病状により学校医その他の医師が感染のおそれがないと認めるまで」: 「医師が感染のおそれがないと認めるまで」は結核や髄膜炎菌性髄膜炎など第一種の感染症の扱いである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-35', '正答は A「禁煙」。

一次予防は病気になる前に発症そのものを防ぐ取り組みである。禁煙は肺癌・心血管疾患・COPDなど未発症の疾患の発症予防にあたり、一次予防に該当する。

【誤答選択肢の解説】
B「血糖降下薬の内服」: すでに糖尿病がある患者の血糖管理は、合併症の発症・進展を防ぐ二次〜三次予防にあたる。
C「抗血小板薬の内服」: 脳梗塞既往のある患者への抗血小板薬は再発予防で、三次予防にあたる。
D「定期的なHbA1c測定」: HbA1cの定期測定は既存疾患の管理であり、一次予防ではない。
E「肺がん検診での胸部エックス線撮影」: がん検診は無症状の段階で早期発見する二次予防である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C035（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-36', '正答は D「赤血球液-LRとの交差適合試験」。

交差適合試験は輸血する血液を決めた時点で、投与の直前に行う検査である。手術は4週後であり、現時点で行っても有効期間を過ぎてしまう。

【誤答選択肢の解説】
A「鉄剤投与」: フェリチン5ng/mLと鉄欠乏があり、術前に鉄剤で貧血を改善しておくのは適切である。
B「自己血貯血」: RhD陰性で適合血の確保が難しく、術前の自己血貯血は有用である。
C「不規則抗体スクリーニング」: 不規則抗体の有無を早期に把握しておくことは、適合血の準備に必要である。
E「血液準備量について院内輸血部門と調整」: 予測出血量800mLに対し、輸血部門と準備量を調整しておくのは適切である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C036（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-4', '正答は A「鼻カニューラ — 1L/分」。

鼻カニューラは1〜6L/分の範囲で用いる。1L/分でおよそ24%の吸入酸素濃度が得られ、低流量投与に適する。

【誤答選択肢の解説】
B「鼻カニューラ — 7L/分」: 7L/分では鼻粘膜の乾燥と疼痛が強く、鼻カニューラの上限(6L/分)を超えている。
C「フェイスマスク — 1L/分」: フェイスマスクは5L/分未満だとマスク内に呼気が滞留して二酸化炭素を再呼吸する。
D「フェイスマスク — 3L/分」: 3L/分も同様に再呼吸を招くため不適切である。
E「リザーバー付マスク — 4L/分」: リザーバー付マスクは6L/分以上、通常10L/分程度で用いる。4L/分ではリザーバーが虚脱する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-40', '正答は E「腹部に挫創があり、意識レベルがJCSIII-100である。」。

腹部挫創に加えJCS III-100の意識障害があり、緊急度・重症度がともに高い最優先治療群(赤)にあたる。搬送手段が限られる災害現場では、この患者を最初に搬送する。

【誤答選択肢の解説】
A「下肢挫創はあるが、自力で歩行できる。」: 自力歩行できるのは軽症群(緑)で、ヘリ搬送の優先度は低い。
B「頭部が挫滅しており、呼吸も脈もない。」: 呼吸も脈もない頭部挫滅は死亡群(黒)で、限られた資源を投じる対象にならない。
C「胸部に打撲傷があり、呼吸状態は安定している。」: 呼吸状態が安定していれば待機的治療群(黄)である。
D「興奮状態だが、簡単な指示に従うことができる。」: 簡単な指示に従えるなら意識は保たれており、待機的治療群にとどまる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C040（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-43', '正答は A「導尿」。

下腹部に弾性軟の腫瘤を触れ、超音波で膀胱に大量の尿貯留があり尿閉である。前立腺肥大症による溢流性尿失禁と考え、まず導尿して膀胱内圧を下げ、腎後性腎障害を防ぐ。

【誤答選択肢の解説】
B「尿道ブジー」: 尿道ブジーは尿道狭窄に対する処置で、まず行うべきものではない。
C「利尿薬投与」: 利尿薬は尿量を増やして膀胱をさらに拡張させ、病態を悪化させる。
D「β3刺激薬投与」: β3刺激薬は蓄尿症状に用いる薬剤で、尿閉を助長する。
E「抗コリン薬投与」: 抗コリン薬は排尿筋の収縮を抑え、尿閉を悪化させるため禁忌に近い。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C043（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-45', '正答は B「「体重を毎朝測定して減量を目指しましょう」」。

毎朝の体重測定は自己モニタリングとして行動変容を促す代表的な方法で、減量の目標設定にも役立つ。肥満を基盤とした耐糖能異常・脂質異常症・高血圧の是正はまず減量から入る。

【誤答選択肢の解説】
A「「血圧が高いので運動は控えましょう」」: 高血圧があっても有酸素運動は推奨される。運動を控えるのは逆である。
C「「空腹時の採血でないと糖尿病と診断できません」」: 食後2時間血糖252mg/dLとHbA1c8.2%で糖尿病型と判定でき、空腹時採血は必須ではない。
D「「糖質を含まないアルコール飲料は問題ありません」」: アルコール自体がエネルギー源であり肝への負担にもなるため、糖質を含まなければよいわけではない。
E「「1日の摂取エネルギーを1,200kcalにしましょう」」: 標準体重約65kgに対して1,200kcalは過度な制限で、続かず筋肉量も落とす。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C045（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-46', '正答は C「アドレナリンの筋肉注射」。

食物アレルギーの既往があり、膨疹の多発、口唇の高度浮腫、喘鳴、血圧70/42mmHgとアナフィラキシーショックである。直ちにアドレナリン0.3mgを大腿前外側に筋注するよう指示する。

【誤答選択肢の解説】
A「気管挿管」: 気道浮腫が進めば挿管も要するが、まずアドレナリンで浮腫と血管透過性亢進を抑えることが先である。
B「クーリング」: 体温37.5°Cで熱中症の病像ではなく、冷却は的外れである。
D「気管支拡張薬の静脈投与」: 気管支拡張薬は補助的で、循環虚脱には無効である。
E「自動体外式除細動器の使用」: 心電図は頻脈以外に異常がなく、除細動の適応がない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C046（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-48', '正答は B「「死因の究明が病理解剖の主な目的です」」。

病理解剖(剖検)は、死因の解明と診断・治療が適切であったかの検証を目的として、遺族の承諾を得て行われる。得られた知見は医療の質の向上に還元される。

【誤答選択肢の解説】
A「「ご遺体は火葬した後にお返しします」」: 解剖後は遺体を整えて遺族に返す。火葬は遺族が行う。
C「「摘出した臓器は病院で永久に保管します」」: 摘出した臓器の保存には別途の承諾が必要で、無条件に永久保管はできない。
D「「ご遺体は病理解剖後1か月間病院でお預かりします」」: 通常は数時間で終了し、当日中に遺体を返すことができる。
E「「病理解剖を行わないと死亡診断書が発行できません」」: 死亡診断書は解剖の有無にかかわらず交付される。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C048（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-49', '正答は C「現状の食塩摂取量を維持する。」。

慢性腎臓病の食塩摂取量は3g/日以上6g/日未満が目安である。本例は5.2〜5.8g/日で適正範囲にあり、現状を維持するよう伝えるのが正しい。

【誤答選択肢の解説】
A「飲酒を勧める。」: 飲酒習慣のない患者に飲酒を勧める理由はない。
B「運動量を現状より減らす。」: 適度な運動は腎機能の維持にも心血管リスクの低減にも有益で、減らす必要はない。
D「蛋白質摂取量を現状の2倍にする。」: 体重66kgに対し蛋白48〜52g/日は0.7〜0.8g/kgで適正である。2倍にすれば腎への負担が増す。
E「1日総エネルギー摂取量を1,200kcalにする。」: 1,200kcalでは必要量に足りず、蛋白の異化が進んでしまう。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C049（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-5', '正答は E「何がつらくてそう思うのか尋ねる。」。

「死にたい」という訴えには、痛み、孤独、家族への負担感など具体的な苦痛が背景にある。まずその内容を尋ね、受け止めることが出発点になる。そのうえで緩和ケアや精神科的支援につなぐ。

【誤答選択肢の解説】
A「抗うつ薬を処方する。」: 背景を確かめずに薬物療法から入るのは適切でない。
B「今後の診療を拒否する。」: 診療の拒否は許されない。
C「自殺は周囲に迷惑がかかることを説明する。」: 自殺を思いとどまらせようと責めるのは、患者をさらに追い詰める。
D「精神科を受診して相談するよう勧める。」: 専門家への紹介は必要になりうるが、まず担当医が話を聴かずに他へ回すのは適切でない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-53', '正答は E「5」。

興味のあるものを指さして他者と共有する行動は生後10〜12か月ごろに現れる。1歳6か月でこれがないのは明らかな遅れで、自閉スペクトラム症を含めた評価が必要になる。

【誤答選択肢の解説】
A「1」: スキップができるようになるのは5歳ごろである。
B「2」: まねをして〇を描けるようになるのは3歳ごろである。
C「3」: 2語文が出るのは2歳ごろで、1歳6か月で単語のみでも遅れではない。
D「4」: 自分の名前を言えるようになるのは3歳ごろである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C053（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-6', '正答は B「指定感染症による入院」。

感染症法に基づく入院勧告・入院措置による入院の医療費は公費で負担される。1類・2類感染症、新型インフルエンザ等感染症、指定感染症が対象で、まん延防止のために国が負担する仕組みである。

【誤答選択肢の解説】
A「結核の一般医療」: 結核の一般医療は医療費の95%が公費で、5%は自己負担となる。
C「精神障害者の措置入院」: 精神障害者の措置入院は公費負担だが、所得に応じた費用徴収がある。
D「小児慢性特定疾病の外来治療」: 小児慢性特定疾病の医療費助成には所得に応じた自己負担がある。
E「予防接種による健康被害の救済措置」: 予防接種による健康被害への対応は救済給付制度であり、医療費の公費負担の枠組みとは異なる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-C-7', '正答は E「人工呼吸器の管理は看護師が在宅で行う診療補助行為に含まれる。」。

在宅人工呼吸器の管理は、主治医の指示のもとで看護師が行う診療の補助に含まれる。回路の点検、加温加湿、吸引、アラーム対応などを担う。

【誤答選択肢の解説】
A「自己負担は発生しない。」: 医療保険・介護保険いずれでも自己負担が生じる。
B「主治医の指示とは独立して行われる。」: 訪問看護は主治医の交付する訪問看護指示書に基づいて行う。
C「介護保険よりも医療保険を優先して利用する。」: 要介護認定を受けている場合は介護保険が優先される。ただし厚生労働大臣が定める疾病等では医療保険が適用される。
D「要介護認定を受けていない者は対象外である。」: 要介護認定を受けていなくても、医療保険による訪問看護を利用できる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 C007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-1', '正答は C「卵巣」。

卵巣の機能が失われるとエストロゲンとインヒビンが減り、負のフィードバックが外れて下垂体からのFSHが上昇する。高ゴナドトロピン性の無月経で、障害部位は卵巣である。

【誤答選択肢の解説】
A「視床下部」: 視床下部性ではGnRHの分泌低下によりFSH・LHとも低値となる。
B「下垂体」: 下垂体性でもFSHは低値となる。
D「子宮」: 子宮性無月経(Asherman症候群など)ではホルモンは正常である。
E「腟」: 腟の異常(処女膜閉鎖など)は月経血の流出障害で、ホルモンは正常である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-17', '正答は B「塩酸モルヒネ皮下投与」。

食欲は良好で経口摂取に問題がなく、疼痛管理は経口投与から始めるのが原則である。皮下投与は経口摂取ができない場合や急速な調節が必要な場合に選ぶもので、現時点では適切でない。

【誤答選択肢の解説】
A「NSAID経口投与」: 骨転移痛にはNSAIDが有効で、経口から開始するのは適切である。
C「骨転移への放射線照射」: 骨転移巣への放射線照射は除痛効果が高く、適切である。
D「アセトアミノフェン経口投与」: アセトアミノフェンの経口投与も基本的な鎮痛手段として適切である。
E「ビスホスホネート製剤静脈投与」: ビスホスホネートは骨関連事象の抑制と骨痛の軽減に用いられ、適切である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-18', '正答は C「中脳」。

左の動眼神経麻痺(眼瞼下垂・散瞳・対光反射消失・外転位)と、対側である右の片麻痺が同時にみられる。中脳の大脳脚を含む病変で動眼神経核・神経束と錐体路が同時に障害されるWeber症候群である。

【誤答選択肢の解説】
A「放線冠」: 放線冠の障害では対側の片麻痺のみで、動眼神経麻痺は生じない。
B「内包」: 内包の障害も対側の片麻痺のみである。
D「橋」: 橋の障害では外転神経・顔面神経の麻痺と対側片麻痺(Millard-Gubler症候群)となる。
E「延髄」: 延髄の障害では舌下神経麻痺と対側片麻痺(Dejerine症候群)となる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D018（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-2', '正答は C「バンコマイシン」。

バンコマイシンは有効域と中毒域が近く、腎障害と聴器障害のリスクがあるため、トラフ値を測定して投与量を調整する(TDM)。

【誤答選択肢の解説】
A「クリンダマイシン」: クリンダマイシンはTDMの対象ではない。
B「セファゾリン」: セファゾリンも治療域が広くTDMを要さない。
D「ペニシリンG」: ペニシリンGは安全域が広い。
E「レボフロキサシン」: レボフロキサシンもTDMの対象ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-21', '正答は E「「ブドウ果汁入りジュースをやめて、明日の便を観察してください」」。

前日に初めて飲んだブドウ果汁の色素で便が赤紫色に着色したもので、便潜血が陰性であり出血ではない。腹部超音波でも異常がなく機嫌も食欲も良い。原因となった飲料をやめて便の色を確認するよう説明すればよい。

【誤答選択肢の解説】
A「「抗菌薬を処方します」」: 感染性腸炎を示す所見がなく、抗菌薬の適応がない。
B「「生理食塩液の点滴をします」」: 経口摂取は良好で脱水もなく、輸液の必要がない。
C「「圧をかけた浣腸による整復が必要です」」: 腸重積を疑う所見(間欠的啼泣、嘔吐、腹部腫瘤、超音波のtarget sign)がなく、整復の適応はない。
D「「血液検査で貧血の有無を確認しましょう」」: 眼瞼結膜に貧血がなく、便潜血も陰性で、貧血の検索を急ぐ理由がない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D021（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-22', '正答は D「広域抗菌薬投与」。

人工関節置換術の翌朝に37.4°C程度の発熱がみられるのは、手術侵襲に伴う炎症反応(吸収熱)として一般的である。創部に異常はなく、感染を示す所見もない段階で広域抗菌薬を投与するのは適切でない。

【誤答選択肢の解説】
A「離床」: 早期離床は深部静脈血栓症と肺炎の予防になり、適切である。
B「クーリング」: 発熱への対症的なクーリングは適切である。
C「解熱剤投与」: 苦痛が強ければ解熱鎮痛薬を用いてよい。
E「リハビリテーション開始」: 人工膝関節置換術後は早期からのリハビリテーションが機能予後を左右する。適切である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-25', '正答は A「普通型車いす」。

上腕二頭筋と橈側手根伸筋が5、上腕三頭筋が4で、深指屈筋と小指外転筋が0という分布はC7レベルの頸髄損傷にあたる。肘の伸展と手関節の背屈が使えるため、上肢で駆動する普通型車いすでの移動が可能である。

【誤答選択肢の解説】
B「歩行器での歩行」: 体幹筋と下肢筋の随意運動が不可能で、歩行器を用いた歩行はできない。
C「松葉杖での歩行」: 松葉杖歩行も下肢の支持性が必要で不可能である。
D「短下肢装具と杖での歩行」: 短下肢装具は足関節を制御するもので、対麻痺のある本例には対応できない。
E「下顎コントロール電動車いす」: 下顎コントロール電動車いすは上肢がまったく使えない高位頸髄損傷で用いる。本例は上肢が使える。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-28', '正答は C「慢性的な空虚感を抱えている。」。

見捨てられ不安に基づく激しい対人関係の変動、理想化と脱価値化の反復、自傷行為、感情の不安定さがみられ、境界性パーソナリティ症を考える。慢性的な空虚感は診断基準に含まれる特徴である。

【誤答選択肢の解説】
A「繰り返し嘘をつく。」: 繰り返し嘘をつき他者を欺くのは反社会性パーソナリティ症の特徴である。
B「第六感やジンクスにこだわる。」: 第六感やジンクスへのこだわりは統合失調型パーソナリティ症の特徴である。
D「完全癖のため物事を終了できない。」: 完全主義のため物事を終えられないのは強迫性パーソナリティ症の特徴である。
E「自分が注目の的になっていることを求める。」: 常に注目の的でありたいと求めるのは演技性パーソナリティ症の特徴である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D028（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-29', '正答は C「ビタミンB12投与」。

母が胃全摘後に貧血治療薬を自己中断しており、完全母乳栄養の児にビタミンB12が供給されていない。体重増加不良、定頸の遅れ、Moro反射の消失という神経症状を伴う大球性貧血で、ビタミンB12を投与する。

【誤答選択肢の解説】
A「鉄剤投与」: 鉄欠乏では小球性低色素性貧血となり、神経症状は伴わない。
B「葉酸投与」: 葉酸欠乏も大球性貧血をきたすが、母は妊娠前から葉酸を含む栄養補助食品を摂取しており、また神経症状は葉酸欠乏では説明しにくい。
D「赤血球濃厚液輸血」: 輸血は原因治療にならず、B12の補充で速やかに改善する。
E「エリスロポエチン製剤投与」: エリスロポエチン不足による貧血ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D029（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-3', '正答は E「網膜中心動脈閉塞症 — 眼球マッサージ」。

網膜中心動脈閉塞症は網膜が数十分で不可逆的に障害されるため、診断と同時に眼球マッサージを行い、塞栓を末梢へ移動させて灌流の再開を図る。前房穿刺や炭酸脱水酵素阻害薬で眼圧を下げることも併用する。

【誤答選択肢の解説】
A「眼窩蜂巣炎 — 炭酸脱水酵素阻害薬の内服」: 眼窩蜂巣炎は細菌感染で、抗菌薬の全身投与が初期対応となる。炭酸脱水酵素阻害薬は無関係である。
B「急性涙囊炎 — アトロピン点眼」: 急性涙囊炎も細菌感染で、抗菌薬投与と切開排膿を行う。アトロピンは適応がない。
C「急性ぶどう膜炎 — ピロカルピン点眼」: 急性ぶどう膜炎では虹彩後癒着を防ぐため散瞳薬とステロイドを用いる。縮瞳薬のピロカルピンは癒着を助長する。
D「裂孔原性網膜剝離 — 副腎皮質ステロイド点眼」: 裂孔原性網膜剝離は手術による復位が必要で、ステロイド点眼では治らない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-30', '正答は A「ヘパリン」。

胎児心拍確認後の流産を3回繰り返し、抗リン脂質抗体が陽性でAPTTが延長し、下肢血栓症の既往もある。抗リン脂質抗体症候群による反復流産で、次回妊娠中はヘパリンと低用量アスピリンの併用で胎盤の微小血栓を防ぐ。

【誤答選択肢の解説】
B「ビタミンD」: ビタミンDに流産予防の根拠はない。
C「ビタミンK」: ビタミンKはむしろ凝固を促す方向に働き、逆効果である。
D「エストロゲン」: エストロゲンは血栓リスクを高め、この病態では避けたい。
E「黄体ホルモン」: 黄体機能不全による流産ではなく、基礎体温は二相性で高温相も14日間保たれている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D030（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-31', '正答は D「ポリソムノグラフィ」。

日中の耐えがたい眠気、情動により誘発される脱力(情動脱力発作)、入眠時幻覚、睡眠麻痺という四徴が揃っており、ナルコレプシーである。終夜睡眠ポリグラフ検査に続いて反復睡眠潜時検査を行い、入眠潜時の短縮と入眠時レム睡眠期の出現を確認する。

【誤答選択肢の解説】
A「針筋電図」: 針筋電図は筋・神経原性疾患の評価に用いるもので、本例に適応がない。
B「聴性脳幹反応」: 聴性脳幹反応は聴覚路と脳幹機能の評価で、眠気の診断にならない。
C「Holter心電図」: Holter心電図は不整脈による失神との鑑別に使えるが、情動脱力発作や睡眠麻痺は説明できない。
E「ドパミントランスポーターSPECT」: ドパミントランスポーターSPECTはParkinson症候群やLewy小体型認知症の評価に用いる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D031（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-32', '正答は A「赤血球輸血」。

汎血球減少があり骨髄は正形成で3系統に異形成を認めることから骨髄異形成症候群である。Hb6.5g/dLで貧血症状(全身倦怠感)と心雑音が出ており、まず赤血球輸血で症状を改善する。

【誤答選択肢の解説】
B「鉄キレート剤の投与」: 鉄キレート剤は輸血の反復で鉄が蓄積してから用いるもので、現時点では不要である。フェリチンも120ng/mLと正常上限である。
C「同種造血幹細胞移植」: 同種造血幹細胞移植は根治的治療だが、78歳という年齢では適応にならない。
D「副腎皮質ステロイドの投与」: 副腎皮質ステロイドは骨髄異形成症候群の標準治療ではない。
E「トロンボポエチン受容体作動薬の投与」: トロンボポエチン受容体作動薬は免疫性血小板減少症に用いる薬剤である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D032（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-34', '正答は E「指に付着した便の培養結果」。

便培養は感染性腸炎を疑うときの検査で、慢性便秘と排便時の少量の鮮血という病像には結びつかない。優先度は最も低い。

【誤答選択肢の解説】
A「痔核の有無」: 排便時の鮮血の原因として痔核は最も多く、視診・指診で確認する。
B「裂肛の有無」: 硬便による裂肛も鮮血の原因として頻度が高い。
C「直腸内の腫瘍の有無」: 65歳で便通の変化と出血があり、直腸癌の除外は必須である。
D「指への血液付着の有無」: 指に血液が付着するかどうかは、出血の有無と位置を知る直接の情報になる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D034（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-35', '正答は C「たこつぼ心筋症」。

たこつぼ心筋症は心尖部を中心とした一過性の壁運動異常が本態で、左室壁厚の増加はきたさない。この時点の鑑別には含まれない。

【誤答選択肢の解説】
A「Fabry病」: Fabry病は左室肥大をきたす代謝性疾患で、鑑別に含まれる。
B「肥大型心筋症」: 肥大型心筋症は左室壁厚20mmを説明できる代表的疾患である。
D「心アミロイドーシス」: 心アミロイドーシスも壁厚の増加を示し、心電図の低電位との乖離が手がかりになる。
E「高血圧症に伴う心肥大」: 血圧152/90mmHgが持続しており、高血圧性心肥大も当然鑑別に入る。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D035（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-36', '正答は A「子宮はない。」。

乳房は発達しているのに腋毛・陰毛がなく、腟が盲端で子宮腟部を認めず、鼠径部に腫瘤(停留精巣)を触れる。アンドロゲン不応症で、核型は46,XYであり、Müller管抑制因子の作用によって子宮は形成されない。

【誤答選択肢の解説】
B「性腺は卵巣である。」: 性腺は精巣である。鼠径部の腫瘤がそれにあたる。
C「染色体trisomyがある。」: 染色体は46,XYで、トリソミーではない。
D「基礎体温は二相性を示す。」: 排卵がないため基礎体温は一相性である。
E「男性ホルモンが欠損している。」: 男性ホルモンは分泌されているが受容体が働かないため作用しない。欠損しているのではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D036（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-4', '正答は E「老人性全身性アミロイドーシスでは免疫グロブリンが心臓に沈着する。」。

老人性(野生型トランスサイレチン型)全身性アミロイドーシスで沈着するのはトランスサイレチンである。免疫グロブリン軽鎖が沈着するのはAL型アミロイドーシスで、形質細胞疾患を背景とする。

【誤答選択肢の解説】
A「二次性心筋症である。」: 全身疾患に伴って心筋が障害される二次性(特定)心筋症である。正しい。
B「心電図で低電位差を認める。」: 心筋壁は厚くなるのに心電図では低電位を示すという乖離が特徴的である。正しい。
C「心筋生検が診断に有用である。」: 心筋生検でCongo red染色と偏光顕微鏡による緑色複屈折を確認する。正しい。
D「左室拡張障害による心不全を生じる。」: 心筋が硬くなり拡張が妨げられる拘束型の血行動態を示す。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-40', '正答は E「JAK2遺伝子変異陽性」。

赤血球増多に加えて白血球・血小板も増え、エリスロポエチンが基準以下に低下している。二次性ではなく真性多血症を考え、90%以上で認められるJAK2 V617F変異を確認する。

【誤答選択肢の解説】
A「PaO2低下」: PaO2低下による二次性多血症ならエリスロポエチンは上昇するはずで、本例は低値である。
B「血清鉄増加」: 瀉血を要する多血症では鉄が消費され、血清鉄はむしろ低下しやすい。
C「骨髄赤芽球低形成」: 真性多血症の骨髄は3系統とも過形成となる。
D「網血小板比率低下」: 血小板産生が亢進しており、網血小板比率は低下しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D040（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-42', '正答は D「妊娠高血圧腎症」。

妊娠20週以降に高血圧が出現し、蛋白尿(尿蛋白/Cr比1.0g/gCr)を伴っている。妊娠前や妊娠20週までに高血圧はなく、妊娠高血圧腎症と診断する。

【誤答選択肢の解説】
A「妊娠高血圧」: 妊娠高血圧は蛋白尿や臓器障害を伴わない場合の診断名である。本例は蛋白尿がある。
B「HELLP症候群」: HELLP症候群は溶血・肝酵素上昇・血小板減少を伴うが、本例はいずれも認めない。
C「高血圧合併妊娠」: 高血圧合併妊娠は妊娠前または妊娠20週までに高血圧があった場合である。
E「加重型妊娠高血圧腎症」: 加重型妊娠高血圧腎症は、もともと高血圧や腎疾患があった妊婦に蛋白尿や臓器障害が加わった場合をいう。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D042（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-43', '正答は E「肝内胆汁うっ滞」。

術後に中心静脈栄養のみで経過した患者に、胆管拡張や肝腫瘤を伴わない直接ビリルビン優位の黄疸が出現している。長期の絶食と高カロリー輸液による肝内胆汁うっ滞で、経腸栄養の再開が改善につながる。

【誤答選択肢の解説】
A「溶血」: 溶血なら間接ビリルビンが優位となり、貧血の進行や網赤血球増加を伴う。
B「急性胆囊炎」: 急性胆囊炎では発熱と右季肋部痛、Murphy徴候を伴う。本例は無熱で圧痛もない。
C「閉塞性黄疸」: 閉塞性黄疸なら胆管の拡張を認めるが、超音波では拡張がない。
D「転移性肝腫瘍」: 肝内に腫瘤性病変を認めず、転移性肝腫瘍は否定的である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D043（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-45', '正答は B「アセトアミノフェン」。

異型リンパ球の出現、肝脾腫、肝逸脱酵素の上昇を伴う咽頭炎で伝染性単核球症である。特異的治療はなく、解熱鎮痛にアセトアミノフェンを用いる対症療法が基本となる。脾破裂を避けるため激しい運動は控えさせる。

【誤答選択肢の解説】
A「アシクロビル」: アシクロビルは単純ヘルペスや水痘帯状疱疹に用いる薬剤で、EBウイルスによる本症の経過を改善しない。
C「アンピシリン」: アンピシリンは伝染性単核球症で高率に薬疹を誘発するため避ける。
D「オセルタミビル」: オセルタミビルはインフルエンザの治療薬である。
E「プレドニゾロン」: ステロイドは気道閉塞や重篤な血球減少など限られた場合にのみ用いる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D045（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-5', '正答は A「気胸の既往」。

気胸は胸腔内に空気が漏れる疾患で、閉塞性睡眠時無呼吸症候群との関連は知られていない。

【誤答選択肢の解説】
B「昼間の眠気」: 日中の過度の眠気は無呼吸による睡眠の分断を反映する代表的な症状である。
C「頻回の夜間覚醒」: 無呼吸のたびに覚醒反応が起こり、夜間の中途覚醒が増える。
D「治療反応性が不良な高血圧」: 交感神経の亢進により治療抵抗性高血圧の背景となる。
E「夜間発症の心血管イベントの既往」: 夜間から早朝の心筋梗塞・脳卒中・不整脈のリスクが高まる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-51', '正答は A「腹膜透析は可能である。」。

腹膜透析は年齢だけを理由に除外されるものではない。手技を実施できる本人または介助者がいれば高齢者でも選択でき、通院回数が少なく残存腎機能を保ちやすいという利点がある。

【誤答選択肢の解説】
B「夫婦間腎移植は可能である。」: 82歳の妻からの生体腎提供は、ドナーの安全性の面から一般に適応にならない。
C「療法開始後の就業はできない。」: 血液透析でも腹膜透析でも就業は可能で、実際に多くの患者が働いている。
D「療法開始後の旅行はできない。」: 透析施設の手配や装具の携行により旅行も可能である。
E「療法選択前に認知機能評価が必要である。」: パソコン教室の講師を務めており認知機能の低下を疑う所見はない。療法選択に認知機能評価が必須というわけではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D051（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-55', '正答は A「Fabry病」。

小児期からの四肢末端の疼痛、低汗症、下背部・臀部の被角血管腫、蛋白尿があり、母と弟にも同症状、母の兄が透析後に突然死という家族歴からFabry病を考える。X連鎖性のα-ガラクトシダーゼA欠損症で、酵素補充療法がある。

【誤答選択肢の解説】
B「線維筋痛症」: 線維筋痛症は広範な慢性疼痛が主体で、低汗症や被角血管腫、蛋白尿は伴わない。
C「Alport症候群」: Alport症候群は血尿と難聴を主徴とし、四肢痛や被角血管腫はない。
D「Bartter症候群」: Bartter症候群は低カリウム血症とアルカローシスを示すが、本例の電解質は正常である。
E「Sjögren症候群」: Sjögren症候群は乾燥症状が主体で、家族性の集積や被角血管腫は伴わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D055（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-57', '正答は D「Alzheimer型認知症」。

3か月かけて緩徐に進行する意欲低下と作業能率の低下があり、周囲からは「ぼーっとしている」と見える。うつ病の既往があるため見誤られやすいが、経過と抗不安薬・睡眠薬でも改善しない点からAlzheimer型認知症を考える。高齢者では認知症の初期がうつ状態として現れることが少なくない。

【誤答選択肢の解説】
A「うつ病」: 過去2回のうつ病エピソードは薬物療法で6か月ほどで回復しており、今回は薬剤を増量しても悪化している点が異なる。
B「慢性硬膜下血腫」: 慢性硬膜下血腫は頭部外傷の既往と経過中の局所神経徴候を伴うことが多い。
C「甲状腺機能低下症」: 甲状腺機能低下症も認知機能低下をきたすが、寒がり・便秘・徐脈・浮腫などの身体所見を伴う。
E「精神作用物質使用による精神および行動の障害」: 処方された抗不安薬・睡眠薬の影響は考慮すべきだが、増量前の2か月前から症状が始まっている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D057（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-59', '正答は A「梅毒」。

無痛性で硬い潰瘍(硬性下疳)と無痛性の鼠径リンパ節腫脹は梅毒第1期の典型像である。痛みがないため受診が遅れやすく、放置しても数週で自然に消退するが感染は進行する。

【誤答選択肢の解説】
B「淋菌感染症」: 淋菌感染症は女性では帯下や排尿時痛が主で、潰瘍は作らない。
C「性器ヘルペス」: 性器ヘルペスは強い疼痛を伴う多発性の浅い潰瘍で、初感染では発熱も伴う。
D「クラミジア感染症」: クラミジア感染症は無症状か軽度の帯下増加が主体で、潰瘍は形成しない。
E「尖圭コンジローマ」: 尖圭コンジローマは乳頭状に隆起する腫瘤で、潰瘍ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D059（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-6', '正答は E「アセトン血性嘔吐症」。

アセトン血性嘔吐症(自家中毒、周期性嘔吐症)は2〜10歳の幼児期に発症し、感染や心理的ストレスを契機に反復する。思春期までにほとんどが自然寛解する。

【誤答選択肢の解説】
A「片頭痛」: 片頭痛は成人期にも持続し、女性では月経周期と関連して続くことが多い。
B「過換気症候群」: 過換気症候群は思春期以降の発症が多い。
C「起立性調節障害」: 起立性調節障害は思春期に発症する。
D「神経性食思不振症」: 神経性やせ症は思春期以降に発症する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-61', '正答は B「膜性腎症」。

高度の蛋白尿(2.5g/gCr)がありながら血尿に乏しく、血圧も腎機能も保たれている。中高年に発症するネフローゼ症候群の原因として最も多い膜性腎症を考える。悪性腫瘍の合併にも注意する。

【誤答選択肢の解説】
A「IgA腎症」: IgA腎症は顕微鏡的血尿が必発で、赤血球円柱を伴うことが多い。本例は潜血陰性である。
C「多発性囊胞腎」: 多発性囊胞腎は両腎に多数の囊胞ができ腎腫大をきたす。右腎の2cm大の所見だけでは合致しない。
D「微小変化型ネフローゼ症候群」: 微小変化型は小児と若年成人に多く、急激な浮腫を伴う。本例は浮腫がなく緩徐な経過である。
E「特発性半月体形成性糸球体腎炎」: 半月体形成性糸球体腎炎は数週で腎機能が急速に悪化し、血尿と赤血球円柱を伴う。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D061（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-62', '正答は C「食道」。

下咽頭癌と食道癌はいずれも飲酒・喫煙を共通の危険因子とし、同じ扁平上皮に発生する。とくに飲酒で顔が赤くなる体質(アセトアルデヒド脱水素酵素2の活性低下)がありながら飲酒を続けた例では食道扁平上皮癌のリスクが著しく高く、重複癌の頻度が最も高い。

【誤答選択肢の解説】
A「口腔」: 口腔も同じ危険因子を共有するが、食道ほど頻度は高くない。
B「喉頭」: 喉頭も領域癌化の対象だが、下咽頭癌後の重複癌としては食道が最多である。
D「胃」: 胃癌の主要な危険因子はH. pylori感染で、飲酒・喫煙との関連は相対的に弱い。
E「十二指腸」: 十二指腸癌は稀で、飲酒・喫煙との関連も知られていない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D062（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-64', '正答は A「1%未満」。

転座を伴わない標準型18トリソミーは減数分裂時の不分離による偶発的な事象で、両親の核型は正常である。再発率は1%未満とされ、主に母体年齢に依存する。

【誤答選択肢の解説】
B「5%程度」: 5%程度になるのは均衡型転座保因者の一部の場合である。
C「25%程度」: 25%は常染色体潜性遺伝疾患の再発率である。
D「50%程度」: 50%は常染色体顕性遺伝疾患の再発率である。
E「ほぼ100%」: ほぼ100%となるのはRobertson転座で同一染色体同士が結合している特殊な場合などである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D064（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-7', '正答は D「肺線維症」。

肺線維症は間質の線維化であり、胸腔内に膿がたまる膿胸の原因にはならない。

【誤答選択肢の解説】
A「肺炎」: 肺炎に伴う傍肺炎性胸水が感染して膿胸に移行するのが最も多い経路である。
B「胸部外傷」: 胸部外傷による血胸に感染が加わると膿胸になる。
C「食道穿孔」: 食道穿孔では消化管内容と細菌が縦隔・胸腔に漏れて膿胸をきたす。
E「降下性壊死性縦隔炎」: 歯性感染や扁桃周囲膿瘍から下降した降下性壊死性縦隔炎は縦隔・胸腔に波及する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-D-8', '正答は D「βラクタム系抗菌薬が有効である。」。

Legionellaは細胞内寄生菌で、細胞内に到達しないβラクタム系抗菌薬は無効である。キノロン系やマクロライド系を用いる。

【誤答選択肢の解説】
A「集団感染がみられる。」: 冷却塔や循環式浴槽、給湯設備を介した集団感染が知られている。
B「中枢神経系症状を呈する。」: 意識障害や失見当識など中枢神経症状を伴いやすい。
C「低ナトリウム血症を生じる。」: 低ナトリウム血症は他の肺炎より高頻度で、診断の手がかりになる。
E「迅速診断に尿中抗原検出キットが有用である。」: 尿中抗原検査は血清群1に対して感度が高く、迅速診断に有用である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 D008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-1', '正答は B「予測される入院費」。

入院診療計画書には、傷病名、症状、治療計画、検査内容と日程、手術内容と日程、推定入院期間、看護計画、リハビリテーションの計画などを記載する。費用の見込みは記載事項に含まれない。

【誤答選択肢の解説】
A「入院時の傷病名」: 入院時の傷病名は記載が求められる。
C「推定される入院期間」: 推定される入院期間は記載事項である。
D「退院に向けた支援計画」: 退院に向けた支援計画も記載が求められる。
E「入院中に計画される検査」: 入院中に計画される検査の内容と日程も記載事項である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-10', '正答は D「頭位変換時に眼振を示す。」。

良性発作性頭位めまい症は、頭位を変えたときに数十秒続く回転性めまいと眼振が誘発される。Dix-Hallpike法などで頭位変換時の眼振を確認して診断する。

【誤答選択肢の解説】
A「難聴を伴う。」: 難聴や耳鳴は伴わない。伴う場合はMeniere病などを考える。
B「小児に好発する。」: 中高年に多く、小児には稀である。
C「一過性の意識消失を伴う。」: 意識消失は伴わない。伴う場合は失神の鑑別が必要である。
E「浮遊耳石は半規管由来である。」: 浮遊耳石は卵形囊の耳石器から剝がれたもので、半規管由来ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-11', '正答は E「ボトルに検体を注入後、ボトル内の培地と血液を転倒混和する。」。

ボトルに血液を注入した後は転倒混和して培地と血液をよく混ぜる。混和が不十分だと凝固して菌の検出感度が落ちる。

【誤答選択肢の解説】
A「抗菌薬投与後に検体を採取する。」: 抗菌薬投与前に採取する。投与後では菌が検出されにくくなる。
B「2セットとも1か所から採血する。」: 汚染菌と真の菌血症を区別するため、2セットは別々の部位から採取する。
C「採血部位の皮膚消毒後、消毒薬が乾く前に採血を行う。」: 消毒薬が乾燥してから穿刺する。乾く前では殺菌効果が十分でない。
D「採取後の血液は好気ボトル、嫌気ボトルの順に入れる。」: 注射器で採血した場合は嫌気ボトルから先に入れる(空気の混入を避けるため)。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-12', '正答は A「肩関節」。

肩関節は球関節で、屈曲・伸展・外転・内転に加えて内旋・外旋という回旋運動の可動域を測定する。

【誤答選択肢の解説】
B「肘関節」: 肘関節は蝶番関節で屈曲・伸展を測る。前腕の回内・回外は前腕として別に測定する。
C「手関節」: 手関節は掌屈・背屈と橈屈・尺屈を測る。
D「膝関節」: 膝関節は屈曲・伸展を測る。
E「足関節」: 足関節は背屈・底屈を測る。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E012（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-13', '正答は A「高血糖」。

高血糖では糸球体で濾過されたブドウ糖が近位尿細管の再吸収能を超えて尿細管腔に残り、浸透圧により水の再吸収を妨げて多尿となる。糖尿病の口渇・多飲・多尿はこの機序による。

【誤答選択肢の解説】
B「心因性多飲」: 心因性多飲は水の過剰摂取による水利尿で、尿浸透圧は低い。
C「腎性尿崩症」: 腎性尿崩症は集合管がADHに反応せず水を再吸収できない水利尿である。
D「中枢性尿崩症」: 中枢性尿崩症もADHの分泌不足による水利尿である。
E「低カリウム血症」: 低カリウム血症は尿濃縮力の低下をきたすが、浸透圧利尿ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E013（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-15', '正答は D「ペスト」。

ペストはペスト菌(Yersinia pestis)による感染症で、ノミを介してネズミから人に伝播する。14世紀のヨーロッパで大流行し、皮膚が黒ずんで死に至ることから黒死病と呼ばれた。感染症法の1類感染症である。

【誤答選択肢の解説】
A「結核」: 結核も歴史的に大きな被害をもたらしたが黒死病とは呼ばれない。
B「コレラ」: コレラは19世紀以降に世界的流行を繰り返した。
C「天然痘」: 天然痘は世界的に流行したが1980年に根絶宣言が出された。
E「発疹チフス」: 発疹チフスはシラミが媒介し、戦争や飢饉に伴って流行した。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E015（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-17', '正答は E「情報バイアスは統計的手法で調整できる。」。

情報バイアスは測定や聞き取りの段階で生じる系統誤差で、いったん歪んだデータを後から統計的に補正することはできない。設計段階で盲検化や標準化した測定手順によって防ぐしかない。

【誤答選択肢の解説】
A「情報バイアスは対象者から情報を得る際に生じる。」: 情報バイアスは対象者から情報を得る過程で生じる。正しい。
B「選択バイアスは対象者の選択方法から生じる。」: 選択バイアスは対象者をどう選ぶかによって生じる。正しい。
C「交絡因子は研究デザインにより調整できる。」: 交絡因子は限定・マッチング・層別化・多変量解析などで調整できる。正しい。
D「交絡因子は原因と結果の両方に関連する。」: 交絡因子は曝露と結果の両方に関連し、かつ因果の中間段階にないものをいう。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-19', '正答は C「有能な人材への業務の集中」。

有能な人材に業務を集中させると、その人の疲労と負荷が増してかえって誤りが起きやすくなり、不在時に対応できる者がいなくなる。防止策にならない。

【誤答選択肢の解説】
A「医療安全を確保するための研修制度」: 研修による知識と技能の維持は基本的な対策である。
B「各種マニュアルの定期的な見直し」: 実態に合わなくなったマニュアルは守られないため、定期的な見直しが要る。
D「危険予知トレーニング」: 起こりうる危険を先に想像して備える訓練は有効である。
E「指さし呼称確認」: 指さし呼称は確認行為を意識化して見落としを減らす。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-21', '正答は D「食道裂孔ヘルニア」。

内ヘルニアは腹腔内の裂孔や陥凹に腸管などが入り込むもので、体表からは触れない。食道裂孔ヘルニアは横隔膜の食道裂孔から胃が縦隔側へ入り込む内ヘルニアである。

【誤答選択肢の解説】
A「鼠径ヘルニア」: 鼠径ヘルニアは腹壁を通って体表に脱出する外ヘルニアである。
B「大腿ヘルニア」: 大腿ヘルニアも鼠径靱帯の下から体表へ脱出する外ヘルニアである。
C「閉鎖孔ヘルニア」: 閉鎖孔ヘルニアは骨盤の閉鎖孔から大腿内側へ脱出する外ヘルニアである。
E「腹壁瘢痕ヘルニア」: 腹壁瘢痕ヘルニアは手術創部の腹壁欠損から脱出する外ヘルニアである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E021（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-22', '正答は E「エネルギーと栄養素の摂取量の基準を示すものである。」。

日本人の食事摂取基準は、健康の保持増進と生活習慣病の予防のために、エネルギーと各栄養素の摂取量の基準を示したものである。5年ごとに改定される。

【誤答選択肢の解説】
A「個人には適用されない。」: 集団だけでなく個人の食事改善にも用いる。
B「65歳未満を対象とする。」: 乳児から高齢者(75歳以上を含む)まで全年齢を対象とする。
C「妊娠や授乳期間については扱わない。」: 妊婦・授乳婦についても付加量が示されている。
D「目標とするBMIは18〜20の範囲である。」: 目標とするBMIは年齢区分ごとに定められ、18〜49歳で18.5〜24.9、65歳以上で21.5〜24.9などとなっている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-23', '正答は A「腎結石」。

蓄尿症状とは頻尿・尿意切迫感・尿失禁など尿をためる過程の障害である。腎結石は側腹部痛や血尿をきたすが、膀胱の蓄尿機能そのものには影響しない。

【誤答選択肢の解説】
B「脳梗塞」: 脳梗塞では排尿の抑制が外れて過活動膀胱となり、頻尿や切迫性尿失禁を生じる。
C「脊髄損傷」: 脊髄損傷では排尿筋過活動により蓄尿症状をきたす。
D「Parkinson病」: Parkinson病でも過活動膀胱による夜間頻尿や切迫性尿失禁がみられる。
E「間質性膀胱炎」: 間質性膀胱炎は膀胱の伸展に伴う疼痛と頻尿が主症状である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E023（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-24', '正答は C「急性好酸球性肺炎」。

急性好酸球性肺炎は喫煙開始や再開、本数の急増を契機に発症することが多く、喫煙が発症因子として知られている。禁煙により再発が防げる。

【誤答選択肢の解説】
A「過敏性肺炎」: 過敏性肺炎は真菌や鳥の蛋白など抗原の反復吸入による。喫煙はむしろ発症を抑える方向に働くとされる。
B「レジオネラ肺炎」: レジオネラ肺炎は環境中の水系からの感染で、喫煙は重症化の因子ではあるが発症因子とは位置づけられない。
D「非結核性抗酸菌症」: 非結核性抗酸菌症は中年女性の非喫煙者に多い。
E「マイコプラズマ肺炎」: マイコプラズマ肺炎は飛沫感染で、喫煙との関連は知られていない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-26', '正答は D「本人の意思」。

胃瘻造設のような侵襲的な処置の可否は、本人の意思が最も優先される。あらかじめ本人が文書で意思表示していれば、それを尊重して方針を決める。

【誤答選択肢の解説】
A「要介護度」: 要介護度は必要な介護量の指標であって、本人の希望に優先しない。
B「医師の判断」: 医師の医学的判断は選択肢と見通しを示すためのもので、本人の意思に代わるものではない。
C「家族の希望」: 家族の希望は本人の意思が確認できない場合に推定意思を探る手がかりとなるが、本人の明示の意思には優先しない。
E「受け入れ施設の状況」: 受け入れ施設の状況は療養場所の調整に関わる事情にすぎない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E026（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-27', '正答は D「トリコモナス腟炎」。

黄色泡沫状の帯下と外陰の瘙痒はトリコモナス腟炎に特徴的である。性行為で伝播するためパートナーの同時治療が必要で、メトロニダゾールを用いる。

【誤答選択肢の解説】
A「萎縮性腟炎」: 萎縮性腟炎は閉経後のエストロゲン低下による乾燥と接触出血が主体で、40歳では考えにくい。
B「細菌性腟炎」: 細菌性腟症は灰白色でさらさらした帯下と魚臭が特徴で、瘙痒は乏しい。
C「カンジダ腟炎」: カンジダ腟炎は白色の酒粕様・カッテージチーズ様帯下と強い瘙痒、外陰の発赤を伴う。本例は帯下の性状が異なり発赤もない。
E「クラミジア子宮頸管炎」: クラミジア子宮頸管炎は無症状のことが多く、帯下が黄色泡沫状にはならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E027（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-28', '正答は A「「リスクマネジャーへの報告が必要です」」。

インスリン10単位の指示に対して100単位を混注し、重症低血糖を起こした重大なインシデントである。事実を組織として共有し原因を分析して再発を防ぐため、リスクマネジャーへ報告する必要がある。個人を責めるのではなく仕組みを直すのが目的である。

【誤答選択肢の解説】
B「「あなたの起こしたことなので、私には関係がありません」」: 指示を出した主治医にも確認体制の責任があり、担当医個人の問題として切り離すことはできない。
C「「家族に余計な心配をかけたくないので、連絡は控えておきましょう」」: 患者・家族への説明は医療安全の基本であり、心配をかけたくないという理由で省いてよいものではない。
D「「診療録には、当初の指示どおり10単位混注したと記載してください」」: 事実と異なる記載は診療録の改ざんであり、絶対に許されない。
E「「患者さんに聞かれたら意識障害の原因は不明と答えることにしましょう」」: 原因が判明しているのに不明と説明するのは虚偽の説明で、信頼を根本から損なう。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E028（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-29', '正答は E「「大したことではないので早く忘れた方がいいです」」。

「大したことではない」「早く忘れたほうがよい」という言葉は被害を矮小化し、自責感を強めて回復を妨げる。被害者の語りを受け止め、安全の確保と必要な検査・支援につなぐ姿勢が求められる。

【誤答選択肢の解説】
A「「自分を責める必要はありません」」: 自責感を和らげる言葉で、適切である。
B「「病院に来るのは勇気がいりましたね」」: 受診という行動を肯定的に認める言葉で、適切である。
C「「婦人科医師の診察を希望されますか」」: 診察の希望を確認し本人に選択権を渡す言葉で、適切である。
D「「お辛いのによく話してくださいました」」: 話してくれたことをねぎらう言葉で、適切である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E029（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-3', '正答は B「残った注射薬は研修医が1人で破棄する。」。

麻薬注射薬の残液を廃棄する際は、麻薬管理者または麻薬施用者の立会いのもと、複数名で確認して廃棄し記録を残す。研修医が1人で処理してはならない。

【誤答選択肢の解説】
A「鍵をかけた堅固な設備に保管する。」: 麻薬は鍵をかけた堅固な設備内に保管することが麻薬及び向精神薬取締法で定められている。
C「紛失した場合は都道府県知事に届け出る。」: 事故(紛失・盗難・破損)が生じた場合は速やかに都道府県知事へ届け出る。
D「施用・交付時に診療録に必要事項を記載する。」: 施用・交付にあたっては診療録に品名・数量・年月日などを記載する。
E「施用・交付には麻薬施用者免許が必要である。」: 麻薬の施用・交付には都道府県知事の免許を受けた麻薬施用者であることが必要である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-30', '正答は E「保護者が同意しなくても当人が同意すれば研究参加は可能である。」。

16歳未満の未成年者を対象とする研究では、代諾者(保護者)からのインフォームド・コンセントが必要である。本人からはインフォームド・アセントを得るが、それだけで参加させることはできない。

【誤答選択肢の解説】
A「患者への説明は理解ができるように行う。」: 年齢と理解力に応じた平易な説明を行うことが求められる。正しい。
B「インフォームド・アセントを得る必要がある。」: 理解力のある未成年者からはアセントを得る。正しい。
C「同意書は記名・捺印もしくは自署名が必要である。」: 同意書には記名・捺印または自署名が必要である。正しい。
D「採血行為による侵襲の程度は倫理審査委員会で判断する。」: 侵襲の程度の評価を含め、研究計画の妥当性は倫理審査委員会が判断する。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E030（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-31', '正答は E「ベンゾジアゼピン系薬剤が有効である。」。

手術翌日の夜間に急に始まったつじつまの合わない言動で、術後せん妄である。ベンゾジアゼピン系薬剤はせん妄を悪化させ遷延させるため、原則として用いない。必要なら少量の抗精神病薬を検討する。

【誤答選択肢の解説】
A「幻視を伴う。」: 幻視を伴うことが多い。正しい。
B「日中にも起こる。」: 夜間に目立つが日中にも起こりうる。正しい。
C「身体疾患が原因となる。」: 手術侵襲・疼痛・脱水・薬剤など身体的要因が原因となる。正しい。
D「意識レベルが短時間で変動する。」: 意識レベルが数時間単位で変動するのがせん妄の特徴で、認知症との鑑別点になる。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E031（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-32', '正答は A「看護師 — 抗菌薬の処方」。

薬剤の処方は医師・歯科医師の業務であり、看護師は行えない。看護師は与薬、観察、口腔ケア、体位管理などを担う。

【誤答選択肢の解説】
B「管理栄養士 — 食形態の評価」: 管理栄養士が嚥下機能に合わせた食形態を評価・調整するのは適切である。
C「言語聴覚士 — 嚥下訓練」: 言語聴覚士が嚥下機能を評価し訓練を行うのは適切である。
D「薬剤師 — 内服薬の剤型検討」: 薬剤師が嚥下しやすい剤型(簡易懸濁・粉砕の可否など)を検討するのは適切である。
E「理学療法士 — 呼吸リハビリテーション」: 理学療法士が排痰や呼吸機能の維持を目的とした呼吸リハビリテーションを行うのは適切である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E032（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-35', '正答は B「会陰部の異常感覚」。

会陰部の感覚障害(サドル型知覚障害)は馬尾症候群の所見で、正中に大きく脱出したヘルニアで生じる。本例は第4/5腰椎間の右側ヘルニアで片側のL5神経根症状を呈しており、会陰部の異常感覚は認められない。

【誤答選択肢の解説】
A「疼痛性跛行」: 疼痛のため患側をかばう疼痛性跛行はみられる。
C「右下腿外側の感覚鈍麻」: L5神経根領域である下腿外側の感覚鈍麻はみられる。
D「右母趾背屈筋力の低下」: 長母趾伸筋はL5支配で、母趾背屈の筋力低下はL5障害の典型である。
E「右下肢伸展挙上テスト陽性」: 下肢伸展挙上テスト(SLR)は坐骨神経の伸張により疼痛が誘発され陽性となる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E035（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-39', '正答は C「下痢」。

モルヒネの代表的な副作用は便秘であり、下痢ではない。便秘はほぼ必発で耐性も生じないため、開始と同時に緩下剤を予防的に併用する。

【誤答選択肢の解説】
A「黄疸」: 肝転移があり、進行に伴う黄疸に注意する。
B「悪心」: 悪心・嘔吐はモルヒネ開始初期によくみられ、制吐薬の併用を検討する。
D「下肢麻痺」: 腰椎転移による脊髄圧迫は下肢麻痺と膀胱直腸障害を招く緊急事態で、警戒が要る。
E「呼吸困難」: 肺転移の進行に加え、モルヒネによる呼吸抑制にも注意する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E039（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-4', '正答は D「明日から食後のジョギングを始めるつもりでいる。」。

準備期は1か月以内に行動を始める意思があり、具体的な準備をしている段階である。「明日から食後のジョギングを始めるつもりでいる」がこれにあたる。

【誤答選択肢の解説】
A「毎食の塩辛い漬物がやめられない。」: 問題を認識しつつ変える意思がないのは前熟考期にあたる。
B「1週間、食事の塩分制限を続けている。」: すでに1週間実行しているのは実行期(6か月未満)である。
C「1年以上、ウォーキングを毎日続けている。」: 1年以上継続しているのは維持期である。
E「半年後にくる誕生日から間食を減らそうと思っている。」: 半年後からと考えているのは熟考期にあたる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-5', '正答は B「患者は同意をいつでも撤回できる。」。

同意はいつでも撤回でき、撤回によって不利益な扱いを受けることはない。この撤回可能性が保証されて初めて、同意が自由な意思に基づくものになる。

【誤答選択肢の解説】
A「本人と家族の同意が必要である。」: 意思決定能力のある成人では本人の同意で足り、家族の同意は要件ではない。
C「予後についての説明は必要でない。」: 予後は治療を選ぶうえで欠かせない情報で、説明の対象である。
D「医師の過失責任を回避する目的で行う。」: 目的は患者の自己決定の支援であり、医師の免責のためではない。
E「最新の治療法を推奨しなければならない。」: 最新であることが最善とは限らず、選択肢を示して患者が選べるようにする。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-6', '正答は E「側臥位で両膝を両手で抱え首を前屈した体位をとらせる。」。

腰椎穿刺は側臥位で膝を抱えて首を前屈させ、背中を丸めることで椎間腔を広げる。この体位をとらせることが穿刺成功の鍵になる。

【誤答選択肢の解説】
A「脳ヘルニアの患者が適応である。」: 脳ヘルニアあるいはその切迫がある場合、腰椎穿刺は脳ヘルニアを誘発するため禁忌である。
B「Jacoby線より上の腰椎間腔を穿刺する。」: Jacoby線(両側腸骨稜を結ぶ線)は第4腰椎棘突起の高さで、脊髄円錐を避けるためこれより下の椎間で穿刺する。
C「脳脊髄液をシリンジで吸引して採取する。」: 髄液は自然滴下で採取する。吸引すると脳ヘルニアや神経根損傷の危険がある。
D「細い穿刺針の方が穿刺後頭痛のリスクが高い。」: 細い針のほうが硬膜の穿刺孔が小さく、穿刺後頭痛は起こりにくい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-7', '正答は A「公衆衛生」。

医師法第1条は「医師は、医療及び保健指導を掌ることによつて公衆衛生の向上及び増進に寄与し、もつて国民の健康な生活を確保するものとする」と定めている。医師の職責が個々の診療にとどまらず公衆衛生に及ぶことを示した条文である。

【誤答選択肢の解説】
B「社会保障」: 社会保障は憲法第25条の文脈で用いられる語である。
C「生命科学」: 生命科学は法文の用語ではない。
D「適正診療」: 適正診療という語は条文にない。
E「臨床医学」: 臨床医学も条文の用語ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-E-8', '正答は D「治験参加への同意書が未取得の段階で治験用の降圧薬を使用した。」。

治験は被験者の自由意思による文書同意が絶対の前提で、同意が取得できていない段階で治験薬を使うことは許されない。救命に必要なのは標準治療であって治験薬ではない。

【誤答選択肢の解説】
A「術前に家族へ連絡を試みた。」: 家族への連絡を試みることは、本人の意思の推定と情報収集の両面で適切である。
B「院内で緊急手術の必要性について討議した。」: 緊急時に院内で必要性を検討し記録に残すことは適切である。
C「通院歴のある医療機関へ診療情報の問い合わせをした。」: 通院先へ診療情報を照会することは、救命のために必要な範囲で許される。
E「輸血開始時までに血液型が判明しなかったためO型Rh(−)の赤血球輸血を行った。」: 血液型判明前の緊急輸血にはO型RhD陰性の赤血球を用いる。適切である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 E008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-1', '正答は C「ビタミンC — 出血傾向」。

ビタミンCはコラーゲン合成に必要で、欠乏すると血管の脆弱化により歯肉出血や皮下出血をきたす(壊血病)。

【誤答選択肢の解説】
A「マグネシウム — 味覚障害」: 味覚障害をきたすのは亜鉛欠乏である。
B「ビタミンA — ペラグラ」: ペラグラはナイアシン(ビタミンB3)欠乏による。
D「カルシウム — 貧血」: 貧血をきたすのは鉄・ビタミンB12・葉酸の欠乏である。
E「亜鉛 — 夜盲」: 夜盲はビタミンA欠乏による。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-13', '正答は A「現金が給付される。」。

公的医療保険の給付は療養の給付という現物給付が原則である(傷病手当金や出産育児一時金など一部に現金給付はあるが、医療そのものは現物で給付される)。

【誤答選択肢の解説】
B「主たる財源は保険料である。」: 財源は保険料が主で、これに公費と患者負担が加わる。正しい。
C「被用者保険の加入者が最も多い。」: 被用者保険(健康保険組合・協会けんぽ・共済)の加入者が最も多い。正しい。
D「国民はいずれかの医療保険に加入する。」: 国民皆保険により、国民はいずれかの医療保険に加入する。正しい。
E「小学校就学前の自己負担は2割である。」: 小学校就学前の自己負担割合は2割である。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F013（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-14', '正答は C「顆粒円柱」。

顆粒円柱は尿細管上皮の変性物を含む病的円柱で、1視野に1つでも認めれば腎実質の障害を示唆する。

【誤答選択肢の解説】
A「赤血球」: 赤血球は1視野に4個以下なら正常範囲である。
B「白血球」: 白血球も1視野に4個以下なら正常範囲である。
D「硝子円柱」: 硝子円柱は健常者でも運動後や脱水時に出現し、少数なら異常ではない。
E「扁平上皮」: 扁平上皮は外尿道口由来の混入で、少数なら意義がない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F014（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-18', '正答は D「骨格筋からアミノ酸が放出される。」。

絶食が続くと糖新生の基質を確保するため、骨格筋の蛋白が分解されてアラニンなどのアミノ酸が血中に放出される。これが肝でグルコースに変換される。

【誤答選択肢の解説】
A「血中のケトン体が低下する。」: 脂肪酸のβ酸化が亢進し、血中ケトン体はむしろ上昇する。
B「肝臓にグルコースが流入する。」: 肝はグルコースを取り込むのではなく、糖新生とグリコーゲン分解で放出する。
C「肝臓から骨格筋に乳酸が運ばれる。」: 乳酸は骨格筋から肝へ運ばれ糖新生に使われる(Cori回路)。向きが逆である。
E「中枢神経で遊離脂肪酸が利用される。」: 遊離脂肪酸は血液脳関門を通れない。飢餓時の中枢神経はケトン体を利用する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F018（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-19', '正答は B「黒色壊死は温存する。」。

黒色壊死(エスカー)は感染源となり創傷治癒を妨げるため、原則としてデブリードマンで除去する。温存するのは血流の乏しい踵部の乾燥壊死など限られた場合である。

【誤答選択肢の解説】
A「異物を除去する。」: 異物は感染と創傷治癒遅延の原因になるため除去する。正しい。
C「深部臓器の損傷を確認する。」: 深部臓器や血管・神経・腱の損傷の有無を確認することは必須である。正しい。
D「非感染創は一期的に縫合する。」: 汚染のない新鮮な創は一期的縫合でよい。正しい。
E「III度熱傷では植皮が必要である。」: III度熱傷は真皮全層を越えるため自然上皮化せず、植皮を要する。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-20', '正答は D「パラシュート反射」。

パラシュート反射は生後6〜9か月ごろに出現し、以後生涯持続する姿勢反射である。10か月児では認められるのが正常で、欠如は運動発達の異常を示唆する。

【誤答選択肢の解説】
A「吸啜反射」: 吸啜反射は生後4〜6か月ごろに消失する原始反射である。
B「Moro反射」: Moro反射も生後4〜6か月ごろに消失する。
C「手掌把握反射」: 手掌把握反射も生後4〜6か月ごろに消失する。
E「非対称性緊張性頸反射」: 非対称性緊張性頸反射も生後4〜6か月ごろに消失する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F020（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-21', '正答は B「受精2〜8週」。

器官形成期にあたる受精後2〜8週は、放射線被曝により形態異常(奇形)が生じうる時期である。しきい値はおよそ100〜200mGyとされる。

【誤答選択肢の解説】
A「受精0〜8日」: 受精後8日までは着床前期で、影響が出れば流産、出なければ正常に発育する「全か無か」の時期である。
C「受精8〜15週」: 受精8〜15週は中枢神経の発達期で、精神発達遅滞のリスクが問題となるが形態異常は少ない。
D「受精15〜25週」: 受精15〜25週も中枢神経への影響が主で、感受性は低下する。
E「受精25週以降」: 受精25週以降は形態異常のリスクはほぼない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F021（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-22', '正答は C「医療観察法は自殺念慮の強い場合の入院に関する法律である。」。

医療観察法は、心神喪失または心神耗弱の状態で重大な他害行為を行った者に対し、適切な医療と社会復帰を確保するための法律である。自殺念慮に関する入院を定めたものではない。

【誤答選択肢の解説】
A「精神科診療所の数は増加傾向にある。」: 精神科診療所は増加傾向にある。正しい。
B「OECD諸国と比べて人口当たりの精神科病床数が多い。」: 我が国の人口当たり精神科病床数はOECD諸国のなかで最も多い水準にある。正しい。
D「精神科救急医療システムは都道府県や政令指定都市が取り組む。」: 精神科救急医療システムの整備は都道府県・政令指定都市が担う。正しい。
E「精神保健福祉センターでは精神障害者福祉手帳の障害等級の判定を行う。」: 精神保健福祉センターは精神障害者保健福祉手帳の等級判定などを行う。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-23', '正答は A「パッチテスト」。

パッチテストは接触皮膚炎などIV型(遅延型)アレルギーを調べる検査で、IgEが介在する即時型食物アレルギーの検査ではない。

【誤答選択肢の解説】
B「プリックテスト」: プリックテストは皮膚に抗原を入れて15分後の膨疹を見る即時型の検査である。
C「食物経口負荷試験」: 食物経口負荷試験は即時型食物アレルギーの確定診断・耐性獲得の確認に用いる標準的検査である。
D「ヒスタミン遊離試験」: ヒスタミン遊離試験は患者の好塩基球から抗原刺激でヒスタミンが遊離するかを見る即時型の検査である。
E「抗原特異的IgE検査」: 抗原特異的IgE検査は即時型アレルギーの基本検査である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F023（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-24', '正答は D「生命表から作成した生存率曲線下の面積」。

平均寿命は0歳の平均余命であり、生命表の生存数曲線の下の面積を出生数で割ったものに等しい。実際に死亡した人の年齢の平均ではない。

【誤答選択肢の解説】
A「その年の死亡者の年齢の平均値」: その年の死亡者の年齢の平均は死亡時年齢の平均であって平均寿命ではない。
B「その年の最も死亡率の高かった年齢」: 最も死亡率の高い年齢は最高齢層になる。
C「その年に最も多くの死亡者がいた年齢」: 最も死亡者が多かった年齢は最頻死亡年齢である。
E「生命表から算出した生存率が50%になった年齢」: 生存率が50%になる年齢は寿命中位数と呼ばれ、平均寿命とは別の指標である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-25', '正答は D「有機溶剤中毒」。

生物学的モニタリングは、体内に取り込まれた化学物質やその代謝物を血液・尿で測る手法である。有機溶剤ではトルエンの尿中馬尿酸、キシレンの尿中メチル馬尿酸などを測定する。

【誤答選択肢の解説】
A「過重労働」: 過重労働は労働時間の把握と面接指導で管理する。
B「気分障害」: 気分障害はストレスチェックや面接で把握する。
C「筋骨格系障害」: 筋骨格系障害は作業姿勢の評価や自覚症状調査による。
E「電離放射線障害」: 電離放射線は個人線量計による外部被曝線量の測定(物理的モニタリング)で管理する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-26', '正答は D「他の年齢層に比べて高齢者の致死率が高い。」。

インフルエンザは高齢者で肺炎の合併や基礎疾患の増悪により致死率が高くなる。このため高齢者は予防接種の定期接種(B類)の対象とされている。

【誤答選択肢の解説】
A「小児に比べて大人の罹患率が高い。」: 罹患率は小児で最も高い。
B「罹患数は1シーズンに1〜2万人である。」: 1シーズンの推計罹患者数は約1,000万人にのぼる。
C「4月から5月にかけて流行のピークがある。」: 流行のピークは12月から3月で、春ではない。
E「オセルタミビル耐性のウイルス株が90%以上を占める。」: オセルタミビル耐性株が大半を占めるという事実はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F026（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-27', '正答は D「鼻閉の程度」。

最長発声持続時間は、深く息を吸って「あー」と発声を続けられる秒数で、肺活量と声門閉鎖の効率で決まる。鼻閉は共鳴に影響するが、発声を持続できる長さには影響しない。

【誤答選択肢の解説】
A「性別」: 肺活量の差により男性のほうが長くなる傾向があり、性別は影響する。
B「年齢」: 加齢とともに肺活量と声門閉鎖機能が低下するため影響する。
C「呼吸機能」: 呼気を供給する呼吸機能は直接の規定因子である。
E「声門閉鎖の程度」: 声門閉鎖が不十分だと呼気が漏れて持続時間が短くなる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F027（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-28', '正答は E「ミトコンドリア遺伝子の点変異は母から子に伝達する。」。

ミトコンドリアDNAは卵細胞質を介して伝わるため、点変異は母から男女いずれの子にも伝達される。父からは伝わらない。

【誤答選択肢の解説】
A「女性患者が多い。」: 伝達は母系だが発症に男女差はなく、女性患者が多いわけではない。
B「両親が保因者である。」: 父は関与せず、両親が保因者という遺伝形式ではない。
C「次子の罹患率を予測できる。」: 変異ミトコンドリアの割合(ヘテロプラスミー)が卵ごとに異なるため、次子の罹患や重症度を正確に予測できない。
D「子は親より重症化する傾向がある。」: 世代を追って必ず重症化するという法則はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F028（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-29', '正答は A「アルコールの摂取 — 尿酸の排泄低下」。

アルコールの代謝で生じた乳酸が尿細管における尿酸の分泌を競合的に阻害し、尿酸の排泄が低下する。加えてビール等のプリン体負荷も加わり、血清尿酸値が上昇する。

【誤答選択肢の解説】
B「高い糖質摂取割合 — 体重の減少」: 糖質摂取割合が高ければ余剰は脂肪として蓄積し、体重は増加する。
C「2週間の絶食後の輸液 — マラスムス」: 長期絶食後に急に栄養を入れるとリフィーディング症候群を起こす。マラスムスは慢性のエネルギー欠乏による消耗である。
D「タンパク質の過剰摂取 — 胆石形成」: 胆石形成に関わるのは脂質の過剰摂取や肥満、急激な減量である。
E「動物性脂肪の過剰摂取 — 血中LDLコレステロールの低下」: 動物性脂肪(飽和脂肪酸)の過剰摂取は血中LDLコレステロールを上昇させる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F029（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-38', '正答は A「海水 — レジオネラ」。

レジオネラは循環式浴槽や冷却塔、加湿器など淡水系の環境で増殖し、エアロゾルの吸入で肺炎を起こす。海水では増殖せず、また経口感染による消化器症状の集団発生の原因にもならない。

【誤答選択肢の解説】
B「食材 — ノロウイルス」: ノロウイルスは二枚貝などの食材や感染者を介した集団食中毒の代表である。
C「井戸水 — エルシニア」: エルシニアは井戸水や食肉を介した感染が知られている。
D「水道水 — クリプトスポリジウム」: クリプトスポリジウムは塩素に抵抗性で、水道水を介した集団感染例がある。
E「プールの水 — 病原性大腸菌」: 病原性大腸菌はプールの水を介した集団感染を起こしうる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F038（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-39', '正答は C「安静時PaO276Torr、労作後PaO255Torr」。

酸素解離曲線ではSpO2 90%がPaO2およそ60Torrに対応する。安静時SpO2 94%はPaO2 70〜80Torr、労作後SpO2 88%はPaO2 55Torr前後にあたる。労作時に急激に酸素化が落ちるのは、曲線の急峻な部分に入るためである。

【誤答選択肢の解説】
A「安静時PaO296Torr、労作後PaO276Torr」: PaO2 96TorrではSpO2は97〜98%となり、安静時94%と合わない。
B「安静時PaO288Torr、労作後PaO266Torr」: PaO2 88TorrでもSpO2は96〜97%で、94%より高くなる。
D「安静時PaO258Torr、労作後PaO242Torr」: PaO2 58TorrならSpO2は約90%で、安静時94%より低すぎる。
E「安静時PaO2116Torr、労作後PaO260Torr」: PaO2 116Torrは室内気では通常みられない高値である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F039（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-41', '正答は C「放射線肺炎」。

放射線肺炎は照射終了後1〜6か月、多くは3か月前後に照射野に一致して生じる。乾性咳嗽・発熱・労作時呼吸困難で発症し、重症例では副腎皮質ステロイドを要する。

【誤答選択肢の解説】
A「脱毛」: 脱毛は照射野に毛髪がある場合に起こる。胸部照射では生じない。
B「血球減少」: 血球減少は広範囲の骨髄照射で問題になるもので、限局した肺照射では起こりにくい。
D「放射線食道炎」: 放射線食道炎は照射期間中から直後にかけての急性反応で、3か月後には軽快している。
E「放射線皮膚炎」: 放射線皮膚炎も照射中から直後の急性反応である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F041（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-43', '正答は D「ビタミンK製剤静注」。

完全母乳栄養の新生児に生後数日で消化管出血が起こり、PT-INRとAPTTがともに延長しPIVKA-IIが著増している。ビタミンK欠乏性出血症で、直ちにビタミンK製剤を静注する。母乳はビタミンKに乏しく、予防投与の徹底が重要である。

【誤答選択肢の解説】
A「緊急開腹術」: 外科的疾患を示す所見はなく、凝固異常の是正が先である。
B「母乳の中止」: 母乳をやめる必要はない。ビタミンKの補充で対応する。
C「赤血球濃厚液の輸血」: Hb13.4g/dLで貧血はなく、輸血の適応がない。
E「5%アルブミン製剤点滴」: 低蛋白血症を補正しても出血は止まらない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F043（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-44', '正答は E「地域包括支援センターに虐待の可能性について相談する。」。

新旧混在する皮下出血斑と打撲痕、口腔衛生の不良、脱水と栄養不良、服薬管理の破綻が揃っており、養護者による虐待(身体的虐待と介護等放棄)を疑う。高齢者虐待防止法により、疑いの段階で市町村または地域包括支援センターに相談・通報する。

【誤答選択肢の解説】
A「ケアマネジャーに処方管理を依頼する。」: 処方管理だけを整えても虐待の状況は変わらない。
B「歯科衛生士を紹介受診させる。」: 口腔ケアは必要だが、優先すべきは安全の確保である。
C「次回受診時に息子を同伴するように伝え、処方して帰宅させる。」: 加害の疑いがある息子を同伴させるのは本人をさらに危険にさらす。
D「直ちに最寄りの警察に保護入所を依頼する。」: 警察への保護依頼は生命に差し迫った危険がある場合で、まず通報先は市町村・地域包括支援センターである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F044（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-48', '正答は A「経過観察」。

精巣容積は正常で恥毛も出現し、声変わりも始まっている。二次性徴はすでに進行しており、身長も−1.0SDに沿って伸びている。家族歴(母の初経が遅い)からも体質性の遅れと考えられ、経過観察でよい。

【誤答選択肢の解説】
B「頭部MRI」: 下垂体病変を疑う所見(視野障害、頭痛、他の下垂体機能低下)がない。
C「成長ホルモンの測定」: 成長曲線がSDに沿っており、成長ホルモン分泌不全を疑う伸び率の低下がない。
D「甲状腺ホルモンの測定」: 甲状腺機能低下を示唆する症状や成長速度の低下がない。
E「手根骨エックス線撮影」: 骨年齢の評価は成長障害を疑う場合に行うもので、本例では必須でない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F048（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-5', '正答は A「過強陣痛」。

遅発一過性徐脈は子宮収縮のピークより遅れて始まり遅れて回復する徐脈で、子宮胎盤循環不全を反映する。過強陣痛では収縮の間に胎盤血流が回復せず、これを生じる。

【誤答選択肢の解説】
B「臍帯圧迫」: 臍帯圧迫では変動一過性徐脈となる。
C「児頭圧迫」: 児頭圧迫では迷走神経反射により早発一過性徐脈となる。
D「胎児貧血」: 胎児貧血ではサイナソイダルパターンを示す。
E「母体発熱」: 母体発熱では胎児頻脈となる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-51', '正答は D「多発肋骨骨折」。

隣接する複数の肋骨がそれぞれ2か所以上で折れると、その部分が胸郭から分離して動揺胸郭(flail chest)となる。吸気で胸腔内が陰圧になると分離部が内側へ引き込まれ、前胸部が陥凹する奇異呼吸を示す。

【誤答選択肢の解説】
A「血胸」: 血胸では呼吸音が減弱するが、胸壁が奇異性に動くことはない。
B「横隔膜損傷」: 横隔膜損傷では腹部臓器が胸腔へ脱出するが、前胸部の陥凹は生じない。
C「横隔神経麻痺」: 横隔神経麻痺は横隔膜の挙上をきたすもので、胸壁の動きには影響しない。
E「心タンポナーデ」: 心タンポナーデはショックと頸静脈怒張、心音減弱を示すが、胸壁の奇異運動は伴わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F051（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-6', '正答は E「メタンフェタミン」。

覚醒剤(メタンフェタミン)では、反復使用の後に少量の再使用でも以前より強い幻覚・妄想が出現する逆耐性現象が知られている。断薬後も飲酒やストレスで再燃(フラッシュバック)しうる。

【誤答選択肢の解説】
A「LSD」: LSDは急速に耐性が形成される薬物で、逆耐性は示さない。
B「大麻」: 大麻も逆耐性現象を示さない。
C「アルコール」: アルコールは耐性が形成される。
D「ジアゼパム」: ジアゼパムなどベンゾジアゼピンも耐性が形成される。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('115-F-9', '正答は A「世帯数は増加傾向にある。」。

人口が減少に転じても、単独世帯と核家族世帯の増加によって世帯の小規模化が進み、世帯数そのものは増加傾向にある。

【誤答選択肢の解説】
B「三世代世帯は単独世帯より多い。」: 三世代世帯は減少を続けており、単独世帯のほうがはるかに多い。
C「単独世帯は核家族世帯より多い。」: 核家族世帯が最も多く、単独世帯はそれに次ぐ。
D「65歳以上の者のみの世帯は全世帯の過半数を占める。」: 65歳以上の者のみの世帯は全世帯の3割程度で、過半数には達しない。
E「核家族世帯の中ではひとり親と未婚の子のみの世帯が最も多い。」: 核家族世帯の内訳では「夫婦と未婚の子のみ」と「夫婦のみ」が多く、ひとり親と未婚の子は最も少ない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第115回医師国家試験 F009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp210416-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-10', '正答は D「手指腫脹を伴う。」。

全身性強皮症では皮膚硬化の前段階として手指が腫れぼったくなる浮腫期(puffy finger)がみられ、Raynaud現象に手指腫脹を伴う。爪郭部の毛細血管異常や抗核抗体陽性も続発性を示唆する所見である。

【誤答選択肢の解説】
A「片側性である。」: 続発性Raynaud現象も両側性に生じる。片側性なら胸郭出口症候群など局所の血管病変を疑う。
B「家族歴がある。」: 家族歴があるのは原発性(Raynaud病)の特徴である。
C「若年発症が多い。」: 若年女性の発症は原発性に多い。続発性は比較的高齢での発症が多い。
E「血圧の左右差を伴う。」: 血圧の左右差は鎖骨下動脈狭窄や大動脈炎症候群を示唆する所見である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-11', '正答は E「物事に対するこだわりが弱い。」。

自閉スペクトラム症の中核症状は、社会的コミュニケーションの障害と、限定された反復的な行動・興味である。こだわりは弱いのではなく強いのが特徴である。

【誤答選択肢の解説】
A「男児に多い。」: 男児に多く、男女比はおよそ4:1とされる。
B「感覚過敏がある。」: 音や光、触覚などへの感覚過敏(あるいは鈍麻)を伴うことが多い。
C「対人関係の苦手さがある。」: 対人的な相互交流の困難は中核症状である。
D「就学前に症状がみられる。」: 発達早期(就学前)から症状が現れることが診断の要件である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-12', '正答は E「肺動脈性肺高血圧症を伴う呼吸不全」。

肺動脈性肺高血圧症は肺循環の圧が上がる病態で、体血圧の急激な上昇による臓器障害という高血圧緊急症の枠組みには当てはまらない。

【誤答選択肢の解説】
A「急性大動脈解離」: 急性大動脈解離は血圧の厳格な降圧を要する代表的な高血圧緊急症である。
B「褐色細胞腫クリーゼ」: 褐色細胞腫クリーゼはカテコラミンの過剰放出による血圧急上昇で、高血圧緊急症である。
C「乳頭浮腫を伴う脳浮腫」: 乳頭浮腫を伴う脳浮腫は高血圧性脳症で、高血圧緊急症である。
D「肺水腫を生じた急性心不全」: 急激な後負荷増大による肺水腫も高血圧緊急症に含まれる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A012（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-16', '正答は C「糖尿病網膜症の存在」。

糖尿病網膜症と糖尿病性腎症はいずれも高血糖による細小血管障害で、並行して進行する。網膜症が存在することは、蛋白尿の原因が糖尿病性腎症であることを最も強く支持する。腎生検が行えない場合の重要な手がかりになる。

【誤答選択肢の解説】
A「姉の糖尿病歴」: 家族歴は糖尿病そのもののなりやすさを示すが、蛋白尿の原因を特定しない。
B「抗GAD抗体陰性」: 抗GAD抗体陰性は1型糖尿病を否定するだけで、腎障害の原因とは無関係である。
D「随時血糖値>200mg/dL」: 高血糖の存在は糖尿病の診断根拠だが、蛋白尿の原因が糖尿病かどうかを示さない。
E「尿蛋白/Cr比>1.0g/gCr」: 蛋白尿の量は原因を示さない。他の糸球体疾患でも同程度の蛋白尿は出る。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A016（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-18', '正答は A「入眠時に金縛りにあう。」。

日中の耐えがたい眠気と情動脱力発作があり、ナルコレプシーである。入眠時や覚醒時に体が動かせなくなる睡眠麻痺(金縛り)は入眠時幻覚とともに四徴の一つで、高率にみられる。

【誤答選択肢の解説】
B「夜間せん妄を合併する。」: 夜間せん妄はナルコレプシーの特徴ではない。
C「睡眠発作後にも眠気が残る。」: ナルコレプシーの睡眠発作は短時間眠るとすっきりするのが特徴で、眠気が残るのは睡眠時無呼吸症候群などである。
D「睡眠中にパニック発作を認める。」: 睡眠中のパニック発作はパニック症でみられる。
E「睡眠中に脚を動かしたいという欲求が強まる。」: 脚を動かしたい欲求はむずむず脚症候群(レストレスレッグス症候群)の症状である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A018（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-25', '正答は C「プリックテストを行う。」。

特定の食物を摂った後に運動したときだけ症状が出る食物依存性運動誘発アナフィラキシーである。まず原因食物を確定させることが対応の出発点で、プリックテストと特異的IgEで評価する。

【誤答選択肢の解説】
A「部活動を止めさせる。」: 原因食物を摂らずに運動すれば発症しないため、部活動を一律にやめさせる必要はない。
B「イカの摂取を禁ずる。」: 原因が確定する前に食物を禁止するのは過剰であり、確定後も運動と組み合わせなければ摂取できることが多い。
D「運動前の食事は禁止する。」: 食事一般を禁じるのではなく、原因食物と運動の組合せを避けるよう指導する。
E「運動前にステロイド薬を内服させる。」: 運動前のステロイド内服に予防効果は確立していない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-26', '正答は E「感染症の流行が終息するまで辛抱するよう励ます。」。

抑うつ気分、易疲労、集中力低下が3か月続き、寝酒という不適切な対処も始まっている。状況が改善するまで我慢するよう励ますのは、必要な評価と介入を遅らせるだけで適切でない。

【誤答選択肢の解説】
A「精神科受診を勧める。」: うつ病の可能性があり、専門医への受診勧奨は適切である。
B「寝酒はやめるように指導する。」: 寝酒は睡眠を浅くし抑うつも悪化させるため、やめるよう指導するのは適切である。
C「本人の同意を得て上司と面談する。」: 本人の同意を得たうえで業務量や環境の調整を上司と相談するのは産業医の役割である。
D「仕事の仕方や内容について詳しく聴く。」: 仕事の内容と進め方を具体的に聴き取ることは、就業上の措置を考えるうえで必要である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A026（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-29', '正答は A「書痙」。

字を書くときにだけ手指が不随意に強く屈曲し、他の日常動作には支障がない。特定の課題でのみ症状が出る課題特異性の局所ジストニアで、書痙である。

【誤答選択肢の解説】
B「痙性斜頸」: 痙性斜頸は頸部の筋が不随意に収縮して頭位が傾く局所ジストニアである。
C「本態性振戦」: 本態性振戦は姿勢時・動作時の律動的な振戦で、字が震えることはあっても手指の異常な屈曲肢位はとらない。
D「ジスキネジア」: ジスキネジアは抗精神病薬などによる不随意運動で、書字に限局しない。
E「アステリキシス」: アステリキシスは羽ばたき振戦で、肝性脳症などの代謝性脳症でみられる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A029（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-30', '正答は A「尿潜血3+」。

側腹部から始まり下方へ移動する数分周期の激痛と悪心・嘔吐は、尿管結石による疝痛発作の典型である。結石が尿路粘膜を傷つけるため、尿潜血が強陽性となる。

【誤答選択肢の解説】
B「両側水腎症」: 閉塞は片側なので水腎症も片側にとどまる。
C「尿沈渣で赤血球円柱+」: 赤血球円柱は糸球体由来の血尿を示す所見で、尿路結石では出現しない。
D「血清クレアチニン値10.2mg/dL」: 対側の腎が保たれていれば血清クレアチニンは上昇しない。
E「尿蛋白/クレアチニン比5.5g/gCr」: ネフローゼ域の蛋白尿は糸球体疾患の所見で、結石では生じない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A030（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-32', '正答は E「プロスタグランディンE1の投与」。

高濃度酸素を投与してもチアノーゼが改善せず、右室から肺動脈への駆出がなく動脈管経由でのみ肺血流が保たれている。動脈管依存性肺循環の病態で、プロスタグランジンE1を投与して動脈管の開存を維持することが救命につながる。

【誤答選択肢の解説】
A「利尿薬の投与」: 利尿薬は循環血液量を減らし、動脈管を通る肺血流をさらに減らす。
B「ドパミンの投与」: ドパミンは血圧を保つ助けにはなるが、肺血流の確保にはならない。
C「ジゴキシンの投与」: ジゴキシンは心不全の治療薬で、この病態の本質に働かない。
D「高濃度酸素の継続」: 酸素は動脈管を収縮させる方向に働くため、動脈管依存性の病態では高濃度酸素の継続は有害となりうる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A032（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-38', '正答は E「持続硬膜外麻酔による鎮痛を行う。」。

開腹手術後の疼痛管理として持続硬膜外麻酔を用いると、鎮痛が良好で腸管運動の回復も早く、早期離床につながる。術後回復力強化(ERAS)の中核的な要素である。

【誤答選択肢の解説】
A「手術の2時間前まで固形物摂取を許可する。」: 固形物は誤嚥防止のため手術の6時間前までとする。2時間前まで許容されるのは清澄水である。
B「ベッド上安静が術後3日間必要である。」: 術後は早期離床が原則で、3日間のベッド上安静は血栓症と肺合併症を増やす。
C「流動食は術後1週間から開始とする。」: 腸管の手術後も早期に経口摂取を再開するのが標準である。
D「手術中患者の体温を室温で管理する。」: 術中は加温して低体温を防ぐ。低体温は創感染と出血を増やす。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A038（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-4', '正答は D「スルホニル尿素薬」。

スルホニル尿素薬は血糖値と無関係に膵β細胞からのインスリン分泌を促すため、単剤でも低血糖を起こしうる。作用時間が長く、高齢者や腎機能低下例では遷延性低血糖に注意する。

【誤答選択肢の解説】
A「DPP-4阻害薬」: DPP-4阻害薬はインクレチンを介した血糖依存性の作用で、単剤では低血糖を起こしにくい。
B「SGLT2阻害薬」: SGLT2阻害薬は尿糖排泄を増やす薬で、単剤での低血糖は少ない。
C「ビグアナイド薬」: ビグアナイド薬は肝の糖新生を抑えるもので、インスリン分泌を促さない。
E「αグルコシダーゼ阻害薬」: αグルコシダーゼ阻害薬は糖の吸収を遅らせるだけで、単剤では低血糖を起こしにくい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-40', '正答は B「Na+154mEq/L、Cl−154mEq/L」。

炎天下の激しい運動の後に筋痛と赤褐色尿が出現し、尿潜血が強陽性なのに沈渣の赤血球が少ないことからミオグロビン尿である。労作性横紋筋融解症で、急性腎障害を防ぐため生理食塩液(Na 154mEq/L、Cl 154mEq/L)を大量に投与して尿量を確保する。

【誤答選択肢の解説】
A「5%ブドウ糖液」: 5%ブドウ糖液は代謝されると自由水となり細胞内へ分布するため、細胞外液量を保てない。
C「Na+84mEq/L、K+20mEq/L、Cl−66mEq/L、L-Lactate−20mEq/L」: カリウムを含む輸液は、壊死した筋から放出されるカリウムに上乗せして高カリウム血症を悪化させる。
D「Na+84mEq/L、K+200mEq/L、Cl−66mEq/L、L-Lactate−20mEq/L」: 同様にカリウムを含んでおり、この病態では避ける。
E「Na+30mEq/L、Cl−20mEq/L、L-Lactate−20mEq/L」: ナトリウム濃度が低く低張で、細胞外液の補充に適さない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A040（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-43', '正答は C「ガストリン」。

下垂体腺腫の既往に加えて高カルシウム血症と低リン血症(副甲状腺機能亢進症)があり、繰り返す難治性の十二指腸潰瘍を伴う。多発性内分泌腫瘍症1型に伴うガストリノーマ(Zollinger-Ellison症候群)を疑い、血清ガストリンを測定する。

【誤答選択肢の解説】
A「TSH」: TSHの異常では難治性潰瘍も高カルシウム血症も説明できない。
B「ACTH」: ACTH過剰(Cushing病)は下垂体腺腫の一型だが、消化性潰瘍の反復と高カルシウム血症を説明しない。
D「カテコラミン」: カテコラミン過剰(褐色細胞腫)は発作性高血圧が主症状である。本例は血圧98/62mmHgと低めである。
E「テストステロン」: テストステロンはこの病像に関与しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A043（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-44', '正答は E「プロラクチン」。

無月経に両側の乳汁分泌を伴い、乳房発育不良、子宮の萎縮、基礎体温一相性と低エストロゲン状態を示している。高プロラクチン血症がゴナドトロピンの分泌を抑えている病態で、プロラクチンが高値となる。

【誤答選択肢の解説】
A「GH」: GH過剰では先端巨大症の身体所見が現れる。
B「FSH」: 卵巣性無月経ならFSHが上昇するが、その場合は乳汁分泌を伴わない。
C「TSH」: 原発性甲状腺機能低下症ではTRH増加を介してプロラクチンも上がりうるが、甲状腺腫大がなく本例の主座はプロラクチンである。
D「ACTH」: ACTHの異常はCushing病を示唆し、乳汁分泌の説明にならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A044（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-46', '正答は B「ブドウ糖負荷試験」。

顔貌の変化、手足の増大、手根管症候群、高血圧、耐糖能異常が揃っており先端巨大症を疑う。確定診断には75g経口ブドウ糖負荷試験を行い、正常なら抑制されるはずのGHが抑制されないことを確認する。

【誤答選択肢の解説】
A「GHRH負荷試験」: GHRH負荷試験は異所性GHRH産生腫瘍の検索などに用いる特殊な検査である。
C「インスリン負荷試験」: インスリン負荷試験はGH分泌不全や副腎皮質機能低下の評価に用いる。
D「グルカゴン負荷試験」: グルカゴン負荷試験は膵β細胞機能や褐色細胞腫の評価に用いる。
E「デキサメタゾン抑制試験」: デキサメタゾン抑制試験はCushing症候群の診断に用いる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A046（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-47', '正答は E「被害の状況を本人から再度聴き取って確認する。」。

被害の状況を繰り返し語らせることは、体験を再体験させて心的外傷を深める二次被害になる。事情聴取は警察が行っており、医師は診療に必要な範囲にとどめる。

【誤答選択肢の解説】
A「性感染症の検査を行う。」: 性感染症の検査と予防内服は必要な医療である。
B「緊急避妊薬を提案する。」: 最終月経から12日で妊娠しうる時期にあたり、緊急避妊薬の提案は適切である。
C「婦人科診察について本人の同意を得る。」: 診察は本人の同意を得て行う。適切である。
D「DNA診断のための検体を腟内から採取する。」: 証拠保全のための検体採取は、本人の同意のうえで行う必要な対応である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A047（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-48', '正答は E「「高圧浣腸で整復できなければ開腹手術になります」」。

間欠的な啼泣、嘔吐、血便、右上腹部の腫瘤、超音波のtarget signから腸重積症である。まず高圧浣腸(注腸)による非観血的整復を試み、整復できなければ、あるいは穿孔や腹膜炎があれば開腹手術となる。この見通しを保護者に伝える。

【誤答選択肢の解説】
A「「高圧浣腸で整復できれば帰宅できます」」: 整復できても10%前後に再発があるため、通常は入院して経過を観察する。
B「「炎症を抑えるため抗菌薬の内服が必要です」」: 感染症ではなく抗菌薬の適応がない。
C「「腹膜炎を併発しているため緊急手術になります」」: 腹腔内遊離ガス像がなく腹膜炎の所見もない。直ちに手術と決まったわけではない。
D「「グリセリン浣腸をして便の状態を確認しましょう」」: すでに超音波で診断が確定しており、グリセリン浣腸で確認する段階ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A048（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-5', '正答は C「原疾患は拡張型心筋症が最も多い。」。

我が国の成人心臓移植の原疾患は拡張型心筋症が最も多く、次いで拡張相肥大型心筋症、虚血性心筋症の順である。

【誤答選択肢の解説】
A「10年生存率は約10%である。」: 10年生存率は約90%で、国際的にみても良好である。
B「年間約1,000例行われている。」: 実施数は年間50〜100例程度にとどまる。
D「原則として術後に免疫抑制薬は用いられない。」: 拒絶反応を防ぐため免疫抑制薬の生涯服用が必要である。
E「2015年以降の平均待機期間は1年以下である。」: ドナー不足のため平均待機期間は3年を超えている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-52', '正答は D「生理食塩液での洗眼」。

アルカリは蛋白を融解しながら組織深部へ進行するため、化学眼外傷のなかでも予後が悪い。診断や他の処置に先んじて、生理食塩液などで大量かつ長時間の洗眼を直ちに開始する。

【誤答選択肢の解説】
A「鎮痛薬の内服」: 鎮痛は必要だが、洗眼より優先されるものではない。
B「希塩酸液の点眼」: 酸で中和しようとすると中和熱が発生し、組織障害をさらに広げる。
C「抗菌薬の点滴静注」: 感染対策は洗眼の後に考えることで、初期対応ではない。
E「高浸透圧利尿薬の点滴静注」: 高浸透圧利尿薬は眼圧上昇に対する薬剤で、まず行う処置ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A052（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-55', '正答は E「HBワクチン及び抗HBsヒト免疫グロブリンの投与」。

曝露源がHBs抗原陽性で、受傷者はHBs抗体を持たない。曝露直後に抗HBsヒト免疫グロブリンで受動免疫を与え、同時にHBワクチンを開始して能動免疫を獲得させるのが標準的対応である。

【誤答選択肢の解説】
A「無投薬」: 感染リスクが高く、無投薬は許されない。
B「HBワクチンの単独投与」: ワクチン単独では抗体産生までに時間がかかり、初期の感染を防げない。
C「核酸アナログ製剤の投与」: 核酸アナログ製剤は慢性B型肝炎の治療薬で、曝露後予防には用いない。
D「抗HBsヒト免疫グロブリンの単独投与」: 免疫グロブリン単独では効果が一時的で、長期の防御が得られない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A055（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-57', '正答は A「虐待」。

新旧混在する皮下出血、硬膜下血腫とびまん性脳浮腫、大腿骨と上腕骨の骨折という説明のつかない多発外傷があり、健診も受けていない。身体的虐待による死亡を第一に考え、警察への届出と司法解剖が必要になる。

【誤答選択肢の解説】
B「てんかん」: てんかんでは多発骨折や新旧混在する皮下出血を説明できない。
C「不慮の事故」: 2か月児は寝返りもできず、大腿骨・上腕骨骨折を伴う事故は起こりにくい。説明のつかない受傷機転自体が虐待を示唆する。
D「熱性けいれん」: 熱性けいれんは発熱を伴い、外傷所見とは無関係である。
E「細菌性髄膜炎」: 細菌性髄膜炎でも骨折や新旧混在の皮下出血は生じない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A057（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-6', '正答は E「レニン・アンジオテンシン系抑制薬」。

レニン・アンジオテンシン系抑制薬(ACE阻害薬・ARB・ミネラルコルチコイド受容体拮抗薬)はアルドステロンの作用を弱め、集合管からのカリウム排泄を減らすため高カリウム血症を起こす。腎機能低下例で特に注意する。

【誤答選択肢の解説】
A「β刺激薬」: β刺激薬はカリウムを細胞内へ移動させ、血清カリウムを下げる。
B「インスリン」: インスリンもカリウムを細胞内へ取り込ませ、高カリウム血症の治療に用いる。
C「ループ利尿薬」: ループ利尿薬は尿中カリウム排泄を増やし低カリウム血症をきたす。
D「グリチルリチン」: グリチルリチンは偽アルドステロン症を起こし、低カリウム血症の原因となる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-64', '正答は E「がん治療を継続しながら膝の手術治療」。

余命が2年以上見込まれ、膝の変形と可動域制限で歩行が制限されている。癌の治療を続けながら人工膝関節置換術を行い、残された時間の生活の質を保つのが妥当である。癌があること自体は手術の禁忌ではない。

【誤答選択肢の解説】
A「がん治療、膝治療ともに放棄」: どちらも放棄する理由がない。
B「がん治療を終了し膝の保存治療」: 癌治療を中断する医学的理由がない。
C「がん治療を終了し膝の手術治療」: 同様に癌治療の終了は不要である。
D「がん治療を継続しながら膝の保存治療」: 保存治療では高度の変形と可動域制限による歩行障害は改善しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A064（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-7', '正答は D「萎縮性胃炎」。

萎縮性胃炎では胃酸分泌が低下するため、逆流しても食道粘膜の傷害が起こりにくい。むしろ逆流性食道炎の頻度は下がる。

【誤答選択肢の解説】
A「肥満」: 肥満は腹圧を高めて逆流を促す。誘因である。
B「高齢」: 高齢では下部食道括約筋の機能低下と食道裂孔ヘルニアが増える。誘因である。
C「亀背」: 亀背(円背)は腹圧を高め、食道裂孔ヘルニアも生じやすくする。誘因である。
E「カルシウム拮抗薬」: カルシウム拮抗薬は下部食道括約筋を弛緩させる。誘因である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-8', '正答は D「心室中隔の非対称性肥大」。

心室中隔の非対称性肥大は肥大型心筋症の所見である。心サルコイドーシスではむしろ心室中隔基部の菲薄化が特徴的で、肥大は示さない。

【誤答選択肢の解説】
A「房室ブロック」: 刺激伝導系に肉芽腫ができやすく、房室ブロックは初発症状として頻度が高い。
B「持続性心室頻拍」: 心筋の瘢痕を基質とする持続性心室頻拍がみられる。
C「左室駆出率の低下」: 心筋障害の進行により左室駆出率が低下する。
E「FDG-PETでの心筋への異常集積」: FDG-PETでの心筋への異常集積は活動性病変の評価に用いられる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-A-9', '正答は D「有機リン剤」。

有機リン剤はコリンエステラーゼを阻害して中毒症状をきたす物質で、骨壊死との関連は知られていない。

【誤答選択肢の解説】
A「飲酒」: 多量飲酒は大腿骨頭壊死の代表的な危険因子である。
B「減圧症」: 減圧症では骨内の血管が窒素気泡で閉塞し、骨壊死を起こす。
C「放射線照射」: 放射線照射は骨の微小循環を障害して放射線骨壊死を生じる。
E「副腎皮質ステロイド」: 副腎皮質ステロイドの全身投与は大腿骨頭壊死の最大の危険因子である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 A009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-1', '正答は D「患者に発表に関する同意を取る。」。

症例報告であっても患者の情報を公表する以上、本人(または代諾者)から発表についての同意を得ることが必要である。学会の指針でも同意の取得が前提とされている。

【誤答選択肢の解説】
A「患者の国籍を記載する。」: 国籍は医学的に必要でない限り記載せず、個人の特定にもつながる。
B「経過の年月日を正確に記載する。」: 日付を正確に書くと受診記録と照合されて個人が特定されうるため、時系列は相対表記にする。
C「顔全体が映った写真を掲載する。」: 顔全体が判別できる写真は個人を特定するため、必要な範囲に限りマスクするなどの配慮が要る。
E「患者氏名をイニシャルに変換する。」: イニシャルも個人の特定につながるため、記号(症例1など)に置き換える。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-10', '正答は E「結核患者の医療費の公費負担は感染症法に規定されている。」。

結核患者の医療費の公費負担は、感染症法(第37条・第37条の2)に規定されている。入院勧告による入院は全額、通院医療は95%が公費で負担される。

【誤答選択肢の解説】
A「診療録の保存義務期間は終診時から2年間である。」: 診療録の保存義務期間は完結の日から5年間である。
B「国民健康保険組合の被保険者数は6千万人より多い。」: 国民健康保険組合の被保険者数は300万人程度で、6千万人には遠く及ばない。
C「国民医療費は2000年からの20年間で3倍に増加した。」: 国民医療費は2000年の約30兆円から40兆円台へ増えたが、3倍にはなっていない。
D「介護保険第1号被保険者数は第2号被保険者数より多い。」: 第1号被保険者(65歳以上)より第2号被保険者(40〜64歳)のほうが多い。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-11', '正答は C「唾液の流涎」。

唾液を飲み込めずに流涎するのは、咽頭・喉頭の高度な腫脹や疼痛で嚥下できないことを意味する。急性喉頭蓋炎や咽後膿瘍など、短時間で気道閉塞に至る病態を示唆する危険な徴候である。

【誤答選択肢の解説】
A「喀痰」: 喀痰は下気道の症状で、咽頭痛の緊急性を示すものではない。
B「膿性鼻汁」: 膿性鼻汁は副鼻腔炎を示唆するが緊急性は低い。
D「顎下リンパ節痛」: 顎下リンパ節の圧痛は咽頭炎に一般的で、それ自体は緊急性を示さない。
E「38°C以上の高熱」: 高熱だけでは気道の危険を判断できない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-12', '正答は C「Duchenne型筋ジストロフィー」。

Duchenne型筋ジストロフィーは乳児期には目立たず、3〜5歳ごろに転びやすさや登はん性起立(Gowers徴候)で気づかれる。X連鎖潜性遺伝で、血清CKの著明高値が手がかりになる。

【誤答選択肢の解説】
A「Werdnig-Hoffmann病」: Werdnig-Hoffmann病(脊髄性筋萎縮症I型)は生後6か月までに発症する。
B「新生児一過性重症筋無力症」: 新生児一過性重症筋無力症は母体からの抗体移行によるもので、生直後に発症し数週で消退する。
D「福山型先天性筋ジストロフィー」: 福山型先天性筋ジストロフィーは乳児期から筋緊張低下と発達遅滞を示す。
E「先天性筋強直性ジストロフィー」: 先天性筋強直性ジストロフィーは新生児期から重度の筋緊張低下と呼吸障害を示す。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B012（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-13', '正答は D「それぞれの高齢者の習慣や生活ペースに合わせた介護を行う。」。

生活歴や習慣は人によって異なり、それに合わせて介護を組み立てることが個性と尊厳の尊重にあたる。施設や介護者の都合に合わせさせるのではない。

【誤答選択肢の解説】
A「親しみを込めるように高齢者の名前を「ちゃん」づけで呼ぶ。」: 「ちゃん」づけは相手を子ども扱いすることになり、尊厳を損なう。
B「転落しないようにベッドに体幹をバンドで固定し安全を図る。」: 体幹をバンドで固定するのは身体拘束で、原則として認められない。
C「排泄の自立が困難な高齢者にトイレの場所を大声で指図する。」: 排泄について大声で指図することは羞恥心を傷つける。
E「移動の自立が困難な高齢者に介護老人福祉施設の入所を勧める。」: 移動が難しいというだけで施設入所を勧めるのは、本人の希望を無視した対応である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B013（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-14', '正答は D「フレイル — 高齢者の強い咀嚼力」。

フレイルの危険因子は咀嚼力の低下である。噛む力が弱まると食べられるものが減り、低栄養からサルコペニア・フレイルへ進む。強い咀嚼力は保護的に働く。

【誤答選択肢の解説】
A「乳癌 — 飲酒習慣」: 飲酒習慣は乳癌の危険因子として確立している。
B「肥満 — 速い摂食速度」: 速い摂食速度は満腹感が得られる前に食べ過ぎるため、肥満の危険因子である。
C「食道癌 — 高温物の飲食嗜好」: 熱い飲食物は食道粘膜を傷つけ、食道癌の危険因子となる。
E「骨粗鬆症 — 若年女性の過度の食事制限」: 若年期の過度な食事制限は最大骨量の獲得を妨げ、将来の骨粗鬆症につながる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B014（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-15', '正答は D「呼吸数24/分」。

成人の安静時呼吸数は12〜20/分で、24/分は頻呼吸にあたる。呼吸数はもっとも早期に異常を示すバイタルサインで、敗血症や呼吸不全の指標として重要である。

【誤答選択肢の解説】
A「腋窩体温36.2°C」: 腋窩体温36.2°Cは正常範囲である。
B「脈拍96/分、整」: 脈拍96/分は正常範囲(60〜100/分)の上限内である。
C「血圧112/70mmHg」: 血圧112/70mmHgは正常である。
E「SpO297%(room air)」: SpO2 97%は正常である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B015（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-16', '正答は E「チューブ先端位置をエックス線写真で確認する。」。

胃管の先端が胃内にあることを最も確実に示せるのはエックス線写真である。気管に誤挿入したまま栄養剤を注入すると致命的になるため、初回留置時には必ず画像で確認する。

【誤答選択肢の解説】
A「挿入前に鼻腔にリドカインを塗布する。」: リドカインの塗布は必須ではなく、咽頭反射を抑えて誤嚥のリスクを高める面もある。
B「挿入時に患者の頸部を後屈させる。」: 頸部を前屈させることで食道側へ入りやすくなる。後屈させると気管に入りやすい。
C「標準的な成人では鼻孔から35cmの深さまで挿入する。」: 成人では鼻孔から45〜55cm程度必要で、35cmでは食道内にとどまる。
D「挿入後生理食塩液を注入し流入音を確認する。」: 液体を注入して確認するのは危険である。誤挿入なら気道に液体を入れることになる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B016（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-17', '正答は C「2:15」。

小児(乳児を含む)の蘇生を医療者2名で行う場合、胸骨圧迫と人工呼吸の比は15:2とする。1名で行う場合や成人では30:2である。

【誤答選択肢の解説】
A「1:3」: 1:3という比は用いない。
B「1:15」: 人工呼吸1回に対し胸骨圧迫15回という比は用いない。
D「2:30」: 30:2は成人、あるいは小児を救助者1名で行う場合の比である。
E「3:30」: 3:30という比は用いない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-19', '正答は E「乳頭の色素沈着」。

乳頭・乳輪の色素沈着は妊娠やホルモンの影響による生理的変化で、悪性を示唆する所見ではない。

【誤答選択肢の解説】
A「えくぼ徴候」: えくぼ徴候(dimpling)はCooper靱帯への浸潤による皮膚の陥凹で、乳癌を示唆する。
B「橙皮様皮膚」: 橙皮様皮膚は皮下リンパ管の閉塞による浮腫で、進行乳癌や炎症性乳癌でみられる。
C「乳頭のびらん」: 乳頭のびらんはPaget病を疑わせる所見である。
D「血性乳頭分泌」: 血性の乳頭分泌は乳管内病変(乳管内乳頭腫や乳癌)を示唆する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-2', '正答は C「頸静脈の怒張 — 右心不全」。

頸静脈の怒張は右房圧の上昇を意味し、右心不全の重要な身体所見である。半座位で観察し、他の所見と併せて評価する。

【誤答選択肢の解説】
A「Coarse crackles — 喘息」: 喘息で聴かれるのは呼気性の笛声音(wheeze)である。coarse cracklesは肺炎や気管支拡張症でみられる。
B「胸部打診で濁音 — 気胸」: 気胸では患側の打診で鼓音となる。濁音は胸水や無気肺である。
D「SpO295%(room air) — 呼吸不全」: 呼吸不全はPaO2 60Torr以下と定義され、SpO2ではおよそ90%以下にあたる。95%は呼吸不全ではない。
E「Cheyne-Stokes呼吸 — 上気道閉塞」: Cheyne-Stokes呼吸は心不全や脳障害でみられる周期性呼吸で、上気道閉塞の所見ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-20', '正答は B「1」。

徒手筋力テストで、関節の動きは起こらないが筋の収縮を触知・視認できる状態は1(trace)と評価する。

【誤答選択肢の解説】
A「0」: 0は筋収縮がまったく認められない状態である。
C「2」: 2は重力を除けば全可動域を動かせる状態である。
D「3」: 3は重力に抗して全可動域を動かせる状態である。
E「4」: 4は重力に抗し、ある程度の抵抗にも打ち勝てる状態である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B020（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-21', '正答は B「グルコース」。

髄液のグルコースは血糖のおよそ60%が正常で、絶対値だけでは評価できない。同時に測った血糖と比べて低下しているかどうかを見ることで、細菌性・結核性・真菌性髄膜炎(髄液糖低下)とウイルス性(正常)を鑑別する。

【誤答選択肢の解説】
A「アルブミン」: 髄液アルブミンは血液脳関門の評価に用いるが、血液との比較が必須の項目ではない。
C「好中球数」: 好中球数は髄液中の絶対数と分画で評価する。
D「蛋白」: 髄液蛋白は基準値との比較で評価する。
E「白血球数」: 白血球数も髄液中の値そのもので評価する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B021（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-22', '正答は C「遺伝子工学によるヒトインスリン製剤の作製」。

遺伝子組換え技術によるヒトインスリン製剤の作製は1980年代で、選択肢のなかで最も新しい。ランゲルハンス島の発見(1869年)、膵摘出犬の実験(1889年)、インスリンの精製(1921年)、アミノ酸配列と立体構造の解明(1950〜60年代)の順に続く。

【誤答選択肢の解説】
A「膵臓ランゲルハンス島の発見」: ランゲルハンスによる膵島の発見は1869年で最も古い。
B「動物膵臓から抽出されたインスリンの精製」: BantingとBestによる動物膵からのインスリン抽出・精製は1921年である。
D「インスリンのアミノ酸配列および立体構造の解明」: Sangerによるアミノ酸配列の決定は1950年代、Hodgkinによる立体構造の解明は1960年代である。
E「膵臓除去犬が尿糖を含む多尿をきたすことの発見」: MeringとMinkowskiによる膵摘出犬の実験は1889年である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-23', '正答は E「「今困っていることについてもっと詳しく教えていただけますか」」。

開放型質問は「はい・いいえ」や特定の情報では答えられず、患者が自由に語れる問いである。「今困っていることについてもっと詳しく教えていただけますか」がこれにあたる。

【誤答選択肢の解説】
A「「ご年齢を教えてください」」: 年齢を尋ねる質問は特定の情報を求める閉鎖型である。
B「「足のむくみに左右差はありますか」」: 左右差の有無を問うのは閉鎖型である。
C「「いつ頃、足のむくみに気がつきましたか」」: 時期を問うのも答えの範囲が限定される閉鎖型である。
D「「就寝後、息苦しくなって目覚めることはありますか」」: 発作性夜間呼吸困難の有無を問うのは閉鎖型である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B023（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-24', '正答は A「検査入院では記載を省略できる。」。

退院時要約は入院の目的にかかわらず作成するもので、検査入院だからといって省略できない。次の診療にとって必要な記録である。

【誤答選択肢の解説】
B「患者の入院中の情報をまとめたものである。」: 入院中の経過・検査・治療・転帰をまとめたものである。正しい。
C「退院後の診療のため遅滞のない記載が求められる。」: 退院後の診療に用いるため、遅滞なく記載することが求められる。正しい。
D「退院後14日以内の記載で保険点数上の加算が認められている。」: 退院後14日以内の記載が診療録管理体制加算の要件となっている。正しい。
E「医師事務作業補助者が作成し、医師が承認したものは有効である。」: 医師事務作業補助者が代行入力し、医師が内容を確認して承認する運用は認められている。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-25', '正答は E「橈骨神経」。

飲酒後に肘掛けへ上腕を長時間圧迫した後に手関節と手指MP関節の伸展ができなくなっており、下垂手である。上腕骨の橈骨神経溝で橈骨神経が圧迫された麻痺(いわゆるSaturday night palsy)である。手背の感覚鈍麻も橈骨神経の支配領域に一致する。

【誤答選択肢の解説】
A「腋窩神経」: 腋窩神経の障害では三角筋麻痺による肩関節外転障害と肩外側の感覚障害が生じる。
B「筋皮神経」: 筋皮神経の障害では肘屈曲(上腕二頭筋)の障害と前腕外側の感覚障害が生じる。
C「尺骨神経」: 尺骨神経の障害では鷲手となり、小指・環指尺側の感覚障害を伴う。
D「正中神経」: 正中神経の障害では猿手となり、母指球の萎縮と橈側3指半の感覚障害を伴う。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-26', '正答は D「肺血栓塞栓症」。

骨盤内手術後で臥床していた患者が、離床して動いた直後に突然の呼吸困難と低酸素血症をきたしている。呼吸音は正常で、肺血栓塞栓症を第一に考える。手術・臥床・悪性疾患などの危険因子と発症の契機が手がかりになる。

【誤答選択肢の解説】
A「気道異物」: 気道異物では吸気性の喘鳴や咳嗽を伴い、突然の窒息感を訴える。
B「気管支喘息」: 気管支喘息では呼気性喘鳴を聴取し、喫煙歴や既往が背景にあることが多い。
C「急性左心不全」: 急性左心不全では湿性ラ音を聴取し、起坐呼吸となる。呼吸音は正常でない。
E「特発性肺線維症」: 特発性肺線維症は慢性に進行し、fine cracklesとばち指を伴う。突然発症しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B026（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-28', '正答は B「患者の意向」。

改訂長谷川式22点で意思決定能力は保たれており、本人が告知を望み積極的治療を望まないと明確に意思表示している。治療方針は本人の意向を最も重視して決める。

【誤答選択肢の解説】
A「患者の年齢」: 年齢だけで治療方針を決めることはできない。
C「長男の意向」: 家族の意向は考慮するが、本人の明示の意思には優先しない。
D「主治医の意向」: 医師の考えは選択肢を示すためのもので、本人の意思を上書きできない。
E「患者の認知機能」: 認知機能は意思決定能力の判断材料だが、22点で能力は保たれており、これ自体が方針を決める因子ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B028（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-29', '正答は C「かかりつけの整形外科担当医へ情報提供」。

骨形成不全症で年1回整形外科を受診しており、今回の手術と入院の経過をかかりつけの整形外科医へ情報提供することが、退院後の継続的な診療に必要である。

【誤答選択肢の解説】
A「退院後安静などの療養指導」: 術後経過は良好で良性であり、特別な安静指導を要さない。
B「介護福祉士資格を持つヘルパーの手配」: すでにボランティアによる支援体制があり、新たな機能障害も生じていない。
D「日常生活動作を支援する福祉器具の貸与の手配」: 電動車いすを含む必要な福祉器具はすでに使用しており、新規の手配は不要である。
E「在宅リハビリテーションを行う理学療法士の手配」: 入院中に新たな機能障害はなく、在宅リハビリテーションの適応がない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B029（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-30', '正答は C「離床センサーの使用」。

夜間にトイレへ行こうとして転倒しており、離床センサーを用いて起き上がりを早期に把握し、介助に入れるようにするのが妥当である。行動を制限せずに安全を高める方法である。

【誤答選択肢の解説】
A「睡眠薬の追加」: ベンゾジアゼピン系薬剤は高齢者の転倒とせん妄の危険因子で、追加はむしろ有害である。減量・中止を検討する。
B「夜間の身体拘束」: 身体拘束は原則として認められず、せん妄や廃用を悪化させる。
D「後日の家族への報告」: 転倒は事故であり、家族への報告は速やかに行う。
E「尿道カテーテルの留置」: 排尿のためだけの尿道カテーテル留置は尿路感染とADL低下を招き、適応がない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B030（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-31', '正答は B「「あなたが承諾した方に病状をお話しします」」。

診療情報を誰に伝えるかは患者本人が決める。本人が承諾した相手にのみ説明するという方針を伝えるのが正しい。

【誤答選択肢の解説】
A「「会社へは主治医からの報告義務があります」」: 主治医に勤務先へ病状を報告する義務はない。
C「「それでは薬物治療のみで対応せざるを得ません」」: 病状を家族に伝えないことと、治療法の選択とは無関係である。
D「「血縁者からの病状説明の依頼は拒否できません」」: 血縁者であっても本人の同意なく病状を伝えることはできない。
E「「どのような治療でも血縁者の同意は必須になります」」: 意思決定能力のある成人では本人の同意で足り、血縁者の同意は不要である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B031（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-33', '正答は C「血糖値の日内変動を測定」。

妊娠中の随時尿糖陽性に加えて空腹時血糖132mg/dLと高値である。この値は妊娠中の明らかな糖尿病(overt diabetes in pregnancy)の基準を満たし、負荷試験は不要で危険でもある。まず血糖の日内変動を測って治療方針を決める。

【誤答選択肢の解説】
A「24時間蓄尿」: 24時間蓄尿は腎症の評価には使えるが、血糖管理の判断に直接つながらない。
B「経口糖尿病薬を開始」: 経口血糖降下薬は妊娠中には原則用いない。
D「強化インスリン療法を開始」: インスリン療法が必要になる可能性は高いが、まず血糖の推移を把握してから量を決める。
E「75g経口ブドウ糖負荷試験を実施」: 空腹時血糖が126mg/dL以上あり、負荷試験は高血糖を助長するため行わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B033（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-35', '正答は D「家族の面会制限」。

緩和ケアでは家族との時間を保つことが大切で、面会を制限する理由はない。むしろ家族が過ごしやすい環境を整える。

【誤答選択肢の解説】
A「酸素投与の継続」: 低酸素血症による呼吸困難を和らげるため酸素投与は継続する。適切である。
B「病室の環境調整」: 室温や湿度、風の当たり方など環境の調整は呼吸困難の緩和に有効である。
C「オピオイド投与」: オピオイドは呼吸困難の緩和に有効で、非癌の終末期でも用いられる。
E「苦痛を訴える部位のマッサージ」: マッサージは苦痛の緩和と安楽に寄与する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B035（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-4', '正答は C「開始時のCRP値で投与期間を決定する。」。

抗菌薬の投与期間は疾患ごとに標準が定まっており、CRPの値で決めるものではない。CRPは炎症の指標にすぎず、これを基準にすると不要に長期の投与になる。

【誤答選択肢の解説】
A「培養検査提出後に開始する。」: 起炎菌の同定のため培養検体を採ってから投与を開始する。正しい。
B「薬物動態に合わせて投与量を調整する。」: 時間依存性か濃度依存性かなど薬物動態・薬力学に応じて用量と間隔を決める。正しい。
D「抗菌薬の臓器への移行性を考慮して選択する。」: 髄膜炎や骨髄炎など、目的臓器への移行性を考慮して薬剤を選ぶ。正しい。
E「感受性検査の結果に応じて適切な抗菌薬に変更する。」: 感受性判明後は狭域薬へ変更する(de-escalation)。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-5', '正答は D「鼻指鼻試験」。

鼻指鼻試験は患者が指示に従って動くことが前提の協調運動検査で、意識障害があると実施できない。

【誤答選択肢の解説】
A「腱反射」: 腱反射は患者の協力がなくても打腱器で誘発できる。
B「項部硬直」: 項部硬直は他動的に頸部を屈曲させて確認でき、意識障害があっても評価できる。
C「対光反射」: 対光反射は光刺激への反応で、意識障害の評価そのものに用いる。
E「膝立て試験(下肢ドロッピングテスト)」: 膝立て試験は他動的に立てた下肢がどう倒れるかを見るもので、意識障害でも実施できる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-6', '正答は D「医療安全支援センター」。

医療安全支援センターは医療法に基づき都道府県等に設置され、患者・家族からの医療に関する相談に応じ、助言や情報提供を行う。主治医以外に相談したいときの窓口となる。

【誤答選択肢の解説】
A「保健所」: 保健所は感染症対策や難病支援など公衆衛生を担う。
B「福祉事務所」: 福祉事務所は生活保護など福祉の窓口である。
C「市町村保健センター」: 市町村保健センターは健康診査や健康相談の拠点である。
E「地域包括支援センター」: 地域包括支援センターは高齢者の総合相談窓口である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-8', '正答は B「尿濃縮力低下」。

加齢に伴い髄質の浸透圧勾配が保ちにくくなり、尿濃縮力が低下する。このため脱水になりやすく、夜間尿も増える。

【誤答選択肢の解説】
A「腎血流量増加」: 腎血流量は加齢とともに減少する。
C「糸球体ろ過値上昇」: 糸球体濾過量も加齢とともに低下する。
D「硬化糸球体数減少」: 硬化糸球体の数は加齢とともに増加する。
E「機能ネフロン数増加」: 機能するネフロンの数は減少する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-B-9', '正答は E「症状が患者の生活に及ぼしている影響を聞く。」。

症状が生活にどう影響しているかを聞くことで、患者の困りごとの中心が分かり、治療目標を共有できる。患者中心の医療面接の基本である。

【誤答選択肢の解説】
A「医学用語を用いて病状を説明する。」: 専門用語は理解を妨げる。平易な言葉に置き換える。
B「相手が話したことは繰り返さない。」: 患者の言葉を繰り返す(反復)ことは、聞いていることを示し語りを促す技法である。
C「冒頭から閉じられた質問を用いる。」: 冒頭は開かれた質問で自由に語ってもらい、その後に閉じられた質問で絞り込む。
D「電子カルテの画面を見ながら話しを聞く。」: 画面を見続けると視線が合わず、聴いてもらえていないという印象を与える。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 B009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-1', '正答は D「男性では膀胱留置カテーテルを下腹部に固定する。」。

男性では陰茎を頭側に向けて下腹部にカテーテルを固定する。陰茎陰囊角で屈曲したまま留置すると、その部位に圧迫壊死が起き尿道皮膚瘻を生じうる。

【誤答選択肢の解説】
A「胃瘻の造設を行ったので経口摂取は控える。」: 胃瘻を造設しても嚥下機能が保たれていれば経口摂取を併用でき、控える必要はない。
B「中心静脈栄養法での輸液中は体動を制限する。」: 中心静脈栄養中も日常生活や体動は制限しない。制限は廃用を招く。
C「仙骨部の褥瘡拡大防止のため円座を使用する。」: 円座は接触部の圧を高めて褥瘡を悪化させるため、現在は用いない。
E「気管切開による人工呼吸療法のため入浴はできない。」: 気管切開下でも、切開部の防水など工夫すれば入浴は可能である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-10', '正答は A「終末期になってから導入する。」。

緩和ケアは終末期に限らず、診断された時から治療と並行して提供されるべきものとされている。基本計画でもこの点が繰り返し強調されている。

【誤答選択肢の解説】
B「患者の家族に対する対応を含む。」: 家族も支援の対象であり、遺族ケアも含まれる。正しい。
C「医療用麻薬に関する啓発を行う。」: 医療用麻薬への誤解を解くための啓発が挙げられている。正しい。
D「精神腫瘍医の役割についての記載がある。」: 精神腫瘍医(サイコオンコロジスト)の役割についての記載がある。正しい。
E「医師以外の医療従事者も緩和ケアに関わる。」: 看護師・薬剤師・心理職など多職種が関わることが前提とされている。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-11', '正答は D「4」。

三次予防はすでに発症した疾患の重症化を防ぎ、機能を回復・維持する取り組みである。慢性閉塞性肺疾患の患者に対する呼吸リハビリテーションがこれにあたる。

【誤答選択肢の解説】
A「1」: 小学生への禁煙教育は発症前の健康増進で、一次予防である。
B「2」: 産業医としての禁煙活動も一次予防である。
C「3」: 喫煙者の健康診断は無症状のうちに疾患を早期発見する二次予防である。
E「5」: 喫煙妊婦への禁煙指導は、母児の疾患発症を防ぐ一次予防である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-12', '正答は B「肝硬変」。

肝硬変による胸水は、低アルブミン血症と門脈圧亢進によって生じる漏出性胸水である。滲出性ではない。

【誤答選択肢の解説】
A「肺梗塞」: 肺梗塞では胸膜の炎症と血管透過性亢進により滲出性胸水を生じる。
C「急性膵炎」: 急性膵炎では膵酵素の刺激により左優位の滲出性胸水を生じる。
D「結核性胸膜炎」: 結核性胸膜炎は代表的な滲出性胸水で、ADA高値とリンパ球優位が特徴である。
E「全身性エリテマトーデス」: 全身性エリテマトーデスの漿膜炎も滲出性胸水をきたす。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C012（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-13', '正答は E「1,000ppm(0.1%)次亜塩素酸ナトリウム」。

ノロウイルスはエンベロープを持たないためアルコールが効きにくい。0.1%(1,000ppm)次亜塩素酸ナトリウムによる消毒か、85〜90°Cで90秒以上の加熱で不活化する。

【誤答選択肢の解説】
A「逆性石鹸」: 逆性石鹸(塩化ベンザルコニウム)はノロウイルスに無効である。
B「40°Cの温水」: 40°Cの温水では不活化できない。85°C以上の加熱が必要である。
C「40%アルコール」: アルコールはエンベロープを持たないウイルスには効きにくい。
D「1分間の赤外線照射」: 赤外線照射に消毒効果はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C013（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-14', '正答は B「−20度」。

関節可動域は解剖学的肢位を0度として表す。底屈20度の位置までしか戻せず0度に届かないので、背屈の可動域は−20度と記載する。

【誤答選択肢の解説】
A「−40度」: −40度は底屈40度の位置が限界の場合である。
C「0度」: 0度は中間位まで背屈できる場合である。
D「20度」: 20度は中間位を越えて背屈できる場合で、尖足と矛盾する。
E「40度」: 40度も同様に背屈可能な場合の値である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C014（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-15', '正答は A「婚姻率」。

婚姻率は人口千人当たりの婚姻件数で、分母は総人口(日本人人口)である。出生率・死亡率も同様に総人口を分母とする。

【誤答選択肢の解説】
B「乳児死亡率」: 乳児死亡率の分母は出生数である。
C「老年人口指数」: 老年人口指数の分母は生産年齢人口(15〜64歳)である。
D「標準化死亡比」: 標準化死亡比の分母は基準集団から求めた期待死亡数である。
E「合計特殊出生率」: 合計特殊出生率は年齢別出生率の合計で、各年齢の女性人口を分母とする。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C015（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-16', '正答は D「バルトリン腺炎」。

バルトリン腺炎は大前庭腺の導管が閉塞して感染し、膿瘍を形成すると外陰部の強い疼痛と腫脹をきたす。歩行や坐位も困難になり、切開排膿を要する。

【誤答選択肢の解説】
A「子宮前屈」: 子宮前屈は正常な子宮の位置で、症状の原因にならない。
B「子宮腔癒着」: 子宮腔癒着(Asherman症候群)は無月経や不妊が問題となり、痛みは主症状でない。
C「子宮腟部びらん」: 子宮腟部びらんは無症状か帯下・接触出血が主で、疼痛は伴わない。
E「子宮頸管ポリープ」: 子宮頸管ポリープは不正性器出血が主症状で、無痛性である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C016（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-2', '正答は D「タンパク質 : 0.8g/kg/日」。

低栄養のある高齢者では、筋肉量の維持のため蛋白質を1.0〜1.2g/kg/日程度確保する。腎障害がない以上、0.8g/kg/日では不足で適切でない。

【誤答選択肢の解説】
A「水分 : 30mL/kg/日」: 水分30mL/kg/日は高齢者の目安として妥当である。
B「脂肪 : 総エネルギーの25%」: 脂肪を総エネルギーの20〜30%とするのは妥当である。
C「糖質 : 総エネルギーの55%」: 糖質を総エネルギーの50〜60%とするのは妥当である。
E「総エネルギー : 30kcal/kg/日」: 総エネルギー30kcal/kg/日は低栄養の改善を目指す量として妥当である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-20', '正答は B「ケトン体」。

糖質の供給が絶たれると脂肪酸のβ酸化が亢進し、肝でケトン体が産生される。飢餓性ケトーシスで、絶食2日目には血中ケトン体が明らかに上昇する。

【誤答選択肢の解説】
A「HbA1c」: HbA1cは過去1〜2か月の平均血糖を反映し、2日では変化しない。
C「アルブミン」: アルブミンは半減期が約21日で、2日では下がらない。
D「トリグリセリド」: トリグリセリドは食事由来のカイロミクロンが減るため、むしろ低下する。
E「総コレステロール」: 総コレステロールも短期の絶食で上昇しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C020（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-21', '正答は D「40歳未満女性の部位別悪性新生物では子宮頸がんが最も罹患率が高い。」。

40歳未満の女性では子宮頸癌の罹患率が最も高い。HPVワクチンと検診による予防が可能な癌であり、若年層への対策が課題となっている。

【誤答選択肢の解説】
A「脳血管疾患の患者数は年々増加している。」: 脳血管疾患の患者数は高血圧管理の普及により減少傾向にある。
B「過剰飲酒の割合は男性低所得層で最も高い。」: 生活習慣病のリスクとなる飲酒習慣は、男性では所得が高い層で割合が高い。
C「悪性新生物(全部位)年齢階級別死亡率は60代で増加傾向が見られる。」: 悪性新生物の年齢調整死亡率は全体として低下しており、60代で増加という事実はない。
E「糖尿病罹患は遺伝や生活習慣が主な要因で、社会的環境の関与は少ない。」: 糖尿病の発症には教育歴・所得・雇用形態など社会経済的要因が強く関与することが分かっている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C021（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-22', '正答は B「IL-6」。

IL-6は肝細胞に働いてCRPをはじめとする急性期蛋白の産生を誘導する中心的なサイトカインである。IL-6受容体を阻害するトシリズマブ投与中はCRPが上がらなくなり、感染の指標として使えなくなる点も重要である。

【誤答選択肢の解説】
A「IL-1」: IL-1は発熱や炎症の惹起に関わるが、CRP産生の主たる誘導因子ではない。
C「TGF-β」: TGF-βは線維化や免疫抑制に関わる。
D「TNF-α」: TNF-αも炎症の中心的なサイトカインだが、CRP産生はIL-6を介する。
E「インターフェロンγ」: インターフェロンγはマクロファージの活性化や細胞性免疫に働く。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-24', '正答は C「迷走神経」。

内喉頭筋は迷走神経の枝である反回神経(下喉頭神経)が支配する。輪状甲状筋のみ上喉頭神経外枝が支配するが、これも迷走神経の枝である。

【誤答選択肢の解説】
A「顔面神経」: 顔面神経は表情筋を支配する。
B「舌咽神経」: 舌咽神経は茎突咽頭筋と咽頭・舌後1/3の感覚を担う。
D「副神経」: 副神経は胸鎖乳突筋と僧帽筋を支配する。
E「舌下神経」: 舌下神経は舌筋を支配する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-25', '正答は A「人口動態統計に係る統計」。

人口動態統計は市区町村から都道府県、厚生労働省へと集計される国の統計業務で、地方衛生研究所の業務ではない。

【誤答選択肢の解説】
B「疾病予防に関する調査研究」: 地域の健康課題に関する調査研究は地方衛生研究所の業務である。
C「地域保健関係者の研修指導」: 保健所職員など地域保健関係者への研修指導も業務に含まれる。
D「衛生微生物に関する試験検査」: 衛生微生物や食品・環境の試験検査は中心的な業務である。
E「公衆衛生情報の収集・解析・提供」: 公衆衛生情報の収集・解析・提供も業務に含まれる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-26', '正答は B「平均寿命」。

平均寿命は医療の進歩と生活環境の改善により延び続けており、2019年は男性81.41年・女性87.45年で2009年より延伸している。

【誤答選択肢の解説】
A「総人口」: 総人口は2008年をピークに減少に転じている。
C「年間出生数」: 年間出生数は減少を続け、2019年に90万人を割り込んだ。
D「生産年齢人口」: 生産年齢人口(15〜64歳)も減少を続けている。
E「合計特殊出生率」: 合計特殊出生率は1.3台で推移し、2019年は2009年をやや下回る。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C026（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-3', '正答は C「輸入感染症患者の検疫」。

検疫は検疫所が国の機関として空港・海港で行う業務であり、医療機関の感染制御チームの役割ではない。

【誤答選択肢の解説】
A「職員の感染防止」: 職員のワクチン接種や針刺し事故対応など職業感染防止はチームの業務である。
B「定期的な院内の巡回」: 病棟ラウンドによる手指衛生や隔離の実施状況の確認は中心的な業務である。
D「適正な微生物検査の推進」: 適切な検体提出と培養検査の推進はチームの役割である。
E「院内感染発生に関するサーベイランス」: 耐性菌や医療関連感染のサーベイランスはチームの基本業務である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-37', '正答は D「小腸カプセル内視鏡」。

反復する暗赤色血便と鉄欠乏性貧血があり、上部・下部消化管内視鏡で出血源が特定できない原因不明消化管出血である。小腸が出血源として残るため、非侵襲的に全小腸を観察できるカプセル内視鏡を行う。

【誤答選択肢の解説】
A「小腸造影」: 小腸造影は血管拡張症など粘膜面のわずかな病変を捉えにくい。
B「腹部MRI」: 腹部MRIは腫瘍の検索には使えるが、小さな出血源の同定には向かない。
C「腹部血管造影」: 血管造影は0.5mL/分以上の活動性出血がなければ描出できず、受診時には出血が止まっている。
E「Meckel憩室シンチグラフィ」: Meckel憩室シンチグラフィは異所性胃粘膜を検出する検査で、小児の下血に用いる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C037（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-38', '正答は B「気管支鏡検査」。

閉鎖空間での火災で顔面・口腔に煤が付着し毛髪が焼けており、喘鳴も聴取する。気道熱傷が強く疑われ、気管支鏡で声門下から気管・気管支の粘膜傷害を直接評価する。浮腫が進む前の予防的気管挿管の判断にも直結する。

【誤答選択肢の解説】
A「胸部MRI」: 胸部MRIは気道粘膜の評価に向かず、緊急性のある場面で選ぶ検査ではない。
C「肺動脈造影検査」: 肺動脈造影は肺血栓塞栓症を疑うときの検査である。
D「肺血流シンチグラフィ」: 肺血流シンチグラフィも同様である。
E「上部消化管内視鏡検査」: 上部消化管内視鏡は腐食性物質の誤飲で行うもので、吸入による気道熱傷の評価にはならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C038（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-41', '正答は C「摂取エネルギー量の制限を指導する。」。

小刻み歩行と筋強剛があり振戦を欠くパーキンソニズムで、薬が大量に残っているという情報から服薬状況も把握できていない。抗精神病薬や制吐薬(スルピリド、メトクロプラミドなど)による薬剤性パーキンソニズムを疑い、まず内服薬の内容を確認する。原因薬があれば中止で改善しうる。

【誤答選択肢の解説】
A「認知機能の確認を行う。」: 認知機能の評価も必要だが、転倒の原因として直接介入できる薬剤性の可能性を先に確かめる。
D「在宅支援のために訪問看護の介入を依頼する。」: 訪問看護の導入は有用だが、原因の把握が先である。
E「頭部外傷後の遅発性合併症について説明を行う。」: 慢性硬膜下血腫の説明は必要だが、繰り返す転倒の原因への対応が優先される。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C041（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-42', '正答は E「5」。

毛細血管再充満時間が2秒を超えるのは末梢循環不全を示す所見である。3秒は明らかな延長で、脱水やショックの進行を意味する。

【誤答選択肢の解説】
A「1」: 足底刺激で開眼するのは意識レベルの評価で、循環の指標ではない。
B「2」: 皮膚色がピンク色であることは循環が保たれている所見である。
C「3」: ツルゴールの軽度低下は脱水を示すが、循環不全そのものの指標ではない。
D「4」: 口唇の乾燥も脱水の所見で、循環不全を直接示さない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C042（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-44', '正答は A「1」。

正常な新生児は生後24時間以内に胎便を排泄する。48時間かかっているのは胎便排泄遅延で、腹部膨満を伴うことからHirschsprung病や鎖肛、胎便性イレウスなどを疑う。

【誤答選択肢の解説】
B「2」: 出生体重3,100gに対し2,950gは4.8%の減少で、生理的体重減少(5〜10%)の範囲内である。
C「3」: 大泉門2×2cmは正常範囲である。
D「4」: 日齢3の黄疸は生理的黄疸として矛盾しない。
E「5」: 新生児で肝を右季肋下に1〜2cm触知するのは正常である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C044（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-45', '正答は B「12誘導心電図」。

糖尿病と陳旧性心筋梗塞があり、労作と無関係に発汗と悪心が反復している。糖尿病では神経障害のため胸痛を欠く無痛性心筋虚血が起こりうる。急性冠症候群を想定してまず12誘導心電図を記録する。

【誤答選択肢の解説】
A「胸部造影CT」: 胸部造影CTは大動脈解離や肺塞栓を疑うときの検査で、まず行うものではない。
C「心エコー検査」: 心エコーは壁運動異常の評価に有用だが、心電図より優先されない。
D「運動負荷心電図」: 急性冠症候群が否定されていない段階での運動負荷は危険である。
E「心筋シンチグラフィ」: 心筋シンチグラフィは待機的な虚血評価に用いる検査である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C045（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-46', '正答は A「初乳がみられる。」。

初乳は産褥2〜3日ごろから分泌が始まり、蛋白質と免疫グロブリンA、ラクトフェリンに富む。産褥3日目の所見として正しい。

【誤答選択肢の解説】
B「黄色悪露がみられる。」: 産褥3日は赤色悪露の時期である。黄色悪露は産褥2週ごろからみられる。
C「内子宮口は閉鎖している。」: 内子宮口が閉鎖するのは産褥10〜12日ごろで、3日目にはまだ開いている。
D「腹壁上から子宮底を触れない。」: 産褥3日では子宮底は臍下2〜3横指で触れる。触れなくなるのは産褥10〜12日ごろである。
E「産後の後陣痛を最も強く感じる。」: 後陣痛は分娩直後から翌日にかけて最も強く、産褥3日には軽快している。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C046（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-47', '正答は D「ビタミンD」。

魚介類も乳製品も10年以上摂っていない厳格な菜食で、低カルシウム血症と低リン血症をきたしている。手のこわばりは低カルシウム血症によるテタニー症状で、ビタミンDの欠乏を考える。

【誤答選択肢の解説】
A「亜鉛」: 亜鉛欠乏では味覚障害をきたすが、本例は味覚に異常がない。
B「葉酸」: 葉酸欠乏では大球性貧血をきたすが、血算は正常である。
C「ビタミンB1」: ビタミンB1欠乏では脚気やWernicke脳症をきたし、神経診察に異常が出る。
E「ビタミンE」: ビタミンE欠乏は稀で、失調や深部感覚障害をきたす。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C047（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-49', '正答は D「医療保護入院」。

本人の意思を確認できず、医療保護が必要な状態である。精神保健指定医の診察と家族等(ここでは夫)の同意により医療保護入院とする。

【誤答選択肢の解説】
A「緊急措置入院」: 緊急措置入院は自傷他害のおそれが著しく急を要する場合の形式である。
B「措置入院」: 措置入院も自傷他害のおそれがあり、2名の指定医の診察が必要な形式である。
C「応急入院」: 応急入院は家族等の同意が得られない場合に72時間を限度として行うもので、同意可能な夫がいる本例には当たらない。
E「任意入院」: 任意入院は本人の同意によるもので、意思を確認できない本例では選べない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C049（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-5', '正答は B「肺がん検診では判定に二重読影が行われる。」。

肺がん検診の胸部エックス線写真は、読影の見落としを減らすため2人以上による二重読影が行われる。比較読影も併せて行う。

【誤答選択肢の解説】
A「特定健診・特定保健指導は事業主が行う。」: 特定健診・特定保健指導の実施主体は医療保険者である。
C「地域包括支援センターは都道府県が設置する。」: 地域包括支援センターの設置主体は市町村である。
D「医療法に基づく5疾病5事業には高血圧が含まれる。」: 5疾病は癌・脳卒中・心筋梗塞等の心血管疾患・糖尿病・精神疾患で、高血圧は含まれない。
E「PSAによるがん検診は対策型がん検診において推奨されている。」: PSA検診は死亡率減少効果の証拠が不十分で、対策型検診としては推奨されていない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-51', '正答は C「「早朝1時間の散歩を始めたのは良いことですね」」。

すでに早朝の散歩を始めており、行動変容ステージの実行期にあたる。この段階では始めた行動を肯定的に評価して強化し、継続を支えることが有効である。

【誤答選択肢の解説】
A「「肥満は生活習慣病の原因のひとつです」」: 知識の提供は前熟考期から熟考期にかけての働きかけである。
B「「多くの人が散歩していると思いますよ」」: 周囲がやっているという情報は動機づけとして弱く、実行期の支援にならない。
D「「肥満は身体に良くないので痩せる努力をしましょう」」: 漠然と努力を促すのは、すでに実行している人への働きかけとして適切でない。
E「「肥満につながる生活スタイルを見直すと良いですよ」」: 生活の見直しを勧めるのは熟考期から準備期への働きかけである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C051（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-52', '正答は E「第1子の遺伝子検査が陰性でも診断は変わらない。」。

Duchenne型筋ジストロフィーの遺伝子検査(欠失・重複の検出)の感度はおよそ95%で、点変異などは検出されないことがある。臨床所見と筋病理で診断されている以上、遺伝子検査が陰性でも診断は変わらない。

【誤答選択肢の解説】
A「母親は本疾患の確定保因者である。」: およそ1/3は新生突然変異によるため、母親が確定保因者とは言えない。
B「本疾患に突然変異による発症はない。」: 新生突然変異による発症は珍しくない。
C「女性が本疾患の症状を示すことはない。」: X染色体不活化の偏りにより、保因者女性が症状を示すことがある(manifesting carrier)。
D「本疾患の遺伝子検査の感度は100%である。」: 感度は100%ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C052（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-54', '正答は C「出発国への送還」。

検疫法に基づき検疫所長が行えるのは、隔離・停留、消毒、質問・診察・検査、健康監視などである。出発国への送還を命じる権限はない。

【誤答選択肢の解説】
A「本人の隔離」: 一類感染症の患者に対する隔離は検疫法に定められた措置である。
B「航空機の消毒」: 航空機・船舶や物件の消毒も検疫所長が行える措置である。
D「出発国での行動歴の聴取」: 質問により行動歴や接触者を聴取することは検疫法に基づく措置である。
E「可能性のある病原体の検査」: 病原体の検査も検疫所長が行える措置である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C054（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-7', '正答は E「特定の区域を超えて世界中で感染が拡大して持続している状態」。

パンデミックは、特定の地域を超えて世界的な規模で感染が拡大し持続している状態を指す。

【誤答選択肢の解説】
A「人への新しい種類の感染が確認された状態」: 人への新しい種類の感染が確認された状態は、新興感染症の出現である。
B「通常の予測以上に感染が拡大している状態」: 通常の予測を超えて感染が拡大するのはアウトブレイクである。
C「特定の区域や集団内で予測以上に感染が拡大している状態」: 特定の区域や集団内での予測以上の拡大はエピデミックである。
D「特定の区域などで普段から継続的に感染が発生している状態」: 特定の区域で継続的に発生している状態はエンデミック(常在)である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-8', '正答は D「自律神経系の活動が変動しやすい。」。

レム睡眠では交感神経と副交感神経の活動が不安定に変動し、心拍数や血圧、呼吸が乱れやすい。早朝のレム睡眠期に心血管イベントが起こりやすいのはこのためである。

【誤答選択肢の解説】
A「徐波睡眠と呼ばれる。」: 徐波睡眠と呼ばれるのはノンレム睡眠の深い段階である。
B「骨格筋の活動が活発になる。」: レム睡眠では抗重力筋の緊張が完全に消失する。
C「夢を見ていることが少ない。」: レム睡眠中に覚醒させると高率に夢の報告が得られる。
E「成人では一晩の睡眠の半分以上を占める。」: レム睡眠は成人で全睡眠時間のおよそ20〜25%である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-C-9', '正答は E「患者世帯の標準報酬月額」。

高額療養費制度の自己負担限度額は、70歳未満では標準報酬月額(所得区分)によって、70歳以上では所得区分と外来・入院の別によって決まる。疾患の種類や医療機関の規模では変わらない。

【誤答選択肢の解説】
A「疾患の種類」: 疾患の種類による区別はない。
B「治療の種類」: 治療の種類でも変わらない。
C「疾患の罹病期間」: 罹病期間ではなく、同一月の自己負担額で判定する。
D「受診医療機関の規模」: 医療機関の規模は限度額を規定しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 C009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-10', '正答は D「胚染色体異常」。

妊娠12週未満の早期流産の原因として最も多いのは胎児(胚)の染色体異常で、およそ半数以上を占める。偶発的に生じるもので、母体側の行動によるものではない点を説明することが大切である。

【誤答選択肢の解説】
A「子宮奇形」: 子宮奇形は流産の原因となりうるが頻度は低い。
B「子宮筋腫」: 子宮筋腫も粘膜下筋腫などで流産に関与しうるが、最多ではない。
C「頸管無力症」: 頸管無力症は妊娠中期以降の流早産の原因である。
E「抗リン脂質抗体症候群」: 抗リン脂質抗体症候群は反復流産の重要な原因だが、全体としての頻度は染色体異常に及ばない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-17', '正答は B「切符を買うなどの一般的な行動はできる。」。

身元の記憶を失いながら、日常の行動能力や新たな記憶は保たれている。解離性同一性の障害を伴う解離性健忘(解離性遁走)で、切符を買う、会話するといった手続き的・日常的な行動は問題なく行える。

【誤答選択肢の解説】
A「替え玉妄想がみられる。」: 替え玉妄想(Capgras症候群)は器質性疾患や統合失調症でみられる別の症候である。
C「記憶がないことについて深刻に悩んでいる。」: 記憶がないことに対して深刻に悩まず淡々としている(満ち足りた無関心)のが特徴である。
D「抗精神病薬を投与する必要がある。」: 解離性障害に抗精神病薬の適応はない。
E「アルツハイマー型認知症の初期症状である。」: Alzheimer型認知症では近時記憶から障害され、保護後の記憶が保たれることはない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-18', '正答は A「α遮断薬」。

α遮断薬は末梢血管を拡張させる降圧薬で、抗不整脈作用を持たない。特発性心室頻拍の薬物療法には用いられない。

【誤答選択肢の解説】
B「β遮断薬」: β遮断薬は交感神経を介した心室頻拍の抑制に用いられる。
C「I群抗不整脈薬」: I群抗不整脈薬(Naチャネル遮断薬)は心室頻拍に用いられる。
D「ベラパミル」: ベラパミルはベラパミル感受性特発性心室頻拍に有効である。
E「ジルチアゼム」: ジルチアゼムも同じ非ジヒドロピリジン系カルシウム拮抗薬として用いられうる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D018（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-19', '正答は C「中枢性鎮咳薬の投与」。

喫煙歴が長く口すぼめ呼吸を認め、感染を契機に増悪したCOPDである。喀痰の喀出が治療の要であり、中枢性鎮咳薬で咳を止めると痰が貯留して気道閉塞と感染の悪化を招く。

【誤答選択肢の解説】
A「酸素療法」: SpO2 87%であり、CO2ナルコーシスに注意しつつ酸素療法を行う。適切である。
B「抗菌薬の投与」: 黄色痰と発熱があり、細菌感染を伴う増悪として抗菌薬を投与する。適切である。
D「副腎皮質ステロイドの投与」: COPD増悪では全身性ステロイドの短期投与が回復を早める。適切である。
E「短時間作用型β2刺激薬の吸入」: 短時間作用型β2刺激薬の吸入は気流閉塞の改善に有効である。適切である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-2', '正答は A「「自分は電波で操られている」」。

「電波で操られている」という訴えは、自分の意思や行動が外部の力に支配されているという作為体験(させられ体験)で、自我障害にあたる。Schneiderの一級症状に含まれ統合失調症を強く示唆する。

【誤答選択肢の解説】
B「「(壁のしみを指して)虫が這っている」」: 壁のしみが虫に見えるのは錯視で、せん妄やアルコール離脱でみられる。
C「「電車の中で発作が起こるのが心配です」」: 発作への予期不安はパニック症の症状である。
D「「人前では緊張して思うように話すことができません」」: 人前での過度の緊張は社交不安症の症状である。
E「「鍵をかけたのか何度も確認しないと気が済みません」」: 施錠の確認を繰り返すのは強迫症の強迫行為である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-21', '正答は C「出血性脳梗塞を併発後の昏睡状態」。

感染性心内膜炎に出血性脳梗塞を併発して昏睡状態にある場合、体外循環に伴う抗凝固で頭蓋内出血が拡大する危険が高く、早期手術は避けて時期を待つ。他の選択肢はいずれも早期手術の適応である。

【誤答選択肢の解説】
A「弁穿孔の合併」: 弁穿孔による急性弁逆流は手術適応である。
B「弁周囲膿瘍の形成」: 弁周囲膿瘍は抗菌薬だけでは制御できず、手術適応である。
D「疣贅が増大し塞栓症がみられる場合」: 可動性の大きな疣贅や塞栓の反復は手術適応である。
E「内科的にコントロールが困難な心不全の出現」: 内科的に制御できない心不全は最も明確な手術適応である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D021（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-22', '正答は A「レム〈REM〉睡眠行動障害」。

夢の内容に一致した大声や粗大な体動が睡眠中に現れており、レム睡眠中に本来生じる筋緊張の消失が失われるレム睡眠行動障害である。α-シヌクレイノパチー(Parkinson病、Lewy小体型認知症、多系統萎縮症)の前駆症状となることが知られている。

【誤答選択肢の解説】
B「睡眠時無呼吸症候群」: 睡眠時無呼吸症候群はいびきと無呼吸、日中の眠気が主体で、粗大な体動は伴わない。
C「下肢静止不能症候群」: 下肢静止不能症候群は入眠前の下肢の不快感と動かしたい衝動が特徴である。
D「突発睡眠」: 突発睡眠(ナルコレプシー)は日中の耐えがたい眠気が主症状である。
E「夜驚症」: 夜驚症はノンレム睡眠から生じる小児の睡眠時随伴症で、本人に記憶が残らない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-24', '正答は D「鎮痛状況により投与量の調節を行う。」。

癌性疼痛に対するオピオイドは、痛みの強さに応じて有効かつ副作用が許容できる量まで個々に調節する(タイトレーション)。上限を決めた固定量で使うものではない。

【誤答選択肢の解説】
A「貼付薬は使用できない。」: フェンタニル貼付薬など経皮吸収型製剤が使用でき、経口摂取が難しい患者にも有用である。
B「疼痛時にのみ投与する。」: 持続する痛みには定時投与が原則で、疼痛時のみの頓用では痛みの波を抑えられない。
C「注射薬から投与を開始する。」: 経口摂取が可能であれば経口薬から開始する。
E「レスキューは長時間作用性の薬剤を用いる。」: レスキューには即効性のある速放性製剤を用いる。長時間作用性では間に合わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-28', '正答は E「「以前にこのようなことはありましたか」」。

過去に同様のことがあったかどうかは、今回の誤飲に対する処置の判断には結びつかない。何を・どれだけ・いつ飲んだか、その後どうしたかが処置を決める情報である。

【誤答選択肢の解説】
A「「吐かせましたか」」: すでに嘔吐させたかどうかは、追加処置や誤嚥のリスク評価に必要である。
B「「水を飲ませましたか」」: 水を飲ませたかどうかは、たばこの場合ニコチンの吸収を早めるため重要な情報である。
C「「口の中に何か入っていましたか」」: 口腔内の残存物は摂取物の同定と量の推定につながる。
D「「どれくらい時間がたっていますか」」: 経過時間は催吐や吸着の適応、症状出現の見通しを決める。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D028（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-3', '正答は C「Forrester分類」。

Forrester分類は、肺動脈楔入圧18mmHgと心係数2.2L/分/m2を境として心不全を4群に分ける。Swan-Ganzカテーテルによる実測値に基づく分類である。

【誤答選択肢の解説】
A「AHA(American Heart Association)心不全ステージ分類」: AHA/ACCのステージ分類は器質的心疾患の有無と症状によるもので、血行動態の実測値を用いない。
B「Child分類」: Child分類は肝硬変の重症度分類である。
D「Nohria-Stevenson分類」: Nohria-Stevenson分類はうっ血と低灌流を身体所見から判断する分類で、カテーテルを要さない。
E「NYHA心機能分類」: NYHA分類は自覚症状に基づく機能分類である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-34', '正答は B「多系統萎縮症」。

起立性低血圧(収縮期で30mmHgの低下)、便秘と尿失禁という自律神経障害に、小脳性運動失調(測定障害・変換運動障害・体幹動揺)と振戦を欠くパーキンソニズムが加わっている。多系統萎縮症である。

【誤答選択肢の解説】
A「Parkinson病」: Parkinson病では小脳症状を欠き、初期からこれほど高度の自律神経障害は出にくい。
C「Huntington病」: Huntington病は舞踏運動と精神症状・認知機能低下が主体である。
D「筋萎縮性側索硬化症」: 筋萎縮性側索硬化症は上位・下位運動ニューロン徴候が主体で、自律神経障害や小脳症状は目立たない。
E「大脳皮質基底核変性症」: 大脳皮質基底核変性症は左右差の強い失行と筋強剛が特徴で、自律神経障害は前景に出ない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D034（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-35', '正答は A「肺拡散能検査」。

製パン工房で働き始めてから、職場にいる日中だけ乾性咳嗽が出て週末には消える。小麦粉抗原による職業性の気道アレルギー(baker''s asthma)を考え、原因抗原に対する特異的IgE抗体を測定する。好酸球12%と花粉症の既往もアトピー素因を支持する。

【誤答選択肢の解説】
B「気道過敏性試験」: 気道過敏性試験は喘息の診断に有用だが、原因抗原を特定できない。
D「気道可逆性試験」: 気道可逆性試験も喘息の証明にはなるが、職業曝露との因果を示さない。
E「ピークフロー日内変動」: ピークフローの日内変動は喘息の指標だが、抗原の同定には至らない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D035（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-38', '正答は B「左股関節切開・洗浄」。

発熱に続いて左下肢を動かさなくなり、他動運動で強く泣き、著明な炎症反応がある。乳児の化膿性股関節炎で、関節軟骨と大腿骨頭が急速に破壊されるため、緊急に切開・洗浄してドレナージすることが必要である。

【誤答選択肢の解説】
A「NSAID内服」: NSAIDでは感染は制御できず、診断と治療が遅れる。
C「両下肢オーバーヘッド牽引」: 牽引は化膿性関節炎の治療にならない。
D「リーメンビューゲル装具着用」: リーメンビューゲル装具は発育性股関節形成不全に用いる。
E「副腎皮質ステロイド左股関節内投与」: 感染している関節へのステロイド投与は病態を悪化させる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D038（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-39', '正答は D「50%」。

両側の側腹部腫瘤、成人期発症の腎障害、くも膜下出血の家族歴、複数の血縁者の透析歴から常染色体顕性多発性囊胞腎である。常染色体顕性遺伝なので、子への伝達確率は50%である。

【誤答選択肢の解説】
A「0%」: 遺伝性であり0%ではない。
B「25%」: 25%は常染色体潜性遺伝の場合の再発率である。
C「33%」: 33%という値は遺伝形式から導かれない。
E「100%」: 100%となるのは変異がホモ接合の場合などで、この疾患では該当しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D039（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-4', '正答は D「糖質コルチコイドの増量」。

先天性副腎皮質過形成症では内因性のコルチゾール分泌が不足しており、発熱などのストレス下では需要に見合った増加ができない。副腎クリーゼを防ぐため、糖質コルチコイドを通常の2〜3倍に増量する(シックデイルール)。

【誤答選択肢の解説】
A「水分制限」: 水分制限はむしろ脱水と循環虚脱を招く。
B「抗菌薬投与」: 抗菌薬は原因が細菌感染と判断されれば用いるが、初期対応の要点ではない。
C「利尿薬静注」: 利尿薬は循環血液量を減らし危険である。
E「グルコース・インスリン療法」: グルコース・インスリン療法は高カリウム血症の治療で、初期対応として選ぶものではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-40', '正答は D「経口副腎皮質ステロイド」。

難治性喘息に末梢血好酸球の著明な増加と中枢性気管支拡張、抗菌薬に反応しない肺陰影があり、アレルギー性気管支肺アスペルギルス症を考える。治療の中心は経口副腎皮質ステロイドで、必要に応じて抗真菌薬を併用する。

【誤答選択肢の解説】
A「シクロスポリン」: シクロスポリンはステロイド抵抗例に検討されることはあるが第一選択ではない。
B「セフェム系抗菌薬」: 真菌に対する免疫反応が病態であり、細菌用の抗菌薬は無効である。
C「高用量吸入ステロイド」: 吸入ステロイドだけでは中枢気道の粘液栓と免疫反応を抑えられない。
E「アスペルギルス減感作療法」: アスペルギルスの減感作療法は確立した治療法ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D040（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-47', '正答は C「ボツリヌス症」。

蜂蜜を与えられた乳児に便秘が先行し、哺乳力低下、眼瞼下垂、散瞳と対光反射遅延、頸定の消失、腱反射消失が現れている。乳児ボツリヌス症で、腸管内で発芽した芽胞が産生する毒素が神経筋接合部を遮断する。1歳未満に蜂蜜を与えてはならない。

【誤答選択肢の解説】
A「脳性麻痺」: 脳性麻痺は非進行性で、4か月まで発達良好だった児に急性に発症することはない。
B「重症筋無力症」: 重症筋無力症でも眼瞼下垂は出るが、瞳孔は侵されず対光反射は正常である。
D「先天性ミオパチー」: 先天性ミオパチーは出生時から筋緊張低下があり、急性発症ではない。
E「Werdnig-Hoffmann病」: Werdnig-Hoffmann病も進行性だが、瞳孔散大や便秘の先行は特徴でない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D047（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-49', '正答は E「劇症肝炎」。

意識障害にPT-INR延長とFDP上昇を伴い、肝性脳症をきたしている。非ホジキンリンパ腫の治療歴があり、化学療法に伴うHBV再活性化による劇症肝炎が典型的な経過である。治療前のHBs抗原・HBc抗体の確認と、再活性化のモニタリングが欠かせない。

【誤答選択肢の解説】
A「原発性硬化性胆管炎」: 原発性硬化性胆管炎は慢性の胆汁うっ滞で、急性の意識障害と凝固障害を説明しない。
B「被包化膵臓壊死」: 被包化膵臓壊死は重症膵炎の後期合併症である。
C「急性膵炎」: 急性膵炎では上腹部痛と膵酵素上昇が主体で、肝性脳症はきたさない。
D「急性肝炎」: 急性肝炎でも肝逸脱酵素は上がるが、昏睡と高度の凝固障害を伴えば劇症肝炎と呼ぶ。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D049（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-5', '正答は B「食道アカラシア」。

食道アカラシアは下部食道括約筋の弛緩不全による疾患で、内視鏡下バルーン拡張術や経口内視鏡的筋層切開術(POEM)が治療として行われる。

【誤答選択肢の解説】
A「食道憩室」: 食道憩室の治療は外科的切除で、内視鏡治療の対象ではない。
C「食道カンジダ症」: 食道カンジダ症は抗真菌薬による薬物療法で治療する。
D「食道裂孔ヘルニア」: 食道裂孔ヘルニアの根治には腹腔鏡下噴門形成術など外科手術を行う。
E「非びらん性胃食道逆流症」: 非びらん性胃食道逆流症はプロトンポンプ阻害薬などの薬物療法が中心である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-50', '正答は C「活性型葉酸」。

メトトレキサートの継続投与により汎血球減少と口腔粘膜のびらん、消化器症状をきたしている。葉酸代謝の阻害が本態なので、活性型葉酸(ホリナート)を投与して救済する(ロイコボリン救援)。同時にメトトレキサートは中止する。

【誤答選択肢の解説】
A「ST合剤」: ST合剤も葉酸代謝を阻害するため、メトトレキサート中毒では併用を避ける。
B「抗真菌薬」: 真菌感染が確認されていない段階で抗真菌薬を主治療にはしない。
D「ビタミンB12」: ビタミンB12欠乏による血球減少ではない。
E「副腎皮質ステロイド」: ステロイドは骨髄抑制と粘膜障害の是正にならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D050（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-51', '正答は C「麻薬性鎮痛薬投与」。

排便により軽快する腹痛と便通異常が続き、内視鏡で器質的疾患が否定されている過敏性腸症候群である。麻薬性鎮痛薬は依存を生むうえ便秘を悪化させ、慢性の機能性疾患には用いない。

【誤答選択肢の解説】
A「止痢薬投与」: 下痢型では止痢薬(ロペラミドなど)が用いられる。
B「食物繊維摂取」: 食物繊維(水溶性)の摂取は便性の改善に有用である。
D「プロバイオティクス摂取」: プロバイオティクスは症状の改善に用いられる。
E「セロトニン5-HT3受容体拮抗薬投与」: 5-HT3受容体拮抗薬(ラモセトロン)は下痢型過敏性腸症候群の治療薬である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D051（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-55', '正答は D「エリスロポエチン増加」。

肥満といびき、無呼吸の目撃があり閉塞性睡眠時無呼吸症候群による夜間の低酸素血症が背景にある。低酸素が腎でのエリスロポエチン産生を刺激して二次性赤血球増多をきたすため、エリスロポエチンは増加する。

【誤答選択肢の解説】
A「ヒスタミン増加」: ヒスタミン増加は真性多血症でみられ、そう痒の原因となる。
B「ビタミンB12増加」: ビタミンB12増加も真性多血症や慢性骨髄性白血病でみられる。
C「JAK2遺伝子変異陽性」: JAK2遺伝子変異は真性多血症の所見で、二次性ではみられない。
E「フィラデルフィア染色体陽性」: フィラデルフィア染色体は慢性骨髄性白血病の所見である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D055（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-58', '正答は A「補液」。

異型リンパ球の出現、後頸部リンパ節腫脹、肝逸脱酵素の上昇から伝染性単核球症である。特異的治療はなく、水分が摂れていないため補液で脱水を補正する対症療法を行う。

【誤答選択肢の解説】
B「口蓋扁桃摘出術」: 扁桃摘出術は急性期に行うものではない。気道閉塞が切迫すればステロイドを用いる。
C「ペニシリンの投与」: ペニシリン系(とくにアンピシリン)は高率に薬疹を誘発するため避ける。
D「抗ウイルス薬の投与」: EBウイルスに有効な抗ウイルス薬はない。
E「抗アレルギー薬の投与」: アレルギー疾患ではなく抗アレルギー薬の適応がない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D058（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-59', '正答は D「種別ごとの復帰プログラムに基づいて段階的に復帰させる。」。

意識消失と受傷前後の健忘があり脳振盪である。画像に異常がなくても、その日のうちに競技へ戻してはならない。無症状を確認しながら段階的競技復帰プログラムに沿って進める。

【誤答選択肢の解説】
A「速やかに試合へ復帰させる。」: 当日の復帰はセカンドインパクト症候群の危険があり禁忌である。
B「受傷後3時間の経過をみて試合に復帰させる。」: 3時間の経過観察では不十分である。
C「受傷後12時間の経過をみて試合に復帰させる。」: 12時間でも同様に不十分である。
E「今後、同一のスポーツへの復帰はさせない。」: 適切な段階的復帰を経れば同一競技に戻ることができ、一律に禁止する根拠はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D059（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-6', '正答は C「Buerger病」。

Buerger病(閉塞性血栓血管炎)は四肢の中小動脈に炎症性血栓を生じて閉塞をきたす疾患で、動脈壁が膨らむ動脈瘤は形成しない。喫煙との関連が強い。

【誤答選択肢の解説】
A「梅毒」: 梅毒性大動脈炎は上行大動脈に瘤を作る古典的な原因である。
B「動脈硬化」: 動脈硬化は腹部大動脈瘤の最も多い原因である。
D「高安動脈炎」: 高安動脈炎は大動脈とその分枝に狭窄だけでなく瘤も作る。
E「Marfan症候群」: Marfan症候群ではフィブリリンの異常により大動脈基部拡張・瘤・解離をきたす。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-62', '正答は D「尿中アルブミン/クレアチニン比の測定」。

糖尿病性腎症の早期診断には尿中アルブミンの評価が必要である。試験紙法の尿蛋白が陰性でも微量アルブミン尿の段階があり、尿中アルブミン/クレアチニン比が30mg/gCr以上で早期腎症と判定する。

【誤答選択肢の解説】
A「腎臓超音波検査」: 腎臓超音波検査は形態評価で、糖尿病性腎症の病期判定にならない。
B「血中クレアチニンの測定」: 血清クレアチニンは腎機能の指標だが、早期腎症では正常である。
C「血中シスタチンCの測定」: シスタチンCも糸球体濾過量の指標で、アルブミン尿の有無は分からない。
E「尿中β2-マイクログロブリン/クレアチニン比の測定」: β2-マイクログロブリンは尿細管障害の指標で、糖尿病性腎症の診断基準ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D062（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-63', '正答は A「抗菌薬内服」。

通年性の鼻閉・水様性鼻汁・くしゃみに蒼白で浮腫状の鼻粘膜があり、通年性アレルギー性鼻炎である。細菌感染を示す所見はなく、抗菌薬の適応がない。上顎洞粘膜の肥厚もアレルギー性の変化として説明できる。

【誤答選択肢の解説】
B「減感作療法」: 抗原が同定できれば減感作療法(アレルゲン免疫療法)は根治的治療になりうる。
C「鼻内レーザー手術」: 鼻内レーザー手術は鼻閉が強い症例の下鼻甲介に対して行われる。
D「抗ヒスタミン薬内服」: 抗ヒスタミン薬はくしゃみ・鼻汁に有効である。
E「副腎皮質ステロイド点鼻」: 鼻噴霧用ステロイドは鼻閉を含む全症状に有効で、治療の中心となる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D063（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-7', '正答は D「腹部エコー検査」。

腎後性急性腎障害は尿路の閉塞によるもので、腹部超音波で水腎症や膀胱の尿貯留を確認すれば速やかに診断できる。非侵襲的で最初に行うべき検査である。閉塞が解除できれば腎機能は回復しうる。

【誤答選択肢の解説】
A「腎生検」: 腎生検は腎性の鑑別に用いるもので、閉塞の有無は分からない。
B「尿蛋白定量」: 尿蛋白定量は糸球体疾患の評価で、閉塞の判定にならない。
C「尿比重測定」: 尿比重は腎前性と腎性の鑑別の参考になるが、腎後性は区別できない。
E「血清クレアチニン値測定」: 血清クレアチニンは腎障害の程度を示すだけで、原因の部位を示さない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-D-8', '正答は E「伝染性膿痂疹」。

伝染性膿痂疹(とびひ)は黄色ブドウ球菌やA群レンサ球菌による急性の細菌感染症で、水疱や痂皮が接触により拡大する。

【誤答選択肢の解説】
A「癜風」: 癜風はMalassezia属による表在性真菌症である。
B「掌蹠膿疱症」: 掌蹠膿疱症は無菌性の膿疱を繰り返す慢性疾患で、扁桃や歯性の病巣感染が関与する。
C「膿疱性乾癬」: 膿疱性乾癬も無菌性膿疱を生じる慢性炎症性疾患である。
D「化膿性汗腺炎」: 化膿性汗腺炎は毛包の閉塞に始まる慢性反復性の炎症性疾患で、急性の細菌感染症ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 D008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-1', '正答は C「呼吸機能検査」。

呼吸機能検査は閉塞性・拘束性障害の評価に用いるもので、血痰の原因(腫瘍・感染・気管支拡張症・抗凝固薬など)の検索には直接寄与しない。

【誤答選択肢の解説】
A「喀痰細胞診」: 喀痰細胞診は肺癌の検索に有用である。
B「内服薬の確認」: 抗凝固薬や抗血小板薬の服用は血痰の原因になるため確認が必要である。
D「喀痰抗酸菌検査」: 肺結核は血痰の重要な原因で、抗酸菌検査は必須である。
E「胸部エックス線写真」: 胸部エックス線写真は腫瘍・感染・気管支拡張症の評価の第一歩である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-10', '正答は B「妊娠蛋白尿」。

妊娠高血圧症候群の病型は、妊娠高血圧腎症・妊娠高血圧・加重型妊娠高血圧腎症・高血圧合併妊娠の4つである。蛋白尿のみで高血圧を伴わない「妊娠蛋白尿」は現在の分類に含まれない。

【誤答選択肢の解説】
A「妊娠高血圧」: 妊娠高血圧は妊娠20週以降の高血圧で蛋白尿や臓器障害を伴わないものである。
C「高血圧合併妊娠」: 高血圧合併妊娠は妊娠前または妊娠20週までに高血圧を認めるものである。
D「妊娠高血圧腎症」: 妊娠高血圧腎症は高血圧に蛋白尿または臓器障害を伴うものである。
E「加重型妊娠高血圧腎症」: 加重型妊娠高血圧腎症は高血圧合併妊娠に蛋白尿や臓器障害が加わったものである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-11', '正答は E「弾性ストッキング着用」。

弾性ストッキングは下肢の静脈還流を助けて静脈うっ滞を防ぎ、間欠的空気圧迫法とともに周術期の静脈血栓塞栓症の物理的予防法として用いられる。

【誤答選択肢の解説】
A「絶飲食」: 絶飲食は脱水と血液濃縮を招き、血栓形成をむしろ促す。
B「長期臥床」: 長期臥床は静脈うっ滞をつくる最大の危険因子で、早期離床が予防になる。
C「酸素投与」: 酸素投与は血栓形成を防がない。
D「尿道カテーテル留置」: 尿道カテーテルの留置は離床を妨げ、予防に逆行する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-13', '正答は E「肋骨脊柱角の叩打痛」。

肋骨脊柱角(CVA)の叩打痛は腎実質の炎症による所見で、発熱・膿尿と併せて腎盂腎炎の診断を支持する。膀胱炎との鑑別点になる。

【誤答選択肢の解説】
A「Grey-Turner徴候」: Grey-Turner徴候は側腹部の皮下出血で、出血性膵炎や後腹膜出血の所見である。
B「Rovsing徴候」: Rovsing徴候は左下腹部の圧迫で右下腹部に痛みが生じる虫垂炎の所見である。
C「Rosenstein徴候」: Rosenstein徴候も虫垂炎の所見で、左側臥位で圧痛が増強する。
D「反跳痛」: 反跳痛は腹膜刺激徴候で、腎盂腎炎に特異的ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E013（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-15', '正答は C「石綿肺 — fine crackles」。

石綿肺は間質性肺疾患で、吸気終末に聴かれる細かい断続性ラ音(fine crackles)が特徴である。ばち指を伴うことも多い。

【誤答選択肢の解説】
A「COPD — stridor」: COPDでは呼気延長と笛声音(wheeze)を聴取する。stridorは上気道狭窄の所見である。
B「胸膜炎 — rhonchi」: 胸膜炎では胸膜摩擦音(friction rub)を聴取する。
D「肺水腫 — Hammanʼs crunch」: 肺水腫では粗い断続性ラ音(coarse crackles)を聴取する。Hamman徴候は縦隔気腫の所見である。
E「気管支喘息 — friction rub」: 気管支喘息ではwheezeを聴取する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E015（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-16', '正答は B「受療行動調査」。

受療行動調査は、患者が医療機関を選んだ理由、受けた医療の内容、待ち時間、そして満足度などを調べる調査である。

【誤答選択肢の解説】
A「患者調査」: 患者調査は傷病の種類や受療率など医療の需要を把握する調査で、満足度は扱わない。
C「病院機能評価」: 病院機能評価は第三者機関による医療の質の評価で、患者への満足度調査そのものではない。
D「医療事故調査制度」: 医療事故調査制度は予期しない死亡事例の原因究明と再発防止のための制度である。
E「産科医療補償制度」: 産科医療補償制度は分娩に関連して発症した重度脳性麻痺への補償制度である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E016（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-17', '正答は A「脳性麻痺」。

脳性麻痺は周産期などに生じた非進行性の脳病変による運動障害で、上位運動ニューロンの障害により痙性麻痺(筋緊張亢進・腱反射亢進・病的反射)を呈する型が最も多い。

【誤答選択肢の解説】
B「ボツリヌス症」: ボツリヌス症は神経筋接合部の遮断による弛緩性麻痺である。
C「脊髄性筋萎縮症」: 脊髄性筋萎縮症は前角細胞の変性による下位運動ニューロン障害で、弛緩性麻痺となる。
D「Prader-Willi症候群」: Prader-Willi症候群は乳児期の著明な筋緊張低下が特徴である。
E「Guillain-Barré症候群」: Guillain-Barré症候群は末梢神経の脱髄による弛緩性麻痺である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-18', '正答は D「注射針は皮膚に対し直角に刺入する。」。

筋肉注射では、皮下組織を越えて筋層に確実に届かせるため皮膚に対して90度で刺入する。三角筋では肩峰から3横指下を選ぶ。

【誤答選択肢の解説】
A「注射針は18Gを使用する。」: 18Gは太すぎる。ワクチンの筋注には23〜25G程度を用いる。
B「接種後は接種部位をよく揉む。」: 接種後に揉むと組織の損傷や吸収の変動を招くため、揉まずに押さえる。
C「血液逆流を確認後に薬液を注入する。」: 逆流が「ない」ことを確認する。逆流があれば血管内であり刺し直す。
E「接種後は5分間観察して帰宅を許可する。」: アナフィラキシーは接種後30分以内に多く、少なくとも15〜30分の観察が必要である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E018（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-19', '正答は C「横紋筋融解症」。

横紋筋融解症は筋の広範な壊死による病態で、静脈採血で起こるものではない。

【誤答選択肢の解説】
A「消毒薬に対するアレルギー反応」: 消毒用アルコールなどへのアレルギー反応は起こりうる。
B「血管迷走神経反射」: 血管迷走神経反射は採血中の失神として最も頻度の高い合併症である。
D「神経損傷」: 神経損傷は穿刺部位によっては起こりうる重大な合併症である。
E「皮下血腫」: 皮下血腫は圧迫不十分などで日常的にみられる合併症である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-2', '正答は E「虐待が疑われるため家族の同意なく児童の情報を児童相談所に通報した。」。

児童虐待防止法は、虐待を受けたと思われる児童を発見した者に通告義務を課しており、この通告は守秘義務違反にあたらないと明記されている。家族の同意は不要である。

【誤答選択肢の解説】
A「診断のため本人の同意なく患者の家系を調べた。」: 家系の調査は遺伝情報という機微な個人情報を扱うため、本人の同意が要る。
B「診療の内容を患者の実名を含めてSNSに投稿した。」: 実名を含む診療内容の投稿は守秘義務違反であり、絶対に許されない。
C「検体の血液が余ったので本人の同意なく遺伝子配列を解析した。」: 残余検体であっても遺伝子解析には別途の同意が必要である。
D「学習のため本人の同意なく患者の皮膚所見をホームページに載せた。」: 皮膚所見の公開も個人情報の第三者提供にあたり、同意が要る。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-20', '正答は B「適用となるのは常時50人以上の事業場である。」。

長時間労働者に対する医師の面接指導は、事業場の規模にかかわらずすべての事業場に義務づけられている。常時50人以上という要件があるのは産業医の選任やストレスチェックの実施である。

【誤答選択肢の解説】
A「うつ病や自殺の予防が目的に含まれる。」: メンタルヘルス対策として、うつ病や自殺の予防は目的に含まれる。正しい。
C「脳血管・心臓疾患のリスク管理として重要である。」: 過重労働による脳・心臓疾患の発症予防が制度の主眼である。正しい。
D「時間外労働が月80時間超の労働者は希望により面接指導が受けられる。」: 時間外・休日労働が月80時間を超え疲労の蓄積が認められる労働者は、申出により面接指導を受けられる。正しい。
E「事業者は過重労働者に対し医師による面接指導の実施が義務づけられている。」: 事業者には面接指導の実施義務がある。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E020（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-21', '正答は B「突然、意識を失い倒れこんだ。」。

Adams-Stokes症候群は徐脈性・頻脈性不整脈による脳虚血で、前駆症状なく突然意識を失い、不整脈が改善すれば速やかに意識が戻る。

【誤答選択肢の解説】
A「排尿後に意識消失した。」: 排尿後の失神は状況失神(神経調節性失神)である。
C「意識が回復した後、上下肢の麻痺を認めた。」: 意識回復後に麻痺が残るのは脳卒中を示唆する。
D「舌を嚙んでいて口腔内からの出血を認めた。」: 舌咬傷はてんかん発作を示唆する。
E「意識が回復した後、意識がもうろうとしていた。」: 回復後のもうろう状態(発作後もうろう)もてんかんを示唆する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E021（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-22', '正答は D「末梢神経伝導検査」。

手根管症候群では正中神経が手根管内で絞扼される。末梢神経伝導検査で手関節部の遠位潜時延長と伝導速度低下を示し、絞扼部位を客観的に示せる。

【誤答選択肢の解説】
A「脳波検査」: 脳波検査は大脳の機能評価で、末梢神経の絞扼は分からない。
B「針筋電図検査」: 針筋電図は神経原性変化の有無を見るが、絞扼部位の同定には伝導検査が有用である。
C「脳脊髄液検査」: 脳脊髄液検査は中枢神経疾患の評価に用いる。
E「反復誘発筋電図検査」: 反復誘発筋電図は重症筋無力症など神経筋接合部疾患の検査である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-23', '正答は C「システムレビューを行うと家族歴についての情報が充実する。」。

システムレビューは全身の各系統について症状の有無を系統的に確認する手順で、見落としを防ぐためのものである。家族歴の情報を充実させるものではない。

【誤答選択肢の解説】
A「非言語的コミュニケーションは医療情報の収集に必要である。」: 表情や姿勢、視線などの非言語的情報は病歴の重要な手がかりになる。正しい。
B「感情面に対応した応答は信頼関係の構築のために必要である。」: 感情に応答することで信頼関係が築かれ、語りが深まる。正しい。
D「解釈モデルを把握して対応することによって患者満足度は高まる。」: 解釈モデルを踏まえた説明は納得につながり、満足度を高める。正しい。
E「患者教育が十分に行われると治療へのコンプライアンスが高まる。」: 疾患と治療についての理解が深まれば治療の遵守は高まる。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E023（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-24', '正答は B「前立腺肥大」。

前立腺肥大症は下部尿路の閉塞をきたし、進行すると尿を排出できない尿閉に至る。男性の尿閉の原因として最も多い。

【誤答選択肢の解説】
A「尿道下裂」: 尿道下裂は外尿道口の位置異常で、通常は尿閉をきたさない。
C「膀胱尿管逆流」: 膀胱尿管逆流は尿が上行する病態で、排出障害ではない。
D「間質性膀胱炎」: 間質性膀胱炎は頻尿と膀胱痛が主症状である。
E「クラミジア性尿道炎」: クラミジア性尿道炎は排尿時痛と分泌物が主症状である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-25', '正答は A「アトピー性皮膚炎の合併」。

アナフィラキシーの病歴聴取では、原因(誘因)の特定が最も重要である。アトピー性皮膚炎の合併はアトピー素因を示すが、今回の発症の誘因を教えてくれるものではない。

【誤答選択肢の解説】
B「直近の食事の内容」: 食物が誘因として最も多く、直近の食事内容は必須の情報である。
C「蜂に刺されたこと」: 蜂毒は代表的な誘因で、刺傷歴の確認は重要である。
D「食後の運動」: 食物依存性運動誘発アナフィラキシーを見分けるため、食後の運動の有無を聞く。
E「内服薬」: 薬剤も主要な誘因で、内服薬の確認は欠かせない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-27', '正答は B「K 7.0mEq/L」。

脈拍32/分の徐脈と低血圧、眼前暗黒感があり、高カリウム血症による徐脈性不整脈を考える。K 7.0mEq/Lではテント状T波から幅広いQRS、洞停止・房室ブロックへ進み、心停止に至りうる。グルコン酸カルシウム静注を急ぐ。

【誤答選択肢の解説】
A「Na130mEq/L」: 低ナトリウム血症は意識障害やけいれんをきたすが、徐脈の原因にならない。
C「Cl 92mEq/L」: Cl 92mEq/Lの軽度低下は徐脈と関係しない。
D「Ca 8.0mg/dL」: Ca 8.0mg/dLの軽度低下ではQT延長を生じうるが、この徐脈は説明しない。
E「P 5.0mg/dL」: P 5.0mg/dLは軽度高値で、この病態と直接関係しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E027（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-28', '正答は C「経鼻胃管挿入」。

誤嚥性肺炎に敗血症を合併し、嘔吐と上腹部膨隆がある。胃内容を減圧しないと再び誤嚥して肺炎が悪化するため、経鼻胃管を挿入して排液する。

【誤答選択肢の解説】
A「輸血」: 貧血や出血を示す所見がなく、輸血の適応がない。
B「気管挿管」: SpO2 94%で自発呼吸も保たれており、直ちに挿管する段階ではない。
D「ヘパリン投与」: 血栓症を示す所見はなく、ヘパリンの適応がない。
E「プロプラノロール投与」: β遮断薬は敗血症性ショックの循環をさらに悪化させる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E028（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-3', '正答は B「圧痛を伴う。」。

圧痛を伴うリンパ節腫大は、急速な被膜の伸展を意味し炎症性(反応性)を示唆する。癌の転移では緩徐に増大するため痛みを欠くことが多い。

【誤答選択肢の解説】
A「硬い。」: 石のように硬いリンパ節は転移を示唆する。
C「可動性が乏しい。」: 周囲組織への浸潤による可動性の低下は悪性を示唆する。
D「鎖骨上窩にある。」: 鎖骨上窩(とくに左のVirchowリンパ節)の腫大は腹部悪性腫瘍の転移を示唆する。
E「辺縁が不整である。」: 辺縁が不整であることも悪性を示唆する所見である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-30', '正答は E「尿道カテーテル挿入」。

けいれん重積では気道・呼吸・循環の確保と抗けいれん薬の投与が最優先である。尿道カテーテルは急性期の救命処置に直接寄与せず、優先度が低い。

【誤答選択肢の解説】
A「酸素投与」: チアノーゼを認めており酸素投与は必須である。
B「気道確保」: けいれん中は舌根沈下や分泌物で気道が閉塞しやすく、気道確保が要る。
C「静脈路確保」: 抗けいれん薬の静脈投与と血糖・電解質の評価のために静脈路が必要である。
D「抗けいれん薬投与」: 15分以上持続しており、ジアゼパムなど抗けいれん薬の投与が必要である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E030（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-31', '正答は E「「なぜそのようなお気持ちになったのか、お話し下さいますか」」。

「死なせてほしい」という訴えの背景には、制御できていない痛みや、迷惑をかけているという思い、孤独がある。まずその気持ちの中身を尋ね、痛みの再評価と支援体制の見直しにつなげる。

【誤答選択肢の解説】
A「「そんなことを言わずに頑張りましょう」」: 励ましは訴えを否定することになり、患者を孤立させる。
B「「今すぐ安らかに旅立つお手伝いをします」」: 積極的安楽死は我が国では認められておらず、実施できない。
C「「すぐにホスピスへの入院を検討しましょう」」: 本人は自宅で最期を迎えることを希望しており、まず気持ちを聴かずに転院を提案するのは希望に反する。
D「「末期肺癌の根治的治療法がありますので安心してください」」: 末期肺癌に根治的治療はなく、虚偽の説明にあたる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E031（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-34', '正答は C「服薬管理を本人に任せる。」。

改訂長谷川式16点と巧緻機能障害があり独居である。服薬を本人だけに任せると飲み忘れや過量服用が起こる。一包化や訪問看護・薬剤師による服薬支援を組み立てる必要がある。

【誤答選択肢の解説】
A「訪問看護を計画する。」: 心不全の管理と服薬支援のため訪問看護の導入は適切である。
B「介護保険の申請を勧める。」: 要介護認定を受けてサービスにつなぐことは適切である。
D「成年後見制度の適応を検討する。」: 血縁者がなく判断能力の低下があるため、成年後見制度の検討は適切である。
E「多職種間で患者情報を共有する。」: 多職種で情報を共有することは在宅療養を支えるうえで適切である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E034（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-35', '正答は C「収入が無くなる事への不安」。

全人的苦痛のうち社会的苦痛は、仕事・経済・家庭内の役割など社会生活上の問題から生じる苦痛である。休業により収入が絶たれることへの不安がこれにあたる。

【誤答選択肢の解説】
A「死への恐怖」: 死への恐怖はスピリチュアルペイン(実存的苦痛)にあたる。
B「上腹部の痛み」: 上腹部の痛みは身体的苦痛である。
D「癌と診断される事への恐怖」: 診断されることへの恐怖は精神的苦痛である。
E「もっと早く受診すればという後悔」: 受診が遅れたという後悔も精神的苦痛にあたる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E035（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-36', '正答は C「起床時の日光浴」。

起床時に日光を浴びると体内時計がリセットされ、約14〜16時間後に自然な眠気が訪れる。睡眠薬に頼る前に行うべき睡眠衛生指導の基本である。

【誤答選択肢の解説】
A「就寝前の飲酒」: アルコールは入眠を早めるが睡眠を浅くし中途覚醒を増やす。高齢者ではとくに避ける。
B「睡眠薬の増量」: 効果不十分だからと増量すると、転倒やせん妄の危険が高まる。
D「1時間以上の昼寝」: 長い昼寝は夜間の睡眠圧を下げる。昼寝は30分以内にとどめる。
E「夕食時のコーヒー摂取」: カフェインの作用は数時間続くため、夕方以降の摂取は避ける。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E036（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-37', '正答は C「アドレナリン筋注」。

甲殻類摂取後に嘔吐、意識レベル低下、血圧78/52mmHg、膨疹、喘鳴が出現しており、アナフィラキシーショックである。直ちにアドレナリン0.01mg/kgを大腿前外側に筋注する。

【誤答選択肢の解説】
A「β刺激薬吸入」: β刺激薬吸入は気管支攣縮に補助的だが、循環虚脱には無効である。
B「アトロピン静注」: アトロピンは徐脈に用いる薬剤で、この病態の適応ではない。
D「抗ヒスタミン薬静注」: 抗ヒスタミン薬は皮膚症状にしか効かず、効果発現も遅い。
E「プレドニゾロン静注」: ステロイドは遅発相の予防に用いるもので、急性期の第一選択にはならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E037（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-4', '正答は D「蜂巣炎(蜂窩織炎)」。

蜂巣炎は皮下組織の細菌感染で、罹患部位に限局した発赤・熱感・腫脹をきたす。片側性の浮腫となる点が全身性の浮腫と異なる。

【誤答選択肢の解説】
A「肝硬変」: 肝硬変では低アルブミン血症により両側性の浮腫と腹水を生じる。
B「急性心不全」: 急性心不全でも静脈圧の上昇により両側性の浮腫となる。
C「ネフローゼ症候群」: ネフローゼ症候群も低アルブミン血症による全身性浮腫である。
E「甲状腺機能低下症」: 甲状腺機能低下症の粘液水腫も全身性である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-6', '正答は B「Murphy徴候 — 急性胆囊炎」。

Murphy徴候は右季肋部を圧迫しながら深呼吸させると、炎症のある胆囊が指に触れて痛みで吸気が止まる所見で、急性胆囊炎に特徴的である。

【誤答選択肢の解説】
A「筋性防御 — 急性膀胱炎」: 筋性防御は腹膜炎の所見で、急性膀胱炎では生じない。
C「下腹部腫瘤 — 尿管結石」: 下腹部の腫瘤は尿閉による膀胱の拡張や子宮・卵巣腫瘍でみられる。尿管結石では触れない。
D「腹壁静脈怒張 — 腹部大動脈瘤」: 腹壁静脈の怒張(メデューサの頭)は門脈圧亢進症の所見である。
E「鼠径リンパ節腫大 — 停留精巣」: 停留精巣自体は鼠径リンパ節腫大をきたさない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-7', '正答は A「臍静脈」。

胎盤でガス交換を受けた血液は臍静脈を通って胎児へ戻るため、胎児循環のなかで最も酸素分圧が高い。静脈管を経て下大静脈から右房に入り、卵円孔を通って優先的に脳と上半身へ送られる。

【誤答選択肢の解説】
B「肺静脈」: 胎児の肺は換気されておらず、肺静脈血の酸素分圧は低い。
C「動脈管」: 動脈管には肺動脈の低酸素血が流れる。
D「上大静脈」: 上大静脈には上半身からの静脈血が戻る。
E「内腸骨動脈」: 内腸骨動脈は臍動脈へつながる低酸素の血液である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-8', '正答は A「敗血症 — ノルアドレナリン」。

敗血症性ショックは血管拡張による血液分布異常性ショックで、十分な輸液でも血圧が保てない場合はノルアドレナリンを第一選択の昇圧薬として用いる。

【誤答選択肢の解説】
B「大量出血 — ヘパリン」: 大量出血には輸血と止血が必要で、ヘパリンは出血を助長する。
C「徐脈性不整脈 — グルコース」: 徐脈性不整脈にはアトロピンや経皮ペーシングを用いる。
D「肺血栓塞栓症 — アミノフィリン」: 肺血栓塞栓症には抗凝固療法や血栓溶解療法を行う。
E「アナフィラキシー — リドカイン」: アナフィラキシーの第一選択はアドレナリンの筋注である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-E-9', '正答は C「亜急性期」。

地域医療構想の病床機能区分は高度急性期・急性期・回復期・慢性期の4つで、亜急性期は含まれない。

【誤答選択肢の解説】
A「高度急性期」: 高度急性期は集中治療室など特に高い医療資源を投入する機能である。
B「急性期」: 急性期は急性期の患者に医療を提供する機能である。
D「回復期」: 回復期はリハビリテーションを提供し在宅復帰を支える機能である。
E「慢性期」: 慢性期は長期にわたる療養を担う機能である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 E009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-1', '正答は A「ケアマネジャー」。

介護保険サービスの利用計画(ケアプラン)を作成し、事業所との調整を行うのは介護支援専門員(ケアマネジャー)である。通所リハビリテーションの導入もここを通す。

【誤答選択肢の解説】
B「歯科衛生士」: 歯科衛生士は口腔ケアを担う。
C「訪問看護師」: 訪問看護師は在宅での医療的ケアを提供する。
D「ホームヘルパー」: ホームヘルパーは訪問介護のサービスを提供する。
E「理学療法士」: 理学療法士はリハビリテーションを実施する側で、サービスの調整は行わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-10', '正答は A「高度医療の提供」。

離島の診療所に求められるのは、限られた資源のなかで初期対応を行い、必要な患者を本土の医療機関へつなぐことである。高度医療をその場で提供することは現実的でなく、優先度が低い。

【誤答選択肢の解説】
B「自治体との連携」: 保健・福祉との連携は地域全体の健康を支えるうえで欠かせない。
C「他の医療機関との連携」: 後方支援病院との連携は紹介・搬送の要である。
D「遠隔読影システムの整備」: 遠隔読影は専門医のいない環境で画像診断を可能にする。
E「救急搬送システムの整備」: 急変時にヘリコプターや船で搬送する体制の整備は必須である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-12', '正答は C「使い方が限定的である。」。

ユニバーサルデザインの7原則は、公平な利用、利用における柔軟性、単純で直感的な利用、分かりやすい情報、うっかりミスへの寛容、身体的負担の少なさ、接近と利用のための空間である。使い方が限定的であることは柔軟性の原則に反する。

【誤答選択肢の解説】
A「公平に利用できる。」: 公平な利用は第1原則である。
B「身体的な負担が少ない。」: 身体的負担が少ないことは第6原則である。
D「単純で直感的に利用できる。」: 単純で直感的な利用は第3原則である。
E「使い方を誤っても重大な結果になりにくい。」: 誤りへの寛容は第5原則である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F012（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-13', '正答は E「免疫能低下の患者に生じることが多い。」。

院内肺炎は入院48時間以降に発症する肺炎で、基礎疾患や治療により免疫能が低下した患者に起こることが多い。緑膿菌や耐性菌が起炎菌となりやすい。

【誤答選択肢の解説】
A「主要な検出菌は肺炎球菌である。」: 院内肺炎の主要な検出菌は緑膿菌、黄色ブドウ球菌、腸内細菌科細菌などである。肺炎球菌は市中肺炎の主要菌である。
B「人工呼吸器関連肺炎は含まれない。」: 人工呼吸器関連肺炎は院内肺炎に含まれる。
C「入院当日に発症した肺炎も含まれる。」: 入院48時間以内の発症は市中肺炎として扱う。
D「死亡率は医療・介護関連肺炎より低い。」: 院内肺炎の死亡率は医療・介護関連肺炎より高い。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F013（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-14', '正答は C「左右が分かる。」。

左右の区別がつくのは5〜6歳ごろで、選択肢のなかで最も遅い。

【誤答選択肢の解説】
A「円をえがく。」: 円を模写できるのは3歳ごろである。
B「はさみを使う。」: はさみを使えるのは3歳ごろである。
D「片足立ちをする。」: 片足立ちができるのは3〜4歳ごろである。
E「ごっこ遊びをする。」: ごっこ遊びは2〜3歳ごろから始まる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F014（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-15', '正答は E「顕微鏡的多発血管炎」。

顕微鏡的多発血管炎はANCA関連血管炎で、好中球の顆粒成分であるミエロペルオキシダーゼに対する自己抗体(MPO-ANCA)が高率に陽性となる。急速進行性糸球体腎炎と肺胞出血が問題になる。

【誤答選択肢の解説】
A「川崎病」: 川崎病にANCAは関与せず、診断は臨床基準による。
B「高安動脈炎」: 高安動脈炎は大型血管炎でANCAは陰性である。
C「巨細胞性動脈炎」: 巨細胞性動脈炎も大型血管炎でANCAは陰性である。
D「結節性多発動脈炎」: 結節性多発動脈炎は中型血管炎で、ANCAは通常陰性である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F015（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-16', '正答は D「水平半盲 — 加齢黄斑変性」。

加齢黄斑変性は黄斑部の病変なので中心暗点と変視症をきたす。水平半盲(高位・低位半盲)は網膜中心動脈分枝閉塞や視神経・視路の病変でみられ、加齢黄斑変性の所見ではない。

【誤答選択肢の解説】
A「Bjerrum暗点 — 緑内障」: Bjerrum暗点は緑内障に特徴的な弓状の視野欠損である。
B「盲中心暗点 — 視神経炎」: 盲中心暗点は視神経炎や中毒性視神経症でみられる。
C「両耳側半盲 — 下垂体腺腫」: 両耳側半盲は視交叉中央部を圧迫する下垂体腺腫の所見である。
E「輪状暗点 — 網膜色素変性」: 輪状暗点は網膜色素変性の初期にみられる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F016（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-17', '正答は C「被保護世帯数は高齢者世帯が最も多い。」。

被保護世帯を世帯類型別にみると高齢者世帯が最も多く、全体の半数を超えている。単身高齢者の増加が背景にある。

【誤答選択肢の解説】
A「生活保護基準は都道府県が定める。」: 生活保護基準は厚生労働大臣が定める。
B「被保護世帯数は近年減少傾向にある。」: 被保護世帯数は高齢者世帯の増加により高止まりし、近年も減少に転じていない。
D「生活保護の開始は要介護状態が最も多い。」: 保護開始の理由では傷病や貯金等の減少・喪失が多く、要介護状態が最多ではない。
E「生活保護受給者は国民健康保険に加入している。」: 生活保護受給者は国民健康保険の適用から除外され、医療扶助により医療を受ける。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-18', '正答は A「凝集性(食塊のまとまり)が高い」。

食塊がひとまとまりになりやすい(凝集性が高い)食品は、咽頭をまとまって通過するため誤嚥しにくい。とろみを付けるのはこの性質を高めるためである。

【誤答選択肢の解説】
B「均質性(なめらかさ)が低い」: 均質性が低くばらけやすい食品はまとまらず、誤嚥しやすい。
C「付着性が高い」: 付着性が高いと咽頭に残留し、後から誤嚥する原因になる。
D「硬度が高い」: 硬度が高いと咀嚼で食塊を作りにくい。
E「温度が高い」: 温度が高いことは誤嚥の予防にならない。むしろ体温に近い温度は嚥下反射を起こしにくい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F018（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-19', '正答は D「薬剤相互作用は考慮せずに処方する。」。

高齢者では複数の薬による相互作用が有害事象の主要な原因になる。相互作用を考慮せずに処方することは、ポリファーマシー対策として明確に誤りである。

【誤答選択肢の解説】
A「かかりつけ薬局を決めてもらう。」: かかりつけ薬局に一本化すると重複や相互作用を薬剤師が把握できる。
B「類似薬の重複の有無を確認する。」: 同種同効薬の重複の確認は基本的な対応である。
C「お薬手帳を持ち歩くように指示する。」: お薬手帳の携行は他院での処方を含めた把握につながる。
E「病状が安定していれば減薬を考慮する。」: 病状が安定していれば減薬(処方の見直し)を検討するのは適切である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-2', '正答は C「就労上の留意点を指導する。」。

主治医は病状に基づいて、就労にあたり避けるべき作業や配慮すべき点を具体的に示す。これが産業医や事業者による就業上の措置につながる。

【誤答選択肢の解説】
A「復職の可否を判定する。」: 復職の可否と就業上の措置を最終的に判断するのは事業者で、産業医が意見を述べる。
B「上司と一緒に受診させる。」: 上司の同席は本人の同意が前提で、必須ではない。
D「治療計画を雇用主に伝える。」: 雇用主への情報提供は本人の同意なしにはできない。
E「治療を優先し仕事を控えるよう指導する。」: 治療と仕事の両立支援は、仕事を続けながら治療を受けられるようにする取り組みである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-20', '正答は A「児童福祉施設が規定されている。」。

児童福祉施設について定めているのは児童福祉法である。次世代育成支援対策推進法は、子育て支援のための行動計画の策定を国・地方公共団体・事業主に求める法律である。

【誤答選択肢の解説】
B「国民は子育て支援に協力する責務を負っている。」: 国民も子育て支援に協力する責務を負うと規定されている。
C「子どもが健やかに生まれ、育成されることを目的とする。」: 次代の社会を担う子どもが健やかに生まれ育つ環境の整備が目的である。
D「国及び地方公共団体は子育て支援を推進する責務を負っている。」: 国及び地方公共団体の責務が規定されている。
E「従業員数が100人を超える事業主は次世代育成行動計画を策定する。」: 常時雇用する労働者が100人を超える事業主に一般事業主行動計画の策定が義務づけられている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F020（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-21', '正答は C「ママ、ブーブーなど意味のあることばをいくつか話しますか。」。

1歳6か月では有意語(ママ、ブーブーなど意味のあることば)がいくつか出ているかを確認する。これが1歳6か月健康診査の言語発達の目安である。

【誤答選択肢の解説】
A「自分の名前が言えますか。」: 自分の名前が言えるのは3歳ごろの目安である。
B「2語文(ワンワンキタ、マンマチョウダイなど)を言いますか。」: 2語文が出るのは2歳ごろの目安である。
D「家族といっしょにいるとき、話しかけるような声を出しますか。」: 喃語のような発声は生後6か月ごろの目安で、1歳6か月では遅すぎる基準である。
E「大人の言う簡単なことば(おいで、ちょうだいなど)がわかりますか。」: 簡単な指示の理解は1歳前後の目安で、言語表出の評価にはならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F021（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-23', '正答は E「臍レベルの温痛覚障害」。

Brown-Séquard症候群では、後索と皮質脊髄路は同側性の障害となり、外側脊髄視床路は交叉後に上行するため対側の温痛覚が障害される。右半分の離断なので、左半身には障害レベルのやや下方から温痛覚障害が現れる。乳頭は第4胸髄、臍は第10胸髄に相当する。

【誤答選択肢の解説】
A「腹壁反射の消失」: 腹壁反射の消失は同側(右)に生じる。
B「Babinski徴候陽性」: Babinski徴候は錐体路障害の所見で同側(右)に出る。
C「Hoffmann反射陽性」: Hoffmann反射も同側の上位運動ニューロン徴候である。
D「下肢の振動覚障害」: 振動覚は後索を通り同側性なので、障害は右に出る。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F023（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-24', '正答は E「精神保健福祉センター」。

精神保健福祉センターは地域住民の精神保健福祉を担う都道府県の機関で、職場の自殺予防対策の枠組みに直接位置づけられる組織ではない。

【誤答選択肢の解説】
A「産業医」: 産業医はメンタルヘルス対策の中心的な役割を担う。
B「衛生管理者」: 衛生管理者は職場の衛生管理を統括し、対策の実務を担う。
C「産業保健師」: 産業保健師は健康相談や保健指導を通じて関わる。
D「産業保健推進センター」: 産業保健総合支援センターは事業場の産業保健活動を支援する機関である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-25', '正答は A「IgG」。

糸球体基底膜は分子量と電荷によるふるいとして働き、分子量約15万でマイナス荷電のIgGはほとんど濾過されない。健常者の尿にIgGが出ないのはこのためである。

【誤答選択肢の解説】
B「イヌリン」: イヌリンは分子量約5,000で自由に濾過され、糸球体濾過量の測定に用いられる。
C「グルコース」: グルコースは自由に濾過されたのち近位尿細管でほぼ全量が再吸収される。
D「ナトリウム」: ナトリウムは自由に濾過される。
E「クレアチニン」: クレアチニンも自由に濾過され、腎機能の指標に用いられる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-3', '正答は C「神経」。

放射線感受性は細胞分裂が盛んで未分化な細胞ほど高い(Bergonié-Tribondeauの法則)。神経細胞は分裂しない高度に分化した細胞で、感受性が最も低い。

【誤答選択肢の解説】
A「甲状腺」: 甲状腺は小児期を中心に感受性があり、被曝で癌のリスクが高まる。
B「骨髄」: 骨髄は造血幹細胞が盛んに分裂しており、最も感受性が高い組織の一つである。
D「皮膚」: 皮膚の基底細胞も分裂が盛んで、脱毛や紅斑を生じる。
E「卵巣」: 卵巣の卵母細胞も感受性が高い。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-39', '正答は C「気管内の煤付着」。

気管内の煤の付着は、火災発生時に呼吸をしていた、すなわち生存していたことを示す生活反応である。血中一酸化炭素ヘモグロビン濃度の上昇も同様の意義をもつ。

【誤答選択肢の解説】
A「頭蓋内の燃焼血腫」: 頭蓋内の燃焼血腫は加熱により硬膜外に血液が滲出したもので、死後の加熱でも生じる。
B「頸部皮膚のIII度熱傷」: 皮膚の熱傷は死後の焼損でも生じ、生存の証明にならない。
D「肘関節屈筋の熱収縮」: 熱により屈筋が収縮して生じる闘士型姿勢(拳闘家肢位)も死後変化である。
E「背部の死斑」: 死斑は死後に生じる所見である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F039（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-42', '正答は C「ネフローゼ症候群」。

眼瞼を含む全身の圧痕性浮腫が急速に進み、1か月で8kgの体重増加がある。心不全や肝疾患を示す所見がなく、低アルブミン血症による浮腫すなわちネフローゼ症候群を第一に考える。尿蛋白の定量を急ぐ。

【誤答選択肢の解説】
A「肺高血圧症」: 肺高血圧症では頸静脈怒張やII音肺動脈成分の亢進を伴う。
B「下肢静脈血栓症」: 下肢静脈血栓症は片側性で疼痛を伴い、眼瞼の浮腫は説明できない。
D「甲状腺機能低下症」: 甲状腺機能低下症の粘液水腫は圧痕を残さない非圧痕性浮腫である。
E「Budd-Chiari症候群」: Budd-Chiari症候群は肝静脈の閉塞で腹水と肝腫大をきたすが、眼瞼浮腫は生じにくい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F042（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-43', '正答は B「産瘤は右頭頂骨後部にできる。」。

先進部が小泉門で3時方向、矢状縫合が骨盤横径に一致する第2頭位から、全開大時に小泉門が12時方向で矢状縫合が縦径に一致している。第2回旋(内回旋)が正常に完了した所見である。産瘤は先進部すなわち骨盤入口部で最も低い位置にあたる右頭頂骨の後部にできる。

【誤答選択肢の解説】
A「第2回旋の異常である。」: 矢状縫合が縦径に一致し小泉門が恥骨側を向いており、第2回旋は正常に完了している。
C「骨重積は右頭頂骨が左頭頂骨の下になる。」: 骨重積では先進する側の頭頂骨が上になる。第2頭位では右頭頂骨が左頭頂骨の上に重なる。
D「第4回旋で児の顔面は母体の左側へ向く。」: 第4回旋(外回旋)では児の顔面は母体の右側を向く。
E「体幹娩出時に左側の肩甲が先に娩出される。」: 体幹娩出では恥骨側にある前在肩甲、すなわち右肩甲が先に娩出される。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F043（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-44', '正答は C「3」。

下顎呼吸は呼吸中枢の機能が失われつつあることを示す死亡直前の徴候で、多くは数時間から24時間以内の死亡を予測させる。家族に立ち会いを希望されている以上、この時点で連絡することが必要である。

【誤答選択肢の解説】
A「1」: 呼びかけに答えない意識レベルの低下は数日前から進行しうる。
B「2」: 嚥下できないことも数日単位で先行する変化である。
D「4」: 四肢の浮腫は低アルブミン血症などで慢性に生じる。
E「5」: 1日排便がないことは死期の予測に結びつかない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F044（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-48', '正答は B「冠動脈造影を施行する。」。

II・III・aVF誘導のST上昇があり、下壁の急性心筋梗塞である。透析患者でも再灌流療法の適応は同じで、直ちに冠動脈造影を行い経皮的冠動脈形成術につなげる。

【誤答選択肢の解説】
A「利尿薬を投与する。」: 透析直後で体液過剰はなく、心不全でもないため利尿薬の適応がない。
C「緊急血液透析を施行する。」: 透析は本日終了しており、緊急に行う理由がない。
D「自宅での経過観察を指示する。」: ST上昇型心筋梗塞であり、経過観察は許されない。
E「上肢の超音波検査を施行する。」: シャントは血管雑音を聴取でき機能している。胸痛の原因ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F048（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-5', '正答は D「甲状腺機能亢進症」。

甲状腺機能亢進症では脂質代謝が亢進し、トリグリセリドもコレステロールもむしろ低下する。高値の原因にならない。

【誤答選択肢の解説】
A「先端巨大症」: 先端巨大症ではGHのインスリン拮抗作用により脂質異常をきたす。
B「内臓脂肪蓄積」: 内臓脂肪の蓄積は遊離脂肪酸の肝への流入を増やし、VLDL産生を高める。
C「アルコール多飲」: アルコールは肝でのVLDL合成を促進する。
E「インスリン抵抗性増加」: インスリン抵抗性はリポ蛋白リパーゼ活性を下げ、トリグリセリドを上昇させる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-50', '正答は A「身体依存が認められる。」。

断酒3日目に手指振戦と発汗という離脱症状が出ており、身体依存が形成されていることを示す。離脱期にはベンゾジアゼピンによる管理とビタミンB1の補充を行う。

【誤答選択肢の解説】
B「医師から退職を勧める。」: 退職を勧めるのは医師の役割ではなく、就労の継続はむしろ回復を支える。
C「うつ病を合併する可能性は低い。」: アルコール依存症はうつ病を高率に合併する。本例も気分の落ち込みを訴えている。
D「治療の第一選択は薬物療法である。」: 治療の中心は断酒の継続を支える心理社会的介入(自助グループ、集団療法)で、薬物療法は補助である。
E「自ら積極的に治療を求めることが多い。」: 否認が強く、自ら治療を求めることは少ない。周囲の働きかけで受診に至ることが多い。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F050（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-51', '正答は B「医療者は袖なしエプロンを装着する。」。

袖なしエプロンでは前腕が露出し、放射性物質による汚染を防げない。長袖のガウンと手袋、キャップ、マスクで全身を覆う必要がある。

【誤答選択肢の解説】
A「医療者は個人線量計を装着する。」: 医療者自身の被曝線量を把握するため個人線量計は必須である。
C「曝露した放射性物質の種類を確認する。」: 核種によって半減期・放射線の種類・除染方法が異なるため、種類の確認は重要である。
D「患者の搬入経路を考慮しゾーニングを行う。」: 汚染区域と清潔区域を分けるゾーニングは汚染拡大の防止に必要である。
E「放射線測定器を用いて患者の表面の汚染測定を行う。」: 除染の効果を確認するためサーベイメータによる測定を行う。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F051（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-54', '正答は B「流行性耳下腺炎」。

新生児聴覚スクリーニングは正常だったが、2歳時のムンプス罹患後に一側の高度感音難聴が生じている。ムンプス難聴は片側性・高度で不可逆的なことが多く、後天性一側性難聴の代表的な原因である。

【誤答選択肢の解説】
A「慢性中耳炎」: 慢性中耳炎では伝音難聴が主体で、高度感音難聴は説明できない。
C「先天性風疹症候群」: 先天性風疹症候群による難聴は出生時から存在し、新生児スクリーニングで検出される。
D「低酸素性虚血性脳症」: 新生児仮死の既往はなく、低酸素性虚血性脳症は否定的である。
E「Treacher Collins症候群」: Treacher Collins症候群は特徴的な顔貌と外耳道閉鎖を伴い、出生時から明らかである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F054（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-7', '正答は E「しゃがみ込みで減弱する収縮期雑音 — 閉塞性肥大型心筋症」。

閉塞性肥大型心筋症の収縮期雑音は、左室容積が増えると流出路の狭窄が軽減して減弱する。しゃがみ込みは静脈還流を増やし前負荷を高めるため雑音は弱まる。逆にValsalva手技や立位で増強する。

【誤答選択肢の解説】
A「連続性雑音 — 大動脈弁狭窄兼閉鎖不全症」: 連続性雑音は動脈管開存症に特徴的である。大動脈弁狭窄兼閉鎖不全では収縮期と拡張期の雑音がそれぞれ聴かれる(to-and-fro)。
B「心膜ノック音 — 心タンポナーデ」: 心膜ノック音は収縮性心膜炎の所見である。心タンポナーデでは心音が減弱する。
C「吸気で増強する収縮期雑音 — 肺動脈弁閉鎖不全症」: 吸気で増強する収縮期雑音(Rivero-Carvallo徴候)は三尖弁閉鎖不全症の所見である。
D「上半身の前傾で増強する拡張期雑音 — 三尖弁狭窄症」: 前傾姿勢で増強する拡張期雑音は大動脈弁閉鎖不全症の所見である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-75', '正答は D「後期流産 — 死産届必要」。

妊娠12週以降22週未満の流産を後期流産という。妊娠14週なので後期流産にあたり、死産の届出に関する規程により妊娠12週以後の死児の出産は死産届が必要である。

【誤答選択肢の解説】
A「早期流産 — 死産届不要」: 妊娠14週は早期流産(12週未満)ではなく、また死産届は必要である。
B「早期流産 — 死産届必要」: 診断が誤っている。
C「後期流産 — 死産届不要」: 死産届が必要である。
E「早産 — 死産届不要」: 妊娠22週未満なので早産ではない。
F「早産 — 死産届必要」: 同様に早産ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F075（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-8', '正答は A「子宮腺筋症」。

子宮腺筋症は子宮内膜組織が筋層内に存在する疾患で、子宮の腫大と収縮不良により過多月経と強い月経痛をきたす。

【誤答選択肢の解説】
B「子宮腔癒着症」: 子宮腔癒着症(Asherman症候群)では内膜が失われ、過少月経や無月経となる。
C「Sheehan症候群」: Sheehan症候群は下垂体前葉機能低下で、無月経と乳汁分泌不全をきたす。
D「多囊胞性卵巣症候群」: 多囊胞性卵巣症候群は稀発月経・無月経が特徴である。
E「高プロラクチン血症」: 高プロラクチン血症も無月経の原因である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('116-F-9', '正答は B「尋常性乾癬」。

尋常性乾癬は境界明瞭な紅斑と銀白色の鱗屑を特徴とする皮膚の疾患で、粘膜疹はほとんどみられない。

【誤答選択肢の解説】
A「扁平苔癬」: 扁平苔癬は頰粘膜にレース状の白色線条(Wickham線条)を生じる。
C「膿疱性乾癬」: 膿疱性乾癬では地図状舌など口腔内の変化を伴うことがある。
D「尋常性天疱瘡」: 尋常性天疱瘡は口腔粘膜のびらんで発症することが多い。
E「多形滲出性紅斑」: 多形滲出性紅斑、とくに重症型では口唇・口腔粘膜のびらんを伴う。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第116回医師国家試験 F009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp220421-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-11', '正答は B「喘息増悪はウイルス感染後が最も多い。」。

喘息増悪の契機として最も多いのはウイルス性上気道感染(ライノウイルスなど)である。感染対策と増悪時の対応をあらかじめ計画しておくことが重要になる。

【誤答選択肢の解説】
A「喘息死は増加傾向にある。」: 吸入ステロイドの普及により喘息死は大きく減少している。
C「吸入ステロイド薬は喫煙により作用が増強する。」: 喫煙は吸入ステロイドの効果を弱める。
D「抗IgE抗体はアトピー型喘息の第一選択薬である。」: 抗IgE抗体は重症の難治例に用いる生物学的製剤で、第一選択ではない。
E「急性増悪時には長時間作用性β2刺激薬が第一選択である。」: 急性増悪時には短時間作用性β2刺激薬を用いる。長時間作用性は効果発現が遅い。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-12', '正答は C「日本住血吸虫症」。

日本住血吸虫症は淡水中のミヤイリガイを中間宿主とし、経皮的にセルカリアが侵入して感染する。性行為による感染ではない。

【誤答選択肢の解説】
A「梅毒性肝炎」: 梅毒は性感染症で、第2期に肝炎を生じることがある。
B「B型急性肝炎」: B型肝炎ウイルスは血液・体液を介し、性感染症として重要である。
D「アメーバ性肝膿瘍」: 赤痢アメーバは糞口感染に加え、男性同性間の性行為による感染が問題となっている。
E「肝周囲炎〈Fitz-Hugh-Curtis症候群〉」: Fitz-Hugh-Curtis症候群はクラミジアや淋菌の骨盤内感染が肝周囲に波及したものである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A012（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-13', '正答は C「ビタミンA — 夜盲」。

ビタミンAはロドプシンの構成成分で、欠乏すると暗順応が障害され夜盲をきたす。進行すると眼球乾燥症や角膜軟化症に至る。

【誤答選択肢の解説】
A「葉酸 — 小球性貧血」: 葉酸欠乏では大球性(巨赤芽球性)貧血をきたす。小球性ではない。
B「ニコチン酸 — 心不全」: ニコチン酸(ナイアシン)欠乏はペラグラで、皮膚炎・下痢・認知症を三徴とする。
D「ビタミンB1 — 腱反射亢進」: ビタミンB1欠乏(脚気)では腱反射は低下・消失する。
E「ビタミンB12 — 皮膚炎」: ビタミンB12欠乏では巨赤芽球性貧血と亜急性連合性脊髄変性症をきたす。皮膚炎ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A013（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-14', '正答は B「下痢」。

胃食道逆流症は胃酸が食道へ逆流する疾患で、胸やけ・呑酸・胸痛・咽頭違和感・慢性咳嗽などの食道外症状をきたす。下痢は下部消化管の症状で、生じにくい。

【誤答選択肢の解説】
A「胸痛」: 非心臓性胸痛の原因として頻度が高い。
C「呑酸」: 呑酸は代表的な症状である。
D「咽頭痛」: 咽喉頭の逆流症状として咽頭痛や違和感が出る。
E「慢性咳嗽」: 逆流による迷走神経反射や微少誤嚥で慢性咳嗽をきたす。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A014（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-18', '正答は D「選択緘黙」。

家庭では普通に話せるのに学校など特定の場面で話せなくなり、知的発達に問題がない。選択性緘黙(場面緘黙)で、社交不安を背景とする不安症である。

【誤答選択肢の解説】
A「吃音症〈小児期発症流暢症〉」: 吃音症は話そうとするときに音の繰り返しや引き伸ばしが生じるもので、場面による差はこれほど明瞭でない。
B「Tourette症候群」: Tourette症候群は運動チックと音声チックが持続する疾患である。
C「学習障害」: 学習障害は読み書き計算など特定の学習能力の障害である。
E「素行症」: 素行症は他者の権利を侵害する反復的な行動パターンで、本例に該当しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A018（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-19', '正答は C「利尿薬投与」。

反復する回転性めまいに、患側の耳閉感・耳鳴・変動する感音難聴を伴っており、Ménière病である。内リンパ水腫が病態なので、浸透圧利尿薬(イソソルビド)で内リンパ液量を減らす治療を行う。

【誤答選択肢の解説】
A「水分制限」: むしろ水分を十分にとることが内リンパ圧の安定に有用とされる。
B「頭位治療」: 頭位治療(Epley法など)は良性発作性頭位めまい症の治療である。
D「抗ウイルス薬投与」: 抗ウイルス薬は前庭神経炎やRamsay Hunt症候群で検討されるものである。
E「ガンマグロブリン投与」: ガンマグロブリンの適応となる病態ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-20', '正答は A「胃全摘術を予定する。」。

体重減少、Virchowリンパ節、上腹部腫瘤、Schnitzler転移を示す直腸指診所見があり、進行胃癌で根治手術の適応がない状況である。手術を希望する患者に対して、まず本人が病状をどう理解しているかを確認することが説明の出発点になる。

【誤答選択肢の解説】
B「家族同席で再度説明する。」: 家族同席の説明は有用だが、本人の理解を確かめるのが先である。
C「なぜ手術を希望するか尋ねる。」: 希望の理由を聞くことも大切だが、前提となる病状認識のずれを先に把握する。
E「セカンドオピニオンについて説明する。」: セカンドオピニオンの案内は、病状の共有ができてからの話である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A020（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-24', '正答は A「終生免疫を獲得する。」。

両眼の充血・眼脂と耳前リンパ節腫脹から流行性角結膜炎(アデノウイルス)である。アデノウイルスには多数の血清型があり、終生免疫は獲得できず何度でも罹患しうる。

【誤答選択肢の解説】
B「院内感染の原因となる。」: 感染力が強く、眼科外来や病棟での院内感染の原因となる。正しい。
C「感染経路は接触感染である。」: 手指や器具を介した接触感染で広がる。正しい。
D「学校を休まなければならない。」: 学校保健安全法の第三種感染症として、医師が感染のおそれがないと認めるまで出席停止となる。正しい。
E「感染予防のために手洗いが有用である。」: 手洗いとタオルの共用を避けることが予防の基本である。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-25', '正答は B「眼窩部単純CT」。

鉄片が高速で飛入しており眼球穿孔外傷と眼内異物を疑う。単純CTは金属異物の存在と位置を確実に描出でき、診断に有用である。

【誤答選択肢の解説】
A「蛍光眼底造影」: 蛍光眼底造影は網膜血管の評価に用いる検査で、透光体が混濁した状況では施行できない。
C「網膜電図〈ERG〉」: 網膜電図は網膜機能の評価で、異物の同定にならない。
D「眼部超音波検査」: 眼部超音波は有用だが、穿孔創のある眼球に探触子を当てると内容の脱出を招く危険がある。
E「眼窩部単純MRI」: MRIは金属異物が磁場で移動して眼内をさらに損傷するため禁忌である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-28', '正答は D「水痘・帯状疱疹ウイルス」。

耳介の水疱を伴う耳痛と同側の末梢性顔面神経麻痺があり、Ramsay Hunt症候群である。膝神経節に潜伏していた水痘・帯状疱疹ウイルスの再活性化による。

【誤答選択肢の解説】
A「アデノウイルス」: アデノウイルスは咽頭結膜熱や流行性角結膜炎の原因である。
B「単純ヘルペスウイルス」: 単純ヘルペスウイルスはBell麻痺の一因とされるが、耳介の水疱は伴わない。
C「Epstein-Barrウイルス」: EBウイルスは伝染性単核球症の原因である。
E「ヒトパピローマウイルス」: ヒトパピローマウイルスは疣贅や子宮頸癌の原因である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A028（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-30', '正答は D「新鮮凍結血漿」。

破水直後の急激な呼吸困難に、フィブリノゲン50mg/dLという著明な低下を伴っている。羊水塞栓症による産科DICで、フィブリノゲンを含む凝固因子を補充する新鮮凍結血漿の大量投与が治療の中心になる。

【誤答選択肢の解説】
A「抗菌薬」: 感染を示す所見に乏しく、抗菌薬は主治療にならない。
B「アルブミン」: アルブミンは膠質浸透圧を保つが、凝固因子を含まない。
C「ジアゼパム」: けいれんはなく、ジアゼパムの適応がない。
E「ノルアドレナリン」: 昇圧薬は循環の補助にはなるが、DICそのものを是正しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A030（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-32', '正答は E「代償性呼吸性アシドーシス」。

pH7.26と酸血症があり、PaCO2 68TorrとHCO3− 28mEq/Lで、代償が不十分な呼吸性アシドーシスである。慢性呼吸性アシドーシスであれば腎性代償によりHCO3−はもっと上昇するはずで、急性増悪が加わっていることを示す。「代償性」とは言えない。

【誤答選択肢の解説】
A「肺高血圧」: 心エコーで右心系の拡張と心室中隔の左方偏位があり、肺高血圧を認める。
B「肺胞低換気」: PaCO2 68Torrの高二酸化炭素血症は肺胞低換気を示す。
C「シャント率上昇」: 胸郭形成術後の変形と換気血流不均等によりシャント率は上昇する。
D「混合性換気障害」: %VC45%の拘束性障害とFEV1%60%の閉塞性障害を併せもつ混合性換気障害である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A032（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-33', '正答は E「抗精神病薬の減量により軽快する。」。

抗精神病薬の投与直後からじっとしていられずに歩き回るのはアカシジア(静坐不能症)である。薬剤性の錐体外路症状で、原因薬の減量・中止により軽快する。

【誤答選択肢の解説】
A「ジストニアと呼ばれる。」: ジストニアは持続的な筋収縮による異常肢位で、眼球上転や斜頸として現れる。
B「両下肢の知覚低下を伴う。」: 知覚低下は伴わない。
C「睡眠時無呼吸症候群を伴う。」: 睡眠時無呼吸症候群とは無関係である。
D「脳波異常を伴う。」: 脳波に異常は生じない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A033（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-34', '正答は B「有効な薬物療法がある。」。

不注意・多動・衝動性が複数の場面でみられ、注意欠如多動症である。メチルフェニデート徐放剤やアトモキセチン、グアンファシンなど有効な薬物療法があり、行動療法と併せて用いる。

【誤答選択肢の解説】
A「知的障害を伴う。」: 知的障害を伴わない例が多い。
C「成人になると症状は消失する。」: 多動は年齢とともに目立たなくなることがあるが、不注意は成人期にも残ることが多い。
D「出生後の養育が発症要因である。」: 養育が原因ではない。脳機能の発達の偏りによると考えられている。
E「好ましい行動を褒めるよりも好ましくない行動を注意する。」: 望ましい行動を具体的に褒めて強化することが、行動療法の基本である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A034（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-4', '正答は D「片側性すりガラス陰影」。

急性好酸球性肺炎の陰影は両側びまん性で、すりガラス陰影と小葉間隔壁の肥厚、胸水を伴う。片側性ではない。

【誤答選択肢の解説】
A「胸水貯留」: 両側の胸水貯留は高率に認められる。正しい。
B「IL-5上昇」: 好酸球の遊走・活性化を担うIL-5が上昇する。正しい。
C「末梢血好酸球数正常」: 急性期には末梢血好酸球が正常のことが多く、これが慢性好酸球性肺炎との違いである。正しい。
E「気管支肺胞洗浄液中の好酸球数増加」: 気管支肺胞洗浄液中の好酸球が25%以上に増加することが診断の要である。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-47', '正答は D「完全矯正の眼鏡装用」。

3歳で両眼+6.00Dの強い遠視があり、遠くを見るときにも調節を働かせるため輻湊が過剰になって内斜視をきたす調節性内斜視である。調節麻痺薬下で測定した屈折値をそのまま完全矯正する眼鏡を常用させると、調節の必要がなくなって眼位が正位に戻る。

【誤答選択肢の解説】
A「経過観察」: この年齢で内斜視を放置すると斜視弱視と両眼視機能の未発達を残す。経過観察してよい時期ではない。
B「低矯正の眼鏡装用」: 低矯正では残った遠視を補うために調節が働き続け、内斜視が消えない。遠視の眼鏡は完全矯正が原則である。
C「プリズム眼鏡の装用」: プリズム眼鏡は屈折矯正で改善しない斜視角に対して用いるもので、まず完全矯正眼鏡を試すのが順序である。
E「全身麻酔下の斜視手術」: 手術は完全矯正眼鏡で残った非調節性の斜視角に対して検討する。屈折矯正を試す前の手術は適応がない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A047（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-5', '正答は D「神経性食思〈欲〉不振症」。

神経性やせ症は思春期から若年成人の女性に圧倒的に多く、男女比はおよそ1:10とされる。

【誤答選択肢の解説】
A「双極I型障害」: 双極I型障害の有病率に明らかな男女差はない。
B「アルコール依存症」: アルコール依存症は男性に多い。
C「自閉スペクトラム症」: 自閉スペクトラム症は男児に多い(およそ4:1)。
E「反社会性パーソナリティ障害」: 反社会性パーソナリティ障害は男性に多い。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-56', '正答は E「5」。

6年来の腹痛と下痢で、就職という心理社会的因子で増悪しており過敏性腸症候群がまず疑われる。しかし便潜血陽性は器質的疾患を示唆する警告徴候であり、大腸癌や炎症性腸疾患を除外するために下部消化管内視鏡検査を行う根拠となる。

【誤答選択肢の解説】
A「1」: 胸やけは胃食道逆流症を示唆する上部消化管の症状で、下部消化管の検索理由にならない。
B「2」: 警告徴候となるのは体重減少である。1年間で4kgの増加は器質的疾患を示唆しない。
C「3」: 脈拍96/分は正常上限にとどまり、消化管出血を示唆するほどの頻脈ではない。
D「4」: 腸蠕動音の亢進は下痢があれば過敏性腸症候群でもみられ、器質的疾患に特異的ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A056（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-59', '正答は C「強迫性障害」。

自分でも過剰だと分かっているのにやめられない戸締りの確認が反復し、遅刻するほど生活に支障をきたしており強迫性障害である。不合理と自覚している(自我違和的)点と、確認行為という強迫行為が反復する点が診断の決め手になる。

【誤答選択肢の解説】
A「適応障害」: 適応障害はストレス因に対する抑うつや不安が主体で、この患者のような定型的な確認強迫は説明できない。
B「解離性障害」: 解離性障害は記憶や同一性の連続性が失われる病態で、健忘や遁走を認めない本例は当てはまらない。
D「身体化障害」: 身体化障害では多彩な身体症状を訴える。身体症状の訴えはない。
E「社交〈社会〉不安障害」: 社交〈社会〉不安障害は人前で注視され評価されることへの恐怖で、一人暮らしの自宅の戸締りとは関係しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A059（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-63', '正答は D「デング熱」。

東南アジアから帰国後の高熱・筋肉痛に、口腔粘膜の点状出血、白血球2,000という白血球減少、Ht60%という血液濃縮を伴っておりデング熱である。潜伏期は3〜7日と短く、解熱するころに血漿漏出が進んでショックに陥ることがあるため、輸液管理が重要になる。

【誤答選択肢の解説】
A「エボラ出血熱」: エボラ出血熱の流行地は中部・西部アフリカで、東南アジアの渡航歴では考えない。
B「A型肝炎」: A型肝炎は黄疸と著明なトランスアミナーゼ上昇が前面に出る。出血傾向や血液濃縮は典型的でない。
C「腸チフス」: 腸チフスは高熱に比して脈が遅い比較的徐脈とバラ疹が特徴で、112/分の頻脈は合わない。
E「マラリア」: マラリアは周期的な発熱と溶血性貧血、脾腫を伴う。脾を触知せず、点状出血と血液濃縮が目立つ本例には合わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A063（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-69', '正答は E「副腎静脈血サンプリング」。

低カリウム血症を伴う高血圧で、血漿アルドステロン濃度472pg/mLに対し血漿レニン活性0.1ng/mL/時とアルドステロン・レニン比が著明に高く、原発性アルドステロン症である。手術の可否を決めるには片側性か両側性かの判定が要るので、確定後の局在診断として副腎静脈血サンプリングを行う。

【誤答選択肢の解説】
A「FDG-PET」: FDG-PETは悪性腫瘍の検索に用いる検査で、アルドステロン産生腺腫の同定には役立たない。
B「レノグラム」: レノグラムは腎の血流と排泄機能をみる検査で、副腎の局在診断はできない。
C「腎静脈血サンプリング」: 腎静脈血サンプリングはレニン分泌の左右差をみる検査で、腎血管性高血圧の評価に用いる。本例はレニンが抑制されている。
D「ガリウムシンチグラフィ」: ガリウムシンチグラフィは炎症巣や腫瘍の検索に用いる。副腎皮質の機能を反映する核医学検査はアドステロールシンチグラフィである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A069（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-7', '正答は A「悪性貧血」。

自己免疫性胃炎(A型胃炎)では胃体部の壁細胞が自己免疫機序で破壊され、内因子の分泌が失われる。回腸末端でのビタミンB12吸収が障害され、悪性貧血(巨赤芽球性貧血)をきたす。

【誤答選択肢の解説】
B「溶血性貧血」: 溶血性貧血との関連はない。
C「悪性リンパ腫」: 胃MALTリンパ腫はH. pylori感染に関連する。
D「鉄欠乏性貧血」: 鉄欠乏性貧血も初期に生じうるが、A型胃炎に特徴的な合併症は悪性貧血である。
E「再生不良性貧血」: 再生不良性貧血との関連はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-72', '正答は A「動脈管開存症」。

右心室83.9%に対して右肺動脈90.2%・左肺動脈92.6%と、肺動脈のレベルで酸素飽和度が段階的に上昇している。左右短絡の流入部位が肺動脈であることを示しており、大動脈から肺動脈へ血液が流れ込む動脈管開存症である。

【誤答選択肢の解説】
B「Fallot四徴症」: Fallot四徴症は右左短絡のため大動脈血の酸素飽和度が低下する。大動脈98.8%とは相容れない。
C「心房中隔欠損症」: 心房中隔欠損症では右心房の段階で酸素飽和度が上昇する。右心房84.5%は上大静脈82.8%と大差ない。
D「心室中隔欠損症」: 心室中隔欠損症では右心室の段階で上昇する。右心室83.9%は右心房84.5%と大差ない。
E「房室中隔欠損症〈心内膜床欠損症〉」: 房室中隔欠損症〈心内膜床欠損症〉は心房と心室の両方に短絡があり、右心房から酸素飽和度が上がる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A072（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-8', '正答は E「マンモグラフィ」。

我が国の対策型乳がん検診は40歳以上の女性を対象に2年に1回のマンモグラフィで行う。死亡率減少効果が示されている方法である。

【誤答選択肢の解説】
A「CT」: CTは被曝が多く、対策型検診には用いない。
B「MRI」: MRIは高リスク者の検査で、対策型検診の方法ではない。
C「視触診」: 視触診は単独では死亡率減少効果が示されず、現在は推奨されていない。
D「超音波検査」: 超音波検査は有効性の証拠が十分でなく、対策型検診には含まれない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-A-9', '正答は B「静止時振戦」。

静止時振戦はParkinson病でみられる所見である。肝硬変で特徴的なのは羽ばたき振戦(アステリキシス)で、性質が異なる。

【誤答選択肢の解説】
A「手掌紅斑」: 手掌紅斑はエストロゲンの代謝障害による。正しい。
C「女性化乳房」: 女性化乳房も同じ機序で生じる。正しい。
D「くも状血管腫」: くも状血管腫も肝硬変の代表的な皮膚所見である。正しい。
E「腹壁静脈怒張」: 腹壁静脈怒張(メデューサの頭)は門脈圧亢進による側副血行路である。正しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 A009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-1', '正答は C「薬剤に関する報告件数が最も多い。」。

インシデントレポートで報告される事象は薬剤に関するものが最も多く、指示・処方の誤りや与薬時の間違いが上位を占める。原因の分析と再発防止に用いるためのもので、報告者の責任追及には使わない。

【誤答選択肢の解説】
A「保健所に報告する義務がある。」: 保健所への報告義務はない。院内の医療安全管理部門で集計・分析する。
B「医療安全管理委員会が作成する。」: 作成するのは事象に関与した、あるいは発見した医療従事者である。医療安全管理委員会は集まった報告を分析して対策を立てる。
D「報告件数が少ないほど医療安全の質が高い。」: 報告件数が少ないのは報告しにくい組織風土を示すことがあり、安全の質が高い証拠にはならない。
E「患者に実害がない場合は作成する必要はない。」: 患者に実害が及ばなかった事例(ヒヤリ・ハット)こそ再発防止の手がかりであり、報告の対象である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-11', '正答は B「「何をするのも億劫で仕方ありません」」。

「何をするのも億劫」は意欲低下と精神運動制止を表す訴えで、抑うつ状態の中核症状である。抑うつ気分、興味・喜びの喪失とともに、うつ病を疑う手がかりになる。

【誤答選択肢の解説】
A「「すぐにかっとなってしまいます」」: かっとなりやすいのは易怒性で、躁状態や器質性精神障害、認知症などでみられる。
C「「なんとなく落ち着かない気持ちになります」」: 落ち着かない気持ちは不安や焦燥を表す訴えで、不安障害でもみられる。
D「「昼間にうとうとすることが多くなりました」」: 昼間の傾眠は睡眠時無呼吸症候群や薬剤性など睡眠の問題を示唆する。
E「「外に出ると誰かに見られているような気がします」」: 見られている感じは注察妄想で、統合失調症を疑う訴えである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-12', '正答は C「一般名による薬剤名の記載は有効である。」。

後発医薬品の使用促進のため一般名(一般的名称)による処方が認められており、薬局で該当する銘柄を調剤できる。処方箋には氏名・年齢・薬名・分量・用法用量・発行年月日・使用期間などの記載が必要である。

【誤答選択肢の解説】
A「有効期間は1日である。」: 使用期間の記載がなければ、交付の日を含めて4日以内である。
B「薬剤師に発行権限がある。」: 処方箋を交付できるのは医師・歯科医師・獣医師で、薬剤師に発行権限はない。
D「医療機関が特定の保険薬局を指定できる。」: 患者には保険薬局を選ぶ自由があり、医療機関が特定の薬局を指定することはできない。
E「処方医は自筆で署名をしなくてはならない。」: 記名押印でもよく、自筆の署名でなければならないわけではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B012（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-13', '正答は B「肥大型心筋症」。

肥大型心筋症はサルコメア蛋白の遺伝子変異による常染色体顕性(優性)遺伝形式をとることが多く、半数程度が家族性である。突然死の家族歴も含めて家族内発症を確認することが診断と血縁者のスクリーニングに直結する。

【誤答選択肢の解説】
A「心房細動」: 心房細動の大半は加齢・高血圧・心不全・弁膜症などを背景に生じる。家族歴が診断の決め手になることは少ない。
C「冠攣縮性狭心症」: 冠攣縮性狭心症は喫煙や飲酒などの生活習慣の関与が大きい。
D「大動脈弁狭窄症」: 大動脈弁狭窄症は加齢に伴う石灰化が主因で、二尖弁でも多くは孤発例である。
E「心サルコイドーシス」: 心サルコイドーシスは原因不明の肉芽腫性疾患で、家族集積性は乏しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B013（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-14', '正答は B「40歳」。

介護保険の被保険者は、65歳以上の第1号被保険者と、40歳以上65歳未満の医療保険加入者である第2号被保険者からなる。強制加入となるのは40歳からで、第2号被保険者は特定疾病による要介護状態のときに給付を受けられる。

【誤答選択肢の解説】
A「20歳」: 20歳は国民年金の強制加入開始年齢である。
C「60歳」: 60歳から始まる公的な保険制度はない。
D「65歳」: 65歳は第1号被保険者になる年齢で、加入が始まる年齢ではない。
E「75歳」: 75歳は後期高齢者医療制度の対象となる年齢である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B014（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-15', '正答は C「結節性紅斑」。

結節性紅斑は下腿伸側に生じる有痛性の皮下結節で、圧痛はあっても瘙痒はきたしにくい。溶連菌感染やサルコイドーシス、Behçet病、炎症性腸疾患などに伴って現れる。

【誤答選択肢の解説】
A「薬疹」: 薬疹の多くは瘙痒を伴う播種状の紅斑として現れる。
B「蕁麻疹」: 蕁麻疹は強い瘙痒を伴う膨疹が出没するのが特徴である。
D「多形滲出性紅斑」: 多形滲出性紅斑は標的状の紅斑で、瘙痒や灼熱感を伴う。
E「アトピー性皮膚炎」: アトピー性皮膚炎は瘙痒が診断に必須の症状である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B015（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-16', '正答は C「血圧低下」。

緊張性気胸では胸腔内圧の上昇が縦隔を健側へ圧排し、静脈還流が妨げられて血圧が低下する。閉塞性ショックであり、画像検査を待たずに患側の胸腔穿刺による脱気を行う。

【誤答選択肢の解説】
A「ばち指」: ばち指は慢性の低酸素血症や肺癌、間質性肺炎、Fallot四徴症などで生じ、急性の緊張性気胸では認めない。
B「奇異呼吸」: 奇異呼吸は吸気時に胸壁が陥凹する所見で、フレイルチェストや上気道閉塞でみられる。
D「縦隔動揺」: 縦隔動揺は呼吸性に縦隔が左右へ振れる所見で、フレイルチェストや開放性気胸でみられる。緊張性気胸では縦隔は健側へ偏位したままになる。
E「患側肋間腔狭小」: 患側の肋間腔はむしろ開大し、胸郭の膨隆と打診上の鼓音を伴う。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B016（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-17', '正答は D「相手の話を熱心に聞く。」。

傾聴は相手の話に関心を向けて熱心に聞く態度そのものを指す。うなずきや相づち、沈黙を待つといった非言語的な促しによって、患者が語りやすい場をつくることが目的である。

【誤答選択肢の解説】
A「事実確認を行う。」: 事実の確認は必要な作業だが、聞き手の関心に沿って情報を確かめる行為であり傾聴とは異なる。
B「アドバイスをする。」: 助言を挟むと患者の語りが途切れる。傾聴の段階では判断や助言を控える。
C「時間を限って聞く。」: 時間を区切って聞くことは効率のための工夫であって、傾聴の要件ではない。
E「決められた項目を聞く。」: あらかじめ決めた項目を順に尋ねるのは構造化面接であり、患者の語りに従う傾聴とは対照的である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-18', '正答は D「アミノグリコシド系」。

アミノグリコシド系は有効域と中毒域が近く、腎障害と第8脳神経障害(聴力障害・平衡障害)を起こすため治療薬物モニタリングの対象となる。ほかにバンコマイシン、テイコプラニン、アルベカシン、ボリコナゾールが対象である。

【誤答選択肢の解説】
A「カルバペネム系」: カルバペネム系は治療域が広く、通常TDMの対象としない。
B「ニューキノロン系」: ニューキノロン系は経口吸収がよく、血中濃度測定は日常的には行わない。
C「リンコマイシン系」: リンコマイシン系(クリンダマイシンなど)もTDMの対象ではない。
E「セファロスポリン系」: セファロスポリン系は安全域が広く、血中濃度の測定は不要である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B018（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-19', '正答は D「横隔膜ヘルニア」。

先天性横隔膜ヘルニアでは胎生期に腹部臓器が胸腔内へ脱出し、肺の発育を妨げるため肺低形成をきたす。出生直後から呼吸不全と肺高血圧をきたすので、バッグマスク換気を避けて気管挿管を行い、循環を安定させてから手術する。

【誤答選択肢の解説】
A「水頭症」: 水頭症は脳室の拡大による病態で、肺の発育には影響しない。
B「二分脊椎」: 二分脊椎は下肢の運動・感覚障害や膀胱直腸障害をきたすが、肺低形成は伴わない。
C「臍帯ヘルニア」: 臍帯ヘルニアは腹腔外に臓器が脱出するもので、胸腔は圧迫されない。
E「先天性食道閉鎖症」: 先天性食道閉鎖症は気管食道瘻を伴うことが多く誤嚥性肺炎をきたすが、肺低形成の原因にはならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-2', '正答は B「咳嗽を伴う。」。

喀血は気道からの出血なので、咳嗽とともに喀出される。鮮紅色で泡沫を混じ、アルカリ性であることも吐血との鑑別点になる。

【誤答選択肢の解説】
A「悪心を伴う。」: 悪心を伴って嘔吐されるのは吐血である。
C「食物残渣を伴う。」: 食物残渣が混じるのは胃内容とともに嘔出された吐血である。
D「タール便を伴う。」: タール便は上部消化管からの出血が腸管を通過したもので、吐血に伴う所見である。
E「暗赤色の色調である。」: 暗赤色やコーヒー残渣様の色調は胃酸で変性した血液で、吐血の特徴である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-20', '正答は D「完全房室ブロック — 安静臥位」。

完全房室ブロックによる失神(Adams-Stokes発作)は心室補充調律の停止や心室細動によって起こり、体位とは関係なく生じる。安静臥位はむしろ静脈還流を保って失神を防ぐ体位であり、誘因にはならない。

【誤答選択肢の解説】
A「起立性低血圧 — α遮断薬投与」: α遮断薬は末梢血管を拡張させて起立時の血圧低下を招くため、起立性低血圧の誘因として正しい。
B「頸動脈洞症候群 — 頸部の伸展」: 頸動脈洞症候群では頸部の伸展や回旋、きつい襟、髭剃りなどの刺激が徐脈と血圧低下を招く。正しい組合せである。
C「Brugada症候群 — 発熱」: Brugada症候群では発熱がナトリウムチャネルの機能異常を助長し、心室細動の引き金となる。正しい組合せである。
E「閉塞性肥大型心筋症 — 激しい運動」: 閉塞性肥大型心筋症では激しい運動により左室流出路の狭窄が強まり、心拍出量が低下して失神する。正しい組合せである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B020（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-21', '正答は A「国民皆保険制度である。」。

我が国は全国民が何らかの公的医療保険に加入する国民皆保険制度をとっており、1961年に達成された。フリーアクセス、現物給付、原則3割の一部負担が特徴である。

【誤答選択肢の解説】
B「予防接種は対象である。」: 予防接種や健康診断、正常分娩など疾病の治療にあたらないものは保険給付の対象外である。定期接種は予防接種法に基づき公費で行う。
C「保険医は保険者が指定する。」: 保険医を登録するのは厚生労働大臣である。保険者は保険料を集めて給付を行う主体である。
D「65歳以上は後期高齢者医療制度に加入する。」: 後期高齢者医療制度の対象は75歳以上、および65歳以上で一定の障害があると認定された者である。
E「雇用主は被用者保険の保険料を全額負担する。」: 被用者保険の保険料は事業主と被保険者が原則として折半して負担する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B021（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-22', '正答は E「被験者への説明と同意文書の取得」。

介入を伴う臨床研究では、目的・方法・予測される利益と不利益・拒否しても不利益を受けないことなどを説明したうえで、被験者本人から文書で同意を得る必要がある。インフォームド・コンセントは説明と自発的な同意の取得によって初めて成立する。

【誤答選択肢の解説】
A「研究に用いる薬物の服用」: 薬物を服用したという事実をもって同意とみなすことはできない。同意は投与に先立って得るものである。
B「研究を行う主治医の同意」: 主治医の同意は被験者本人の同意の代わりにならない。同意する権利は被験者にある。
C「研究施設の倫理委員会の承認」: 倫理委員会の承認は研究を実施するための要件だが、個々の被験者から同意を得る手続きとは別である。
D「施設のホームページでの公示」: ホームページでの公示による情報公開(オプトアウト)は既存資料を用いる観察研究などで認められる方式で、ランダム化比較試験には用いられない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-23', '正答は B「イヌリンクリアランスは正確なGFR評価に用いられる。」。

イヌリンは糸球体で自由に濾過され、尿細管で再吸収も分泌も受けないため、そのクリアランスがそのまま糸球体濾過量に等しくなる。手技が煩雑なので日常診療では推算GFRを用いるが、正確な測定の基準となるのはイヌリンクリアランスである。

【誤答選択肢の解説】
A「GFRの軽度低下で血清クレアチニン値は上昇する。」: 血清クレアチニン値はGFRが半分程度に低下するまで基準範囲にとどまる(クレアチニン盲域)。軽度低下では上昇しない。
C「健常者において加齢によるGFR低下は80歳まで起こらない。」: 健常者でも30〜40歳ごろから加齢とともに緩やかにGFRが低下する。
D「筋肉量が少ない場合はeGFRが実測GFRより低くなることが多い。」: 筋肉量が少ないと血清クレアチニン値が低く出るため、eGFRは実測GFRより高く見積もられる。
E「成人のeGFRは血清クレアチニン値、身長および年齢から計算される。」: 成人のeGFRは血清クレアチニン値、年齢、性別から計算する。身長を用いるのは小児の推算式である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B023（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-25', '正答は E「患者が未成年の場合、患者の意思よりも代理人の希望が優先される。」。

リスボン宣言では、法的無能力の患者であっても、判断能力があればその意思決定に参加する権利を認めており、患者の意思は尊重されなければならないとしている。代理人の希望が一律に優先されるわけではない。

【誤答選択肢の解説】
A「患者には医療情報の提供を拒否する権利がある。」: 患者には知る権利とともに、知らされないことを明確に要求する権利も認められている。
B「患者には医学教育への参加を拒否する権利がある。」: 医学教育や医学研究への参加を拒否する権利が明記されている。
C「自殺企図の患者の場合、患者の生命を救う努力をする。」: 意識のない患者や自殺企図の患者については、常に患者の最善の利益に沿って生命を救う努力をするとされている。
D「患者の情報は患者の死後も秘密が守られる必要がある。」: 患者の秘密は死後も守られなければならないと明記されている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-26', '正答は A「表情をみながら触診する。」。

重度の認知症で言葉による訴えができない患者では、表情の変化が疼痛や不快を伝える主要な手がかりになる。うなり声も苦痛の表現でありうるので、表情を確かめながらゆっくり触診し、痛みの部位を探る。

【誤答選択肢の解説】
B「浮腫の有無は左半身で判断する。」: 右側臥位では下側になる右半身に浮腫が偏る。体位の影響を考慮して両側を比べる必要がある。
C「股関節を完全伸展させてから診察する。」: 拘縮した関節を無理に伸展させると強い疼痛や骨折を招く。可動域の範囲内で診察する。
D「声を出さないよう指示してから聴診する。」: 重度の認知症では指示が通らず、うなり声は苦痛の表現でもある。抑えさせるべきものではない。
E「打診は疼痛が疑われる部位に繰り返し行う。」: 疼痛が疑われる部位に打診を繰り返せば苦痛を強いることになる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B026（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-27', '正答は D「横紋筋融解症」。

慣れないフルマラソン後の筋肉痛と赤黒い尿で、尿潜血3+にもかかわらず沈渣に赤血球を認めないことから、ミオグロビン尿を反映した横紋筋融解症である。ミオグロビンは尿潜血反応を陽性にするが赤血球としては見えない。急性腎障害と高カリウム血症を警戒し、大量輸液を行う。

【誤答選択肢の解説】
A「膀胱炎」: 膀胱炎では排尿時痛や頻尿を伴い、沈渣に白血球と細菌を認める。
B「IgA腎症」: IgA腎症では沈渣に変形赤血球や赤血球円柱を認め、蛋白尿を伴うことが多い。
C「尿路結石」: 尿路結石では側腹部の疝痛発作を伴い、沈渣に赤血球を認める。
E「多発性囊胞腎」: 多発性囊胞腎では両側の腹部腫瘤と高血圧、家族歴を認め、血尿は赤血球によるものである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B027（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-28', '正答は D「患者の推定意思を尊重し家族と医療チームが話し合って決定する。」。

本人の意思が確認できないときは、家族等から本人の価値観や過去の言動を聴き取って推定意思を尊重し、それに基づいて何が本人にとって最善かを医療・ケアチームと家族が繰り返し話し合って決める。人生の最終段階における医療・ケアの決定プロセスに関するガイドラインの基本的な考え方である。

【誤答選択肢の解説】
A「患者を介護する家族が決定する。」: 決定の基礎になるのは家族の希望ではなく本人の推定意思である。本例では家族の意見も分かれている。
B「病状説明を行って患者が決定する。」: 傾眠状態で呼びかけに反応せず、現時点で本人が意思決定できる状態にない。
C「患者にとっての最善な治療方法を医療チームが決定する。」: 医学的な妥当性だけで医療チームが決めてよいものではない。本人の推定意思と家族との合意形成が要る。
E「院内に設置された委員会が家族と医療チームの意見に基づいて決定する。」: 複数の専門職からなる委員会は、話し合っても合意に至らない場合に助言を求める仕組みであり、最初から判断を委ねる場ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B028（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-29', '正答は D「体重」。

体重は日々同じ条件で測れば体液貯留を最も鋭敏かつ定量的に反映する。数日で2〜3kg増えれば心不全の増悪を疑う手がかりになり、自己管理の指標として在宅での測定が勧められる。

【誤答選択肢の解説】
A「体温」: 体温は体液量を反映せず、感染などの合併を知る指標である。
B「脈拍」: 脈拍は活動や情動でも変動し、体液量の指標としての特異度が低い。
C「血圧」: 血圧も測定条件や服薬で変動し、体液貯留を早期に捉える指標にはならない。
E「浮腫」: 浮腫が目に見えるようになるのは数kgの体液貯留が生じた後で、体重変化より遅れて現れる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B029（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-3', '正答は D「症例対照研究のために患者に許可なく本籍地を含む個人情報を収集した。」。

研究のために診療目的を超えた個人情報を本人の許可なく収集することは、個人情報保護法にも人を対象とする医学系研究の倫理指針にも反する。研究利用には本人の同意、または倫理審査委員会の承認を得たうえでの適切な手続きが必要である。

【誤答選択肢の解説】
A「患者から医療施設への寄付の申し出があり受け入れた。」: 医療施設への寄付は個々の診療内容に影響を与えない限り受け入れうる。医師個人が診療の見返りとして金品を受け取ることとは区別される。
B「自らの専門性を超えると判断した患者を他の医療機関に紹介した。」: 自らの能力を超えると判断したときに適切な医療機関へ紹介することは、むしろ医師の義務である。
C「サプリメントを使用する患者に健康被害に留意するよう指導した。」: サプリメントの使用を頭ごなしに否定せず、健康被害の可能性を伝えて注意を促すのは適切な指導である。
E「血液製剤の使用を拒む成人患者に意思の尊重と救命の両立とを図る努力をした。」: 輸血拒否のような場合に、患者の自己決定を尊重しつつ救命の道を探る努力をすることは倫理的に望ましい対応である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-30', '正答は E「「痛みの原因をどのように考えていますか」」。

解釈モデルとは、患者が自分の症状の原因や意味をどう理解しているかという考えである。これを尋ねることで患者の心配の中身が分かり、説明の焦点を定めやすくなる。解釈・感情・影響・期待の4つを聞き出すのが医療面接の基本である。

【誤答選択肢の解説】
A「「どうされましたか」」: 受診の理由を広く尋ねる開放型質問で、解釈モデルを直接引き出す問いではない。
B「「どのような痛みですか」」: 痛みの性状という症状の情報を集める質問である。
C「「最近ストレスはありましたか」」: 心理社会的な背景を探る質問で、患者自身の解釈を尋ねてはいない。
D「「このような痛みは初めてですか」」: 症状の経過を確かめる質問である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B030（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-32', '正答は A「鼻翼をつまむ。」。

鼻出血の大部分は鼻中隔前方のKiesselbach部位からで、座って軽く前かがみになり、鼻翼を指でつまんで10〜20分圧迫すれば止まることが多い。硬い鼻骨ではなく柔らかい鼻翼を左右から押さえるのがこつである。

【誤答選択肢の解説】
B「仰臥位にする。」: 仰臥位にすると血液が咽頭へ流れ込み、誤嚥や嘔吐を招く。座位で軽く前傾させる。
C「鼻部を氷で冷やす。」: 冷罨法は補助的なもので、これだけでは止血できない。
D「後頸部を軽くたたく。」: 後頸部を叩いても止血効果はない。
E「のどに流れてきた血液は飲み込ませる。」: 飲み込んだ血液は嘔気・嘔吐を誘発するため、口から吐き出させる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B032（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-35', '正答は C「3」。

徒手筋力テストで、重力に抗して全可動域の運動ができるが抵抗を加えると保てない状態は3(Fair)である。重力に抗せるかどうかが2と3の、抵抗に抗せるかどうかが3と4の境目になる。

【誤答選択肢の解説】
A「1」: 1(Trace)は筋収縮を触知できるが関節運動が起こらない状態である。
B「2」: 2(Poor)は重力を除いた肢位でのみ全可動域の運動ができる状態である。
D「4」: 4(Good)は中等度の抵抗に抗して全可動域の運動ができる状態である。
E「5」: 5(Normal)は強い抵抗に抗して全可動域の運動ができる状態である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B035（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-36', '正答は B「ジアゼパム」。

けいれんが反復して意識が戻らない、あるいは5分以上続く状態はてんかん重積状態であり、第一選択はベンゾジアゼピン系のジアゼパム静注である。抗けいれん薬の自己中断が誘因になっている。呼吸抑制に備えて気道管理の準備をしておく。

【誤答選択肢の解説】
A「モルヒネ」: モルヒネは鎮痛薬で抗けいれん作用はなく、呼吸抑制を加えるだけである。
C「フロセミド」: フロセミドは利尿薬でけいれんの治療薬ではない。
D「アドレナリン」: アドレナリンは心停止やアナフィラキシーに用いる。
E「グルコン酸カルシウム」: グルコン酸カルシウムは低カルシウム血症によるテタニーや高カリウム血症の心筋保護に用いる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B036（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-37', '正答は E「ゆっくり呼吸するように指導する。」。

満員バスという状況で誘発された頻呼吸に、SpO2は100%で低酸素はなく、呼吸性アルカローシスによる口周囲と四肢のしびれを伴っており過換気症候群である。安心させたうえで、意識してゆっくり呼吸するよう指導すれば軽快する。

【誤答選択肢の解説】
A「抗精神病薬を内服させる。」: 抗精神病薬の適応はない。不安が強ければ抗不安薬を考慮する。
B「そのまま学校に行かせる。」: 症状が続いたまま帰すのは不適切で、まず呼吸を落ち着かせる。
C「低流量酸素を吸入させる。」: SpO2は100%で低酸素血症はなく、酸素投与を要さない。
D「紙袋を口につけて呼吸させる。」: 紙袋再呼吸法は低酸素血症を招いて死亡した例が報告されており、現在は行わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B037（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-38', '正答は B「診療方針について患者本人に説明し意向を聞く。」。

聴覚障害と軽度の知的障害が疑われても意識は清明で、意思決定能力がないと決めつけてはならない。筆談や図の使用などその人に合った方法で分かるように説明し、本人の意向を確かめることが出発点になる。

【誤答選択肢の解説】
A「医師が患者に代わって診療方針を決定する。」: 本人への意思決定支援を尽くさずに医師が代行して決めてよいものではない。
C「民生委員を成年後見人とみなして診療方針について相談する。」: 民生委員は地域の相談・見守りを担う非常勤の特別職公務員で、法定代理権をもたない。成年後見人とみなすことはできない。
D「患者本人の意思決定困難を理由にこれ以上の検査治療を行わない。」: 意思決定が難しいことを理由に検査や治療を控えるのは、障害を理由とする不利益な取扱いにあたる。
E「医学的検査の結果に基づき、客観的に治療の適否や内容を決定する。」: 医学的所見のみで客観的に決めるのは、本人の価値観や意向を無視した対応である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B038（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-4', '正答は D「臍帯動脈」。

臍帯動脈は胎児から胎盤へ向かう血管で、全身を灌流し終えた血液が流れるため胎児循環で最も酸素飽和度が低い。胎盤でガス交換を受けたあと臍帯静脈として胎児に戻る、という向きを押さえておく。

【誤答選択肢の解説】
A「左心室」: 左心室には卵円孔を経て酸素飽和度の高い血液が流入し、脳と上肢へ送られる。
B「静脈管」: 静脈管は臍帯静脈の血液を肝を迂回して下大静脈へ導く経路で、酸素飽和度は高い。
C「臍帯静脈」: 臍帯静脈は胎盤でガス交換を受けた直後の血液で、胎児循環で最も酸素飽和度が高い。
E「中大脳動脈」: 中大脳動脈は左心系から送り出された比較的酸素飽和度の高い血液を受ける。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-40', '正答は B「異状死の届出」。

診療中の疾病と関係のない外因や、死因に異状が疑われる状況で死亡を確認した場合、医師は24時間以内に所轄警察署へ届け出なければならない(医師法第21条)。肺炎が治癒し退院予定だった患者が点滴チューブの外れとともに死亡しており、異状死として届け出る。

【誤答選択肢の解説】
A「清掃の指示」: 現場は保存する必要があり、清掃してしまうと検証ができなくなる。
C「保健所へ連絡」: 異状死の届出先は所轄警察署であって保健所ではない。
D「病理解剖の依頼」: 病理解剖は病死の死因を究明するためのもので、遺族の承諾も要る。この状況ではまず警察への届出が先である。
E「死亡診断書の記載」: 死因を診療中の疾病で説明できないため死亡診断書は書けない。届出を経たうえで死体検案書となる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B040（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-5', '正答は B「鑑別診断」。

SOAPのA(Assessment)は、SとOから導かれる評価であり、鑑別診断や病態の解釈がここに入る。SOAPは主観的情報・客観的情報・評価・計画の順に整理する記載法である。

【誤答選択肢の解説】
A「現病歴」: 現病歴は患者本人が語る情報でS(Subjective)に入る。
C「検査結果」: 検査結果は測定された客観的情報でO(Objective)に入る。
D「身体所見」: 身体所見も診察で得た客観的情報でO(Objective)に入る。
E「治療計画」: 治療計画は次に何をするかを示すのでP(Plan)に入る。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-6', '正答は D「Osler結節」。

Osler結節は手指や足趾の腹側にできる有痛性の紅色結節で、感染性心内膜炎の免疫複合体による血管炎を反映する。無痛性のJaneway斑や爪下線状出血とともに末梢の血管病変として現れる。

【誤答選択肢の解説】
A「Roth斑」: Roth斑は網膜にみられる中心が白い出血斑で、感染性心内膜炎を示唆するが眼底所見であって皮膚所見ではない。
B「輪状紅斑」: 輪状紅斑はリウマチ熱の大症状の一つで、体幹に環状の紅斑が現れる。
C「Koplik斑」: Koplik斑は麻疹の発疹出現前に頬粘膜に生じる白色斑で、粘膜疹である。
E「遊走性紅斑」: 遊走性紅斑はマダニ刺咬部から環状に拡大するLyme病の初期病変である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-7', '正答は C「認知機能」。

3つの単語を言わせて復唱させるのは、改訂長谷川式簡易知能評価スケールやMMSEなど認知機能検査の記銘の項目である。高齢者総合機能評価では身体機能・認知機能・情緒・社会的背景を多面的に評価する。

【誤答選択肢の解説】
A「意欲」: 意欲の評価にはVitality Indexなど、日常の行動観察に基づく尺度を用いる。
B「運動機能」: 運動機能はTimed Up and Go テストや開眼片脚起立時間、握力などで評価する。
D「基本的日常生活動作」: 基本的日常生活動作は食事・移動・排泄などの自立度をBarthel IndexやFIMで評価する。
E「手段的日常生活動作」: 手段的日常生活動作は買い物・金銭管理・服薬管理などをLawton尺度や老研式活動能力指標で評価する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-B-9', '正答は A「血小板の減少」。

血小板減少はHELLP症候群など妊娠高血圧症候群の重症化を示す臓器障害の指標で、加重型やけいれん発作への移行を警戒する必要がある。ほかに肝機能障害、腎機能障害、肺水腫、視覚障害や持続する頭痛も重症化の徴候となる。

【誤答選択肢の解説】
B「呼吸数の減少」: 肺水腫が生じれば呼吸数はむしろ増加する。呼吸数の減少は重症化の指標にならない。
C「下腿浮腫の悪化」: 下腿浮腫は正常妊娠でも高頻度にみられるため、現在の診断基準では重症度の判定に用いない。
D「子宮収縮の増強」: 子宮収縮の増強は切迫早産や常位胎盤早期剝離を疑う所見であって、妊娠高血圧症候群そのものの重症度指標ではない。
E「尿蛋白/クレアチニン比の低下」: 尿蛋白/クレアチニン比は増加が病態の進行を示す。低下は重症化を示さない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 B009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-10', '正答は B「セラミド」。

角層では、角化細胞が産生した層板顆粒の内容が細胞間に放出され、セラミド・コレステロール・遊離脂肪酸がラメラ構造をつくる。なかでもセラミドが約半分を占め、水分の保持と経皮的な水分喪失の防止を担う。

【誤答選択肢の解説】
A「ケラチン」: ケラチンは角化細胞の内部を満たす中間径フィラメントで、細胞間脂質ではない。
C「アミロイド」: アミロイドはβシート構造をとる異常蛋白の沈着で、正常の角層構成成分ではない。
D「デスモソーム」: デスモソームは角化細胞どうしを結ぶ接着装置で、蛋白からなる。
E「ヘミデスモソーム」: ヘミデスモソームは基底細胞を基底膜に接着させる装置である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-11', '正答は C「十二指腸」。

十二指腸は球部を除いて後腹膜に固定されており、腸間膜をもたない。ほかに膵(尾部を除く)、上行結腸、下行結腸、腎、副腎、尿管、腹部大動脈、下大静脈が後腹膜臓器である。

【誤答選択肢の解説】
A「食道」: 食道は大部分が後縦隔を走り、腹腔内に入る部分はごく短い。後腹膜臓器には数えない。
B「胃」: 胃は小網と大網をもち、腹腔内を可動性をもって位置する。
D「空腸」: 空腸は腸間膜をもつ腹腔内臓器で、可動性がある。
E「横行結腸」: 横行結腸は横行結腸間膜をもつ腹腔内臓器である。上行結腸・下行結腸が後腹膜に固定されているのと対照的である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-12', '正答は D「2.1」。

人口置換水準は、女性が生涯に産む子どもの数が親世代を過不足なく置き換える水準で、我が国ではおよそ2.07である。女児の出生割合と、女性が出産年齢に達するまでの死亡を考慮するため2をやや上回る。

【誤答選択肢の解説】
A「1.0」: 1.0では次の世代の人口が半減する。
B「1.1」: 1.1も人口置換水準を大きく下回る。近年の我が国の合計特殊出生率はこれに近い水準まで低下している。
C「1.9」: 1.9はやや下回る水準で、人口は緩やかに減少する。
E「4.0」: 4.0は出生率の高い開発途上国でみられる水準である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C012（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-16', '正答は D「この結果から喫煙による肺癌死亡の寄与危険度が計算できる。」。

曝露の有無で群を分けて10年間追跡したコホート研究である。寄与危険度(リスク差)は曝露群の罹患率から非曝露群の罹患率を引いたもので、1.20−0.10=1.10(人/1,000人年)と計算できる。

【誤答選択肢の解説】
A「研究手法は症例対照研究である。」: 疾病の発生前に曝露を把握して追跡しており、コホート研究である。症例対照研究は結果が生じた後に過去の曝露をさかのぼって調べる。
B「この研究は喫煙と肺癌の因果関係を証明している。」: 統計的な関連を示すだけでは因果関係の証明にならない。時間的前後関係、量・反応関係、生物学的妥当性などを併せて判断する。
C「喫煙本数と肺癌死亡率の間に量・反応関係がある。」: 喫煙の有無しか示されておらず、喫煙本数別のデータがないため量・反応関係は判断できない。
E「喫煙者の非喫煙者に対する肺癌死亡の相対危険度は1.2である。」: 相対危険度は1.20÷0.10=12である。1.2は両者の値を取り違えている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C016（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-17', '正答は B「MRワクチン — 水痘ワクチン」。

2020年10月の改正で異なるワクチン間の接種間隔の制限は原則撤廃され、現在も27日以上あける必要があるのは注射生ワクチンどうしの場合だけである。MRワクチンも水痘ワクチンも注射生ワクチンなので、同時接種しないなら27日以上あける。

【誤答選択肢の解説】
A「BCG — ロタウイルスワクチン」: ロタウイルスワクチンは経口生ワクチンで、注射生ワクチンとの間隔の制限はない。
C「おたふくかぜワクチン — 4種混合ワクチン」: 4種混合ワクチンは不活化ワクチンなので、接種間隔の制限を受けない。
D「小児用肺炎球菌ワクチン — B型肝炎ワクチン」: 小児用肺炎球菌ワクチンもB型肝炎ワクチンも不活化ワクチンで、間隔の制限はない。
E「インフルエンザ桿菌ワクチン — MRワクチン」: インフルエンザ桿菌〈Hib〉ワクチンは不活化ワクチンなので、MRワクチンとの間隔の制限はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-18', '正答は E「我が国の相対的貧困率はOECD加盟国の平均より高い。」。

相対的貧困率は等価可処分所得が中央値の半分に満たない人の割合で、我が国は15%前後とOECD加盟国の平均を上回る。生存に必要な最低限の水準を欠く絶対的貧困と異なり、その社会の標準的な生活水準からの隔たりを表す指標である。

【誤答選択肢の解説】
A「世界銀行が定義している。」: 1日あたりの所得額で絶対的貧困を定義しているのが世界銀行で、相対的貧困はOECDの定義による。
B「生活保護を受給している世帯の状況を指す。」: 生活保護の受給の有無とは無関係に、所得の分布から算出される。
C「単身世帯の相対的貧困率は母子世帯より高い。」: ひとり親世帯の相対的貧困率は5割近くに達し、単身世帯より高い。
D「世帯の大きさによらず世帯所得の高さで決まる。」: 世帯所得を世帯人員の平方根で割った等価可処分所得を用いるため、世帯の大きさを考慮している。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C018（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-19', '正答は B「介護福祉士」。

介護保険法上の機能訓練指導員になれるのは、理学療法士、作業療法士、言語聴覚士、看護職員、柔道整復師、あん摩マッサージ指圧師、および一定の実務経験のあるはり師・きゅう師である。介護福祉士は含まれない。

【誤答選択肢の解説】
A「看護師」: 看護師は看護職員として機能訓練指導員になれる。
C「言語聴覚士」: 言語聴覚士は機能訓練指導員になれる。
D「作業療法士」: 作業療法士は機能訓練指導員になれる。
E「理学療法士」: 理学療法士は機能訓練指導員になれる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-2', '正答は A「二次医療圏単位で構築される。」。

地域包括ケアシステムが想定する範囲は、おおむね30分以内に必要なサービスが提供される日常生活圏域(中学校区程度)である。二次医療圏は一般的な入院医療を提供する単位で、地域包括ケアの単位ではない。

【誤答選択肢の解説】
B「生活支援サービスを中核とした包括的ケアである。」: 住まいを土台に、介護予防と生活支援を基盤として医療・介護・リハビリテーションの専門的サービスが乗るという構造で示される。
C「介護保険事業計画の策定によりシステムとして構築する。」: 市町村が3年ごとに策定する介護保険事業計画を通じて、地域の実情に応じて構築していく。
D「高齢者の尊厳の保持と自立生活の支援を目的としている。」: 高齢者が尊厳を保ちながら住み慣れた地域で自分らしい暮らしを続けられるようにすることを目的としている。
E「地域ケア会議で個別課題の支援を通じた地域の課題把握を行う。」: 地域ケア会議では個別事例の検討を積み重ねることで地域に共通する課題を見いだし、政策形成につなげる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-20', '正答は B「参加制約は生活環境に起因する。」。

ICFの参加制約は、その人が生活・人生の場面に関わるときに経験する困難で、建物や交通、制度、周囲の態度といった環境因子に大きく左右される。同じ機能障害があっても環境が整えば参加制約は生じない、という考え方をとる。

【誤答選択肢の解説】
A「障害者を対象とした分類である。」: ICFは障害の有無にかかわらずすべての人の生活機能を記述する分類である。
C「障害程度を基準にした分類である。」: 障害の程度で人を段階づける分類ではなく、心身機能・身体構造、活動、参加という構成要素を中立的な用語で記述する。
D「機能障害のために活動制限が生じる。」: 機能障害があっても、環境や個人因子によって活動制限が生じないことがある。一方向の因果ではなく相互作用としてとらえる。
E「参加制約と社会的不利は同義語である。」: 社会的不利はICIDHの用語で、障害の帰結を一方向にとらえていた。ICFはこれを環境との相互作用でとらえ直して参加制約と呼んでおり、同義ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C020（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-22', '正答は A「家族構成」。

要介護認定の一次判定は、認定調査員が調べる74項目の基本調査と主治医意見書をコンピュータにかけ、介護に要する時間を推計して行う。調査項目は身体機能・起居動作、生活機能、認知機能、精神・行動障害、社会生活への適応などで構成され、家族構成のような介護環境は含まれない。

【誤答選択肢の解説】
B「生活機能」: 食事摂取、排尿、外出頻度などの生活機能は調査項目に含まれる。
C「認知機能」: 意思の伝達、短期記憶、日課の理解などの認知機能は調査項目に含まれる。
D「社会的行動」: 被害的、作話、昼夜逆転などの精神・行動障害(社会的行動)は調査項目に含まれる。
E「基本動作機能」: 寝返り、起き上がり、歩行などの基本動作機能(身体機能・起居動作)は調査項目に含まれる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-24', '正答は D「患者・家族からの苦情に対応する。」。

医療安全支援センターは、患者や家族からの医療に関する苦情・相談に対応し、助言や情報提供を行う窓口である。医療法に基づいて都道府県、保健所設置市および特別区に設置される。

【誤答選択肢の解説】
A「市町村に設置される。」: 設置主体は都道府県、保健所を設置する市および特別区で、すべての市町村ではない。
B「医療事故調査を実施する。」: 医療事故調査は医療機関自身が行い、その結果を医療事故調査・支援センターに報告する。名称は似ているが別の仕組みである。
C「地域保健法に規定されている。」: 根拠法は医療法であり、地域保健法ではない。
E「看護師の常駐が義務付けられている。」: 相談員を配置するが、看護師の常駐が義務付けられているわけではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-25', '正答は D「へき地医療拠点病院は一次医療圏単位で整備される。」。

へき地医療拠点病院は都道府県が二次医療圏を基本として指定し、無医地区への巡回診療、へき地診療所への医師派遣や代診医の派遣を担う。一次医療圏単位で整備されるものではない。

【誤答選択肢の解説】
A「巡回診療が推進されている。」: 無医地区などへの巡回診療はへき地医療拠点病院の中心的な役割の一つである。
B「ITの活用が推進されている。」: 遠隔画像診断や遠隔コンサルテーションなど情報通信技術の活用が進められている。
C「医療計画の5事業に含まれている。」: 医療計画では救急医療、災害時医療、へき地医療、周産期医療、小児医療の5事業(現在は新興感染症を加えて6事業)について体制を定める。
E「プライマリケアを実践する医師の確保が求められている。」: 限られた医師で幅広い健康問題に対応する必要があるため、総合的な診療能力をもつ医師の確保が課題とされている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-26', '正答は C「肺結核」。

肺結核は飛沫核(空気)感染するため、陰圧に保った個室で管理し、部屋の空気は高性能フィルターを通して排気する。医療者はN95マスクを着用する。麻疹と水痘も同じ空気感染予防策の対象である。

【誤答選択肢の解説】
A「インフルエンザ」: インフルエンザは飛沫感染で、サージカルマスクと個室ないし集団隔離で足りる。陰圧は要さない。
B「ウイルス性胃腸炎」: ウイルス性胃腸炎は接触感染が主で、手指衛生と適切な吐物処理が中心となる。
D「流行性角結膜炎」: 流行性角結膜炎は接触感染で、手指衛生と器具の消毒、患者の隔離で対応する。
E「流行性耳下腺炎」: 流行性耳下腺炎は飛沫感染で、飛沫予防策の対象である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C026（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-27', '正答は B「食に関する指導(食育)」。

食に関する指導(食育)は学校給食法および食育基本法に規定されており、学校保健安全法の規定ではない。学校保健安全法は健康診断、健康相談、感染症による出席停止、学校環境衛生、学校安全計画などを定める。

【誤答選択肢の解説】
A「学校職員の健康保持」: 職員の健康診断など学校職員の健康の保持増進が規定されている。
C「児童の学校外における安全点検や対策」: 通学路の安全を含め、学校外での安全確保に関する取組みが学校安全計画に位置づけられている。
D「児童の心的外傷後ストレス障害〈PTSD〉へのケア」: 事件・事故や災害の後に心身の健康問題を抱える児童生徒への支援(心のケア)が規定されている。
E「就学中に発生した災害時の児童に対する安全対策」: 危険等発生時対処要領の作成など、災害時の児童生徒の安全確保が規定されている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C027（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-28', '正答は A「Barthel Index〈BI〉」。

Barthel Indexは食事、移乗、整容、トイレ動作、入浴、歩行、階段昇降、更衣、排便・排尿の10項目を採点し、100点満点で日常生活動作の自立度を評価する尺度である。FIMとともにリハビリテーションの場で広く用いられる。

【誤答選択肢の解説】
B「Japan Coma Scale〈JCS〉」: Japan Coma Scaleは意識障害の深度を3-3-9度方式で評価する。
C「Glasgow Coma Scale〈GCS〉」: Glasgow Coma Scaleは開眼、言語反応、運動反応の3項目で意識レベルを評価する。
D「Brief Psychiatric Rating Scale〈BPRS〉」: Brief Psychiatric Rating Scaleは統合失調症などの精神症状の重症度を評価する。
E「Mini-Mental State Examination〈MMSE〉」: Mini-Mental State Examinationは見当識や記銘・計算などから認知機能を評価する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C028（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-3', '正答は B「曝露因子と関連している。」。

交絡因子は、曝露因子と関連があり、かつそれ自体が結果の危険因子であって、曝露から結果に至る中間段階にはない因子である。この3条件を満たすため、見かけ上の関連を生んだり真の関連を隠したりする。

【誤答選択肢の解説】
A「偶然誤差の一種である。」: 交絡は系統誤差(バイアス)の一種であり、標本の偶然のばらつきによる偶然誤差とは異なる。
C「コホート研究では発生しない。」: 交絡はコホート研究でも生じる。無作為割付を行わない限り曝露群と非曝露群の背景がそろわないためである。
D「統計的に有意でなければ無視できる。」: 統計学的に有意かどうかと交絡の有無は別の問題で、有意でなくても効果推定値は歪みうる。
E「データを収集した後には新しい交絡は発生しない。」: 解析段階で対象を絞り込んだり追跡から脱落したりすることでも新たな歪みが生じる。交絡はデザインと解析の両方で対処する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-31', '正答は D「医師の臨床研修」。

医師の臨床研修は医師法に規定されている。医療法が定めるのは医療提供施設の開設・管理、医療計画(医療圏、基準病床数、地域医療構想、医療従事者の確保など)、医療安全の確保といった医療提供体制に関する事項である。

【誤答選択肢の解説】
A「医療圏」: 医療圏(一次・二次・三次)は医療法に基づく医療計画で定められる。
B「基準病床数」: 基準病床数は病床の地域的な偏在を是正するため医療法に基づいて定められる。
C「地域医療構想」: 地域医療構想は2014年の医療法改正で医療計画の一部として位置づけられた。
E「医療従事者の確保」: 医療従事者の確保に関する事項は医療計画に定める項目として医療法に規定されている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C031（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-32', '正答は B「全職員対象の敷地内禁煙」。

ポピュレーションアプローチは、危険度の高い個人を選び出さずに集団全体に働きかけてリスク分布そのものを下げる方法である。全職員を対象とする敷地内禁煙は、対象を絞らずに集団全体の曝露を減らす典型例である。

【誤答選択肢の解説】
A「肥満者対象の脂肪吸引」: 肥満者という高リスク者を選んで介入しており、しかも治療的な処置である。
C「高血圧患者対象の内服治療」: 高血圧と診断された者に絞って治療しており、ハイリスクアプローチである。
D「長期欠席児童対象の心理相談」: 長期欠席という問題が生じた児童に限って介入するハイリスクアプローチである。
E「うつ病患者対象のカウンセリング」: うつ病と診断された患者への治療であり、ハイリスクアプローチにあたる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C032（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-34', '正答は D「生活保護制度」。

公助は公費(税)を財源として、自助・互助・共助では対応できない困窮に対応する仕組みで、生活保護や虐待対策、人権擁護がこれにあたる。社会保険方式で支え合う制度は共助、自らの健康管理は自助、住民同士の支え合いは互助と整理される。

【誤答選択肢の解説】
A「医療保険制度」: 医療保険制度は保険料を出し合って支え合う社会保険であり、共助にあたる。
B「介護保険制度」: 介護保険制度も社会保険であり、共助にあたる。
C「雇用保険制度」: 雇用保険制度も社会保険であり、共助にあたる。
E「特定健康診査」: 特定健康診査は自らの健康管理のために受けるもので、自助に位置づけられる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C034（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-35', '正答は E「80歳で20歯以上の自分の歯を有する者の割合の目標達成」。

健康日本21(第二次)の中間評価では、80歳で20歯以上の自分の歯を有する者の割合が目標値に達したと評価された。フッ化物の応用や定期的な歯科受診の普及が背景にある。

【誤答選択肢の解説】
A「成人の喫煙率の増加」: 成人の喫煙率は低下を続けており、増加してはいない。
B「野菜と果物の摂取量の目標達成」: 野菜摂取量は目標の350gに届かず、果物の摂取量も目標を下回ったままで、改善していない。
C「20歳代女性のやせの者の割合の増加」: 20歳代女性のやせの者の割合は横ばいで、増加したとは評価されていない。
D「20歳代における歯肉に炎症所見を有する者の割合の増加」: 20歳代で歯肉に炎症所見を有する者の割合は改善しておらず、増加という評価ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C035（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-4', '正答は D「トリアージは医師以外の医療職も行うことができる。」。

トリアージは医師に限らず、看護師、救急救命士など訓練を受けた医療職が実施できる。多数傷病者が同時に発生する災害では、限られた資源を最大多数の救命に振り向けるため、START法などで迅速に優先度を判定する。

【誤答選択肢の解説】
A「災害拠点病院は市区町村が指定する。」: 災害拠点病院を指定するのは都道府県知事である。
B「災害現場では医師は救急救命士の指揮下に入る。」: 救急救命士は医師の指示のもとで特定行為を行う。医師が救急救命士の指揮下に入ることはない。
C「防災体制を整備する地域的単位を二次医療圏と呼ぶ。」: 二次医療圏は一般的な入院医療を提供する区域として定められたもので、防災体制の整備単位として定義されたものではない。
E「災害医療とは災害時健康危機管理支援チーム〈DHEAT〉の医療活動のことである。」: DHEATは被災地の行政機能を支援する保健医療の専門職チームで、災害医療そのものを指す言葉ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-40', '正答は E「光化学オキシダント」。

夏の日中、快晴・微風・高温という条件で、屋外にいた複数の児童が同時に目の刺激と咽頭痛、咳を訴えている。窒素酸化物と揮発性有機化合物が紫外線を受けて生成する光化学オキシダントによる健康被害である。交通量の多い地域で発生しやすく、注意報が出れば屋外活動を控えさせる。

【誤答選択肢の解説】
A「輻射熱」: 輻射熱による熱中症であれば体温上昇や発汗停止、意識障害が主体で、目の刺激や咽頭痛は説明できない。
B「一酸化炭素」: 一酸化炭素中毒は閉鎖空間で起こり、頭痛や意識障害をきたすが眼刺激症状はない。屋外の校庭では考えにくい。
C「ダイオキシン」: ダイオキシンは慢性の曝露で問題となる物質で、10km離れた焼却施設から急性の集団症状が出ることはない。
D「微小粒子状物質」: 微小粒子状物質は呼吸器や循環器への影響が中心で、強い眼の刺激症状は特徴的でない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C040（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-41', '正答は D「「家庭血圧の測定を続けてください」」。

家庭血圧は診察室血圧より予後をよく反映し、白衣高血圧や仮面高血圧の判別、降圧薬の効果判定にも役立つ。良好に管理できている患者にも、測定の継続を勧めるのが適切である。

【誤答選択肢の解説】
A「「禁酒しましょう」」: 機会飲酒であり、節酒の助言は要るとしても禁酒を求める根拠はない。
B「「運動はもう必要ありません」」: 運動は降圧と心血管リスク低減に有効で、良好な管理が得られている今も続けるべきである。
C「「内服薬は時々休みましょう」」: 自己判断で服薬を中断すると血圧が再上昇する。指示どおりの継続が必要である。
E「「定期的な健康診査は受けなくてよいです」」: 血圧以外の異常を早期に見つけるためにも、定期的な健康診査は続けるべきである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C041（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-42', '正答は B「運動の推奨」。

BMI22.0で肥満はなく、食塩摂取5.5g/日、野菜350g/日と食事は良好、飲酒も少量である。是正すべき点は運動習慣がほとんどないことで、有酸素運動を毎日30分程度続けるよう勧めるのが適切である。

【誤答選択肢の解説】
A「飲酒の禁止」: ビール350mLを週2回は節度ある適度な飲酒の範囲内で、禁止する必要はない。
C「体重の減量」: BMI22.0は標準体重であり、減量の対象にならない。
D「食塩摂取の制限」: 食塩摂取量5.5g/日は高血圧の食事療法で目標とする6g/日未満をすでに満たしている。
E「野菜摂取の制限」: 野菜はカリウムや食物繊維の供給源として摂取が勧められる。制限する理由はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C042（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-44', '正答は D「アルギニン負荷試験」。

6歳女児の乳房発育と身長・体重の促進から思春期早発症を疑う。原因検索には頭蓋内病変を除くMRI、卵巣・副腎腫瘍を除く腹部超音波検査、骨年齢の評価が要る。アルギニン負荷試験は成長ホルモンの分泌不全を調べる検査で、成長が促進している本例では必要がない。

【誤答選択肢の解説】
A「頭部MRI」: 中枢性思春期早発症の原因となる視床下部・下垂体の器質性病変を除外するために行う。
B「成長曲線の確認」: 成長速度の変化がいつから起きたかを知るために不可欠である。
C「腹部超音波検査」: 卵巣腫瘍や副腎腫瘍などエストロゲン産生源の検索、子宮・卵巣の成熟度の評価に有用である。
E「手根骨エックス線撮影」: 手根骨エックス線撮影で骨年齢を評価すると、暦年齢を上回る骨成熟の進行を確認できる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C044（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-45', '正答は C「気管挿管」。

灯油(炭化水素)を飲んでおり、意識レベルはJCS III-100で気道保護反射が失われ、酸素投与下でもSpO2 88%と誤嚥による化学性肺炎が進行している。まず気管挿管により気道を確保し、換気と酸素化を立て直す。

【誤答選択肢の解説】
A「胃洗浄」: 石油製品は誤嚥すると重篤な化学性肺炎を起こすため、胃洗浄は禁忌である。行うとしても気道確保の後になる。
B「血液透析」: 炭化水素は分布容積が大きく脂溶性が高いため血液透析では除去できない。
D「大量輸液」: 血圧は保たれており、大量輸液を要する循環不全はない。
E「高気圧酸素治療」: 高気圧酸素治療は一酸化炭素中毒などの適応で、気道が確保されていない本例では行えない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C045（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-46', '正答は D「弁護士を代理人として行うことができる。」。

退院請求は入院中の本人または家族等が、都道府県知事に対して退院や処遇改善を求める制度である。本人が直接行うほか、弁護士など代理人を通じて行うこともできる。請求を受けると精神医療審査会が入院の必要性を審査する。

【誤答選択肢の解説】
A「病院長の許可が必要である。」: 病院長の許可は要らない。病院を介さずに請求できることが制度の要点である。
B「口頭では行うことができない。」: 書面によるのが原則だが、電話や口頭による請求も受け付けられる。
C「閉鎖病棟入院中でなければ行えない。」: 閉鎖病棟か開放病棟かを問わず、入院形態にかかわらず行える。
E「両親ともに同意している医療保護入院では行えない。」: 医療保護入院は本人の同意によらない入院であり、まさに退院請求の対象となる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C046（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-48', '正答は B「心拍動を認める胎芽」。

最終月経が1月1日なので、3月7日は妊娠9週2日にあたる。胎囊は妊娠5週ごろ、胎芽と心拍動は妊娠6週ごろに確認できるので、この時期には心拍動のある胎芽(胎児)が見える。

【誤答選択肢の解説】
A「胎囊のみ」: 胎囊のみが見えるのは妊娠5週前後で、9週で心拍動が確認できないのは流産を疑う所見である。
C「木の葉状の子宮内膜像」: 木の葉状の子宮内膜像は排卵期にみられる非妊娠時の所見である。
D「頭殿長〈CRL〉3.0cmの胎児」: 頭殿長3.0cmとなるのは妊娠10週前後を過ぎてからで、この時期にはやや大きすぎる。
E「児頭大横径〈BPD〉3.0cmの胎児」: 児頭大横径が測定できるようになるのは妊娠12週以降で、3.0cmは妊娠20週前後の大きさである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C048（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-5', '正答は D「療養期」。

病床機能報告では、医療機関が病棟ごとに高度急性期・急性期・回復期・慢性期の4区分から機能を選んで都道府県に報告する。「療養期」という区分はない。長期療養を担う病床は慢性期に含まれる。

【誤答選択肢の解説】
A「高度急性期」: 高度急性期は診療密度が特に高い医療を提供する機能で、区分に含まれる。
B「急性期」: 急性期は急性期の患者に医療を提供する機能で、区分に含まれる。
C「回復期」: 回復期は在宅復帰に向けた医療やリハビリテーションを提供する機能で、区分に含まれる。
E「慢性期」: 慢性期は長期にわたり療養が必要な患者を入院させる機能で、区分に含まれる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-50', '正答は E「全身性エリテマトーデス」。

若年女性の多発関節痛に、脱毛、口腔粘膜のびらん、凍瘡様皮疹、蛋白尿と変形赤血球を伴う血尿、白血球減少と血小板減少がそろっており全身性エリテマトーデスである。CRPが上昇しないのに発熱するという解離、APTT延長(ループスアンチコアグラント)も本症を支持する。

【誤答選択肢の解説】
A「皮膚筋炎」: 皮膚筋炎ではGottron徴候やヘリオトロープ疹と近位筋の筋力低下を伴い、CKが上昇する。CK26U/Lは合わない。
B「Behçet病」: Behçet病は口腔内アフタ、外陰部潰瘍、ぶどう膜炎、結節性紅斑を主症状とし、腎障害や血球減少は前面に出ない。
C「関節リウマチ」: 関節リウマチは持続する滑膜炎による関節破壊が主体で、蛋白尿や血球減少、粘膜疹は説明できない。
D「Sjögren症候群」: Sjögren症候群は乾燥症状が中心で、全身性エリテマトーデスに合併することはあるが本例の多彩な症状の主因とはいえない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C050（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-51', '正答は A「1」。

3歳では手すりを使って交互に足を出しながら階段を昇れるのが標準で、ひとりで階段を昇れないのは粗大運動の遅れを疑う。ほかの下線部はいずれも3歳としてふつうにみられる発達段階である。

【誤答選択肢の解説】
B「2」: 上着を自分で着られるようになるのは4歳ごろで、3歳で脱ぐだけできるのは正常である。
C「3」: ルールのある遊びができるようになるのは4〜5歳ごろで、3歳では並行遊びから連合遊びの段階である。
D「4」: 住所を言えるようになるのは5歳前後で、3歳で名前が言えれば正常である。
E「5」: 左右の区別がつくのは5〜6歳ごろで、3歳でわからないのは正常である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C051（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-52', '正答は E「5」。

ICFの生活機能は心身機能・身体構造、活動、参加の3つからなり、参加は仕事、家庭内での役割、地域社会との関わりなど生活・人生場面へのかかわりを指す。近所付き合いがないことは地域社会への参加の状況を表している。

【誤答選択肢の解説】
A「1」: 脳出血という病気は健康状態であって、生活機能の3要素には含まれない。
B「2」: 運動麻痺は心身機能の障害(機能障害)にあたる。
C「3」: 過疎地域に住んでいることは環境因子にあたる。
D「4」: 妻と2人暮らしという家族の状況も環境因子にあたる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C052（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-53', '正答は D「「作業場の室温を下げるようにしましょう」」。

空調のない閉め切った室内での作業中に大量発汗、めまい、頭痛が生じており熱中症(I度)である。作業環境そのものが原因なので、室温を下げて暑熱環境を改善することが最も本質的な対策になる。肥満と睡眠不足はいずれも熱中症の危険因子である。

【誤答選択肢の解説】
A「「今後は縫製作業を控えましょう」」: 作業自体をやめる必要はない。環境の改善と水分・塩分の補給、休憩で予防できる。
B「「肥満と症状は関係ないでしょう」」: 肥満は熱の産生が多く放散が悪いため熱中症の危険因子であり、関係がないとはいえない。
C「「寝不足と症状は関係ないでしょう」」: 睡眠不足は体調不良として熱中症の危険因子に挙げられており、関係がないとはいえない。
E「「のどが渇いていなければ水分を摂る必要はないでしょう」」: 高齢者や作業中は口渇を自覚しにくい。渇きを感じる前から計画的に水分と塩分を摂る必要がある。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C053（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-57', '正答は E「陰茎」。

喫煙と飲酒はいずれも上気道から上部消化管の扁平上皮を広く傷害するため、口腔・咽頭・喉頭・食道・肺に重複癌が生じやすい(field cancerization)。陰茎癌はヒトパピローマウイルス感染や包茎が主な危険因子で、喫煙・飲酒による重複癌としては可能性が低い。

【誤答選択肢の解説】
A「口腔」: 口腔は喫煙と飲酒が直接作用する扁平上皮で、重複癌の好発部位である。
B「下咽頭」: 下咽頭癌は喉頭癌・食道癌との重複が特に多いことで知られる。
C「肺」: 肺は喫煙による最大の標的臓器で、重複癌の頻度が高い。
D「食道」: 食道扁平上皮癌は喫煙と飲酒が二大危険因子で、頭頸部癌との重複が多い。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C057（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-6', '正答は E「アルマ・アタ宣言」。

アルマ・アタ宣言(1978年、WHOとUNICEF)は「すべての人々に健康を」を掲げ、住民の主体的な参加と地域資源の活用によって基本的な保健医療を提供するプライマリヘルスケアの理念を打ち出した。

【誤答選択肢の解説】
A「オタワ憲章」: オタワ憲章(1986年)はヘルスプロモーションを「人々が自らの健康をコントロールし改善できるようにするプロセス」と定義した。
B「アデレード宣言」: アデレードでの会議は健康的な公共政策づくりを主題としたヘルスプロモーションの国際会議である。
C「ジュネーブ宣言」: ジュネーブ宣言は医師の職業倫理の誓いを現代の言葉に改めたものである。
D「ヘルシンキ宣言」: ヘルシンキ宣言は人を対象とする医学研究の倫理原則を定めたものである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-7', '正答は E「シュレッダー処理された書類」。

事業活動に伴って生じる廃棄物のうち、法令で定める20種類が産業廃棄物である。紙くずは建設業や印刷業など特定の業種から出たものだけが産業廃棄物になるため、医療機関から出る書類は事業系一般廃棄物として扱う。

【誤答選択肢の解説】
A「使用済みメス」: 使用済みメスは血液が付着した鋭利な器材で、感染性産業廃棄物として処理する。
B「未使用注射針」: 未使用でも注射針は鋭利な金属くずであり、産業廃棄物として専用容器で処理する。
C「アルコール試薬」: アルコール試薬は廃アルコール類として産業廃棄物にあたる。
D「使用済みゴム手袋」: 使用済みゴム手袋はゴムくず・廃プラスチック類にあたり、感染性であればなお産業廃棄物として処理する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-C-9', '正答は C「C」。

Cは2013年に14,344人と突出し、2018〜2019年にも2,000人を超える流行を示している。成人男性を中心とした大規模流行が2013年と2018年に起きた風疹の推移に一致する。

【誤答選択肢の解説】
A「A」: 827人から7,007人へ一貫して増え続けており、近年急増している梅毒である。
B「B」: 毎年1,000〜1,600人前後で緩やかに減少しており、新規報告数が横ばいの後天性免疫不全症候群である。
D「D」: 数十人から数百人の間で増減し2019年に744人と近年最多となっており、麻疹である。
E「E」: 2011〜2013年に報告がなく2014年から十数〜数十人で推移しており、2014年に五類全数把握疾患に追加された薬剤耐性アシネトバクター感染症である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 C009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-10', '正答は B「骨盤骨折」。

骨盤骨折では後腹膜腔に大量の出血をきたし、循環血液量の半分近くを失うこともある。後腹膜は圧迫止血が効きにくく死因になりやすいので、骨盤輪の不安定性を認めたら骨盤固定具を装着し、輸血と経カテーテル動脈塞栓術を早期に考える。

【誤答選択肢の解説】
A「頸椎捻挫」: 頸椎捻挫は軟部組織の損傷が主で、大量出血はきたさない。
C「肩関節脱臼」: 肩関節脱臼は整復を要するが、出血性ショックの原因にはならない。
D「橈骨遠位端骨折」: 橈骨遠位端骨折は開放骨折でなければ出血量は限られる。
E「膝前十字靱帯損傷」: 膝前十字靱帯損傷は関節血症をきたすが、循環に影響する量ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-13', '正答は D「速やかなAEDの使用が予後改善に有効である。」。

心臓振盪は、心室の受攻期(T波の上行脚)にあたる瞬間に前胸部へ衝撃が加わり、心室細動が誘発される病態である。ただちに胸骨圧迫を始め、AEDによる除細動を行えれば救命でき、予後を大きく左右する。

【誤答選択肢の解説】
A「高齢者での報告例が多い。」: 胸郭が柔らかく衝撃が心臓に伝わりやすい小児・若年者に多い。
B「死亡に至ることはまれである。」: 除細動が遅れれば致死的で、死亡例も多い。
C「受傷後、1週間前後に心停止が生じる。」: 受傷直後に心室細動が生じるものであり、時間をおいて起こるものではない。
E「迷走神経反射から生じる洞性徐脈が原因である。」: 機序は心室細動であって、迷走神経反射による洞性徐脈ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D013（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-14', '正答は E「母指から環指橈側の感覚障害」。

手根管症候群は横手根靱帯の下で正中神経が絞扼される病態で、母指・示指・中指と環指の橈側半分にしびれと感覚障害をきたす。進行すると母指球筋が萎縮して母指の対立が困難になる。夜間から明け方に悪化するのが特徴である。

【誤答選択肢の解説】
A「頸部痛」: 頸部痛は頸椎症性神経根症など頸部由来の病変を示唆する。手根管症候群では生じない。
B「小指球筋の萎縮」: 小指球筋の萎縮は尺骨神経麻痺による。手根管症候群では母指球筋が萎縮する。
C「手関節の背屈困難」: 手関節の背屈困難(下垂手)は橈骨神経麻痺による。
D「腕橈骨筋反射の亢進」: 末梢神経の絞扼であり深部腱反射は亢進しない。亢進は中枢性の障害を示す。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D014（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-15', '正答は B「炭酸リチウム」。

炭酸リチウムは有効域が狭く腎から排泄されるため、血中濃度の上昇による中毒と、長期投与による腎性尿崩症や慢性間質性腎炎をきたしやすい。定期的な血中濃度測定と腎機能の監視が要る。

【誤答選択肢の解説】
A「スタチン」: スタチンの主な有害事象は横紋筋融解症と肝障害で、それに伴わない腎障害の頻度は高くない。
C「塩酸メトホルミン」: メトホルミンは腎排泄されるため腎機能低下時には減量・中止するが、薬剤自体が腎障害を起こすわけではない。問題となるのは乳酸アシドーシスである。
D「カルシウム拮抗薬」: カルシウム拮抗薬は腎障害を起こしにくく、腎機能低下例でも使いやすい降圧薬である。
E「副腎皮質ステロイド」: 副腎皮質ステロイドの主な有害事象は易感染性、糖尿病、骨粗鬆症などで、腎障害は主要な問題ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D015（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-16', '正答は D「副腎皮質ステロイド」。

中年女性の急性肝炎様の経過で、肝炎ウイルスマーカーがすべて陰性、IgG 3,131mg/dLと高値、抗核抗体640倍陽性、肝生検で門脈域に形質細胞を含む単核球浸潤を認めており自己免疫性肝炎である。副腎皮質ステロイドが第一選択で、反応も良好なことが多い。

【誤答選択肢の解説】
A「グリチルリチン」: グリチルリチンは肝庇護薬で、炎症を抑える主たる治療にはならない。
B「インターフェロン」: インターフェロンはウイルス性肝炎に用いる。自己免疫性肝炎では病態を悪化させうる。
C「核酸アナログ製剤」: 核酸アナログ製剤はB型肝炎の治療薬で、HBs抗原陰性の本例には適応がない。
E「直接作用型抗ウイルス薬〈direct acting antivirals〉」: 直接作用型抗ウイルス薬はC型肝炎の治療薬で、HCV-RNA陰性の本例には適応がない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D016（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-19', '正答は E「アニオンギャップの増加」。

ビグアナイド薬を内服する腎機能低下例(クレアチニン2.0mg/dL)で、多量飲酒を契機に意識障害と血圧低下、呼吸数28/分のKussmaul呼吸をきたしている。血糖128mg/dLと高くないので、乳酸アシドーシスである。乳酸という測定されない陰イオンが増えるためアニオンギャップが開大する。

【誤答選択肢の解説】
A「食後の低血糖」: ビグアナイド薬は単独では低血糖を起こしにくく、血糖128mg/dLは低血糖ではない。
B「呼気のアセトン臭」: 尿ケトン体陰性であり、ケトン体による呼気のアセトン臭はきたさない。
C「呼吸性アシドーシス」: 頻呼吸による代償が働いておりPaCO2はむしろ低下する。呼吸性アシドーシスではない。
D「代謝性アルカローシス」: 代謝性アシドーシスであって、アルカローシスではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-2', '正答は B「ベラパミル」。

ベラパミルは非ジヒドロピリジン系カルシウム拮抗薬で陰性変力作用が強く、左室駆出率の低下した心不全では心収縮力をさらに落として増悪させるため使用しない。ジルチアゼムやシベンゾリンなども同じ理由で避ける。

【誤答選択肢の解説】
A「スタチン」: スタチンは心不全を悪化させない。動脈硬化性疾患の二次予防に用いる。
C「ACE阻害薬」: ACE阻害薬は左室駆出率の低下した心不全の予後を改善する基本薬である。
D「SGLT2阻害薬」: SGLT2阻害薬は左室駆出率にかかわらず心不全の予後を改善することが示され、標準治療に組み込まれている。
E「プロトンポンプ阻害薬」: プロトンポンプ阻害薬は心収縮力に影響しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-20', '正答は E「血管透過性亢進」。

採卵後に両側卵巣が10cmに腫大し、腹水と血液濃縮(Ht51%)、凝固亢進を伴っており卵巣過剰刺激症候群である。血管内皮増殖因子などにより血管透過性が亢進して血漿成分が血管外へ漏出し、腹水貯留と循環血漿量減少が同時に起こる。血栓症を警戒する。

【誤答選択肢の解説】
A「腹膜炎」: 発熱や腹膜刺激徴候はなく、腹部は軟である。腹膜炎を示す所見に乏しい。
B「右心不全」: 心エコー検査で異常を認めず、頸静脈怒張もない。右心不全は否定的である。
C「腎機能障害」: クレアチニン0.81mg/dLと腎機能は保たれている。
D「門脈圧亢進」: 肝疾患を示す所見はなく、門脈圧亢進を疑わせる脾腫や側副血行路も認めない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D020（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-22', '正答は D「Romberg徴候が陽性である。」。

胃全摘後10年でMCV114fLの大球性貧血をきたしており、内因子の欠乏によるビタミンB12欠乏症である。脊髄後索が侵されて深部感覚が障害されるため、暗所や閉眼で身体の動揺が強まるRomberg徴候が陽性となる(亜急性連合性脊髄変性症)。

【誤答選択肢の解説】
A「側方注視時に左右に分離する複視を認める。」: 核間性眼筋麻痺は多発性硬化症などでみられる。ビタミンB12欠乏症の典型所見ではない。
B「鼻指鼻試験で測定障害を呈する。」: 鼻指鼻試験の測定障害は小脳性の運動失調を示す。本症の失調は後索障害による感覚性である。
C「上肢Barré徴候が陽性である。」: 上肢Barré徴候は錐体路障害による軽度の片麻痺をみる検査で、頭部MRIに異常のない本例では陽性にならない。
E「アキレス腱反射が亢進する。」: 側索の障害で腱反射が亢進することもあるが、末梢神経障害を合併してアキレス腱反射はむしろ低下・消失することが多い。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-23', '正答は B「アデノウイルス」。

発熱、咽頭炎、結膜炎の3つがそろう咽頭結膜熱(プール熱)で、原因はアデノウイルスである。夏に流行し、迅速抗原検査で診断できる。学校保健安全法では主要症状が消退して2日を経過するまで出席停止となる。

【誤答選択肢の解説】
A「麻疹ウイルス」: 麻疹では頰粘膜にKoplik斑が出現し、その後に全身の発疹をみる。白斑も皮疹も認めない。
C「パルボウイルスB19」: パルボウイルスB19による伝染性紅斑では頰の紅斑が特徴だが、皮疹を認めない。
D「コクサッキーウイルス」: コクサッキーウイルスによるヘルパンギーナや手足口病では口腔内に水疱を認めるが、水疱はない。
E「単純ヘルペスウイルス」: 単純ヘルペスウイルスによる歯肉口内炎では歯肉腫脹と口腔内の水疱・潰瘍をみるが、いずれも認めない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D023（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-24', '正答は E「von Willebrand病」。

乳児期からの鼻出血と皮下出血に、出血時間の延長とAPTTの延長が併存し、血小板数と血小板凝集能は正常で、父親にも出血傾向がある。von Willebrand因子の異常により血小板粘着障害と第VIII因子の減少が同時に起こるvon Willebrand病である。常染色体顕性遺伝が多い。

【誤答選択肢の解説】
A「血友病A」: 血友病AはX連鎖潜性遺伝で男児に発症し、APTTは延長するが出血時間は正常で、関節内出血が主となる。父から息子へは遺伝しない。
B「単純性紫斑」: 単純性紫斑は若い女性の下肢にみられる軽微な紫斑で、凝固検査に異常はない。
C「血小板無力症」: 血小板無力症ではADPによる血小板凝集能が欠如する。凝集能は正常である。
D「ビタミンK欠乏症」: ビタミンK欠乏症ではプロトロンビン時間が延長する。PT-INR1.0と正常である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-26', '正答は E「抗アルドステロン薬」。

慢性腎臓病の患者に抗アルドステロン薬が投与され、K6.5mEq/Lの高カリウム血症をきたしている。抗アルドステロン薬は集合管でのカリウム排泄を抑えるため、腎機能低下例では高カリウム血症の最大の原因になる。ただちに中止し、心電図を確認して治療する。

【誤答選択肢の解説】
A「スルホニル尿素薬」: スルホニル尿素薬の問題は低血糖で、血清カリウムは上げない。
B「DPP-4阻害薬」: DPP-4阻害薬はカリウムに影響しない。
C「SGLT2阻害薬」: SGLT2阻害薬は尿糖排泄を促し、脱水には注意を要するが高カリウム血症の原因にはならない。
D「カルシウム拮抗薬」: カルシウム拮抗薬は血清カリウムに影響しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D026（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-28', '正答は D「ビタミンB12」。

新生児期に広範な小腸切除を受け、回腸末端が失われている。ビタミンB12は内因子と結合して回腸末端で吸収されるため、体内の貯蔵が尽きる数年後に欠乏し、MCV111fLの大球性貧血をきたす。経口では補えないので非経口的に投与する。

【誤答選択肢の解説】
A「ビタミンA」: ビタミンA欠乏では夜盲や眼球乾燥をきたすが、貧血の原因にはならない。
B「ビタミンC」: ビタミンC欠乏(壊血病)では出血傾向と歯肉出血をきたす。出血時間は正常で紫斑もない。
C「ビタミンB1」: ビタミンB1欠乏では脚気や Wernicke脳症をきたす。大球性貧血は説明できない。
E「ビタミンK」: ビタミンK欠乏ではプロトロンビン時間が延長する。PT-INR1.0と正常である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D028（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-35', '正答は B「Tourette症候群」。

幼児期に始まった多彩な運動チックと音声チックが1年以上続いており、Tourette症候群である。単純チックから複雑チックへ広がり、汚言症を伴うこともある。多くは年齢とともに軽快するが、生活への支障が大きければ薬物療法を検討する。

【誤答選択肢の解説】
A「分離不安症」: 分離不安症は愛着対象から離れることへの過度の不安が主症状で、チックは伴わない。
C「自閉スペクトラム症」: 自閉スペクトラム症は社会的コミュニケーションの障害と限定的な興味・常同行動が幼児期から続く。音声チックや汚言症は中核症状ではない。
D「吃音症〈小児期発症流暢症〉」: 吃音症は語の反復や引き伸ばしなど発話の流暢性の障害で、運動チックを伴わない。
E「注意欠陥多動障害〈ADHD〉」: 注意欠陥多動障害は不注意・多動・衝動性が中心で、チックを合併することはあるが本例の中核ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D035（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-37', '正答は D「血清K値」。

糖尿病性ケトアシドーシスである。インスリンを投与するとカリウムが細胞内へ移動するため、初期には正常〜高値であった血清カリウムが治療開始後数時間で急速に低下する。心電図監視のもとでカリウムを補充しながら治療する。

【誤答選択肢の解説】
A「血圧」: 生理食塩液で循環血漿量が回復するため、血圧はむしろ上昇する。
B「HbA1c値」: HbA1cは過去1〜2か月の平均血糖を反映するので、数時間では変化しない。
C「血清Na値」: 高血糖による偽性低ナトリウム血症が是正され、血清ナトリウムはむしろ上昇する。
E「血清Cl値」: 生理食塩液には塩素が多く含まれるため、血清塩素はむしろ上昇する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D037（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-39', '正答は C「薬剤リンパ球刺激試験」。

サプリメント摂取後に生じた肝障害で、ウイルス性・自己免疫性のマーカーがすべて陰性、末梢血の好酸球が12%と増加している。薬物性肝障害を疑う状況であり、原因物質に対するリンパ球の反応をみる薬剤リンパ球刺激試験が診断の一助となる。

【誤答選択肢の解説】
A「ICG試験」: ICG試験は肝の予備能をみる検査で、原因の特定には役立たない。
B「尿素呼気試験」: 尿素呼気試験はHelicobacter pylori感染の診断に用いる。
D「α1-アンチトリプシン法」: α1-アンチトリプシン法は蛋白漏出性胃腸症で消化管への蛋白漏出をみる検査である。
E「経口グルコース負荷試験〈75gOGTT〉」: 75gOGTTは耐糖能の評価に用いる。血糖96mg/dLで糖代謝の問題はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D039（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-4', '正答は E「新規に透析を導入する原因疾患として患者数が増加傾向である。」。

腎硬化症は高血圧が続くことで細動脈の硬化と糸球体の虚血をきたす病態で、高齢化に伴い透析導入原因の第3位を占め、その割合は増加傾向にある。糖尿病性腎症が第1位、慢性糸球体腎炎が第2位である。

【誤答選択肢の解説】
A「初期から尿に赤血球円柱が出現する。」: 赤血球円柱は糸球体腎炎に特徴的な所見で、腎硬化症では尿沈渣に乏しいのがふつうである。
B「しばしばネフローゼ症候群を呈する。」: 蛋白尿は軽度にとどまることが多く、ネフローゼ症候群を呈することはまれである。
C「140/90mmHg以下の降圧は推奨されない。」: 厳格な降圧が腎機能低下の進行を抑えるため、130/80mmHg未満を目標とする降圧が推奨される。
D「レニン・アンジオテンシン系抑制薬は禁忌である。」: レニン・アンジオテンシン系抑制薬は蛋白尿を伴う場合に有用で、禁忌ではない。両側腎動脈狭窄など個別の禁忌があるにすぎない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-40', '正答は D「「アドレナリン自己注射製剤を携帯しましょう」」。

小麦の摂取と運動が重なったときだけ症状が出る食物依存性運動誘発アナフィラキシーである。原因食物を食べた後4時間程度は運動を避けるのが基本で、それでも発症しうるため、アドレナリン自己注射製剤を携帯し、学校とも対応を共有しておく。

【誤答選択肢の解説】
A「「運動をしてはいけません」」: 小麦を食べていなければ運動できるので、運動そのものを禁じる必要はない。
B「「小麦の完全除去が必要です」」: 完全除去まではせず、運動の前に摂らないという形で管理する。成長期の子どもに不要な除去は望ましくない。
C「「抗ヒスタミン薬を登校前に服用してください」」: 抗ヒスタミン薬の予防内服でアナフィラキシーは防げない。
E「「運動前にβ2刺激薬を吸入すれば問題ありません」」: β2刺激薬は気管支収縮を緩めるだけで、循環虚脱を伴うアナフィラキシーには対応できない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D040（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-41', '正答は C「フェリチン」。

夕方に上がるスパイク状の弛張熱、解熱とともに消えるサーモンピンクの紅斑、関節炎、リンパ節腫脹、著明な白血球増多と好中球優位、リウマトイド因子と抗核抗体陰性がそろっており成人Still病である。血清フェリチンの著増が診断を支持する。

【誤答選択肢の解説】
A「第XIII因子」: 第XIII因子は凝固の最終段階でフィブリンを架橋する因子で、欠乏すると創傷治癒の遅延や遅発性の出血をきたす。本症の評価には用いない。
B「HLA-B51」: HLA-B51はBehçet病との関連が知られる。口腔内アフタや陰部潰瘍は認めない。
D「ハプトグロビン」: ハプトグロビンは溶血性貧血で低下する指標で、貧血のない本例では意味をなさない。
E「血清アミロイドA」: 血清アミロイドAは炎症の指標にすぎず、成人Still病に特徴的ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D041（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-42', '正答は A「座位訓練」。

発症5日目で神経徴候が悪化せず、背もたれを90度にしても血圧が下がらないことを確認できている。全身状態が安定した時点で座位を保つ訓練から始め、廃用症候群を防ぎつつ段階的に離床を進める。

【誤答選択肢の解説】
B「右手での書字訓練」: 右上下肢が麻痺側であり、この時期に麻痺側手指での書字は行えない。
C「左上肢の他動可動域訓練」: 他動可動域訓練が要るのは麻痺側の右上肢である。左上下肢の筋力は5で正常である。
D「歩行器使用での歩行訓練」: 右下肢は股関節屈曲1、膝伸展0、足関節背屈0で、歩行器を用いても歩行訓練は行えない。
E「手すりを使用しての階段昇降訓練」: 階段昇降は座位・立位の安定を確認したのちの段階で、現時点では時期尚早である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D042（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-43', '正答は E「副腎皮質ステロイド薬の投与」。

貧血に間接ビリルビン優位の黄疸、網赤血球増加、LD上昇、ハプトグロビン著減がそろい、直接Coombs試験が陽性であることから自己免疫性溶血性貧血である。温式では副腎皮質ステロイドが第一選択で、多くが反応する。

【誤答選択肢の解説】
A「脾臓の摘出」: 脾摘はステロイドが無効または減量できない場合の二次的な選択肢である。
B「造血幹細胞移植」: 造血幹細胞移植は本症の初期治療にはならない。
C「抗C5抗体の投与」: 抗C5抗体(エクリズマブ)は発作性夜間ヘモグロビン尿症に用いる。直接Coombs試験は陰性となる。
D「抗CD20抗体の投与」: 抗CD20抗体(リツキシマブ)はステロイド抵抗例に用いる二次治療である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D043（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-49', '正答は A「血糖測定」。

母体の妊娠糖尿病により胎児が高インスリン血症となり、出生後に糖の供給が絶たれて低血糖に陥る。体重4,100gの巨大児であることもそれを裏づける。無症候のこともあるので、ただちに血糖を測定して補正する。

【誤答選択肢の解説】
B「心エコー検査」: 糖尿病母体児では肥大型心筋症の合併もありうるが、心音に異常がなく呼吸循環も安定しており緊急性がない。
C「頭部超音波検査」: 頭部超音波検査は頭蓋内出血を疑うときに行うもので、神経学的異常を認めない本例では優先度が低い。
D「ビリルビン測定」: 生後1時間で黄疸は問題にならない。ビリルビンの評価は日齢が進んでからである。
E「胸部エックス線検査」: 呼吸数50/分、SpO2 98%、呼吸音も正常で、呼吸障害を示す所見がない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D049（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-54', '正答は D「「子宮頸部細胞診を半年後に行いましょう」」。

軽度異形成(CIN1)の多くは自然に消退するため、ただちに治療せず細胞診による経過観察を行う。6か月ごとの細胞診とコルポスコピィで、高度化しないかを確かめていく。

【誤答選択肢の解説】
A「「MRI検査を行いましょう」」: MRIは浸潤癌の進行度診断に用いるもので、上皮内にとどまる病変には不要である。
B「「円錐切除術を行いましょう」」: 円錐切除術は高度異形成(CIN3)や上皮内癌、微小浸潤癌が適応で、CIN1には過剰な治療である。早産の危険も高まる。
C「「抗ウイルス薬を内服しましょう」」: HPV感染そのものに有効な抗ウイルス薬はない。
E「「ヒトパピローマウイルス〈HPV〉ワクチンで治療をしましょう」」: HPVワクチンは感染の予防のためのもので、すでに生じた病変を治療する効果はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D054（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-58', '正答は A「KL-6低下」。

夏季に繰り返し、入院して原因環境から離れると治療なしに軽快する経過と、両側のfine cracklesおよび小葉中心性陰影から夏型過敏性肺炎である。間質の障害を反映してKL-6はむしろ上昇するので、低下という記載が誤りである。

【誤答選択肢の解説】
B「拘束性換気機能障害」: 間質性肺疾患では肺が硬くなり、肺活量が低下する拘束性換気機能障害を示す。
C「ツベルクリン反応陰転化」: ツベルクリン反応の陰転化はサルコイドーシスなど細胞性免疫の変化を反映する所見で、過敏性肺炎でもみられうる。
D「抗Trichosporon asahii抗体陽性」: 夏型過敏性肺炎の原因抗原はTrichosporon asahiiで、その抗体が陽性となる。
E「気管支肺胞洗浄液中CD4/CD8比低下」: 気管支肺胞洗浄液ではリンパ球が増加し、CD8陽性細胞が優位となってCD4/CD8比が低下する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D058（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-6', '正答は D「妊娠高血圧症候群の高リスクである。」。

抗リン脂質抗体症候群は動静脈血栓症と習慣流産をきたす自己免疫疾患で、妊娠高血圧症候群や胎児発育不全、常位胎盤早期剝離の高リスクである。妊娠中は低用量アスピリンとヘパリンの併用で管理する。

【誤答選択肢の解説】
A「血小板が増加する。」: 血小板はしばしば減少する。増加はしない。
B「永続的な妊娠の禁止を要する。」: 妊娠は禁止されない。適切な抗凝固療法のもとで妊娠・出産が可能である。
C「プロトロンビン時間が短縮する。」: ループスアンチコアグラントの影響でAPTTが延長する。プロトロンビン時間の短縮は特徴ではない。
E「副腎皮質ステロイドが第一選択薬である。」: 第一選択は抗血小板薬と抗凝固薬による血栓予防である。副腎皮質ステロイドは基礎疾患がある場合などに限られる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-60', '正答は D「4」。

子宮体部の癌肉腫は骨盤への放射線照射から10年以上を経て発生する二次発癌として知られる。45歳時の根治的放射線治療が最も関連が深い。

【誤答選択肢の解説】
A「1」: 胞状奇胎は絨毛性疾患で、続発するのは侵入奇胎や絨毛癌である。子宮体部の癌肉腫とは結びつかない。
B「2」: HPV感染は子宮頸部の扁平上皮癌の原因で、子宮体部の癌肉腫の原因にはならない。
C「3」: 抗癌薬も二次発癌の原因になりうるが、この部位・組織型では放射線の関与のほうが強い。
E「5」: ビスホスホネート製剤の代表的な有害事象は顎骨壊死と非定型大腿骨骨折で、発癌との関連はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D060（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-64', '正答は D「関節液培養」。

人工股関節置換術から7年を経て、発熱、局所の腫脹・熱感・発赤、白血球増多とCRP上昇、インプラントのゆるみを認めており人工関節感染を疑う。起因菌と感受性を確かめるため、抗菌薬を始める前に関節液を穿刺して培養に出す。

【誤答選択肢の解説】
A「副腎皮質ステロイド関節内注入」: 感染が疑われる関節への副腎皮質ステロイド注入は感染を悪化させるため禁忌である。
B「下肢持続牽引」: 牽引は感染の診断にも治療にもならない。
C「可動域訓練」: 可動域訓練は感染の制御がついてから考えるもので、この時点で優先されない。
E「ギプス固定」: ギプス固定では感染巣は治らず、原因の究明にもならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D064（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-66', '正答は D「鉄キレート剤の投与」。

4年にわたる頻回の赤血球輸血でフェリチン2,500ng/mL、血清鉄250μg/dL、皮膚の色素沈着、肝のCT値上昇を認め、輸血後鉄過剰症である。鉄キレート剤を投与して臓器への鉄沈着を減らす。

【誤答選択肢の解説】
A「瀉血」: Hb5.8g/dLの高度貧血があり、瀉血は行えない。瀉血が選べるのはヘモクロマトーシスで貧血のない場合である。
B「肝移植」: 肝機能は保たれており、肝移植の適応ではない。
C「造血幹細胞移植」: 75歳で高度の血球減少があり、造血幹細胞移植の適応にならない。
E「エリスロポエチン製剤の投与」: 再生不良性貧血は造血幹細胞そのものの減少によるため、エリスロポエチン製剤は無効である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D066（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-67', '正答は D「高二酸化炭素血症」。

RSウイルスによる細気管支炎である。細気管支の狭窄で呼気が妨げられ、換気が保てなくなると二酸化炭素が貯留する。陥没呼吸とチアノーゼを認め呼吸数60/分と努力呼吸が続いており、呼吸不全への進行を高二酸化炭素血症で捉える。

【誤答選択肢の解説】
A「血小板数減少」: 血小板数の減少はきたさない。
B「血清IgE高値」: 初回の細気管支炎でIgEが高値になるとは限らない。喘息の発症と関連づけられることはあるが検査所見としては予測できない。
C「好中球核左方移動」: ウイルス感染であり、好中球の核左方移動は起こりにくい。
E「胸部エックス線写真の肺浸潤影」: 細気管支の閉塞による過膨脹が主で、肺浸潤影ではなく肺野の透過性亢進を示すことが多い。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D067（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-68', '正答は E「ニューキノロン系抗菌薬が第一選択薬である。」。

膿性の尿道分泌物にGram陰性双球菌を認め淋菌性尿道炎である。淋菌はニューキノロン系への耐性率が高く第一選択にならない。第一選択はセフトリアキソンの単回静注である。

【誤答選択肢の解説】
A「咽頭炎の原因となる。」: オーラルセックスにより淋菌性咽頭炎を生じる。無症状のことが多く、感染源となる。
B「クラミジアとの混合感染がある。」: クラミジアとの混合感染が20〜30%にみられるため、同時に治療することが多い。
C「診断にはPCR検査が有用である。」: 核酸増幅検査(PCR)は感度が高く、咽頭や尿検体でも診断に有用である。
D「女性では骨盤炎症性疾患の原因となる。」: 女性では上行感染により骨盤内炎症性疾患を起こし、不妊や子宮外妊娠の原因となる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D068（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-8', '正答は B「母乳栄養」。

母乳栄養は腸管の免疫を助け、壊死性腸炎の発症を減らすことが知られている。発症要因ではなくむしろ予防因子である。腸管の未熟性を背景に、虚血と細菌の異常増殖、経腸栄養の負荷が重なって発症する。

【誤答選択肢の解説】
A「敗血症」: 敗血症は循環不全と炎症を介して腸管の虚血を招き、発症要因となる。
C「低酸素血症」: 低酸素血症は腸管の血流低下をきたし、発症要因となる。
D「低出生体重」: 低出生体重、とくに極低出生体重児は腸管が未熟で最大の危険因子である。
E「動脈管開存」: 動脈管開存では拡張期に腸管への血流が奪われ(steal現象)、腸管虚血をきたす。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-D-9', '正答は E「アキレス腱の肥厚」。

家族性高コレステロール血症では、高LDLコレステロール血症、腱黄色腫、家族歴の3つが診断の柱になる。なかでもアキレス腱の肥厚は特徴的で、軟線撮影で厚さ9mm以上(男性)を目安に評価する。

【誤答選択肢の解説】
A「角膜混濁」: 角膜混濁はLCAT欠損症や魚眼病でみられる。家族性高コレステロール血症では角膜輪(老人環)がみられる。
B「扁桃腫大」: 扁桃の橙黄色腫大はコレステロールエステル転送に関わるTangier病の特徴である。
C「赤血球の変形」: 赤血球の変形(有棘赤血球)は無βリポ蛋白血症などでみられる。
D「手掌線条黄色腫」: 手掌線条黄色腫はIII型高脂血症(家族性III型高リポ蛋白血症)に特徴的である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 D009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-1', '正答は E「ランダム化比較試験〈RCT〉」。

介入研究は研究者が曝露(治療や予防手段)を割り付けて、その結果を比較する研究である。ランダム化比較試験は割り付けを無作為に行うことで交絡を制御でき、因果関係を示す証拠として最も強い。

【誤答選択肢の解説】
A「横断研究」: 横断研究はある一時点の曝露と疾病を同時に調べる観察研究である。
B「コホート研究」: コホート研究は曝露の有無で群を分けて追跡する観察研究で、割り付けは行わない。
C「症例対照研究」: 症例対照研究は疾病のある群とない群で過去の曝露をさかのぼって比べる観察研究である。
D「ケースシリーズ研究」: ケースシリーズ研究は症例の記述にとどまり、比較対照を置かない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-10', '正答は A「歯周病」。

歯周病は歯垢中の細菌による慢性炎症で、適切な歯磨きと禁煙、定期的な歯科受診によって発症を防げる。糖尿病との相互関係も知られ、生活習慣病の一つに位置づけられている。

【誤答選択肢の解説】
B「1型糖尿病」: 1型糖尿病は膵β細胞が自己免疫機序で破壊されて起こり、生活習慣とは関係しない。
C「悪性リンパ腫」: 悪性リンパ腫の発症は生活習慣の改善では防げない。
D「急性骨髄性白血病」: 急性骨髄性白血病は造血幹細胞の遺伝子異常によるもので、生活習慣による予防はできない。
E「原発性アルドステロン症」: 原発性アルドステロン症は副腎の腺腫や過形成によるもので、生活習慣とは関係しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-11', '正答は C「準備期 — 行動計画の作成」。

準備期は1か月以内に行動を変えようと思っており、すでに準備を始めている段階である。いつ・何を・どれだけ行うかという具体的な行動計画を一緒に作ることが有効な働きかけになる。

【誤答選択肢の解説】
A「無関心期 — 目標の設定」: 無関心期はまだ変える気がない段階で、目標を設定させても実行につながらない。まずは情報提供で気づきを促す。
B「関心期 — 情報の提供」: 関心期は関心はあるが行動に移せない段階で、変えることの利点と負担を整理して動機づけを高める。
D「実行期 — 罰則の設定」: 実行期は始めて6か月未満の段階で、続けられるように支援と称賛を行う。罰則は逆効果である。
E「維持期 — 支援の終了」: 維持期でも逆戻りは起こりうるため、支援を打ち切るのではなく継続を後押しする。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-12', '正答は C「皮膚に対して直角に穿刺する。」。

大腿動脈は体表から深い位置にあるため、拍動を触知した真上から皮膚に対して直角に穿刺する。鼠径靱帯の下で、外側から大腿神経・動脈・静脈の順に並ぶ位置関係を確かめて行う。

【誤答選択肢の解説】
A「穿刺針の太さは18Gを選択する。」: 18Gは太すぎる。動脈血ガス分析には23G前後の細い針を用いる。
B「動脈の走行は目視で確認する。」: 動脈は皮下深くを走り目視できない。指で拍動を触れて位置を確かめる。
D「シリンジに十分な陰圧をかける。」: 動脈圧で自然に血液が流入するので、強い陰圧は不要である。陰圧をかけると気泡が混入して測定値が狂う。
E「抜針後に穿刺部位をよく揉む。」: 揉むと出血や血腫を招く。5分以上しっかり圧迫止血する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E012（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-13', '正答は C「強直性脊椎炎 — 安静により改善する腰背部痛」。

強直性脊椎炎の腰背部痛は炎症性腰痛で、安静や睡眠中にむしろ悪化し、明け方に強く、体を動かすと軽快する。安静により改善するのは椎間板ヘルニアなど機械的腰痛の特徴で、組合せとして誤っている。

【誤答選択肢の解説】
A「関節リウマチ — 中足趾節関節の腫脹」: 関節リウマチは中足趾節関節や中手指節関節など小関節の滑膜炎をきたす。正しい組合せである。
B「乾癬性関節炎 — 遠位指節間関節の腫脹」: 乾癬性関節炎は遠位指節間関節を侵し、爪の変化を伴うことが多い。正しい組合せである。
D「Sjögren症候群 — 舌乳頭の萎縮」: Sjögren症候群では唾液分泌の低下により口腔乾燥をきたし、舌乳頭が萎縮して平滑舌となる。正しい組合せである。
E「皮膚筋炎 — 頸部における屈筋優位の筋力低下」: 皮膚筋炎では体幹に近い筋が侵され、頸部では屈筋が優位に低下して頭を持ち上げにくくなる。正しい組合せである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E013（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-14', '正答は E「McBurney圧痛点は臍と右前上腸骨棘を結ぶ線上外側1/3にある。」。

McBurney点は臍と右上前腸骨棘を結ぶ線を3等分した外側3分の1の点で、急性虫垂炎で圧痛が強くなる部位である。Lanz点(左右の上前腸骨棘を結ぶ線の右3分の1)とともに押さえておく。

【誤答選択肢の解説】
A「健常者の膵臓は深吸気時に触知する。」: 膵は後腹膜の深部にあり、健常者では触知できない。
B「健常者では両側の腎臓全体を触知する。」: 健常者では腎はふつう触れない。やせた人で右腎の下極が触れることがある程度である。
C「反跳痛は除圧時より加圧時の痛みが強い。」: 反跳痛は手を離したときに強く痛むもので、腹膜刺激徴候である。加圧時より除圧時の痛みが強い。
D「Murphy徴候は患者が大きく息を吐いた時に評価する。」: Murphy徴候は右季肋部を圧迫しながら息を吸わせたときに痛みで吸気が止まるかをみる。吐かせるのではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E014（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-15', '正答は E「聴診 → 打診 → 触診」。

腹部診察は視診のあと聴診、打診、触診の順に行う。触診や打診を先に行うと腸管が刺激されて腸蠕動音が変化し、本来の音を評価できなくなるためである。

【誤答選択肢の解説】
A「触診 → 打 —診 → 聴診」: 触診を最初に行うと腸蠕動音が変わってしまう。
B「触診 → 聴診 → 打診」: 同じく触診が先になっており、聴診の所見が変わってしまう。
C「打診 → 聴診 → 触診」: 打診も腹壁への刺激となるため、聴診より先に行わない。
D「打診 → 触 —診 → 聴診」: 打診と触診が聴診より先になっている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E015（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-16', '正答は C「データの収集・解析方法の計画」。

倫理審査委員会は研究計画書の妥当性を審査するので、目的、対象、方法、データの収集と解析の計画は審査を受ける前に固めておく必要がある。統計解析の計画が不十分な研究は被験者に負担をかけるだけで成果が出ないため、倫理的に問題があるとされる。

【誤答選択肢の解説】
A「インフォームドコンセントの取得」: 同意の取得は承認された説明文書と手順に沿って行うもので、審査前に行ってはならない。
B「研究参加希望者の適格性の判定」: 被験者の組入れも審査の承認後に始める。
D「研究協力者への謝金の支払い」: 謝金の額と支払い方法も審査の対象で、承認前に支払うことはできない。
E「治験薬剤の投与」: 治験薬の投与という介入そのものを承認前に行うことは許されない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E016（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-17', '正答は E「クエン酸ナトリウム」。

クエン酸ナトリウムはカルシウムをキレートして凝固を止め、測定時にカルシウムを加えれば反応を再開できるため、プロトロンビン時間やAPTTなどの凝固検査に用いる。血液9に対し抗凝固剤1の比を守ることが重要である。

【誤答選択肢の解説】
A「EDTA」: EDTAもカルシウムをキレートするが結合が強固で凝固反応を再開できない。血算に用いる。
B「ヘパリン」: ヘパリンはアンチトロンビンを介してトロンビンを阻害し、凝固検査の値を乱す。
C「ワルファリン」: ワルファリンは経口の抗凝固薬で、採血管の抗凝固剤としては用いない。
D「フッ化ナトリウム」: フッ化ナトリウムは解糖を止めるための添加物で、血糖測定用の採血管に用いる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-18', '正答は C「自己注射が認められている。」。

アナフィラキシーの既往がある患者にはアドレナリン自己注射製剤の処方が認められており、患者本人や家族、学校の教職員などが大腿前外側に筋肉内注射できる。早期の投与が予後を左右する。

【誤答選択肢の解説】
A「皮下に投与する。」: 皮下では吸収が遅い。大腿前外側への筋肉内注射が推奨される。
B「妊婦には使用しない。」: 妊婦でもアナフィラキシーでは母体の救命が優先され、投与する。
D「不整脈がある場合は使用しない。」: アナフィラキシーは生命に関わるため、不整脈があっても投与をためらわない。
E「ショックになってから投与する。」: ショックに至る前、呼吸器や循環器の症状が現れた時点で投与する。遅れるほど予後が悪い。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E018（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-20', '正答は E「精巣腫瘍」。

精巣腫瘍は無痛性の陰囊内腫瘤として気づかれるもので、尿路と交通しないため肉眼的血尿では発症しない。腫瘍マーカーのAFPとhCGが診断と経過観察に有用である。

【誤答選択肢の解説】
A「腎癌」: 腎癌では血尿、腹部腫瘤、疼痛が古典的三徴とされ、無症候性の肉眼的血尿で見つかることがある。
B「腎盂癌」: 腎盂癌は尿路上皮癌で、無症候性肉眼的血尿が典型的な初発症状である。
C「膀胱癌」: 膀胱癌も無症候性肉眼的血尿が最も多い初発症状である。
D「前立腺癌」: 前立腺癌は排尿症状や検診のPSA高値で見つかることが多いが、進行例では肉眼的血尿をきたす。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E020（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-21', '正答は E「疾病や治療についての患者の理解を確認する。」。

アドヒアランスは患者が治療方針の決定に参加し、納得して実行することを指す。病気と治療の意義を患者がどう理解しているかを確かめ、必要に応じて説明し直すことが向上につながる。

【誤答選択肢の解説】
A「処方日数を長くする。」: 処方日数を延ばすだけでは服薬の実行は改善せず、残薬の把握もしにくくなる。
B「薬の飲み忘れを叱責する。」: 叱責すると患者は飲み忘れを申告しなくなり、実態がつかめなくなる。
C「副作用の説明を省略する。」: 副作用を説明しないと、症状が出たときに自己判断で中断してしまう。
D「内服回数を可能な限り分割する。」: 内服回数はできるだけ少なくまとめるほうが続けやすい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E021（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-23', '正答は B「インフルエンザ」。

1918〜1919年に世界的に流行したスペインインフルエンザは、第一次世界大戦の末期と重なって数千万人の死者を出した。A(H1N1)型による最初のインフルエンザパンデミックとされる。

【誤答選択肢の解説】
A「エボラ出血熱」: エボラ出血熱は1976年に初めて確認され、流行は主にアフリカに限られる。
C「鳥インフルエンザ(H5N1)」: 鳥インフルエンザ(H5N1)のヒトへの感染が問題となったのは1997年以降である。
D「中東呼吸器症候群〈MERS〉」: 中東呼吸器症候群は2012年に初めて報告された。
E「後天性ヒト免疫不全症候群〈AIDS〉」: 後天性ヒト免疫不全症候群が報告されたのは1981年である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E023（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-24', '正答は D「患者が嘔吐している場合は撥水性ガウンを着用して診察する。」。

標準予防策では、血液・体液・分泌物・排泄物・傷のある皮膚・粘膜はすべて感染性があるものとして扱う。飛散する恐れがあれば、手袋に加えて撥水性ガウンやマスク、ゴーグルなど個人防護具を選んで用いる。

【誤答選択肢の解説】
A「滅菌手袋を着用する。」: 日常の診療では清潔(非滅菌)手袋で足りる。滅菌手袋は無菌操作を要する場面で用いる。
B「感染症と診断してから実施する。」: 診断の有無にかかわらず、すべての患者に対して常に行うのが標準予防策である。
C「次亜塩素酸ナトリウムで手指衛生を行う。」: 手指衛生は石けんと流水による手洗いかアルコール製剤で行う。次亜塩素酸ナトリウムは皮膚に用いない。
E「患者の唾液が付着した木製舌圧子は一般廃棄物として処理する。」: 唾液が付着した舌圧子は感染性廃棄物として処理する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-25', '正答は C「両上肢の随意把持努力により減弱する。」。

両上肢を組んで引っ張らせるJendrassik手技は、反射弓の緊張を高めて腱反射を出やすくする方法である。減弱させるのではなく増強させるので、この記述が誤っている。

【誤答選択肢の解説】
A「末梢神経障害で低下する。」: 反射弓の求心路・遠心路が障害されるため、末梢神経障害では腱反射が低下する。
B「下肢の力を抜くように指示する。」: 力が入っていると反射が出にくいので、力を抜くよう促す。
D「大腿四頭筋の収縮により下腿が前方に上がる。」: 膝蓋腱を叩くと大腿四頭筋が収縮し、下腿が前方に振り上がる。
E「ハンマーのバランスのよい部分を持って診察する。」: ハンマーは柄の適切な位置を軽く持ち、手首のスナップを使って叩く。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-27', '正答は D「ジアゼパムの静脈内投与」。

坐薬のジアゼパムでけいれんが止まらず30分以上持続しており、けいれん重積状態である。静脈路が確保できたので、まずジアゼパムを静脈内投与する。効果がなければ第二選択薬に進む。

【誤答選択肢の解説】
A「経過観察」: 30分以上続くけいれんを経過観察してよい状況ではない。
B「解熱薬の投与」: 解熱薬に抗けいれん作用はなく、熱性けいれんの再発予防にもならない。
C「経鼻胃管の留置」: 経鼻胃管はけいれんを止める手段ではない。
E「気管挿管による人工呼吸」: 酸素投与でSpO2 98%まで改善しており、呼吸は保たれている。挿管はまず薬物で止めることを試みてからである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E027（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-28', '正答は D「医師の承諾」。

臓器の移植に関する法律では、本人の書面による提供意思がある場合と、本人の意思が不明で家族が承諾する場合に提供できる。医師の承諾は根拠にならない。

【誤答選択肢の解説】
A「個人番号カードの意思表示」: 個人番号カードの裏面には臓器提供の意思表示欄があり、書面による意思表示として有効である。
B「運転免許証の意思表示」: 運転免許証の意思表示欄も有効である。
C「健康保険証の意思表示」: 健康保険証の意思表示欄も有効である。
E「家族の承諾」: 本人の意思が不明でも、家族が書面で承諾すれば提供できる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E028（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-29', '正答は D「オピオイドの経口投与」。

NSAIDで抑えきれない癌性疼痛には、段階を踏まずにオピオイドを導入してよい。経口摂取が可能なので、まず経口のオピオイドから始めて効果と有害事象をみながら調節する。

【誤答選択肢の解説】
A「NSAIDの増量」: NSAIDには天井効果があり、増量しても鎮痛は頭打ちで、腎障害や消化管出血の危険が増すだけである。
B「持続硬膜外麻酔」: 持続硬膜外麻酔は全身投与で制御できない場合に検討する侵襲的な手段である。
C「膵癌への放射線照射」: 放射線照射は骨転移痛などに有用だが、効果が出るまで時間がかかり、まず行うものではない。
E「副腎皮質ステロイド投与」: 副腎皮質ステロイドは補助薬として併用するもので、単独で第一に用いる鎮痛手段ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E029（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-3', '正答は E「Douglas窩の圧痛」。

骨盤内炎症性疾患では炎症が骨盤腹膜に及ぶため、内診でDouglas窩に圧痛を認める。子宮頸部を動かすと痛む頸管可動痛や付属器の圧痛とともに、診断の中心となる所見である。

【誤答選択肢の解説】
A「帯下の悪臭」: 帯下の悪臭は細菌性腟症などでもみられ、骨盤内への波及を示す所見ではない。
B「脾臓の触知」: 脾臓の触知は血液疾患や門脈圧亢進症を示唆し、骨盤内の炎症とは関係しない。
C「子宮口の開大」: 子宮口の開大は流産や切迫早産、分娩の進行を示す所見である。
D「下腹部腫瘤触知」: 下腹部腫瘤の触知は子宮筋腫や卵巣腫瘍でもみられ、炎症に特異的ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-30', '正答は A「頸管縫縮術」。

妊娠中期に自覚症状の乏しいまま胎胞が膨隆して流産することを繰り返しており、頸管無力症である。次の妊娠では妊娠12〜14週ごろに予防的な頸管縫縮術を行う。

【誤答選択肢の解説】
B「NSAID投与」: NSAIDは子宮収縮を抑える目的で用いられることがあるが、頸管無力症の治療にはならず、胎児の動脈管早期閉鎖の危険がある。
C「β2刺激薬投与」: β2刺激薬は子宮収縮抑制薬で、収縮を伴わない頸管無力症には無効である。
D「マグネシウム製剤投与」: マグネシウム製剤も子宮収縮抑制薬であり、同様に適応でない。
E「副腎皮質ステロイド投与」: 副腎皮質ステロイドは早産が避けられない場合に胎児の肺成熟を促す目的で用いるもので、この時期の対応ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E030（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-32', '正答は C「心肺蘇生法」。

気道異物による窒息から心停止に至っている。頸動脈を触知しないので、ただちに胸骨圧迫を含む心肺蘇生を始める。胸骨圧迫は胸腔内圧を高めて異物を押し出す効果も期待できる。

【誤答選択肢の解説】
A「開胸手術」: 開胸手術は気道異物の処置ではない。
B「静脈路確保」: 静脈路確保より胸骨圧迫が優先される。
D「背部叩打法」: 背部叩打法は意識がある間に行う手技で、意識を失った時点で心肺蘇生に切り替える。
E「気管支鏡下摘出術」: 気管支鏡下摘出術は循環を立て直したうえで行うもので、心停止の場では第一の処置にならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E032（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-33', '正答は E「5」。

ロコモティブシンドロームでは運動器の衰えから移動能力が落ちる。外出を控えれば活動量がさらに減り、廃用が進んで悪循環に陥る。外出の禁止は誤りで、安全に外出を続けられるように支援するのが適切である。

【誤答選択肢の解説】
A「1」: 下肢を中心とした筋力訓練とバランス訓練が中核の対応である。
B「2」: 身長155cm・体重38kgと低体重で低栄養が疑われ、蛋白質を中心とした栄養指導が必要である。
C「3」: ふさぎ込みがちで抑うつが疑われ、こころの健康への配慮は適切である。
D「4」: 転倒は骨折から要介護に直結するため、住環境の整備を含む転倒予防の指導は重要である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E033（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-35', '正答は A「訪問看護」。

自分で行えていたストマの管理が入院を機に難しくなっている。ストマ装具の交換や皮膚のトラブルへの対応は医療的な処置なので、介護保険の訪問看護を導入して支援する。

【誤答選択肢の解説】
B「訪問診療」: 外来通院が予定されており通院できる状態なので、医師が自宅に出向く訪問診療の適応ではない。
C「訪問入浴介護」: 入浴は自立しており、訪問入浴介護は要さない。
D「訪問薬剤管理」: 認知機能に問題がなく服薬管理もできているので、訪問薬剤管理指導は要さない。
E「グループホーム入所」: 妻と同居しており在宅生活が続けられる。認知症対応型のグループホーム入所の対象でもない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E035（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-36', '正答は D「母乳量は十分であると伝える。」。

出生体重3,000gから日齢28で3,600gとなっており、退院時の2,800gから約33g/日の増加で標準的である。排尿10回、排便3回と十分で、母乳量は足りていると判断できる。母親の不安に対しては、根拠を示して安心させることが最も適切な対応になる。

【誤答選択肢の解説】
A「人工乳に変更する。」: 体重増加は良好で、人工乳に変える理由がない。
B「母乳を与える回数を増やす。」: 現在の授乳回数で足りており、増やす必要はない。
C「母乳添加用粉末を追加する。」: 母乳添加用粉末は極低出生体重児などに用いるもので、正期産で順調に育っている児には要さない。
E「母乳と人工乳との混合栄養に変更する。」: 混合栄養に変える必要はなく、母乳のみで足りている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E036（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-37', '正答は C「抗菌薬を投与する。」。

ネコ咬傷はPasteurella multocidaなどによる感染を起こしやすく、深く狭い創で嫌気的な環境ができるため急速に進行する。すでに発赤と腫脹があり、アモキシシリン・クラブラン酸などの抗菌薬を投与する。

【誤答選択肢の解説】
A「創部を温める。」: 急性炎症の時期に温めると腫脹と疼痛が悪化する。
B「創部を縫合する。」: 動物咬傷は感染の危険が高く、原則として一次縫合せず開放創のままとする。
D「右前腕を強く縛る。」: 駆血は血流を妨げて組織を傷害するだけで、感染の管理にならない。
E「猫の口腔内スワブを培養する。」: 起因菌は創部から採取して調べる。動物の口腔内を培養しても治療の役に立たない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E037（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-38', '正答は B「カテーテルを抜去する前に固定水を抜く。」。

バルーンカテーテルは、抜去する前に注射器で固定水(バルーンの蒸留水)を完全に抜いてから引き抜く。膨らんだまま引くと尿道を損傷する。

【誤答選択肢の解説】
A「体位は座位で行う。」: 仰臥位で行う。座位では操作しにくく清潔も保ちにくい。
C「外尿道口をエタノールで消毒する。」: エタノールは粘膜を刺激するため用いない。外尿道口の消毒には水溶性の消毒薬を使う。
D「新しいカテーテルの内腔に潤滑剤を注入する。」: 潤滑剤はカテーテルの外側と尿道に用いる。内腔に注入すれば流出路を塞いでしまう。
E「今後は毎日交換する。」: 頻回の交換はかえって尿路感染や尿道損傷の危険を高める。閉塞や汚染があるときに交換する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E038（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-39', '正答は B「子どもに話しかける。」。

急性中耳炎が疑われる2歳児が不安で泣いている。まず子どもと目線を合わせて話しかけ、母親に抱かれたままの姿勢で安心させてから診察に入る。信頼関係を作ることが正確な所見を得る近道になる。

【誤答選択肢の解説】
A「診察台に寝かせる。」: 診察台に寝かせると不安が強まる。母親に抱かれた状態のまま診るほうがよい。
C「鎮静薬を内服させる。」: 耳鏡による診察のために鎮静薬を用いる必要はない。
D「翌日の外来受診を指示する。」: 夜間眠れないほどの痛みと発熱があり、この日のうちに鼓膜を確認すべきである。
E「最初に耳鏡で鼓膜所見を確認する。」: 耳鏡は痛みを伴い児が嫌がるため、最後に行う。まず苦痛の少ない診察から進める。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E039（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-4', '正答は C「装着はどの部位に付けても構わない。」。

トリアージタッグは原則として右手首に装着する。負傷などで装着できない場合は左手首、右足首、左足首、頸部の順とする。装着部位を決めておくのは、混乱した現場で誰もが確実に見つけられるようにするためである。

【誤答選択肢の解説】
A「傷病者識別のために使用する。」: 氏名や傷病の内容、トリアージ区分を記載して傷病者を識別するために用いる。
B「我が国の規格は統一されている。」: 様式は総務省消防庁により全国で統一されている。
D「多数の傷病者が同時発生したときに使う。」: 多数傷病者が同時に発生し、治療の優先順位づけが必要な状況で用いる。
E「死亡している場合は黒色タッグを装着する。」: 死亡または救命が困難な場合は0(黒)を残すように切り取る。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-5', '正答は C「Horner症候群 — 散瞳」。

Horner症候群は交感神経の遠心路が障害される病態で、縮瞳、眼瞼下垂、患側顔面の発汗低下を三徴とする。散瞳ではなく縮瞳をきたす点が誤りである。

【誤答選択肢の解説】
A「急性緑内障発作 — 散瞳」: 急性緑内障発作では中等度に散瞳したまま対光反応が鈍くなる。正しい組合せである。
B「交感神経作動薬 — 散瞳」: 交感神経作動薬は瞳孔散大筋を収縮させて散瞳させる。正しい組合せである。
D「動眼神経麻痺 — 散瞳」: 動眼神経麻痺では副交感神経成分が障害されて散瞳し、眼瞼下垂と外斜視を伴う。正しい組合せである。
E「有機リン中毒 — 縮瞳」: 有機リン中毒ではアセチルコリンの蓄積によりムスカリン様作用が強まり縮瞳する。正しい組合せである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-8', '正答は A「後天性血友病A」。

後天性血友病Aは第VIII因子に対する自己抗体(インヒビター)が生じる病態で、高齢者に突然の出血傾向として現れる。広範な皮下出血や筋肉内出血をきたし、APTTが延長するがPTは正常である。

【誤答選択肢の解説】
B「本態性血小板血症」: 本態性血小板血症は血小板が増加する疾患で、血栓症が主体である。
C「抗リン脂質抗体症候群」: 抗リン脂質抗体症候群も動静脈血栓症をきたす病態で、出血ではない。
D「免疫性血小板減少性紫斑病」: 免疫性血小板減少性紫斑病は血小板の減少により点状出血や紫斑、粘膜出血をきたす。深部の筋肉内出血は典型的でない。
E「IgA血管炎〈Schönlein-Henoch紫斑病〉」: IgA血管炎は下肢に触知可能な紫斑をきたす小血管炎で、凝固能は正常である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-E-9', '正答は D「橈骨神経損傷」。

三角筋への筋肉注射は肩峰から2〜3横指下の三角筋中央部に行う。遠位側にずれると、上腕骨の橈骨神経溝を走る橈骨神経を損傷して下垂手をきたす危険がある。

【誤答選択肢の解説】
A「肩関節障害」: 肩関節障害は逆に近位側、肩峰に近すぎる部位に打った場合に問題となる。
B「肩腱板損傷」: 肩腱板も肩峰の直下にあり、近位側にずれたときに損傷しうる。
C「血栓性静脈炎」: 血栓性静脈炎は静脈内への薬剤投与に伴う合併症である。
E「上腕動脈損傷」: 上腕動脈は上腕の内側を走り、三角筋の刺入部位からは離れている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 E009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-1', '正答は C「肺炎球菌性肺炎」。

肺炎球菌は莢膜をもつ細菌で、これに対抗するのは抗体と補体による液性免疫と脾臓の働きである。Tリンパ球の機能低下による日和見感染症には含まれない。無脾症や低ガンマグロブリン血症で問題となる。

【誤答選択肢の解説】
A「粟粒結核」: 結核菌は細胞内寄生菌で、細胞性免疫が落ちると封じ込めが破れて粟粒結核として再燃する。
B「食道カンジダ症」: 食道カンジダ症はCD4陽性リンパ球が減少したときに生じ、後天性免疫不全症候群の指標疾患である。
D「ニューモシスチス肺炎」: ニューモシスチス肺炎はCD4が200/μL未満に減った状況で起こる代表的な日和見感染症である。
E「サイトメガロウイルス感染症」: サイトメガロウイルスは潜伏感染し、細胞性免疫の低下により網膜炎や腸炎として再活性化する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-11', '正答は D「網膜色素変性 — 輪状暗点」。

網膜色素変性では網膜の中間周辺部から杆体が変性するため、初期には夜盲と輪状暗点が生じ、進行すると求心性視野狭窄となる。

【誤答選択肢の解説】
A「緑内障 — 中心暗点」: 緑内障では網膜神経線維の走行に沿った弓状暗点(Bjerrum暗点)や鼻側階段が生じる。中心視力は末期まで保たれる。
B「視神経炎 — 求心性狭窄」: 視神経炎では乳頭黄斑線維が侵され中心暗点をきたす。
C「加齢黄斑変性 — 弓状暗点」: 加齢黄斑変性では黄斑が侵されるため中心暗点と変視症が生じる。
E「中心性漿液性網脈絡膜症 — らせん状視野」: 中心性漿液性網脈絡膜症も黄斑の漿液性剝離により中心暗点と小視症をきたす。らせん状視野は心因性視覚障害の所見である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-12', '正答は B「Crohn病」。

Crohn病は口腔から肛門までの全消化管を侵しうる疾患で、アフタ性口内炎は腸管外病変としてしばしばみられる。縦走潰瘍、敷石像、非乾酪性肉芽腫、痔瘻とともに診断の手がかりになる。

【誤答選択肢の解説】
A「腸結核」: 腸結核は回盲部に輪状潰瘍をきたすが、口腔内アフタは特徴的でない。
C「大腸憩室症」: 大腸憩室症は腸管壁の脱出によるもので、口腔病変を伴わない。
D「虚血性大腸炎」: 虚血性大腸炎は下行結腸からS状結腸の血流障害によるもので、口腔病変とは無関係である。
E「過敏性腸症候群」: 過敏性腸症候群は器質的病変を伴わない機能性疾患である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F012（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-13', '正答は D「色素沈着」。

副腎腺腫が自律的にコルチゾールを分泌するため、負のフィードバックで下垂体のACTHは抑制される。ACTHの前駆体に由来するメラニン細胞刺激作用も働かないので、色素沈着はきたさない。色素沈着がみられるのは異所性ACTH症候群やAddison病である。

【誤答選択肢の解説】
A「円形顔貌」: 脂肪の中心性再分布により満月様顔貌(円形顔貌)を呈する。
B「眼瞼浮腫」: 顔面の脂肪沈着と体液貯留により眼瞼の腫れぼったさをきたす。
C「骨粗鬆症」: 骨形成の抑制と骨吸収の亢進により骨粗鬆症をきたし、椎体骨折の原因となる。
E「皮膚線条」: 皮膚が菲薄化し、腹部などに赤紫色の皮膚線条を生じる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F013（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-14', '正答は C「完全大血管転位症」。

完全大血管転位症では体循環と肺循環が並列となり、卵円孔と動脈管を通じた血液の混合がなければ生存できない。出生直後からチアノーゼが強く、プロスタグランジンE1で動脈管を開存させ、必要ならバルーン心房中隔裂開術を行う。

【誤答選択肢の解説】
A「心房中隔欠損症」: 心房中隔欠損症は成人期まで無症状で経過することも多い。
B「心室中隔欠損症」: 心室中隔欠損症では肺血管抵抗が下がる生後数週から心不全症状が現れる。出生直後の緊急介入は要さない。
D「部分肺静脈還流異常症」: 部分肺静脈還流異常症は短絡量が少なく、症状に乏しい。
E「房室中隔欠損症〈心内膜床欠損症〉」: 房室中隔欠損症も心不全は生後数週以降に現れる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F014（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-15', '正答は B「カルシウム」。

挫滅症候群では壊れた筋細胞からカリウム、ミオグロビン、CK、リンが放出される一方、遊離したリンと結合したカルシウムが壊死筋に沈着するため血清カルシウムは低下する。

【誤答選択肢の解説】
A「カリウム」: 細胞内に多いカリウムが放出され高カリウム血症となる。致死性不整脈の原因となる。
C「CK」: 筋の破壊を反映してCKが著明に上昇する。
D「ヘマトクリット」: 傷害された筋への大量の体液移動により循環血漿量が減り、血液が濃縮してヘマトクリットが上昇する。
E「ミオグロビン」: ミオグロビンが血中に放出され、腎尿細管を傷害して急性腎障害をきたす。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F015（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-19', '正答は B「2時間」。

水やお茶など固形物を含まない清澄水は、麻酔導入の2時間前まで摂ってよいとされている。長い絶飲は脱水や不快感を招くだけで、誤嚥の予防にはつながらない。

【誤答選択肢の解説】
A「15分」: 15分では胃内容が排出しきらず短すぎる。
C「6時間」: 6時間は軽い固形食(パンなど)に必要な絶食時間である。
D「12時間」: 12時間の絶飲は不要に長く、脱水を招く。
E「24時間」: 24時間の絶飲は害があるだけである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-20', '正答は D「蛋白質摂取を制限する。」。

フレイルの背景にはサルコペニアがあり、筋肉量を保つには十分な蛋白質が要る。制限はむしろ悪化させるので誤りである。高齢者では1.0g/kg/日以上の摂取が勧められる。

【誤答選択肢の解説】
A「毎日歯を磨く。」: 口腔機能の衰え(オーラルフレイル)は低栄養につながるため、口腔のケアは予防策となる。
B「運動習慣をつける。」: レジスタンス運動を含む運動習慣は筋力低下を防ぐ。
C「よく嚙んで食べる。」: よく嚙むことは咀嚼機能を保ち、食事摂取量の維持につながる。
E「ボランティアなどの社会活動に参加する。」: 社会参加は社会的フレイルを防ぎ、身体活動と意欲の維持にもつながる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F020（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-21', '正答は C「プロテインC」。

ビタミンK依存性の蛋白は、凝固因子の第II・VII・IX・X因子と、抗凝固に働くプロテインCおよびプロテインSである。グルタミン酸残基のγ-カルボキシル化にビタミンKが要る。

【誤答選択肢の解説】
A「第V因子」: 第V因子はビタミンK依存性ではない。肝で合成されるが γ-カルボキシル化を受けない。
B「第XIII因子」: 第XIII因子はフィブリンを架橋する因子で、ビタミンK依存性ではない。
D「フィブリノゲン」: フィブリノゲンは肝で合成されるがビタミンK依存性ではない。
E「アンチトロンビン」: アンチトロンビンも肝で合成される抗凝固因子だが、ビタミンK依存性ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F021（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-22', '正答は A「成人特有の反応である。」。

悲嘆反応は年齢を問わず生じる。子どもも死別に反応するが、退行や身体症状、遊びを通した表現など大人と異なる形をとることがあり、発達段階に応じた支援が要る。

【誤答選択肢の解説】
B「うつ病との鑑別が必要である。」: 抑うつ気分や不眠はうつ病と重なるため、経過や自責感の質から鑑別する必要がある。
C「身体的影響を生じる。」: 不眠、食欲低下、疲労感など身体的な影響も生じる。
D「提供されるケアをグリーフケアという。」: 死別による悲嘆を抱える人への支援をグリーフケアという。
E「時間とともに軽快する。」: 多くは時間とともに軽快する。長引いて生活に支障をきたす場合は遷延性悲嘆症として対応する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-24', '正答は E「簡易精神症状評価尺度[Brief Psychiatric Rating Scale〈BPRS〉]」。

簡易精神症状評価尺度(BPRS)は、思考解体、幻覚、感情の平板化など18項目を評価者が採点する尺度で、統合失調症の精神症状を包括的にとらえて治療効果の判定に用いる。

【誤答選択肢の解説】
A「Rorschachテスト」: Rorschachテストはインクの染みへの反応から人格傾向をみる投影法の検査である。
B「状態特性不安検査〈STAI〉」: 状態特性不安検査は不安の程度を、その時の状態と性格傾向に分けて測る。
C「リバーミード行動記憶検査〈RBMT〉」: リバーミード行動記憶検査は日常生活に即した記憶障害の評価に用いる。
D「Mini-Mental State Examination〈MMSE〉」: Mini-Mental State Examinationは認知機能のスクリーニング検査である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-26', '正答は D「日光角化症」。

デルマドロームは内臓疾患に伴って現れる皮膚症状のことである。日光角化症は長年の紫外線曝露によって生じる前癌病変で、内臓疾患を反映するものではない。

【誤答選択肢の解説】
A「Sweet病」: Sweet病(急性熱性好中球性皮膚症)は骨髄異形成症候群や白血病に伴うことがある。
B「皮膚筋炎」: 皮膚筋炎は悪性腫瘍の合併率が高く、悪性腫瘍の検索が必要である。
C「黒色表皮腫」: 黒色表皮腫はインスリン抵抗性や胃癌などの内臓悪性腫瘍に伴う。
E「壊疽性膿皮症」: 壊疽性膿皮症は潰瘍性大腸炎やCrohn病、関節リウマチなどに伴う。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F026（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-27', '正答は C「多発性骨髄腫 — 紅皮症」。

紅皮症は全身の皮膚が潮紅して落屑する状態で、皮膚T細胞リンパ腫(Sézary症候群)や薬疹、乾癬などでみられる。多発性骨髄腫の特徴的な症候ではなく、この組合せが誤っている。

【誤答選択肢の解説】
A「Hodgkinリンパ腫 — 間欠熱」: Hodgkinリンパ腫では発熱と無熱期を繰り返すPel-Ebstein型の間欠熱がみられる。正しい組合せである。
B「菌状息肉症 — 皮膚腫瘤」: 菌状息肉症は皮膚T細胞リンパ腫で、紅斑期から局面期を経て腫瘤期に至る。正しい組合せである。
D「マクログロブリン血症 — 網膜静脈怒張」: マクログロブリン血症では過粘稠度症候群により網膜静脈の怒張と蛇行をきたす。正しい組合せである。
E「慢性リンパ性白血病 — 肝脾腫」: 慢性リンパ性白血病ではリンパ節腫脹とともに肝脾腫をきたす。正しい組合せである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F027（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-28', '正答は B「警報音は高音域の音とする。」。

加齢に伴って高い周波数の音から聞き取りにくくなる。警報音は低音域を用いるほうが高齢労働者に届きやすいので、高音域とするのは適切でない。

【誤答選択肢の解説】
A「通路の段差を解消する。」: つまずきによる転倒を防ぐため、段差の解消は有効である。
C「作業場所の照度を確保する。」: 加齢により必要な明るさが増すため、十分な照度の確保は有効である。
D「危険箇所は標識で注意喚起する。」: 標識による注意喚起は危険の認知を助ける。
E「腰を低い位置に下げてから重量物を持ち上げる。」: 腰を落としてから持ち上げる姿勢は腰部への負担を減らし、腰痛を防ぐ。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F028（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-29', '正答は E「変容が得られないときは意思を強く持つよう指導する。」。

行動が変わらないときに意思の強さを求めるのは、うまくいかない原因を本人の性格に帰することになり、自己効力感を下げてしまう。障壁を一緒に洗い出し、目標を実行しやすい大きさに調整するほうが効果的である。

【誤答選択肢の解説】
A「自分で目標を設定する。」: 自分で決めた目標のほうが実行につながる。
B「自分の行動を記録する。」: 体重や歩数を自分で記録するセルフモニタリングは行動変容の基本的な技法である。
C「行動変容の規範意識を高める。」: 周囲の規範や価値観に働きかけることは行動変容を後押しする。
D「行動変容ステージに合わせた方法を選ぶ。」: 行動変容ステージに応じて働きかけを変えることが効果を高める。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F029（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-3', '正答は A「バリアフリーの推進」。

ノーマライゼーションは、障害の有無にかかわらず誰もが地域で当たり前の生活を送れる社会をつくるという考え方である。段差の解消や情報の保障などバリアフリーの推進はその具体化にあたる。

【誤答選択肢の解説】
B「リビングウィルの尊重」: リビングウィルの尊重は終末期における自己決定の尊重にあたる。
C「セカンドオピニオンの利用」: セカンドオピニオンの利用は治療選択における患者の自己決定を支える仕組みである。
D「ヘルスプロモーションの啓発」: ヘルスプロモーションは人々が自らの健康を管理し改善できるようにする過程で、オタワ憲章に基づく。
E「インフォームド・コンセントの徹底」: インフォームド・コンセントは説明を受けたうえで同意するという自己決定の原則である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-30', '正答は E「12か月 — 非対称性緊張性頸反射」。

非対称性緊張性頸反射は原始反射で、生後4〜6か月ごろまでに消える。12か月で残っていれば中枢神経の障害を疑う所見であり、この組合せが誤りである。

【誤答選択肢の解説】
A「1か月 — Moro反射」: Moro反射は生後4〜6か月ごろまでみられる。1か月でみられるのは正常である。
B「3か月 — 足底把握反射」: 足底把握反射は生後9〜10か月ごろまでみられる。3か月でみられるのは正常である。
C「6か月 — Landau反射」: Landau反射は生後4〜6か月ごろから2歳ごろまでみられる姿勢反射である。
D「9か月 — パラシュート反射」: パラシュート反射は生後8〜9か月ごろに出現し、生涯残る。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F030（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-32', '正答は D「見当識障害」。

見当識障害は意識障害や認知症、せん妄でみられる症状で、躁状態では意識は清明に保たれる。躁状態では気分の高揚、観念奔逸、行為心迫、誇大的な言動が前面に出る。

【誤答選択肢の解説】
A「多弁」: 多弁は観念奔逸を反映した躁状態の代表的な症状である。
B「浪費」: 抑制がきかず高額な買い物をするなどの浪費は躁状態でよくみられる。
C「易怒性」: 思いどおりにならないと激しく怒る易怒性・易刺激性も躁状態の症状である。
E「睡眠欲求の減少」: 眠らなくても平気で活動を続ける睡眠欲求の減少は躁状態の特徴である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F032（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-34', '正答は A「医師の免許」。

医師法は医師の免許、国家試験、臨床研修、業務(応召義務、診断書交付義務、無診察治療の禁止、異状死体の届出、診療録の記載と保存)を定める。免許に関する規定は医師法である。

【誤答選択肢の解説】
B「医師の守秘義務」: 医師の守秘義務は刑法第134条に規定されている。医師法には定めがない。
C「医療機関の種類」: 病院・診療所・助産所といった医療機関の種類は医療法が定める。
D「医療の安全の確保」: 医療の安全の確保は医療法に定められている。
E「特定機能病院の要件」: 特定機能病院の要件も医療法が定める。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F034（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-35', '正答は E「頭部MRAの検査予定日」。

カプセル内視鏡は消化管に停滞することがあり、そのままMRI検査を受けると発熱や粘膜損傷の危険がある。頭部MRAが予定されているので、カプセルの排出を確認してから検査を受けるよう日程を調整する必要がある。

【誤答選択肢の解説】
A「排便の頻度」: 排便は2日に1回の普通便で、通過を妨げるほどの便秘ではない。
B「腹部手術の既往」: 虫垂切除術は開腹歴ではあるが、癒着による狭窄を疑う症状はなく、最も注意すべき点ではない。
C「抗凝固薬休薬の可否」: カプセル内視鏡は生検や処置を伴わないので、抗凝固薬の休薬を要さない。
D「抗不安薬の内服状況」: 抗不安薬の内服はカプセル内視鏡の実施に影響しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F035（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-36', '正答は C「8点」。

心拍は6秒間に12回で毎分120回のため2点、啼泣が強く呼吸は2点、四肢を活発に動かす筋緊張は2点、刺激への咳嗽という反射は2点、皮膚色が全身暗紫色で0点となり、合計8点である。

【誤答選択肢の解説】
A「6点」: 6点ではどこかの項目をさらに1点減じることになるが、該当する所見がない。
B「7点」: 7点も同様に減点する根拠がない。
D「9点」: 皮膚色が全身暗紫色なので0点であり、9点にはならない。
E「10点」: 満点となるのは全身が淡紅色の場合で、本児は当てはまらない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F036（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-37', '正答は E「Pseudomonas aeruginosa」。

寛解導入療法後の好中球数は500×1%で5/μLと極度の好中球減少にあたる。発熱性好中球減少症では緑膿菌による敗血症が最も予後を左右するため、抗緑膿菌活性をもつ抗菌薬を直ちに開始する。

【誤答選択肢の解説】
A「Clostridium perfringens」: Clostridium perfringensはガス壊疽の起因菌で、発熱性好中球減少症の初期治療の主たる標的ではない。
B「Enterococcus faecalis」: Enterococcus faecalisも問題になりうるが、初期治療で最優先されるのは緑膿菌である。
C「Haemophilus influenzae」: Haemophilus influenzaeは市中肺炎の起因菌で、この状況で最優先とはならない。
D「Moraxella catarrhalis」: Moraxella catarrhalisも市中の気道感染の起因菌である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F037（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-38', '正答は D「「専門の病院に緊急入院して精査が必要です」」。

白血球95万という著明な増加に、Hb5.6g/dLの貧血と血小板1.5万の減少、LDと尿酸の上昇を伴っており、乳児の急性白血病が強く疑われる。白血球うっ滞と腫瘍崩壊症候群の危険があり、専門施設への緊急入院が必要である。

【誤答選択肢の解説】
A「「点滴をしてから帰りましょう」」: 点滴をして帰宅させてよい状態ではない。
B「「もっと早く受診するべきでした」」: 受診の遅れを責めることは母親を追い詰めるだけで、医学的にも意味がない。
C「「明日かかりつけ医に相談してください」」: 翌日まで待てる状態ではない。
E「「命にかかわることはないので心配は要りません」」: 生命に関わる病態であり、心配は要らないという説明は誤りである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F038（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-39', '正答は C「ループ利尿薬」。

糖尿病性腎症による腎不全とネフローゼ状態に、体重7kgの増加、下腿浮腫、心拡大と肺うっ血を伴っており体液過剰である。まずループ利尿薬で除水し、うっ血を解除する。

【誤答選択肢の解説】
A「新鮮凍結血漿」: 新鮮凍結血漿は凝固因子の補充に用いるもので、膠質浸透圧を上げる目的で使うものではない。
B「赤血球濃厚液」: Hb8.6g/dLの腎性貧血は緊急の輸血を要する水準ではなく、輸血は体液量をさらに増やす。
D「アルブミン製剤」: アルブミン製剤は低アルブミン血症の是正を目的とした投与が推奨されておらず、体液量を増やす。
E「維持輸液(組成:Na+35mEq/L、K+20mEq/L、Cl−35mEq/L、グルコース5.0%)」: K5.8mEq/Lと高カリウム血症があり、カリウムを含む維持輸液は禁忌にあたる。体液過剰でもある。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F039（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-4', '正答は D「血清アルブミン値」。

生理的黄疸は、新生児が多血であること、赤血球寿命が短いこと、グルクロン酸抱合酵素の活性が低いこと、腸肝循環が亢進していることが重なって生じる。血清アルブミン値はビリルビンの運搬能に関わり核黄疸の危険を左右するが、黄疸そのものの成因ではない。

【誤答選択肢の解説】
A「多血症」: 新生児は多血でヘマトクリットが高く、崩壊する赤血球が多いためビリルビンの産生が多い。
B「腸肝循環」: 腸内細菌叢が未熟でβ-グルクロニダーゼにより脱抱合され、再吸収される腸肝循環が亢進している。
C「赤血球寿命」: 新生児の赤血球寿命は70〜90日と成人より短く、崩壊が多い。
E「グルクロン酸抱合酵素活性」: 肝のグルクロン酸抱合酵素の活性が低く、間接ビリルビンを処理しきれない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-41', '正答は D「定期的な悪性腫瘍スクリーニングが必須である。」。

移植後は免疫抑制薬を長期に続けるため、免疫監視機構が働きにくくなり悪性腫瘍の発生率が高まる。皮膚癌やリンパ増殖性疾患をはじめ、定期的なスクリーニングが欠かせない。

【誤答選択肢の解説】
A「妻の定期受診は不要である。」: 生体腎提供者は腎機能や血圧の経過をみるため生涯にわたる定期受診が必要である。
B「海外旅行に行くことはできない。」: 状態が安定していれば海外旅行もできる。渡航先の感染症対策と薬の携行に注意する。
C「インフルエンザワクチンは接種できない。」: 不活化ワクチンであるインフルエンザワクチンは接種でき、むしろ推奨される。生ワクチンは避ける。
E「移植を受けた患者の半数で移植10年後に再び透析が必要になる。」: 生体腎移植の10年生着率は8割前後で、半数が透析に戻るわけではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F041（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-43', '正答は E「総エネルギー摂取量の40〜60%を炭水化物由来とする。」。

2型糖尿病の食事療法では、指示エネルギー量の40〜60%を炭水化物から摂り、蛋白質20%まで、残りを脂質とするのが標準的な配分である。

【誤答選択肢の解説】
A「食塩摂取量を10g/日未満とする。」: 血圧144/92mmHgもあり、食塩は6g/日未満を目標とする。10g/日未満では緩すぎる。
B「蛋白質摂取量を35g/日未満とする。」: 腎症がなく蛋白質を35g/日未満に絞る理由はない。過度の制限は栄養障害を招く。
C「脂質は飽和脂肪酸を50g/日以上とする。」: 飽和脂肪酸は動脈硬化を促すため控えるべきで、50g/日以上という指示は逆である。
D「総エネルギー摂取量を1,800kcal/日とする。」: 身長152cmの標準体重は約50.9kgで、25〜30kcal/kgとすると1,300〜1,500kcal/日が目安となる。1,800kcalは多い。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F043（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-44', '正答は E「日常生活動作〈ADL〉」。

予約どおりバスを使って来院し、身だしなみも整っている。移動と身の回りの管理ができており、日常生活動作は保たれていると判断できる。

【誤答選択肢の解説】
A「意欲」: 好きだった花の手入れや食事の準備が億劫になっており、意欲は低下している。
B「運動機能」: よくつまずいて転倒しており、運動機能は低下している。
C「栄養状態」: 食欲が低下し食事量も減っており、栄養状態は悪化しつつある。
D「嚥下機能」: 食事中にむせるようになっており、嚥下機能は低下している。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F044（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-45', '正答は B「禁酒」。

ビール350mLを週2回は節度ある適度な飲酒の範囲内で、これをやめても腎機能の維持にはつながらない。BMI29.0の肥満、蛋白質2.0g/kg/日、食塩9.5g/日という是正すべき点が明らかにある。

【誤答選択肢の解説】
A「禁煙」: 喫煙は腎機能低下を進める確立した危険因子で、禁煙の効果は大きい。
C「体重の減量」: BMI29.0の肥満は糸球体過剰濾過を招く。減量は蛋白尿と腎機能低下を抑える。
D「食塩摂取制限」: 食塩9.5g/日は多い。6g/日未満への制限は降圧と蛋白尿の減少をもたらす。
E「蛋白質摂取制限」: 蛋白質2.0g/kg/日は過剰で、0.6〜0.8g/kg/日程度への制限が腎機能低下の進行を抑える。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F045（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-49', '正答は B「カルシウム拮抗薬」。

Ca11.5mg/dLの高カルシウム血症、K6.0mEq/Lの高カリウム血症、クレアチニン2.1mg/dLの腎機能低下があり、ACE阻害薬・NSAID・ビスホスホネート製剤はいずれも中止・見直しが要る。カルシウム拮抗薬はこれらの異常に関与せず、血圧160/96mmHgに対しても継続してよい。

【誤答選択肢の解説】
A「NSAID」: NSAIDは腎血流を減らして腎障害を悪化させ、高カリウム血症も助長する。中止する。
C「ビスホスホネート製剤」: ビスホスホネート製剤は腎機能低下時には慎重投与で、高カルシウム血症の原因検索が済むまで見直しが要る。
D「ベンゾジアゼピン系睡眠薬」: ベンゾジアゼピン系睡眠薬は1週間前から追加されており、意識レベルの低下と食欲低下に関与している可能性が高い。
E「アンジオテンシン変換酵素〈ACE〉阻害薬」: ACE阻害薬は腎機能低下と高カリウム血症を悪化させるため中止する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F049（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-51', '正答は A「気道確保」。

強い嚥下痛から始まり、含み声と吸気性喘鳴が急速に進んでおり急性喉頭蓋炎による上気道閉塞である。診察中にも増悪しており、まず気道確保を行う。窒息に備えて輪状甲状靱帯穿刺・切開の準備をしておく。

【誤答選択肢の解説】
B「経鼻胃管挿入」: 経鼻胃管の挿入は喉頭の刺激となり、かえって閉塞を招く危険がある。
C「消炎鎮痛薬の投与」: 消炎鎮痛薬では気道の腫脹はすぐに引かず、閉塞に間に合わない。
D「気管支拡張薬の吸入」: 閉塞部位は喉頭であり、気管支拡張薬は効かない。
E「テオフィリンの静脈内投与」: テオフィリンも気管支に作用する薬で、上気道閉塞には無効である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F051（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-54', '正答は C「母乳を与えてから再度聴診を試みる。」。

乳児の心音を聴くには児が静かであることが要る。最後の授乳から2時間30分が経ち空腹で泣いているので、母乳を与えて落ち着かせ、あるいは入眠したところで聴診するのが最も現実的で侵襲もない。

【誤答選択肢の解説】
A「薬剤による鎮静を行う。」: 心雑音の聴取のために鎮静薬を用いるのは侵襲が大きく、適切でない。
B「おもちゃを手に持たせて遊ばせる。」: 1か月児はおもちゃを手に持って遊べる発達段階にない。
D「聴診をあきらめて心エコー検査を行う。」: 聴診を試みる余地があるうちから心エコー検査に切り替える必要はない。まず身体診察を尽くす。
E「アニメーションビデオを用いて興味をひく。」: 1か月児は映像に注意を向けられず、あやす手段にならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F054（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-55', '正答は B「早期破水」。

破水は子宮口全開大より前に起こると早期破水と呼ぶ。午前8時、子宮口6cm開大の時点で破水しており早期破水にあたる。分娩開始前の破水は前期破水である。

【誤答選択肢の解説】
A「遷延分娩」: 経産婦の分娩所要時間は15時間以内が目安で、午前1時の陣痛開始から午後1時の全開大まで12時間であり遷延分娩ではない。
C「微弱陣痛」: 陣痛周期3分、持続1分は有効な陣痛で、微弱陣痛ではない。
D「分娩停止」: 子宮口は4cmから6cm、全開大へと進み、児頭も下降しており停止していない。
E「後方後頭位」: 小泉門を1時方向に触れ矢状縫合が骨盤縦径に一致しており、第1前方後頭位である。後方後頭位ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F055（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-58', '正答は D「スタチンの開始」。

スタチンは尿酸値を上げず、痛風発作の誘因にならない。むしろ軽度に尿酸を下げるとの報告もある。

【誤答選択肢の解説】
A「飲酒」: アルコールは尿酸の産生を増やし排泄を妨げるため、発作の誘因となる。
B「運動」: 激しい運動はATPの分解を進めて尿酸を増やし、発汗による脱水も加わって誘因となる。
C「脱水」: 脱水は血中尿酸濃度を上げ、尿酸塩の析出を促す。
E「降圧利尿薬の開始」: サイアザイド系などの降圧利尿薬は尿酸の排泄を妨げ、高尿酸血症をきたす。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F058（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-6', '正答は D「在宅療養中の肺がん終末期の肺炎による死亡」。

医療関連死は医療行為に関連して生じた死亡を指す。在宅療養中の肺癌終末期に肺炎で亡くなるのは原疾患の自然な経過であり、医療行為に起因するものではない。

【誤答選択肢の解説】
A「術中の大量出血による死亡」: 手術という医療行為に伴う出血による死亡で、医療関連死にあたる。
B「輸液ポンプの誤用による死亡」: 機器の誤用という医療行為の過程で生じた死亡である。
C「負荷心電図検査中の心室細動による死亡」: 検査という医療行為の最中に生じた死亡である。
E「入院中に発生した重度褥瘡に起因する敗血症による死亡」: 入院中の療養看護の過程で生じた褥瘡に起因しており、医療関連死にあたる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('117-F-9', '正答は C「味覚障害」。

味覚障害は亜鉛欠乏や薬剤、口腔乾燥などで生じるもので、誤嚥を示す所見ではない。誤嚥は原因不明の発熱、湿性咳嗽、喀痰の増加、飲水時のむせから疑う。

【誤答選択肢の解説】
A「発熱」: 誤嚥性肺炎により発熱をきたす。高齢者では発熱だけが手がかりのこともある。
B「湿性咳嗽」: 気道に入った唾液や食物により湿った咳が出る。
D「喀痰の増加」: 気道への異物の刺激で分泌が増え、喀痰が増加する。
E「飲水時のむせ」: 水分は最も誤嚥しやすく、飲水時のむせは嚥下障害の代表的な徴候である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第117回医師国家試験 F009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp230502-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-1', '正答は B「腹部大動脈瘤」。

腹部大動脈瘤は破裂するまで自覚症状に乏しく、腹部の拍動性腫瘤や、他の目的で行った画像検査で偶然見つかることが多い。径5cmを超えると破裂の危険が高まり、待機的な人工血管置換術やステントグラフト内挿術を検討する。

【誤答選択肢の解説】
A「大動脈解離」: 大動脈解離は突然の激烈な胸背部痛で発症する。
C「感染性心内膜炎」: 感染性心内膜炎は持続する発熱、心雑音、塞栓症状で気づかれる。
D「冠攣縮性狭心症」: 冠攣縮性狭心症は夜間から早朝の安静時胸痛で受診する。
E「たこつぼ心筋症」: たこつぼ心筋症は強い精神的・身体的ストレスの後に胸痛や呼吸困難で発症する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-10', '正答は A「TPHAは疾患活動性の指標となる。」。

TPHA(TP抗体)は梅毒トレポネーマそのものに対する抗体で、治癒後も生涯陽性のままとなるため疾患活動性の指標にならない。活動性と治療効果の判定にはRPRなどの脂質抗原検査の抗体価を用いる。

【誤答選択肢の解説】
B「他の性感染症の合併について検索する。」: 性感染症は重複しやすく、HIVやクラミジアなどの検索が必要である。
C「神経梅毒は感染からの期間を問わず起こる。」: 神経梅毒は早期にも生じうるため、感染からの期間で除外できない。
D「妊婦が未治療の場合、児の先天梅毒の原因となる。」: 未治療の妊婦から経胎盤感染して先天梅毒をきたす。妊婦健診での検査が重要である。
E「日本では10年前と比較して報告数が増加している。」: 国内の梅毒報告数は近年著しく増加している。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-11', '正答は E「前立腺全摘除術」。

前立腺全摘除術では外尿道括約筋やその支持組織が損傷され、咳やくしゃみなど腹圧がかかったときに尿がもれる腹圧性尿失禁をきたす。骨盤底筋訓練が治療の中心となる。

【誤答選択肢の解説】
A「尿閉」: 尿閉では膀胱に貯まった尿があふれる溢流性尿失禁となる。
B「脳梗塞」: 脳梗塞では排尿反射の抑制が外れて切迫性尿失禁をきたす。
C「過活動膀胱」: 過活動膀胱は急な強い尿意を伴う切迫性尿失禁の原因である。
D「間質性膀胱炎」: 間質性膀胱炎は膀胱痛と頻尿が主症状である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-12', '正答は E「ムンプスウイルス」。

ムンプスウイルスは内耳を直接侵し、多くは片側性の高度感音難聴を後遺症として残す。ワクチンで予防できる難聴として重要である。

【誤答選択肢の解説】
A「アデノウイルス」: アデノウイルスは咽頭結膜熱や流行性角結膜炎の原因で、難聴はきたさない。
B「Epstein-Bar〈r EB〉ウイルス」: EBウイルスは伝染性単核症の原因で、感音難聴の原因としては挙げられない。
C「単純ヘルペスウイルス」: 単純ヘルペスウイルスは口唇ヘルペスや脳炎、Bell麻痺に関与するが、後天性の感音難聴の代表ではない。
D「風疹ウイルス」: 風疹ウイルスによる難聴は胎内感染による先天性風疹症候群としてみられるもので、後天性ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A012（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-16', '正答は D「高位精巣摘除術」。

無痛性の精巣腫大に充実性腫瘤と後腹膜リンパ節転移を認め、精巣腫瘍である。経陰囊的な生検は腫瘍を播種させるため行わず、鼠径部を切開して精索を高位で処理する高位精巣摘除術で診断と初期治療を兼ねる。

【誤答選択肢の解説】
A「経過観察」: 後腹膜リンパ節転移があり、経過観察は適応外である。
B「放射線治療」: 組織型が確定しないまま放射線治療は行えない。
C「精巣の針生検」: 経陰囊的な針生検は腫瘍細胞を陰囊内やリンパ路に播種させる危険があり禁忌である。
E「殺細胞性抗癌薬」: 化学療法は高位精巣摘除術で組織型を確かめてから行う。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A016（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-19', '正答は D「胸部〜下肢造影CT」。

若年発症で家族歴に脳静脈洞血栓症があり、下肢浮腫とDダイマー10μg/mLの上昇を伴っている。遺伝性の血栓性素因を背景とした深部静脈血栓症と肺血栓塞栓症を疑い、胸部から下肢までの造影CTで血栓の有無と範囲を一度に評価する。

【誤答選択肢の解説】
A「気管支鏡検査」: 気管支鏡検査は気道や肺実質の病変を調べるもので、血栓の評価にはならない。
B「呼吸機能検査」: 呼吸機能検査は急性の血栓塞栓症の診断には役立たず、実施にも時間がかかる。
C「頸部超音波検査」: 頸部超音波検査は頸動脈の動脈硬化の評価に用いる。
E「足関節上腕血圧比〈ABI〉」: 足関節上腕血圧比は下肢の動脈閉塞をみる検査で、静脈血栓の評価には使えない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-2', '正答は E「居室と脱衣所の温度差をなくす。」。

冬季の入浴中の事故の多くは、暖かい居室から寒い脱衣所・浴室へ移動した際の急激な血圧変動(ヒートショック)による。脱衣所と浴室を暖めて温度差をなくすことが最も有効な予防策である。

【誤答選択肢の解説】
A「食後に入浴する。」: 食後は消化管に血流が集まり血圧が下がりやすいので、食直後の入浴は避ける。
B「深夜に入浴する。」: 深夜は室温が下がり発見も遅れるため、危険が高い。
C「浴槽から出た後は体を冷やす。」: 湯から出た後に体を冷やすと血管が収縮して血圧が急に上がる。
D「気温が高い時期の入浴を避ける。」: 事故が多いのは気温の低い冬季であり、暑い時期を避けるのは的外れである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-25', '正答は E「サイトメガロウイルス感染症」。

妊娠初期検査で風疹HI抗体価が高く梅毒もHIVも陰性であった妊婦が、妊娠15週の感冒様症状の後に胎児発育不全と胎児腹水をきたしている。母体の初感染から経胎盤感染するサイトメガロウイルス感染症が最も考えられる。

【誤答選択肢の解説】
A「水痘」: 水痘の母子感染では四肢低形成や瘢痕性皮膚病変が特徴で、水疱疹のエピソードもない。
B「梅毒」: RPR 1倍未満、TPHA陰性で梅毒は否定される。
C「風疹」: 風疹HI抗体価128倍と免疫があり、初感染は考えにくい。
D「B型肝炎」: HBs抗原陰性であり、また B型肝炎の母子感染は分娩時感染が主で胎児発育不全をきたさない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-29', '正答は A「抗菌薬」。

発熱、下腹部の反跳痛、子宮の圧痛、外子宮口からの膿性分泌物、著明な白血球増多とCRP上昇から骨盤内炎症性疾患である。淋菌とクラミジアを想定した抗菌薬治療を速やかに始める。

【誤答選択肢の解説】
B「整腸薬」: 整腸薬では感染は治らない。
C「抗ウイルス薬」: 起因菌は細菌であり、抗ウイルス薬の適応はない。
D「GnRHアゴニスト」: GnRHアゴニストは子宮内膜症や子宮筋腫に用いる。
E「グルココルチコイド」: 感染症に対してグルココルチコイドを単独で用いれば病態を悪化させる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A029（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-3', '正答は C「ビタミンD欠乏症」。

ビタミンD欠乏では腸管からのカルシウムとリンの吸収がともに低下する。低カルシウム血症に反応して副甲状腺ホルモンが上昇し、尿細管でのリン再吸収を抑えるため、低リン血症がさらに進む。

【誤答選択肢の解説】
A「腫瘍性骨軟化症」: 腫瘍性骨軟化症はFGF23の過剰産生による低リン血症が主体で、血清カルシウムは基準内に保たれる。
B「甲状腺機能亢進症」: 甲状腺機能亢進症では骨吸収が亢進して血清カルシウムはむしろ上昇する。
D「副甲状腺機能低下症」: 副甲状腺機能低下症では尿中へのリン排泄が減るため、低カルシウム血症と高リン血症になる。
E「慢性腎臓病に伴うミネラル骨代謝異常」: 慢性腎臓病ではリンの排泄が低下して高リン血症となり、活性型ビタミンD低下により低カルシウム血症をきたす。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-30', '正答は C「ベンゾジアゼピン系薬剤」。

長年の多量飲酒者が断酒すると、数時間から数日で手指振戦、発汗、不眠、けいれん、振戦せん妄といった離脱症状をきたす。交叉耐性のあるベンゾジアゼピン系薬剤を投与して離脱症状を抑え、漸減する。

【誤答選択肢の解説】
A「抗酒薬」: 抗酒薬は離脱期を脱して断酒を維持する段階で用いる。離脱症状の治療薬ではない。
B「レボドパ〈L-dopa〉」: レボドパはParkinson病の治療薬で、アルコール離脱の振戦には無効である。
D「アセチルコリンエステラーゼ阻害薬」: アセチルコリンエステラーゼ阻害薬はAlzheimer型認知症の治療薬である。
E「選択的セロトニン再取り込み阻害薬〈SSRI〉」: SSRIはうつ病や不安障害に用いるもので、離脱症状には即効性がない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A030（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-31', '正答は E「臨床工学技士」。

臨床工学技士は生命維持管理装置の操作と保守を担う。人工呼吸器を要さない誤嚥性肺炎の治療サポートでは出番がない。

【誤答選択肢の解説】
A「管理栄養士」: 体重46kgと低栄養があり、管理栄養士が栄養管理と食形態の調整に関わる。
B「言語聴覚士」: むせがあり嚥下障害の評価と嚥下訓練を言語聴覚士が担う。
C「歯科衛生士」: う歯があり口腔内が乾燥しており、口腔ケアで誤嚥性肺炎を防ぐために歯科衛生士が関わる。
D「理学療法士」: 左不全片麻痺があり、廃用を防ぐ運動療法と排痰の援助を理学療法士が担う。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A031（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-32', '正答は A「血漿交換」。

汎血球減少と骨髄の著明な低形成から再生不良性貧血である。血漿交換は血漿中の病因物質を除く治療で、造血幹細胞の減少という病態には効かず適応にならない。

【誤答選択肢の解説】
B「赤血球輸血」: Hb5.4g/dLの高度貧血に対し、症状に応じて赤血球輸血を行う。
C「抗胸腺細胞グロブリン〈ATG〉投与」: 抗胸腺細胞グロブリンとシクロスポリンによる免疫抑制療法が重症例の標準治療である。
D「トロンボポエチン受容体作動薬投与」: トロンボポエチン受容体作動薬は造血の回復を促す薬剤として免疫抑制療法に併用される。
E「顆粒球コロニー刺激因子〈G-CSF〉投与」: 好中球360/μLと減少しており、感染症を合併すればG-CSFを用いる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A032（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-35', '正答は E「直接作用型抗ウイルス薬〈direct acting antivirals〉」。

HCV抗体陽性かつHCV-RNA陽性でC型慢性肝炎である。現在の第一選択は直接作用型抗ウイルス薬で、8〜12週の内服により95%以上でウイルスが排除される。

【誤答選択肢の解説】
A「インターフェロン」: インターフェロンは有害事象が多く、直接作用型抗ウイルス薬に置き換わった。
B「核酸アナログ製剤」: 核酸アナログ製剤はB型肝炎の治療薬である。HBs抗原は陰性である。
C「グルココルチコイド」: グルココルチコイドは自己免疫性肝炎に用いる。ウイルスを増やす危険がある。
D「ウルソデオキシコール酸」: ウルソデオキシコール酸は原発性胆汁性胆管炎などに用いる肝庇護薬で、ウイルスは排除できない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A035（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-36', '正答は C「グルコン酸カルシウム」。

腎機能低下に果物の多食が重なり、K6.7mEq/Lの高カリウム血症で心電図にテント状T波が出ている。致死性不整脈を防ぐため、まずグルコン酸カルシウムを静注して心筋の膜を安定化させ、続いてグルコース・インスリン療法や透析でカリウムを下げる。

【誤答選択肢の解説】
A「SGLT2阻害薬」: SGLT2阻害薬は血糖を下げるが、この状況で緊急に投与する薬ではない。
B「アルブミン製剤」: アルブミン製剤は体液過剰と肺うっ血を悪化させる。
D「エリスロポエチン製剤」: エリスロポエチン製剤は腎性貧血に用いるもので、効果が出るまで数週かかる。
E「アンジオテンシン受容体拮抗薬」: アンジオテンシン受容体拮抗薬は高カリウム血症をさらに悪化させるため、この時点では禁忌である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A036（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-37', '正答は A「筋膜切開」。

上腕骨顆上骨折後に前腕の著明な腫脹、他動伸展での激痛、橈骨動脈拍動の消失がそろっており急性コンパートメント症候群である。ただちに筋膜切開で内圧を下げないとVolkmann拘縮を残す。

【誤答選択肢の解説】
B「牽引治療」: 牽引では区画内圧は下がらず、対応が遅れる。
C「ギプス固定」: ギプス固定はむしろ内圧を高めて悪化させる。
D「手指の可動域訓練」: 他動伸展で激痛があり、可動域訓練は不適切である。
E「骨折の観血的整復固定」: 骨折の固定より先に区画内圧の解除が要る。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A037（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-4', '正答は A「糖尿病」。

糖尿病では自律神経障害により心臓の求心性神経が障害され、心筋虚血があっても胸痛を自覚しない無痛性心筋虚血をきたす。発見が遅れて重症化しやすいので、定期的な心電図や負荷検査による評価が要る。

【誤答選択肢の解説】
B「骨粗鬆症」: 骨粗鬆症は骨量の減少による病態で、心筋虚血の自覚とは関係しない。
C「気管支喘息」: 気管支喘息は気道の慢性炎症による疾患で、痛覚には影響しない。
D「Parkinson病」: Parkinson病では自律神経障害を伴うが、無痛性虚血をきたす代表的疾患としては挙げられない。
E「胃食道逆流症」: 胃食道逆流症はむしろ狭心症と紛らわしい胸痛を起こす側である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-40', '正答は A「乳癌」。

皮膚の陥凹(えくぼ徴候)を伴う硬い腫瘤に、マンモグラフィでスピキュラを伴う腫瘤陰影と多形性の微細石灰化を認めており乳癌である。針生検で組織型とサブタイプを確かめて治療方針を決める。

【誤答選択肢の解説】
B「乳腺症」: 乳腺症は月経周期に伴う疼痛と硬結が主で、スピキュラや多形性微細石灰化は伴わない。
C「葉状腫瘍」: 葉状腫瘍は急速に増大する境界明瞭な腫瘤で、皮膚陥凹やスピキュラは示さない。
D「慢性乳腺炎」: 慢性乳腺炎では発赤と圧痛を伴う炎症所見が前面に出る。
E「乳腺線維腺腫」: 乳腺線維腺腫は若年者に多い可動性良好な境界明瞭腫瘤である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A040（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-43', '正答は E「副腎皮質ステロイド点鼻」。

季節性の症状で鼻汁好酸球陽性、スギ花粉の飛散期に増悪しており季節性アレルギー性鼻炎である。鼻噴霧用の副腎皮質ステロイドは鼻閉を含むすべての症状に有効で、効果の発現も早い。

【誤答選択肢の解説】
A「抗菌薬内服」: 細菌感染ではなく、抗菌薬の適応はない。
B「減感作療法」: 減感作療法(アレルゲン免疫療法)は数年かけて行うもので、今すぐの改善にはつながらない。
C「免疫抑制薬内服」: 免疫抑制薬を用いる病態ではない。
D「鼻内レーザー手術」: 鼻内レーザー手術は薬物療法で改善しない鼻閉に対して、花粉飛散前に行うものである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A043（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-44', '正答は A「C3低下」。

先行する咽頭炎から2週間後に血尿・蛋白尿、浮腫、高血圧が現れており急性糸球体腎炎(A群β溶血性連鎖球菌感染後)である。免疫複合体による補体の消費を反映して血清C3が低下し、6〜8週で回復する。

【誤答選択肢の解説】
B「IgE高値」: IgE高値はアレルギー疾患や寄生虫感染でみられ、本症の所見ではない。
C「M蛋白陽性」: M蛋白は多発性骨髄腫などで検出される。
D「抗核抗体陽性」: 抗核抗体陽性はループス腎炎を示唆するが、顔面皮疹もなく先行感染との時間関係が典型的である。
E「抗リン脂質抗体陽性」: 抗リン脂質抗体は血栓症と関連し、本症の所見ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A044（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-47', '正答は E「レム〈REM〉睡眠行動障害」。

睡眠後半に夢の内容に一致した行動が現れ、覚醒すると夢を記憶している。筋強剛と認知機能低下も伴っており、レム睡眠行動障害である。Parkinson病やLewy小体型認知症に先行する徴候として重要である。

【誤答選択肢の解説】
A「夜間せん妄」: 夜間せん妄では意識が混濁し、日中の記憶も断片的で、夢として想起されない。
B「睡眠時遊行症」: 睡眠時遊行症はノンレム睡眠中に生じ、本人は出来事を覚えていない。小児に多い。
C「ナルコレプシー」: ナルコレプシーは日中の耐えがたい眠気と情動脱力発作が主症状である。日中の異常はない。
D「むずむず脚症候群」: むずむず脚症候群は入眠時の下肢の不快感と動かしたい衝動が主症状である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A047（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-5', '正答は B「湿性咳嗽」。

特発性肺線維症の咳嗽は痰を伴わない乾性咳嗽である。湿性咳嗽は気管支拡張症や慢性気管支炎など気道分泌の増える病態でみられる。

【誤答選択肢の解説】
A「ばち指」: 慢性の低酸素血症を反映してばち指がみられる。
C「体重減少」: 進行すると呼吸仕事量の増大と食欲低下により体重が減る。
D「fine crackles」: 両側背下部に吸気終末のfine crackles(捻髪音)を聴取するのが特徴的である。
E「労作時呼吸困難」: 拡散障害と拘束性換気障害により労作時呼吸困難が徐々に進行する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-53', '正答は D「乳房超音波検査」。

マンモグラフィで腫瘤を指摘され触知もできる。次に行うのは乳房超音波検査で、腫瘤の性状を評価し、その場で針生検の穿刺誘導にも使える。乳癌の診断は視触診・画像・病理の三者で進める。

【誤答選択肢の解説】
A「頭部MRI」: 頭部MRIは転移の検索であり、診断が確定する前に行うものではない。
B「乳房MRI」: 乳房MRIは広がり診断に用いるもので、まず行う検査ではない。
C「胸部造影CT」: 胸部造影CTも病期診断の段階の検査である。
E「骨シンチグラフィ」: 骨シンチグラフィは骨転移の検索で、確定診断の後に必要に応じて行う。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A053（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-55', '正答は A「結核性髄膜炎」。

亜急性に進む頭痛と発熱、意識障害に脳神経麻痺(外転神経・顔面神経)を伴い、脳脊髄液は単核球優位の細胞増多、糖の低下、蛋白の上昇、ADA上昇を示しており結核性髄膜炎である。頭蓋底の癒着性炎症が脳神経麻痺を招く。

【誤答選択肢の解説】
B「重症筋無力症」: 重症筋無力症は日内変動する眼瞼下垂や複視が主で、発熱や髄液異常は伴わない。
C「正常圧水頭症」: 正常圧水頭症は歩行障害・認知機能低下・尿失禁が三徴で、CTで脳室拡大を認めるが本例では認めない。
D「多発性硬化症」: 多発性硬化症では髄液の糖は低下しない。
E「Bell麻痺」: Bell麻痺は末梢性顔面神経麻痺のみで、髄膜刺激徴候や意識障害を伴わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A055（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-58', '正答は C「「専門の病院に紹介しましょう」」。

生後1か月で哺乳力が低下し、舌の線維束攣縮、弱い泣き声、腹式呼吸(奇異呼吸)、四肢の筋力低下を認めており脊髄性筋萎縮症I型が疑われる。治療可能な時期が限られるため、速やかに専門施設へ紹介する。

【誤答選択肢の解説】
A「「人工乳に変えましょう」」: 哺乳に時間がかかるのは栄養の種類ではなく筋力の問題であり、人工乳にしても解決しない。
B「「感冒薬を服用しましょう」」: 感冒を示す所見はない。
D「「1か月後に再受診してください」」: 進行性の疾患であり、1か月の経過観察は許されない。
E「「うつ伏せにして寝かせましょう」」: うつ伏せ寝は乳幼児突然死症候群の危険因子であり、勧めてはならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A058（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-59', '正答は A「尿素呼気試験」。

血小板のみが減少し、他の血球と凝固に異常なく、骨髄で巨核球はむしろ増えており免疫性血小板減少性紫斑病である。Helicobacter pylori感染があれば除菌で血小板が回復する例があるため、尿素呼気試験で感染の有無を確かめて治療方針を決める。

【誤答選択肢の解説】
B「血小板凝集能検査」: 血小板凝集能検査は血小板無力症など機能異常を疑うときの検査で、数の減少の評価には用いない。
C「抗リン脂質抗体検査」: 抗リン脂質抗体は血栓症の評価に用いる。出血傾向の本例では治療方針を左右しない。
D「組織適合抗原〈HLA〉検査」: HLA検査は輸血不応や移植の適合性をみるためのもので、初期の治療方針決定には要らない。
E「抗ADAMTS-13抗体検査」: 抗ADAMTS-13抗体は血栓性血小板減少性紫斑病で調べる。溶血性貧血や腎障害、神経症状を欠く本例では考えにくい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A059（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-6', '正答は D「膵管癌 — 膵・胆管合流異常症」。

膵・胆管合流異常症では膵液が胆道へ逆流し、胆道癌(とくに胆囊癌)の危険因子となる。膵管癌の原因ではないので、この組合せが誤りである。

【誤答選択肢の解説】
A「肝細胞癌 — 肝硬変」: 肝細胞癌の大部分は肝炎ウイルスやアルコール、脂肪性肝疾患による肝硬変を背景に発生する。正しい組合せである。
B「食道腺癌 — Barrett食道」: 胃食道逆流により生じたBarrett食道は食道腺癌の前癌病変である。正しい組合せである。
C「胆道癌 — 先天性胆道拡張症」: 先天性胆道拡張症は膵・胆管合流異常を伴い、胆道癌の危険が高い。正しい組合せである。
E「胃癌 — ヘリコバクター・ピロリ感染症」: ヘリコバクター・ピロリの持続感染は萎縮性胃炎を経て胃癌の原因となる。正しい組合せである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-60', '正答は B「眼底検査」。

血圧228/132mmHgに腎機能障害と低カリウム血症を伴い、高血圧緊急症が疑われる。眼底で乳頭浮腫や軟性白斑・出血があれば臓器障害が進行していることになり、降圧の速度と目標を決める判断材料になる。

【誤答選択肢の解説】
A「頭部CT」: 神経診察に異常がなく、頭蓋内病変を疑う所見はない。
C「頸動脈エコー検査」: 29歳で頸動脈の動脈硬化を評価する意義は乏しい。
D「腹部エックス線撮影」: 腹部エックス線撮影で得られる情報はほとんどない。
E「足関節上腕血圧比〈ABI〉」: 足関節上腕血圧比は末梢動脈疾患の評価で、緊急の降圧方針を左右しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A060（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-62', '正答は A「West症候群」。

生後7か月で、両上肢を挙上し頭部を前屈する動作が数秒〜十数秒間隔で反復し(シリーズ形成)、同時に発達の退行がみられており West症候群(点頭てんかん)である。脳波でヒプスアリスミアを確認し、ビガバトリンやACTH療法を行う。

【誤答選択肢の解説】
B「欠神てんかん」: 欠神てんかんは学童期に始まる数秒の意識消失発作で、発達の退行は伴わない。
C「Lennox-Gastaut症候群」: Lennox-Gastaut症候群は幼児期以降に多彩な発作型で発症し、West症候群から移行することがある。
D「先天性筋強直性ジストロフィー」: 先天性筋強直性ジストロフィーは出生時からの筋緊張低下と哺乳障害が主で、発作性の動作ではない。
E「福山型先天性筋ジストロフィー」: 福山型先天性筋ジストロフィーも筋力低下と精神運動発達遅滞が主体で、シリーズ形成する発作は特徴でない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A062（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-63', '正答は E「カタル期には核酸増幅検査が診断に有用である。」。

百日咳のカタル期は感冒と区別しにくいが、菌量が多く感染力も強い時期で、核酸増幅検査(LAMP法など)の感度が高い。培養と抗体価は時期や日数の制約が大きく、早期診断には核酸増幅検査が有用である。

【誤答選択肢の解説】
A「空気感染する。」: 百日咳は飛沫感染で、空気(飛沫核)感染はしない。
B「潜伏期は2、3日である。」: 潜伏期は7〜10日程度で、2、3日ではない。
C「痙咳期に呼気喘鳴を聴取する。」: 痙咳期に聴かれるのは、発作性の咳の後に息を吸い込むときの笛声(吸気性のwhoop)である。呼気喘鳴ではない。
D「セフェム系抗菌薬が有効である。」: 百日咳菌にセフェム系は無効で、マクロライド系が第一選択である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A063（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-64', '正答は B「2」。

尿中ナトリウムが10mEq/Lと低いことは、尿細管でナトリウムを最大限に再吸収していることを示し、腎前性の急性腎障害を裏づける。腎性であれば尿細管が障害されて再吸収できず、尿中ナトリウムは高くなる。

【誤答選択肢の解説】
A「1」: 尿量の減少は急性腎障害そのものを示す所見で、原因の鑑別には役立たない。
C「3」: Hb10.0g/dLの貧血は原因の鑑別に結びつかない。
D「4」: クレアチニンの上昇は腎障害があることを示すだけで、原因の区別はできない。
E「5」: 高カリウム血症は腎機能低下の結果であり、これも原因の鑑別にはならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A064（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-65', '正答は E「立ち上がり・立位保持訓練」。

端座位はほぼ自立しているが、立ち上がりと立位保持には中等度の介助を要する。到達している段階の一つ先に目標を置くのが原則で、立ち上がりと立位保持の訓練を行う。

【誤答選択肢の解説】
A「歩行訓練」: 立位が保てない段階で歩行訓練には進めない。
B「座位訓練」: 端座位はすでにほぼ自立しており、座位訓練は目標として低すぎる。
C「階段昇降訓練」: 階段昇降は歩行が安定してから取り組む段階である。
D「右手での書字訓練」: 右上肢は肘屈曲1、手指伸展0で、書字ができる筋力ではない。利き手交換はもっと先の課題である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A065（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-66', '正答は D「呼吸筋麻痺」。

上位運動ニューロン徴候(腱反射亢進、Babinski徴候陽性)と下位運動ニューロン徴候(筋萎縮、線維束性収縮)が併存し、感覚は正常で眼球運動も保たれており筋萎縮性側索硬化症である。進行すると呼吸筋が麻痺し、呼吸不全が予後を規定する。

【誤答選択肢の解説】
A「褥瘡」: 褥瘡は陰性四徴の一つで、末期まで生じにくいとされる。
B「複視」: 眼球運動障害も陰性四徴の一つで、複視はきたしにくい。
C「排尿障害」: 膀胱直腸障害も陰性四徴に含まれ、排尿障害は生じにくい。
E「起立性低血圧」: 自律神経は比較的保たれ、起立性低血圧は特徴的でない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A066（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-7', '正答は B「たばこパッケージの警告表示」。

たばこのパッケージには、健康被害に関する警告文の表示が法令で義務づけられている。表示面積の拡大など段階的に強化されてきた。

【誤答選択肢の解説】
A「たばこ広告の禁止」: 広告は業界の自主規制などで制限されているが、全面禁止には至っていない。
C「ニコチン依存症の治療の無料化」: 禁煙治療は一定の要件を満たせば保険が適用されるが、無料ではない。
D「公共施設の屋内における空間分煙の義務化」: 健康増進法の改正で多くの施設は屋内原則禁煙となっており、分煙の義務化ではない。
E「非喫煙者に対する医療保険の保険料の減額」: 喫煙の有無で医療保険の保険料を変える仕組みはない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-8', '正答は A「自然治癒する。」。

痔瘻は肛門腺の感染から生じた瘻管が残ったもので、自然に治ることはない。瘻管を処理する手術が唯一の根治手段である。

【誤答選択肢の解説】
B「Crohn病に合併する。」: Crohn病では難治性の痔瘻を合併することが多く、痔瘻から診断に至ることもある。
C「肛門癌の原因になる。」: 長年放置した痔瘻からは痔瘻癌が発生しうる。
D「肛門周囲膿瘍で発症する。」: 肛門周囲膿瘍が自壊または切開排膿された後に瘻管が残って痔瘻となる。
E「便意とは関係なく排膿する。」: 瘻管の外口から便意と無関係に膿が出る。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-A-9', '正答は D「自己誘発嘔吐と下剤乱用を反復することが多い。」。

神経性過食症では、過食の後に体重増加を防ごうとして自己誘発嘔吐や下剤・利尿薬の乱用といった代償行動を反復する。嘔吐による低カリウム血症、う蝕、手背のタコ(Russell徴候)に注意する。

【誤答選択肢の解説】
A「自己肯定感が高い。」: 自己評価が体型や体重に強く左右され、自己肯定感はむしろ低い。
B「過活動になることが多い。」: 過活動が目立つのは神経性やせ症のほうである。
C「肥満に対する恐怖心はない。」: 体重が増えることへの強い恐怖があり、それが代償行動の動機になる。
E「食事をコントロールできるという感覚は保たれる。」: 過食の最中は食べることを制御できないという感覚を伴うのが特徴である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 A009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-1', '正答は D「薬剤師」。

採血(静脈路からの採血を含む)は診療の補助として、看護師・准看護師・保健師・助産師と臨床検査技師が医師の指示のもとで行える。薬剤師の業務は調剤と服薬指導であり、採血は含まれない。

【誤答選択肢の解説】
A「看護師」: 看護師は診療の補助として採血できる。
B「助産師」: 助産師も看護師の業務を行えるので採血できる。
C「保健師」: 保健師も同様に採血できる。
E「臨床検査技師」: 臨床検査技師は法令上、採血が明記された業務である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-10', '正答は E「患者の機能障害の固定を目標とする。」。

リハビリテーションは機能障害を固定させることではなく、残された機能を最大限に生かして活動と参加を高め、その人らしい生活を取り戻すことを目指す。

【誤答選択肢の解説】
A「発症後早期に開始する。」: 廃用症候群を防ぐため、全身状態が許せば早期から開始する。
B「患者の社会参加を支援する。」: 就労や地域での役割を含む社会参加の支援は目標の中心にある。
C「患者の生活機能の改善を目指す。」: 国際生活機能分類でいう生活機能全体の改善を目指す。
D「患者の目標を多職種で共有する。」: 医師、看護師、療法士、社会福祉士などが目標を共有してチームで取り組む。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-11', '正答は B「研究で知り得た情報を公開する権利がある。」。

患者・市民参画は研究の企画や実施に患者や市民の視点を取り入れる取組みで、参画者は研究協力者として守秘義務を負う。研究で知り得た情報を自ら公開する権利をもつわけではない。

【誤答選択肢の解説】
A「研究初期からパートナーとして参画する。」: 研究テーマの設定など初期段階から対等なパートナーとして加わることが求められる。
C「研究対象者の負担が軽減されるように助言する。」: 検査の回数や来院負担など、対象者の立場からの助言が期待される。
D「研究倫理審査委員会へ一般の立場の委員として参加する。」: 倫理審査委員会には一般の立場を代表する委員が加わることになっている。
E「研究に関連する文書が分かりやすい表現になるように助言する。」: 説明文書や同意文書が分かりやすい表現になるよう助言することは重要な役割である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-14', '正答は E「慢性閉塞性肺疾患〈COPD〉」。

慢性閉塞性肺疾患の最大の危険因子は喫煙で、飲酒は危険因子とされていない。

【誤答選択肢の解説】
A「食道癌」: アルコールはアセトアルデヒドを介して食道扁平上皮癌の危険を高める。
B「認知症」: 多量飲酒は認知症の危険因子として知られる。
C「骨粗鬆症」: 飲酒は骨形成を妨げ、転倒も増えるため骨粗鬆症と骨折の危険因子である。
D「Wernicke脳症」: 慢性のアルコール多飲によるビタミンB1欠乏がWernicke脳症を引き起こす。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B014（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-15', '正答は B「処方日数の短期化」。

処方日数が短くなることはポリファーマシーの原因にならない。むしろ長期処方や残薬の把握不足が薬剤の重複を招く。

【誤答選択肢の解説】
A「多疾患の併存」: 複数の疾患それぞれに標準治療を積み上げると薬剤数が増える。
C「複数医療機関からの処方」: 複数の医療機関がそれぞれ処方すれば、重複や相互作用が生じる。
D「薬剤自己管理能力の低下」: 自己管理能力が落ちると残薬が増え、実際の服用状況が把握できなくなる。
E「医療機関と薬局の連携の欠如」: お薬手帳などによる情報共有が働かないと、重複処方を見つけられない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B015（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-16', '正答は A「新生児」。

新生児では体重の約75〜80%が水分で、そのうち細胞外液が約40%と最も高い割合を占める。成長とともに細胞外液の割合は減り、成人では約20%になる。このため新生児・乳児は脱水に陥りやすい。

【誤答選択肢の解説】
B「乳児」: 乳児では細胞外液の割合が新生児より下がる。
C「幼児」: 幼児ではさらに下がる。
D「学童」: 学童では成人に近づく。
E「成人」: 成人の細胞外液は体重の約20%で最も低い。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B016（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-17', '正答は B「感度の高い検査が陰性のとき」。

感度の高い検査が陰性であれば偽陰性が少ないので、その疾患をほぼ否定できる。逆に特異度の高い検査が陽性であれば偽陽性が少なく、確定診断に近づく。

【誤答選択肢の解説】
A「感度の高い検査が陽性のとき」: 感度の高い検査の陽性は偽陽性を多く含みうるので、確定には向かない。
C「特異度の高い検査が陽性のとき」: 特異度の高い検査の陽性は確定(rule in)に有用で、除外には使わない。
D「特異度の高い検査が陰性のとき」: 特異度の高い検査が陰性でも偽陰性が多く、除外はできない。
E「感度/(1-特異度)が1より大きいとき」: 感度/(1−特異度)は陽性尤度比で、1より大きいことは検査後確率が上がることを示す。除外の指標ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-19', '正答は A「「症状をあげていただけますか」」。

解釈モデルは患者が自分の病気の原因、経過、意味、望む治療をどう考えているかである。症状を列挙してもらうのは事実の情報収集であり、患者の考えを引き出す問いではない。

【誤答選択肢の解説】
B「「どんな治療が必要になるとお考えですか」」: どんな治療が要ると考えるかは、治療への期待を尋ねる問いである。
C「「病気が治ったら生活はどう変わりますか」」: 治ったら生活がどう変わるかは、病気が生活に与える影響と期待を尋ねる問いである。
D「「原因について思い当たることはありますか」」: 原因について思い当たることを尋ねるのは、解釈モデルの中核である。
E「「病気があることでどのようにお困りですか」」: 困りごとを尋ねるのは、病気が生活に及ぼす影響を知る問いである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-2', '正答は E「前立腺は、直腸指診で腹側に触知する。」。

前立腺は直腸の腹側(前方)にあるため、直腸指診で指の腹側に触れる。大きさ、硬さ、表面の性状、圧痛を確かめる。

【誤答選択肢の解説】
A「肝臓は、双手診で裏面を触知する。」: 肝は深吸気時に下降した下縁を触知する。裏面を触れることはできない。
B「膵臓は、深呼気時に触知する。」: 膵は後腹膜の深部にあり、健常者では触知できない。
C「腎臓は、深吸気時に上極を触知する。」: 腎は深吸気時に下降した下極を触れることがある。上極は触れない。
D「膀胱は、直腸指診で背側に触知する。」: 膀胱は恥骨結合の背側、直腸の腹側にあり、直腸指診では指の腹側に触れる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-20', '正答は C「「盗聴器を体に埋め込まれて監視されています」」。

盗聴器を埋め込まれて監視されているという確信は、事実に反する内容を訂正できずに保持する妄想(被害妄想・注察妄想)である。

【誤答選択肢の解説】
A「「床に小さな虫が沢山見えます」」: 存在しない虫が見えるのは幻視である。
B「「母親の声で名前を呼ばれるのが聞こえます」」: 実際にはない声が聞こえるのは幻聴である。
D「「腹の中にあるゴムの球が動き回るのを感じます」」: 腹の中で球が動くという体感の異常は体感幻覚(セネストパチー)である。
E「「何を食べても砂を嚙んでいるようでおいしくないです」」: 何を食べても砂のように感じるのは味覚の異常である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B020（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-21', '正答は C「大量飲酒 — 肺塞栓症」。

大量飲酒で問題になるのは離脱症状、肝機能障害、麻酔薬の必要量の増加などで、肺塞栓症とは結びつかない。肺塞栓症の危険因子は長期臥床、肥満、悪性腫瘍、下肢静脈瘤などである。

【誤答選択肢の解説】
A「喫煙 — 術後無気肺」: 喫煙は気道分泌の増加と線毛運動の低下を招き、術後無気肺や肺炎の危険を高める。正しい組合せである。
B「開口障害 — 気道確保困難」: 開口障害があると喉頭展開ができず、気道確保が困難になる。正しい組合せである。
D「抗凝固薬服用中 — 止血困難」: 抗凝固薬の継続は術中術後の止血困難につながる。正しい組合せである。
E「バナナ摂取後の蕁麻疹 — ラテックスアレルギー」: バナナ・アボカド・キウイなどで蕁麻疹が出る人はラテックスと交差反応を示す。正しい組合せである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B021（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-22', '正答は B「Kernig徴候 — 髄膜炎」。

Kernig徴候は股関節と膝関節を屈曲させた状態から膝を伸展させようとすると抵抗と疼痛が生じる所見で、髄膜刺激徴候の一つである。項部硬直やBrudzinski徴候とともに髄膜炎を疑う。

【誤答選択肢の解説】
A「えくぼ徴候 — 女性化乳房」: えくぼ徴候は乳癌でCooper靱帯が引かれて皮膚が陥凹する所見である。
C「Chvostek徴候 — 胸水貯留」: Chvostek徴候は顔面神経を叩くと顔面筋が収縮する所見で、低カルシウム血症を示す。
D「Blumberg徴候 — 停留精巣」: Blumberg徴候は反跳痛で、腹膜刺激徴候である。
E「Grey-Turner徴候 — 尿路結石」: Grey-Turner徴候は側腹部の皮下出血斑で、重症急性膵炎などの後腹膜出血を示す。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-23', '正答は D「医療の安全の確保に資することを目的とする。」。

医療事故調査制度は医療法に基づき、原因を明らかにして再発を防ぎ、医療の安全を確保することを目的とする。責任追及のための仕組みではない。

【誤答選択肢の解説】
A「刑法に規定されている。」: 根拠法は医療法である。
B「警察に通報してから調査を開始する。」: 警察への通報を前提とする制度ではない。異状死の届出は医師法に基づく別の手続きである。
C「診療に起因した死亡全てが対象となる。」: 対象は医療に起因する、または起因すると疑われる死亡のうち、管理者が予期しなかったものに限られる。
E「調査が終了するまで、医療機関は事故の説明を遺族にしてはならない。」: 調査の状況や結果は遺族に説明することとされている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B023（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-24', '正答は D「「知らない人と会うと非常に緊張する」」。

社交〈社会〉不安障害は、他人から注視され評価される場面で強い不安と身体症状が生じ、そうした場面を避けるようになる病態である。初対面の人と会うときの著しい緊張はその典型である。

【誤答選択肢の解説】
A「「MRI検査が怖い」」: 閉所での恐怖は限局性恐怖症(閉所恐怖)にあたる。
B「「世間の人々から嫌われている」」: 世間の人々から嫌われているという確信は関係妄想や被害妄想である。
C「「明日にも何か大変なことが起こる」」: 漠然と大変なことが起こる予感は全般性不安障害でみられる。
E「「外出時、自宅に鍵をかけたか数十回確認する」」: 施錠の確認を何十回も繰り返すのは強迫性障害の確認強迫である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-25', '正答は E「インフォームド・アセント」。

インフォームド・アセントは、同意能力が十分でない未成年者に理解力に応じた説明を行い、本人の納得(賛意)を得ることをいう。法的な同意は代諾者から得たうえで、本人の意思も尊重する。

【誤答選択肢の解説】
A「オプトアウト」: オプトアウトは既存の資料を用いる研究などで、拒否の機会を保障して情報公開する方式である。
B「パターナリズム」: パターナリズムは医療者が患者に代わって決めてしまう考え方である。
C「リビングウィル」: リビングウィルは終末期医療についての事前の意思表示である。
D「セカンドオピニオン」: セカンドオピニオンは別の医師に意見を求めることである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-26', '正答は E「「薬を始めないのであれば、他の医療機関を受診していただけますか」」。

他の医療機関の受診を促すのは、治療方針に同意しないことを理由に診療関係を切ることになり、診療を拒む正当な事由にあたらない。通院を続ける意思がある以上、対話を重ねて合意点を探るべきである。

【誤答選択肢の解説】
A「「どのような治療なら実践可能だと思いますか」」: 実行できる治療を患者自身に考えてもらう問いは、行動変容を促すうえで適切である。
B「「どのようなことを治療の目標と考えていますか」」: 患者が何を目標としているかを共有することは方針の擦り合わせに役立つ。
C「「改めて薬を始めたくない理由をお話しいただけますか」」: 服薬を避けたい理由を聞くことは、誤解や不安の把握につながる。
D「「いまの糖尿病の状態が続くと、どうなると考えていますか」」: このままの状態が続いた場合をどう考えているかを尋ねるのは、認識のずれを確かめる適切な問いである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B026（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-27', '正答は D「睡眠を妨げる痛み」。

癌性疼痛の緩和は、まず夜間の睡眠が妨げられない状態を目指し、次に安静時の痛みの消失、最後に体動時の痛みの消失という順に段階的に目標を上げていく。本例は睡眠を妨げる痛みが主訴でもある。

【誤答選択肢の解説】
A「歩行時の痛み」: 歩行時の痛みは体動時痛で、最終段階の目標にあたる。
B「立位時の痛み」: 立位時の痛みも体動時痛にあたる。
C「階段昇降時の痛み」: 階段昇降時の痛みも同様に体動時痛である。
E「重い荷物を持ち上げる時の痛み」: 重い荷物を持ち上げるときの痛みは負荷が最も大きく、緩和の目標として最後になる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B027（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-28', '正答は D「この患者への診療をさし控える。」。

サプリメントを使いたいという申し出を理由に診療を控えることは、診療の拒否にあたり許されない。希望の背景を聴き、薬物相互作用などの情報を集めて一緒に判断するのが適切な対応である。

【誤答選択肢の解説】
A「患者の思いを丁寧に聞く。」: なぜ使いたいのかという思いを丁寧に聴くことが出発点になる。
B「医療チームで情報共有する。」: 訪問看護師や薬剤師と情報を共有して安全性を確かめる。
C「費用負担について確認する。」: 自費となるため、生活への負担を確認することは適切である。
E「サプリメントに関する医療情報を収集する。」: 成分と内服薬との相互作用について情報を集めることは医師の役割である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B028（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-29', '正答は A「喀痰抗酸菌染色」。

空気感染予防策を始めるかどうかは、周囲に菌を排出しているか(排菌の有無)で決まる。喀痰抗酸菌染色(塗抹検査)は数時間で結果が出て菌量も分かるので、隔離の判断に直結する。

【誤答選択肢の解説】
B「喀痰抗酸菌培養」: 培養は結果が出るまで数週間かかり、隔離の判断には間に合わない。
C「ツベルクリン反応」: ツベルクリン反応は感染の既往をみるもので、排菌の有無は分からない。生物学的製剤の使用下では偽陰性にもなる。
D「気管支肺胞洗浄〈BAL〉培養」: 気管支肺胞洗浄は侵襲が大きく、まず喀痰で調べる。
E「結核菌特異的全血インターフェロンガンマ遊離測定法〈IGRA〉」: IGRAも感染の有無をみる検査で、活動性や排菌の判断はできない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B029（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-3', '正答は D「熱性けいれん」。

熱性けいれんは生後6か月から5歳ごろに好発し、有熱時けいれんの大半を占める。2歳児のけいれんの原因として最も頻度が高い。

【誤答選択肢の解説】
A「急性脳症」: 急性脳症は熱性けいれんに比べてはるかにまれである。
B「てんかん」: てんかんの有病率は約1%で、この年齢のけいれんの主因ではない。
C「細菌性髄膜炎」: 細菌性髄膜炎はワクチンの普及で著減しており、頻度は低い。
E「憤怒けいれん〈泣き入りひきつけ〉」: 憤怒けいれんは啼泣に伴う無熱性のもので、熱性けいれんより頻度が低い。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-30', '正答は C「「どうすれば体重を減らせると思いますか」」。

減量したい気持ちはあるが、仕事の忙しさを理由に行動に移せていない関心期である。具体的な指示を与えるより、どうすればできそうかを本人に考えてもらい、障壁を一緒に整理することが有効である。

【誤答選択肢の解説】
A「「このままだと将来、血液透析が必要になります」」: 脅すような伝え方は防衛的な反応を招き、関係を損ないやすい。
B「「本気で減量したくなったら受診してください」」: 受診の継続を遠ざける声かけで、支援の機会を失う。
D「「半年で5kgの減量を頑張りましょう」」: 具体的な数値目標の設定は、行動を始める準備が整った準備期以降に適する。
E「「毎日30分間歩きましょう」」: 運動する時間がないと述べている段階で一律の運動処方を与えても実行につながらない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B030（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-31', '正答は E「5」。

毛細血管再充満時間4秒は末梢循環不全を示し、代償性ショックを疑う所見である。乳児では血圧が下がるのは代償が破綻した後なので、皮膚所見での早期認識が重要になる。

【誤答選択肢の解説】
A「1」: 体温37.1°Cは発熱とはいえない。
B「2」: 心拍数120/分は1か月児として正常範囲である。
C「3」: 血圧80/50mmHgもこの月齢で保たれている値である。
D「4」: 呼吸数36/分も1か月児では正常範囲である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B031（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-32', '正答は E「「転倒に気をつけて片足立ちやスクワットをしましょう」」。

歩行距離が短くなりつまずきが増えており、ロコモティブシンドロームの段階にある。片脚立ちとスクワットは下肢筋力とバランスを鍛えるロコモーショントレーニングの中心で、転倒に注意しながら続けるよう勧める。

【誤答選択肢の解説】
A「「禁酒をしましょう」」: ビール350mLを週3回は節度ある適度な飲酒の範囲内で、禁酒を求める根拠はない。
B「「外出は控えましょう」」: 外出を控えれば活動量が落ちてさらに運動機能が低下する。
C「「体重を減らしましょう」」: BMI24.4は肥満ではなく、高齢者では過度の減量が筋肉量の減少を招く。
D「「腰痛が治まるまでベッド上で安静にしましょう」」: 腰痛に対する長期の安静はかえって回復を遅らせる。動ける範囲で活動を保つのがよい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B032（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-33', '正答は E「胃管を55cmまで挿入し胸部エックス線写真で胃管先端が胃内にあることを確認し再開する。」。

胃管が30cm抜けており、入れ直した後は先端が胃内にあることを確かめてから注入する。最も確実なのは胸部エックス線写真での確認で、気管内への誤挿入を見逃さない。

【誤答選択肢の解説】
A「そのまま再開する。」: 先端の位置が分からないまま注入すれば、気道に流入して致死的になる。
B「胃管を55cmまで挿入し再開する。」: 挿入長だけでは食道内や気管内にあることを否定できない。
C「胃管を55cmまで挿入し心窩部で空気注入音を聴取し再開する。」: 空気注入音の聴取は気管内にあっても聞こえることがあり、確認法として不確実である。
D「胃管を55cmまで挿入し水を注入して胃管の開通を確認し再開する。」: 水の注入は、気管内にあれば誤嚥そのものになる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B033（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-35', '正答は A「胸腔穿刺」。

胸部強打後に、患側の胸郭膨隆・鼓音・呼吸音減弱に加えて頸静脈怒張と血圧低下がそろっており緊張性気胸である。画像を待たずにただちに胸腔穿刺で脱気し、続いて胸腔ドレーンを留置する。

【誤答選択肢の解説】
B「低体温療法」: 低体温療法は心停止後の脳保護に用いるもので、この状況の治療ではない。
C「浸透圧利尿薬投与」: 浸透圧利尿薬は脳浮腫に用いる。頭蓋内圧亢進を示す所見はない。
D「乳酸リンゲル液大量投与」: 閉塞性ショックであり、大量輸液では静脈還流の障害は解除できない。
E「非侵襲的陽圧換気〈NPPV〉」: 陽圧換気は胸腔内圧をさらに高め、緊張性気胸を悪化させる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B035（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-37', '正答は D「ペニシリン系薬」。

パートナーに無痛性の陰茎潰瘍(初期硬結)の治療歴があり、本人には手掌・足底の紅斑丘疹と無痛性のリンパ節腫脹がみられる。第2期梅毒であり、治療の第一選択はペニシリン系薬である。

【誤答選択肢の解説】
A「抗真菌薬」: 真菌感染ではない。
B「抗ウイルス薬」: 細菌(スピロヘータ)による感染であり、抗ウイルス薬は無効である。
C「セフェム系薬」: セフェム系は梅毒の標準治療薬ではない。
E「カルバペネム系薬」: カルバペネム系も適応ではない。ペニシリンアレルギーがある場合はドキシサイクリンなどを用いる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B037（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-38', '正答は E「5」。

参加制約は、生活・人生の場面に関わるときに生じる困難である。趣味の俳句教室に通えなくなり家に閉じこもりがちになっていることが、社会参加が妨げられている状態にあたる。

【誤答選択肢の解説】
A「1」: マンションに一人暮らしという住環境は環境因子にあたる。
B「2」: 長距離を歩けないことは活動制限にあたる。
C「3」: おしゃべり好きという性格は個人因子にあたる。
D「4」: 入口の階段という物理的な障壁は環境因子にあたる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B038（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-39', '正答は D「腹部超音波検査」。

高度の蛋白尿と低アルブミン血症、高コレステロール血症、浮腫がそろいネフローゼ症候群である。血液が濃縮し(Ht55%)腎機能も悪化しており、腎静脈血栓症の合併を疑って、まず侵襲のない腹部超音波検査で腎の大きさと血流を評価する。

【誤答選択肢の解説】
A「膀胱鏡検査」: 膀胱鏡検査は肉眼的血尿の原因検索に用いる。潜血は陰性である。
B「レノグラム」: レノグラムは分腎機能の評価で、初期評価としての優先度は低い。
C「腹部造影CT」: クレアチニン1.9mg/dLと腎機能が低下しており、造影剤の使用は慎重を要する。
E「腹部エックス線撮影」: 腹部エックス線撮影で得られる情報はほとんどない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B039（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-4', '正答は E「Courvoisier徴候陽性」。

Courvoisier徴候は無痛性に腫大した胆囊を触れる所見で、膵頭部癌など遠位胆管の悪性閉塞を示唆する。腹膜炎の所見ではない。

【誤答選択肢の解説】
A「反跳痛」: 反跳痛(Blumberg徴候)は腹膜刺激徴候の代表である。
B「筋性防御」: 筋性防御は腹壁筋の反射性収縮で、腹膜炎を示す。
C「打診による圧痛」: 打診による圧痛は腹膜刺激徴候を捉える感度の高い方法である。
D「踵下ろし試験陽性」: つま先立ちから踵を落として腹痛が誘発される踵下ろし試験は腹膜刺激徴候をみる手技である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-40', '正答は C「血小板数」。

妊娠32週の高血圧に、頭痛・眼華閃発・心窩部痛という中枢神経症状と肝被膜伸展の症状が加わっており、HELLP症候群を含む重症の妊娠高血圧腎症である。溶血、肝酵素上昇、血小板減少が三徴で、低下するのは血小板数である。

【誤答選択肢の解説】
A「LD」: 溶血を反映してLDは上昇する。
B「AST」: 肝細胞障害によりASTは上昇する。
D「ヘマトクリット値」: 溶血が進めばヘマトクリットは下がりうるが、血管透過性亢進による血液濃縮で上昇することも多く、必発の低下所見ではない。
E「尿蛋白/クレアチニン比」: 腎障害の進行により尿蛋白/クレアチニン比は上昇する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B040（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-5', '正答は E「抜去した内針はリキャップをする。」。

使用した針のリキャップは針刺し事故の主要な原因で、行ってはならない。抜いた内針はそのまま専用の耐貫通性容器に廃棄する。

【誤答選択肢の解説】
A「穿刺前に皮膚を消毒する。」: 刺入部の皮膚はアルコールなどで消毒し、乾いてから穿刺する。
B「皮膚面に15〜30度の角度で穿刺する。」: 浅い角度で刺入するのが基本で、15〜30度が目安である。
C「血液の流出を確認後に内針とカテーテル(外筒)を少し進める。」: 逆血を確認した時点では内針だけが血管内にあるので、少し進めてから外筒を送る。
D「駆血帯を外してから内針を抜去する。」: 駆血帯を外してから内針を抜くと、血液の噴出を防げる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-6', '正答は B「改善策の記述を含める。」。

インシデントレポートは事実の記載にとどまらず、なぜ起きたかの分析と再発を防ぐための改善策までを含めて初めて意味をもつ。個人の責任追及ではなく仕組みの改善に用いる。

【誤答選択肢の解説】
A「保健所に提出する。」: 提出先は院内の医療安全管理部門であって保健所ではない。
C「作成するのは患者である。」: 作成するのは事象に関与した、あるいは発見した医療従事者である。
D「内容を医療機関のホームページで公開する。」: 個人情報を含むため一般に公開するものではない。
E「提出レポート数が少ない医療機関は安全度が高い。」: 報告数が少ないのは報告しにくい風土を示すことがあり、安全度の高さを意味しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-7', '正答は C「関節液」。

T2強調像では自由水を多く含む組織ほど高信号になる。関節液は水そのものなので著明な高信号を示し、関節水腫の評価に用いる。

【誤答選択肢の解説】
A「腱」: 腱は緻密な線維組織で水分に乏しく、T1・T2ともに低信号である。
B「靱帯」: 靱帯も同様に低信号である。
D「骨皮質」: 骨皮質は可動性のプロトンがほとんどなく、無信号に近い。
E「半月板」: 半月板は線維軟骨で低信号を示し、内部に高信号が入れば断裂を疑う。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-8', '正答は C「副甲状腺」。

副甲状腺は米粒大で甲状腺の背側にあり、正常では触知できない。触れるほど大きくなっていれば腺腫や癌を疑う。

【誤答選択肢の解説】
A「顎下腺」: 顎下腺は下顎角の内側で双手診により触知できる。
B「頸動脈」: 頸動脈は胸鎖乳突筋の内側で拍動として触知できる。
D「輪状軟骨」: 輪状軟骨は甲状軟骨の下方に輪状の隆起として触れる。
E「胸鎖乳突筋」: 胸鎖乳突筋は頭部を対側に回旋させると明瞭に触知できる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-B-9', '正答は E「症例対照研究よりエビデンスレベルが高い。」。

ランダム化比較試験は無作為割付により既知・未知の交絡因子が両群に均等に分かれるため、症例対照研究やコホート研究より高いエビデンスレベルに位置づけられる。

【誤答選択肢の解説】
A「観察研究である。」: 研究者が介入を割り付ける介入研究である。
B「外的妥当性が高い研究である。」: 適格基準を厳しく設けるため対象が限られ、結果を一般の患者に当てはめる外的妥当性はむしろ低くなりやすい。
C「未測定の交絡因子に対応できない。」: 無作為化によって未測定の交絡因子も均等に分かれるので、対応できるのが最大の利点である。
D「有病率の低い疾患の研究に適している。」: まれな疾患では必要な症例数を集めにくく、症例対照研究のほうが適している。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 B009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-1', '正答は D「コレステロール塞栓症」。

コレステロール塞栓症は、カテーテル操作や抗凝固療法を契機に粥腫のコレステロール結晶が末梢へ飛び、網状皮斑や足趾のチアノーゼ、腎機能低下をきたす。異物反応として好酸球増加と低補体血症を伴う。

【誤答選択肢の解説】
A「IgA腎症」: IgA腎症はIgAを含む免疫複合体の沈着による糸球体腎炎で、好酸球は増えない。
B「遺伝性血管性浮腫」: 遺伝性血管性浮腫はC1インヒビターの欠損によるもので、好酸球増加を伴わない。
C「抗リン脂質抗体症候群」: 抗リン脂質抗体症候群は血栓症と習慣流産をきたす病態で、好酸球増加は特徴でない。
E「多発血管炎性肉芽腫症」: 多発血管炎性肉芽腫症は好中球とPR3-ANCAが関与する。好酸球が増えるのは好酸球性多発血管炎性肉芽腫症である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-10', '正答は E「知的障害」。

特別支援学校の対象は、視覚障害・聴覚障害・知的障害・肢体不自由・病弱(身体虚弱を含む)の5つと定められている。知的障害はこれに含まれる。

【誤答選択肢の解説】
A「自閉症」: 自閉症は特別支援学級や通級による指導の対象である。
B「学習障害」: 学習障害も通級による指導の対象である。
C「言語障害」: 言語障害も特別支援学級や通級による指導の対象である。
D「情緒障害」: 情緒障害も特別支援学級や通級による指導の対象である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-11', '正答は D「定期予防接種」。

定期予防接種は予防接種法に規定されている。健康増進法が定めるのは、国民の健康増進の基本方針(健康日本21)、国民健康・栄養調査、受動喫煙の防止、食事摂取基準の策定などである。

【誤答選択肢の解説】
A「健康日本21」: 健康日本21は健康増進法に基づく基本方針として策定される。
B「受動喫煙防止」: 受動喫煙の防止は健康増進法に定められ、2018年の改正で規制が強化された。
C「食事摂取基準」: 日本人の食事摂取基準は健康増進法に基づき厚生労働大臣が定める。
E「国民健康・栄養調査」: 国民健康・栄養調査も健康増進法に基づいて毎年実施される。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-12', '正答は B「左橋病変」。

Babinski徴候は錐体路障害を示す。錐体路は延髄下部で交叉するので、それより上位である橋の病変では対側に徴候が出る。左橋の病変で右のBabinski徴候が陽性となる。

【誤答選択肢の解説】
A「右大脳半球病変」: 右大脳半球の病変では対側の左に錐体路徴候が出る。
C「右小脳病変」: 小脳の病変では運動失調をきたすが、錐体路徴候は出ない。
D「左頸髄病変」: 頸髄では交叉を終えているので、左頸髄の病変は左に徴候を出す。
E「馬尾障害」: 馬尾は末梢神経であり、障害されても腱反射は低下し、Babinski徴候は陰性である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C012（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-13', '正答は E「「自分の考えなど取るに足らない価値のないものです」」。

自我障害は、思考や行動が自分のものであるという感覚(自我意識)が損なわれる症状である。自分の考えに価値がないという訴えは微小妄想や自責感で、うつ状態にみられるもので自我障害ではない。

【誤答選択肢の解説】
A「「自分の考えが他人に操られています」」: 他人に操られるという訴えはさせられ体験(作為体験)である。
B「「自分の考えが抜き取られてしまいます」」: 考えを抜き取られるという訴えは思考奪取である。
C「「自分の考えでない考えが勝手に浮かんできます」」: 自分のものでない考えが浮かぶという訴えは思考吹入である。
D「「自分の考えが電波に乗って世界中に伝わっています」」: 考えが世界に伝わるという訴えは思考伝播である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C013（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-14', '正答は B「3か月で寝返りをする。」。

寝返りができるようになるのは生後5〜6か月ごろで、3か月ではまだできない。3か月で獲得するのは定頸(首のすわり)である。

【誤答選択肢の解説】
A「1か月でMoro反射が認められる。」: Moro反射は生後4〜6か月ごろまでみられるので、1か月で認めるのは正常である。
C「7か月で顔にタオルをかけるとすぐにタオルを取り除く。」: 顔にかけた布をすぐに取り除けるようになるのは生後6〜7か月ごろである。
D「10か月でパラシュート反射が認められる。」: パラシュート反射は生後8〜9か月ごろに出現し、以後生涯残る。
E「12か月で抱き上げて立位にし、前後左右に倒すと足を出して体を支えようとする。」: 立位で傾けたときに足を踏み出して支えるホッピング反応は1歳前後に完成する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C014（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-15', '正答は E「地域の医療従事者に対する研修」。

地域医療支援病院は、かかりつけ医からの紹介患者への医療提供、医療機器の共同利用、救急医療の提供に加えて、地域の医療従事者に対する研修の実施が承認要件とされている。都道府県知事が承認する。

【誤答選択肢の解説】
A「高度医療技術の開発」: 高度医療技術の開発と評価は特定機能病院の要件である。
B「地域住民の栄養改善」: 地域住民の栄養改善は保健所や市町村保健センターが担う。
C「質の高い臨床研究の主導」: 高度な医療技術の開発・研究の主導も特定機能病院の役割である。
D「難病患者の療養生活支援」: 難病患者の療養生活支援は難病相談支援センターが担う。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C015（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-16', '正答は E「子宮頸癌」。

子宮頸癌の大部分はヒトパピローマウイルスの持続感染により生じるため、HPVワクチンの接種で発症を予防できる。定期接種の対象で、キャッチアップ接種も行われている。

【誤答選択肢の解説】
A「胃癌」: 胃癌のワクチンはない。予防はヘリコバクター・ピロリの除菌による。
B「肺癌」: 肺癌のワクチンはない。予防は禁煙である。
C「白血病」: 白血病を予防するワクチンはない。
D「膀胱癌」: 膀胱癌にもワクチンはない。BCGの膀胱内注入は上皮内癌の治療であって予防ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C016（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-18', '正答は B「経済状況」。

CGA7は7項目からなる簡易版で、意欲、認知機能(復唱・遅延再生)、手段的ADL、基本的ADL(入浴・排泄)、情緒・気分を短時間で評価する。経済状況は含まれない。

【誤答選択肢の解説】
A「意欲」: 外来や診察の場面での自発性から意欲を評価する項目がある。
C「認知機能」: 3単語の復唱と遅延再生で認知機能を評価する。
D「基本的ADL」: 入浴と排泄の自立度で基本的ADLを評価する。
E「手段的ADL」: 買い物や食事の準備、金銭管理などで手段的ADLを評価する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C018（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-19', '正答は B「通院が困難な患者」。

訪問診療は、疾病や傷病のために通院による療養が困難な患者に対し、計画的に医師が居宅を訪問して行う医療である。通院困難であることが要件で、疾患名や居住形態では決まらない。

【誤答選択肢の解説】
A「認知症の患者」: 認知症があっても通院できる患者は対象にならない。
C「独居の高齢の患者」: 独居であることは要件ではない。
D「胃瘻が造設されている患者」: 胃瘻が造設されていても、通院できれば対象にならない。
E「夜間に発熱した高齢の患者」: 急な発熱で臨時に往診するのは往診であって、計画的に訪問する訪問診療とは区別される。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-2', '正答は E「気持ちの辛さについて優先順位をつけて対応する。」。

終末期の苦痛は身体・精神・社会・スピリチュアルにわたり、すべてに同時に対応することはできない。患者が今いちばん辛いと感じていることを聴き取り、優先順位をつけて対応する。

【誤答選択肢の解説】
A「不安について医師からは尋ねない。」: 不安や気持ちの辛さは医師から尋ねなければ語られないことが多い。
B「誰でも辛いのだから耐えるよう伝える。」: 耐えるよう促すことは苦痛の否認であり、孤立を深める。
C「希死念慮の話題を始めた時には制止する。」: 希死念慮の話題を制止すると、大切な訴えを聴く機会を失う。安全を確かめながら傾聴する。
D「楽しかった過去の話については聞き流す。」: 過去の思い出を語ることは人生の意味を確かめる作業(ライフレビュー)であり、真剣に聴く。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-20', '正答は A「病院」。

職業性白内障は放射線や赤外線などへの曝露で生じる。医療機関ではエックス線透視やインターベンションに従事する職員が電離放射線に曝露するため、水晶体の等価線量限度が定められ、防護眼鏡の着用が求められる。

【誤答選択肢の解説】
B「印刷工場」: 印刷工場で問題となるのは有機溶剤による中毒で、かつて1,2-ジクロロプロパンによる胆管癌が発生した。
C「縫製工場」: 縫製工場では上肢の反復作業による頸肩腕障害が問題となる。
D「クリーニング工場」: クリーニング工場ではテトラクロロエチレンなど有機溶剤の曝露が問題となる。
E「コンビニエンスストア」: コンビニエンスストアには白内障を起こす特有の曝露はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C020（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-21', '正答は A「外側半規管」。

温度眼振検査は外耳道に冷水や温水、冷風を入れて外側半規管の内リンパに対流を起こし、誘発される眼振を観察する。左右の半規管機能を個別に評価できる唯一の検査で、半規管麻痺の判定に用いる。

【誤答選択肢の解説】
B「外有毛細胞」: 外有毛細胞の機能は耳音響放射で評価する。
C「球形囊」: 球形囊は垂直方向の直線加速度を感じる耳石器で、前庭誘発筋電位で評価する。
D「後半規管」: 後半規管の機能はhead impulse testやDix-Hallpike法で評価する。
E「卵形囊」: 卵形囊は水平方向の直線加速度を感じる耳石器で、眼球反対回旋などで評価する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C021（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-22', '正答は A「65」。

基準集団の年齢階級別死亡率を対象集団の人口に当てはめると、期待死亡数は2,000×100/10万＋4,000×150/10万＋4,000×300/10万＝2＋6＋12＝20人となる。観察された死亡数は1＋4＋8＝13人なので、標準化死亡比は13÷20×100＝65である。

【誤答選択肢の解説】
B「76」: 76は期待死亡数の計算を誤ったときに出る値である。
C「110」: 110は観察死亡数と期待死亡数を取り違えると近い値になる。
D「130」: 130は観察死亡数13をそのまま10倍したもので、期待死亡数で割っていない。
E「170」: 170は基準集団と対象集団を入れ替えて計算したときに出る値である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-24', '正答は D「「治療に納得いかない場合は精神医療審査会に申し立てができます」」。

医療保護入院や措置入院の患者、その家族等は、都道府県知事に対して退院や処遇改善を請求でき、精神医療審査会が入院の必要性と処遇の妥当性を審査する。入院時にこの権利を書面で告知しなければならない。

【誤答選択肢の解説】
A「「弁護士と面会することはできません」」: 弁護士など代理人との面会や電話は、いかなる場合も制限してはならない。
B「「入院中に任意入院に切り替えることはありません」」: 病状が改善して本人の同意が得られれば任意入院に切り替える。
C「「入院治療が必要な理由や入院目的について自分で考えましょう」」: 入院の必要性と目的は医師が説明すべきことで、本人に考えさせるものではない。
E「「退院の希望があった場合は72時間以内に退院することができます」」: 72時間以内の退院という規定はない。72時間は応急入院の入院期間の上限である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-25', '正答は D「ブロモクリプチン」。

ブロモクリプチンはドパミンD2受容体作動薬で、下垂体前葉からのプロラクチン分泌を抑えて乳汁分泌を止める。高プロラクチン血症や乳汁漏出症の治療に用いる。

【誤答選択肢の解説】
A「スルピリド」: スルピリドはドパミン受容体を遮断してプロラクチンを上昇させ、乳汁分泌を促す。
B「パロキセチン」: パロキセチンなどのSSRIも高プロラクチン血症をきたすことがある。
C「プレドニゾロン」: プレドニゾロンは乳汁分泌に直接影響しない。
E「メトクロプラミド」: メトクロプラミドもドパミン受容体遮断薬で、プロラクチンを上昇させる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-26', '正答は E「Turner症候群」。

Turner症候群はX染色体が1本欠けた45,Xを典型とし、染色体数が減少する疾患である。低身長、翼状頸、外反肘、性腺発育不全を特徴とする。

【誤答選択肢の解説】
A「Down症候群」: Down症候群は21番染色体が3本になる(トリソミー)ため、染色体数は増える。
B「Klinefelter症候群」: Klinefelter症候群は47,XXYで、性染色体が1本多い。
C「Marfan症候群」: Marfan症候群はフィブリリン遺伝子の変異による常染色体顕性遺伝疾患で、染色体数は正常である。
D「Prader-Willi症候群」: Prader-Willi症候群は15番染色体長腕の父由来領域の欠失などによるもので、染色体数そのものは正常である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C026（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-28', '正答は A「鶏卵1個(約50g)」。

1単位80kcalは糖尿病の食品交換表で用いられる目安で、鶏卵1個(約50g)がおよそこれに当たる。食品の量とエネルギーの対応をつかんでおくと栄養指導に役立つ。

【誤答選択肢の解説】
B「木綿豆腐1丁(約300g)」: 木綿豆腐1丁(約300g)は約210kcalである。
C「食パン6枚切り1枚(約60g)」: 食パン6枚切り1枚(約60g)は約150kcalである。
D「米飯(炊飯後)茶碗1杯(約160g)」: 米飯茶碗1杯(約160g)は約250kcalである。
E「ビール中ジョッキ1杯(約570mL)」: ビール中ジョッキ1杯(約570mL)は約230kcalである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C028（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-29', '正答は E「血中ヘモグロビン値」。

ヘモグロビン濃度はアンドロゲンによる造血刺激と月経による鉄喪失の差から男性のほうが高く、基準値に性差がある。ヘマトクリット、赤血球数、血清クレアチニン、尿酸なども同様に性差をもつ。

【誤答選択肢の解説】
A「血清Ca値」: 血清カルシウム値に性差はない。
B「血清CRP値」: CRPの基準値にも性差は設けられていない。
C「動脈血PaO2」: 動脈血酸素分圧は加齢で下がるが、性差はない。
D「血清アルブミン値」: 血清アルブミン値にも性差はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C029（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-3', '正答は E「ヘマトクリット値」。

妊娠末期には循環血漿量が約50%増えるのに対し赤血球量の増加は約20〜30%にとどまるため、相対的に希釈されてヘマトクリット値とヘモグロビン濃度が低下する(妊娠性貧血)。

【誤答選択肢の解説】
A「心拍数」: 心拍出量の増加に伴い心拍数は10〜20/分増える。
B「白血球数」: 白血球数は妊娠中に増加する。
C「糸球体濾過量」: 腎血漿流量の増加により糸球体濾過量は約50%増え、血清クレアチニンは下がる。
D「インスリン抵抗性」: hPLなどの作用でインスリン抵抗性はむしろ高まる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-35', '正答は A「尿酸」。

尿酸結石はエックス線を透過するため、腹部単純写真で写らない。高尿酸血症(8.6mg/dL)を背景に、超音波でのみ確認できる結石という組合せが尿酸結石を示す。尿のアルカリ化で溶解が期待できる点も特徴である。

【誤答選択肢の解説】
B「炭酸カルシウム」: 炭酸カルシウムはカルシウムを含むためエックス線写真に写る。
C「リン酸カルシウム」: リン酸カルシウムも高吸収でエックス線写真に写る。
D「シュウ酸カルシウム」: シュウ酸カルシウムは尿路結石で最も多いが、エックス線写真によく写る。
E「リン酸マグネシウムアンモニウム」: リン酸マグネシウムアンモニウム(感染結石)も写る。尿素分解菌の感染を背景に生じ、サンゴ状結石をつくる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C035（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-38', '正答は A「経過観察」。

完全母乳栄養で体重増加は良好、直接ビリルビンは0.1mg/dLと上がらず間接ビリルビン優位の黄疸が続いている。母乳性黄疸であり、生後2〜3か月で自然に消退するので経過観察でよい。

【誤答選択肢の解説】
B「交換輸血」: 交換輸血は核黄疸の危険が差し迫る著明な高ビリルビン血症に行うもので、総ビリルビン6.6mg/dLでは適応がない。
C「光線療法」: この値では光線療法も要さない。
D「胆道ドレナージ」: 直接ビリルビンが上がっておらず胆汁うっ滞はない。便色も問題になっていない。
E「母乳栄養から人工栄養への変更」: 母乳を中止する必要はない。母乳の利点を損なうだけである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C038（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-39', '正答は B「網赤血球数」。

過多月経による鉄欠乏性貧血で、鉄剤を投与すると数日で赤芽球の産生が動き出し、1週間前後で網赤血球が増加する(網赤血球クリーゼ)。ヘモグロビンの上昇はその後に続く。

【誤答選択肢の解説】
A「血清鉄値」: 血清鉄は投与直後に上がるが、これは吸収された鉄そのものを見ているだけで治療反応の指標にならない。
C「ヘモグロビン値」: ヘモグロビン値が上がり始めるのは網赤血球の増加より後で、正常化には数か月かかる。
D「血清フェリチン値」: 血清フェリチンは貯蔵鉄を反映し、正常化するのは最後である。
E「トランスフェリン飽和度」: トランスフェリン飽和度も鉄の補充を反映するが、造血の反応そのものではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C039（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-4', '正答は A「医療法 — 無診察治療の禁止」。

無診察治療の禁止は医師法第20条に定められている。医療法が定めるのは医療提供施設の開設と管理、医療計画、医療安全の確保といった提供体制に関する事項である。

【誤答選択肢の解説】
B「児童福祉法 — 小児慢性特定疾患の医療費助成」: 小児慢性特定疾病の医療費助成は児童福祉法に基づく。正しい組合せである。
C「労働基準法 — 産前産後休業」: 産前産後休業は労働基準法第65条に定められている。正しい組合せである。
D「がん対策基本法 — がん治療の均てん化」: がん医療の均てん化の促進はがん対策基本法の基本理念である。正しい組合せである。
E「労働者災害補償保険法 — 業務災害に関する給付」: 業務災害・通勤災害に関する保険給付は労働者災害補償保険法に基づく。正しい組合せである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-40', '正答は C「赤」。

呼びかけに反応せず、呼吸数32/分、毛細血管再充満時間3秒で、両下腿の挫滅による大量出血がある。生命の危機が差し迫っており、直ちに処置すれば救命が期待できる最優先治療群であるから赤タッグを付ける。挫滅症候群への対応も要る。

【誤答選択肢の解説】
A「緑」: 緑は歩行可能な軽症群につけるもので、この患者には当てはまらない。
B「黄」: 黄は多少処置が遅れても生命に危険がない待機的治療群で、意識障害と大量出血がある本例は該当しない。
D「白」: 白いタッグを付ける区分はない。
E「黒」: 黒は死亡または救命が極めて困難な群につける。自発呼吸があり循環も残っており、該当しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C040（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-41', '正答は C「世界保健機関〈WHO〉」。

世界保健機関は各国から集めた感染症の発生動向を公表し、診断と治療に関する技術的な指針も示している。国外で流行する感染症の情報を得るのに最も適した組織である。

【誤答選択肢の解説】
A「入国管理局」: 入国管理局は出入国の管理を行う機関で、感染症の医学情報は扱わない。
B「国際協力機構〈JICA〉」: 国際協力機構は開発協力を担う機関で、感染症の発生動向の公表主体ではない。
D「救急医療情報センター」: 救急医療情報センターは地域の受入れ可能な医療機関を案内する仕組みである。
E「地域医療支援センター」: 地域医療支援センターは都道府県が医師の確保と配置調整を行う組織である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C041（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-42', '正答は B「低体温」。

体重28kg、BMI12.8の著しいるいそうで、神経性やせ症である。飢餓に対する適応として代謝が落ち、低体温、徐脈、低血圧、産毛の増加、無月経をきたす。

【誤答選択肢の解説】
A「高血糖」: 摂取不足のため低血糖に傾く。高血糖は起こらない。
C「骨密度増加」: エストロゲン低下と低栄養により骨密度は低下する。
D「高カリウム血症」: 低栄養では低カリウム血症になりやすい。とくに嘔吐や下剤乱用があれば顕著である。
E「高ナトリウム血症」: ナトリウムも低下しやすく、高ナトリウム血症は典型的でない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C042（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-43', '正答は C「腹部超音波検査」。

妊娠31週で突然の下腹部痛と性器出血、板状硬に近い腹部膨満、ショックバイタルを認めており常位胎盤早期剝離が最も疑われる。ベッドサイドで直ちに行える腹部超音波検査で胎盤後血腫と胎児の状態を確認する。

【誤答選択肢の解説】
A「頭部単純CT」: 意識はほぼ清明で、頭蓋内病変を疑う所見はない。
B「腹部造影CT」: 造影CTは搬送と時間を要し、ショック状態の妊婦には不適である。
D「子宮動脈造影検査」: 子宮動脈造影は分娩後出血の止血手段で、この時点の診断手技ではない。
E「胎児心拍数陣痛図〈CTG〉」: 胎児心拍数陣痛図は並行して装着するが、母体の出血源と胎盤の状態を把握する超音波検査が優先される。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C043（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-44', '正答は B「2日以内は異常行動に留意する。」。

インフルエンザでは、抗ウイルス薬の使用の有無にかかわらず、発症から少なくとも2日間は突然走り出すなどの異常行動が起こりうる。保護者に対し、児を一人にしないなど転落防止の注意を促す必要がある。

【誤答選択肢の解説】
A「解熱後翌日から登校できる。」: 学校保健安全法では、発症後5日を経過し、かつ解熱後2日(幼児は3日)を経過するまで出席停止である。
C「家族と接するときにマスクは必要ない。」: 飛沫感染するため、家族と接する際もマスクを着用する。
D「口渇がなければ水分摂取の必要はない。」: 発熱と発汗で脱水になりやすく、口渇を待たずに水分を摂る。
E「抗ウイルス薬は症状がある期間を3日間短縮する。」: 抗ウイルス薬が短縮する有症状期間は約1日である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C044（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-45', '正答は D「妊娠高血圧腎症」。

妊娠20週以降に初めて高血圧が出現し、蛋白尿(尿蛋白/Cr比2.4g/gCr)を伴っており妊娠高血圧腎症である。胎児発育不全も伴っており、母児の状態をみながら分娩時期を決める。

【誤答選択肢の解説】
A「妊娠高血圧」: 妊娠高血圧は蛋白尿や臓器障害を伴わない場合の診断名である。
B「HELLP症候群」: HELLP症候群は溶血、肝酵素上昇、血小板減少を伴う。AST15U/L、血小板18万で該当しない。
C「高血圧合併妊娠」: 高血圧合併妊娠は妊娠前または妊娠20週までに高血圧があった場合をいう。妊娠32週までは異常がなかった。
E「加重型妊娠高血圧腎症」: 加重型妊娠高血圧腎症は、もともとの高血圧や腎疾患に蛋白尿や臓器障害が加わった場合である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C045（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-46', '正答は E「ポリソムノグラフィー」。

肥満、大きないびき、睡眠中の無呼吸、日中の眠気に加え、咽頭の視診で軟口蓋しか見えない(Mallampati分類の高度)ことから閉塞性睡眠時無呼吸を疑う。診断と重症度判定にはポリソムノグラフィーで無呼吸低呼吸指数を求める。

【誤答選択肢の解説】
A「嚥下機能検査」: 嚥下障害の訴えはなく、嚥下機能検査は診断に寄与しない。
B「気管支鏡検査」: 気管支鏡は下気道の病変を調べる検査で、睡眠時の無呼吸は評価できない。
C「頭部エックス線撮影」: 頭部エックス線写真(セファログラム)は顎顔面形態の評価に補助的に使うが、診断は確定できない。
D「発声機能検査」: 発声機能検査は音声障害の評価に用いる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C046（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-47', '正答は B「症状の緩和」。

肝転移と副腎転移を伴う進行肺癌で、腫瘍による上大静脈症候群をきたしている。この放射線治療は治癒を目指すものではなく、腫瘍を縮小させて上大静脈の圧排を解き、顔面と上肢の腫脹を軽くする緩和目的である。

【誤答選択肢の解説】
A「根治」: 遠隔転移がある段階で局所照射による根治は望めない。
C「遠隔転移の縮小」: 照射野は右上肺野の腫瘤であり、肝や副腎の転移は縮小しない。
D「殺細胞性薬の作用増強」: 同時化学放射線療法では増感効果を狙うが、本例は症状緩和のための照射である。
E「PD-L1蛋白質発現減弱」: 放射線照射でPD-L1発現が減弱することは期待される効果ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C047（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-48', '正答は D「高所作業の制限」。

片麻痺が残る状態では、墜落による重大災害を避けるため高所作業の制限が必要になる。産業医は、業務内容と残存する機能障害を突き合わせて就業上の配慮を意見する。

【誤答選択肢の解説】
A「出張の制限」: 出張そのものが片麻痺で直ちに危険になるわけではない。
B「夜勤の制限」: 夜勤の制限が必要になるのは睡眠障害やてんかんなど別の事情による。
C「業務時間の制限」: 業務時間は段階的に戻すことはあっても、真っ先に考慮すべき安全上の制限ではない。
E「接客業務の制限」: 接客業務は片麻痺があっても安全に行える。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C048（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-49', '正答は A「インスリン」。

肥満に高血糖、高トリグリセリド血症、低HDLコレステロール血症、肝障害が重なっており、インスリン抵抗性を基盤とした病態である。空腹時の血中インスリン値からHOMA-IRを算出してインスリン抵抗性を評価する。

【誤答選択肢の解説】
B「グルカゴン」: グルカゴンの測定はグルカゴノーマなど特殊な病態を疑うときに行う。
C「コルチゾール」: コルチゾールはCushing症候群を疑うときに測るが、満月様顔貌や皮膚線条などの所見がない。
D「成長ホルモン〈GH〉」: 成長ホルモンは先端巨大症を疑うときに測る。特徴的な身体所見がない。
E「遊離サイロキシン〈FT4〉」: 遊離サイロキシンは甲状腺機能の評価で、この病態の中心ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C049（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-51', '正答は B「限局性学習障害」。

全般的な知的発達は保たれているのに、漢字の書字だけが著しく習得できず学習に支障をきたしており限局性学習障害(書字表出の障害)である。読み書きや計算のうち特定の領域だけが際立って苦手になるのが特徴である。

【誤答選択肢の解説】
A「知的発達障害」: 知的発達障害では全般的な知的機能が低く、成績も広く振るわない。中等度の成績を保っていた本例は当てはまらない。
C「自閉スペクトラム症」: 自閉スペクトラム症では社会的コミュニケーションの障害が中核症状だが、友人関係のトラブルはない。
D「注意欠如多動性障害」: 注意欠如多動性障害では不注意や多動が複数の場面でみられるが、その記載がない。
E「発達性協調運動障害」: 発達性協調運動障害は運動のぎこちなさが主体で、漢字だけが習得できないという偏りは説明できない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C051（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-52', '正答は E「予防接種」。

三次予防は、発症した疾病の悪化や合併症を防ぎ、機能を維持して社会復帰を図る段階の対策である。予防接種は疾病そのものの発生を防ぐ一次予防にあたる。

【誤答選択肢の解説】
A「禁煙」: 既にある腎障害と動脈硬化の進行を抑えるための禁煙は三次予防にあたる。
B「禁酒」: 血圧と肝への負担を減らす禁酒も、合併症の進展を防ぐ三次予防である。
C「運動療法」: 運動療法は血糖と血圧の管理を通じて合併症の進行を抑える三次予防である。
D「栄養療法」: 栄養療法も腎症の進行を抑える目的で行われ、三次予防にあたる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C052（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-53', '正答は B「後向きコホート研究」。

過去の人事記録から曝露の有無で2群に分け、すでに起きている疾病の発生を追跡して比較している。曝露から結果へという向きはコホート研究と同じで、時間的に過去にさかのぼって行うため後向きコホート研究という。

【誤答選択肢の解説】
A「症例対照研究」: 症例対照研究は罹患者と非罹患者を先に分けて、過去の曝露を比べる。本例は曝露の有無で群を分けている。
C「ケースシリーズ研究」: ケースシリーズ研究は症例の記述にとどまり、比較対照を置かない。
D「ランダム化比較試験」: ランダム化比較試験は研究者が曝露を無作為に割り付ける。曝露は業務によるものである。
E「メタ分析〈メタアナリシス〉」: メタ分析は既存の複数の研究結果を統合する手法である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C053（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-54', '正答は B「腟分泌物鏡検」。

黄色泡沫状の帯下と腟壁の発赤から腟トリコモナス症を疑う。腟分泌物を生理食塩水で希釈して鏡検し、鞭毛で活発に運動する原虫を確認すれば診断できる。パートナーも同時に治療する。

【誤答選択肢の解説】
A「血清TPHA」: 血清TPHAは梅毒の検査で、帯下の性状から想定される病態と合わない。
C「コルポスコピー」: コルポスコピーは子宮頸部の上皮内病変を観察する検査である。
D「腟壁擦過細胞診」: 腟壁擦過細胞診でも原虫が見つかることはあるが、鏡検のほうが迅速で確実である。
E「腟分泌物Gram染色」: Gram染色は細菌の観察に用いる。トリコモナスは原虫で、生鮮標本の鏡検が適している。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C054（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-55', '正答は C「3」。

正常な分娩では、児頭は後頭部を母体腹壁側に向けて回旋し、顔は母体背中側を向く(第1回旋・第3回旋)。顔面を母体腹壁側に向ける回旋は後方後頭位で、分娩の遷延や停止を招く異常な経過である。

【誤答選択肢の解説】
A「1」: 破水から7時間後に規則的な子宮収縮が始まるのは前期破水後の経過として異常ではない。
B「2」: 陣痛開始から5時間で子宮口全開大に至るのは経産婦として順調である。
D「4」: 肩甲は母体腹壁側(前在肩甲)が先に、次いで背中側(後在肩甲)が娩出されるのが正常である。
E「5」: 胎盤は児娩出後30分以内に娩出されるのが正常で、9分は問題ない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C055（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-56', '正答は D「1水質基準 2環境基準」。

水道水そのものに求められるのは水道法に基づく水質基準である。公共用水域である河川に定められるのは環境基本法に基づく環境基準で、生物化学的酸素要求量はその項目に含まれる。排水基準は工場などが排出する水に課される基準である。

【誤答選択肢の解説】
A「1環境基準 2排水基準」: 水道水に適用されるのは環境基準ではなく水質基準である。
B「1許容基準 2環境基準」: 許容基準は作業環境における有害物質濃度の目安を指す用語で、水道水の基準ではない。
C「1許容基準 2排水基準」: 水道水は水質基準、河川は環境基準であり、どちらも当てはまらない。
E「1水質基準 2排水基準」: 河川という公共用水域に適用されるのは環境基準で、排水基準は工場の排出口に適用される。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C056（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-57', '正答は D「病理解剖を行う。」。

前日まで診療を受けていた大腸癌の進行による死亡で、死因に異状はない。病死の死因や病態をさらに詳しく調べるために遺族の承諾を得て行うのは病理解剖である。

【誤答選択肢の解説】
A「行政解剖を行う。」: 行政解剖は監察医制度のある地域で、犯罪性のない異状死体について行う。
B「系統解剖を行う。」: 系統解剖は医学教育のための解剖で、生前の献体の意思に基づく。
C「司法解剖を行う。」: 司法解剖は犯罪に関係する疑いのある死体について裁判所の令状に基づき行う。
E「解剖を実施しない。」: 遺族が希望しており、病理解剖という適切な手段がある。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C057（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-6', '正答は C「脾動脈は腹腔動脈から分岐する。」。

腹腔動脈は左胃動脈、総肝動脈、脾動脈の3本に分かれる。脾動脈は膵の上縁に沿って蛇行しながら脾門に至り、途中で膵枝と短胃動脈、左胃大網動脈を出す。

【誤答選択肢の解説】
A「総肝動脈と総胆管は伴走する。」: 総肝動脈は腹腔動脈から分かれて肝十二指腸間膜に入る。総胆管と並走するのは固有肝動脈である。
B「下腸間膜動脈は尿管に伴走する。」: 尿管に伴走するのは精巣(卵巣)動脈で、下腸間膜動脈は尿管とは走行が異なる。
D「Glisson鞘には肝動脈、肝静脈および胆管が存在する。」: Glisson鞘を通るのは門脈、肝動脈、胆管の三つ組で、肝静脈は含まれない。
E「上腸間膜静脈と下腸間膜静脈が合流して門脈を形成する。」: 門脈は上腸間膜静脈と脾静脈が合流して形成される。下腸間膜静脈は多くの場合、脾静脈に合流する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-7', '正答は B「Rotor症候群」。

Rotor症候群は肝細胞における抱合型ビリルビンの排泄障害による体質性黄疸で、肝の構造は保たれ門脈圧も上がらないので脾腫はきたさない。

【誤答選択肢の解説】
A「肝硬変」: 肝硬変では門脈圧亢進によりうっ血性の脾腫をきたす。
C「日本住血吸虫症」: 日本住血吸虫症では虫卵が門脈枝に詰まって肝の線維化と門脈圧亢進を招く。
D「Budd-Chiari症候群」: Budd-Chiari症候群は肝静脈の閉塞により肝うっ血と門脈圧亢進をきたす。
E「特発性門脈圧亢進症」: 特発性門脈圧亢進症は肝硬変がないのに門脈圧が上がり、著明な脾腫をきたす。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-8', '正答は D「Raynaud現象」。

チェーンソーや削岩機などの振動工具を長く使うと、手指の細動脈が攣縮して白く変色するRaynaud現象(白ろう病)を生じる。末梢神経障害や骨関節障害も伴い、業務上疾病として扱われる。

【誤答選択肢の解説】
A「Gottron徴候」: Gottron徴候は皮膚筋炎で手指関節背面に生じる紅斑である。
B「Heberden結節」: Heberden結節は遠位指節間関節の変形性関節症による骨性の膨隆である。
C「Osler結節」: Osler結節は感染性心内膜炎でみられる指趾腹の有痛性結節である。
E「Romberg徴候」: Romberg徴候は深部感覚障害を示す神経学的所見である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-C-9', '正答は D「在宅勤務中の負傷は労働災害補償の対象である。」。

在宅勤務も労働であり、業務に起因して生じた負傷であれば労働災害補償の対象となる。業務との関連が認められることが要件である。

【誤答選択肢の解説】
A「労働者は在宅勤務をする権利を有する。」: 在宅勤務は労使の取決めによるもので、労働者に権利として保障されているものではない。
B「在宅勤務中は健康診断を受診しなくてよい。」: 在宅勤務でも事業者には健康診断を実施する義務があり、労働者にも受診義務がある。
C「在宅勤務中の労働時間は労働者の裁量である。」: 労働時間の管理は事業者の責務で、労働者の裁量に委ねられるわけではない。
E「在宅勤務は新型コロナウイルス感染症の流行によって始まった。」: 在宅勤務は以前から存在し、感染症の流行によって普及が加速したにすぎない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 C009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-1', '正答は E「吐き気をともなう。」。

前庭神経炎は片側の前庭機能が急に脱落する病態で、強い回転性めまいと悪心・嘔吐が数日続く。蝸牛症状(難聴・耳鳴)を伴わないことがMénière病との鑑別点になる。

【誤答選択肢の解説】
A「再発することが多い。」: 通常は一度きりで、反復するのは Ménière病や良性発作性頭位めまい症である。
B「垂直性の眼振を認める。」: 眼振は健側向きの水平回旋性で、垂直性眼振は中枢性病変を示唆する。
C「頭痛をともなう。」: 頭痛は伴わない。頭痛を伴うめまいでは前庭性片頭痛や中枢性病変を考える。
D「難聴をともなう。」: 難聴は伴わない。伴えばMénière病や突発性難聴を考える。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-10', '正答は C「嗅覚障害」。

眼窩吹き抜け骨折では眼窩下壁や内壁が骨折し、下直筋の絞扼による眼球運動障害と複視、眼窩下神経の障害による頰部の知覚障害、副鼻腔との交通による鼻出血や眼窩気腫を生じる。嗅神経は篩板を通り眼窩底とは離れているため、嗅覚障害は起こりにくい。

【誤答選択肢の解説】
A「複視」: 下直筋が絞扼されると上方視で複視が生じる。
B「鼻出血」: 上顎洞や篩骨洞と交通するため鼻出血をきたす。
D「眼球上転障害」: 下直筋の絞扼により眼球の上転が制限される。
E「頰部知覚障害」: 眼窩下神経の障害により同側の頰部と上口唇の知覚が低下する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-11', '正答は E「生後間もなくから体重増加は不良となる。」。

重症複合免疫不全症ではT細胞とB細胞の両方の機能が失われ、生後数か月から反復する重症感染症と難治性下痢により体重増加不良(発育不全)をきたす。造血幹細胞移植が唯一の根治療法で、早期発見のため新生児マススクリーニングも行われている。

【誤答選択肢の解説】
A「全身のリンパ節が腫大する。」: リンパ組織が発育せず、胸腺は小さく扁桃やリンパ節も触れにくい。
B「ウィルスへの免疫は保たれる。」: 細胞性免疫が失われるため、ウイルスや真菌に対する抵抗力も著しく低い。生ワクチンは禁忌である。
C「顕性遺伝(優性遺伝)の形式をとる。」: X連鎖潜性遺伝または常染色体潜性遺伝の形式をとる。
D「血清免疫グロブリンは正常範囲である。」: 免疫グロブリンは著明に低下する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-18', '正答は C「下垂体MRI」。

無月経に加えてプロラクチン125ng/mLの高値と、増悪する頭痛を認めており、プロラクチン産生下垂体腺腫が疑われる。腫瘍の大きさと視交叉への進展を確かめるため下垂体MRIを行う。

【誤答選択肢の解説】
A「腹部CT」: 腹部CTで下垂体は評価できない。
B「FDG-PET」: FDG-PETは悪性腫瘍の検索に用いるもので、下垂体腺腫の描出には適さない。
D「マンモグラフィ」: 乳汁漏出があってもマンモグラフィで下垂体病変は分からない。
E「甲状腺超音波検査」: TSHは基準内で、甲状腺機能低下による高プロラクチン血症は考えにくい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D018（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-19', '正答は B「悪性腫瘍」。

ヘリオトロープ疹とGottron丘疹に近位筋の筋力低下、CK1,620U/Lを伴い皮膚筋炎である。抗TIF1-γ抗体は悪性腫瘍の合併と強く関連し、陽性例では全身の悪性腫瘍検索を欠かせない。

【誤答選択肢の解説】
A「肝不全」: AST・ALTの上昇は筋由来で、肝不全を示すものではない。
C「間質性肺炎」: 間質性肺炎は抗ARS抗体や抗MDA5抗体で問題となる。胸部エックス線写真に異常はなく、抗TIF1-γ抗体では合併が少ない。
D「急性腎障害」: クレアチニン0.4mg/dLで腎機能は保たれている。
E「膀胱直腸障害」: 膀胱直腸障害は脊髄病変でみられるもので、本症の合併症ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-2', '正答は A「エボラウイルス」。

アフリカで流行を繰り返し、体液との接触で感染し、回復後も精液中にウイルスが残存し、致死率が約50%という記述はエボラウイルス病に一致する。一類感染症に指定されている。

【誤答選択肢の解説】
B「ジカウィルス」: ジカウイルスは蚊が媒介し、致死率は低い。妊婦の感染による小頭症が問題となる。
C「新型コロナウィルス」: 新型コロナウイルスは飛沫・エアロゾルで伝播し、致死率は大幅に低い。
D「デングウイルス」: デングウイルスも蚊が媒介し、アジアや中南米で流行する。
E「ポリオウイルス」: ポリオウイルスは経口感染し、急性弛緩性麻痺をきたす。致死率は低い。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-22', '正答は E「5」。

FDG-PETで両側肺への遠隔転移が確認されており、切除の適応外と判断する根拠になる。肝細胞癌の切除は肝内に限局した病変が対象で、肺転移があれば全身療法に切り替える。

【誤答選択肢の解説】
A「1」: HCV抗体陽性は背景肝疾患を示すもので、切除の可否を左右しない。
B「2」: ICG15分値8%は肝予備能が良好であることを示し、切除を支持する所見である。
C「3」: 肝内転移1個は同一肝内の病変で、切除の対象となりうる。
D「4」: 径5cmという大きさ自体は切除不能の理由にならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-23', '正答は C「急性副鼻腔炎」。

感冒に続いて片側の頰部痛と同側の膿性鼻汁が出ており急性副鼻腔炎(上顎洞炎)である。多くはウイルス性で自然軽快するが、症状が強く遷延すれば細菌感染を考えて抗菌薬を用いる。

【誤答選択肢の解説】
A「鼻せつ」: 鼻せつは鼻前庭の毛囊の感染で、鼻入口部に限局した発赤と圧痛を認める。
B「三叉神経痛」: 三叉神経痛は誘因を伴う電撃様の発作性疼痛で、膿性鼻汁は伴わない。
D「頰部蜂窩織炎」: 頰部蜂窩織炎なら皮膚に発赤と腫脹を認めるが、認めない。
E「アレルギー性鼻炎」: アレルギー性鼻炎の鼻汁は水様性で、片側の頰部痛は起こさない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D023（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-24', '正答は B「NSAID」。

検査で器質的異常がなく、心理社会的なストレスと関連して食後の胃もたれが続いており機能性ディスペプシアである。酸分泌抑制薬、消化管運動調節薬、漢方薬(六君子湯)、必要に応じて抗うつ薬が用いられる。NSAIDは胃粘膜を傷害するため用いない。

【誤答選択肢の解説】
A「漢方薬」: 六君子湯などの漢方薬は上腹部症状に有用で、治療選択肢の一つである。
C「抗うつ薬」: 薬物療法で改善しない例には少量の抗うつ薬が用いられる。
D「酸分泌抑制薬」: 酸分泌抑制薬は心窩部痛症候群に有効で、第一選択の一つである。
E「消化管運動調節薬」: 消化管運動調節薬は食後愁訴症候群に有効である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-3', '正答は C「無脈性心室頻拍」。

無脈性心室頻拍は心室細動とともに電気ショックの適応(ショック適応リズム)である。ただちに除細動を行い、胸骨圧迫を再開する。

【誤答選択肢の解説】
A「心静止」: 心静止は電気ショックの適応ではなく、胸骨圧迫とアドレナリン投与を続ける。
B「心房細動」: 心房細動そのものは心停止ではない。血行動態が破綻した場合の同期下カルディオバージョンは、心停止に対する除細動とは別である。
D「完全房室ブロック」: 完全房室ブロックには経皮ペーシングやアトロピンで対応する。
E「無脈性電気活動〈PEA〉」: 無脈性電気活動もショック適応ではなく、原因の是正と胸骨圧迫を行う。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-33', '正答は D「適応障害〈適応反応症〉」。

はっきりしたストレス因(叱責)から3か月以内に症状が現れ、休日には趣味を楽しめており、ストレス因が取り除かれると軽快している。適応障害の典型的な経過である。

【誤答選択肢の解説】
A「うつ病」: うつ病では興味・喜びの喪失が場面を問わず持続する。休日に趣味を楽しめている点が合わない。
B「社交不安障害」: 社交不安障害は他者からの評価を伴う場面全般への恐怖で、幼少期から続くことが多い。
C「概日リズム障害」: 概日リズム障害は睡眠相のずれが中心で、動悸や気分の落ち込みは主症状でない。
E「心的外傷後ストレス障害」: 心的外傷後ストレス障害は生命を脅かすような出来事の後に、再体験・回避・過覚醒が続くもので、叱責はその出来事にあたらない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D033（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-36', '正答は E「遊離サイロキシン〈FT4〉」。

体重減少、頻脈、皮膚の湿潤、前頸部の腫脹、手指振戦がそろっており甲状腺機能亢進症(Basedow病)を疑う。遊離サイロキシンとTSHを測定して確かめる。

【誤答選択肢の解説】
A「頭部MRI」: 頭部MRIは下垂体病変を疑うときに行うが、まず末梢のホルモンを測る。
B「抗GAD抗体」: 抗GAD抗体は1型糖尿病を疑うときに測る。多飲・多尿の記載がない。
C「アルギニン負荷試験」: アルギニン負荷試験は成長ホルモン分泌不全の診断に用いる。
D「手根骨エックス線撮影」: 手根骨エックス線撮影は骨年齢の評価で、この病態の診断には直結しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D036（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-38', '正答は B「線維筋痛症」。

3か月以上続く全身の広範な疼痛に、圧痛点の存在、睡眠障害(むずむず脚症候群を含む)、炎症所見の欠如がそろっており線維筋痛症である。心理社会的な負荷が誘因になることも多い。

【誤答選択肢の解説】
A「脊椎関節炎」: 脊椎関節炎では炎症性腰背部痛と脊椎可動域の制限をきたすが、可動域に異常はない。
C「関節リウマチ」: 関節リウマチでは関節の腫脹と滑膜炎を認める。腫脹はない。
D「変形性関節症」: 変形性関節症の骨棘は認めるが、体幹を含む広範な圧痛は説明できない。
E「リウマチ性多発筋痛症」: リウマチ性多発筋痛症では肩や腰帯の痛みと著明な赤沈亢進を伴う。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D038（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-39', '正答は C「経過観察」。

加熱式たばこのスティックはニコチン含有量が少なく、すでに吐き出させ嘔吐もしている。バイタルサインは安定しており症状もないので、催吐や胃洗浄は行わず経過観察でよい。

【誤答選択肢の解説】
A「胃洗浄」: 胃洗浄は誤嚥の危険があり、この状況では適応がない。
B「気道確保」: 意識は清明で呼吸も保たれており、気道確保は要らない。
D「多量飲水」: 多量の水を飲ませるとニコチンの吸収を促すため、たばこ誤飲では禁忌とされる。
E「血液浄化法」: 血液浄化法を要する重症中毒ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D039（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-4', '正答は A「男性に多い。」。

チック症は男児に多く、男女比はおよそ3〜4対1である。幼児期から学童期に始まり、多くは思春期を過ぎるころに軽快する。

【誤答選択肢の解説】
B「思春期に好発する。」: 好発は4〜11歳ごろで、思春期には軽快に向かうことが多い。
C「緩徐な運動症状が多い。」: チックは突発的で素早い運動が特徴である。
D「症状は睡眠時に多くみられる。」: 睡眠中は軽減または消失する。
E「生涯にわたり症状が続くことが多い。」: 多くは成人までに軽快し、生涯続くのは一部である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-40', '正答は B「膜性腎症」。

高齢者に無症候性の高度蛋白尿(尿蛋白/クレアチニン比2.5g/gCr)が生じ、血尿に乏しく腎機能もほぼ保たれている。成人のネフローゼ症候群で最も多い膜性腎症を考える。悪性腫瘍の合併検索も要る。

【誤答選択肢の解説】
A「IgA腎症」: IgA腎症では顕微鏡的血尿が持続するのが特徴で、潜血陰性の本例は合わない。
C「多発性囊胞腎」: 多発性囊胞腎なら超音波検査で多数の囊胞を認める。腎に異常を認めない。
D「微小変化型ネフローゼ症候群」: 微小変化型は小児と若年成人に多く、急激に発症する。無症候で2年にわたる経過は合わない。
E「特発性半月体形成性糸球体腎炎」: 半月体形成性糸球体腎炎では数週で腎機能が急速に悪化し、血尿と赤血球円柱を伴う。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D040（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-42', '正答は B「気管挿管」。

縦隔の巨大腫瘤と末梢血の芽球14%からT細胞性リンパ芽球性リンパ腫・白血病が疑われる。仰臥位で気道と大血管が圧排されて呼吸困難とチアノーゼが急速に進んでおり、まず気管挿管で気道を確保する。

【誤答選択肢の解説】
A「開胸手術」: 開胸手術は気道緊急の対応にならない。
C「胸腔穿刺」: 胸腔穿刺は胸水の排除であって、縦隔腫瘤による気道閉塞は解除できない。
D「気管支拡張薬吸入」: 閉塞は縦隔腫瘤による圧排で、気管支拡張薬は無効である。
E「座位の励行を指示して帰宅」: 急速に悪化しており帰宅させてはならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D042（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-45', '正答は D「ジスキネジア」。

抗Parkinson病薬の増量に伴って出現した、体幹や四肢を不規則にくねらせる不随意運動はジスキネジアである。レボドパの血中濃度が高い時期に現れることが多く、投与量や投与法の調整で対応する。

【誤答選択肢の解説】
A「チック」: チックは突発的で反復性の常同的な運動で、一時的に抑制できる。
B「ジストニア」: ジストニアは持続的な筋収縮による異常肢位で、レボドパの効果が切れる時間帯に足に生じることが多い。
C「静止時振戦」: 静止時振戦はParkinson病そのものの症状で、薬剤の増量で新たに出るものではない。
E「ミオクローヌス」: ミオクローヌスは電撃様の短い筋収縮で、性状が異なる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D045（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-48', '正答は E「「適切なタイミングで欠損孔の閉鎖治療が必要か考えます」」。

II音の固定性分裂と肺動脈弁領域の収縮期雑音、三尖弁の相対的狭窄による拡張期雑音、右心系の拡大を認める心房中隔欠損症である。右心負荷があるので、就学前ごろを目安にカテーテル閉鎖術か外科的閉鎖の適応を検討する。

【誤答選択肢の解説】
A「「遺伝性の発症が多い疾患です」」: 大部分は孤発例で、遺伝性が多い疾患ではない。
B「「保育園での運動は控えましょう」」: 肺高血圧がなく症状もない時期に運動を制限する必要はない。
C「「小児期に不整脈を生じることが多いです」」: 心房性不整脈は成人期になって問題となるもので、小児期には少ない。
D「「心臓の負担をとるために塩分制限が必要です」」: 心不全症状がなく、塩分制限を要する状態ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D048（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-5', '正答は B「外ヘルニアである。」。

鼠径ヘルニアは腹壁の外へ脱出する外ヘルニアである。腹腔内の陥凹に入り込む内ヘルニアと区別される。

【誤答選択肢の解説】
A「高齢女性に多い。」: 成人の鼠径ヘルニアは高齢男性に多い。女性では大腿ヘルニアの割合が相対的に高くなる。
C「内鼠径ヘルニアの頻度が高い。」: 成人では下腹壁動脈の外側から脱出する外鼠径ヘルニアが最も多い。
D「腹膜鞘状突起の閉鎖不全が原因である。」: 腹膜鞘状突起の閉鎖不全は小児の外鼠径ヘルニアの原因である。成人では腹壁の脆弱化による。
E「開腹手術の既往はリスクファクターである。」: 開腹手術の既往は腹壁瘢痕ヘルニアの危険因子であって、鼠径ヘルニアのそれではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-50', '正答は B「気管支喘息」。

夜間から早朝の呼吸困難と慢性の咳・痰があり、FEV1%68%の閉塞性障害がβ2受容体刺激薬吸入で FEV1が2.12Lから2.66Lへ25%以上改善している。可逆性のある気道閉塞であり気管支喘息である。ネコが抗原の可能性がある。

【誤答選択肢の解説】
A「過敏性肺炎」: 過敏性肺炎は拘束性換気障害を示し、%VCが低下する。104%と保たれている。
C「慢性気管支炎」: 慢性気管支炎の気流閉塞は可逆性に乏しい。
D「うっ血性心不全」: うっ血性心不全なら心音・呼吸音の異常や胸部エックス線写真での心拡大を認める。
E「睡眠時無呼吸症候群」: 睡眠時無呼吸症候群では呼吸機能検査は正常で、気管支拡張薬にも反応しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D050（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-52', '正答は A「経過観察」。

発熱、扁桃の白苔、頸部リンパ節腫脹、異型リンパ球15%、肝逸脱酵素の上昇からEBウイルスによる伝染性単核症である。多くは自然に軽快するので対症療法と経過観察でよい。脾破裂を避けるため激しい運動は控えさせる。

【誤答選択肢の解説】
B「血漿交換」: 血漿交換を要する病態ではない。
C「アシクロビル投与」: アシクロビルはEBウイルスに対する有効性が確立しておらず、通常は用いない。
D「アンピシリン投与」: アンピシリンを投与すると高率に薬疹が出るため避ける。
E「殺細胞性抗癌薬投与」: 悪性リンパ腫ではなく、抗癌薬の適応はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D052（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-55', '正答は C「病室に出入りする人全員が同様に予防策を理解する。」。

多剤耐性緑膿菌は接触感染で広がるため接触予防策をとる。医師・看護師だけでなく、清掃員や面会者を含め病室に出入りするすべての人が同じ予防策を理解して実行しなければ、伝播は止められない。

【誤答選択肢の解説】
A「個室管理は必要ない。」: 接触予防策では個室管理か同一菌の患者どうしの集団隔離を行う。
B「N95マスクを着用し診察する。」: N95マスクは空気感染予防策で用いる。緑膿菌は空気感染しない。
D「手袋を使用して患者に接触した場合、手袋を外せば手洗いは必要ない。」: 手袋には目に見えない破損があり、外した後も手指衛生が必要である。
E「痰の吸引をしなければPersonal Protective Equipmen〈t PPE〉は必要ない。」: 環境や患者に接触する場面では吸引の有無にかかわらず個人防護具を用いる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D055（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-58', '正答は B「脂肪便」。

長年の多量飲酒と反復する腹痛の既往、膵のびまん性石灰化から慢性膵炎の非代償期である。膵外分泌機能が低下してリパーゼが不足し、脂肪が消化されずに脂肪便となる。膵消化酵素薬を補充する。

【誤答選択肢の解説】
A「黒色便」: 黒色便は上部消化管出血を示す所見で、本症の特徴ではない。
C「粘血便」: 粘血便は潰瘍性大腸炎や細菌性腸炎でみられる。
D「灰白色便」: 灰白色便は胆汁がうっ滞して腸管に届かない閉塞性黄疸でみられる。総ビリルビンは0.8mg/dLで正常である。
E「兎糞状便」: 兎糞状便は便秘型過敏性腸症候群でみられる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D058（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-59', '正答は E「パーソナリティ障害〈パーソナリティ症〉」。

思春期以降に始まり、対人関係の不安定さ、見捨てられ不安、衝動性、反復する自傷や過量服薬が持続しており境界性パーソナリティ障害である。心理療法が治療の中心で、薬物療法は補助的に用いる。

【誤答選択肢の解説】
A「双極性障害」: 双極性障害では躁病相と抑うつ相が数週から数か月の単位で現れる。気分の変動は対人関係の出来事に即時に反応しており、性質が異なる。
B「統合失調症」: 統合失調症では幻覚妄想や思考障害が中核となるが、そうした症状の記載がない。
C「自閉スペクトラム症」: 自閉スペクトラム症は幼少期から社会的コミュニケーションの障害が続く。小学生までは問題がなかった。
D「注意欠如多動性障害〈注意欠如多動症〉」: 注意欠如多動性障害も幼少期から不注意や多動が複数の場面で認められる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D059（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-6', '正答は E「尿管嵌頓結石」。

成人男性の腎盂腎炎は、女性と違って上行性感染だけで起こることは少なく、尿路の閉塞など基礎疾患を伴うことが多い。尿管に嵌頓した結石による閉塞が最も頻度の高い原因で、閉塞を解除しなければ敗血症に至る。

【誤答選択肢の解説】
A「性感染症」: 性感染症は尿道炎や精巣上体炎の原因になるが、腎盂腎炎の主因ではない。
B「過活動膀胱」: 過活動膀胱は排尿の切迫感が主症状で、腎盂腎炎の原因にはならない。
C「糖尿病腎症」: 糖尿病は感染しやすさの背景にはなるが、糖尿病腎症そのものが腎盂腎炎の原因になるわけではない。
D「間質性膀胱炎」: 間質性膀胱炎は無菌性の慢性膀胱痛症候群で、感染とは異なる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-60', '正答は E「アンジオテンシン変換酵素〈ACE〉阻害薬」。

Raynaud現象と前腕までの皮膚硬化があり全身性強皮症で、抗RNAポリメラーゼIII抗体陽性、急激な高血圧、腎機能の急速な悪化、血漿レニン活性の上昇から強皮症腎クリーゼである。ACE阻害薬が特異的に有効で、ためらわず投与する。

【誤答選択肢の解説】
A「β遮断薬」: β遮断薬は末梢血管を収縮させてRaynaud現象を悪化させ、腎クリーゼには無効である。
B「ループ利尿薬」: ループ利尿薬は循環血漿量を減らしてレニン・アンジオテンシン系をさらに亢進させる。
C「グルココルチコイド」: 高用量のグルココルチコイドはむしろ腎クリーゼの誘因となる。
D「抗コリンエステラーゼ薬」: 抗コリンエステラーゼ薬は重症筋無力症に用いる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D060（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-64', '正答は D「気管支肺胞洗浄〈BAL〉:リンパ球分画増加」。

職場でだけ咳が出て自宅では出ないという環境との関連があり、キノコ栽培に従事していることからキノコ胞子による過敏性肺炎が疑われる。気管支肺胞洗浄液ではリンパ球が増加し、CD8陽性細胞が優位となる。

【誤答選択肢の解説】
A「喀痰:抗酸菌塗抹陽性」: 抗酸菌感染を疑う所見はなく、職場との関連も説明できない。
B「生化学検査:血清IgA高値」: 血清IgAの高値は本症の所見ではない。
C「呼吸機能検査FEV1%:60%以下」: 過敏性肺炎は拘束性換気障害を示し、FEV1%は低下しない。
E「経気管支肺生検病理組織:びまん性肺胞障害〈DAD〉」: びまん性肺胞障害は急性呼吸窮迫症候群の病理像で、過敏性肺炎では肉芽腫を伴うリンパ球性の胞隔炎をみる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D064（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-7', '正答は A「患者数は少ない。」。

我が国の透析患者の約97%は血液透析で、腹膜透析は3%前後にとどまる。腹膜透析は自宅で行え、通院回数が少なく残存腎機能が保たれやすいという利点をもつ。

【誤答選択肢の解説】
B「食事制限は厳しい。」: 持続的に除水と溶質除去が行われるため、水分やカリウムの制限はむしろ緩やかである。
C「自宅での施行は困難である。」: 自宅で患者自身または家族が行うのが基本の治療法である。
D「動静脈シャント造設を要する。」: シャントを要するのは血液透析である。腹膜透析では腹腔カテーテルを留置する。
E「不均衡症候群を起こしやすい。」: 不均衡症候群は血液透析で血中の溶質が急に減ったときに起こる。緩やかな腹膜透析では起こりにくい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-8', '正答は E「肺サーファクタント減少」。

急性呼吸窮迫症候群ではII型肺胞上皮細胞が障害されてサーファクタントの産生が減り、また滲出した血漿蛋白により不活化される。その結果、肺胞が虚脱してコンプライアンスが低下する。

【誤答選択肢の解説】
A「気道抵抗低下」: 気道抵抗が低下することはない。病態の主座は肺胞と間質である。
B「肺血管抵抗低下」: 低酸素性肺血管攣縮と微小血栓により肺血管抵抗は上昇する。
C「肺内シャント減少」: 虚脱した肺胞に血流が流れ続けるため肺内シャントは増加し、酸素投与に反応しにくい低酸素血症となる。
D「肺コンプライアンス増加」: 肺は硬くなり、コンプライアンスは低下する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-D-9', '正答は D「潰瘍性大腸炎」。

原発性硬化性胆管炎は肝内外の胆管が線維性に狭窄する疾患で、その半数以上に潰瘍性大腸炎を合併する。大腸内視鏡検査による評価が勧められ、大腸癌と胆管癌の危険も高い。

【誤答選択肢の解説】
A「虚血性腸炎」: 虚血性腸炎は腸管の血流低下によるもので、本症との関連はない。
B「偽膜性腸炎」: 偽膜性腸炎は抗菌薬使用後のClostridioides difficile感染による。
C「大腸憩室炎」: 大腸憩室炎は憩室に生じた炎症で、本症とは無関係である。
E「過敏性腸症候群」: 過敏性腸症候群は器質的病変を伴わない機能性疾患である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 D009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-10', '正答は E「山中伸弥 — 多能性幹細胞〈iPS細胞〉の作製」。

山中伸弥は体細胞に4つの因子を導入して多能性を獲得させるiPS細胞の作製により、2012年にノーベル生理学・医学賞を受賞した。

【誤答選択肢の解説】
A「大隅良典 — 免疫チェックポイント阻害因子の発見」: 大隅良典の受賞理由はオートファジーの機構の解明である。
B「大村智 — 抗体の多様性に関する遺伝的原理の発見」: 大村智の受賞理由は寄生虫感染症に対するイベルメクチンにつながる発見である。
C「利根川進 — 寄生虫感染症の治療法の発見」: 利根川進の受賞理由は抗体の多様性が生じる遺伝的原理の解明である。
D「本庶佑 — オートファジーの解明」: 本庶佑の受賞理由はPD-1の発見による免疫チェックポイント阻害を用いた癌治療である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-11', '正答は D「がん、循環器疾患、糖尿病の総称である。」。

非感染性疾患は感染以外の原因で生じる慢性疾患の総称で、がん、循環器疾患、糖尿病に加えて慢性呼吸器疾患が主要な4つの疾患とされ、精神疾患などを含めることもある。3つに限る記述は誤りである。

【誤答選択肢の解説】
A「遺伝要因は発症に関係する。」: 家族歴や遺伝的素因は発症に関与する。
B「生活習慣は発症に関係する。」: 喫煙、飲酒、食生活、身体活動の4つが共通の危険因子とされる。
C「予防は健康日本21の目標である。」: 健康日本21は非感染性疾患の予防を主要な目標に掲げている。
E「社会的な環境を踏まえた対策が必要である。」: 健康の社会的決定要因を踏まえた環境整備が必要とされている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-12', '正答は B「滅菌手袋を着用して穿刺する。」。

腰椎穿刺は無菌操作で行うため、術者は滅菌手袋を着用し、穿刺部位を広く消毒して滅菌ドレープをかける。医原性の髄膜炎を防ぐために欠かせない。

【誤答選択肢の解説】
A「患者を腹臥位にする。」: 側臥位で背中を丸めさせて棘突起間を開く。腹臥位では行えない。
C「できるだけ太い穿刺針を用いる。」: 太い針は穿刺後頭痛を増やすため、できるだけ細い針を用いる。
D「患者のL1とL2の椎間を穿刺する。」: 脊髄円錐は成人でL1〜L2の高さで終わるので、その下のL3/4またはL4/5を穿刺する。
E「患者は脳脊髄液採取後に一定時間座位を保つようにする。」: 穿刺後は仰臥位で安静にする。座位を保つ必要はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E012（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-13', '正答は C「医療者と患者がともに最善の方法を探る。」。

共同意思決定は、医学的な根拠と患者の価値観・生活の双方を持ち寄り、医療者と患者が対話しながら一緒に最善の方針を作り上げる過程である。

【誤答選択肢の解説】
A「医療者が最善と考えた方針を説明し同意を得る。」: 医療者が決めた方針に同意を得るのはパターナリズムに近い形である。
B「医療者が提供した選択肢から患者が選択する。」: 選択肢を示して患者に選ばせるだけでは、情報提供にとどまり共同の意思決定にならない。
D「インフォームド・コンセントと同義である。」: インフォームド・コンセントは説明と同意の手続きで、方針を一緒に作る過程とは異なる。
E「患者の経過が確実に予測できる場合に適している。」: 経過が確実に予測できる場合はむしろ標準治療が定まりやすい。共同意思決定が生きるのは、複数の選択肢があり優劣がつけがたい場面である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E013（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-14', '正答は E「副鼻腔気管支症候群」。

副鼻腔気管支症候群は慢性副鼻腔炎と気管支の慢性炎症が併存する病態で、膿性痰を伴う湿性咳嗽が続く。マクロライド少量長期療法が有効である。

【誤答選択肢の解説】
A「咳喘息」: 咳喘息は痰を伴わない乾性咳嗽が主体である。
B「間質性肺炎」: 間質性肺炎も乾性咳嗽をきたす。
C「感染後咳嗽」: 感染後咳嗽は気道の過敏性が残ることによる乾性咳嗽である。
D「胃食道逆流症」: 胃食道逆流症による咳嗽も乾性である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E014（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-15', '正答は C「自身の業務に関係のない患者の電子カルテを閲覧する。」。

自身の診療に関係しない患者の診療録を閲覧することは、正当な目的のない個人情報へのアクセスであり、守秘義務と職業倫理に反する。

【誤答選択肢の解説】
A「患者からのセカンドオピニオンの求めに応じる。」: セカンドオピニオンを求める権利は患者にあり、応じるのは適切である。
B「他の医師の不適切な医療行為に対して忠告する。」: 同僚の不適切な医療行為に対して忠告することは、患者の安全を守るための責務である。
D「治験薬剤の適応に合致する患者に治験の情報を提供する。」: 適応に合う患者に治験の情報を提供することは、選択肢を示す行為として適切である。
E「判断能力のない患者の利益擁護者に病状や治療内容を説明する。」: 判断能力を欠く患者について、その利益を守る立場の者に説明することは適切である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E015（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-16', '正答は A「乳汁分泌」。

乳汁分泌は妊娠・授乳期のほか、高プロラクチン血症や薬剤性でみられる生理的・内分泌的な現象で、乳癌を疑う所見ではない。乳癌で問題になるのは血性の乳頭分泌である。

【誤答選択肢の解説】
B「乳頭陥凹」: 腫瘍が乳管を引き込むと乳頭が陥凹する。
C「えくぼ徴候」: Cooper靱帯が引かれて皮膚が陥凹するえくぼ徴候は乳癌を示唆する。
D「橙皮様変化」: 皮膚のリンパ管が閉塞して毛孔が目立つ橙皮様変化は進行乳癌の所見である。
E「大胸筋に固着した腫瘤」: 大胸筋に固着した腫瘤は胸壁への浸潤を示す。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E016（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-17', '正答は E「血清クレアチニンを用いた推算GFRは筋肉量に影響される。」。

血清クレアチニンは筋肉由来なので、筋肉量が多ければ高く、少なければ低く出る。これを用いた推算GFRは、るいそうの高齢者や四肢麻痺の患者で実際より高く見積もられる。そうした場合はシスタチンCによる推算が有用である。

【誤答選択肢の解説】
A「腎血流量は加齢により増加する。」: 腎血流量は加齢とともに減少する。
B「尿濃縮能は加齢により増加する。」: 尿濃縮能も加齢とともに低下し、高齢者は脱水になりやすい。
C「糸球体濾過量〈GFR〉は妊娠中期に減少する。」: 妊娠中は腎血漿流量が増えてGFRは約50%増加する。
D「GFRが低下すると血清シスタチンCは減少する。」: シスタチンCはGFRが低下すれば上昇する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-18', '正答は E「悪い知らせを聞く意思があるかどうかを患者本人に確認する。」。

悪い知らせを伝える際は、まず患者がどこまで知りたいと望んでいるかを確かめる。SPIKESでいうInvitationの段階で、知りたくないという意思も尊重される。

【誤答選択肢の解説】
A「家族は同席させない。」: 患者が望むなら家族の同席が支えになる。誰に同席してほしいかを事前に確認する。
B「一度だけ説明すればよい。」: 一度で受け止められるものではなく、繰り返し説明し理解を確かめる。
C「患者の解釈モデルは聴取しない。」: 患者が病状をどう理解しているかを先に聴くこと(Perception)は、説明の出発点になる。
D「患者の理解度にかかわらず手短に説明する。」: 理解度に合わせて言葉を選び、区切りながら伝える必要がある。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E018（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-19', '正答は D「予期不安」。

予期不安は、パニック発作がまた起こるのではないかという持続的な不安で、発作そのものと並ぶパニック障害の中核症状である。これに広場恐怖や回避行動が加わって生活が制限される。

【誤答選択肢の解説】
A「健忘」: 健忘は解離性障害や器質性精神障害でみられる。
B「無為」: 無為は統合失調症の陰性症状である。
C「観念奔逸」: 観念奔逸は躁状態でみられる思考の障害である。
E「フラッシュバック」: フラッシュバックは心的外傷後ストレス障害の再体験症状である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-2', '正答は B「複数の研究を統合できる。」。

メタ分析は同じ問いを扱った複数の研究結果を統計学的に統合し、より精度の高い推定値を得る手法である。系統的レビューと組み合わせて用いられ、エビデンスレベルの階層では最上位に位置づけられる。

【誤答選択肢の解説】
A「エビデンスレベルは低い。」: エビデンスレベルは最も高い部類に位置づけられる。
C「出版バイアスは考慮しなくてよい。」: 有意な結果が公表されやすいという出版バイアスは、メタ分析で必ず検討すべき問題である。
D「無作為化比較対照試験と同義である。」: ランダム化比較試験を統合の対象とすることは多いが、同義ではない。
E「研究者自身が対象集団に直接働きかけてデータを収集する。」: 既存の研究結果を統合する手法で、研究者が対象集団に直接働きかけることはない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-20', '正答は E「固定姿勢保持困難〈asterixis〉は上肢を前方に水平挙上させて観察する。」。

固定姿勢保持困難(羽ばたき振戦)は、上肢を前方に挙げて手関節を背屈させ、その姿勢を保たせたときに現れる不規則な落下運動である。肝性脳症や高二酸化炭素血症、尿毒症でみられる。

【誤答選択肢の解説】
A「呼吸数測定は5秒間行う。」: 呼吸数は意識されると変わるので、患者に気づかれないよう30秒〜1分測る。
B「血圧測定は患者が会話中に行う。」: 会話は血圧を上げるため、静かに座って数分安静にしてから測る。
C「上肢近位筋の筋力測定は握力計で行う。」: 握力計で測れるのは前腕・手の筋力である。上肢近位筋は徒手筋力テストで評価する。
D「内頸静脈での中心静脈圧推定は臥位で行う。」: 中心静脈圧の推定は上半身を30〜45度起こした半坐位で行う。臥位では拍動の頂点が観察できない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E020（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-22', '正答は D「医師が署名しなければならない。」。

死亡診断書(死体検案書)には医師が記名押印または署名しなければならない。作成は医師の義務で、正当な事由なく交付を拒めない。

【誤答選択肢の解説】
A「解剖所見は記載できない。」: 死亡の原因の欄には、解剖によって明らかになった所見も記載する。解剖の有無を記す欄もある。
B「歯科医師は発行できない。」: 歯科医師も自らの診療に関する範囲で死亡診断書を交付できる。
C「主治医以外は記載できない。」: 主治医でなくても、死亡を確認した医師が診察に基づいて記載できる。
E「保健所に届け出なければならない。」: 届出先は市町村長である。死亡届に添えて提出する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-23', '正答は A「胸骨圧迫」。

窒息した人が意識を失って倒れたら、心停止に準じてただちに胸骨圧迫を始める。胸骨圧迫による胸腔内圧の上昇は異物を押し出す効果も期待できる。

【誤答選択肢の解説】
B「背部叩打」: 背部叩打は意識があるうちに行う手技である。
C「腹部突き上げ」: 腹部突き上げも意識がある間に行う。
D「口対口人工呼吸」: まず胸骨圧迫を始め、人工呼吸は訓練を受けていれば30対2で組み合わせる。
E「口腔内異物除去」: 口腔内をのぞいて見える異物は取り除くが、盲目的な指による掻き出しは異物を押し込む危険があり、圧迫を中断してまで行わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E023（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-25', '正答は D「敗血症性ショック — 蕁麻疹」。

蕁麻疹はアナフィラキシーショックの所見である。敗血症性ショックでは発熱や低体温、末梢血管拡張による四肢の温感(ウォームショック)、乏尿、意識障害がみられる。

【誤答選択肢の解説】
A「出血性ショック — 頻脈」: 出血性ショックでは循環血液量の減少を代償して頻脈になる。正しい組合せである。
B「心原性ショック — 乏尿」: 心原性ショックでは心拍出量の低下により腎血流が減り乏尿となる。正しい組合せである。
C「神経原性ショック — 徐脈」: 神経原性ショックでは交感神経の遮断により血管拡張と徐脈をきたす。正しい組合せである。
E「アナフィラキシーショック — 喉頭浮腫」: アナフィラキシーショックでは喉頭浮腫による気道閉塞が致命的となる。正しい組合せである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-26', '正答は A「減塩」。

BMI21.3で肥満はなく、腹囲・脂質・血糖・尿酸も問題ない。是正すべきは食塩摂取15g/日という点であり、6g/日未満を目標に減塩を指導する。

【誤答選択肢の解説】
B「禁酒」: 機会飲酒であり禁酒を求める根拠はない。
C「体重の減量」: 身長168cm、体重60kgで肥満はなく、減量の対象にならない。
D「脂肪摂取制限」: 総コレステロール170mg/dL、トリグリセリド70mg/dLと脂質は良好である。
E「プリン体摂取制限」: 尿酸6.8mg/dLは基準内で、プリン体制限を要さない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E026（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-27', '正答は D「精巣捻転症」。

急な陰囊痛と腫大、透光性なし、著明な圧痛に加えてカラードプラで精巣内の血流が乏しく精巣捻転症である。発症から6〜8時間以内に整復しないと精巣が壊死するため、緊急手術を行う。

【誤答選択肢の解説】
A「精巣腫瘍」: 精巣腫瘍は無痛性の腫大として現れ、血流はむしろ増加する。
B「精巣水瘤」: 精巣水瘤は透光性を認め、圧痛を伴わない。
C「精索静脈瘤」: 精索静脈瘤は立位で目立つ蔓状の静脈拡張で、急激な疼痛はきたさない。
E「鼠径ヘルニア」: 鼠径ヘルニアなら鼠径部に腫瘤を触れるが、触れない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E027（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-3', '正答は E「Staphylococcus epidermidis」。

Staphylococcus epidermidisをはじめとするコアグラーゼ陰性ブドウ球菌は皮膚の常在菌で、2セット中1セットのみの陽性なら採血時の汚染菌と判断することが多い。ただし人工物が留置されていれば起因菌となりうる。

【誤答選択肢の解説】
A「Candida albicans」: Candida albicansは血液から検出されれば汚染とはみなさず、必ず治療する。
B「Escherichia coli」: Escherichia coliも常在菌ではあるが、血液培養から検出されれば起因菌として扱う。
C「Pseudomonas aeruginosa」: Pseudomonas aeruginosaも検出されれば起因菌として治療する。
D「Staphylococcus aureus」: Staphylococcus aureusは1セットのみの陽性でも起因菌とみなし、感染性心内膜炎の検索を含めて治療する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-30', '正答は A「医療安全管理部門にインシデントレポートを提出する。」。

薬剤師の指摘が生かされず、アレルギー歴のある薬剤が投与されて蕁麻疹という健康被害が生じている。院内の医療安全管理部門へインシデントレポートを提出し、指摘が治療方針に反映される仕組みづくりにつなげる。

【誤答選択肢の解説】
B「医療事故調査委員会に調査を依頼する。」: 医療事故調査制度の対象は予期しなかった死亡例で、この事例は該当しない。
C「当該の抗菌薬の製薬会社に報告する。」: 既知のアレルギー歴を確認しなかった院内の過程の問題であり、製薬会社への副作用報告が第一ではない。
D「どこにも報告する必要はない。」: 実害が生じており、報告して再発防止につなげる必要がある。
E「保健所に届け出る。」: 保健所への届出を要する事案ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E030（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-31', '正答は A「緊急手術」。

無月経7週で妊娠反応陽性、子宮内に胎囊を認めず付属器領域に腫瘤、Morrison窩とDouglas窩に液体貯留、血圧78/52mmHgのショック状態であり、卵管妊娠破裂による腹腔内出血である。ただちに開腹または腹腔鏡下の緊急手術を行う。

【誤答選択肢の解説】
B「子宮鏡検査」: 子宮鏡は子宮腔内を観察する検査で、出血性ショックの対応にならない。
C「子宮動脈塞栓術」: 子宮動脈塞栓術は分娩後出血などに用いる。破裂した卵管の止血には手術が確実である。
D「1週間経過観察」: ショック状態であり経過観察は許されない。
E「葉酸代謝拮抗薬投与」: メトトレキサート療法は未破裂で循環動態が安定した異所性妊娠に限られる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E031（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-32', '正答は E「Neisseria meningitidis」。

急速に進行する発熱と頭痛、項部硬直に加えて四肢の出血斑(電撃性紫斑)を伴っており、髄膜炎菌による侵襲性髄膜炎菌感染症である。血液培養でグラム陰性双球菌が検出される。予後を左右するので直ちに抗菌薬を投与し、濃厚接触者には予防内服を行う。

【誤答選択肢の解説】
A「Escherichia coli」: Escherichia coliはグラム陰性桿菌で、成人の市中髄膜炎の主因ではない。
B「Group A Streptococcus」: A群溶血性連鎖球菌はグラム陽性球菌で連鎖状に並ぶ。
C「Moraxella catarrhalis」: Moraxella catarrhalisもグラム陰性双球菌だが、気道感染の起因菌で電撃性紫斑を伴う敗血症はきたさない。
D「Neisseria gonorrhoeae」: Neisseria gonorrhoeaeもグラム陰性双球菌だが、性器や咽頭の感染が主で、この経過は合わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E032（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-33', '正答は C「腹部超音波検査」。

総合感冒薬に含まれる抗ヒスタミン薬や抗コリン成分が引き金となった、前立腺肥大症を背景とする急性尿閉である。下腹部の弾性軟の腫瘤は充満した膀胱で、腹部超音波検査で残尿量を確かめれば診断がつく。導尿で速やかに解除する。

【誤答選択肢の解説】
A「骨盤部MRI」: 骨盤部MRIは前立腺癌の局所診断に用いるもので、急性期にまず行う検査ではない。
B「腹部造影CT」: 造影CTは被曝と造影剤の負担があり、まず行う検査ではない。
D「腹部エックス線撮影」: 腹部エックス線撮影では膀胱内の尿は評価できない。
E「下部消化管内視鏡検査」: 下部消化管内視鏡は大腸の検査で、この病態には無関係である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E033（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-34', '正答は E「産褥6週間後に再度75g経口ブドウ糖負荷試験を行う。」。

75gOGTTで2点以上が基準を超えており妊娠糖尿病である。妊娠糖尿病の既往は将来の2型糖尿病発症の危険因子なので、産褥6〜12週に75gOGTTを再検して耐糖能を評価し、以後も定期的に追跡する。

【誤答選択肢の解説】
A「運動療法は勧めない。」: 禁忌がなければ運動療法は勧められる。
B「経口血糖降下薬を開始する。」: 妊娠中の経口血糖降下薬は原則として用いず、食事療法で不十分ならインスリンを用いる。
C「1日1,200kcalの食事療法を行う。」: 1,200kcalでは母児に必要なエネルギーが不足する。標準体重×30kcalに妊娠中期以降の付加量を加える。
D「食後2時間の血糖値が150mg/dL未満を目標とする。」: 妊娠中の目標は食後2時間値120mg/dL未満とより厳格である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E034（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-35', '正答は D「「話し合いで決まったことでも後で変更できます」」。

人生の最終段階における医療・ケアの話し合いは、本人の状態や気持ちの変化に応じて何度でも見直すことが前提である。一度決めたら変えられないものではないと伝えることが、話し合いを始めやすくする。

【誤答選択肢の解説】
A「「話し合いの内容は文書では残しません」」: 話し合いの内容は文書にまとめて共有し、関係者が同じ理解をもてるようにする。
B「「配偶者は代理意思決定者にはなれません」」: 配偶者は本人の意思を最もよく知る立場にあり、代理意思決定者になりうる。
C「「本人は認知症があるので参加は不要です」」: 認知症があっても本人の意思を確かめる努力が必要で、可能な範囲で参加してもらう。
E「「ケアマネジャーに話し合いの内容を伝える必要はありません」」: 在宅サービスの調整を担うケアマネジャーとの共有は欠かせない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E035（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-36', '正答は A「直腸指診を行う。」。

心窩部から右下腹部への痛みの移動と咳嗽時の疼痛から急性虫垂炎を疑う。骨盤内に位置する虫垂の炎症では腹壁からの所見が乏しいので、直腸指診でDouglas窩の圧痛を確かめることが診断に役立つ。

【誤答選択肢の解説】
B「聴診の前に打診を行う。」: 腹部診察は視診・聴診・打診・触診の順で行う。打診が聴診より先になってはならない。
C「腸蠕動音の聴取は5秒間行う。」: 腸蠕動音の減弱を判断するには最低1分は聴く。5秒では足りない。
D「痛みを訴える部位から触診する。」: 痛みの部位は最後に触れる。先に触れると防御反応で以後の診察ができなくなる。
E「腸蠕動音の聴取は5か所以上で行う。」: 腸蠕動音は腹腔内に伝わるので、1か所を十分な時間聴けばよい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E036（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-37', '正答は D「「おつらいですね、もう少しお気持ちをお話しいただけますか」」。

「もう終わりにしたい」という訴えの背後には、身体の苦痛だけでなく孤独感や無力感があることが多い。まず気持ちを受けとめ、さらに語ってもらうことで何が最もつらいのかを一緒に探る。

【誤答選択肢の解説】
A「「緩和ケア病棟への入院を検討しましょう」」: 本人は自宅で過ごすことを望んでおり、いきなり入院を提案するのは訴えを受けとめていない。
B「「すぐに安楽な死を迎えられる薬剤を準備します」」: 生命を積極的に終わらせる行為は許されない。
C「「身体の症状で、いま一番つらい症状を教えてください」」: 身体症状に絞って尋ねると、精神的・社会的な苦痛を語る機会を閉ざしてしまう。最初の返答としては早い。
E「「そんなことをおっしゃらずに、もう少し頑張ってみましょう」」: 励ましは訴えの否認となり、患者を孤立させる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E037（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-38', '正答は E「回復期リハビリテーション病院」。

大腿骨頸部骨折の術後で、意欲があり在宅復帰を目指せる状態である。回復期リハビリテーション病棟は集中的な訓練で日常生活動作を高め、在宅復帰を図る施設で、この患者に最も適する。

【誤答選択肢の解説】
A「介護医療院」: 介護医療院は長期の療養と生活の場を提供する施設で、在宅復帰を目指す段階には合わない。
B「特定機能病院」: 特定機能病院は高度医療を担う施設で、リハビリテーションの場ではない。
C「グループホーム」: グループホームは認知症の人が共同生活を送る場で、認知症のない本例は対象にならない。
D「特別養護老人ホーム」: 特別養護老人ホームは原則として要介護3以上の人が生活する施設である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E038（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-39', '正答は B「小刻み歩行」。

便秘と嗅覚低下という前駆症状に続き、左右差のある静止時振戦・筋強剛・姿勢反射障害が現れ、ドパミントランスポーターSPECTで線条体の取込み低下を認めておりParkinson病である。歩幅が狭く足を擦るような小刻み歩行が特徴的で、前方突進やすくみ足を伴う。

【誤答選択肢の解説】
A「鶏歩」: 鶏歩は下垂足のため膝を高く上げる歩行で、腓骨神経麻痺や末梢神経障害でみられる。
C「動揺性歩行」: 動揺性歩行は近位筋の筋力低下により腰を左右に振る歩行で、筋ジストロフィーでみられる。
D「はさみ足歩行」: はさみ足歩行は両下肢の痙縮による歩行で、痙性対麻痺でみられる。痙縮はない。
E「マグネット歩行」: マグネット歩行は足が床に吸いつくような歩行で、正常圧水頭症でみられる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E039（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-40', '正答は E「5」。

予防給付は要支援1・2と認定された人が受けられる給付である。要支援1という認定こそが根拠になる。

【誤答選択肢の解説】
A「1」: 高血圧症で通院していることは給付の要件にならない。
B「2」: 一人暮らしであることも要件ではない。
C「3」: 年金生活という経済状況も要件ではない。
D「4」: 認知機能に問題がないことも給付の根拠にはならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E040（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-5', '正答は D「橈骨動脈の触知不良」。

死期が近づくと心拍出量が低下し末梢循環が保てなくなるため、橈骨動脈が触れにくくなる。四肢の冷感とチアノーゼ、下顎呼吸、意識レベルの低下とともに、死が数日以内に迫っている徴候となる。

【誤答選択肢の解説】
A「手足の熱感」: 末梢循環不全により手足は冷たくなる。
B「尿量の増加」: 腎血流の低下により尿量は減少する。
C「酸素飽和度の上昇」: 呼吸機能の低下により酸素飽和度は下がる。
E「毛細血管再充満時間の短縮」: 循環不全により毛細血管再充満時間は延長する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-6', '正答は C「高血圧症」。

患者調査では、65歳以上の外来患者数は高血圧性疾患が最も多い。有病率が高く、生涯にわたり通院を要することが背景にある。

【誤答選択肢の解説】
A「糖尿病」: 糖尿病も多いが、高血圧性疾患には及ばない。
B「緑内障」: 緑内障は眼科の外来で多いが、全体では高血圧性疾患に及ばない。
D「悪性新生物」: 悪性新生物は入院での比重が大きく、外来患者数では上位ではない。
E「脂質異常症」: 脂質異常症も多いが、高血圧性疾患のほうが多い。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-7', '正答は D「綿棒を患者の鼻孔から上方に向けて挿入する。」。

鼻腔は鼻背に沿って上向きではなく、鼻孔から顔面に対して水平に、後方(耳のほう)へ向けて挿入する。上方に向けると鼻甲介にあたって痛みを与え、検体も採れない。

【誤答選択肢の解説】
A「個人防護具を着用する。」: 飛沫を浴びる手技なので、マスク・ゴーグル・ガウン・手袋を着用する。
B「患者の側方に立つ。」: 咳やくしゃみを正面から浴びないよう、患者の側方に立つ。
C「患者の頭部が動かないよう支える。」: 急に動くと粘膜を傷つけるため、頭部を支えて固定する。
E「咽頭後壁からぬぐい液を採取する。」: 鼻咽頭ぬぐい液は咽頭後壁に綿棒を当て、数秒とどめてから回転させて採取する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-8', '正答は A「患者の眼鏡」。

標準予防策で手袋を要するのは、血液・体液・分泌物・排泄物、傷のある皮膚、粘膜に触れるときである。患者の眼鏡はこれらに該当せず、素手で扱ってよい。

【誤答選択肢の解説】
B「創部にあてたガーゼ」: 創部にあてたガーゼは血液や滲出液が付着しており手袋を要する。
C「便が付着したオムツ」: 便が付着したオムツは排泄物であり手袋を要する。
D「口腔ケアに用いたブラシ」: 口腔ケアに用いたブラシは唾液が付着しており手袋を要する。
E「喀痰が付着したティッシュペーパー」: 喀痰が付着したティッシュペーパーも分泌物であり手袋を要する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-E-9', '正答は B「かゆみ」。

閉塞性黄疸では胆汁が腸管へ流れず、胆汁酸が血中に貯留して皮膚の神経終末を刺激するため強いかゆみが生じる。灰白色便と濃い尿(ビリルビン尿)も伴う。

【誤答選択肢の解説】
A「紫斑」: 紫斑は血小板減少や凝固障害でみられ、閉塞性黄疸で直ちに生じるものではない。
C「黒色便」: 黒色便は上部消化管出血によるもので、閉塞性黄疸では灰白色便となる。
D「立ちくらみ」: 立ちくらみは起立性低血圧や貧血の症状である。
E「肉眼的血尿」: 肉眼的血尿は尿路の出血によるもので、閉塞性黄疸では濃い黄褐色のビリルビン尿となる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 E009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-1', '正答は E「駅のホームドア(転落防止柵)」。

ユニバーサルデザインは、障害の有無や年齢にかかわらず誰もが使えるように最初から設計するという考え方である。ホームドアは視覚障害者だけでなく、酔客や子ども、すべての利用者の転落を防ぐ。

【誤答選択肢の解説】
A「手話通訳」: 手話通訳は聴覚障害者を対象とした支援である。
B「電動車椅子」: 電動車椅子は歩行が困難な人のための福祉用具である。
C「点字ブロック」: 点字ブロックは視覚障害者を対象とした設備である。
D「障害者用駐車場」: 障害者用駐車場も対象を限定した設備で、バリアフリーの考え方にあたる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-10', '正答は C「2000年代」。

我が国の総人口は2008年をピークに、以後は減少に転じている。少子化により出生数が死亡数を下回る自然減が定着したためである。

【誤答選択肢の解説】
A「1980年代」: 1980年代はまだ人口が増加していた。
B「1990年代」: 1990年代も増加が続いていた。合計特殊出生率の低下が問題になり始めた時期である。
D「2010年代」: 2010年代は既に減少が続いていた時期で、転じた時期ではない。
E「2020年代」: 2020年代も減少が続いている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-11', '正答は D「インドメタシン — 動脈管収縮」。

インドメタシンなどのNSAIDはプロスタグランジンの合成を抑えるため、胎児の動脈管を収縮させる。妊娠後期の使用は避ける。

【誤答選択肢の解説】
A「アンジオテンシン変換酵素〈ACE〉阻害薬 — 羊水過多症」: ACE阻害薬は胎児の腎機能を障害して尿量を減らすため、羊水過少症をきたす。
B「吸入副腎皮質ステロイド — 早産」: 吸入副腎皮質ステロイドは喘息の管理に必要で、妊娠中も継続する。早産の原因にはならない。
C「ミソプロストール — 脳出血」: ミソプロストールは子宮収縮を起こして流産を招く。脳出血ではない。
E「ミノサイクリン — 水腎症」: ミノサイクリンなどのテトラサイクリン系は胎児の歯の着色と骨形成の抑制をきたす。水腎症ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-12', '正答は A「60分以下」。

分娩第2期(子宮口全開大から児娩出まで)の所要時間は、初産婦で2〜3時間、経産婦では1時間以下が目安である。これを超えて進行しない場合は遷延を疑う。

【誤答選択肢の解説】
B「61〜120分」: 61〜120分は初産婦の目安に近い。
C「121〜180分」: 121〜180分も初産婦の範囲で、経産婦では遷延を考える。
D「181〜240分」: 181〜240分は初産婦でも遷延にあたる。
E「241分以上」: 241分以上はいずれの場合も明らかな遷延である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F012（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-13', '正答は A「後負荷の減少」。

後負荷が減れば左室は同じ収縮力でより多くの血液を駆出できるため、1回拍出量が増えて心拍出量が増加する。血管拡張薬が心不全に有効な理由でもある。

【誤答選択肢の解説】
B「心拍数の減少」: 心拍出量は1回拍出量と心拍数の積なので、心拍数が減れば減少する。
C「前負荷の減少」: 前負荷が減ればFrank-Starlingの法則により1回拍出量が減る。
D「冠血流量の減少」: 冠血流量が減れば心筋の収縮力が落ち、心拍出量は減る。
E「甲状腺機能の低下」: 甲状腺機能低下では心拍数と心収縮力が落ち、心拍出量は減る。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F013（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-14', '正答は A「医療扶助」。

生活保護の8つの扶助のうち、医療扶助と介護扶助は現物給付である。医療扶助では自己負担なく指定医療機関で医療を受けられ、費用は直接医療機関に支払われる。

【誤答選択肢の解説】
B「教育扶助」: 教育扶助は義務教育に必要な費用を金銭で支給する。
C「住宅扶助」: 住宅扶助は家賃相当額を金銭で支給する。
D「生活扶助」: 生活扶助は日常生活に必要な費用を金銭で支給する。
E「葬祭扶助」: 葬祭扶助も費用を金銭で支給する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F014（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-15', '正答は E「有害物質使用工程の密閉化」。

労働衛生の3管理のうち作業環境管理は、有害要因そのものを作業環境から取り除く対策である。有害物質を扱う工程を密閉化して発散を断つのは、その典型で最も効果が高い。

【誤答選択肢の解説】
A「安全な手順の教育」: 安全な手順の教育は労働衛生教育にあたる。
B「暑熱作業の時間制限」: 作業時間の制限は作業管理にあたる。
C「防塵マスク使用の徹底」: 防塵マスクの使用は個人が曝露を減らす対策で、作業管理にあたる。
D「血中鉛高値者の保健指導」: 血中鉛高値者への保健指導は健康管理にあたる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F015（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-17', '正答は C「慢性骨髄性白血病」。

慢性骨髄性白血病では成熟した顆粒球系細胞が骨髄外造血の場である脾臓に浸潤し、臍を越えるほどの著明な脾腫をきたす。左季肋部の膨満感や早期満腹感が受診の契機になる。

【誤答選択肢の解説】
A「多発性骨髄腫」: 多発性骨髄腫では形質細胞が骨髄内で増え、脾腫は通常みられない。
B「急性骨髄性白血病」: 急性骨髄性白血病でも脾腫はあっても軽度である。
D「急性リンパ性白血病」: 急性リンパ性白血病では肝脾腫やリンパ節腫脹をみるが、著明な脾腫は特徴的でない。
E「成人T細胞白血病・リンパ腫」: 成人T細胞白血病・リンパ腫では高カルシウム血症、皮疹、リンパ節腫脹が主体である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-19', '正答は E「臨床経過と病理解剖の所見を比較検討する。」。

臨床病理検討会は、亡くなった患者の臨床経過と病理解剖で得られた所見を突き合わせ、診断や治療が適切だったかを検討する場である。臨床研修の必修項目でもある。

【誤答選択肢の解説】
A「稀な疾患の治療法を相談する。」: 治療法の相談はキャンサーボードなど別の場で行う。
B「入院中の診断困難症例を相談する。」: 入院中の症例の検討はカンファレンスで行う。CPCは剖検例が対象である。
C「医療行為と医療事故の因果関係を評価する。」: 医療行為と事故の因果関係の評価は医療事故調査の枠組みで行う。
D「術前検査の結果から手術の術式を検討する。」: 術式の検討は術前カンファレンスで行う。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-2', '正答は B「白内障」。

放射線白内障は被曝から数か月から数年を経て現れる晩発影響(晩期障害)である。しきい値のある確定的影響で、水晶体の等価線量限度が定められている。

【誤答選択肢の解説】
A「脱毛」: 脱毛は被曝後数週で現れる早期(急性)反応である。
C「運動失調」: 運動失調は胎内被曝や大量被曝による中枢神経症状で、急性期に現れる。
D「けいれん」: けいれんは中枢神経症候群として被曝直後に現れる。
E「皮膚紅斑」: 皮膚紅斑も被曝後数時間から数週で現れる早期反応である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-20', '正答は B「腹部超音波」。

ラジオ波焼灼術は腹部超音波でリアルタイムに病変を描出しながら、経皮的に電極針を腫瘍へ刺入して行う。焼灼範囲の確認にも用いる。

【誤答選択肢の解説】
A「腹部MRI」: MRIは治療前の病変の同定に用いるが、通常この手技の穿刺誘導には使わない。
C「超音波内視鏡」: 超音波内視鏡は消化管壁や膵の観察に用いる。
D「腹部血管造影」: 血管造影は肝動脈化学塞栓療法で用いる。
E「上部消化管内視鏡」: 上部消化管内視鏡は食道・胃・十二指腸の観察に用いる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F020（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-21', '正答は B「脈圧」。

加齢により大血管の弾性が失われて収縮期血圧が上がり、拡張期血圧は下がるため脈圧が増大する。これが収縮期高血圧の主な機序である。

【誤答選択肢の解説】
A「骨量」: 骨量は加齢とともに減少する。
C「肺活量」: 肺の弾性が失われ胸郭も硬くなるため、肺活量は減少する。
D「心拡張能」: 心筋の線維化により拡張能は低下する。
E「糸球体濾過量」: 糸球体濾過量も加齢とともに低下する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F021（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-22', '正答は D「植込み型ペースメーカ」。

植込み型ペースメーカは血液と接する人工物が電極先端に限られ、血流も妨げないため抗凝固療法を要さない。心房細動などの合併があれば別の理由で抗凝固薬を用いる。

【誤答選択肢の解説】
A「ECMO」: ECMOは血液を体外の回路に通すため抗凝固が必須である。
B「人工心肺装置」: 人工心肺装置も体外循環であり抗凝固が必須である。
C「人工弁(機械弁)」: 機械弁は血栓を生じやすく、ワルファリンによる生涯の抗凝固が必要である。
E「植込み型補助人工心臓」: 植込み型補助人工心臓もポンプ内の血栓形成を防ぐため抗凝固が必須である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-23', '正答は A「t検定」。

血圧のような連続変数の平均を2群で比べるにはt検定を用いる。分布が正規でなければMann-WhitneyのU検定などノンパラメトリック法を使う。

【誤答選択肢の解説】
B「χ2検定」: χ2検定は割合など質的データの分布を比べるのに用いる。
C「生存分析」: 生存分析は事象が起こるまでの時間を扱う。
D「比例ハザードモデル」: 比例ハザードモデルは生存時間に対する複数因子の影響をみる。
E「ロジスティック回帰」: ロジスティック回帰は2値の結果に対する複数因子の影響をみる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F023（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-24', '正答は C「複数の臼歯が生える。」。

離乳は生後5〜6か月ごろに始めるが、乳歯が生え始めるのはそのころで、臼歯が生えそろうのは1歳半以降である。臼歯の萌出を待つ必要はない。

【誤答選択肢の解説】
A「5秒以上座れる。」: 支えがあれば座位を保てることは、安全に食べさせるための目安になる。
B「食べ物に興味を示す。」: 大人が食べる様子に関心を示すことは、離乳開始のよい合図である。
D「首のすわりがしっかりしている。」: 定頸は誤嚥を防ぐうえで欠かせない前提である。
E「スプーンを口に入れても嫌がらない。」: 哺乳反射が減弱してスプーンを受け入れられることが目安になる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-25', '正答は E「連合弛緩」。

連合弛緩は考えのつながりが緩んで話がまとまらなくなる思考の障害(思考過程の障害)であり、知覚の障害ではない。

【誤答選択肢の解説】
A「幻嗅」: 幻嗅は対象のない匂いを感じる知覚の障害である。
B「幻視」: 幻視も対象のない視覚体験で知覚の障害である。
C「思考化声」: 思考化声は自分の考えが声として聞こえる幻聴の一種である。
D「体感幻覚」: 体感幻覚は身体の内部に生じる異常な感覚で、知覚の障害である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-26', '正答は E「腕頭動脈」。

腕頭動脈は大動脈弓から分かれて胸骨柄の背側を走り、右鎖骨下動脈と右総頸動脈に分かれる。頸部の体表からは圧迫できない位置にある。

【誤答選択肢の解説】
A「気管」: 気管は前頸部の皮下にあり、強く圧迫すれば閉塞して窒息する。
B「外頸静脈」: 外頸静脈は胸鎖乳突筋の表層を走り、圧迫で容易に閉塞する。
C「総頸動脈」: 総頸動脈は胸鎖乳突筋の内側で触知でき、圧迫できる。
D「内頸静脈」: 内頸静脈も頸動脈鞘内にあり、圧迫の影響を受ける。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F026（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-27', '正答は C「①4 ②5 ③1」。

後期高齢者医療制度の財源は、患者負担を除くと公費が約5割、現役世代からの支援金が約4割、高齢者本人の保険料が約1割で構成される。したがって①4割、②5割、③1割となる。

【誤答選択肢の解説】
A「①2 ②5 ③3」: 支援金2割・公費5割・保険料3割では、支援金と保険料の割合が実際と食い違う。
B「①4 ②3 ③3」: 公費が3割では、財源の半分を公費が占めるという構成を説明できない。
D「①5 ②2 ③3」: 支援金5割・公費2割は、公費と支援金の関係が逆転している。
E「①5 ②4 ③1」: 支援金5割・公費4割も、公費が最大の財源であるという構成に合わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F027（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-28', '正答は C「遠隔医療の推進」。

持続可能な開発目標は貧困、飢餓、保健、教育、ジェンダー、水、エネルギー、経済成長、不平等、気候変動など17の目標からなる。遠隔医療の推進という個別の手段は目標に掲げられていない。

【誤答選択肢の解説】
A「貧困撲滅」: 目標1はあらゆる場所のあらゆる形態の貧困を終わらせることである。
B「格差の是正」: 目標10は国内および国家間の不平等を是正することである。
D「ジェンダー平等」: 目標5はジェンダー平等の達成である。
E「気候変動への対応」: 目標13は気候変動とその影響に立ち向かうための緊急対策である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F028（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-29', '正答は C「脂肪細胞での中性脂肪分解促進」。

インスリンは同化ホルモンで、脂肪細胞ではリポ蛋白リパーゼを活性化して中性脂肪の合成・蓄積を促し、ホルモン感受性リパーゼを抑えて分解を抑制する。分解を促進するという記述は逆である。

【誤答選択肢の解説】
A「肝臓での糖新生抑制」: 肝での糖新生を抑えて血糖の上昇を防ぐ。
B「肝臓でのグリコーゲン合成促進」: 肝でグリコーゲン合成を促し、グルコースを貯蔵する。
D「骨格筋でのアミノ酸取り込み促進」: 骨格筋へのアミノ酸取り込みと蛋白合成を促す。
E「骨格筋でのグルコース取り込み促進」: GLUT4の細胞膜への移動を促して骨格筋のグルコース取り込みを増やす。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F029（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-3', '正答は E「背部の外傷は側臥位にして確認する。」。

骨盤骨折が疑われる患者を側臥位にすると、骨折部がずれて後腹膜出血を悪化させる。背部の観察は頭部・体幹を一直線に保ったまま複数人で行うログロールで、必要最小限にとどめる。

【誤答選択肢の解説】
A「血圧変化を確認する。」: 後腹膜への大量出血をきたすため、血圧の推移の確認は必須である。
B「下肢脚長差を確認する。」: 骨盤輪の転位を反映して下肢の脚長差が生じる。
C「骨盤周辺の打撲痕を確認する。」: 打撲痕や皮下出血は受傷部位と外力の方向を示す手がかりになる。
D「外尿道口からの出血を確認する。」: 外尿道口からの出血は尿道損傷を示唆し、盲目的な導尿を避ける判断につながる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-30', '正答は D「リスクファクターの数に応じて対象者を抽出する。」。

特定保健指導は特定健康診査の結果から、腹囲や体格に加えて血糖・脂質・血圧・喫煙という危険因子の数によって動機付け支援と積極的支援に階層化して対象者を選ぶ。

【誤答選択肢の解説】
A「事業主が実施する。」: 実施主体は医療保険者である。
B「20歳以上を対象とする。」: 対象は40歳から74歳までである。
C「健康増進法で規定されている。」: 根拠法は高齢者の医療の確保に関する法律である。
E「ポピュレーションストラテジーに基づいて対策する。」: 危険因子をもつ個人を選んで介入するハイリスクストラテジーである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F030（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-37', '正答は B「呼気延長」。

気管支喘息の中発作である。末梢気道が狭窄するため呼気に時間がかかり、聴診で呼気の延長とwheezesを聴取する。胸部エックス線写真の肺過膨張も呼出障害を反映している。

【誤答選択肢の解説】
A「嗄声」: 嗄声は喉頭の病変でみられる。喘息では生じない。
C「犬吠様咳嗽」: 犬吠様咳嗽はクループ(急性喉頭蓋炎・急性声門下喉頭炎)の症状である。
D「無呼吸発作」: 無呼吸発作は乳児の細気管支炎や百日咳でみられる。
E「レプリーゼ」: レプリーゼは百日咳の痙咳発作の後にみられる笛声様の吸気である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F037（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-38', '正答は B「非侵襲的陽圧換気〈NPPV〉」。

pH7.32、PaCO2 60Torrと急性増悪した慢性II型呼吸不全で、意識は清明で喀痰も少ない。非侵襲的陽圧換気は換気を助けて二酸化炭素を洗い出し、挿管を回避できる。

【誤答選択肢の解説】
A「気管挿管」: 意識が保たれ気道分泌も多くないので、まずNPPVを試みる。
C「短時間作用性β2刺激薬吸入」: 気道の可逆性狭窄が主体ではなく、β2刺激薬では換気不全は改善しない。
D「グルココルチコイド点滴静注」: グルココルチコイドは慢性閉塞性肺疾患の急性増悪で補助的に用いるが、換気不全そのものを是正しない。
E「リザーバー付マスク10L/分酸素投与」: 高流量の酸素はCO2ナルコーシスを招く。目標SpO2を88〜92%程度に抑える。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F038（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-39', '正答は D「大泉門」。

在胎期間の推定にはNew Ballard法などを用い、皮膚の成熟度、うぶ毛、足底のしわ、乳房・乳輪の発達、耳介の軟骨、外性器といった身体的成熟の指標と神経学的所見を組み合わせる。大泉門の大きさは在胎期間を反映しない。

【誤答選択肢の解説】
A「乳房」: 乳輪の隆起と乳腺組織の触知量は成熟の指標である。
B「皮膚」: 皮膚の厚さ、透見される血管、落屑の程度は成熟の指標である。
C「うぶ毛」: うぶ毛は在胎28週ごろ全身を覆い、満期に近づくと減る。
E「足底のしわ」: 足底のしわは満期に近づくほど足底全体に広がる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F039（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-4', '正答は C「労働災害」。

医療計画には5疾病(がん・脳卒中・心筋梗塞等の心血管疾患・糖尿病・精神疾患)と6事業(救急医療、災害時医療、新興感染症対応、へき地医療、周産期医療、小児医療)、在宅医療、地域医療構想、医療従事者の確保などを定める。労働災害は労働者災害補償保険法の領域で、医療計画の記載事項ではない。

【誤答選択肢の解説】
A「救急医療」: 救急医療は医療計画の事業に含まれる。
B「精神疾患」: 精神疾患は5疾病の一つとして含まれる。
D「地域医療構想」: 地域医療構想は医療計画の一部として定められる。
E「医療従事者の確保」: 医療従事者の確保も医療計画の記載事項である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-41', '正答は C「「入院して治療をしましょう」」。

日齢14で38.8°Cの発熱があり、活気不良で大泉門が膨隆している。新生児の発熱は細菌性髄膜炎や敗血症を想定して、入院のうえ血液・尿・髄液を培養し、直ちに抗菌薬を開始する。

【誤答選択肢の解説】
A「「明日まで経過をみましょう」」: 急速に悪化しうるため、翌日まで待つことは許されない。
B「「抗菌薬を内服させましょう」」: 経口の抗菌薬では髄液移行が不十分で、外来治療の対象にならない。
D「「腋窩部や鼠径部を冷却しましょう」」: 冷却は解熱の手段にすぎず、原因の検索と治療が優先される。
E「「母乳栄養を人工栄養へ変更しましょう」」: 母乳を人工乳に変える理由はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F041（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-42', '正答は B「利尿薬の投与」。

径8mmの心室中隔欠損を介する多量の左右短絡により肺うっ血と体重増加不良をきたしている。手術までの橋渡しとして、まず利尿薬で肺うっ血と容量負荷を軽減する。

【誤答選択肢の解説】
A「酸素吸入」: 酸素は肺血管を拡張させて左右短絡をさらに増やすため、この病態では有害になりうる。
C「β遮断薬の投与」: β遮断薬は乳児の急性期心不全の第一選択にならない。
D「アドレナリンの投与」: アドレナリンは心拍出量が保たれている本例には不要で、体血管抵抗を上げて短絡を増やす。
E「肺血管拡張薬の投与」: 肺血管拡張薬は肺血流をさらに増やし、短絡を悪化させる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F042（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-44', '正答は E「ホルムアルデヒド」。

内装の改修後から屋内で症状が出て、換気のよい日は軽い。合板や接着剤から放散するホルムアルデヒドによるシックハウス症候群である。建築基準法で使用が規制され、換気設備の設置が義務づけられている。

【誤答選択肢の解説】
A「オゾン」: オゾンは光化学スモッグや複写機から生じるもので、内装材からは放散しない。
B「エタノール」: エタノールは室内空気汚染の主要な原因物質ではない。
C「二酸化窒素」: 二酸化窒素は燃焼機器や自動車排ガスから生じる。
D「フロンガス」: フロンガスはオゾン層破壊の原因物質で、室内での健康被害は問題にならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F044（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-45', '正答は B「II」。

意思疎通ができ、着替え・食事・排泄・入浴が自立している一方で、服薬と金銭の管理には家族の助けが要る。誰かが注意していれば自立できる段階なのでランクIIにあたる。

【誤答選択肢の解説】
A「I」: ランクIは日常生活がほぼ自立している段階で、服薬管理に助けが必要な本例は当てはまらない。
C「III」: ランクIIIは介護を必要とする段階で、基本的な日常生活動作が自立している本例より重い。
D「IV」: ランクIVは常に介護を必要とする段階である。
E「M」: ランクMは著しい精神症状や問題行動があり専門医療を要する段階だが、周辺症状も問題行動もない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F045（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-46', '正答は D「カリウム」。

eGFR15.3mL/分/1.73m2の高度腎機能低下にK5.8mEq/Lの高カリウム血症を伴い、カリウム摂取量3,500mg/日は過剰である。1,500mg/日程度への制限が要る。塩分5.8g/日と蛋白質30g/日はすでに目標を満たしている。

【誤答選択肢の解説】
A「塩分」: 塩分5.8g/日は6g/日未満の目標を満たしており、これ以上の制限は要らない。
B「水分」: 浮腫は軽度で、飲水1.5L/日は過剰ではない。
C「蛋白質」: 蛋白質30g/日は体重52kgに対し0.6g/kgで、既に十分制限されている。
E「カロリー」: 体重は1年間変化なく、エネルギー摂取は適正である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F046（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-5', '正答は D「中高生の1日のゲームの使用時間」。

健やか親子21(第2次)は、切れ目ない妊産婦・乳幼児への保健対策、学童期・思春期の健やかな体の育成、子どもの健やかな成長を見守る地域づくりを基盤課題とし、育てにくさを感じる親への支援と妊娠期からの児童虐待防止を重点課題としている。ゲームの使用時間は指標に含まれない。

【誤答選択肢の解説】
A「十代の飲酒率」: 十代の飲酒率は学童期・思春期の課題の指標である。
B「妊婦の喫煙率」: 妊婦の喫煙率は妊娠期の指標である。
C「低出生体重児の割合」: 低出生体重児の割合も指標に含まれる。
E「積極的に育児をしている父親の割合」: 積極的に育児をしている父親の割合も指標に含まれる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-50', '正答は E「精神保健福祉センター」。

精神保健福祉センターは都道府県・指定都市に置かれ、精神保健と精神障害者の福祉に関する相談指導、社会復帰の支援、関係機関の情報提供を担う。復職支援や緊急時の受診先の相談窓口として適している。

【誤答選択肢の解説】
A「グループホーム」: グループホームは共同生活を送る住まいで、相談窓口ではない。
B「労働基準監督署」: 労働基準監督署は労働条件と安全衛生の監督を行う機関である。
C「就労移行支援事業所」: 就労移行支援事業所は就労のための訓練を行う場で、緊急受診先の情報提供は担わない。
D「知的障害者更生施設」: 知的障害者を対象とする施設であり、本例には該当しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F050（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-51', '正答は D「4」。

1歳6か月では積み木を2〜3個積めるのが標準で、つまめても積めないのは微細運動の遅れを疑う。ほかの下線部はこの月齢としてふつうにみられる。

【誤答選択肢の解説】
A「1」: 両足で跳べるようになるのは2歳ごろで、できなくてよい。
B「2」: 階段を降りられるようになるのは2歳ごろである。
C「3」: 直線をまねしてひけるようになるのは2歳ごろである。
E「5」: 絵を見て物の名前を言えるようになるのは2歳前後で、1歳6か月では指させれば十分である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F051（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-52', '正答は E「びまん性汎細気管支炎」。

小児期からの副鼻腔炎を思わせる経過に、慢性の膿性痰と労作時呼吸困難が加わり、胸部CTでびまん性小葉中心性粒状影を認めておりびまん性汎細気管支炎である。マクロライド少量長期療法が奏効する。

【誤答選択肢の解説】
A「肺気腫」: 肺気腫は喫煙者に生じ、CTでは低吸収域をみる。喫煙歴はない。
B「粟粒結核」: 粟粒結核では大きさのそろった粒状影が全肺野に均等に分布し、発熱や全身症状を伴う。
C「気管支拡張症」: 気管支拡張症では拡張した気管支と気管支壁の肥厚をみる。小葉中心性粒状影が主体ではない。
D「慢性気管支炎」: 慢性気管支炎では画像所見に乏しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F052（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-53', '正答は C「強迫性障害〈強迫症〉」。

菌が付いているという考えが不合理と分かりながら消えず、洗浄行為が長時間に及んで仕事も家族関係も損なわれている。疎通は良好で病識も保たれており強迫性障害である。SSRIと曝露反応妨害法が治療の中心となる。

【誤答選択肢の解説】
A「統合失調症」: 統合失調症では不合理性の自覚が失われ、疎通性も損なわれることが多い。
B「症状性精神障害」: 症状性精神障害は身体疾患に伴う精神症状で、意識障害や認知機能低下を伴う。
D「身体的苦痛症〈身体症状症〉」: 身体症状症は身体の苦痛と、それへのとらわれが中心で、洗浄強迫は説明できない。
E「素行障害〈素行・非社会的行動症〉」: 素行障害は他者の権利を侵害する反復的な行動が特徴で、本例とは異なる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F053（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-54', '正答は C「地域医療支援病院へ紹介する。」。

誤嚥性肺炎による呼吸不全と血圧低下があり、在宅では対応できない。地域医療支援病院はかかりつけ医からの紹介患者を受け入れて入院治療を担う病院で、紹介先として適している。

【誤答選択肢の解説】
A「介護医療院に入所させる。」: 介護医療院は長期療養の生活の場で、急性期の治療を担わない。
B「特定機能病院へ紹介する。」: 特定機能病院は高度先進医療を担う施設で、標準的な肺炎治療の紹介先ではない。
D「地域包括支援センターに連絡する。」: 地域包括支援センターは介護予防と相談支援の窓口で、急性期の治療は行わない。
E「特別養護老人ホームに入所させる。」: 特別養護老人ホームも生活の場であり、急性期治療の場ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F054（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-55', '正答は E「抗dsDNA抗体」。

若年女性の顔面紅斑、多関節炎、蛋白尿、汎血球減少に高ガンマグロブリン血症を伴っており全身性エリテマトーデスである。抗dsDNA抗体は疾患特異性が高く、抗体価はループス腎炎の活動性とよく相関する。

【誤答選択肢の解説】
A「抗CCP抗体」: 抗CCP抗体は関節リウマチに特異的である。腎障害や血球減少は説明できない。
B「抗Jo-1抗体」: 抗Jo-1抗体は多発性筋炎・皮膚筋炎に伴い、間質性肺炎と関連する。CKは正常である。
C「抗Mi-2抗体」: 抗Mi-2抗体も皮膚筋炎に特異的な抗体である。
D「抗Scl-70抗体」: 抗Scl-70抗体はびまん皮膚硬化型全身性強皮症に特異的である。皮膚硬化はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F055（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-56', '正答は D「輪状甲状靱帯切開」。

換気も気管挿管もできない状況(cannot ventilate, cannot intubate)であり、輪状甲状靱帯を切開して外科的に気道を確保する。低酸素が続けば数分で心停止に至るため、ためらわず移行する。

【誤答選択肢の解説】
A「ECMO」: ECMOの導入には時間がかかり、気道確保の代わりにならない。
B「胸骨圧迫」: 頸動脈を触知でき心停止ではないので、胸骨圧迫の適応ではない。
C「緊急ペーシング」: 徐脈による循環不全ではなく、ペーシングは無効である。
E「大動脈内バルーンパンピング〈IABP〉」: 大動脈内バルーンパンピングは心原性ショックの補助循環で、換気の問題は解決しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F056（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-57', '正答は D「4」。

腸重積症の既往はロタウイルスワクチンの接種禁忌である。ワクチン接種後に腸重積の危険がわずかに高まるためで、初回接種の月齢上限も定められている。

【誤答選択肢の解説】
A「1」: 在胎36週2日の早産は禁忌にあたらない。暦月齢に従って接種する。
B「2」: 出生体重2,460gの低出生体重も禁忌にならない。
C「3」: 卵円孔開存は器質的心疾患ではなく、禁忌にならない。
E「5」: 体温37.0°Cは明らかな発熱(37.5°C以上)にあたらず、接種できる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F057（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-6', '正答は B「赤芽球癆 — シクロスポリン」。

赤芽球癆は赤芽球系のみが選択的に障害される病態で、Tリンパ球による自己免疫機序が関与する。シクロスポリンなどの免疫抑制療法が有効である。

【誤答選択肢の解説】
A「腎性貧血 — グルココルチコイド」: 腎性貧血にはエリスロポエチン製剤やHIF-PH阻害薬を用いる。
C「巨赤芽球性貧血 — エリスロポエチン」: 巨赤芽球性貧血の治療はビタミンB12または葉酸の補充である。
D「慢性炎症に伴う貧血 — 鉄剤」: 慢性炎症に伴う貧血では鉄は貯蔵鉄として封じ込められており、鉄剤は無効である。原疾患の治療が優先される。
E「自己免疫性溶血性貧血 — ガンマグロブリン」: 自己免疫性溶血性貧血の第一選択は副腎皮質ステロイドである。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('118-F-8', '正答は A「バンコク憲章」。

バンコク憲章(2005年)はグローバル化した世界におけるヘルスプロモーションを主題とし、オタワ憲章の理念を発展させた文書である。

【誤答選択肢の解説】
B「リスボン宣言」: リスボン宣言は患者の権利に関する世界医師会の宣言である。
C「ジュネーブ宣言」: ジュネーブ宣言は医師の職業倫理の誓いである。
D「ヘルシンキ宣言」: ヘルシンキ宣言は人を対象とする医学研究の倫理原則である。
E「アルマ・アタ宣言」: アルマ・アタ宣言はプライマリヘルスケアの理念を打ち出した宣言である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第118回医師国家試験 F008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp240424-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-1', '正答は A「膵の萎縮を認める。」。

自己免疫性膵炎では膵がびまん性に腫大し、いわゆるソーセージ様の形態を示す。萎縮ではなく腫大が特徴で、主膵管はびまん性に不整狭細化する。

【誤答選択肢の解説】
B「高齢男性に好発する。」: 60歳代以降の男性に多い。
C「病理で線維化を認める。」: リンパ球と形質細胞の浸潤に伴う線維化(花筵状線維化)と閉塞性静脈炎が病理学的特徴である。
D「IgG4関連疾患に含まれる。」: IgG4関連疾患の膵病変にあたり、涙腺・唾液腺や胆管、後腹膜にも病変を伴うことがある。
E「治療はグルココルチコイド投与が第一選択である。」: グルココルチコイドが第一選択で、速やかに膵腫大と狭細化が改善する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-10', '正答は A「SGLT2阻害薬 — 近位尿細管」。

SGLT2は近位尿細管に発現し、濾過されたグルコースの大部分を再吸収する。SGLT2阻害薬はこれを抑えて尿糖排泄を増やし、血糖低下に加え心・腎保護作用を示す。

【誤答選択肢の解説】
B「抗アルドステロン薬 — Henleの上行脚」: 抗アルドステロン薬が作用するのは集合管である。
C「サイアザイド系利尿薬 — 集合管」: サイアザイド系利尿薬は遠位尿細管のNa-Cl共輸送体を阻害する。
D「バソプレシンV2受容体拮抗薬 — 遠位尿細管」: バソプレシンV2受容体は集合管にあり、拮抗薬は水利尿を起こす。
E「ループ利尿薬 — Henleの下行脚」: ループ利尿薬はHenleの太い上行脚のNa-K-2Cl共輸送体を阻害する。下行脚は水のみを通す。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-16', '正答は D「Kayser-Fleischer輪」。

小児の肝障害に、尿中銅排泄の増加、血清銅とセルロプラスミンの低下がそろっておりWilson病である。角膜Descemet膜への銅沈着によるKayser-Fleischer輪が細隙灯顕微鏡で確認できる。

【誤答選択肢の解説】
A「円錐角膜」: 円錐角膜は角膜が円錐状に突出する疾患で、銅代謝とは無関係である。
B「視神経萎縮」: 視神経萎縮はLeber遺伝性視神経症などでみられる。
C「水晶体混濁」: 白内障はGalactose血症やステロイド長期使用でみられる。Wilson病では特徴的な「ひまわり白内障」もあるが、診断に用いる代表的所見はKayser-Fleischer輪である。
E「桜実紅斑〈cherry red spot〉」: 桜実紅斑はTay-Sachs病やNiemann-Pick病などのライソゾーム病でみられる眼底所見である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A016（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-17', '正答は C「腹部造影CT」。

造影CTは被曝を伴い、思春期の患者に毎回行うと生涯の発癌リスクが積み重なる。腫瘍マーカーと超音波で追跡し、異常が疑われたときにCTを行うのが適切である。

【誤答選択肢の解説】
A「腹部触診」: 腹部触診は無侵襲で、腫瘤の再発を捉える基本の診察である。
B「月経の聴取」: 化学療法後の卵巣機能を評価するため、月経の再開を確認する必要がある。
D「腹部超音波検査」: 超音波検査は被曝がなく、残存卵巣と骨盤内の観察に適している。
E「腫瘍マーカー測定」: AFPは卵黄囊腫瘍のマーカーで、再発を最も早く捉える指標である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-19', '正答は D「自宅待機を指示する。」。

喀痰抗酸菌染色が陽性で排菌が確認された時点で、周囲への感染を防ぐ必要がある。すでに帰宅している患者には自宅待機を指示し、翌日以降の入院と届出につなげる。

【誤答選択肢の解説】
A「勤務先に連絡する。」: 本人の同意なく勤務先へ連絡することはできない。接触者健診は保健所が主体となって進める。
B「保健所に報告する。」: 結核の届出は診断した時点で行うが、確定は培養や核酸増幅検査を待つ。まず本人の行動を制限して感染拡大を防ぐことが先である。
C「抗結核薬を投与する。」: 薬剤感受性を確かめる検体を採取したうえで、入院のうえ治療を始める。帰宅している患者にその場で投与はできない。
E「患者にN95マスクを着用させる。」: 患者にはサージカルマスクを着用させる。N95マスクを着けるのは周囲の医療者である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-2', '正答は A「頸肩腕障害」。

頸肩腕障害は、上肢を一定の姿勢で長時間使う作業により頸部から肩、上肢に痛みやしびれ、こりを生じる作業関連疾患である。VDT作業に従事する若年労働者に多く、作業姿勢と休憩の見直しが対策となる。

【誤答選択肢の解説】
B「肩関節周囲炎」: 肩関節周囲炎は中年以降に多く、肩の可動域制限が主症状である。
C「肘部管症候群」: 肘部管症候群は尺骨神経の絞扼で、環指尺側と小指のしびれと小指球筋の萎縮をきたす。
D「変形性頸椎症」: 変形性頸椎症は加齢による椎間板と椎間関節の変性で、中高年に多い。
E「頸椎後縦靱帯骨化症」: 頸椎後縦靱帯骨化症も中年以降に発症し、進行すると脊髄症状をきたす。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-25', '正答は E「Streptococcus agalactiae(GBS)」。

日齢20の細菌性髄膜炎で、生後1か月未満の起因菌としてはB群溶血性連鎖球菌(Streptococcus agalactiae)が最も多い。産道での垂直感染により生じ、大腸菌とともに新生児髄膜炎の二大起因菌である。

【誤答選択肢の解説】
A「Haemophilus influenzae」: Haemophilus influenzaeは乳児期以降の起因菌で、Hibワクチンの普及により激減した。
B「Neisseria meningitidis」: Neisseria meningitidisは年長児や若年成人に多い。
C「Pseudomonas aeruginosa」: Pseudomonas aeruginosaは院内感染や免疫不全でみられる。
D「Streptococcus pneumoniae」: Streptococcus pneumoniaeは生後3か月以降の主要な起因菌である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-26', '正答は A「腹部造影CT」。

大量飲酒後の激しい心窩部痛にアミラーゼ2,048U/Lを認め、急性膵炎である。造影CTは膵の壊死範囲や周囲への炎症の波及を評価でき、重症度判定に必須である。

【誤答選択肢の解説】
B「腹部超音波検査」: 超音波検査は消化管ガスに妨げられ膵の全体像を捉えにくい。胆石の検索には有用である。
C「超音波内視鏡検査」: 超音波内視鏡は急性期には侵襲が大きく、重症度の判定には向かない。
D「磁気共鳴胆管膵管撮影〈MRCP〉」: MRCPは胆管結石の検索に有用だが、膵の壊死範囲の評価は造影CTが優れる。
E「内視鏡的逆行性胆管膵管造影〈ERCP〉」: ERCPは膵炎を悪化させうるため、胆石性膵炎で胆管炎を伴う場合などに限られる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A026（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-27', '正答は E「ビタミンB1」。

慢性の大量飲酒者に、意識障害・眼球運動障害・失調性歩行の三徴がそろっておりWernicke脳症である。ビタミンB1の測定結果を待たずに直ちに投与する。ブドウ糖を先に投与すると症状が悪化するので順序に注意する。

【誤答選択肢の解説】
A「亜鉛」: 亜鉛欠乏は味覚障害や皮膚炎をきたすが、この三徴は説明できない。
B「鉄剤」: 貧血はあるが緊急に鉄剤を要する状態ではなく、原因の評価が先である。
C「葉酸」: 葉酸欠乏も飲酒者にみられるが、Wernicke脳症を防ぐのはビタミンB1である。
D「ビタミンD」: ビタミンD欠乏は骨軟化症をきたすもので、急を要さない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A027（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-30', '正答は C「血糖値の異常」。

食後数時間で空腹感とともに動悸・発汗・手指振戦が現れ、糖分の摂取で軽快する。耐糖能異常を背景とした反応性低血糖で、症状の原因は血糖値の異常である。

【誤答選択肢の解説】
A「高血圧症」: 血圧142/88mmHgは軽度の上昇にすぎず、この症状の説明にならない。
B「更年期障害」: 更年期のホットフラッシュは時間帯や食事と無関係に起こり、糖分で改善しない。
D「スタチン内服」: スタチンの有害事象は筋症状と肝障害で、低血糖症状は起こさない。
E「慢性甲状腺炎」: TSHとFT4はいずれも基準内で、甲状腺機能は正常である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A030（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-31', '正答は D「心臓カテーテル検査」。

労作時胸痛が増悪して安静時にも持続し、ST低下とトロポニンT陽性を認めており非ST上昇型急性冠症候群である。侵襲的検査(心臓カテーテル検査)による冠動脈の評価と血行再建を早期に行う。

【誤答選択肢の解説】
A「運動負荷心電図検査」: 症状が持続している状況で運動負荷をかけることは禁忌である。
B「冠動脈CT」: 冠動脈CTは低リスク例の除外に用いる検査で、この状況では治療の遅れにつながる。
C「心臓MRI」: 心臓MRIは心筋症や心筋炎の評価に用いる。
E「薬物負荷心筋血流シンチグラフィ」: 薬物負荷心筋血流シンチグラフィも安定狭心症の評価に用いる検査である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A031（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-32', '正答は D「HBV-DNA定量」。

HBs抗原陰性でHBc抗体陽性は既往感染を示す。リツキシマブを含む化学療法ではHBVが再活性化して劇症肝炎に至ることがあるため、治療前にHBV-DNA定量を行い、以後も定期的に監視する。

【誤答選択肢の解説】
A「HBc抗原」: HBc抗原は血中で測定できない。
B「HBe抗原」: HBe抗原はHBs抗原陽性例でウイルス量の目安として測るもので、既往感染例の再活性化監視には用いない。
C「HBe抗体」: HBe抗体も同様に、再活性化の監視の指標にならない。
E「HCV-RNA定量」: HCV抗体が陰性であり、HCV-RNAを測る意義はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A032（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-36', '正答は E「大腿骨遠位端」。

新生児マススクリーニング陽性で、哺乳力低下、遷延性黄疸、便秘、大泉門の開大、臍ヘルニアがそろっており先天性甲状腺機能低下症である。骨成熟の遅れをみるには、満期産児で通常存在する大腿骨遠位端骨核の有無を確認する。

【誤答選択肢の解説】
A「頭蓋骨」: 頭蓋骨のエックス線写真では骨成熟を評価できない。
B「肋骨」: 肋骨も骨年齢の指標にならない。
C「手根骨」: 手根骨の骨核が現れるのは生後数か月以降で、新生児期の評価には使えない。
D「腰椎」: 腰椎も骨成熟の指標にならない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A036（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-39', '正答は E「de Quervain病」。

手関節橈側の腫脹と圧痛に加え、母指を握り込んで手関節を尺屈させると疼痛が誘発される(Finkelstein試験陽性)。短母指伸筋腱と長母指外転筋腱の腱鞘炎であるde Quervain病である。

【誤答選択肢の解説】
A「ばね指」: ばね指は屈筋腱の腱鞘炎で、指の屈伸時に引っかかりや弾発現象を生じる。
B「関節リウマチ」: 関節リウマチは多関節の対称性腫脹をきたす。指関節に異常はない。
C「手根管症候群」: 手根管症候群は正中神経の絞扼で、母指から環指橈側のしびれが主症状である。感覚障害はない。
D「肘部管症候群」: 肘部管症候群は尺骨神経の絞扼で、環指尺側と小指の症状をきたす。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A039（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-4', '正答は E「ケラトアカントーマ — 臍部」。

ケラトアカントーマは日光に当たる顔面や手背などの露出部に生じ、中央にケラチン栓をもつ半球状の腫瘤として急速に増大する。臍部は好発部位ではない。

【誤答選択肢の解説】
A「疥癬 — 外陰部」: 疥癬はヒゼンダニが手指間、腋窩、外陰部などの柔らかい皮膚に寄生する。外陰部の結節は男性で特徴的である。
B「ケロイド — 耳介」: ケロイドは前胸部、肩、恥骨部とともに耳介(ピアス孔)に好発する。
C「脂腺母斑 — 頭部」: 脂腺母斑は頭部の脱毛斑として生まれつき存在する。
D「血管性浮腫 — 口唇」: 血管性浮腫は口唇や眼瞼など疎な結合組織の部位に生じやすい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-41', '正答は B「酸分泌抑制薬」。

内視鏡や画像で器質的異常がなく、心窩部痛と早期飽満感がストレスと関連して続いており機能性ディスペプシアである。心窩部痛症候群には酸分泌抑制薬が第一選択となる。

【誤答選択肢の解説】
A「NSAID」: NSAIDは胃粘膜を傷害し、症状を悪化させる。
C「ニトログリセリン」: ニトログリセリンは狭心症に用いる。
D「グルココルチコイド」: グルココルチコイドは適応がなく、胃粘膜傷害の危険もある。
E「グルカゴン類似ペプチド〈GLP-1〉」: GLP-1受容体作動薬は胃排出を遅らせるため、早期飽満感を悪化させる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A041（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-42', '正答は E「確定診断には核酸増幅検査が用いられる。」。

膿性の尿道分泌物にGram陰性双球菌を認め淋菌性尿道炎である。核酸増幅検査は感度が高く、咽頭を含む検体でも診断でき、クラミジアの同時検出も可能で確定診断に用いる。

【誤答選択肢の解説】
A「潜伏期間は2〜3週間である。」: 潜伏期は2〜7日と短い。2〜3週間の潜伏期はクラミジアの特徴である。
B「パートナーの治療は不要である。」: 無症状のパートナーも治療しなければ再感染(ピンポン感染)を繰り返す。
C「1回感染すると終生免疫を獲得する。」: 淋菌感染に終生免疫は成立せず、何度でも感染する。
D「ニューキノロン系抗菌薬を投与する。」: ニューキノロン耐性が広がっており第一選択にならない。セフトリアキソンの単回静注を用いる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A042（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-45', '正答は C「炭酸リチウム」。

昇進を機に多弁、浪費、活動性亢進をきたした躁状態である。カルバマゼピンでStevens-Johnson症候群を起こした既往があり、気分安定薬としては炭酸リチウムを選ぶ。腎機能と血中濃度の監視が要る。

【誤答選択肢の解説】
A「ジアゼパム」: ジアゼパムは不安や不眠に一時的に用いるだけで、躁状態の治療薬ではない。
B「イミプラミン」: イミプラミンなどの抗うつ薬は躁状態を増悪させる。
D「フェニトイン」: フェニトインは抗てんかん薬で、気分安定作用はない。またカルバマゼピンとの交差反応の危険もある。
E「カルバマゼピン」: カルバマゼピンは重篤な薬疹の既往があり禁忌である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A045（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-46', '正答は D「Guillain-Barré症候群」。

先行感染の1週間後に、外眼筋麻痺・運動失調・腱反射消失の三徴が現れており、Guillain-Barré症候群の亜型であるFisher症候群である。抗GQ1b抗体が陽性となり、多くは自然に軽快する。

【誤答選択肢の解説】
A「重症筋無力症」: 重症筋無力症では症状に日内変動があり、腱反射は保たれる。
B「多発性硬化症」: 多発性硬化症は時間的・空間的多発を示し、腱反射はむしろ亢進する。
C「進行性核上性麻痺」: 進行性核上性麻痺は垂直方向の眼球運動障害と易転倒性をきたすが、年単位で緩徐に進行する。
E「筋萎縮性側索硬化症〈ALS〉」: 筋萎縮性側索硬化症では眼球運動が保たれ、腱反射は亢進する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A046（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-47', '正答は B「赤血球輸血」。

汎血球減少で骨髄は過形成、3系統に異形成を認め芽球は増えておらず骨髄異形成症候群(低リスク群)である。エリスロポエチンは10mIU/mLと低く反応が期待できないため、症状のある貧血には赤血球輸血で対応する。

【誤答選択肢の解説】
A「血漿交換」: 血漿交換を要する病態ではない。
C「グルココルチコイド投与」: グルココルチコイドは再生不良性貧血にも骨髄異形成症候群にも標準治療とならない。
D「トロンボポエチン受容体作動薬投与」: トロンボポエチン受容体作動薬は血小板減少に用いるが、Hb5.2g/dLの貧血が当面の問題である。
E「顆粒球コロニー刺激因子〈G-CSF〉投与」: G-CSFは好中球減少に用いるもので、貧血は改善しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A047（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-5', '正答は B「排尿前」。

家庭血圧は起床後1時間以内、排尿後、朝食前、服薬前に、座位で1〜2分の安静をとってから測る。膀胱が充満していると交感神経が刺激されて血圧が上がるため、排尿前ではなく排尿後に測る。

【誤答選択肢の解説】
A「朝食前」: 食事の影響を避けるため朝食前に測る。
C「服薬前」: 降圧薬の効果が切れた時点の値をみるため服薬前に測る。
D「座位安静後」: 1〜2分の座位安静後に測ることが定められている。
E「起床後1時間以内」: 起床後1時間以内に測ることで、早朝高血圧を捉えられる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-53', '正答は C「急性間質性腎炎」。

抗菌薬の投与後に腎機能が急速に悪化し、尿中β2-マイクログロブリンが著明に上昇して尿糖も陽性である。尿細管障害を示す所見であり、薬剤性の急性間質性腎炎が最も考えられる。被疑薬の中止が治療の基本となる。

【誤答選択肢の解説】
A「膜性腎症」: 膜性腎症は高度の蛋白尿を呈するが、蛋白は(±)にとどまる。
B「糖尿病腎症」: 血糖98mg/dL、HbA1c5.2%で糖尿病はない。尿糖陽性は尿細管での再吸収障害による。
D「急性糸球体腎炎」: 急性糸球体腎炎では血尿と赤血球円柱、補体低下を認める。潜血陰性でC3も高値である。
E「急速進行性糸球体腎炎」: 急速進行性糸球体腎炎ではANCAや抗GBM抗体が陽性となり、血尿と赤血球円柱を認める。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A053（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-55', '正答は A「放射線治療」。

両側の骨盤壁に及ぶ子宮傍組織浸潤があり進行子宮頸癌(IIIB期以上)である。手術の適応はなく、根治を目指すには同時化学放射線療法を行う。出血の制御にも放射線治療が有効である。

【誤答選択肢の解説】
B「血管新生阻害薬」: 血管新生阻害薬は化学療法との併用で再発・転移例に用いる。
C「広汎子宮全摘出術」: 骨盤壁に達する浸潤があり、広汎子宮全摘出術の適応外である。
D「シスプラチン動注」: 動注化学療法は標準治療として位置づけられていない。
E「免疫チェックポイント阻害薬」: 免疫チェックポイント阻害薬は既治療の再発・転移例が対象である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A055（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-56', '正答は A「血漿交換」。

発熱、意識障害、血小板減少、破砕赤血球を伴う溶血性貧血、腎機能障害の五徴がそろい、PT・APTT・FDPが正常で血栓性血小板減少性紫斑病である。ADAMTS13活性の低下が本態で、直ちに血漿交換を行う。

【誤答選択肢の解説】
B「血小板輸血」: 血小板輸血は血栓形成を助長するため原則として避ける。
C「抗菌薬投与」: CRP0.8mg/dLと炎症所見に乏しく、感染症を示す所見はない。
D「ヘパリン投与」: FDP9μg/mLとPT・APTTは正常で播種性血管内凝固ではなく、ヘパリンの適応はない。
E「トロンボポエチン受容体作動薬投与」: トロンボポエチン受容体作動薬は免疫性血小板減少性紫斑病に用いるもので、この病態には無効である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A056（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-57', '正答は C「カルシウム拮抗薬」。

深夜から早朝の安静時に起こる胸痛が、器質的狭窄のないまま硝酸薬で速やかに消失しており冠攣縮性狭心症である。カルシウム拮抗薬が発作の予防に最も有効で、禁煙も欠かせない。

【誤答選択肢の解説】
A「スタチン」: スタチンは動脈硬化の進展抑制に有用だが、攣縮そのものは抑えない。
B「DPP-4阻害薬」: DPP-4阻害薬は血糖降下薬で、攣縮には無効である。
D「ビスホスホネート製剤」: ビスホスホネート製剤は骨粗鬆症の治療薬である。
E「アンジオテンシン受容体拮抗薬〈ARB〉」: ARBは降圧薬で、冠攣縮の予防薬としては位置づけられていない。β遮断薬はむしろ攣縮を誘発しうる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A057（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-64', '正答は B「β遮断薬の投与」。

安静時痛と潰瘍・壊死を伴う包括的高度慢性下肢虚血で、浅大腿動脈の閉塞に対して血行再建を急ぐ。β遮断薬は末梢血管抵抗を高めて症状を悪化させうるため、この病態での投与は適切でない。

【誤答選択肢の解説】
A「下肢切断術」: 壊死と感染が制御できなければ切断もやむを得ず、選択肢として考慮される。
C「外科的バイパス術」: 浅大腿動脈の長区間閉塞にはバイパス術が有力な選択肢である。
D「経皮的血管形成術」: 血管内治療による血行再建も第一に検討される。
E「プロスタグランジン製剤の投与」: プロスタグランジン製剤は血行再建が難しい場合の補助的治療として用いられる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A064（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-65', '正答は C「「アドレナリン吸入を行います」」。

オットセイの鳴き声のような犬吠様咳嗽、吸気性喘鳴、陥没呼吸からクループ症候群(急性声門下喉頭炎)である。中等症以上ではアドレナリンの吸入で声門下の浮腫を速やかに減らす。デキサメタゾンの全身投与も併せて行う。

【誤答選択肢の解説】
A「「人工呼吸管理を行います」」: 会話が可能で酸素化も保たれており、人工呼吸管理を要する段階ではない。
B「「β2刺激薬吸入を行います」」: 閉塞部位は声門下で、β2刺激薬は下気道に作用するため無効である。
D「「抗ヒスタミン薬静注を行います」」: アレルギー反応ではなく、抗ヒスタミン薬は効かない。
E「「副腎皮質ステロイド吸入を行います」」: 副腎皮質ステロイドは全身投与(経口・静注)を行う。吸入では十分な効果が得られない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A065（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-68', '正答は B「自由に行動させて観察する。」。

言語発達の遅れ、独特の抑揚とオウム返し、視線の合いにくさ、同一性へのこだわりから自閉スペクトラム症が疑われる。診察室では自由に行動させ、その様子から対人関係やこだわりを観察するのが最も有用である。

【誤答選択肢の解説】
A「押さえつけて診察する。」: 押さえつけると強い抵抗を招き、以後の診察も難しくなる。
C「着席するよう厳しく指示する。」: 厳しい指示は理解されず、混乱を招くだけである。
D「しつけが悪いと両親を注意する。」: 養育が原因ではなく、両親を責めることは支援の妨げになる。
E「行動が落ち着いた時期の再受診を両親に指示する。」: 受診の機会を逃さず、この場で観察と評価を進める。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A068（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-7', '正答は E「連続性病変」。

潰瘍性大腸炎の炎症は直腸から連続性・びまん性に口側へ広がり、粘膜と粘膜下層にとどまる。この連続性が、区域性(skip lesion)に病変が分布するCrohn病との最大の鑑別点である。

【誤答選択肢の解説】
A「敷石像」: 敷石像は縦走潰瘍と横走潰瘍に囲まれた粘膜の隆起で、Crohn病の所見である。
B「縦走潰瘍」: 縦走潰瘍もCrohn病に特徴的である。
C「全層性炎症」: 全層性の炎症はCrohn病の特徴で、瘻孔や狭窄の原因となる。
D「難治性痔瘻」: 難治性痔瘻もCrohn病でみられ、そこから診断されることがある。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-8', '正答は E「1日尿量が2,000mL以上となるように水分摂取が推奨される。」。

尿が濃縮されると結晶が析出しやすくなるため、1日尿量2,000mL以上を目標に水分を摂ることが結石成分によらず共通の予防策である。

【誤答選択肢の解説】
A「低カルシウム食が推奨される。」: カルシウム摂取を減らすと腸管でシュウ酸と結合する相手が減り、吸収されたシュウ酸が尿中に増えてかえって結石ができやすくなる。
B「予防法は結石成分によらず同じである。」: 尿酸結石では尿のアルカリ化、シスチン結石でも尿のアルカリ化と、成分ごとに予防法は異なる。
C「野菜と果実の摂取量を制限することが推奨される。」: 野菜と果実はクエン酸やカリウムを含み、結石の形成を抑える。摂取が勧められる。
D「食事によるナトリウム摂取量を制限する必要はない。」: ナトリウムの過剰摂取は尿中カルシウム排泄を増やすため、減塩が勧められる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-A-9', '正答は D「再脱臼は若年者で生じやすい。」。

肩関節前方脱臼では関節唇や関節包が損傷し、若年者ほど修復が不十分で再脱臼しやすい。10歳代の発症では再脱臼率が高く、鏡視下の修復術が検討される。

【誤答選択肢の解説】
A「横隔神経麻痺の合併が多い。」: 合併しやすいのは腋窩神経麻痺で、三角筋の筋力低下と肩外側の知覚低下をきたす。
B「肩関節周囲炎の原因となる。」: 肩関節周囲炎は加齢に伴う退行性変化によるもので、脱臼が原因ではない。
C「後方に脱臼することが多い。」: 肩関節脱臼の大部分(9割以上)は前方脱臼である。
E「肩関節内転位で脱臼することが多い。」: 外転・外旋を強制されたときに前方へ脱臼する。内転位ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 A009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-1', '正答は A「鶏眼 — うおのめ」。

鶏眼は足底の圧迫部に角質が楔状に増殖したもので、俗に「うおのめ」と呼ばれる。中心の芯が真皮を圧迫して痛む。

【誤答選択肢の解説】
B「色素性母斑 — とびひ」: 「とびひ」は伝染性膿痂疹の俗称である。色素性母斑は「ほくろ」と呼ばれる。
C「水痘 — みずいぼ」: 「みずいぼ」は伝染性軟属腫の俗称である。水痘は「みずぼうそう」である。
D「麦粒腫 — そばかす」: 「そばかす」は雀卵斑の俗称である。麦粒腫は「ものもらい」と呼ばれる。
E「風疹 — はしか」: 「はしか」は麻疹の俗称である。風疹は「三日はしか」と呼ばれる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-10', '正答は A「外国籍でも加入できる。」。

在留資格をもち住所を有する外国籍の人も、国民健康保険や被用者保険に加入できる。国民皆保険は国籍ではなく居住と就労の状況に基づく。

【誤答選択肢の解説】
B「財源は保険料より公費が多い。」: 財源の内訳は保険料が約5割、公費が約4割で、保険料のほうが多い。
C「療養の給付は現金給付である。」: 療養の給付は医療サービスそのものを受ける現物給付である。
D「予防接種は保険給付の対象である。」: 予防接種や健康診断など疾病の治療にあたらないものは給付の対象外である。
E「保険医療機関は調剤を行う院外薬局を指定する。」: 患者には薬局を選ぶ自由があり、医療機関が指定することはできない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-11', '正答は E「チアノーゼ」。

チアノーゼは還元ヘモグロビンが5g/dLを超えると現れる。したがって多血症では出やすく、高度の貧血では低酸素があっても出にくいことに注意する。

【誤答選択肢の解説】
A「黄疸」: 黄疸はビリルビンの増加により皮膚と眼球結膜が黄染するものである。
B「紅斑」: 紅斑は真皮の血管拡張・充血によるもので、圧迫すると退色する。
C「紫斑」: 紫斑は皮下の出血で、圧迫しても退色しない。
D「網状皮斑」: 網状皮斑は皮膚の網目状の色調変化で、血管攣縮や塞栓でみられる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-12', '正答は B「胸椎の叩打痛」。

思春期特発性脊柱側弯症は無痛性に進行するのが特徴で、叩打痛は認めない。疼痛を伴う場合は骨腫瘍や感染など別の原因を疑う必要がある。

【誤答選択肢の解説】
A「肋骨隆起」: 前屈させると椎体の回旋により肋骨隆起(rib hump)が現れ、早期発見に有用である。
C「片側肩甲骨の突出」: 椎体の回旋により片側の肩甲骨が突出する。
D「肩の高さの左右差」: 側弯により左右の肩の高さに差が生じる。
E「ウエストラインの非対称」: 体幹の傾きによりウエストラインが非対称になる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B012（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-13', '正答は D「大量のエストロゲンは骨端線を閉鎖させる。」。

エストロゲンは骨端軟骨の成熟を促し、最終的に骨端線を閉鎖させる。思春期の急激な身長の伸びが止まるのはこのためで、思春期早発症では最終身長が低くなる。

【誤答選択肢の解説】
A「初経は排卵性の月経である。」: 初経後1〜2年は無排卵性の月経周期が多い。
B「思春期まで卵胞数は増加する。」: 卵胞数は胎生期の約700万個をピークに減り続け、出生時に約200万個、思春期には30万個ほどになる。
C「初経前にゴナドトロピンは低下する。」: 初経に先立ってゴナドトロピンの分泌は増加する。
E「二次性徴は陰毛発育、乳房発育、初経の順に進む。」: 二次性徴は乳房発育(思春期の始まり)、陰毛発育、初経の順に進む。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B013（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-14', '正答は A「訪問介護」。

訪問介護(ホームヘルプ)は身体介護と生活援助を行う介護保険の生活支援サービスで、ケアプランに基づいて提供される。医師の指示は要らない。

【誤答選択肢の解説】
B「訪問看護」: 訪問看護は医師が交付する訪問看護指示書に基づいて行う。
C「訪問栄養指導」: 訪問栄養食事指導は医師の指示に基づいて管理栄養士が行う。
D「訪問薬剤管理指導」: 訪問薬剤管理指導も医師の指示に基づいて薬剤師が行う。
E「訪問リハビリテーション」: 訪問リハビリテーションも医師の指示が必要である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B014（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-15', '正答は E「左側臥位」。

上部消化管内視鏡検査は左側臥位で行う。胃の大彎側が下になって観察しやすく、唾液や吐物が口の外に流れて誤嚥を防げるためである。

【誤答選択肢の解説】
A「右側臥位」: 右側臥位では胃の観察に不利で、唾液も咽頭に貯留しやすい。
B「起座位」: 起座位では内視鏡の挿入と観察が行えない。
C「仰臥位」: 仰臥位では唾液や吐物を誤嚥する危険が高い。
D「砕石位」: 砕石位は経腟・経肛門の処置で用いる体位である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B015（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-16', '正答は C「頭痛」。

急性中耳炎に頭痛が加われば、炎症が乳突蜂巣を越えて頭蓋内に及ぶ合併症(硬膜外膿瘍、S状静脈洞血栓症、髄膜炎、脳膿瘍)を疑う。緊急に側頭骨と頭部の画像検査を行う。

【誤答選択肢の解説】
A「耳痛」: 耳痛は急性中耳炎の主症状で、それ自体は画像検査の適応にならない。
B「耳漏」: 耳漏は鼓膜穿孔による排膿で、通常は症状の軽快につながる。
D「難聴」: 難聴は中耳の貯留液による伝音難聴で、急性中耳炎に通常みられる。
E「発熱」: 発熱も急性中耳炎によくみられる症状である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B016（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-17', '正答は E「エネルギー」。

保存期末期腎不全では蛋白質を制限するため、そのぶんエネルギーが不足すると体蛋白の異化が進んで尿素窒素が増える。エネルギーはむしろ十分に(30〜35kcal/kg/日)確保する必要がある。

【誤答選択肢の解説】
A「リン」: リンは高リン血症と血管石灰化を防ぐため制限する。
B「食塩」: 食塩は3g以上6g/日未満に制限する。
C「蛋白質」: 蛋白質は0.6〜0.8g/kg/日に制限し、腎機能低下の進行を抑える。
D「カリウム」: カリウムは高カリウム血症による致死性不整脈を防ぐため制限する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-18', '正答は D「大腿動脈」。

動脈血ガス分析の採血には、体表から触知しやすく太い橈骨動脈が第一選択だが、選択肢の中では大腿動脈が最も適する。鼠径靱帯直下で拍動を触知でき、圧迫止血も確実に行える。

【誤答選択肢の解説】
A「総頸動脈」: 総頸動脈は脳への血流を担い、血腫や塞栓が脳虚血に直結するため穿刺しない。
B「鎖骨下動脈」: 鎖骨下動脈は深く、胸膜が近いため気胸の危険があり、圧迫止血もできない。
C「尺骨動脈」: 尺骨動脈は手への側副血行の主体で、損傷すると手の虚血を招くため避ける。
E「膝窩動脈」: 膝窩動脈は深部にあり触知しにくく、圧迫止血も難しい。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B018（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-2', '正答は E「個人の経験に依存した判断」。

EBMは、疑問の定式化、情報の収集、批判的吟味、患者への適用、そして振り返りという5段階で進める。得られた根拠と患者の価値観、臨床医の技能を統合するもので、個人の経験だけに頼る判断はこれと対極にある。

【誤答選択肢の解説】
A「患者への適用」: 得られた根拠を目の前の患者に当てはめられるかを検討する段階が含まれる。
B「文献情報の収集」: 定式化した疑問に答える文献を効率よく集める段階が含まれる。
C「文献の批判的吟味」: 研究デザインや結果の妥当性を吟味する段階が含まれる。
D「患者の問題の定式化」: 患者・介入・比較・結果の枠組みで疑問を定式化する段階が出発点になる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B002（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-20', '正答は C「20」。

初産婦では妊娠20週前後、経産婦では18週前後に胎動を自覚し始める。胎動は妊娠週数の推定と胎児の健康状態を知る手がかりになる。

【誤答選択肢の解説】
A「4」: 妊娠4週では胎芽もごく小さく、胎動を感じることはない。
B「12」: 妊娠12週では胎児は動いているが、母体が感じ取れるほどではない。
D「28」: 妊娠28週にはすでに明瞭な胎動を自覚している。
E「36」: 妊娠36週では胎動を感じ始める時期をはるかに過ぎている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B020（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-21', '正答は E「卵巣」。

エストラジオールが低いのにFSHが高いのは、卵巣からのフィードバックが働かず下垂体が刺激され続けている状態で、原因は卵巣にある(高ゴナドトロピン性性腺機能低下症)。早発卵巣不全やTurner症候群でみられる。

【誤答選択肢の解説】
A「視床」: 視床は感覚の中継核で、性腺の調節には関与しない。
B「視床下部」: 視床下部性ならGnRHが出ずFSHも低値となる。
C「下垂体」: 下垂体性でもFSHは低値となる。
D「副腎」: 副腎性の無月経では男性化徴候を伴い、FSHがここまで上昇しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B021（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-22', '正答は A「患者の職場からの照会への回答」。

職場からの照会に答えることは、診療や公益上の例外にあたらない第三者提供であり、本人の同意が要る。同意なく答えれば守秘義務違反となる。

【誤答選択肢の解説】
B「調剤薬局からの疑義照会への回答」: 疑義照会への回答は適切な調剤のために必要で、黙示の同意で足りる。
C「健康保険の審査支払機関からの照会への回答」: 審査支払機関への情報提供は法令に基づくもので、同意は要らない。
D「市役所からの生活保護受給者に係る病状調査への回答」: 生活保護法に基づく病状調査への回答も法令に基づくものである。
E「医療事故発生時の医療事故調査・支援センターへの報告」: 医療事故調査・支援センターへの報告は医療法に基づく義務である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B022（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-23', '正答は B「脈拍 — 52/分」。

乳児の心拍数は120〜140/分が正常で、52/分は明らかな徐脈である。乳児の徐脈は低酸素の結果として現れることが多く、心停止に至る前段階として直ちに換気と酸素化を立て直す必要がある。

【誤答選択肢の解説】
A「体温 — 38.0°C」: 38.0°Cの発熱は原因の検索を要するが、直ちに処置を要する所見ではない。
C「血圧 — 76/52 mmHg」: 血圧76/52mmHgは乳児として保たれている。
D「呼吸数 — 36/分」: 呼吸数36/分は乳児の正常範囲内である。
E「SpO2 — 96%(room air)」: SpO2 96%は正常である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B023（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-24', '正答は B「角膜」。

角膜は血流を必要としない組織で、心臓が停止した後でも一定時間内であれば提供できる。腎臓と膵臓も心停止後の提供が可能である。

【誤答選択肢の解説】
A「肺」: 肺は脳死下でなければ提供できない。
C「肝臓」: 肝臓も脳死下での提供が原則である。
D「小腸」: 小腸も脳死下での提供に限られる。
E「心臓」: 心臓は脳死下でしか提供できない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-25', '正答は B「法の遵守」。

実際に行っていない診療の報酬を請求することは詐欺にあたり、健康保険法にも反する不正請求である。医師の職業倫理の基本である法の遵守に反したことが処分の理由となる。

【誤答選択肢の解説】
A「情報開示」: 情報を開示しなかったことが問題なのではない。
C「労働者保護」: 従業員の労働条件が問われた事案ではない。
D「経営の健全性」: 経営の健全性そのものが処分の対象になるわけではない。
E「情報セキュリティ」: 個人情報の管理が問われた事案ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B025（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-26', '正答は A「応援を呼ぶ。」。

反応がない人を見つけたら、まず大声で応援を呼び、救急コールと除細動器の手配を依頼する。一人で対応しようとすると蘇生の開始も遅れるため、人と資機材を集めることが最初の行動になる。

【誤答選択肢の解説】
B「頸椎を固定する。」: 頸椎の保護は高所からの転落など受傷機転が疑われる場合に考える。まず応援である。
C「胸骨圧迫を開始する。」: 胸骨圧迫は呼吸と反応を確かめた後に始める。
D「呼吸の有無を確認する。」: 呼吸の確認は応援を呼んだ直後に行う。
E「頸動脈の拍動を確認する。」: 頸動脈の触知は医療者が呼吸の確認と同時に10秒以内に行う。順序としては応援要請が先である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B026（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-27', '正答は D「4」。

視線が合わないのは対人的な関わりの発達の遅れを示す所見で、9か月では明らかな異常である。自分の手を見つめる行動(ハンドリガード)も本来は生後4か月ごろに消える。ほかの下線部はこの月齢としてふつうにみられる。

【誤答選択肢の解説】
A「1」: つかまり立ちから独りで立てるようになるのは10〜12か月ごろである。
B「2」: 独歩は1歳前後で獲得するので、9か月でできなくてよい。
C「3」: 積み木を積めるようになるのは1歳前後である。
E「5」: 意味のある言葉が出るのは1歳前後で、喃語の段階として正常である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B027（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-28', '正答は D「鼻カニューラ2L/分」。

慢性II型呼吸不全の急性増悪では、高濃度酸素はCO2ナルコーシスを招く。SpO2 88〜92%を目標に、現在の1L/分からわずかに増やす2L/分程度から始め、動脈血ガスを再検して調節する。

【誤答選択肢の解説】
A「リザーバー付マスク15L/分」: リザーバー付マスク15L/分は過剰でCO2ナルコーシスを招く。
B「リザーバー付マスク10L/分」: 10L/分も同じ理由で不適切である。
C「鼻カニューラ5L/分」: 鼻カニューラ5L/分でも高濃度になりすぎる。
E「鼻カニューラ0.5L/分」: 0.5L/分ではSpO2 87%からさらに下がり、低酸素が是正されない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B028（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-29', '正答は E「「胎児形態異常のリスクは糖尿病ではない方とほとんど変わりません」」。

妊娠前からHbA1c 6.0%と血糖が良好に管理されていれば、胎児形態異常の頻度は糖尿病のない妊婦とほとんど変わらない。器官形成期の高血糖こそが危険因子なので、その事実を伝えて安心させる。

【誤答選択肢の解説】
A「「人工妊娠中絶を勧めます」」: 中絶を勧める根拠はまったくない。
B「「胎児の形態異常は超音波検査で分かります」」: 超音波検査で分かる形態異常には限りがあり、すべてを検出できるわけではない。
C「「インスリンから経口糖尿病薬に変更しましょう」」: 妊娠中の経口血糖降下薬は原則として用いず、インスリンを続ける。
D「「75g経口ブドウ糖負荷試験で耐糖能の再評価をしましょう」」: すでに糖尿病と診断され治療中の妊婦に糖負荷試験を行う必要はなく、高血糖を招く危険もある。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B029（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-3', '正答は A「緩和ケアは在宅医療の中で実施できる。」。

緩和ケアは病院でも在宅でも提供でき、在宅では訪問診療と訪問看護、必要に応じて医療用麻薬の持続皮下注などを組み合わせて行う。住み慣れた場所で過ごしたいという希望に応えられる。

【誤答選択肢の解説】
B「緊急時に行う在宅医療は訪問診療と呼ばれる。」: 計画的に定期訪問するのが訪問診療で、緊急時に出向くのは往診である。
C「使用した注射針は一般廃棄物として処理する。」: 使用済みの注射針は感染性産業廃棄物として処理する。
D「我が国では病院よりも在宅で死亡する場合が多い。」: 我が国の死亡場所は病院が最も多く、在宅はその半分にも満たない。
E「訪問看護を利用する場合は介護保険よりも医療保険が優先される。」: 要介護認定を受けていれば原則として介護保険が優先される。厚生労働大臣が定める疾病等や急性増悪時には医療保険となる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-31', '正答は A「血糖測定」。

インスリン治療中の糖尿病患者が突然の意識障害をきたした場合、まず低血糖を疑う。血糖測定は即座に行え、低ければブドウ糖投与で速やかに回復するため、他の検査に先立って行う。

【誤答選択肢の解説】
B「脳波検査」: 脳波検査は非けいれん性てんかん重積を疑うときに行うが、まず低血糖を除外する。
C「頭部単純CT」: 頭部CTは麻痺や外傷を疑うときに行う。麻痺は認めない。
D「脳脊髄液検査」: 髄液検査は髄膜炎を疑うときに行うが、発熱も髄膜刺激徴候もない。
E「動脈血ガス分析」: 動脈血ガス分析も鑑別に有用だが、最も簡便で治療に直結するのは血糖測定である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B031（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-32', '正答は B「輸液の減量」。

終末期に近づくと体液を保持できず、輸液を続けると胸水・腹水・浮腫・気道分泌の増加を招いて苦痛が増す。呼吸音の減弱と喀痰の増加、著明な浮腫が出ており、まず輸液量を減らす。

【誤答選択肢の解説】
A「酸素投与」: SpO2 96%と酸素化は保たれており、酸素投与では気道分泌は減らない。
C「緊急血液透析」: 腎機能の悪化を示す所見はなく、本人の希望する在宅療養とも相容れない。
D「薬物による抗癌治療」: 本人が選択しなかった治療であり、この全身状態でも適応がない。
E「下大静脈フィルター留置術」: 肺血栓塞栓症を疑う所見はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B032（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-33', '正答は E「労働者災害補償保険の給付対象となる。」。

業務中に生じた負傷は、本人の不注意によるものであっても業務災害として労働者災害補償保険の給付対象となる。事業主の過失の有無を問わない無過失責任の仕組みである。

【誤答選択肢の解説】
A「全額自己負担となる。」: 労災保険から療養補償給付が支給され、自己負担は生じない。
B「医療扶助の給付対象となる。」: 医療扶助は生活保護の給付で、この事案には該当しない。
C「健康保険の給付対象となる。」: 業務災害には健康保険を使えない。
D「後期高齢者医療制度の給付対象となる。」: 後期高齢者医療制度も業務災害には適用されない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B033（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-34', '正答は E「患者中心性」。

専門用語が多く理解できなかったこと、心理状態への配慮を欠いたこと、仕事の心配という生活上の問題に応じてもらえなかったこと、いずれも患者の価値観や状況に沿った医療という患者中心性の欠如を示す。

【誤答選択肢の解説】
A「安全性」: 誤投薬や合併症など安全に関わる問題は起きていない。
B「公平性」: 受けられる医療に不公平があったという記載はない。
C「適時性」: 受診後すぐに入院と治療が行われており、適時性は保たれている。
D「有効性」: 適切な診断と治療により回復しており、有効性は保たれている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B034（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-36', '正答は B「口腔ケアの実施を提案する。」。

口腔内の衛生状態が不良で乾燥しており、これが食欲低下と誤嚥性肺炎の一因になっている。口腔ケアは食べる機能を支える基本で、栄養サポートチームの介入として適切である。

【誤答選択肢の解説】
A「胃瘻造設を提案する。」: 終末期に近い患者に胃瘻を造設しても予後や生活の質の改善は期待しにくく、まず提案する内容ではない。
C「緩和ケアチームとは独立して活動する。」: 緩和ケアチームと目標を共有して連携する必要がある。
D「体重が4kg以上減少してから介入する。」: 体重減少を待つのではなく、低栄養の兆しを捉えて早期に介入する。
E「栄養療法の実施にあたり主治医の許諾は不要である。」: 栄養療法の実施には主治医の同意と指示が必要である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B036（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-37', '正答は C「腹部単純CT」。

突然の側腹部痛、肋骨脊柱角の叩打痛、血尿、水腎症から尿管結石である。腹部単純エックス線写真に写らない尿酸結石でも単純CTなら描出でき、大きさと位置、水腎症の程度まで一度に評価できる。

【誤答選択肢の解説】
A「FDG-PET」: FDG-PETは悪性腫瘍の検索に用いる。
B「膀胱鏡検査」: 膀胱鏡は膀胱内の病変を観察する検査で、尿管結石の診断には向かない。
D「膀胱造影検査」: 膀胱造影は膀胱損傷や膀胱尿管逆流の評価に用いる。
E「腎シンチグラフィ」: 腎シンチグラフィは分腎機能の評価に用いる検査で、急性期の診断には使わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B037（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-38', '正答は E「5」。

スリッパは脱げやすく踵が固定されないため、高齢者の転倒の危険因子になる。踵を覆い滑りにくい靴に替えることが転倒予防の基本である。

【誤答選択肢の解説】
A「1」: 食事の再開は栄養状態を保ち、筋力の維持につながる。
B「2」: 点滴ラインの終了は行動を妨げるものが減るので、転倒の危険はむしろ下がる。
C「3」: 離床センサーは早期に気づくための対策である。
D「4」: 看護師の見守りも転倒を防ぐための対策である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B038（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-39', '正答は E「多職種の関係者で対応を検討する。」。

外出には症状の管理、酸素の携行、移動手段の確保、学校との調整など多くの準備が要る。医師、看護師、薬剤師、社会福祉士など多職種で検討し、本人の希望を実現する道を探る。

【誤答選択肢の解説】
A「家族の意向の確認は不要である。」: 付き添いや急変時の対応が必要になるため、家族の意向の確認は欠かせない。
B「酸素投与中は出席を見合わせる。」: 携帯用酸素ボンベを用いれば酸素投与下でも外出できる。
C「移動に消防署の救急車を依頼する。」: 救急車は緊急時の搬送手段であり、予定された外出には介護タクシーなどを利用する。
D「学校への連絡は方針確定後に行う。」: 座席や休憩場所の確保などのため、学校とは早い段階から相談する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B039（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-4', '正答は B「聴力低下は高音から始まる。」。

老人性難聴は蝸牛基底回転の有毛細胞から障害されるため、高音域から左右対称性に聴力が低下する。語音明瞭度も落ちるので、大きな声より、ゆっくりはっきり話すことが有効である。

【誤答選択肢の解説】
A「耳鳴は伴わないことが多い。」: 耳鳴を伴うことが多い。
C「伝音難聴を示すことが多い。」: 内耳の障害による感音難聴である。
D「補聴器の使用は極力避ける。」: 補聴器の装用は社会的孤立や認知機能低下を防ぐうえで積極的に勧められる。
E「純音聴力検査で左右非対称性の難聴を示す。」: 両側対称性に進行するのが特徴で、左右差が目立つ場合は聴神経腫瘍などを疑う。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-40', '正答は A「喘鳴」。

縦隔腫瘤が気管を圧排して内腔が狭窄しており、中枢気道の狭窄音が胸骨付近で聴かれる。吸気・呼気を通じた高調な連続性ラ音(喘鳴)で、頸部から胸骨上で最も強く聴取される。

【誤答選択肢の解説】
B「水泡音」: 水泡音(coarse crackles)は気道内の分泌物によるもので、肺炎や気管支拡張症でみられる。
C「捻髪音」: 捻髪音(fine crackles)は虚脱した末梢気道が吸気終末に開く音で、間質性肺炎でみられる。肺野に異常はない。
D「胸膜摩擦音」: 胸膜摩擦音は胸膜炎で炎症を起こした胸膜がこすれる音である。
E「呼吸音減弱」: 呼吸音の減弱は気胸や胸水、無気肺でみられる。肺野に異常はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B040（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-5', '正答は E「地域包括支援センター」。

地域包括支援センターは市町村が設置する。介護予防ケアマネジメント、総合相談支援、権利擁護、包括的・継続的ケアマネジメント支援を担い、保健師・社会福祉士・主任介護支援専門員が配置される。

【誤答選択肢の解説】
A「児童相談所」: 児童相談所は都道府県と指定都市に設置が義務づけられている。
B「医療安全支援センター」: 医療安全支援センターは都道府県、保健所設置市および特別区が設置する。
C「精神保健福祉センター」: 精神保健福祉センターは都道府県と指定都市が設置する。
D「地域医療支援センター」: 地域医療支援センターは都道府県が設置し、医師の確保と地域偏在の是正を担う。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-6', '正答は E「立方体の模写」。

改訂長谷川式簡易知能評価スケールは9項目からなり、年齢、見当識、3単語の記銘と遅延再生、計算(100から7の連続減算)、数字の逆唱、物品記銘、語想起で構成される。立方体の模写は含まれず、これはMMSEの項目である。

【誤答選択肢の解説】
A「計算」: 100から順に7を引く計算の項目がある。
B「見当識」: 日時と場所の見当識を問う項目がある。
C「物品記銘」: 5つの物品を見せた後に隠して答えさせる項目がある。
D「数字の逆唱」: 3桁と4桁の数字の逆唱を求める項目がある。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-7', '正答は E「「心身ともにおつらいですね」」。

共感とは相手の感情を理解し、それを言葉にして返すことである。つらさを言い当てて受け止める言葉が最も共感的で、患者は理解されたと感じられる。

【誤答選択肢の解説】
A「「夜は眠れていますか」」: 情報を集める質問で、感情に触れていない。
B「「元気を出してくださいよ」」: 励ましは感情の否定になりやすく、共感とは異なる。
C「「痛み止めを処方しますね」」: 対処の提案であって、気持ちを受け止めてはいない。
D「「私がなんとかしましょう」」: 医師の意気込みを伝えるもので、患者の感情に向き合っていない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-B-8', '正答は E「尿道留置カテーテルの集尿袋内の尿」。

集尿袋内の尿は時間が経って細菌が増殖しており、また外部から汚染されるため培養検体に適さない。カテーテル留置中はカテーテルの採尿ポートを消毒して注射器で新鮮な尿を採る。

【誤答選択肢の解説】
A「中間尿」: 中間尿は外尿道口の常在菌の混入を減らせるので、標準的な検体である。
B「尿道分泌物」: 尿道分泌物は尿道炎の起因菌を調べる適切な検体である。
C「導尿で採取した尿」: 導尿で採取した尿は外陰部の常在菌の混入が少ない。
D「腎瘻造設時に採取した尿」: 腎瘻造設時に採取した尿は無菌操作で得られ、上部尿路の情報が得られる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 B008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-1', '正答は B「救命救急センター数の増加」。

健康日本21(第3次)は、健康寿命の延伸と健康格差の縮小を最終目標に、生活習慣の改善、社会環境の質の向上、ライフコースアプローチを柱とする。救命救急センターの整備は医療提供体制の課題で、医療計画が扱う。

【誤答選択肢の解説】
A「健康経営の推進」: 健康経営に取り組む企業の増加は、社会環境の質の向上の目標に含まれる。
C「メンタルヘルス対策に取り組む事業場の増加」: メンタルヘルス対策に取り組む事業場の増加も目標に含まれる。
D「利用者に応じた食事提供をしてくれる特定給食施設の増加」: 利用者に応じた食事提供をする特定給食施設の増加も目標に含まれる。
E「「居心地がよく歩きたくなる」まちなかづくりに取り組む市町村数の増加」: 「居心地がよく歩きたくなる」まちなかづくりに取り組む市町村の増加も目標に含まれる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C001（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-10', '正答は D「自己免疫性溶血性貧血」。

尿潜血反応はヘモグロビンとミオグロビンのペルオキシダーゼ活性を捉えるため、溶血で遊離したヘモグロビンが尿中に出れば、赤血球がなくても陽性となる。潜血陽性で沈渣に赤血球を認めないのがヘモグロビン尿の特徴である。

【誤答選択肢の解説】
A「腎梗塞」: 腎梗塞では梗塞部からの出血で沈渣に赤血球を認める。
B「膀胱癌」: 膀胱癌では腫瘍からの出血により沈渣に赤血球を多数認める。
C「尿路結石」: 尿路結石でも粘膜損傷により沈渣に赤血球を認める。
E「膜性増殖性糸球体腎炎」: 膜性増殖性糸球体腎炎では変形赤血球や赤血球円柱を認める。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C010（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-11', '正答は E「滅裂思考」。

思路(思考過程)の障害は考えのつながり方の異常で、滅裂思考は文と文のつながりが失われて理解できなくなるものである。観念奔逸や思考制止も思路の障害にあたる。

【誤答選択肢の解説】
A「強迫観念」: 強迫観念は思考の内容にとらわれる障害で、思考内容の異常に分類される。
B「思考吹入」: 思考吹入は自我障害にあたる。
C「心気妄想」: 心気妄想は思考内容の障害(妄想)である。
D「広場恐怖」: 広場恐怖は不安症状で、思考の障害ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C011（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-12', '正答は E「ガラガラをつかむ。」。

微細運動は手指を使う細かい動きを指す。ガラガラをつかむのは把握の発達をみる項目で、生後3〜4か月ごろに獲得する微細運動の指標である。

【誤答選択肢の解説】
A「首がすわる。」: 首がすわるのは体幹を支える粗大運動である。
B「手をみつめる。」: 手をみつめる行動(ハンドリガード)は視覚と身体の認識に関わるもので、運動そのものではない。
C「寝返りをする。」: 寝返りは全身を使う粗大運動である。
D「バイバイをする。」: バイバイは模倣による社会性の発達を示す項目である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C012（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-13', '正答は B「訪問診療」。

訪問診療は医療保険で提供される。介護保険の対象になるのは訪問介護や福祉用具貸与、住宅改修など生活を支えるサービスである。

【誤答選択肢の解説】
A「住宅改修」: 手すりの設置や段差の解消といった住宅改修は介護保険の給付である。
C「介護医療院」: 介護医療院は介護保険の施設サービスである。
D「福祉用具貸与」: 福祉用具貸与も介護保険の給付である。
E「ショートステイ」: ショートステイ(短期入所生活介護)も介護保険の給付である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C013（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-14', '正答は E「都道府県知事」。

感染症法に基づく就業制限は都道府県知事が通知する。一類・二類・三類感染症および新型インフルエンザ等感染症の患者について、飲食物に直接接触する業務などへの従事を制限する。

【誤答選択肢の解説】
A「産業医」: 産業医は事業者に意見を述べる立場で、法に基づく就業制限の通知権限をもたない。
B「事業者」: 事業者は通知を受けて対応する側である。
C「主治医」: 主治医は診断して届け出るが、就業制限そのものは通知できない。
D「感染症専門医」: 専門医であっても通知の権限はない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C014（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-16', '正答は A「沸点が高い。」。

生物濃縮を受けやすいのは、脂溶性が高く化学的に安定で分解されにくい物質である。沸点が高いことは揮発しにくく環境中に残りやすいことを意味し、食物連鎖を通じて濃縮される。PCBや有機水銀、DDTが代表である。

【誤答選択肢の解説】
B「水溶性である。」: 水溶性の物質は尿中に排泄されやすく、体内に蓄積しない。
C「急性毒性が強い。」: 急性毒性の強さと蓄積のしやすさは別の性質である。
D「化学的に不安定である。」: 化学的に不安定なら環境中で分解されて濃縮されない。
E「生体内で代謝されやすい。」: 生体内で代謝されやすい物質は排泄され、蓄積しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C016（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-17', '正答は D「エタノール」。

エタノールは分子が小さく脂溶性もあるため、胃粘膜から直接吸収される。約20%が胃で、残りが小腸で吸収されるため、空腹時には吸収が速く血中濃度が急に上がる。

【誤答選択肢の解説】
A「鉄」: 鉄は十二指腸から空腸上部で吸収される。
B「葉酸」: 葉酸も空腸で吸収される。
C「脂肪酸」: 脂肪酸は胆汁酸ミセルとなって空腸・回腸で吸収される。
E「グルコース」: グルコースはSGLT1により小腸で吸収される。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C017（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-19', '正答は D「低出生体重児の届出」。

母子保健法は、体重2,500g未満の低出生体重児が出生したときの届出のほか、母子健康手帳の交付、妊産婦・乳幼児の健康診査、養育医療、新生児訪問指導などを定めている。

【誤答選択肢の解説】
A「定期予防接種」: 定期予防接種は予防接種法に規定されている。
B「児童虐待に係る通告」: 児童虐待に係る通告は児童虐待防止法と児童福祉法に規定されている。
C「人工妊娠中絶の要件」: 人工妊娠中絶の要件は母体保護法に規定されている。
E「就学時健康診断の実施」: 就学時健康診断は学校保健安全法に規定されている。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C019（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-20', '正答は C「すくみ足」。

すくみ足は歩き出しや方向転換で足が床に張りついて出なくなる症状で、床の線やレーザーポインタ、号令といった外的な合図(キュー)があると乗り越えられる。等間隔の線をまたぐ訓練はこれを利用したものである。

【誤答選択肢の解説】
A「加速歩行」: 加速歩行は歩き出すと歩幅が狭く速くなる症状で、線をまたいでも制御できない。
B「姿勢異常」: 姿勢異常には体幹のストレッチや姿勢を意識させる訓練を行う。
D「突進現象」: 突進現象は重心が前に移って止まれなくなるもので、方向転換や停止の訓練で対応する。
E「静止時振戦」: 静止時振戦は薬物療法や脳深部刺激療法の対象で、歩行訓練では改善しない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C020（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-21', '正答は E「樹状細胞」。

樹状細胞は取り込んだ抗原をMHCクラスIIに載せてナイーブT細胞に提示できる、最も強力な抗原提示細胞である。マクロファージとB細胞も抗原提示能をもつ。

【誤答選択肢の解説】
A「T細胞」: T細胞は提示された抗原を認識する側で、提示はしない。
B「血小板」: 血小板は止血に働き、抗原提示能はない。
C「好酸球」: 好酸球は寄生虫感染やアレルギーに関与するが、抗原提示細胞ではない。
D「好中球」: 好中球は貪食と殺菌を担うが、ナイーブT細胞への抗原提示は行わない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C021（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-23', '正答は D「複視」。

Bell麻痺は顔面神経の障害で、外眼筋を支配する動眼・滑車・外転神経は侵されないため複視は生じない。複視があれば脳幹病変など別の原因を考える。

【誤答選択肢の解説】
A「口角の下垂」: 口輪筋の麻痺により口角が下がる。
B「前頭筋の麻痺」: 末梢性の麻痺なので前頭筋も麻痺し、額のしわ寄せができなくなる。
C「聴覚過敏」: アブミ骨筋の麻痺により音が響いて聞こえる聴覚過敏を生じる。
E「味覚障害」: 鼓索神経が障害されると舌前2/3の味覚が低下する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C023（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-24', '正答は E「ユニバーサル・ヘルス・カバレッジ〈UHC〉の達成」。

ゴール3のターゲットには、ユニバーサル・ヘルス・カバレッジの達成、すなわちすべての人が経済的な困難なく必要な保健医療サービスを受けられる状態の実現が明記されている。

【誤答選択肢の解説】
A「水・衛生へのアクセス」: 水と衛生へのアクセスはゴール6の内容である。
B「国内および国家間の不平等の是正」: 国内および国家間の不平等の是正はゴール10である。
C「社会的な健康規定要因への取り組み」: 健康の社会的決定要因への取り組みは重要な考え方だが、ゴール3の個別ターゲットとしては掲げられていない。
D「グローバル・パートナーシップの活性化」: グローバル・パートナーシップの活性化はゴール17である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C024（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-26', '正答は E「抗アミノアシルtRNA合成酵素抗体〈抗ARS抗体〉 — 間質性肺炎」。

抗ARS抗体は多発性筋炎・皮膚筋炎に伴い、間質性肺炎、機械工の手、多関節炎、Raynaud現象を特徴とする抗合成酵素症候群を形成する。間質性肺炎の合併率が高く、予後を左右する。

【誤答選択肢の解説】
A「抗MDA5抗体 — 間質性腎炎」: 抗MDA5抗体は急速進行性の間質性肺炎と関連する。間質性腎炎ではない。
B「抗Mi-2抗体 — 蝶形紅斑」: 抗Mi-2抗体は皮膚症状の目立つ古典的な皮膚筋炎に伴う。蝶形紅斑は全身性エリテマトーデスの所見である。
C「抗SS-A抗体 — 皮膚硬化」: 抗SS-A抗体はSjögren症候群に伴い、乾燥症状や新生児ループスと関連する。皮膚硬化ではない。
D「抗TIF1-γ抗体 — 硬化性胆管炎」: 抗TIF1-γ抗体は悪性腫瘍を合併する皮膚筋炎と関連する。硬化性胆管炎ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C026（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-27', '正答は A「血友病」。

薬害エイズ事件では、血友病患者の凝固因子補充に用いられた非加熱の濃縮血液製剤にHIVが混入しており、多数の患者が感染した。加熱製剤への切り替えの遅れが被害を広げた。

【誤答選択肢の解説】
B「多発性骨髄腫」: 多発性骨髄腫の治療に濃縮血液製剤は用いない。
C「無菌性髄膜炎」: 無菌性髄膜炎は対症療法で治療する。
D「成人T細胞白血病」: 成人T細胞白血病はHTLV-1による疾患で、血液製剤による医原性免疫不全とは別である。
E「Creutzfeldt-Jakob病」: Creutzfeldt-Jakob病はヒト乾燥硬膜の移植による医原性感染が問題となった、別の薬害である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C027（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-28', '正答は E「血清クレアチニン値」。

妊娠中は腎血漿流量と糸球体濾過量が増えるため、血清クレアチニン値は低下する。非妊娠時の基準値を当てはめると腎機能障害を見落とすので注意する。

【誤答選択肢の解説】
A「白血球数」: 白血球数は妊娠中に増加する。
B「一回換気量」: プロゲステロンの作用で一回換気量は増加する。
C「大腿静脈圧」: 増大した子宮が下大静脈を圧迫するため大腿静脈圧は上昇する。
D「インスリン抵抗性」: hPLなどの作用でインスリン抵抗性は増大する。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C028（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-29', '正答は E「偽性副甲状腺機能低下症」。

偽性副甲状腺機能低下症は、副甲状腺ホルモンの受容体以降のシグナル伝達(Gs蛋白)の障害により標的臓器が反応できない病態である。PTHはむしろ高値なのに低カルシウム血症と高リン血症を示す。

【誤答選択肢の解説】
A「骨軟化症」: 骨軟化症はビタミンD欠乏やリン喪失によるもので、受容体異常ではない。
B「Basedow病」: Basedow病はTSH受容体に対する刺激性の自己抗体によるもので、受容体そのものの異常ではない。
C「慢性甲状腺炎」: 慢性甲状腺炎は甲状腺への自己免疫性の破壊による。
D「副甲状腺機能亢進症」: 副甲状腺機能亢進症はホルモンの過剰分泌によるもので、受容体は正常である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C029（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-3', '正答は E「精神医療審査会の事務」。

精神保健福祉センターは、精神医療審査会の事務を担うほか、精神保健に関する知識の普及、相談指導、自立支援医療と精神障害者保健福祉手帳の判定を行う。

【誤答選択肢の解説】
A「要介護認定」: 要介護認定は市町村が介護認定審査会の判定に基づいて行う。
B「障害年金の認定」: 障害年金の認定は日本年金機構が行う。
C「麻薬の取り締まり」: 麻薬の取り締まりは麻薬取締官・麻薬取締員が担う。
D「心神喪失者の精神鑑定」: 心神喪失者の精神鑑定は裁判所が選任した鑑定医が行う。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C003（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-30', '正答は D「過敏性腸症候群」。

過敏性腸症候群は器質的な病変を伴わない機能性疾患で、下血をきたさない。血便があれば診断を見直し、器質的疾患を検索する必要がある。

【誤答選択肢の解説】
A「大腸癌」: 大腸癌は腫瘍からの出血により下血をきたす。
B「潰瘍性大腸炎」: 潰瘍性大腸炎では粘血便が特徴的である。
C「虚血性大腸炎」: 虚血性大腸炎では突然の腹痛に続いて鮮血便をみる。
E「非閉塞性腸管虚血症〈NOMI〉」: 非閉塞性腸管虚血症でも腸管壊死により下血をきたす。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C030（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-31', '正答は E「ベンゾジアゼピン系薬」。

ベンゾジアゼピン系薬は反復使用で耐性と身体依存を形成し、急に中止すると不安、不眠、けいれんなどの離脱症状が現れる。漸減して中止する必要がある。

【誤答選択肢の解説】
A「LSD」: LSDは幻覚剤で、精神依存はあるが身体依存は形成しにくい。
B「大麻」: 大麻も精神依存が主で、身体依存は弱い。
C「コカイン」: コカインは強い精神依存を生じるが、身体依存は形成しにくい。
D「アンフェタミン類」: アンフェタミン類も精神依存が中心で、身体依存は弱い。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C031（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-37', '正答は D「4」。

ノロウイルスはエンベロープをもたないためアルコールが効きにくい。吐物で汚染された面は次亜塩素酸ナトリウムで消毒する。

【誤答選択肢の解説】
A「1」: 吐物を広げないようペーパータオルで静かに拭き取るのは適切である。
B「2」: 使用したペーパータオルをビニール袋に密封するのは適切である。
C「3」: 感染性の吐物を医療廃棄物として処理するのは適切である。
E「5」: アルコールが効きにくいため、石鹸と流水による手洗いで物理的に洗い流すのが適切である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C037（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-38', '正答は E「子宮収縮薬投与」。

分娩第2期が3時間続き、陣痛周期5〜6分・持続20秒と微弱陣痛になっている。児頭下降度SP±0cmで下降が進まず、胎児心拍数は良好なので、まず子宮収縮薬で陣痛を補強する。

【誤答選択肢の解説】
A「吸引分娩」: 吸引分娩は児頭下降度がSP+2cm以上に達してから行う。
B「経過観察」: 分娩第2期が3時間に及んでおり、経過観察は適切でない。
C「帝王切開」: 胎児は良好で、児頭も下降しつつある。まず陣痛の補強を試みる。
D「胎児圧出法」: 胎児圧出法は子宮底を圧迫する手技で、単独では行わず、また子宮破裂の危険がある。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C038（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-39', '正答は A「老衰」。

老衰は、高齢者で他に記載すべき死因がない自然死に用いる。長期の経過で徐々に衰弱し、明らかな病態を特定できない本例は老衰と記載してよい。

【誤答選択肢の解説】
B「心不全」: 心不全は死亡に至る過程を示す状態で、直接死因として単独で記載しない。
C「脳梗塞」: 脳梗塞は5年前の発症で、今回の死亡の直接の原因とは考えにくい。
D「呼吸不全」: 呼吸不全も心不全と同様、死亡の一過程を示す表現である。
E「不詳の死」: 経過と死体所見から老衰と判断できており、不詳とする理由がない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C039（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-4', '正答は D「調査対象者数」。

偶然誤差は標本の偶然のばらつきによる誤差で、対象者数を増やせば小さくなる。系統誤差(バイアス)と違い、標本サイズによって左右されるのが特徴である。

【誤答選択肢の解説】
A「喫煙の定義」: 喫煙の定義が曖昧なら測定バイアスとなり、系統誤差である。
B「記名の有無」: 記名式では正直に答えにくく、これも測定バイアス(系統誤差)にあたる。
C「質問の妥当性」: 質問の妥当性が低ければ測りたいものが測れず、系統誤差となる。
E「無作為抽出の有無」: 無作為抽出を怠れば選択バイアスが生じ、これも系統誤差である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C004（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-43', '正答は B「体重の減量」。

身長160cm、体重90kgでBMI35.2の高度肥満である。肥満は排卵障害の原因となり、妊娠高血圧症候群や妊娠糖尿病、巨大児の危険も高める。妊娠前の減量が最も有効な助言になる。

【誤答選択肢の解説】
A「休職」: 小学校教師という職業に妊娠を妨げる要因はなく、休職を勧める根拠はない。
C「妊娠の断念」: 血圧は良好に管理されており、妊娠を断念する理由はない。
D「降圧薬の中止」: 降圧薬は妊娠中に使える薬剤へ変更するのであって、中止するものではない。
E「体外授精の開始」: まだ避妊をやめて自然妊娠を試みる段階で、いきなり体外受精を始めるものではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C043（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-44', '正答は B「妊娠反応検査」。

生殖年齢の女性の不正性器出血では、まず妊娠の有無を確かめる。異所性妊娠や流産を見落とせば命に関わるため、月経不順であっても妊娠反応検査が最初の一歩になる。

【誤答選択肢の解説】
A「腹部単純CT」: 被曝を伴い、妊娠の可能性を否定する前に行うべきではない。
C「経腟超音波検査」: 経腟超音波検査は次に行う重要な検査だが、妊娠反応の結果があってこそ所見を解釈できる。
D「子宮内膜組織診」: 子宮内膜組織診は子宮体癌を疑うときに行う。妊娠の可能性を否定してからである。
E「プロゲステロン投与」: プロゲステロン投与は原因を確かめずに行うもので、妊娠中であれば診断を遅らせる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C044（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-45', '正答は A「入院させる。」。

予防接種歴も乳児健診の記録もなく、栄養は明らかに不足し(1日400mLのミルクのみ、体重6,500g)、おむつは長時間交換されず衣類も汚れている。ネグレクトが強く疑われるので、まず入院させて身体の評価と保護を同時に行う。

【誤答選択肢の解説】
B「警察へ通報する。」: 通告先は児童相談所または市町村で、警察ではない。まず児の安全を確保する。
C「自宅で経過観察させる。」: 自宅に帰せば養育環境が変わらず、状態が悪化する。
D「家族に育児への協力を促す。」: 家族への働きかけだけでは児の安全を確保できない。
E「明日かかりつけ医を受診させる。」: 5日続く発熱とけいれんの既往があり、翌日まで待てる状態ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C045（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-46', '正答は A「Rorschachテスト」。

自傷と衝動的な過量服薬を繰り返し、対人関係が不安定という像からパーソナリティ障害が疑われる。Rorschachテストは投影法の人格検査で、意識されにくい内的な体験様式やパーソナリティ構造の理解に役立つ。

【誤答選択肢の解説】
B「前頭葉機能検査〈FAB〉」: 前頭葉機能検査は前頭葉障害の評価に用いる。
C「Wechsler成人知能検査」: Wechsler成人知能検査は知的機能の評価に用いる。大学院を修了しており知的な問題は示唆されない。
D「リバーミード行動記憶検査」: リバーミード行動記憶検査は記憶障害の評価に用いる。
E「Mini-Mental State Examination〈MMSE〉」: MMSEは認知機能のスクリーニング検査である。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C046（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-5', '正答は B「経済的虐待」。

児童虐待防止法が定める児童虐待は、身体的虐待・性的虐待・ネグレクト・心理的虐待の4類型である。経済的虐待は高齢者虐待防止法や障害者虐待防止法に定めがあるが、児童虐待の類型には含まれない。

【誤答選択肢の解説】
A「性的虐待」: 児童にわいせつな行為をすること、させることは性的虐待にあたる。
C「身体的虐待」: 外傷が生じる、または生じるおそれのある暴行は身体的虐待にあたる。
D「心理的虐待」: 著しい暴言や拒絶的な対応、面前でのドメスティック・バイオレンスは心理的虐待にあたる。
E「ネグレクト」: 適切な監護を著しく怠ることはネグレクトにあたる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C005（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-6', '正答は D「家事動作訓練が含まれる。」。

介護保険の機能訓練は生活機能の維持・向上を目的とし、調理や掃除、洗濯といった家事動作の訓練も含まれる。生活の場に即した訓練であることが医療機関のリハビリテーションとの違いである。

【誤答選択肢の解説】
A「介護福祉士が実施する。」: 機能訓練指導員になれるのは理学療法士、作業療法士、言語聴覚士、看護職員などで、介護福祉士は含まれない。
B「利用者は減少している。」: 高齢化に伴い利用者は増加している。
C「医師の指示が必要である。」: 介護保険の機能訓練はケアプランに基づいて行うもので、医師の指示は要件ではない。
E「特定機能病院で実施される。」: 特定機能病院は高度医療を担う施設で、介護保険の機能訓練の実施場所ではない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C006（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-7', '正答は E「所得によって支払う保険料が異なる。」。

介護保険料は所得段階に応じて設定され、所得が高いほど多く負担する。第1号被保険者の保険料は市町村ごとに定められ、所得段階も市町村が決める。

【誤答選択肢の解説】
A「保険料は79歳まで支払う。」: 40歳以上であれば生涯にわたって納付する。上限年齢はない。
B「保険料は全市町村で同じである。」: 第1号被保険者の保険料は市町村ごとに異なる。
C「保険料は65歳から納付義務がある。」: 40歳から第2号被保険者として納付義務が生じる。
D「サービス利用で自己負担は生じない。」: サービス利用時には所得に応じて1〜3割の自己負担がある。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C007（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-8', '正答は D「骨盤」。

初期診療では胸部と骨盤のエックス線写真を撮る。骨盤骨折は後腹膜へ大量に出血してショックの原因となり、骨盤輪の不安定性が分かれば固定と血管内治療の判断につながるためである。

【誤答選択肢の解説】
A「頭部」: 頭部は出血源としての寄与が小さく、評価はCTで行う。
B「頸椎」: 頸椎は損傷の有無を評価するが、ショックの原因検索としての優先度は低い。
C「腹部」: 腹腔内出血の評価はエックス線写真では困難で、迅速簡易超音波検査(FAST)を用いる。
E「大腿骨」: 大腿骨骨折も出血源になるが、初期の定型的な撮影部位には含まれない。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C008（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形'),
    ('119-C-9', '正答は C「診療録」。

医師法第24条は、診療録を診療完結の日から5年間保存することを定めている。保存義務を負うのは病院・診療所の管理者、または診療した医師である。

【誤答選択肢の解説】
A「紹介状」: 紹介状の保存期間は医師法に定めがない。
B「処方箋」: 処方箋は療養担当規則により3年間の保存とされ、保存するのは調剤した薬局である。
D「看護記録」: 看護記録は医療法施行規則により2年間の保存とされる。
E「エックス線写真」: エックス線写真も医療法施行規則により2年間の保存とされる。

※この解説はアプリ編集部が作成したものです。厚生労働省が公表する過去問には解説は含まれません。

出典：厚生労働省ホームページ 第119回医師国家試験 C009（https://www.mhlw.go.jp/seisakunitsuite/bunya/kenkou_iryou/iryou/topics/tp250428-01.html）／設問文および選択肢を本アプリの表示形式に整形')
) AS v(blueprint_code, explanation)
WHERE q.blueprint_code = v.blueprint_code
  AND q.exam_type = 'KOKUSHI';

-- 残りのプレースホルダ件数を確認する。
SELECT count(*) AS remaining_placeholders
FROM quiz_question WHERE explanation LIKE '%詳しい解説は準備中%';

COMMIT;
